// Generated from the pinned official warehouse; preserve source attribution.
export default {"GUC":"// 吉利学院(GUC) 拾光课程表适配脚本\n// YETHAN以专教学信息服务平台\n// 该教务系统带图片验证码，需用户在页面内手动登录，脚本基于已登录会话(Cookie)拉取课表\n// 桥接 API 使用 v2：window.shiguangBridge(同步) / window.shiguangBridgePromise(异步)\n\n\n//*****吐槽（>-<）*****\n// ===== YETHAN 系统特性（适配脚本为何做了这么多特判） =====\n// 1. 页面标题错乱：课表页 <title>=\"学生个人信息\"、重修页=\"选课日志\"（模板没改标题）\n// 2. 无校历/学期开始日期字段——开学日期只能从\"按周查课表\"表头偷（且表头只有\"03月02日\"无年份，年份需页头学年/最近年份推算）\n// 3. 课程数据脏：编号/课名/括号挤一行（如 \"B1001 高等数学（4）\"），全角括号混用、教师可能缺失、地点可为 NoRoom\n// 4. 课表视图分裂：全部周次视图表头无日期，仅按周(weekNo=N)视图表头带日期\n// 5. 学生年级/学历等字段经接口加密下发、无干净字段（故无法按学号可靠推算\"大几\"，只显示真实学年学期）\n// 6. 功能集中在单 Action（CourseAction?setAction=...）按字符串分发，无 REST\n// 7. 课表页\"全部周次\"下拉纯纯摆设：提交空值(weekNo=)照样只给\"当前周\"，实测单次只拿到 2 门课——\n//    只好逐周请求十几次再自己合并（详见 fetchAllWeeksTimetable 注释）\n\n\n// ==================== 常量 ====================\n\n// 课表接口地址（所有课表请求均走 POST 表单提交，复刻页面表单：\n// setAction=userCourseScheduleTable / viewType=studentCourseTableWeek / selectTableType=<学期> / queryType=student / weekNo=<周次，空=全部>）\nconst COURSE_ACTION_URL = \"https://jw.guc.edu.cn/yethan/CourseAction\";\n\n// 默认导入学期（用户在选择学期弹窗中取消时回退到本学期）\nconst SELECT_TABLE_TYPE = \"ThisTerm\";\n\n// 拉取课表请求超时时间（毫秒）\nconst FETCH_TIMEOUT_MS = 15000;\n\n// 吉利学院作息时间（第1节~第11节）\nconst TIME_SLOTS = [\n    { number: 1, startTime: \"08:20\", endTime: \"09:05\" },\n    { number: 2, startTime: \"09:10\", endTime: \"09:55\" },\n    { number: 3, startTime: \"10:10\", endTime: \"10:55\" },\n    { number: 4, startTime: \"11:00\", endTime: \"11:45\" },\n    { number: 5, startTime: \"11:50\", endTime: \"12:35\" },\n    { number: 6, startTime: \"14:20\", endTime: \"15:05\" },\n    { number: 7, startTime: \"15:10\", endTime: \"15:55\" },\n    { number: 8, startTime: \"16:10\", endTime: \"16:55\" },\n    { number: 9, startTime: \"17:00\", endTime: \"17:45\" },\n    { number: 10, startTime: \"19:00\", endTime: \"19:45\" },\n    { number: 11, startTime: \"19:50\", endTime: \"20:35\" }\n];\n\n// ==================== 工具函数 ====================\n\n/**\n * 将周次字符串展开为数字数组。\n * 支持 \"19周\" -> [19]，\"1-5,7-9,11-16周\" -> [1,2,3,4,5,7,8,9,11,12,13,14,15,16]\n */\nfunction parseWeeks(weekStr) {\n    const weeks = [];\n    if (!weekStr) return weeks;\n    // 去掉\"周\"及可能存在的(单)/(双)等标记（兼容全角/半角括号）\n    const pureWeekData = weekStr.replace(/周/g, \"\").replace(/[（(].*$/, \"\");\n    pureWeekData.split(\",\").forEach(seg => {\n        seg = seg.trim();\n        if (!seg) return;\n        if (seg.includes(\"-\")) {\n            const [s, e] = seg.split(\"-\").map(Number);\n            if (!isNaN(s) && !isNaN(e) && s >= 1 && e >= s) {\n                for (let i = s; i <= e; i++) weeks.push(i);\n            }\n        } else {\n            const w = parseInt(seg, 10);\n            if (!isNaN(w) && w >= 1) weeks.push(w);\n        }\n    });\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 解析一行课程文本，如 \"B3001 体育与健康（4）（张睿）\"（课名带版本号括号，教师为最后一个全角括号）。\n * 返回 { name, teacher }，无法解析时返回 null。\n * 兼容情况：\n *   - 未选课前课程可能无教师（如 \"B1001 高等数学\"），此时 teacher 为空串，课程保留；\n *   - 课名带版本号括号（如 \"体育与健康（4）\"）时，纯数字括号视为课名一部分，不会误认成教师。\n */\nfunction parseCourseLine(line) {\n    const text = line.trim();\n    if (!text) return null;\n    // 教师为最后一个全角括号内的内容；纯数字括号（如 （4））视为课名版本号而非教师\n    const teacherMatch = text.match(/（([^（）]+)）$/);\n    let teacher = \"\";\n    let name = text;\n    if (teacherMatch) {\n        const candidate = teacherMatch[1].trim();\n        if (!/^\\d+$/.test(candidate)) {\n            teacher = candidate;\n            name = text.substring(0, text.length - teacherMatch[0].length).trim();\n        }\n    }\n    // 去除课程编号前缀（如 B2344），仅当首词形如\"字母+数字\"时去除\n    const tokens = name.split(/\\s+/);\n    if (tokens.length > 1 && /^[A-Za-z]*\\d+$/.test(tokens[0])) {\n        tokens.shift();\n    }\n    name = tokens.join(\" \").trim();\n    if (!name) return null;\n    return { name, teacher };\n}\n\n/**\n * 节次与周次合并去重函数（官方参考实现，来自拾光课程表 wiki《课程合并与去重函数》）\n * - 节次合并：名称、教师、地点、星期、周次完全相同的连续节次（1-2 + 3-4 -> 1-4）\n * - 完全去重：删除完全重复的记录\n * - 周次合并：同节次的单双周/分段周次合并（[15] + [16] -> [15,16]）\n * - 周次排序去重：weeks 自动升序并去重\n */\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    // 1. 深拷贝并规范周次数据，过滤无效项\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n\n    // 阶段 1：合并连续节次与完全重复记录（前提：名称、教师、地点、星期、周次一致）\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n               (a.startSection || 0) - (b.startSection || 0);\n    });\n\n    const step1Merged = [];\n    let current = list[0];\n\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n\n        const isSameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n\n        if (isSameCourseAndWeeks && isContinuous) {\n            // 节次连续：延长结束节次 (如 1-2 节 + 3-4 节 -> 1-4 节)\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            // 完全重复：跳过\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    // 阶段 2：合并同节次的周次（前提：名称、教师、地点、星期、开始/结束节次一致）\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               (a.startSection || 0) - (b.startSection || 0) ||\n               (a.endSection || 0) - (b.endSection || 0);\n    });\n\n    const step2Merged = [];\n    let cur = step1Merged[0];\n\n    for (let i = 1; i < step1Merged.length; i++) {\n        const nxt = step1Merged[i];\n\n        const isSameCourseAndSection =\n            cur.name === nxt.name &&\n            cur.teacher === nxt.teacher &&\n            cur.position === nxt.position &&\n            cur.day === nxt.day &&\n            cur.startSection === nxt.startSection &&\n            cur.endSection === nxt.endSection;\n\n        if (isSameCourseAndSection) {\n            // 周次合并去重 (如 1-8 周 + 9-16 周 -> 1-16 周)\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(cur);\n            cur = nxt;\n        }\n    }\n    step2Merged.push(cur);\n\n    return step2Merged;\n}\n\n/**\n * 解析课表 HTML，返回表格的所有行（<tr> 数组）。找不到表格返回空数组。\n * 供解析课程/作息/开学日期复用，统一课表表格入口。\n */\nfunction getTableRows(html) {\n    const doc = new DOMParser().parseFromString(html, \"text/html\");\n    const table = doc.querySelector(\"table.table_border\");\n    return table ? Array.from(table.querySelectorAll(\"tr\")) : [];\n}\n\n/**\n * 解析课表 HTML 表格为课程模型数组。\n */\nfunction parseTimetableToCourses(html) {\n    const rows = getTableRows(html);\n    if (rows.length === 0) return [];\n\n    const results = [];\n\n    for (const row of rows) {\n        const cells = Array.from(row.querySelectorAll(\"td\"));\n        if (cells.length < 9) continue;\n\n        const section = parseInt(cells[0].textContent.trim(), 10);\n        if (isNaN(section) || section < 1) continue;\n\n        // cells[0]=节次, cells[1]=上课时间, cells[2..8]=星期一~星期日\n        for (let col = 2; col <= 8; col++) {\n            const day = col - 1; // 1=周一, 7=周日\n\n            // 将单元格中的 <br> 转为换行，保留纯文本\n            const clone = cells[col].cloneNode(true);\n            clone.querySelectorAll(\"br\").forEach(br => br.replaceWith(\"\\n\"));\n            const raw = (clone.textContent || \"\").replace(/\\u00A0/g, \" \");\n            const segments = raw.split(\"\\n\").map(s => s.trim()).filter(s => s.length > 0);\n\n            // 课程块形如 [课程行, 周次地点行] 成对出现。\n            // 逐段消费：仅当\"本段是课程行且下一段形如 '…周 …' 的周次地点行\"才配对，\n            // 避免教务改版导致段落错位时漏课或串位\n            for (let j = 0; j < segments.length; j++) {\n                const courseInfo = parseCourseLine(segments[j]);\n                if (!courseInfo) continue;\n                if (j + 1 >= segments.length) continue;\n\n                // 周次地点行，形如 \"1-5,7-9,11-16周 L255极简型智慧教室\"\n                const timePlace = segments[j + 1];\n                const match = timePlace.match(/^(.+?)周\\s*(.*)$/);\n                if (!match) continue;\n                const weeks = parseWeeks(match[1]);\n                const position = (match[2] || \"\").trim();\n                if (weeks.length === 0) continue;\n\n                results.push({\n                    name: courseInfo.name,\n                    teacher: courseInfo.teacher,\n                    position: position,\n                    day: day,\n                    startSection: section,\n                    endSection: section,\n                    weeks: weeks\n                });\n                j++; // 已消费周次地点行\n            }\n        }\n    }\n\n    return mergeAndDistinctCourses(results);\n}\n\n/**\n * 校验作息是否满足官方规则（wiki《一些数据的格式信息》1.2 节）：\n *   - number 必须从 1 开始连续递增，不允许空洞；\n *   - startTime / endTime 匹配 \"HH:mm\" 且 start < end；\n *   - 相邻节次不重叠（下一节 startTime 不早于上一节 endTime）。\n * 返回 false 时调用方应回退写死常量，避免 App 侧校验拒绝导致作息丢失。\n */\nfunction isValidTimeSlots(slots) {\n    if (!Array.isArray(slots) || slots.length === 0) return false;\n    const toMinutes = t => {\n        const m = /^(\\d{1,2}):(\\d{2})$/.exec(t || \"\");\n        return m ? parseInt(m[1], 10) * 60 + parseInt(m[2], 10) : NaN;\n    };\n    for (let i = 0; i < slots.length; i++) {\n        if (slots[i].number !== i + 1) return false;            // 必须从 1 连续递增\n        const s = toMinutes(slots[i].startTime);\n        const e = toMinutes(slots[i].endTime);\n        if (isNaN(s) || isNaN(e) || s >= e) return false;        // 格式合法 且 start < end\n        if (i > 0 && s < toMinutes(slots[i - 1].endTime)) return false; // 相邻不重叠\n    }\n    return true;\n}\n\n/**\n * 从课表 HTML 动态提取作息时间（节次 + 上课时间列，如 \"08:20-09:05\"）。\n * 返回 [{ number, startTime, endTime }]；无有效节次时返回 null（由调用方回退写死常量）。\n * 表头行（节次为\"节\"字）与 rowspan 跨节的空节次行经 parseInt 后自然跳过。\n */\nfunction parseTimeSlots(html) {\n    try {\n        const rows = getTableRows(html);\n        if (rows.length === 0) return null;\n        const slots = [];\n        for (const row of rows) {\n            const cells = Array.from(row.querySelectorAll(\"td\"));\n            if (cells.length < 2) continue;\n            const number = parseInt(cells[0].textContent.trim(), 10);\n            if (isNaN(number) || number < 1) continue;\n            const timeText = (cells[1].textContent || \"\").trim();\n            const m = timeText.match(/^(\\d{1,2}:\\d{2})\\s*-\\s*(\\d{1,2}:\\d{2})$/);\n            if (!m) continue;\n            slots.push({ number: number, startTime: m[1], endTime: m[2] });\n        }\n        if (slots.length === 0) return null;\n        slots.sort((a, b) => a.number - b.number);\n        // 官方校验不通过则返回 null → 调用方回退写死 TIME_SLOTS\n        return isValidTimeSlots(slots) ? slots : null;\n    } catch (e) {\n        console.error(\"解析作息时间失败:\", e);\n        return null;\n    }\n}\n\n// ==================== 网络请求 ====================\n\n/**\n * 带超时的 fetch 封装：统一 AbortController 超时与登录会话 Cookie(credentials: \"include\")。\n * 超时/网络异常由调用方 catch 处理。\n */\nasync function fetchWithTimeout(url, options) {\n    const controller = new AbortController();\n    const timer = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);\n    try {\n        return await fetch(url, Object.assign({ credentials: \"include\" }, options, { signal: controller.signal }));\n    } finally {\n        clearTimeout(timer);\n    }\n}\n\n/**\n * 请求指定周次的课表（POST，复刻页面\"查周课表\"表单）。\n * 成功返回响应 HTML；任何失败返回 null。\n */\nasync function fetchWeekTimetable(semesterType, weekNo) {\n    try {\n        const resp = await fetchWithTimeout(COURSE_ACTION_URL, {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/x-www-form-urlencoded; charset=UTF-8\" },\n            body: new URLSearchParams({\n                setAction: \"userCourseScheduleTable\",\n                viewType: \"studentCourseTableWeek\",\n                selectTableType: semesterType,\n                queryType: \"student\",\n                weekNo: String(weekNo)\n            }).toString()\n        });\n        if (!resp.ok) return null;\n        return await resp.text();\n    } catch (e) {\n        console.error(`获取第${weekNo}周课表失败:`, e);\n        return null;\n    }\n}\n\n/**\n * 逐周抓取整学期课表并合并（教务没有可用的\"全部周次\"接口）。\n *\n * ⚠️ 实测结论：页面下拉的\"全部周次\"（weekNo 为空）实际仍返回\"当前周\"课表，\n * 教务默认视图也是\"当前周\"——只请求一次会漏掉大量课程（实测仅得到 2 门）。\n * 因此必须逐周请求：每周响应中的课程自带完整周次信息，合并去重即可还原整学期。\n * 策略：先抓第 1 周（同时用于登录检测与解析开学日期），再按第 1 周课程的最大周次\n * 并发补齐其余周次（并发 4，兼顾速度与教务限流）。\n *\n * 返回：\n *   - { loggedIn: true, courses, week1Html }  成功（week1Html 供解析开学日期）\n *   - { error: \"not_logged_in\" | \"network\" | \"no_table\" }\n */\nasync function fetchAllWeeksTimetable(semesterType, onProgress) {\n    const firstHtml = await fetchWeekTimetable(semesterType, 1);\n    if (!firstHtml) return { error: \"network\" };\n    if (firstHtml.includes('id=\"ranstring\"') || firstHtml.includes(\"LoginForm\")) return { error: \"not_logged_in\" };\n    if (!firstHtml.includes(\"table_border\")) return { error: \"no_table\" };\n\n    const week1Courses = parseTimetableToCourses(firstHtml);\n    const maxWeek = week1Courses.reduce((m, c) => Math.max(m, Math.max(...c.weeks)), 0) || 19;\n    const all = [...week1Courses];\n\n    const weeks = [];\n    for (let w = 2; w <= Math.min(maxWeek, 25); w++) weeks.push(w);\n\n    const CHUNK = 4;\n    let processed = 1;\n    const total = weeks.length + 1;\n    if (onProgress) onProgress(processed, total);\n    for (let i = 0; i < weeks.length; i += CHUNK) {\n        const batch = weeks.slice(i, i + CHUNK);\n        const htmls = await Promise.all(batch.map(w => fetchWeekTimetable(semesterType, w)));\n        htmls.forEach(h => {\n            if (!h) return;\n            const cs = parseTimetableToCourses(h);\n            if (cs.length) all.push(...cs);\n        });\n        processed += batch.length;\n        if (onProgress) onProgress(Math.min(processed, total), total);\n    }\n\n    return { loggedIn: true, courses: mergeAndDistinctCourses(all), week1Html: firstHtml };\n}\n\n/**\n * 从第 1 周课表 HTML 解析开学日期（第一周第一天 = 表头\"星期一\"的日期）。\n * 返回 \"yyyy-MM-dd\"（官方 CourseConfigJsonModel 格式）；解析失败返回 null。\n *\n * 年份策略（两步）：\n *   1) 优先页头学年解析：\"2025-2026第2学期\" → 第1学期取学年首年(秋季)、第2学期取学年次年(春季)；\n *   2) 兜底：取 \"MM月DD日\" 距今天最近的年份（候选: 去年/今年/明年）。\n *      依据：教务系统仅显示本学期，开学日必然距今天不足半年，最近年份即正确年份。\n */\nfunction parseSemesterStartDate(html) {\n    try {\n        const rows = getTableRows(html);\n        if (rows.length === 0) return null;\n        const headerRow = rows[0];\n        const cells = headerRow ? Array.from(headerRow.querySelectorAll(\"td\")) : [];\n        // 表头：[0]=节, [1]=上课时间, [2]=星期一 ...\n        if (cells.length < 3) return null;\n        const mondayText = cells[2].textContent || \"\"; // 如 \"星期一03月02日\"\n        const m = mondayText.match(/(\\d{1,2})月(\\d{1,2})日/);\n        if (!m) return null;\n        const month = parseInt(m[1], 10);\n        const day = parseInt(m[2], 10);\n        if (month < 1 || month > 12 || day < 1 || day > 31) return null;\n\n        // 年份：优先页头学年解析\n        let year = null;\n        const termMatch = html.match(/(20\\d{2})\\s*[-—]\\s*(20\\d{2})第?(\\d)学期/);\n        if (termMatch) {\n            const y1 = parseInt(termMatch[1], 10);\n            const y2 = parseInt(termMatch[2], 10);\n            const termNo = parseInt(termMatch[3], 10);\n            if (y2 === y1 + 1 && (termNo === 1 || termNo === 2)) {\n                year = termNo === 2 ? y2 : y1; // 第1学期=首年(秋季)，第2学期=次年(春季)\n            }\n        }\n\n        // 兜底：距今天最近的年份\n        if (!year) {\n            const now = new Date();\n            const thisYear = now.getFullYear();\n            let best = thisYear;\n            let bestDiff = Infinity;\n            for (const y of [thisYear - 1, thisYear, thisYear + 1]) {\n                const d = new Date(y, month - 1, day);\n                const diff = Math.abs(d - now);\n                if (diff < bestDiff) { bestDiff = diff; best = y; }\n            }\n            year = best;\n        }\n\n        const pad = n => String(n).padStart(2, \"0\");\n        return `${year}-${pad(month)}-${pad(day)}`;\n    } catch (e) {\n        console.error(\"解析开学日期失败:\", e);\n        return null;\n    }\n}\n\n// ==================== 学期选择 ====================\n\n/**\n * 从选课页 HTML 解析真实学期名（如 \"2025-2026第2学期\"）。\n * 页头 userInfo 形如 \"学号 姓名 <span>2025-2026第2学期</span> 课表\"。\n * 解析失败返回 null（由调用方回退使用通用名）。\n */\nfunction parseSemesterLabel(html) {\n    const m = html.match(/(\\d{4}-\\d{4}第\\d学期)/);\n    return m ? m[1] : null;\n}\n\n/**\n * 从选课页 HTML 解析\"课程名称 → 学分\"映射。\n * 表格列：序号|学期|选课编号|课程代码|课程名称|班号|开课学院|任课教师|学分|性质|上课时间地点|操作\n * 表头行、未选课占位行（课程名为空）、学分非正数均自动跳过。解析失败返回空对象。\n */\nfunction parseCreditMap(html) {\n    const map = {};\n    try {\n        const rows = getTableRows(html);\n        for (const row of rows) {\n            const cells = Array.from(row.querySelectorAll(\"td\"));\n            if (cells.length < 9) continue;\n            const name = (cells[4].textContent || \"\").trim();      // 课程名称\n            if (!name) continue;\n            const credit = parseFloat((cells[8].textContent || \"\").trim()); // 学分\n            if (!isNaN(credit) && credit > 0) map[name] = credit;\n        }\n    } catch (e) {\n        console.error(\"解析学分失败:\", e);\n    }\n    return map;\n}\n\n/**\n * 探测指定学期：请求选课页(userCourseSchedule)一次，同时得到\n *   ① 页头真实学期名（如 \"2025-2026第2学期\"）② 课程名称→学分映射。\n * 任何失败返回 null（调用方回退通用名，且不注入学分）。\n */\nasync function fetchSemesterInfo(type) {\n    try {\n        const resp = await fetchWithTimeout(COURSE_ACTION_URL + \"?setAction=userCourseSchedule&selectTableType=\" + type);\n        if (!resp.ok) return null;\n        const html = await resp.text();\n        return { label: parseSemesterLabel(html), creditMap: parseCreditMap(html) };\n    } catch (e) {\n        console.error(\"探测学期信息失败(\", type, \"):\", e);\n        return null;\n    }\n}\n\n/**\n * 让用户选择导入学期。用 showSingleSelection 显示两个学期的真实学期名\n * （如 \"2025-2026第2学期\" / \"2026-2027第1学期\"，比\"本学期/下学期\"更明确）；\n * 探测不到真实名时回退显示通用名。取消或探测失败时回退默认本学期(ThisTerm)。\n * 返回 { semesterType, creditMap }。\n */\nasync function selectSemester() {\n    const kinds = [\n        { value: \"ThisTerm\", label: \"本学期\" },\n        { value: \"NextTerm\", label: \"下学期\" }\n    ];\n    const infos = await Promise.all(kinds.map(k => fetchSemesterInfo(k.value)));\n    const names = kinds.map((k, i) => (infos[i] && infos[i].label) || k.label);\n    const idx = await window.shiguangBridgePromise.showSingleSelection(\"选择导入学期\", JSON.stringify(names), 0);\n    const chosen = (idx == null || idx === undefined || idx === -1 || !kinds[idx]) ? 0 : idx;\n    return {\n        semesterType: kinds[chosen].value,\n        creditMap: (infos[chosen] && infos[chosen].creditMap) || {}\n    };\n}\n\n/**\n * 按课程名把学分注入课程记录（选课页学分表 → 课表课程）。\n * 匹配不到时保持原样（不设置该字段），不影响导入。\n */\nfunction applyCredits(courses, creditMap) {\n    if (!creditMap || Object.keys(creditMap).length === 0) return courses;\n    for (const c of courses) {\n        const credit = creditMap[c.name];\n        if (typeof credit === \"number\") c.credit = credit;\n    }\n    return courses;\n}\n\n/**\n * 构造课表配置：学期总周数（取课程最大周）+ 开学日期（可选）。\n * 开学日期：从已抓取的第 1 周课表表头取\"星期一\"日期（第一周第一天，\"yyyy-MM-dd\"，官方格式）；\n * 解析失败时不设置该字段（App 端可手动设置），不影响课程导入。\n */\nfunction fetchCourseConfig(week1Html, courses) {\n    const maxWeek = courses.reduce((max, c) => Math.max(max, Math.max(...c.weeks)), 0);\n    const config = { semesterTotalWeeks: Math.max(maxWeek, 1) };\n    if (week1Html) {\n        const semesterStartDate = parseSemesterStartDate(week1Html);\n        if (semesterStartDate) {\n            config.semesterStartDate = semesterStartDate;\n            console.log(\"开学日期:\", semesterStartDate);\n        }\n    }\n    return config;\n}\n\n// ==================== 主流程 ====================\n\nasync function runImportFlow() {\n    const BRIDGE = window.shiguangBridge;\n    const BRIDGE_P = window.shiguangBridgePromise;\n    if (!BRIDGE || !BRIDGE_P) {\n        console.error(\"桥接 API 不可用（缺少 window.shiguangBridge / window.shiguangBridgePromise）\");\n        return;\n    }\n\n    BRIDGE.showToast(\"正在初始化吉利学院课表导入...\");\n\n    // 1. 前置提示\n    const confirmed = await BRIDGE_P.showAlert(\n        \"教务系统课表导入\",\n        \"请确认已在当前页面成功登录教务系统（输入学号、密码及验证码）。\\n登录成功后点击“好的，开始导入”。\",\n        \"好的，开始导入\"\n    );\n    if (!confirmed) {\n        BRIDGE.showToast(\"已取消导入\");\n        return;\n    }\n\n    // 2. 选择导入学期（默认本学期），逐周抓取该学期课表并合并\n    const { semesterType, creditMap } = await selectSemester();\n    BRIDGE.showToast(\"正在获取课表数据...\");\n    const result = await fetchAllWeeksTimetable(semesterType, (done, total) => {\n        BRIDGE.showToast(`正在获取课表数据...（${done}/${total} 周）`);\n    });\n    if (result.error === \"not_logged_in\") {\n        await BRIDGE_P.showAlert(\n            \"未检测到登录状态\",\n            \"当前会话未登录，请先在页面中完成登录，之后重新发起导入。\",\n            \"知道了\"\n        );\n        BRIDGE.showToast(\"未登录，导入中止\");\n        return;\n    }\n    if (result.error === \"network\") {\n        BRIDGE.showToast(\"获取课表失败（网络异常或超时），请检查网络后重试\");\n        return;\n    }\n    if (result.error === \"no_table\") {\n        BRIDGE.showToast(\"未获取到课表数据，请确认登录状态后重试\");\n        return;\n    }\n\n    // 3. 课程已逐周合并去重，这里按课名注入学分（选课页学分表）\n    const courses = result.courses || [];\n    if (courses.length === 0) {\n        BRIDGE.showToast(\"未解析到课程数据，请确认所选学期是否有课程\");\n        return;\n    }\n    applyCredits(courses, creditMap);\n    console.log(\"解析到课程记录数:\", courses.length, courses);\n\n    // 4. 保存课程\n    try {\n        await BRIDGE_P.saveImportedCourses(JSON.stringify(courses));\n        BRIDGE.showToast(`成功保存 ${courses.length} 条课程记录`);\n    } catch (e) {\n        BRIDGE.showToast(\"课程保存失败: \" + e.message);\n        return;\n    }\n\n    // 5. 保存作息时间（从课表\"上课时间\"列动态提取，学校调作息后无需改代码；提取失败回退写死常量）\n    try {\n        const timeSlots = parseTimeSlots(result.week1Html) || TIME_SLOTS;\n        await BRIDGE_P.savePresetTimeSlots(JSON.stringify(timeSlots));\n        BRIDGE.showToast(\"作息时间保存成功\");\n    } catch (e) {\n        BRIDGE.showToast(\"作息时间保存失败: \" + e.message);\n    }\n\n    // 6. 保存课表配置（学期总周数 + 开学日期，均取自第 1 周响应）\n    try {\n        const config = fetchCourseConfig(result.week1Html, courses);\n        await BRIDGE_P.saveCourseConfig(JSON.stringify(config));\n    } catch (e) {\n        BRIDGE.showToast(\"课表配置保存失败: \" + e.message);\n    }\n\n    BRIDGE.showToast(`课表导入完成，共 ${courses.length} 条记录`);\n    BRIDGE.notifyTaskCompletion();\n}\n\n// 启动导入流程\nrunImportFlow();\n","JLU_01":"// 文件: JLU_01.js (JLU 吉林大学教务适配)\n// 经 iedu.jlu.edu.cn 直连\"(新)教务管理系统\"(金智旧版接口)抓取课表\n// 流程：统一身份认证登录 -> 进入(新)教务\"我的课表\"页 -> 触发本脚本\n// 兼容：经 Sangfor 网页 VPN 代理访问时基址可自动适配，无需改动脚本\n\n// ========== 运行时提取教务站点基址 ==========\n// 公网直连时基址为 https://iedu.jlu.edu.cn；若经 Sangfor webvpn 代理，则为\n// https://vpn.jlu.edu.cn/https/<会话hex>（该 hex 是【会话相关】的，不能硬编码）。\n// 两种情况都在课表页运行时从当前页 URL 提取基址，保证会话无关。\nconst PAGE_URL = window.location.href;\nconst _idx = PAGE_URL.indexOf(\"/jwapp/sys/\");\nif (_idx < 0) {\n    window.shiguangBridge.showToast(\"请先进入(新)教务的「我的课表」页面再导入\");\n    throw new Error(\"未在课表页运行，无法定位教务站点基址\");\n}\nconst SITE_BASE = PAGE_URL.substring(0, _idx);            // https://iedu.jlu.edu.cn\nconst REFERER = PAGE_URL;                                 // 当前课表页 URL 作为 Referer\n\n// 七个金智接口（均 POST，credentials:include 携带教务站点会话 cookie）\nconst EP_CURRENT_SEM   = \"/jwapp/sys/wdkb/modules/jshkcb/dqxnxq.do\";    // 当前学期（空 body）\nconst EP_SEMESTER_LIST = \"/jwapp/sys/wdkb/modules/jshkcb/xnxqcx.do\";   // 学期列表（*order=-DM 倒序，手动选择用）\nconst EP_SEM_CAL       = \"/jwapp/sys/wdkb/modules/xskcb/cxxljc.do\";     // 学期校历（XN+XQ -> 起始日/总周次）\nconst EP_SECTIONS      = \"/jwapp/sys/wdkb/modules/jshkcb/jc.do\";        // 节次时间（空 body）\nconst EP_COURSES       = \"/jwapp/sys/wdkb/modules/xskcb/cxxszhxqkb.do\"; // 课表（XNXQDM，不传 SKZC 取全部）\nconst EP_CHANGES       = \"/jwapp/sys/wdkb/modules/xskcb/xsdkkc.do\";     // 调课/停课（XNXQDM）\nconst EP_UNDETERMINED  = \"/jwapp/sys/wdkb/modules/xskcb/xswpkc.do\";    // 未定时间课程（XNXQDM，仅提醒不导入）\n\n// ========== 请求工具 ==========\nasync function api(path, body) {\n    const hasBody = body != null && body !== \"\";\n    const headers = {\n        \"Accept\": \"application/json, text/javascript, */*; q=0.01\",\n        \"X-Requested-With\": \"XMLHttpRequest\",\n        \"Referer\": REFERER\n    };\n    if (hasBody) {\n        headers[\"Content-Type\"] = \"application/x-www-form-urlencoded; charset=UTF-8\";\n    }\n    const res = await fetch(SITE_BASE + path, {\n        method: \"POST\",\n        headers: headers,\n        body: hasBody ? body : \"\",\n        credentials: \"include\"\n    });\n    return res.json();\n}\n\n// ========== 解析：周次二进制串 \"0000111111111111\" -> [5,6,...,16] ==========\n// 长度可变（14/16...），按字符位遍历即可\nfunction parseWeeksFromSkzc(skzc) {\n    const weeks = [];\n    const s = skzc || \"\";\n    for (let i = 0; i < s.length; i++) {\n        if (s[i] === \"1\") weeks.push(i + 1);\n    }\n    return weeks;\n}\n\n// ========== 解析：教师字段 ==========\n// 教务格式为 \"姓名/工号\"，多教师之间用 \",\" 分隔（工号不能当成第二位教师）\nfunction cleanTeacher(raw) {\n    return (raw || \"\").split(\",\").map(t => t.split(\"/\")[0].trim()).filter(Boolean).join(\",\");\n}\n\n// ========== 解析：单条金智课程 -> 拾光模型 ==========\nfunction parseSingleCourse(raw) {\n    const name = raw.KCM;\n    const teacher = cleanTeacher(raw.SKJS) || \"未知教师\";\n    const position = raw.JASMC || \"待定\";          // JASMC 可能为 null\n    const day = parseInt(raw.SKXQ, 10);            // 1=周一...7=周日\n    const startSection = parseInt(raw.KSJC, 10);\n    const endSection = parseInt(raw.JSJC, 10);\n    const weeks = parseWeeksFromSkzc(raw.SKZC);\n    if (!name || !day || !startSection || !endSection || weeks.length === 0) {\n        return null;\n    }\n    return {\n        name, teacher, position, day, startSection, endSection, weeks,\n        _kbId: raw.KBID     // 内部字段，调课按 KBID 匹配用，保存前清除\n    };\n}\n\n// ========== 解析：节次时间行 -> timeSlots（只取 SFSY==1 启用的节次）==========\nfunction parseTimeSlots(rows) {\n    return (rows || [])\n        .filter(r => Number(r.SFSY) === 1)\n        .map(r => ({\n            number: r.DM,\n            startTime: r.KSSJ,\n            endTime: r.JSSJ\n        }))\n        .sort((a, b) => a.number - b.number);\n}\n\n// ========== 解析：学期校历 -> {startDate, totalWeeks} ==========\nfunction parseSemesterCalendar(rows) {\n    const r = (rows || [])[0];\n    if (!r) return null;\n    const startDate = r.XQKSRQ ? String(r.XQKSRQ).split(\" \")[0] : null; // \"2026-03-09\"\n    const totalWeeks = Number(r.ZZC) || 20;                              // 18\n    return { startDate, totalWeeks };\n}\n\n// ========== UI：开始提示 ==========\nasync function promptUserToStart() {\n    const confirmed = await window.shiguangBridgePromise.showAlert(\n        \"吉林大学课表导入\",\n        \"请确保您已登录(新)教务管理系统，并已进入「我的课表」页面。\\n未停留在课表页可能导致会话失效，无法获取数据。\",\n        \"开始导入\"\n    );\n    if (!confirmed) {\n        window.shiguangBridge.showToast(\"已取消导入\");\n        return false;\n    }\n    return true;\n}\n\n// ========== 学期选择（默认当前学期，可选其他）==========\n// 假期教务系统可能仍把\"当前学期\"指向上学期，故保留手动选择其他学期能力\nasync function selectSemester() {\n    // 1. 尝试获取当前学期作为默认选项\n    let current = null;\n    try {\n        current = await fetchCurrentSemester();\n    } catch (e) {\n        console.warn(\"当前学期获取失败，将直接显示学期列表:\", e);\n    }\n\n    if (current) {\n        // 2. 问用户：导入当前学期 / 选择其他\n        const choice = await window.shiguangBridgePromise.showSingleSelection(\n            \"选择学期\",\n            JSON.stringify([\n                `导入当前学期：${current.mc}`,\n                \"选择其他学期\"\n            ]),\n            0\n        );\n        if (choice === null) {\n            window.shiguangBridge.showToast(\"已取消导入\");\n            return null;\n        }\n        if (choice === 0) return current;\n        // choice === 1 -> 继续到学期列表\n    }\n\n    // 3. 拉取学期列表手动选择\n    let rows = [];\n    try {\n        rows = await fetchSemesterList();\n    } catch (e) {\n        window.shiguangBridge.showToast(\"学期列表获取失败，请检查登录状态\");\n        console.error(\"学期列表获取失败:\", e);\n        return null;\n    }\n    if (rows.length === 0) {\n        window.shiguangBridge.showToast(\"未获取到学期列表\");\n        return null;\n    }\n    const labels = rows.map(r => r.MC || r.DM);\n    const idx = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择其他学期\",\n        JSON.stringify(labels),\n        0\n    );\n    if (idx === null) {\n        window.shiguangBridge.showToast(\"已取消导入\");\n        return null;\n    }\n    return parseSemesterRow(rows[idx]);\n}\n\n// ========== 数据获取 ==========\n// 解析学期行 -> {xnxqdm, xn, xq, mc}（当前学期与列表选择共用）\nfunction parseSemesterRow(r) {\n    const xnxqdm = r.DM;                       // \"2025-2026-2\"\n    const parts = xnxqdm.split(\"-\");           // [\"2025\",\"2026\",\"2\"]\n    const xn = parts[0] + \"-\" + parts[1];      // \"2025-2026\"\n    const xq = parts[2];                       // \"2\"\n    return { xnxqdm, xn, xq, mc: r.MC };\n}\n\nasync function fetchCurrentSemester() {\n    const res = await api(EP_CURRENT_SEM, \"\"); // 空 body\n    const r = res?.datas?.dqxnxq?.rows?.[0];\n    if (!r) return null;\n    return parseSemesterRow(r);\n}\n\nasync function fetchSemesterList() {\n    const res = await api(EP_SEMESTER_LIST, \"*order=-DM\"); // 倒序，最新在前\n    return res?.datas?.xnxqcx?.rows || [];\n}\n\nasync function fetchSemesterCalendar(xn, xq) {\n    const res = await api(EP_SEM_CAL, `XN=${xn}&XQ=${xq}`);\n    return parseSemesterCalendar(res?.datas?.cxxljc?.rows);\n}\n\nasync function fetchTimeSlots() {\n    const res = await api(EP_SECTIONS, \"\"); // 空 body\n    return parseTimeSlots(res?.datas?.jc?.rows);\n}\n\nasync function fetchCourses(xnxqdm) {\n    const res = await api(EP_COURSES, `XNXQDM=${xnxqdm}`); // 不传 SKZC，取全部课程\n    const rows = res?.datas?.cxxszhxqkb?.rows || [];\n    return rows.map(parseSingleCourse).filter(c => c !== null);\n}\n\n// ========== 调课/停课（xsdkkc.do，字段已按真实抓包核对）==========\nasync function fetchCourseChanges(xnxqdm) {\n    const res = await api(EP_CHANGES, `XNXQDM=${xnxqdm}&*order=-SQSJ`);\n    return res?.datas?.xsdkkc?.rows || [];\n}\n\nasync function fetchUndeterminedCourses(xnxqdm) {\n    const res = await api(EP_UNDETERMINED, `XNXQDM=${xnxqdm}`);\n    return res?.datas?.xswpkc?.rows || [];\n}\n\n/**\n * 将调课/停课变更应用到已解析课程列表（就地修改）\n * - 停课：按 KBID 匹配原始课，删除受影响周次（change.SKZC）\n * - 调课：新时间字段齐全时，按新时间/周次/师/地落位；同一 KBID 已存在该时段则并入周次\n * - weeks 清空的课程（全周停课）被过滤掉\n * @returns {{courses: Array, appliedCount: number}}\n */\nfunction applyCourseChanges(parsedCourses, rawChanges) {\n    let appliedCount = 0;\n    for (const change of rawChanges) {\n        const kbID = change.KBID;\n        // 课表接口同一学期内 KBID 唯一（实测 11/11），按 KBID 即可精确定位\n        const affected = parsedCourses.filter(c => c._kbId === kbID);\n        if (affected.length === 0) {\n            console.warn(\"调课未匹配到课程, KBID:\", kbID);\n            continue;\n        }\n        let changeApplied = false;\n\n        // 1. 从原课剔除被调走的周次（课表给整学期周次，调课记录只给被调走的那几周）\n        const weeksToRemove = parseWeeksFromSkzc(change.SKZC);\n        affected.forEach(course => {\n            const before = course.weeks.length;\n            course.weeks = course.weeks.filter(w => !weeksToRemove.includes(w));\n            if (course.weeks.length < before) changeApplied = true;\n        });\n\n        // 2. 落位到新时间/地点（新时间字段齐全即为调课，缺字段的即为停课）\n        const newWeeks = parseWeeksFromSkzc(change.XSKZC);\n        const newDay = parseInt(change.XSKXQ, 10);\n        const newStart = parseInt(change.XKSJC, 10);\n        const newEnd = parseInt(change.XJSJC, 10);\n        if (newWeeks.length > 0 && newDay && newStart && newEnd) {\n            const newPosition = change.XJASMC || change.JASMC || \"待定\";\n            // 同一 KBID 的同一课位（含教室）已存在则并入周次，避免产生重复条目\n            const existing = parsedCourses.find(c =>\n                c._kbId === kbID &&\n                c.day === newDay &&\n                c.startSection === newStart &&\n                c.endSection === newEnd &&\n                c.position === newPosition\n            );\n            if (existing) {\n                existing.weeks = [...new Set([...existing.weeks, ...newWeeks])].sort((a, b) => a - b);\n            } else {\n                parsedCourses.push({\n                    name: change.KCM,\n                    teacher: cleanTeacher(change.XSKJS) || cleanTeacher(change.YSKJS) || \"未知教师\",\n                    position: newPosition,\n                    day: newDay,\n                    startSection: newStart,\n                    endSection: newEnd,\n                    weeks: newWeeks,\n                    _kbId: kbID\n                });\n            }\n            changeApplied = true;\n        }\n        if (changeApplied) appliedCount++;\n    }\n    return { courses: parsedCourses.filter(c => c.weeks.length > 0), appliedCount };\n}\n\n/** 保存前清除内部匹配字段 */\nfunction stripInternalFields(courses) {\n    return courses.map(c => {\n        delete c._kbId;\n        return c;\n    });\n}\n\n// ========== 保存 ==========\nasync function saveAll(courses, timeSlots, startDate, totalWeeks) {\n    // 1. 课表配置（起始日 + 总周次，来自学期校历接口）\n    const config = {\n        semesterStartDate: startDate,        // \"2026-03-09\" 或 null\n        semesterTotalWeeks: totalWeeks       // 18\n    };\n    const cfgOk = await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n    if (!cfgOk) {\n        window.shiguangBridge.showToast(\"课表配置保存失败\");\n        return false;\n    }\n\n    // 2. 节次时间\n    const slotOk = await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n    if (!slotOk) {\n        window.shiguangBridge.showToast(\"节次时间保存失败\");\n        return false;\n    }\n\n    // 3. 课程\n    const courseOk = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n    if (!courseOk) {\n        window.shiguangBridge.showToast(\"课程数据保存失败\");\n        return false;\n    }\n    return true;\n}\n\n// ========== 主流程 ==========\nasync function runImportFlow() {\n    window.shiguangBridge.showToast(\"吉林大学课表导入启动...\");\n    try {\n        if (!(await promptUserToStart())) return;\n\n        // 1. 选择学期（默认当前学期，可选其他；假期教务可能仍指上学期）\n        const sem = await selectSemester();\n        if (!sem) return;\n\n        // 2. 学期校历（起始日 + 总周次）\n        const cal = await fetchSemesterCalendar(sem.xn, sem.xq);\n        const startDate = cal?.startDate || null;\n        const totalWeeks = cal?.totalWeeks || 20;\n\n        // 3. 节次时间\n        const timeSlots = await fetchTimeSlots();\n\n        // 4. 课程数据\n        const courses = await fetchCourses(sem.xnxqdm);\n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"该学期未查询到课程数据\");\n            return;\n        }\n\n        // 4.5 调课/停课（查询异常不阻塞主流程）\n        let finalCourses = courses;\n        let changeNote = \"\";\n        try {\n            const changes = await fetchCourseChanges(sem.xnxqdm);\n            const result = applyCourseChanges(courses, changes);\n            finalCourses = result.courses;\n            if (result.appliedCount > 0) {\n                changeNote = `已应用${result.appliedCount}条调课`;\n            }\n        } catch (e) {\n            console.warn(\"调课处理跳过:\", e);\n            changeNote = \"调课查询异常\";\n        }\n        finalCourses = stripInternalFields(finalCourses);\n\n        // 4.6 未定时间课程（仅提醒不导入；查询失败静默跳过）\n        let undetermined = [];\n        try {\n            undetermined = await fetchUndeterminedCourses(sem.xnxqdm);\n        } catch (e) {\n            console.warn(\"未定课程查询跳过:\", e);\n        }\n\n        // 5. 保存\n        window.shiguangBridge.showToast(`当前学期：${sem.mc}，${finalCourses.length} 条课程${changeNote ? \"（\" + changeNote + \"）\" : \"\"}，正在导入...`);\n        const ok = await saveAll(finalCourses, timeSlots, startDate, totalWeeks);\n        if (!ok) return;\n\n        // 5.5 未定时间课程提醒（导入已成功；提醒失败不回滚，仍结束流程）\n        if (undetermined.length > 0) {\n            try {\n                const names = [...new Set(undetermined.map(c => c.KCM).filter(Boolean))].join(\"、\");\n                await window.shiguangBridgePromise.showAlert(\n                    \"导入完成\",\n                    `已导入 ${finalCourses.length} 条课程。\\n另有 ${undetermined.length} 门课程上课时间暂未确定，未导入：${names}。\\n请关注教务通知，时间确定后重新导入。`,\n                    \"知道了\"\n                );\n            } catch (e) {\n                console.warn(\"未定课程提醒失败:\", e);\n                window.shiguangBridge.showToast(`导入成功！共 ${finalCourses.length} 条课程。`);\n            }\n        } else {\n            window.shiguangBridge.showToast(`导入成功！共 ${finalCourses.length} 条课程。`);\n        }\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        console.error(\"主流程异常:\", error);\n        window.shiguangBridge.showToast(\"意外错误: \" + error.message);\n    }\n}\n\n// 启动\nrunImportFlow();\n","JLU_02":"// 文件: JLU_01.js (JLU 吉林大学教务适配)\n// 经 iedu.jlu.edu.cn 直连\"(新)教务管理系统\"(金智旧版接口)抓取课表\n// 流程：统一身份认证登录 -> 进入(新)教务\"我的课表\"页 -> 触发本脚本\n// 兼容：经 Sangfor 网页 VPN 代理访问时基址可自动适配，无需改动脚本\n\n// ========== 运行时提取教务站点基址 ==========\n// 公网直连时基址为 https://iedu.jlu.edu.cn；若经 Sangfor webvpn 代理，则为\n// https://vpn.jlu.edu.cn/https/<会话hex>（该 hex 是【会话相关】的，不能硬编码）。\n// 两种情况都在课表页运行时从当前页 URL 提取基址，保证会话无关。\nconst PAGE_URL = window.location.href;\nconst _idx = PAGE_URL.indexOf(\"/jwapp/sys/\");\nif (_idx < 0) {\n    window.shiguangBridge.showToast(\"请先进入(新)教务的「我的课表」页面再导入\");\n    throw new Error(\"未在课表页运行，无法定位教务站点基址\");\n}\nconst SITE_BASE = PAGE_URL.substring(0, _idx);            // https://iedu.jlu.edu.cn\nconst REFERER = PAGE_URL;                                 // 当前课表页 URL 作为 Referer\n\n// 七个金智接口（均 POST，credentials:include 携带教务站点会话 cookie）\nconst EP_CURRENT_SEM   = \"/jwapp/sys/wdkb/modules/jshkcb/dqxnxq.do\";    // 当前学期（空 body）\nconst EP_SEMESTER_LIST = \"/jwapp/sys/wdkb/modules/jshkcb/xnxqcx.do\";   // 学期列表（*order=-DM 倒序，手动选择用）\nconst EP_SEM_CAL       = \"/jwapp/sys/wdkb/modules/xskcb/cxxljc.do\";     // 学期校历（XN+XQ -> 起始日/总周次）\nconst EP_SECTIONS      = \"/jwapp/sys/wdkb/modules/jshkcb/jc.do\";        // 节次时间（空 body）\nconst EP_COURSES       = \"/jwapp/sys/wdkb/modules/xskcb/cxxszhxqkb.do\"; // 课表（XNXQDM，不传 SKZC 取全部）\nconst EP_CHANGES       = \"/jwapp/sys/wdkb/modules/xskcb/xsdkkc.do\";     // 调课/停课（XNXQDM）\nconst EP_UNDETERMINED  = \"/jwapp/sys/wdkb/modules/xskcb/xswpkc.do\";    // 未定时间课程（XNXQDM，仅提醒不导入）\n\n// ========== 请求工具 ==========\nasync function api(path, body) {\n    const hasBody = body != null && body !== \"\";\n    const headers = {\n        \"Accept\": \"application/json, text/javascript, */*; q=0.01\",\n        \"X-Requested-With\": \"XMLHttpRequest\",\n        \"Referer\": REFERER\n    };\n    if (hasBody) {\n        headers[\"Content-Type\"] = \"application/x-www-form-urlencoded; charset=UTF-8\";\n    }\n    const res = await fetch(SITE_BASE + path, {\n        method: \"POST\",\n        headers: headers,\n        body: hasBody ? body : \"\",\n        credentials: \"include\"\n    });\n    return res.json();\n}\n\n// ========== 解析：周次二进制串 \"0000111111111111\" -> [5,6,...,16] ==========\n// 长度可变（14/16...），按字符位遍历即可\nfunction parseWeeksFromSkzc(skzc) {\n    const weeks = [];\n    const s = skzc || \"\";\n    for (let i = 0; i < s.length; i++) {\n        if (s[i] === \"1\") weeks.push(i + 1);\n    }\n    return weeks;\n}\n\n// ========== 解析：教师字段 ==========\n// 教务格式为 \"姓名/工号\"，多教师之间用 \",\" 分隔（工号不能当成第二位教师）\nfunction cleanTeacher(raw) {\n    return (raw || \"\").split(\",\").map(t => t.split(\"/\")[0].trim()).filter(Boolean).join(\",\");\n}\n\n// ========== 解析：单条金智课程 -> 拾光模型 ==========\nfunction parseSingleCourse(raw) {\n    const name = raw.KCM;\n    const teacher = cleanTeacher(raw.SKJS) || \"未知教师\";\n    const position = raw.JASMC || \"待定\";          // JASMC 可能为 null\n    const day = parseInt(raw.SKXQ, 10);            // 1=周一...7=周日\n    const startSection = parseInt(raw.KSJC, 10);\n    const endSection = parseInt(raw.JSJC, 10);\n    const weeks = parseWeeksFromSkzc(raw.SKZC);\n    if (!name || !day || !startSection || !endSection || weeks.length === 0) {\n        return null;\n    }\n    return {\n        name, teacher, position, day, startSection, endSection, weeks,\n        _kbId: raw.KBID     // 内部字段，调课按 KBID 匹配用，保存前清除\n    };\n}\n\n// ========== 解析：节次时间行 -> timeSlots（只取 SFSY==1 启用的节次）==========\nfunction parseTimeSlots(rows) {\n    return (rows || [])\n        .filter(r => Number(r.SFSY) === 1)\n        .map(r => ({\n            number: r.DM,\n            startTime: r.KSSJ,\n            endTime: r.JSSJ\n        }))\n        .sort((a, b) => a.number - b.number);\n}\n\n// ========== 解析：学期校历 -> {startDate, totalWeeks} ==========\nfunction parseSemesterCalendar(rows) {\n    const r = (rows || [])[0];\n    if (!r) return null;\n    const startDate = r.XQKSRQ ? String(r.XQKSRQ).split(\" \")[0] : null; // \"2026-03-09\"\n    const totalWeeks = Number(r.ZZC) || 20;                              // 18\n    return { startDate, totalWeeks };\n}\n\n// ========== UI：开始提示 ==========\nasync function promptUserToStart() {\n    const confirmed = await window.shiguangBridgePromise.showAlert(\n        \"吉林大学课表导入\",\n        \"请确保您已登录(新)教务管理系统，并已进入「我的课表」页面。\\n未停留在课表页可能导致会话失效，无法获取数据。\",\n        \"开始导入\"\n    );\n    if (!confirmed) {\n        window.shiguangBridge.showToast(\"已取消导入\");\n        return false;\n    }\n    return true;\n}\n\n// ========== 学期选择（默认当前学期，可选其他）==========\n// 假期教务系统可能仍把\"当前学期\"指向上学期，故保留手动选择其他学期能力\nasync function selectSemester() {\n    // 1. 尝试获取当前学期作为默认选项\n    let current = null;\n    try {\n        current = await fetchCurrentSemester();\n    } catch (e) {\n        console.warn(\"当前学期获取失败，将直接显示学期列表:\", e);\n    }\n\n    if (current) {\n        // 2. 问用户：导入当前学期 / 选择其他\n        const choice = await window.shiguangBridgePromise.showSingleSelection(\n            \"选择学期\",\n            JSON.stringify([\n                `导入当前学期：${current.mc}`,\n                \"选择其他学期\"\n            ]),\n            0\n        );\n        if (choice === null) {\n            window.shiguangBridge.showToast(\"已取消导入\");\n            return null;\n        }\n        if (choice === 0) return current;\n        // choice === 1 -> 继续到学期列表\n    }\n\n    // 3. 拉取学期列表手动选择\n    let rows = [];\n    try {\n        rows = await fetchSemesterList();\n    } catch (e) {\n        window.shiguangBridge.showToast(\"学期列表获取失败，请检查登录状态\");\n        console.error(\"学期列表获取失败:\", e);\n        return null;\n    }\n    if (rows.length === 0) {\n        window.shiguangBridge.showToast(\"未获取到学期列表\");\n        return null;\n    }\n    const labels = rows.map(r => r.MC || r.DM);\n    const idx = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择其他学期\",\n        JSON.stringify(labels),\n        0\n    );\n    if (idx === null) {\n        window.shiguangBridge.showToast(\"已取消导入\");\n        return null;\n    }\n    return parseSemesterRow(rows[idx]);\n}\n\n// ========== 数据获取 ==========\n// 解析学期行 -> {xnxqdm, xn, xq, mc}（当前学期与列表选择共用）\nfunction parseSemesterRow(r) {\n    const xnxqdm = r.DM;                       // \"2025-2026-2\"\n    const parts = xnxqdm.split(\"-\");           // [\"2025\",\"2026\",\"2\"]\n    const xn = parts[0] + \"-\" + parts[1];      // \"2025-2026\"\n    const xq = parts[2];                       // \"2\"\n    return { xnxqdm, xn, xq, mc: r.MC };\n}\n\nasync function fetchCurrentSemester() {\n    const res = await api(EP_CURRENT_SEM, \"\"); // 空 body\n    const r = res?.datas?.dqxnxq?.rows?.[0];\n    if (!r) return null;\n    return parseSemesterRow(r);\n}\n\nasync function fetchSemesterList() {\n    const res = await api(EP_SEMESTER_LIST, \"*order=-DM\"); // 倒序，最新在前\n    return res?.datas?.xnxqcx?.rows || [];\n}\n\nasync function fetchSemesterCalendar(xn, xq) {\n    const res = await api(EP_SEM_CAL, `XN=${xn}&XQ=${xq}`);\n    return parseSemesterCalendar(res?.datas?.cxxljc?.rows);\n}\n\nasync function fetchTimeSlots() {\n    const res = await api(EP_SECTIONS, \"\"); // 空 body\n    return parseTimeSlots(res?.datas?.jc?.rows);\n}\n\nasync function fetchCourses(xnxqdm) {\n    const res = await api(EP_COURSES, `XNXQDM=${xnxqdm}`); // 不传 SKZC，取全部课程\n    const rows = res?.datas?.cxxszhxqkb?.rows || [];\n    return rows.map(parseSingleCourse).filter(c => c !== null);\n}\n\n// ========== 调课/停课（xsdkkc.do，字段已按真实抓包核对）==========\nasync function fetchCourseChanges(xnxqdm) {\n    const res = await api(EP_CHANGES, `XNXQDM=${xnxqdm}&*order=-SQSJ`);\n    return res?.datas?.xsdkkc?.rows || [];\n}\n\nasync function fetchUndeterminedCourses(xnxqdm) {\n    const res = await api(EP_UNDETERMINED, `XNXQDM=${xnxqdm}`);\n    return res?.datas?.xswpkc?.rows || [];\n}\n\n/**\n * 将调课/停课变更应用到已解析课程列表（就地修改）\n * - 停课：按 KBID 匹配原始课，删除受影响周次（change.SKZC）\n * - 调课：新时间字段齐全时，按新时间/周次/师/地落位；同一 KBID 已存在该时段则并入周次\n * - weeks 清空的课程（全周停课）被过滤掉\n * @returns {{courses: Array, appliedCount: number}}\n */\nfunction applyCourseChanges(parsedCourses, rawChanges) {\n    let appliedCount = 0;\n    for (const change of rawChanges) {\n        const kbID = change.KBID;\n        // 课表接口同一学期内 KBID 唯一（实测 11/11），按 KBID 即可精确定位\n        const affected = parsedCourses.filter(c => c._kbId === kbID);\n        if (affected.length === 0) {\n            console.warn(\"调课未匹配到课程, KBID:\", kbID);\n            continue;\n        }\n        let changeApplied = false;\n\n        // 1. 从原课剔除被调走的周次（课表给整学期周次，调课记录只给被调走的那几周）\n        const weeksToRemove = parseWeeksFromSkzc(change.SKZC);\n        affected.forEach(course => {\n            const before = course.weeks.length;\n            course.weeks = course.weeks.filter(w => !weeksToRemove.includes(w));\n            if (course.weeks.length < before) changeApplied = true;\n        });\n\n        // 2. 落位到新时间/地点（新时间字段齐全即为调课，缺字段的即为停课）\n        const newWeeks = parseWeeksFromSkzc(change.XSKZC);\n        const newDay = parseInt(change.XSKXQ, 10);\n        const newStart = parseInt(change.XKSJC, 10);\n        const newEnd = parseInt(change.XJSJC, 10);\n        if (newWeeks.length > 0 && newDay && newStart && newEnd) {\n            const newPosition = change.XJASMC || change.JASMC || \"待定\";\n            // 同一 KBID 的同一课位（含教室）已存在则并入周次，避免产生重复条目\n            const existing = parsedCourses.find(c =>\n                c._kbId === kbID &&\n                c.day === newDay &&\n                c.startSection === newStart &&\n                c.endSection === newEnd &&\n                c.position === newPosition\n            );\n            if (existing) {\n                existing.weeks = [...new Set([...existing.weeks, ...newWeeks])].sort((a, b) => a - b);\n            } else {\n                parsedCourses.push({\n                    name: change.KCM,\n                    teacher: cleanTeacher(change.XSKJS) || cleanTeacher(change.YSKJS) || \"未知教师\",\n                    position: newPosition,\n                    day: newDay,\n                    startSection: newStart,\n                    endSection: newEnd,\n                    weeks: newWeeks,\n                    _kbId: kbID\n                });\n            }\n            changeApplied = true;\n        }\n        if (changeApplied) appliedCount++;\n    }\n    return { courses: parsedCourses.filter(c => c.weeks.length > 0), appliedCount };\n}\n\n/** 保存前清除内部匹配字段 */\nfunction stripInternalFields(courses) {\n    return courses.map(c => {\n        delete c._kbId;\n        return c;\n    });\n}\n\n// ========== 保存 ==========\nasync function saveAll(courses, timeSlots, startDate, totalWeeks) {\n    // 1. 课表配置（起始日 + 总周次，来自学期校历接口）\n    const config = {\n        semesterStartDate: startDate,        // \"2026-03-09\" 或 null\n        semesterTotalWeeks: totalWeeks       // 18\n    };\n    const cfgOk = await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n    if (!cfgOk) {\n        window.shiguangBridge.showToast(\"课表配置保存失败\");\n        return false;\n    }\n\n    // 2. 节次时间\n    const slotOk = await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n    if (!slotOk) {\n        window.shiguangBridge.showToast(\"节次时间保存失败\");\n        return false;\n    }\n\n    // 3. 课程\n    const courseOk = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n    if (!courseOk) {\n        window.shiguangBridge.showToast(\"课程数据保存失败\");\n        return false;\n    }\n    return true;\n}\n\n// ========== 主流程 ==========\nasync function runImportFlow() {\n    window.shiguangBridge.showToast(\"吉林大学课表导入启动...\");\n    try {\n        if (!(await promptUserToStart())) return;\n\n        // 1. 选择学期（默认当前学期，可选其他；假期教务可能仍指上学期）\n        const sem = await selectSemester();\n        if (!sem) return;\n\n        // 2. 学期校历（起始日 + 总周次）\n        const cal = await fetchSemesterCalendar(sem.xn, sem.xq);\n        const startDate = cal?.startDate || null;\n        const totalWeeks = cal?.totalWeeks || 20;\n\n        // 3. 节次时间\n        const timeSlots = await fetchTimeSlots();\n\n        // 4. 课程数据\n        const courses = await fetchCourses(sem.xnxqdm);\n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"该学期未查询到课程数据\");\n            return;\n        }\n\n        // 4.5 调课/停课（查询异常不阻塞主流程）\n        let finalCourses = courses;\n        let changeNote = \"\";\n        try {\n            const changes = await fetchCourseChanges(sem.xnxqdm);\n            const result = applyCourseChanges(courses, changes);\n            finalCourses = result.courses;\n            if (result.appliedCount > 0) {\n                changeNote = `已应用${result.appliedCount}条调课`;\n            }\n        } catch (e) {\n            console.warn(\"调课处理跳过:\", e);\n            changeNote = \"调课查询异常\";\n        }\n        finalCourses = stripInternalFields(finalCourses);\n\n        // 4.6 未定时间课程（仅提醒不导入；查询失败静默跳过）\n        let undetermined = [];\n        try {\n            undetermined = await fetchUndeterminedCourses(sem.xnxqdm);\n        } catch (e) {\n            console.warn(\"未定课程查询跳过:\", e);\n        }\n\n        // 5. 保存\n        window.shiguangBridge.showToast(`当前学期：${sem.mc}，${finalCourses.length} 条课程${changeNote ? \"（\" + changeNote + \"）\" : \"\"}，正在导入...`);\n        const ok = await saveAll(finalCourses, timeSlots, startDate, totalWeeks);\n        if (!ok) return;\n\n        // 5.5 未定时间课程提醒（导入已成功；提醒失败不回滚，仍结束流程）\n        if (undetermined.length > 0) {\n            try {\n                const names = [...new Set(undetermined.map(c => c.KCM).filter(Boolean))].join(\"、\");\n                await window.shiguangBridgePromise.showAlert(\n                    \"导入完成\",\n                    `已导入 ${finalCourses.length} 条课程。\\n另有 ${undetermined.length} 门课程上课时间暂未确定，未导入：${names}。\\n请关注教务通知，时间确定后重新导入。`,\n                    \"知道了\"\n                );\n            } catch (e) {\n                console.warn(\"未定课程提醒失败:\", e);\n                window.shiguangBridge.showToast(`导入成功！共 ${finalCourses.length} 条课程。`);\n            }\n        } else {\n            window.shiguangBridge.showToast(`导入成功！共 ${finalCourses.length} 条课程。`);\n        }\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        console.error(\"主流程异常:\", error);\n        window.shiguangBridge.showToast(\"意外错误: \" + error.message);\n    }\n}\n\n// 启动\nrunImportFlow();\n","JNU_01":"//拾光课程表适配JNU脚本（fetch API）\n//本脚本的时间段自动导入仅适配珠海校区，其它校区可自行重新设置上课时间段\n\n//生成年份数组\nconst yearArr = [];\nfor(let i=1990; i<=2100; i++){\n    yearArr.push(i);\n}\n\n//根据URL特征判断当前所在界面\nfunction checkCurrentPage() {\n    const currenturl = window.location.href.toLowerCase(); //获取当前URL并转为小写\n    if (currenturl.includes(\"login?\")) {\n        return 1; //未登录，返回值1\n    }\n    if (currenturl.includes(\"new/index.html\")) {\n        return 2; //在新教务系统首页，没有进入课表，返回值2\n    }\n    if (currenturl.includes(\"jwapp/sys/wdkb\")) {\n        return 0; //成功登录且进入我的课表界面，返回值0\n    }\n    return -1; //未知错误，返回值-1\n}\n\n//显示是否确认导入课程弹窗\nasync function confirmAlert() {\n    try {\n        const confirmed = await window.shiguangBridgePromise.showAlert(\n            \"重要提醒\",\n            \"自动加载上课时间段仅支持珠海校区，\\n是否确认获取课表？\",\n            \"确认\",\n        );\n        if (confirmed) {\n            window.shiguangBridge.showToast(\"正在尝试导入课表...\");\n            return true; // 成功时返回 true\n        } else {\n            window.shiguangBridge.showToast(\"已取消！\");\n            return false; // 用户取消时返回 false\n        }\n    } catch (error) {\n        window.shiguangBridge.showToast(\"显示弹窗出错！\" + error.message);\n        return false; // 出现错误时也返回 false\n    }\n}\n\n//显示到设置中选择开学日期的提醒\nasync function setinfoAlert() {\n    const confirmed = await window.shiguangBridgePromise.showAlert(\n        \"重要提醒\",\n        \"导入课程信息成功，请到设置界面选择当前学期的开学日期\",\n        \"好的\"\n    );\n    if (!confirmed) {\n        return false;\n    }\n    return true;\n}\n\n//显示一个是否手动输入学年学期信息的弹窗\nasync function confirmGetXNXQAlert() {\n    try {\n        const confirmed = await window.shiguangBridgePromise.showAlert(\n            \"重要提醒\",\n            \"自动获取学年学期信息失败，\\n是否确认手动输入学年学期信息？\",\n            \"确认\",\n        );\n        if (confirmed) {\n            return true; // 成功时返回 true\n        } else {\n            window.shiguangBridge.showToast(\"已取消！\");\n            return false; // 用户取消时返回 false\n        }\n    } catch (error) {\n        window.shiguangBridge.showToast(\"显示弹窗出错！\" + error.message);\n        return false; // 出现错误时也返回 false\n    }\n}\n\n//向用户获取学年信息\nasync function getSession() {\n    try {\n        const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n            \"请选择学年的起始年（如2025-2026学年的2025）\",\n            JSON.stringify(yearArr),\n            36\n        );\n        if (selectedIndex !== null && selectedIndex >= 0 && selectedIndex < yearArr.length) {\n            return (yearArr[selectedIndex] + '-' + (Number(yearArr[selectedIndex])+1));\n        } else {\n            window.shiguangBridge.showToast(\"用户取消了选择！\");\n            return -1; // 用户取消时返回-1\n        }\n    } catch (error) {\n        window.shiguangBridge.showToast(\"显示列表出错！\" + error.message);\n        return -1; // 出现错误时也返回-1\n    }\n}\n\n//向用户获取学期信息\nasync function getSemester() {\n    try {\n        const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n            \"请选择学期（1-第一学期，2-第二学期）\",\n            JSON.stringify([1,2]),\n            1\n        );\n        if (selectedIndex !== null && selectedIndex >= 0 && selectedIndex < 2) {\n            if(selectedIndex === 0) {\n                return 1;\n            }else{\n                return 2;\n            }\n        } else {\n            window.shiguangBridge.showToast(\"用户取消了选择！\");\n            return -1; // 用户取消时返回 -1\n        }\n    } catch (error) {\n        window.shiguangBridge.showToast(\"显示列表出错！\" + error.message);\n        return -1; // 出现错误时也返回 -1\n    }\n}\n\n//导入预设时间段\nasync function importPresetTimeSlots() {\n    //预设节次信息，仅适用于珠海校区\n    const timeSlots = [\n        {\"number\":1,\"startTime\":\"08:00\",\"endTime\":\"08:45\"},\n        {\"number\":2,\"startTime\":\"08:55\",\"endTime\":\"09:40\"},\n        {\"number\":3,\"startTime\":\"10:00\",\"endTime\":\"10:45\"},\n        {\"number\":4,\"startTime\":\"10:55\",\"endTime\":\"11:40\"},\n        {\"number\":5,\"startTime\":\"12:40\",\"endTime\":\"13:25\"},\n        {\"number\":6,\"startTime\":\"13:35\",\"endTime\":\"14:20\"},\n        {\"number\":7,\"startTime\":\"14:30\",\"endTime\":\"15:15\"},\n        {\"number\":8,\"startTime\":\"15:25\",\"endTime\":\"16:10\"},\n        {\"number\":9,\"startTime\":\"16:20\",\"endTime\":\"17:05\"},\n        {\"number\":10,\"startTime\":\"17:15\",\"endTime\":\"18:00\"},\n        {\"number\":11,\"startTime\":\"19:00\",\"endTime\":\"19:45\"},\n        {\"number\":12,\"startTime\":\"19:55\",\"endTime\":\"20:40\"},\n        {\"number\":13,\"startTime\":\"20:50\",\"endTime\":\"21:35\"}\n    ]\n\n    try {\n        const result = await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        if (result === true) {\n        } else {\n            window.shiguangBridge.showToast(\"时间段导入失败!\");\n        }\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n    }\n}\n\n\n//使用DOM方法自动获取当前课表的学年学期信息\nfunction getSessionSemester() {\n    const oriData = document.getElementById('dqxnxq2');\n    if (!oriData) {\n        return -1;\n    }\n    const xnxqID = oriData.getAttribute('value');\n    if (!xnxqID) {\n        return -1;\n    }\n    return xnxqID;\n}\n\n//使用fetch API 获取课程表信息\nasync function getCourses(xnxqID) {\n    const fetchConfig = {\n        url:'https://jw.jnu.edu.cn/jwapp/sys/wdkb/modules/xskcb/xskcb.do',\n        method:'POST',\n        params:{\n            XNXQDM:xnxqID\n        }\n    }\n\n    try {\n        const response = await fetch(fetchConfig.url,\n            {method:fetchConfig.method,\n                headers:{'content-type':'application/x-www-form-urlencoded; charset=UTF-8'},\n                credentials:'include',\n                body:new URLSearchParams(fetchConfig.params)});\n        if (!response.ok) {\n            throw new Error(`请求失败：${response.status} ${response.statusText}`);\n        }\n        const courseData = await response.json();\n        if (courseData.datas.xskcb.totalSize === 0){\n            window.shiguangBridge.showToast(\"获取到的课表为空课表，请检查学年学期信息！\")\n            return -1;\n        }\n        window.shiguangBridge.showToast(\"成功获取课程表信息，共\" + courseData.datas.xskcb.totalSize + \"门课程\");\n        return courseData;\n    }catch (error){\n        window.shiguangBridge.showToast(\"获取课程表失败:\" + error.message);\n        return -1;\n    }\n}\n\n//处理原始数据中的周数，输出对应数组\nfunction handleWeekNum(oriData){\n    const result = [];\n    if(oriData.includes('(')){\n        const weekStr = oriData.slice(0,-4);//去掉最后四位\n        const startWeek = weekStr.split('-')[0];\n        const endWeek = weekStr.split('-')[1];\n        if(oriData.includes('单')){\n            for(let i = Number(startWeek); i<=Number(endWeek); i++){\n                if(i%2 !== 0){\n                    result.push(i);\n                }\n            }\n        }else{\n            for(let i = Number(startWeek); i<=Number(endWeek); i++){\n                if(i%2 === 0){\n                    result.push(i);\n                }\n            }\n        }\n    }else{\n        const weekStr = oriData.slice(0,-1); //去掉最后一位\n        const startWeek = weekStr.split('-')[0];\n        const endWeek = weekStr.split('-')[1];\n        for(let i = Number(startWeek); i<=Number(endWeek); i++){\n            result.push(i);\n        }\n    }\n    return result;\n}\n\n//处理原始数据中的节次信息\nfunction handleSectionNum(oriData) {\n    const result = [];\n    const coursesNumStr = oriData.slice(1,-1); //去掉最后一位和第一位\n    const startSection = coursesNumStr.split('-')[0];\n    const endSection = coursesNumStr.split('-')[1];\n    result.push(Number(startSection)); //第一位为开始节次\n    result.push(Number(endSection)); //第二位为结束节次\n    return result;\n}\n\n//处理原始数据中的星期信息\nfunction handleDayNum(OriData) {\n    const weekMap = [\n        \"星期一\",\n        \"星期二\",\n        \"星期三\",\n        \"星期四\",\n        \"星期五\",\n        \"星期六\",\n        \"星期日\",\n    ]\n    for(let i=0; i<7; i++){\n        if(OriData === weekMap[i])\n            return i+1;\n    }\n    return null;\n}\n\n// 解析得到的JSON数据\nfunction analysisCoursesInfo(oriCourseData) {\n    const courses = [];\n    const totalCourseNum = oriCourseData.datas.xskcb.totalSize;\n    if(totalCourseNum === 0){\n        return courses;\n    }\n    const coursesRows = oriCourseData.datas.xskcb.rows || [];\n    for(let i=0; i<totalCourseNum; i++){\n        const courseName = coursesRows[i].KCM ?? \"未知课程\";\n        const teacher = coursesRows[i].SKJS ?? \"未知教师\";\n        const position = coursesRows[i].JASMC ?? \"未知地点\";\n        const courseTime = coursesRows[i].SKSJ.split(' '); //第一为周次，第二位为天次，第三位为节次\n        const day = handleDayNum(courseTime[1]); //得到星期几上课\n        const sectionInfo = {\n            startSection:handleSectionNum(courseTime[2])[0], //开始节次\n            endSection:handleSectionNum(courseTime[2])[1] //结束节次\n        }\n        const weeks = handleWeekNum(courseTime[0]);\n        const courseInfo = {\n            \"name\": courseName,        // 课程名称 (String)\n            \"teacher\": teacher,      // 教师姓名 (String)\n            \"position\": position,      // 上课地点 (String)\n            \"day\": day,                 // 星期几 (Int, 1=周一, 7=周日)\n            \"startSection\": sectionInfo.startSection,        // 开始节次 (Int, 如果 isCustomTime 为 false 或未提供，则必填)\n            \"endSection\": sectionInfo.endSection,          // 结束节次 (Int, 如果 isCustomTime 为 false 或未提供，则必填)\n            \"weeks\": weeks,    // 上课周数 (Int Array, 必须是数字数组，例如 [1, 3, 5, 7])\n        }\n        courses.push(courseInfo);\n    }\n    return courses;\n}\n\n//自动获取总星期数\nfunction autoGetTotalWeekNum(courses) {\n    let totalWeekNum = 0;\n    let currentNum = 0;\n    for(let i=0; i<courses.length; i++){\n        currentNum = courses[i].weeks[courses[i].weeks.length-1];\n        if(currentNum > totalWeekNum) {\n            totalWeekNum = currentNum;\n        }\n    }\n    return totalWeekNum;\n}\n\n//导入课程数据，同时返回得到的总星期数\nasync function saveCourses(courseData) {\n    let xnxqID = getSessionSemester();\n    if (xnxqID === -1) {\n        //无法自动获取学年学期信息，询问是否手动输入\n        if(await confirmGetXNXQAlert()){\n            const session = await getSession();\n            if(session === -1){\n                return -1;\n            }\n            const semester = await getSemester();\n            if(semester === -1){\n                return -1;\n            }\n            xnxqID = (session + '-' + semester);\n            window.shiguangBridge.showToast(\"你选择的学年学期信息：\" + xnxqID);\n        }else {\n            return -1;\n        }\n    }else{\n        window.shiguangBridge.showToast(\"自动获取到学年学期信息：\" + xnxqID);\n    }\n\n    const rawResponse = await getCourses(xnxqID);\n    if(rawResponse === -1) {\n        return -1;\n    }\n\n    const courses = analysisCoursesInfo(rawResponse);\n    const totalWeeksNum = autoGetTotalWeekNum(courses);\n\n    try {\n        const result = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        if (result === true) {\n            //课程导入成功！\n            return totalWeeksNum;\n        } else {\n            window.shiguangBridge.showToast(\"课程导入失败!\");\n            return -1\n        }\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入课程失败: \" + error.message);\n        return -1;\n    }\n\n}\n\n//导入课表配置\nasync function saveConfig(semesterTotalWeeks) {\n    // 注意：只传入要修改的字段，其他字段（如 semesterTotalWeeks）会使用 Kotlin 模型中的默认值\n\n    try {\n        const courseConfigData = {\n            // \"semesterStartDate\": semesterStartData, //月份要使用两位数，否则软件会崩溃\n            \"semesterTotalWeeks\": Number(semesterTotalWeeks),\n            \"defaultClassDuration\": 45,\n            \"defaultBreakDuration\": 10,\n            \"firstDayOfWeek\": 1\n        };\n        const configJsonString = JSON.stringify(courseConfigData);\n        const result = await window.shiguangBridgePromise.saveCourseConfig(configJsonString);\n        if (result === true) {\n            //课表配置导入成功\n            return 0;\n        } else {\n            window.shiguangBridge.showToast(\"课表配置导入失败\");\n            return -1;\n        }\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入配置失败: \" + error.message);\n        return -1;\n    }\n}\n\n/**\n * 编排这些异步操作，并在用户取消时停止后续执行。\n */\nasync function runAllDemosSequentially() {\n    //检查是否进入课表界面\n    const currentPageNum = checkCurrentPage();\n    if(currentPageNum === 1){\n        window.shiguangBridge.showToast(\"请登录教务系统\");\n        return;\n    }else if(currentPageNum === 2) {\n        window.shiguangBridge.showToast(\"请进入我的课表界面\");\n        return;\n    }else if(currentPageNum === -1) {\n        window.shiguangBridge.showToast(\"未知错误\");\n        return;\n    }\n\n    //确认是否导入课程\n    const alertResult = await confirmAlert();\n    if (!alertResult) {\n        return; // 用户取消，立即退出函数\n    }\n\n    //导入课程，返回-1表示导入失败\n    const totalNum = await saveCourses();\n    if(totalNum === -1) {\n        return;\n    }\n\n    //导入预设上课时间段\n    await importPresetTimeSlots();\n\n    //导入课表配置\n    const saveConfigResult = await saveConfig(totalNum);\n    if(saveConfigResult === 0)\n    {\n        //课表导入成功，提示用户设置开学日期\n        await setinfoAlert();\n    }\n    else if(saveConfigResult === -1)\n    {\n        return;\n    }\n\n    // 发送最终的生命周期完成信号\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunAllDemosSequentially();\n","UJS_01":"// 江苏大学(ujs.edu.cn) 拾光课程表适配脚本\n// 基于正方教务系统接口适配\n// 出现问题请联系作者或者提交直接pr更改,这更加快速\n\n// 基于GSMC修改\n// 作者：洛初 Github@gongfuture\n\n// 2026.03.30 第一版\n// 通过正方接口 xskbcx_cxXsgrkb 拉取个人课表，解析课程名、教师、教室、星期、节次和周次（含单双周）。\n// 交互上依次询问学年、学期与作息类型（夏令时/冬令时/智能选择，智能选择按固定切令时日期判定）。\n// 按课程所在楼栋匹配上午与下午作息，写入课程的自定义时间；导入课程、课表配置与预设时间段。\n\n// 2026.08.23 第二版\n// 桥接接口升级至 v2（window.shiguangBridge / window.shiguangBridgePromise）。\n// 补充开学日期：从首页日历区块取当前学期起止日期写入 semesterStartDate，总周数改为按实际周次取值；\n// 取不到开学日期时跳过配置保存，避免覆盖用户已有设置。\n// 课程备注补充重修标记、选课备注（体育项目、微专业等）与周次原文。\n// 集中实践课（军训、毕业设计等）无星期节次无法排课，改为弹窗提示手动添加。\n// 教师与教室为空不再丢弃课程；修正京江各号楼的楼栋匹配；支持校外 WebVPN 访问。\n\n// 2026.09.07 第三版\n// 开学日期改从校历接口 xskbcxZccx_cxZcByXnxq 按所选学年学期获取，历史学期同样能取到，\n// 总周数取校历周数，日期解析兼容 zcrq / ksrq 字段兜底；取不到校历时仍跳过配置保存。\n// 作息时间不随切令时自动变化，导入后弹窗提示下次切令时日期。\n// 新增课程合并去重：连续节次合并、同课同节次的周次合并、完全重复去重。\n// 学年学期改为从教务系统读取选项并默认选中当前学期，读取失败时回退手动输入。\n// 课程请求与校历请求并行执行，课程解析与配置计算整合进同一函数，结构对齐官方参考脚本。\n// 修复：教务页面 zftal 脚本会改写 Array.prototype.filter（回调实参颠倒），\n// 导致集中实践课被静默丢弃，改用自实现的 arrayFilter 规避；清理注释残留与冗余日志。\n\n/**\n * 数组过滤（原生实现）。\n * 教务页面加载的 zftal 脚本会改写 Array.prototype.filter/some/every，\n * 把回调实参换成 (index, value)（原生的 value 在前），\n * 原生 filter 写法在这种页面上会得到错误结果（例如过滤不掉空选项），\n * 所以这里用普通循环自行实现，不依赖任何被改写过的数组方法。\n */\nfunction arrayFilter(arr, predicate) {\n    const result = [];\n    for (let i = 0; i < arr.length; i++) {\n        if (predicate(arr[i], i, arr)) {\n            result.push(arr[i]);\n        }\n    }\n    return result;\n}\n\n/**\n * 解析周次字符串，处理单双周和周次范围。\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    const weekSets = weekStr.split(',');\n    let weeks = [];\n\n    for (const set of weekSets) {\n        const trimmedSet = set.trim();\n\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周/); // 匹配以数字周结束的\n\n        let start = 0;\n        let end = 0;\n        let processed = false;\n\n        if (rangeMatch) { // 范围, 如 \"1-5周\"\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) { // 单个周, 如 \"6周\"\n            start = end = Number(singleMatch[1]);\n            processed = true;\n        }\n\n        if (processed) {\n            // 确定单双周\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue; // 单周跳过偶数\n                if (isDouble && w % 2 !== 0) continue; // 双周跳过奇数\n                weeks.push(w);\n            }\n        }\n    }\n\n    // 去重并排序\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 节次与周次合并去重函数（参考官方 wiki 课程合并与去重函数）。\n * 正方系统常把同一门课拆成多条记录：连续节次分开返回（1-2 节 + 3-4 节）、\n * 单双周分开返回、或完全重复返回，这里统一合并/去重。\n * @param {Array<Object>} courses 原始解析课程数组\n * @returns {Array<Object>} 合并去重后的课程数组\n */\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    // 1. 深拷贝并规范周次数据，过滤无效项\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n\n    // 阶段 1：合并连续节次与完全重复记录（前提：名称、教师、地点、星期、周次一致）\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n               (a.startSection || 0) - (b.startSection || 0);\n    });\n\n    const step1Merged = [];\n    let current = list[0];\n\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n\n        const isSameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n\n        if (isSameCourseAndWeeks && isContinuous) {\n            // 节次连续：延长结束节次 (如 1-2 节 + 3-4 节 -> 1-4 节)\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            // 完全重复：跳过\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    // 阶段 2：合并同节次的周次（前提：名称、教师、地点、星期、开始/结束节次一致）\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               (a.startSection || 0) - (b.startSection || 0) ||\n               (a.endSection || 0) - (b.endSection || 0);\n    });\n\n    const step2Merged = [];\n    let cur = step1Merged[0];\n\n    for (let i = 1; i < step1Merged.length; i++) {\n        const nxt = step1Merged[i];\n\n        const isSameCourseAndSection =\n            cur.name === nxt.name &&\n            cur.teacher === nxt.teacher &&\n            cur.position === nxt.position &&\n            cur.day === nxt.day &&\n            cur.startSection === nxt.startSection &&\n            cur.endSection === nxt.endSection;\n\n        if (isSameCourseAndSection) {\n            // 周次合并去重 (如 1-8 周 + 9-16 周 -> 1-16 周，单周 + 双周 -> 每周)\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(cur);\n            cur = nxt;\n        }\n    }\n    step2Merged.push(cur);\n\n    return step2Merged;\n}\n\n/**\n * 拼接教务系统接口地址。\n * 校内直连时 location.origin 就是教务域名，前缀为空；\n * 校外经 WebVPN 访问时路径带有 /http/<hex> 前缀，必须保留，否则会变成跨域请求。\n */\nfunction buildApiUrl(path) {\n    const prefixMatch = window.location.pathname.match(/^\\/http\\/[0-9a-f]+/i);\n    const prefix = prefixMatch ? prefixMatch[0] : \"\";\n    return window.location.origin + prefix + path;\n}\n\n/**\n * 拼装课程备注。\n * xm 只有姓名，kcmc 只有课程名，以下信息只存在于原始字段里，\n * 放进备注方便用户核对：重修标记、选课备注（体育项目、微专业等）、周次原文。\n */\nfunction buildCourseRemark(rawCourse) {\n    const parts = [];\n\n    const retakeFlag = String(rawCourse.cxbjmc || \"\").trim();\n    if (retakeFlag) {\n        parts.push(retakeFlag);\n    }\n\n    const selectionNote = String(rawCourse.xkbz || \"\").trim();\n    if (selectionNote) {\n        parts.push(selectionNote);\n    }\n\n    const weekDesc = String(rawCourse.zcd || \"\").trim();\n    if (weekDesc) {\n        parts.push(weekDesc);\n    }\n\n    return parts.join(\" | \");\n}\n\n/**\n * 解析集中实践课列表（sjkList）。\n * 这类课程（军事技能训练、形势与政策等）只有课程名、教师和起止周，\n * 没有星期和节次，无法映射到周课表，只能提示用户手动添加。\n */\nfunction parsePracticeCourses(jsonData) {\n    if (!jsonData || !Array.isArray(jsonData.sjkList)) {\n        return [];\n    }\n\n    return arrayFilter(\n        jsonData.sjkList\n            .map((item) => ({\n                name: String(item.kcmc || \"\").trim(),\n                teacher: String(item.jsxm || \"\").trim(),\n                weekDesc: String(item.qsjsz || \"\").trim()\n            })),\n        (item) => item.name\n    );\n}\n\n/**\n * 解析 API 返回的 JSON 数据。\n * 合并去重后，按课程所在位置匹配作息，写入自定义时间。\n */\nfunction parseJsonData(jsonData, isSummerTime) {\n    // 检查JSON结构：新的数据在 kbList 字段中\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        console.warn(\"JS: JSON 数据结构错误或缺少 kbList 字段。\");\n        return [];\n    }\n\n    const rawCourseList = jsonData.kbList;\n    const initialCourseList = [];\n\n    for (const rawCourse of rawCourseList) {\n        // 关键字段检查：只有 kcmc(课名), xqj(星期), jcs(节次范围), zcd(周次描述) 是排课必需的。\n        // xm(教师) 与 cdmc(教室) 在实践课、线上课、未排地点的课程上可能为空，\n        // 缺这两项不影响排课，不能因此丢弃整门课程。\n        if (!rawCourse.kcmc || !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) {\n            continue;\n        }\n\n        const weeksArray = parseWeeks(rawCourse.zcd);\n\n        // 周次有效性检查\n        if (weeksArray.length === 0) {\n            continue;\n        }\n\n        // 解析节次范围，例如 \"1-2\"\n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]);\n\n        const day = Number(rawCourse.xqj); // xqj: 星期几 (周一为1, 周日为7)\n\n        // 数字有效性检查\n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) || day < 1 || day > 7 || startSection > endSection) {\n            continue;\n        }\n\n        const remark = buildCourseRemark(rawCourse);\n\n        const course = {\n            name: String(rawCourse.kcmc).trim(),\n            teacher: String(rawCourse.xm || \"\").trim(),\n            position: String(rawCourse.cdmc || \"\").trim(),\n            day: day,\n            startSection: startSection,\n            endSection: endSection,\n            weeks: weeksArray\n        };\n\n        if (remark) {\n            course.remark = remark;\n        }\n\n        initialCourseList.push(course);\n    }\n\n    // 正方常把同一门课拆成多条记录（连续节次、单双周、重复），先合并去重，\n    // 再按楼栋匹配作息写入自定义时间，最后按星期节次排序。\n    const mergedCourses = mergeAndDistinctCourses(initialCourseList);\n    const finalCourseList = applyCustomTimeToCourses(mergedCourses, isSummerTime);\n    finalCourseList.sort((a, b) =>\n        a.day - b.day ||\n        a.startSection - b.startSection ||\n        a.name.localeCompare(b.name)\n    );\n\n    console.log(`JS: 课程解析完成，原始 ${initialCourseList.length} 条，合并去重后 ${finalCourseList.length} 条。`);\n    return finalCourseList;\n}\n\n/**\n * 检查当前是否处于夏令时作息时间段。\n * @returns true 夏令时 false 冬令时\n *\n * 曾尝试抓取教务处作息时间公告页（https://jwc.ujs.edu.cn/index/xl_zuo_xi_shi_jian.htm），\n * 但跨域（CORS）无法读取，智能选择回退到预设日期。\n * 冬令时是十一假期结束后调整，取 10 月 7 日；夏令时公告历年均为 4 月 7 日起执行。\n */\nfunction whetherSummerTimeSlot() {\n    // 预设日期\n    const summerStart = new Date(new Date().getFullYear(), 3, 7); // 4月7日\n    const winterStart = new Date(new Date().getFullYear(), 9, 7); // 10月7日\n\n    const now = new Date();\n    return now >= summerStart && now < winterStart;\n}\n\n/**\n * 计算本次导入的作息何时失效。\n * 作息时间是导入时一次性写死的，不会自动跟随切令时变化，\n * 所以这里返回下一个「切到另一种令时」的日期，用于提示用户届时重新导入。\n * 夏令时 4 月 7 日起执行，冬令时十一假期后（10 月 7 日）起执行。\n */\nfunction getNextTimeSlotSwitchDate(isSummerTime) {\n    const now = new Date();\n    const year = now.getFullYear();\n    const targetLabel = isSummerTime ? \"冬令时\" : \"夏令时\";\n\n    const candidates = [\n        { date: new Date(year, 3, 7), label: \"夏令时\" },\n        { date: new Date(year, 9, 7), label: \"冬令时\" },\n        { date: new Date(year + 1, 3, 7), label: \"夏令时\" },\n        { date: new Date(year + 1, 9, 7), label: \"冬令时\" }\n    ];\n\n    const next = candidates.find((item) => item.date > now && item.label === targetLabel);\n\n    return {\n        label: next.label,\n        text: `${next.date.getFullYear()}年${next.date.getMonth() + 1}月${next.date.getDate()}日`\n    };\n}\n\n/**\n * 检查是否在登录页面。\n * 校内直连时地址是 http://jwxt.ujs.edu.cn/sso/jziotlogin，\n * 校外经 WebVPN 时地址是 https://webvpn.ujs.edu.cn/http/<hex>/sso/jziotlogin，\n * 因此按路径结尾判断，两种入口都能识别。\n */\nfunction isLoginPage() {\n    return window.location.pathname.endsWith(\"/sso/jziotlogin\");\n}\n\n\nfunction validateYearInput(input) {\n    if (/^[0-9]{4}$/.test(input)) {\n        return false;\n    }\n    return \"请输入四位数字的学年！\";\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\n/**\n * 从教务系统课表查询页读取学年学期选项。\n * 学年：以系统当前选中项为中心，取前 2 年 + 后 2 年，共 5 个选项；\n * 学期：直接取页面全部选项。\n * 读取失败返回 null，由调用方回退到手动输入。\n */\nasync function fetchAcademicOptions() {\n    const url = buildApiUrl(\"/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151\");\n\n    try {\n        const response = await fetch(url, {\n            method: \"GET\",\n            credentials: \"include\"\n        });\n\n        if (!response.ok) return null;\n\n        const doc = new DOMParser().parseFromString(await response.text(), \"text/html\");\n\n        const allYearOptions = arrayFilter(\n            Array.from(doc.querySelectorAll(\"#xnm option\"))\n                .map((opt) => ({\n                    value: opt.value,\n                    text: opt.textContent.trim(),\n                    selected: opt.selected\n                })),\n            (opt) => opt.value !== \"\"\n        );\n\n        const semesterOptions = arrayFilter(\n            Array.from(doc.querySelectorAll(\"#xqm option\"))\n                .map((opt) => ({\n                    value: opt.value,\n                    // 江大返回的文本只有「1」「2」，直接展示不友好，补成「第一学期」这类写法。\n                    text: /^\\d$/.test(opt.textContent.trim())\n                        ? `第${\"一二三四五六七八九十\"[Number(opt.textContent.trim()) - 1] || opt.textContent.trim()}学期`\n                        : opt.textContent.trim(),\n                    selected: opt.selected\n                })),\n            (opt) => opt.value !== \"\"\n        );\n\n        if (allYearOptions.length === 0 || semesterOptions.length === 0) {\n            return null;\n        }\n\n        const selectedIndex = allYearOptions.findIndex((opt) => opt.selected);\n        const start = Math.max(0, selectedIndex === -1 ? 0 : selectedIndex - 2);\n        const end = Math.min(allYearOptions.length, selectedIndex === -1 ? 5 : selectedIndex + 3);\n        const yearOptions = allYearOptions.slice(start, end);\n\n        const defaultSemesterIndex = semesterOptions.findIndex((opt) => opt.selected);\n\n        return {\n            yearOptions,\n            semesterOptions,\n            defaultYearIndex: selectedIndex === -1 ? 0 : selectedIndex - start,\n            defaultSemesterIndex: defaultSemesterIndex === -1 ? 0 : defaultSemesterIndex\n        };\n    } catch (error) {\n        console.warn(\"JS: 读取学年学期选项失败:\", error);\n        return null;\n    }\n}\n\n/**\n * 提示用户选择学年和学期。\n * 优先用教务系统返回的选项（自动默认选中当前学期），\n * 读取失败时回退为手动输入学年 + 固定的两学期选择。\n * @returns {{academicYear: string, semesterCode: string}} 或 null（取消）\n */\nasync function selectAcademicYearAndSemester() {\n    const optionsData = await fetchAcademicOptions();\n\n    if (optionsData) {\n        const { yearOptions, semesterOptions, defaultYearIndex, defaultSemesterIndex } = optionsData;\n\n        const yearIndex = await window.shiguangBridgePromise.showSingleSelection(\n            \"选择学年\",\n            JSON.stringify(yearOptions.map((item) => item.text)),\n            defaultYearIndex\n        );\n        if (yearIndex === null || yearIndex === -1) return null;\n\n        const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n            \"选择学期\",\n            JSON.stringify(semesterOptions.map((item) => item.text)),\n            defaultSemesterIndex\n        );\n        if (semesterIndex === null || semesterIndex === -1) return null;\n\n        return {\n            academicYear: yearOptions[yearIndex].value,\n            semesterCode: semesterOptions[semesterIndex].value\n        };\n    }\n\n    // 回退：手动输入学年。\n    const currentYear = new Date().getFullYear().toString();\n    const currentMonth = new Date().getMonth() + 1; // 月份从0开始，所以加1\n    // 如果当前月份在8月或之后，默认学年是当前年份，否则是上一年份\n    const defaultYear = currentMonth >= 8 ? currentYear : (Number(currentYear) - 1).toString();\n\n    const academicYear = await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\",\n        \"未能从教务系统读取学年学期，请手动输入要导入课程的起始学年（如2025-2026 应该填2025）:\",\n        defaultYear,\n        \"validateYearInput\"\n    );\n    if (academicYear === null) return null;\n\n    const semesters = [\"第一学期\", \"第二学期\"];\n    const defaultSemesterIndex = currentMonth >= 8 ? 0 : 1;\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesters),\n        defaultSemesterIndex\n    );\n    if (semesterIndex === null || semesterIndex === -1) return null;\n\n    return {\n        academicYear,\n        semesterCode: getSemesterCode(semesterIndex)\n    };\n}\n\nasync function selectTimeSlot() {\n    const timeSlots = [\"智能选择\" ,\"夏令时\", \"冬令时\"];\n    const timeSlotIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择作息时间\",\n        JSON.stringify(timeSlots),\n        0\n    );\n    return timeSlotIndex;\n}\n\nasync function reselectTimeSlot(selectedTimeSlot) {\n    const options = [\"对的对的，就是这个\", \"不对不对，应该是另外一个\"];\n    const dialogTitle = \"当前智能选择结果为: \\n  \" + (selectedTimeSlot ? \"夏令时\" : \"冬令时\") + \"\\n是否更改选择？\";\n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        dialogTitle,\n        JSON.stringify(options),\n        0\n    );\n\n    if (selectedIndex === null || selectedIndex === -1) {\n        return false;\n    }\n\n    // 选中第 2 项（索引 1）表示“需要改成另外一个”。\n    return selectedIndex === 1;\n}\n\n/**\n * 将选择索引转换为 API 所需的学期码。\n */\nfunction getSemesterCode(semesterIndex) {\n    // semesterIndex 3 (第一学期), 12 (第二学期)\n    return semesterIndex === 0 ? \"3\" : \"12\";\n}\n\n\n/**\n * 获取指定学年学期的校历周次。\n *\n * 接口按周次顺序返回数组，每个元素代表一周：\n * rq 形如 \"2026-08-31/2026-09-06\"，zs 是周次序号。\n * 第 1 周的起始日（周一）就是 semesterStartDate 需要的开学日期，\n * 数组长度就是教务排的总周数。\n * 与首页日历区块不同，这个接口尊重 xnm/xqm 参数，历史学期同样能取到；\n * 尚未排出校历的学期返回空数组。\n */\nasync function fetchSemesterWeeks(academicYear, semesterCode) {\n    const url = buildApiUrl(\"/kbcx/xskbcxZccx_cxZcByXnxq.html?gnmkdm=N2154\");\n\n    try {\n        const response = await fetch(url, {\n            \"headers\": {\n                \"content-type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            \"body\": `xnm=${academicYear}&xqm=${semesterCode}`,\n            \"method\": \"POST\",\n            \"credentials\": \"include\"\n        });\n\n        if (!response.ok) {\n            throw new Error(`状态码 ${response.status}`);\n        }\n\n        const weekList = JSON.parse(await response.text());\n\n        if (!Array.isArray(weekList) || weekList.length === 0) {\n            console.warn(\"JS: 校历接口未返回周次数据，该学期可能尚未排出校历。\");\n            return null;\n        }\n\n        // 正常情况下数组已按周次排好，仍按 zs 找一次第 1 周，避免顺序变化时取错日期。\n        const firstWeek = weekList.find((item) => Number(item.zs) === 1) || weekList[0];\n\n        // rq 形如 \"2026-08-31/2026-09-06\"，取斜杠前的周一日期；\n        // 部分正方部署改用 zcrq / ksrq 字段，一并兜底。\n        const rqDate = String(firstWeek.rq || \"\").split(\"/\")[0].trim();\n        const fallbackMatch = String(firstWeek.zcrq || firstWeek.ksrq || \"\").match(/(\\d{4}-\\d{2}-\\d{2})/);\n        const startDate = /^\\d{4}-\\d{2}-\\d{2}$/.test(rqDate) ? rqDate : (fallbackMatch ? fallbackMatch[1] : \"\");\n\n        if (!startDate) {\n            console.warn(\"JS: 校历接口返回的日期无法识别:\", firstWeek);\n            return null;\n        }\n\n        const range = { startDate: startDate, totalWeeks: weekList.length };\n        console.log(\"JS: 校历周次:\", range);\n        return range;\n\n    } catch (error) {\n        console.warn(\"JS: 获取校历周次失败:\", error);\n        return null;\n    }\n}\n\n/**\n * 计算课表配置。\n *\n * 应用侧的 saveCourseConfig 是整体覆盖而非字段级合并：没有传入的字段会被写成模型默认值，\n * 其中 semesterStartDate 的默认值是 null，会把用户已经设置好的开学日期清空。\n * 所以拿不到真实开学日期时返回 null，由调用方跳过整个配置保存，宁可不写也不要写坏。\n *\n * defaultClassDuration / defaultBreakDuration 不显式传入，会被重置为应用默认的 45 / 10 分钟，\n * 与江大「45 分钟一节、课间 10 分钟」一致，因此没有副作用。\n */\nfunction buildCourseConfig(semesterRange, firstDayOfWeek) {\n    if (!semesterRange) {\n        return null;\n    }\n\n    return {\n        semesterStartDate: semesterRange.startDate,\n        // 直接采用校历周数。校历含考试周与假期周，比实际上课周多几周，\n        // 但这个值只是课表的周次上限：多几周空白无害，少了会截断课程。\n        semesterTotalWeeks: semesterRange.totalWeeks,\n        firstDayOfWeek: firstDayOfWeek\n    };\n}\n\n\n/**\n * 请求和解析课程数据。\n * 课程请求与校历请求并行执行，课表配置一并算好返回，\n * 由调用方决定是否保存（拿不到开学日期时 config 为 null）。\n */\nasync function fetchAndParseCourses(academicYear, semesterCode, isSummerTime) {\n    window.shiguangBridge.showToast(\"正在请求课表数据...\");\n\n    const xnmXqmBody = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`;\n    const url = buildApiUrl(\"/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151\");\n\n    // 并行获取课程数据和校历周次\n    const [courseResponse, semesterRange] = await Promise.all([\n        fetch(url, {\n            method: \"POST\",\n            headers: {\n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\"\n            },\n            body: xnmXqmBody,\n            credentials: \"include\"\n        }),\n        fetchSemesterWeeks(academicYear, semesterCode)\n    ]);\n\n    try {\n        if (!courseResponse.ok) {\n            throw new Error(`网络请求失败。状态码: ${courseResponse.status} (${courseResponse.statusText})`);\n        }\n\n        let jsonData;\n        try {\n            jsonData = JSON.parse(await courseResponse.text());\n        } catch (e) {\n            console.error('JS: JSON 解析失败，可能是会话过期:', e);\n            window.shiguangBridge.showToast(\"数据返回格式错误，可能是您未成功登录或会话已过期。\");\n            return null;\n        }\n\n        const courses = parseJsonData(jsonData, isSummerTime);\n\n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"未找到任何课程数据，请检查所选学年学期是否正确或本学期无课，或教务系统需要二次登录。\");\n            return null;\n        }\n\n        // 集中实践课（军训、形势与政策等）没有星期和节次，无法排进周课表，单独取出用于提示。\n        const practiceCourses = parsePracticeCourses(jsonData);\n        if (practiceCourses.length > 0) {\n            console.log(`JS: 检测到 ${practiceCourses.length} 门集中实践课，无法自动导入。`);\n        }\n\n        // qsxqj: 教务系统设置的一周起始星期几，缺失时按周一处理。\n        const rawFirstDay = Number(jsonData.qsxqj);\n        const firstDayOfWeek = (rawFirstDay >= 1 && rawFirstDay <= 7) ? rawFirstDay : 1;\n\n        return {\n            courses: courses,\n            practiceCourses: practiceCourses,\n            config: buildCourseConfig(semesterRange, firstDayOfWeek)\n        };\n\n    } catch (error) {\n        window.shiguangBridge.showToast(`请求或解析失败: ${error.message}`);\n        console.error('JS: Fetch/Parse Error:', error);\n        return null;\n    }\n}\n\nasync function saveCourses(parsedCourses) {\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        console.error('JS: Save Courses Error:', error);\n        return false;\n    }\n}\n\n/**\n * 只在能拿到真实开学日期时写入课表配置。\n * 拿不到就完全不调用 saveCourseConfig —— 应用侧是整体覆盖，\n * 传入不含 semesterStartDate 的配置会把用户已设置的开学日期清空。\n */\nasync function saveCourseConfigIfPossible(config) {\n    if (!config) {\n        window.shiguangBridge.showToast(\"未取到本学期开学日期，已跳过课表配置，请在应用内手动设置开学日期。\");\n        console.log(\"JS: 无可用开学日期，跳过 saveCourseConfig 以保留用户现有配置。\");\n        return;\n    }\n\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        window.shiguangBridge.showToast(\n            `课表配置更新成功！开学日期 ${config.semesterStartDate}，总周数 ${config.semesterTotalWeeks} 周。`\n        );\n    } catch (error) {\n        window.shiguangBridge.showToast(`课表配置保存失败: ${error.message}`);\n        console.error('JS: Save Config Error:', error);\n    }\n}\n\n// 上午作息时间\n// 北固及本部主楼、主A楼、生环楼、汽车能动楼、京江楼\nconst AMorningTimeSlots = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:55\", endTime: \"09:40\" },\n    { number: 3, startTime: \"10:00\", endTime: \"10:45\" },\n    { number: 4, startTime: \"10:55\", endTime: \"11:40\" },\n];\n\n// 三江楼、材料楼、机械楼、新校区各教学楼\nconst BMorningTimeSlots = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:55\", endTime: \"09:40\" },\n    { number: 3, startTime: \"10:10\", endTime: \"10:55\" },\n    { number: 4, startTime: \"11:05\", endTime: \"11:50\" },\n];\n\n// 三山楼、讲堂群、实践楼\nconst CMorningTimeSlots = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:55\", endTime: \"09:40\" },\n    { number: 3, startTime: \"10:20\", endTime: \"11:05\" },\n    { number: 4, startTime: \"11:15\", endTime: \"12:00\" },\n];\n\n// 夏令时\n// 下午作息时间\n// 北固\nconst DSummerAfternoonTimeSlots = [\n    { number: 5, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 6, startTime: \"14:55\", endTime: \"15:40\" },\n    { number: 7, startTime: \"15:50\", endTime: \"16:35\" },\n    { number: 8, startTime: \"16:45\", endTime: \"17:30\" },\n];\n\n// 本部\nconst ESummerAfternoonTimeSlots = [\n    { number: 5, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 6, startTime: \"14:55\", endTime: \"15:40\" },\n    { number: 7, startTime: \"16:00\", endTime: \"16:45\" },\n    { number: 8, startTime: \"16:55\", endTime: \"17:40\" },\n];\n\n// 晚上作息时间\nconst SummerEveningTimeSlots = [\n    { number: 9, startTime: \"19:00\", endTime: \"19:45\" },\n    { number: 10, startTime: \"19:55\", endTime: \"20:40\" },\n    { number: 11, startTime: \"20:50\", endTime: \"21:35\" },\n];\n\n// 冬令时\n// 下午作息时间\n// 北固\nconst DWinterAfternoonTimeSlots = [\n    { number: 5, startTime: \"13:30\", endTime: \"14:15\" },\n    { number: 6, startTime: \"14:25\", endTime: \"15:10\" },\n    { number: 7, startTime: \"15:20\", endTime: \"16:05\" },\n    { number: 8, startTime: \"16:15\", endTime: \"17:00\" },\n];\n\n// 本部\nconst EWinterAfternoonTimeSlots = [\n    { number: 5, startTime: \"13:30\", endTime: \"14:15\" },\n    { number: 6, startTime: \"14:25\", endTime: \"15:10\" },\n    { number: 7, startTime: \"15:30\", endTime: \"16:15\" },\n    { number: 8, startTime: \"16:25\", endTime: \"17:10\" },\n];\n\n// 晚上作息时间\nconst WinterEveningTimeSlots = [\n    { number: 9, startTime: \"18:30\", endTime: \"19:15\" },\n    { number: 10, startTime: \"19:25\", endTime: \"20:10\" },\n    { number: 11, startTime: \"20:20\", endTime: \"21:05\" },\n];\n\n// 全局默认作息\n// 夏令时\nconst SummerTimeSlots = [...AMorningTimeSlots, ...ESummerAfternoonTimeSlots, ...SummerEveningTimeSlots];\n\n// 冬令时\nconst WinterTimeSlots = [...AMorningTimeSlots, ...EWinterAfternoonTimeSlots, ...WinterEveningTimeSlots];\n\nfunction getCampusTypeFromPosition(position) {\n    const normalized = String(position || \"\").replace(/\\s+/g, \" \").trim();\n    if (!normalized) return null;\n\n    // api 不再返回「本部」这类校区前缀，北固的返回格式也未确认，只能先这么写：\n    // 带「北固」的按北固校区处理，其余一律按本部处理。\n    const firstPart = normalized.split(\" \")[0] || \"\";\n    if (firstPart.includes(\"北固\") || normalized.includes(\"北固\")) return \"D\";\n    return \"E\";\n}\n\nfunction getMorningTypeFromPosition(position) {\n    const text = String(position || \"\").trim();\n\n    // 教务系统返回的是「京江2号楼2101」「京江3号楼3407」这类名称，没有「京江楼」这个写法，\n    // 所以这里匹配「京江」而不是「京江楼」。\n    if (text.includes(\"主A楼\") || text.includes(\"京江\")) return \"A\";\n    if (text.includes(\"三江楼\")) return \"B\";\n    if (text.includes(\"三山楼\") || text.includes(\"讲堂群\")) return \"C\";\n\n    return null;\n}\n\nfunction buildCourseTimeSlotsByPosition(position, isSummerTime) {\n    const morningType = getMorningTypeFromPosition(position);\n    const campusType = getCampusTypeFromPosition(position);\n\n    // 仅对指定楼宇做自定义。\n    if (!morningType || !campusType) {\n        return null;\n    }\n\n    const morningTimeSlots = morningType === \"A\"\n        ? AMorningTimeSlots\n        : morningType === \"B\"\n            ? BMorningTimeSlots\n            : CMorningTimeSlots;\n\n    const afternoonTimeSlots = isSummerTime\n        ? (campusType === \"D\" ? DSummerAfternoonTimeSlots : ESummerAfternoonTimeSlots)\n        : (campusType === \"D\" ? DWinterAfternoonTimeSlots : EWinterAfternoonTimeSlots);\n\n    const eveningTimeSlots = isSummerTime ? SummerEveningTimeSlots : WinterEveningTimeSlots;\n\n    return [...morningTimeSlots, ...afternoonTimeSlots, ...eveningTimeSlots];\n}\n\nfunction applyCustomTimeToCourses(courses, isSummerTime) {\n    let customizedCount = 0;\n    let skippedCount = 0;\n\n    const updatedCourses = courses.map((course) => {\n        const courseTimeSlots = buildCourseTimeSlotsByPosition(course.position, isSummerTime);\n        if (!courseTimeSlots) {\n            skippedCount += 1;\n            return course;\n        }\n\n        const slotMap = new Map(courseTimeSlots.map((slot) => [slot.number, slot]));\n        const startSlot = slotMap.get(course.startSection);\n        const endSlot = slotMap.get(course.endSection);\n\n        if (!startSlot || !endSlot) {\n            skippedCount += 1;\n            console.warn(`JS: 课程 ${course.name} 的节次(${course.startSection}-${course.endSection})未命中自定义时间映射，回退为普通节次。`);\n            return course;\n        }\n\n        customizedCount += 1;\n        return {\n            ...course,\n            isCustomTime: true,\n            customStartTime: startSlot.startTime,\n            customEndTime: endSlot.endTime,\n        };\n    });\n\n    console.log(`JS: 自定义时间处理完成，命中 ${customizedCount} 门，跳过 ${skippedCount} 门。`);\n    return updatedCourses;\n}\n\n\nasync function importPresetTimeSlots(timeSlots) {\n    if (timeSlots.length === 0) {\n        window.shiguangBridge.showToast(\"警告：时间段为空，未导入时间段信息。\");\n        return;\n    }\n\n    window.shiguangBridge.showToast(`正在导入 ${timeSlots.length} 个预设时间段...`);\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n        console.error('JS: Save Time Slots Error:', error);\n    }\n}\n\n\nasync function runImportFlow() {\n    if (isLoginPage()) {\n        window.shiguangBridge.showToast(\"导入失败：请先登录教务系统！\");\n        console.log(\"JS: 检测到当前在登录页面，终止导入。\");\n        return;\n    }\n\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    const selection = await selectAcademicYearAndSemester();\n    if (selection === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n    const { academicYear, semesterCode } = selection;\n    console.log(`JS: 已选择学年学期: ${academicYear} / ${semesterCode}`);\n\n    const timeSlotIndex = await selectTimeSlot();\n    if (timeSlotIndex === null || timeSlotIndex === -1) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n\n    let isSummerTime;\n    if (timeSlotIndex === 1) {\n        isSummerTime = true;\n    } else if (timeSlotIndex === 2) {\n        isSummerTime = false;\n    } else {\n        isSummerTime = whetherSummerTimeSlot();\n        const shouldReselect = await reselectTimeSlot(isSummerTime);\n        if (shouldReselect) {\n            isSummerTime = !isSummerTime;\n        }\n    }\n    console.log(`JS: 作息类型: ${isSummerTime ? \"夏令时\" : \"冬令时\"}`);\n\n    const result = await fetchAndParseCourses(academicYear, semesterCode, isSummerTime);\n    if (result === null) {\n        console.log(\"JS: 课程获取或解析失败，流程终止。\");\n        return;\n    }\n    const { courses, practiceCourses, config } = result;\n\n    // 作息时间在导入时一次性写入，不会自动跟随切令时变化，需要明确告知用户。\n    // 同时说明只有部分教学楼收录了独立作息，其余楼栋使用默认作息时间。\n    const nextSwitch = getNextTimeSlotSwitchDate(isSummerTime);\n    await window.shiguangBridgePromise.showAlert(\n        \"作息时间提示\",\n        `本次按${isSummerTime ? \"夏令时\" : \"冬令时\"}导入。作息时间在导入时写入，不会自动跟随学校切换令时。\\n` +\n        `${nextSwitch.text}起学校切换为${nextSwitch.label}，届时请重新导入课表，或在应用内手动修改时间段。\\n\\n` +\n        \"脚本已根据课程所在位置匹配作息时间，部分课程可能与预设时间不符。\\n\" +\n        \"请在课表页面核对课程时间，如有错误请手动修改课程所在位置或节次信息。\\n\\n\" +\n        \"已收录独立作息的楼栋：主A楼、京江各号楼、三江楼、三山楼、讲堂群。\\n\" +\n        \"其余楼栋（各学院楼、各实验室、运动场、未排地点等）使用默认作息时间。\\n\\n\" +\n        \"欢迎其他楼栋的同学提供课程时间信息以完善脚本！\",\n        \"我知道了\"\n    );\n\n    if (practiceCourses.length > 0) {\n        const practiceList = practiceCourses\n            .map((item) => {\n                const teacher = item.teacher ? `（${item.teacher}）` : \"\";\n                const weekDesc = item.weekDesc ? ` ${item.weekDesc}` : \"\";\n                return `· ${item.name}${teacher}${weekDesc}`;\n            })\n            .join(\"\\n\");\n\n        console.log(\"JS: 集中实践课列表:\", practiceCourses);\n        await window.shiguangBridgePromise.showAlert(\n            \"集中实践课需手动添加\",\n            `本学期有 ${practiceCourses.length} 门集中实践课，教务系统未给出星期和节次，无法自动导入：\\n\\n` +\n            practiceList +\n            \"\\n\\n请按实际安排在应用内手动添加。\",\n            \"我知道了\"\n        );\n    }\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        console.log(\"JS: 课程保存失败，流程终止。\");\n        return;\n    }\n\n    await saveCourseConfigIfPossible(config);\n\n    await importPresetTimeSlots(isSummerTime ? SummerTimeSlots : WinterTimeSlots);\n\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    console.log(\"JS: 整个导入流程执行完毕并成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();\n","UJS_02":"// 江苏大学(ujs.edu.cn)研究生管理系统 拾光课程表适配脚本\n// 基于正方研究生管理系统(研究生版 Gmis / pyxx)适配\n// 出现问题请联系作者或者提交直接pr更改,这更加快速\n\n// 作者：洛初 Github@gongfuture\n\n// 2026.09.10 第一版\n// 研究生系统没有对外直连入口，需先经统一身份认证（ehall 门户或 http://yjsgll.ujs.edu.cn/pyxx/）登录。\n// 课表从学生课表查询页 pygl/kbcx_xs.aspx 的 DataGrid 里解析：\n// 单元格文本自带「第3-18周 单双周:星期二 上3,4 星期五 上1,2」，星期、节次、周次都能直接取到。\n// 作息时间取自课表页下方的作息表（上午/下午/晚上），由服务端按当前令时渲染，脚本原样导入，\n// 因此不再像本科脚本那样询问夏令时/冬令时，也不做楼栋匹配（研究生系统全校一套作息）。（后续看十一再调整）\n\n// 2026.10.07 第二版\n// 作息改为写入「组合作息方案」（comboSchedule）：夏令时 / 冬令时两套作息按日期区间自动切换，\n// 不再从课表页抓取作息表，也不再需要用户手动选择令时。\n// 夏令时 4/7 起、冬令时 10/7 起，与学校历年切令时公告一致，写死在方案规则里。\n// 研究生全校作息统一（都在研究生楼一带），不存在本科那种按楼栋分叉的作息，\n// 因此可以完全依赖组合作息，课程不再逐条写自定义时间：翻到哪一周，应用就用那一周的日期去匹配规则。\n// 作息数据取自教务处公布的江大作息：上午三江楼(B)一套，下午/晚上本部(E)夏令时与冬令时各一套，两季上午相同。\n// 开学日期：研究生系统没有校历接口，改用「我的课表」接口 App_Ajax/GetkcHandler.ashx 逐周回查，\n// 找到某门课第一次出现的日期，再按（起始周-1）*7+（星期-1）反推开学日期；反推不到则跳过配置保存。\n// 组合作息的日期区间按「本学期起止日期 ∩ 各令时日期区间」生成，保证整个学期被规则完整覆盖；\n// 拿不到开学日期时回退为当年固定的 4/7–10/6、10/7–次年 4/6 两个区间。\n\n/**\n * 数组过滤（原生实现）。\n * 部分教务页面会改写 Array.prototype.filter，这里用普通循环自行实现，不依赖被改写过的数组方法。\n */\nfunction arrayFilter(arr, predicate) {\n    const result = [];\n    for (let i = 0; i < arr.length; i++) {\n        if (predicate(arr[i], i, arr)) {\n            result.push(arr[i]);\n        }\n    }\n    return result;\n}\n\n/**\n * 拼接教务系统接口地址。\n * 校内直连时 location.origin 就是教务域名，前缀为空；\n * 校外经 WebVPN 访问时路径带有 /http/<hex> 前缀，必须保留，否则会变成跨域请求。\n */\nfunction buildApiUrl(path) {\n    const prefixMatch = window.location.pathname.match(/^\\/http\\/[0-9a-f]+/i);\n    const prefix = prefixMatch ? prefixMatch[0] : \"\";\n    return window.location.origin + prefix + path;\n}\n\n/**\n * 当前是否在研究生管理系统内。\n * 校内直连域名是 yjsgll.ujs.edu.cn，校外经 WebVPN 时是 webvpn.ujs.edu.cn/http/<hex>/pyxx/。\n */\nfunction isGraduateSystemPage() {\n    const host = window.location.hostname;\n    if (host.indexOf(\"yjsgll.ujs.edu.cn\") !== -1) return true;\n    return /\\/http\\/[0-9a-f]+\\/pyxx\\//i.test(window.location.pathname);\n}\n\n/**\n * 是否停在登录页。\n * 未登录访问会被重定向到统一身份认证 https://pass.ujs.edu.cn/cas/login?service=.../pyxx/loginCAS.aspx。\n */\nfunction isLoginPage() {\n    const host = window.location.hostname;\n    if (host.indexOf(\"pass.ujs.edu.cn\") !== -1) return true;\n    return window.location.pathname.indexOf(\"/cas/login\") !== -1;\n}\n\n/**\n * 解析周次文本，返回周次数组。\n * 研究生系统的写法是「第3-18周」，也可能出现「第3周」；\n * 单双周标记要先把「单双周」这个词本身剔掉，否则会被误判成单周。\n */\nfunction parseWeeks(weekText) {\n    if (!weekText) return [];\n\n    const cleaned = String(weekText).replace(/单双周/g, \"\");\n    const oddOnly = cleaned.indexOf(\"单\") !== -1;\n    const evenOnly = cleaned.indexOf(\"双\") !== -1;\n\n    const weeks = [];\n    const rangePattern = /(\\d+)\\s*-\\s*(\\d+)\\s*周|(\\d+)\\s*周/g;\n    let match;\n\n    while ((match = rangePattern.exec(cleaned)) !== null) {\n        const start = Number(match[1] || match[3]);\n        const end = match[2] ? Number(match[2]) : start;\n\n        for (let week = start; week <= end; week++) {\n            if (oddOnly && week % 2 === 0) continue;\n            if (evenOnly && week % 2 !== 0) continue;\n            weeks.push(week);\n        }\n    }\n\n    return Array.from(new Set(weeks)).sort((a, b) => a - b);\n}\n\n/**\n * 节次与周次合并去重（参考官方 wiki 课程合并与去重函数）。\n * 课表里同一门课的每个上课时段都会重复一份完整文本，\n * 解析后会得到多条完全相同的记录，这里统一合并/去重。\n */\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || \"\",\n        teacher: c.teacher || \"\",\n        position: c.position || \"\",\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n\n    // 阶段 1：合并连续节次与完全重复记录（前提：名称、教师、地点、星期、周次一致）\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n            a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) ||\n            (a.day || 0) - (b.day || 0) ||\n            a.weeks.join(\",\").localeCompare(b.weeks.join(\",\")) ||\n            (a.startSection || 0) - (b.startSection || 0);\n    });\n\n    const step1Merged = [];\n    let current = list[0];\n\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n\n        const isSameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(\",\") === next.weeks.join(\",\");\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n\n        if (isSameCourseAndWeeks && isContinuous) {\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    // 阶段 2：合并同节次的周次（前提：名称、教师、地点、星期、开始/结束节次一致）\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n            a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) ||\n            (a.day || 0) - (b.day || 0) ||\n            (a.startSection || 0) - (b.startSection || 0) ||\n            (a.endSection || 0) - (b.endSection || 0);\n    });\n\n    const step2Merged = [];\n    let cur = step1Merged[0];\n\n    for (let i = 1; i < step1Merged.length; i++) {\n        const nxt = step1Merged[i];\n\n        const isSameCourseAndSection =\n            cur.name === nxt.name &&\n            cur.teacher === nxt.teacher &&\n            cur.position === nxt.position &&\n            cur.day === nxt.day &&\n            cur.startSection === nxt.startSection &&\n            cur.endSection === nxt.endSection;\n\n        if (isSameCourseAndSection) {\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(cur);\n            cur = nxt;\n        }\n    }\n    step2Merged.push(cur);\n\n    return step2Merged;\n}\n\n/**\n * 取单元格文本。\n * 课表每个格子里是 <br> 分行的文本，DOMParser 解析出来的文档没有 innerText，\n * 先把 <br> 换成换行再取 textContent。\n */\nfunction readCellText(cell) {\n    const clone = cell.cloneNode(true);\n    Array.from(clone.querySelectorAll(\"br\")).forEach(br => br.replaceWith(\"\\n\"));\n    return clone.textContent.replace(/ /g, \" \").replace(/\\r/g, \"\");\n}\n\n/**\n * 把「上3,4」「晚9,10,11」里的节次换算成全天连续节次。\n * 研究生系统文本里的节次就是全天连续编号（晚上从 9 开始），\n * 但个别部署可能写成段内编号（下1,2 / 晚1,2,3），这里两种写法都兼容。\n */\nfunction normalizeSection(periodPrefix, number) {\n    if (periodPrefix === \"下\") return number <= 4 ? number + 4 : number;\n    if (periodPrefix === \"晚\") return number <= 3 ? number + 8 : number;\n    return number;\n}\n\nconst CHINESE_WEEKDAY_MAP = {\n    \"一\": 1, \"二\": 2, \"三\": 3, \"四\": 4, \"五\": 5, \"六\": 6, \"日\": 7, \"天\": 7\n};\n\n/**\n * 解析一个课表单元格的文本。\n * 典型内容：\n *   课程:ESP（专门用途英语）\n *   班级:ESP（专门用途英语）5班理工\n *   (Y206(M)                       )\n *   第3-18周 单双周:星期二 上3,4 星期五 上1,2\n *   主讲教师:史莹娟\n * 一门课在同一格里会列出全部上课时段（上面的例子就是周二 + 周五两段），\n * 所以一个单元格可能产出多条课程记录。\n */\nfunction parseCourseCellText(text) {\n    const lines = String(text).split(\"\\n\").map(line => line.trim()).filter(line => line.length > 0);\n\n    let name = \"\";\n    let className = \"\";\n    let teacher = \"\";\n    let position = \"\";\n    let scheduleLine = \"\";\n\n    for (const line of lines) {\n        if (/^课程[:：]/.test(line)) {\n            name = line.replace(/^课程[:：]\\s*/, \"\").trim();\n            continue;\n        }\n        if (/^班级[:：]/.test(line)) {\n            className = line.replace(/^班级[:：]\\s*/, \"\").trim();\n            continue;\n        }\n        if (/^主讲教师[:：]/.test(line)) {\n            teacher = line.replace(/^主讲教师[:：]\\s*/, \"\").trim();\n            continue;\n        }\n        if (/^[（(].*[)）]$/.test(line)) {\n            // 教室整行被括号包住，去掉最外层括号（教室内名可能自带括号，如 Y206(M)）\n            position = line.replace(/^[（(]/, \"\").replace(/[)）]$/, \"\").trim();\n            continue;\n        }\n        if (line.indexOf(\"周\") !== -1) {\n            scheduleLine = scheduleLine ? `${scheduleLine} ${line}` : line;\n        }\n    }\n\n    // 名称、周次、上课时段是排课必需的，缺一不可\n    if (!name || !scheduleLine) return [];\n\n    const weeks = parseWeeks(scheduleLine);\n    if (weeks.length === 0) return [];\n\n    const sessionPattern = /星期([一二三四五六日天])\\s*([上下晚])\\s*([0-9，,、\\s]+)/g;\n    const records = [];\n    let match;\n\n    while ((match = sessionPattern.exec(scheduleLine)) !== null) {\n        const day = CHINESE_WEEKDAY_MAP[match[1]];\n        if (!day) continue;\n\n        const numbers = arrayFilter(\n            match[3].split(/[^0-9]+/).map(item => Number(item)),\n            (item) => !isNaN(item) && item > 0\n        );\n        if (numbers.length === 0) continue;\n\n        const sections = numbers.map(number => normalizeSection(match[2], number)).sort((a, b) => a - b);\n        const startSection = sections[0];\n        const endSection = sections[sections.length - 1];\n\n        if (startSection < 1 || endSection > 20) continue;\n\n        const remarkParts = [];\n        if (className) remarkParts.push(`班级:${className}`);\n        if (scheduleLine) remarkParts.push(scheduleLine.trim());\n\n        records.push({\n            name: name,\n            teacher: teacher,\n            position: position,\n            day: day,\n            startSection: startSection,\n            endSection: endSection,\n            weeks: weeks,\n            remark: remarkParts.join(\" | \")\n        });\n    }\n\n    return records;\n}\n\n/**\n * 解析课表页 #MainWork_DataGrid1 里的全部课程。\n * 每个单元格自带完整文本（含星期、节次、周次），不必按表格行列还原，\n * 重复出现的记录交给 mergeAndDistinctCourses 去重。\n */\nfunction parseCoursesFromGrid(doc) {\n    const grid = doc.querySelector(\"#MainWork_DataGrid1\");\n    if (!grid) return [];\n\n    const courses = [];\n    for (const cell of Array.from(grid.querySelectorAll(\"td\"))) {\n        const text = readCellText(cell);\n        if (text.indexOf(\"课程\") === -1) continue;\n        courses.push(...parseCourseCellText(text));\n    }\n\n    return mergeAndDistinctCourses(courses);\n}\n\n/**\n * 研究生楼作息时间（江苏大学教务处公布的作息，两季对比如下）。\n *\n * 上午一年四季不变，与本科三江楼(B)那套一致；\n * 下午/晚上分夏令时与冬令时两套，与本科本部(E)那套一致：\n *   夏令时：下午 14:00 开始，晚上 19:00 开始；\n *   冬令时：下午 13:30 开始，晚上 18:30 开始。\n *\n * 节次是全天连续编号（上午 1-4、下午 5-8、晚上 9-11），与课表文本里的「上3,4」「晚9,10,11」一致。\n */\nconst MorningTimeSlots = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:55\", endTime: \"09:40\" },\n    { number: 3, startTime: \"10:10\", endTime: \"10:55\" },\n    { number: 4, startTime: \"11:05\", endTime: \"11:50\" }\n];\n\n// 夏令时 下午\nconst SummerAfternoonTimeSlots = [\n    { number: 5, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 6, startTime: \"14:55\", endTime: \"15:40\" },\n    { number: 7, startTime: \"16:00\", endTime: \"16:45\" },\n    { number: 8, startTime: \"16:55\", endTime: \"17:40\" }\n];\n\n// 夏令时 晚上\nconst SummerEveningTimeSlots = [\n    { number: 9, startTime: \"19:00\", endTime: \"19:45\" },\n    { number: 10, startTime: \"19:55\", endTime: \"20:40\" },\n    { number: 11, startTime: \"20:50\", endTime: \"21:35\" }\n];\n\n// 冬令时 下午\nconst WinterAfternoonTimeSlots = [\n    { number: 5, startTime: \"13:30\", endTime: \"14:15\" },\n    { number: 6, startTime: \"14:25\", endTime: \"15:10\" },\n    { number: 7, startTime: \"15:30\", endTime: \"16:15\" },\n    { number: 8, startTime: \"16:25\", endTime: \"17:10\" }\n];\n\n// 冬令时 晚上\nconst WinterEveningTimeSlots = [\n    { number: 9, startTime: \"18:30\", endTime: \"19:15\" },\n    { number: 10, startTime: \"19:25\", endTime: \"20:10\" },\n    { number: 11, startTime: \"20:20\", endTime: \"21:05\" }\n];\n\n// 两季各一套完整作息（上午、下午、晚上依次顺延，共 11 节）\nconst SummerTimeSlots = [...MorningTimeSlots, ...SummerAfternoonTimeSlots, ...SummerEveningTimeSlots];\nconst WinterTimeSlots = [...MorningTimeSlots, ...WinterAfternoonTimeSlots, ...WinterEveningTimeSlots];\n\n/**\n * 组合作息方案名称。\n */\nconst COMBO_SCHEDULE_NAME = \"江苏大学研究生作息（夏令时 / 冬令时自动切换）\";\n\n/**\n * 判断当前是否处于夏令时作息。\n * 学校历年都是 4 月 7 日起执行夏令时、10 月 7 日起执行冬令时（十一假期结束后切回）。\n * 这里只用于决定「基础时间段」写入哪一套，真正生效的时间由组合作息按日期决定。\n */\nfunction isSummerTimeNow() {\n    const now = new Date();\n    const summerStart = new Date(now.getFullYear(), 3, 7); // 4月7日\n    const winterStart = new Date(now.getFullYear(), 9, 7); // 10月7日\n    return now >= summerStart && now < winterStart;\n}\n\n/**\n * 把日期字符串（\"YYYY-MM-DD\"）加减天数，返回同样格式的字符串。\n */\nfunction shiftDate(dateStr, days) {\n    const date = new Date(`${dateStr}T00:00:00`);\n    date.setDate(date.getDate() + days);\n    return formatDate(date);\n}\n\n/**\n * 构造组合作息方案（comboSchedule）。\n *\n * 规则按日期区间匹配：夏令时 4/7–10/6，冬令时 10/7–次年 4/6。\n * 两者首尾相接，全年任意一天都能命中一条，不存在空档。\n *\n * 一个学期可能横跨两套令时区间，也可能跨年：\n *   秋季学期（9 月开学、次年 1 月结束）：当年夏令时尾巴 + 当年冬令时；\n *   春季学期（2 月开学、7 月结束）：上一年冬令时尾巴 + 当年夏令时。\n * 所以这里不假设\"学期属于某一年\"，而是把学期覆盖到的每一年都生成一对区间，\n * 再逐个与学期区间求交集，命中的才写进方案——这样任何学期都能被完整覆盖。\n *\n * 拿到开学日期时，方案只覆盖本学期，避免与其它学期的作息方案互相干扰；\n * 拿不到开学日期时退回全年固定的两个区间（以导入当天的\"夏令时年份\"为基准）。\n *\n * @param {string|null} semesterStartDate 本学期开学日期 \"YYYY-MM-DD\"，取不到传 null\n * @param {number} totalWeeks 本学期总周数\n */\nfunction buildComboSchedule(semesterStartDate, totalWeeks) {\n    // 本学期日期区间（含最后一周的最后一天）\n    const semesterEnd = semesterStartDate\n        ? shiftDate(semesterStartDate, Math.max(1, totalWeeks) * 7 - 1)\n        : null;\n\n    /**\n     * 求「本学期」与「某个令时区间」的交集，无交集返回 null。\n     */\n    const intersect = (seasonStart, seasonEnd) => {\n        if (!semesterStartDate || !semesterEnd) return null;\n        const start = semesterStartDate > seasonStart ? semesterStartDate : seasonStart;\n        const end = semesterEnd < seasonEnd ? semesterEnd : seasonEnd;\n        return start <= end ? { startDate: start, endDate: end } : null;\n    };\n\n    // 学期覆盖到的年份范围：往前多取一年，兜住\"1 月结束的秋季学期\"和\"2 月开学的春季学期\"\n    const now = new Date();\n    const month = now.getMonth() + 1;\n    const fallbackSummerYear = (month >= 8 || month < 4) ? now.getFullYear() : now.getFullYear() - 1;\n    const firstYear = semesterStartDate\n        ? Number(semesterStartDate.slice(0, 4))\n        : fallbackSummerYear;\n    const lastYear = semesterEnd ? Number(semesterEnd.slice(0, 4)) : firstYear;\n\n    const publicSchedules = [];\n\n    for (let year = firstYear - 1; year <= lastYear; year++) {\n        // 该年度的夏令时：year/4/7 – year/10/6；冬令时：year/10/7 – (year+1)/4/6\n        const summerRange = intersect(`${year}-04-07`, `${year}-10-06`);\n        if (summerRange) {\n            publicSchedules.push({\n                name: \"夏令时\",\n                startDate: summerRange.startDate,\n                endDate: summerRange.endDate,\n                defaultClassDuration: 45,\n                defaultBreakDuration: 10,\n                timeSlots: SummerTimeSlots\n            });\n        }\n\n        const winterRange = intersect(`${year}-10-07`, `${year + 1}-04-06`);\n        if (winterRange) {\n            publicSchedules.push({\n                name: \"冬令时\",\n                startDate: winterRange.startDate,\n                endDate: winterRange.endDate,\n                defaultClassDuration: 45,\n                defaultBreakDuration: 10,\n                timeSlots: WinterTimeSlots\n            });\n        }\n    }\n\n    // 拿不到开学日期，或学期与所有令时区间都没有交集（例如纯夏季小学期）时，退回全年固定区间\n    if (publicSchedules.length === 0) {\n        publicSchedules.push({\n            name: \"夏令时\",\n            startDate: `${fallbackSummerYear}-04-07`,\n            endDate: `${fallbackSummerYear}-10-06`,\n            defaultClassDuration: 45,\n            defaultBreakDuration: 10,\n            timeSlots: SummerTimeSlots\n        });\n        publicSchedules.push({\n            name: \"冬令时\",\n            startDate: `${fallbackSummerYear}-10-07`,\n            endDate: `${fallbackSummerYear + 1}-04-06`,\n            defaultClassDuration: 45,\n            defaultBreakDuration: 10,\n            timeSlots: WinterTimeSlots\n        });\n    }\n\n    // 按开始日期排序，保证规则顺序与时间顺序一致（应用取第一条命中的规则）\n    publicSchedules.sort((a, b) => a.startDate.localeCompare(b.startDate));\n\n    return {\n        name: COMBO_SCHEDULE_NAME,\n        publicSchedules: publicSchedules\n    };\n}\n\n/**\n * 读取下拉框当前选中项的值。\n * DOMParser 解析出的文档不一定支持 select.value，这里按 selected 属性自行判断。\n */\nfunction getSelectedOptionValue(select) {\n    if (!select || !select.options || select.options.length === 0) return \"\";\n\n    for (const option of Array.from(select.options)) {\n        if (option.hasAttribute(\"selected\")) return option.value;\n    }\n    return select.options[0].value;\n}\n\n/**\n * 收集表单里可提交的字段，模拟一次完整回发。\n * ASP.NET 的 __VIEWSTATE 等方法不能少，逐个手写容易漏，这里整体搬运后按需覆盖。\n */\nfunction collectPostbackFields(doc, overrides) {\n    const params = new URLSearchParams();\n    const form = doc.querySelector(\"#form1\") || doc.querySelector(\"form\");\n    if (!form) return params;\n\n    for (const el of Array.from(form.querySelectorAll(\"input[name], select[name], textarea[name]\"))) {\n        const tag = el.tagName.toLowerCase();\n        const name = el.getAttribute(\"name\");\n        if (!name) continue;\n\n        if (tag === \"select\") {\n            params.set(name, getSelectedOptionValue(el));\n            continue;\n        }\n\n        const type = (el.getAttribute(\"type\") || \"text\").toLowerCase();\n        if (type === \"submit\" || type === \"image\" || type === \"button\" || type === \"reset\") {\n            // 图片按钮/提交按钮需要 .x / .y，或者完全不提交，这里跳过由调用方补充\n            continue;\n        }\n        if (type === \"checkbox\" || type === \"radio\") {\n            if (!el.hasAttribute(\"checked\")) continue;\n        }\n\n        params.set(name, el.getAttribute(\"value\") || \"\");\n    }\n\n    Object.keys(overrides || {}).forEach(key => params.set(key, overrides[key]));\n    return params;\n}\n\n/**\n * 以 form 表单方式回发并返回响应 HTML。\n */\nasync function postForm(url, params) {\n    const response = await fetch(url, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\" },\n        body: params.toString(),\n        credentials: \"include\"\n    });\n\n    if (!response.ok) {\n        throw new Error(`回发失败，状态码 ${response.status}`);\n    }\n    return await response.text();\n}\n\n/**\n * 读取指定学期的课表页文档。\n * 课表页默认渲染系统当前学期；要查历史/其它学期得按页面自身的逻辑回发两次：\n * 先把学期下拉框回发一次（换出新的 __VIEWSTATE），再点一次「查询」按钮重新绑定课表。\n * @param {string} semesterValue 学期下拉框的 value，为空表示用默认（当前）学期\n */\nasync function fetchTimetableDocument(semesterValue) {\n    const url = buildApiUrl(\"/pyxx/pygl/kbcx_xs.aspx\");\n\n    const pageResponse = await fetch(url, { method: \"GET\", credentials: \"include\" });\n    const pageDoc = new DOMParser().parseFromString(await pageResponse.text(), \"text/html\");\n\n    const semesterSelect = pageDoc.querySelector(\"#MainWork_drpxq\");\n    if (!semesterSelect) {\n        throw new Error(\"NOT_LOGGED_IN\");\n    }\n\n    const currentValue = getSelectedOptionValue(semesterSelect);\n    if (!semesterValue || semesterValue === currentValue) {\n        return pageDoc;\n    }\n\n    // 第一步：学期下拉框回发，拿到与新选中项对应的 __VIEWSTATE\n    const firstParams = collectPostbackFields(pageDoc, {\n        \"__EVENTTARGET\": \"ctl00$MainWork$drpxq\",\n        \"__EVENTARGUMENT\": \"\",\n        \"ctl00$MainWork$drpxq\": semesterValue\n    });\n    const afterChangeDoc = new DOMParser().parseFromString(await postForm(url, firstParams), \"text/html\");\n\n    // 第二步：点「查询」按钮，课表才按新学期的选项重新绑定\n    const secondParams = collectPostbackFields(afterChangeDoc, {\n        \"__EVENTTARGET\": \"\",\n        \"__EVENTARGUMENT\": \"\",\n        \"ctl00$MainWork$drpxq\": semesterValue,\n        \"ctl00$MainWork$btnSearch.x\": \"5\",\n        \"ctl00$MainWork$btnSearch.y\": \"5\"\n    });\n    const resultDoc = new DOMParser().parseFromString(await postForm(url, secondParams), \"text/html\");\n\n    if (!resultDoc.querySelector(\"#MainWork_DataGrid1\")) {\n        throw new Error(\"POSTBACK_FAILED\");\n    }\n    return resultDoc;\n}\n\n/**\n * 读取学期下拉框的全部选项。\n */\nfunction readSemesterOptions(doc) {\n    const select = doc.querySelector(\"#MainWork_drpxq\");\n    if (!select) return null;\n\n    const options = Array.from(select.options)\n        .map(option => ({\n            value: option.value,\n            text: option.textContent.trim(),\n            selected: option.hasAttribute(\"selected\")\n        }))\n        .filter(option => option.text);\n\n    if (options.length === 0) return null;\n\n    let defaultIndex = options.findIndex(option => option.selected);\n    if (defaultIndex === -1) defaultIndex = 0;\n\n    return { options: options, defaultIndex: defaultIndex };\n}\n\nfunction formatDate(date) {\n    const pad = (value) => String(value).padStart(2, \"0\");\n    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;\n}\n\nfunction addDays(date, days) {\n    const result = new Date(date.getFullYear(), date.getMonth(), date.getDate());\n    result.setDate(result.getDate() + days);\n    return result;\n}\n\n/**\n * 查询某天「我的课表」接口，判断目标课程当天是否上课。\n * App_Ajax/GetkcHandler.ashx 是首页「我的课表」按日期查询用的接口，\n * 传入日期就返回当天课程，可以用来反推开学日期。\n */\nasync function hasCourseOn(date, courseName, studentId) {\n    const url = buildApiUrl(\n        `/pyxx/App_Ajax/GetkcHandler.ashx?kcdate=${formatDate(date)}&xh=${encodeURIComponent(studentId)}`\n    );\n\n    const response = await fetch(url, { method: \"GET\", credentials: \"include\" });\n    if (!response.ok) return false;\n\n    const doc = new DOMParser().parseFromString(await response.text(), \"text/html\");\n    const text = (doc.body ? doc.body.textContent : \"\").replace(/\\s+/g, \"\");\n    return text.indexOf(String(courseName).replace(/\\s+/g, \"\")) !== -1;\n}\n\n/**\n * 找到参照日期：距离今天最近的一个「目标星期」的日期（今天或之前）。\n * 星期编号 1-7 对应周一到周日。\n */\nfunction findReferenceDate(day) {\n    const today = new Date();\n    const jsDay = today.getDay(); // 0=周日\n    const todayDay = jsDay === 0 ? 7 : jsDay;\n    let diff = todayDay - day;\n    if (diff < 0) diff += 7;\n    return addDays(today, -diff);\n}\n\n/**\n * 挑选用于探测的课程：起始周最早、周次跨度最短的那门，\n * 跨度短意味着要核对的周次少。\n */\nfunction pickProbeCourse(courses) {\n    let best = null;\n\n    for (const course of courses) {\n        if (!course.weeks || course.weeks.length === 0) continue;\n\n        const weeks = course.weeks;\n        const span = weeks[weeks.length - 1] - weeks[0];\n\n        if (!best ||\n            weeks[0] < best.weeks[0] ||\n            (weeks[0] === best.weeks[0] && span < best.span)) {\n            best = { name: course.name, day: course.day, weeks: weeks, span: span };\n        }\n    }\n\n    return best;\n}\n\n/**\n * 反推本学期开学日期。\n *\n * 研究生系统没有校历接口，只能借「我的课表」接口逐周回查：\n * 以目标课程所在星期的最近一个日期为参照，按周展开探测（区间大约覆盖前后一个学期），\n * 再把每个命中日期当作「该课第一次上课的那天」，用课程自己的周次表去核对：\n * 前一周必须没课，且课程周次表里的每一周都应当对得上。\n * 核对通过后，开学日期 = 首次上课日期 - ((起始周 - 1) * 7 + (星期 - 1))，按周一为一周之始。\n *\n * 校验通过多个候选时取离今天最近的那个，避免把上一学年的同名课程认成本学期。\n * 任何一步拿不到结果就返回 null，由调用方跳过配置保存。\n */\nasync function deriveSemesterStartDate(courses, studentId) {\n    if (!studentId) {\n        console.warn(\"JS: 未取到学号，跳过开学日期推算。\");\n        return null;\n    }\n\n    const target = pickProbeCourse(courses);\n    if (!target) {\n        console.warn(\"JS: 没有可用于探测的课程，跳过开学日期推算。\");\n        return null;\n    }\n\n    const reference = findReferenceDate(target.day);\n    const maxBackWeeks = 40;\n    const maxForwardWeeks = 12;\n\n    const offsets = [0];\n    for (let week = 1; week <= maxBackWeeks; week++) {\n        offsets.push(-week);\n        if (week <= maxForwardWeeks) offsets.push(week);\n    }\n\n    const observed = new Map();\n    const batchSize = 2;\n    let hitBatchIndex = -1;\n\n    for (let index = 0; index < offsets.length; index += batchSize) {\n        const batch = offsets.slice(index, index + batchSize);\n        const results = await Promise.all(\n            batch.map(async offset => ({\n                offset: offset,\n                hit: await hasCourseOn(addDays(reference, offset * 7), target.name, studentId)\n            }))\n        );\n\n        for (const item of results) {\n            observed.set(item.offset, item.hit);\n        }\n\n        if (hitBatchIndex === -1 && results.some(item => item.hit)) {\n            hitBatchIndex = index / batchSize;\n        }\n        // 找到命中后再多探一批，够核对课程周次就够了，不必把整个区间探完\n        if (hitBatchIndex !== -1 && index / batchSize > hitBatchIndex) {\n            break;\n        }\n\n        // 稍作等待防止风控\n        const delay = 300 + Math.floor(Math.random() * 200);\n        await new Promise(resolve => setTimeout(resolve, delay));\n    }\n\n    const hitOffsets = Array.from(observed.keys())\n        .filter(offset => observed.get(offset))\n        .sort((a, b) => Math.abs(a) - Math.abs(b) || a - b);\n\n    if (hitOffsets.length === 0) {\n        console.warn(`JS: 前后约一个学期内未探到课程「${target.name}」，跳过开学日期推算。`);\n        return null;\n    }\n\n    const firstWeek = target.weeks[0];\n    // 单双周课程每隔一周才上课，用课程自己的周次间隔做「上一次课」的核对距离，\n    // 否则会把「课程中途的某一次课」误判成起始周（相邻一周本来就该没课）。\n    const weekStep = target.weeks.length > 1 ? target.weeks[1] - target.weeks[0] : 1;\n\n    for (const candidate of hitOffsets) {\n        // 起始周之前的那一次课必须没有课，否则这个候选只是课程中途的一次课\n        if (observed.get(candidate - weekStep) === true) continue;\n\n        // 用课程自己的周次表核对：课程上课的每一周都应探到课\n        let consistent = true;\n        let checked = 0;\n\n        for (const week of target.weeks) {\n            const offset = candidate + (week - firstWeek);\n            const seen = observed.get(offset);\n            if (seen === undefined) continue;\n\n            checked += 1;\n            if (!seen) {\n                consistent = false;\n                break;\n            }\n        }\n\n        if (!consistent || checked < 1) continue;\n\n        const firstClassDate = addDays(reference, candidate * 7);\n        const startDate = addDays(firstClassDate, -((firstWeek - 1) * 7 + (target.day - 1)));\n\n        // 推算出的开学日期必须是周一，否则说明数据对不上，宁可不写\n        if (startDate.getDay() !== 1) continue;\n\n        console.log(`JS: 探测课程「${target.name}」首次上课日期 ${formatDate(firstClassDate)}（第 ${firstWeek} 周），推算开学日期 ${formatDate(startDate)}。`);\n        return formatDate(startDate);\n    }\n\n    console.warn(`JS: 课程「${target.name}」的探测结果与周次表对不上，跳过开学日期推算。`);\n    return null;\n}\n\n/**\n * 计算本学期总周数：取所有课程周次的最大值。\n * 研究生系统没有校历，这个值只是课表的周次上限，多算几周无空白无妨，少算会截断课程。\n */\nfunction calculateTotalWeeks(courses) {\n    let maxWeek = 0;\n    for (const course of courses) {\n        for (const week of course.weeks) {\n            if (week > maxWeek) maxWeek = week;\n        }\n    }\n    return maxWeek;\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"研究生系统课表导入\",\n        \"导入前请确保您已在浏览器中登录江苏大学研究生管理系统（可从综合服务门户点「研究生管理系统」进入，或直接访问 http://yjsgll.ujs.edu.cn/pyxx/）。\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function saveCourses(parsedCourses) {\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        console.error(\"JS: Save Courses Error:\", error);\n        return false;\n    }\n}\n\n/**\n * 只在能拿到真实开学日期时写入课表配置。\n * 应用侧的 saveCourseConfig 是整体覆盖而非字段级合并：没有传入的字段会被写成模型默认值，\n * 其中 semesterStartDate 的默认值是 null，会把用户已经设置好的开学日期清空。\n * 所以拿不到开学日期时返回 null，宁可不写也不要写坏。\n */\nasync function saveCourseConfigIfPossible(config) {\n    if (!config) {\n        window.shiguangBridge.showToast(\"未取到本学期开学日期，已跳过课表配置，请在应用内手动设置开学日期。\");\n        console.log(\"JS: 无可用开学日期，跳过 saveCourseConfig 以保留用户现有配置。\");\n        return;\n    }\n\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        window.shiguangBridge.showToast(\n            `课表配置更新成功！开学日期 ${config.semesterStartDate}，总周数 ${config.semesterTotalWeeks} 周。`\n        );\n    } catch (error) {\n        window.shiguangBridge.showToast(`课表配置保存失败: ${error.message}`);\n        console.error(\"JS: Save Config Error:\", error);\n    }\n}\n\n/**\n * 提交基础时间段（组合作息的骨架）。\n * 必须成功，否则后面的 saveComboSchedule 会被应用直接拒绝（顺序强校验）。\n */\nasync function importPresetTimeSlots(timeSlots) {\n    if (timeSlots.length === 0) {\n        window.shiguangBridge.showToast(\"警告：时间段为空，未导入时间段信息。\");\n        return false;\n    }\n\n    window.shiguangBridge.showToast(`正在导入 ${timeSlots.length} 个预设时间段...`);\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n        console.error(\"JS: Save Time Slots Error:\", error);\n        return false;\n    }\n}\n\n/**\n * 提交组合作息方案：夏令时 / 冬令时按日期区间自动切换。\n * 应用会以 importPresetTimeSlots 提交的基础时间段为骨架做差量合并，\n * 本方案每个模板都提交完整 1-11 节，所以合并结果与模板本身一致。\n * 调用后本次导入任务不再允许调用 savePresetTimeSlots，因此顺序必须固定为「先时间段、后方案」。\n */\nasync function importComboSchedule(comboSchedule) {\n    window.shiguangBridge.showToast(\"正在导入夏令时/冬令时组合作息方案...\");\n    try {\n        await window.shiguangBridgePromise.saveComboSchedule(JSON.stringify(comboSchedule));\n        console.log(\"JS: 组合作息方案已导入:\", comboSchedule);\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入作息方案失败: \" + error.message);\n        console.error(\"JS: Save Combo Schedule Error:\", error);\n        return false;\n    }\n}\n\nasync function runImportFlow() {\n    if (!isGraduateSystemPage()) {\n        window.shiguangBridge.showToast(\"导入失败：请先进入江苏大学研究生管理系统！\");\n        console.log(\"JS: 当前不在研究生管理系统页面，终止导入。\");\n        return;\n    }\n\n    if (isLoginPage()) {\n        window.shiguangBridge.showToast(\"导入失败：请先登录研究生管理系统！\");\n        console.log(\"JS: 检测到当前在登录页面，终止导入。\");\n        return;\n    }\n\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    window.shiguangBridge.showToast(\"正在读取课表数据...\");\n\n    // 先取一次默认（当前）学期，用于学期列表与课表\n    let defaultDoc;\n    try {\n        defaultDoc = await fetchTimetableDocument(\"\");\n    } catch (error) {\n        if (error.message === \"NOT_LOGGED_IN\") {\n            window.shiguangBridge.showToast(\"未登录或登录已过期，请先登录研究生管理系统。\");\n        } else {\n            window.shiguangBridge.showToast(`读取课表失败: ${error.message}`);\n        }\n        console.error(\"JS: 读取课表页失败:\", error);\n        return;\n    }\n\n    const semesterData = readSemesterOptions(defaultDoc);\n    if (!semesterData) {\n        window.shiguangBridge.showToast(\"未能读取学期列表，请确认已登录并停留在研究生管理系统。\");\n        return;\n    }\n\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesterData.options.map(item => item.text)),\n        semesterData.defaultIndex\n    );\n    if (semesterIndex === null || semesterIndex === -1) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n\n    const semesterValue = semesterData.options[semesterIndex].value;\n    const semesterText = semesterData.options[semesterIndex].text;\n\n    let timetableDoc = defaultDoc;\n    if (semesterIndex !== semesterData.defaultIndex) {\n        window.shiguangBridge.showToast(`正在切换到 ${semesterText} ...`);\n        try {\n            timetableDoc = await fetchTimetableDocument(semesterValue);\n        } catch (error) {\n            window.shiguangBridge.showToast(`切换学期失败: ${error.message}`);\n            console.error(\"JS: 切换学期失败:\", error);\n            return;\n        }\n    }\n\n    const courses = parseCoursesFromGrid(timetableDoc);\n    if (courses.length === 0) {\n        window.shiguangBridge.showToast(`${semesterText} 未找到任何课程，请确认所选学期是否正确。`);\n        console.log(\"JS: 课表为空，终止导入。\");\n        return;\n    }\n\n    console.log(`JS: 解析到 ${courses.length} 门课程。`);\n\n    // 学号取自课表页隐藏域，用来查「我的课表」接口\n    const studentId = (timetableDoc.querySelector(\"#MainWork_WUCpyjhdy_HFfilename\") || {}).value || \"\";\n\n    window.shiguangBridge.showToast(\"正在推算开学日期...\");\n    const semesterStartDate = await deriveSemesterStartDate(courses, studentId);\n\n    const totalWeeks = calculateTotalWeeks(courses);\n    const config = semesterStartDate\n        ? {\n            semesterStartDate: semesterStartDate,\n            semesterTotalWeeks: totalWeeks,\n            firstDayOfWeek: 1\n        }\n        : null;\n\n    // 基础时间段（骨架）用导入当下的令时那一套；方案里两个模板都会提交完整 11 节，\n    // 骨架实际只是用来满足「先时间段、后方案」的顺序要求，不会影响最终显示。\n    const baseTimeSlots = isSummerTimeNow() ? SummerTimeSlots : WinterTimeSlots;\n    const comboSchedule = buildComboSchedule(semesterStartDate, totalWeeks);\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        console.log(\"JS: 课程保存失败，流程终止。\");\n        return;\n    }\n\n    await saveCourseConfigIfPossible(config);\n\n    // 顺序不可调换：saveComboSchedule 依赖 savePresetTimeSlots 成功写入的基础时间段。\n    const timeSlotSaved = await importPresetTimeSlots(baseTimeSlots);\n    if (timeSlotSaved) {\n        await importComboSchedule(comboSchedule);\n    } else {\n        window.shiguangBridge.showToast(\"时间段导入失败，已跳过组合作息方案。\");\n        console.log(\"JS: 基础时间段未写入成功，跳过 saveComboSchedule。\");\n    }\n\n    const scheduleBrief = comboSchedule.publicSchedules\n        .map((rule) => `${rule.name} ${rule.startDate} ~ ${rule.endDate}`)\n        .join(\"\\n\");\n\n    await window.shiguangBridgePromise.showAlert(\n        \"导入完成\",\n        `已导入 ${semesterText} 共 ${courses.length} 门课程。\\n\\n` +\n        `作息已写入组合作息方案（全天 ${baseTimeSlots.length} 节），将于每年 4 月 7 日切换到夏令时、` +\n        \"10 月 7 日切换到冬令时，无需重新导入。\\n\\n\" +\n        `本次方案的生效区间：\\n${scheduleBrief}\\n\\n` +\n        (semesterStartDate\n            ? `开学日期由课表数据反推得到：${semesterStartDate}，请在应用内核对。`\n            : \"未能反推开学日期（作息方案已退回全年固定区间），请在应用内手动设置开学日期。\"),\n        \"我知道了\"\n    );\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    console.log(\"JS: 整个导入流程执行完毕并成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();\n","JSNU_01":"/**\n * 解析强智系统的周次字符串\n */\nfunction parseWeeks(weekStr) {\n    let weeks = [];\n    let parts = weekStr.split(',');\n    for (let part of parts) {\n        if (part.includes('-')) {\n            let [start, end] = part.split('-');\n            for (let i = parseInt(start); i <= parseInt(end); i++) {\n                if (!weeks.includes(i)) weeks.push(i);\n            }\n        } else {\n            let w = parseInt(part);\n            if (!isNaN(w) && !weeks.includes(w)) weeks.push(w);\n        }\n    }\n    return weeks.sort((a, b) => a - b);\n}\n\n/**\n * 提取课程数据\n */\nfunction extractCoursesFromDoc(doc) {\n    let parsedCourses = [];\n    const table = doc.getElementById('timetable');\n    if (!table) throw new Error(\"请求成功但未找到课表表格，请确认教务系统状态。\");\n\n    const rows = table.getElementsByTagName('tr');\n    // 跳过表头(0)和尾部的备注行\n    for (let i = 1; i < rows.length - 1; i++) {\n        const cells = rows[i].getElementsByTagName('td');\n        for (let j = 0; j < cells.length; j++) {\n            const dayOfWeek = j + 1; \n            const cell = cells[j];\n            \n            const detailDivs = cell.querySelectorAll('div.kbcontent');\n            if (detailDivs.length === 0) continue;\n\n            detailDivs.forEach(div => {\n                let htmlContent = div.innerHTML;\n                if (!htmlContent.trim() || htmlContent === '&nbsp;') return;\n\n                // 强智同一个时间段如果有多门课，用连续破折号分隔\n                let courseBlocks = htmlContent.split(/-{10,}\\s*<br\\s*\\/?>/i);\n\n                courseBlocks.forEach(block => {\n                    if (!block.trim()) return;\n\n                    let tempDiv = document.createElement('div');\n                    tempDiv.innerHTML = block;\n\n                    let courseObj = {\n                        day: dayOfWeek,\n                        isCustomTime: false\n                    };\n\n                    // 1. 提取课程名 (移除二维码 div 后，取第一行纯文本)\n                    let itemBoxes = tempDiv.querySelectorAll('.item-box');\n                    itemBoxes.forEach(box => box.remove());\n                    \n                    let lines = tempDiv.innerHTML.split(/<br\\s*\\/?>/i);\n                    for (let line of lines) {\n                        let cleanLine = line.replace(/<[^>]+>/g, '').trim();\n                        if (cleanLine && cleanLine !== \"\") {\n                            courseObj.name = cleanLine;\n                            break;\n                        }\n                    }\n\n                    // 2. 提取教师\n                    let teacherFont = tempDiv.querySelector('font[title=\"教师\"]');\n                    courseObj.teacher = teacherFont ? teacherFont.innerText.trim() : \"未知\";\n\n                    // 3. 提取教室\n                    let positionFont = tempDiv.querySelector('font[title=\"教室\"]');\n                    courseObj.position = positionFont ? positionFont.innerText.trim() : \"待定\";\n\n                    // 4. 提取周次和节次\n                    let timeFont = tempDiv.querySelector('font[title=\"周次(节次)\"]');\n                    if (timeFont) {\n                        let timeText = timeFont.innerText.trim();\n                        let timeMatch = timeText.match(/(.+?)\\(周\\)(?:\\[([\\d-]+)节\\])?/);\n                        if (timeMatch) {\n                            courseObj.weeks = parseWeeks(timeMatch[1]);\n                            if (timeMatch[2]) {\n                                let secParts = timeMatch[2].split('-');\n                                courseObj.startSection = parseInt(secParts[0]);\n                                courseObj.endSection = parseInt(secParts[secParts.length - 1]);\n                            } else {\n                                courseObj.startSection = i * 2 - 1;\n                                courseObj.endSection = i * 2;\n                            }\n                        }\n                    } else {\n                        return; // 抛弃无时间信息的记录\n                    }\n\n                    if (courseObj.name && courseObj.weeks && courseObj.weeks.length > 0) {\n                        parsedCourses.push(courseObj);\n                    }\n                });\n            });\n        }\n    }\n\n    // ========== 新增：去重逻辑 ==========\n    let uniqueCourses = [];\n    let courseSet = new Set();\n\n    parsedCourses.forEach(course => {\n        // 生成唯一标识符：星期几 + 开始节次 + 结束节次 + 课程名 + 周次数组转字符串\n        let uniqueKey = `${course.day}-${course.startSection}-${course.endSection}-${course.name}-${course.weeks.join(',')}`;\n        \n        // 如果 Set 中没有这个标识符，说明是第一次遇到，加入结果数组\n        if (!courseSet.has(uniqueKey)) {\n            courseSet.add(uniqueKey);\n            uniqueCourses.push(course);\n        }\n    });\n\n    return uniqueCourses; // 返回去重后的纯净数组\n}\n\n/**\n * 生成学校专属的作息时间段\n */\nfunction getPresetTimeSlots() {\n    return [\n        { \"number\": 1, \"startTime\": \"08:00\", \"endTime\": \"08:40\" },\n        { \"number\": 2, \"startTime\": \"08:45\", \"endTime\": \"09:25\" },\n        { \"number\": 3, \"startTime\": \"09:45\", \"endTime\": \"10:25\" },\n        { \"number\": 4, \"startTime\": \"10:30\", \"endTime\": \"11:10\" },\n        { \"number\": 5, \"startTime\": \"11:15\", \"endTime\": \"11:55\" },\n        { \"number\": 6, \"startTime\": \"14:00\", \"endTime\": \"14:40\" },\n        { \"number\": 7, \"startTime\": \"14:45\", \"endTime\": \"15:25\" },\n        { \"number\": 8, \"startTime\": \"15:45\", \"endTime\": \"16:25\" },\n        { \"number\": 9, \"startTime\": \"16:30\", \"endTime\": \"17:10\" },\n        { \"number\": 10, \"startTime\": \"18:30\", \"endTime\": \"19:10\" },\n        { \"number\": 11, \"startTime\": \"19:15\", \"endTime\": \"19:55\" } \n    ];\n}\n\n/**\n * 生成全局课表配置\n */\nfunction getCourseConfig() {\n    return {\n        \"defaultClassDuration\": 40,\n        \"defaultBreakDuration\": 5\n    };\n}\n\n/**\n * 异步编排流程\n */\nasync function runImportFlow() {\n    try {\n        if (typeof window.shiguangBridge !== 'undefined') {\n            window.shiguangBridge.showToast(\"正在获取课表数据，请稍候...\");\n        } else {\n            console.log(\"正在发起请求获取课表...\");\n        }\n\n        const response = await fetch('/jsxsd/xskb/xskb_list.do', { method: 'GET' });\n        const htmlText = await response.text();\n        const parser = new DOMParser();\n        let doc = parser.parseFromString(htmlText, 'text/html');\n\n        const selectElem = doc.getElementById('xnxq01id');\n        let semesters = [];\n        let semesterValues = [];\n        let defaultIndex = 0;\n\n        if (selectElem) {\n            const options = selectElem.querySelectorAll('option');\n            options.forEach((opt, index) => {\n                semesters.push(opt.innerText.trim());\n                semesterValues.push(opt.value);\n                if (opt.hasAttribute('selected')) {\n                    defaultIndex = index;\n                }\n            });\n        }\n\n        if (semesters.length > 0 && typeof window.shiguangBridgePromise !== 'undefined') {\n            let selectedIdx = await window.shiguangBridgePromise.showSingleSelection(\n                \"请选择要导入的学期\", \n                JSON.stringify(semesters), \n                defaultIndex\n            );\n\n            if (selectedIdx === null) {\n                window.shiguangBridge.showToast(\"已取消导入\");\n                return;\n            }\n\n            if (selectedIdx !== defaultIndex) {\n                window.shiguangBridge.showToast(`正在获取 [${semesters[selectedIdx]}] 课表...`);\n                let formData = new URLSearchParams();\n                formData.append('xnxq01id', semesterValues[selectedIdx]);\n\n                const postResponse = await fetch('/jsxsd/xskb/xskb_list.do', {\n                    method: 'POST',\n                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },\n                    body: formData.toString()\n                });\n                const postHtml = await postResponse.text();\n                doc = parser.parseFromString(postHtml, 'text/html');\n            }\n        }\n\n        const courses = extractCoursesFromDoc(doc);\n        \n        if (courses.length === 0) {\n            const errMsg = \"未能解析到任何课程，请检查是否暂无排课。\";\n            if (typeof window.shiguangBridgePromise !== 'undefined') {\n                await window.shiguangBridgePromise.showAlert(\"提示\", errMsg, \"好的\");\n            } else {\n                alert(errMsg);\n            }\n            return;\n        }\n\n        const config = getCourseConfig();\n        const timeSlots = getPresetTimeSlots();\n\n        if (typeof window.shiguangBridgePromise === 'undefined') {\n            console.log(\"【去重成功】课程数据：\\n\", JSON.stringify(courses, null, 2));\n            alert(`解析并去重成功！共获取到 ${courses.length} 门课程。请打开F12查看。`);\n            return;\n        }\n\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        \n        const saveResult = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        if (!saveResult) {\n            window.shiguangBridge.showToast(\"保存课程失败，请重试！\");\n            return;\n        }\n\n        window.shiguangBridge.showToast(`成功导入 ${courses.length} 节课程及作息时间！`);\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (error) {\n        if (typeof window.shiguangBridge !== 'undefined') {\n            window.shiguangBridge.showToast(\"导入发生异常: \" + error.message);\n        } else {\n            console.error(\"【导入发生异常】\", error);\n            alert(\"导入发生异常: \" + error.message);\n        }\n    }\n}\n\nrunImportFlow();","JSTC_01":"// 江苏旅游职业学院（jstc.edu.cn） 拾光课程表适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提issues或者提交pr更改,这更加快速\n\n\n\n// 不确定是否还有效的数据 仅保留代码内部不做调用\nconst presetTimeSlots_oldFunction = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:50\", endTime: \"09:35\" },\n    { number: 3, startTime: \"09:55\", endTime: \"10:40\" },\n    { number: 4, startTime: \"10:45\", endTime: \"11:30\" },\n    { number: 5, startTime: \"11:35\", endTime: \"12:20\" },\n    { number: 6, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 7, startTime: \"14:50\", endTime: \"15:35\" },\n    { number: 8, startTime: \"15:55\", endTime: \"16:40\" },\n    { number: 9, startTime: \"16:45\", endTime: \"17:30\" },\n    { number: 10, startTime: \"19:00\", endTime: \"19:45\" },\n    { number: 11, startTime: \"19:50\", endTime: \"20:35\" }\n];\n\n\n\n\nconst presetTimeSlots = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:40\" },\n    { number: 2, startTime: \"08:50\", endTime: \"09:30\" },\n    { number: 3, startTime: \"09:50\", endTime: \"10:30\" },\n    { number: 4, startTime: \"10:40\", endTime: \"11:20\" },\n    { number: 5, startTime: \"11:30\", endTime: \"12:10\" },\n    { number: 6, startTime: \"14:00\", endTime: \"14:40\" },\n    { number: 7, startTime: \"14:50\", endTime: \"15:30\" },\n    { number: 8, startTime: \"15:50\", endTime: \"16:30\" },\n    { number: 9, startTime: \"16:40\", endTime: \"17:20\" },\n    { number: 10, startTime: \"19:00\", endTime: \"19:40\" },\n    { number: 11, startTime: \"19:50\", endTime: \"20:30\" }\n];\n\n\n/**\n * 获取学期下拉列表选项\n */\nasync function fetchSemesters() {\n    try {\n        const res = await fetch(\"https://jwxt.jstc.edu.cn/student/for-std/course-table\", {\n            headers: {\n                \"accept\": \"text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            method: \"GET\",\n            credentials: \"include\"\n        });\n        if (!res.ok) return null;\n        \n        const htmlText = await res.text();\n        const parser = new DOMParser();\n        const doc = parser.parseFromString(htmlText, \"text/html\");\n        const select = doc.getElementById(\"allSemesters\");\n        if (!select) return null;\n\n        const options = Array.from(select.querySelectorAll(\"option\")).map(opt => ({\n            label: opt.textContent.trim(),\n            value: opt.value.trim()\n        }));\n\n        return options;\n    } catch (e) {\n        console.error(\"Fetch semesters failed:\", e);\n        return null;\n    }\n}\n\n/**\n * 获取学期开学时间元数据\n */\nasync function fetchSemesterMetadata(semesterId) {\n    try {\n        const res = await fetch(`https://jwxt.jstc.edu.cn/student/ws/semester/get/${semesterId}`, {\n            headers: {\n                \"accept\": \"*/*\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            method: \"GET\",\n            credentials: \"include\"\n        });\n        if (!res.ok) return null;\n        const data = await res.json();\n        return data.startDate || null;\n    } catch (e) {\n        console.error(\"Fetch semester metadata failed:\", e);\n        return null;\n    }\n}\n\n/**\n * 获取并解析课表原数据\n */\nasync function fetchAndParseCourses(semesterId) {\n    try {\n        const url = `https://jwxt.jstc.edu.cn/student/for-std/course-table/semester/${semesterId}/print-data?semesterId=${semesterId}&hasExperiment=true`;\n        const res = await fetch(url, {\n            headers: {\n                \"accept\": \"*/*\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            method: \"GET\",\n            credentials: \"include\"\n        });\n\n        if (!res.ok) return null;\n        const data = await res.json();\n        \n        if (!data || !Array.isArray(data.studentTableVms) || data.studentTableVms.length === 0) {\n            return null;\n        }\n\n        const rawActivities = data.studentTableVms[0].activities || [];\n        const parsedCourses = [];\n\n        for (const act of rawActivities) {\n            if (!act.courseName || !act.weekday || !act.startUnit || !act.endUnit || !Array.isArray(act.weekIndexes)) {\n                continue;\n            }\n\n            const teacherName = Array.isArray(act.teachers) && act.teachers.length > 0\n                ? act.teachers.map(t => t.replace(/\\(\\d+\\)/g, '')).join(',')\n                : '';\n\n            parsedCourses.push({\n                name: act.courseName.trim(),\n                teacher: teacherName.trim(),\n                position: (act.room || '').trim(),\n                day: Number(act.weekday),\n                startSection: Number(act.startUnit),\n                endSection: Number(act.endUnit),\n                weeks: act.weekIndexes.map(Number).sort((a, b) => a - b)\n            });\n        }\n\n        return parsedCourses;\n    } catch (e) {\n        console.error(\"Fetch course data failed:\", e);\n        return null;\n    }\n}\n\n/**\n * 流程控制\n */\nasync function runImportFlow() {\n    window.shiguangBridge.showToast(\"开始拉取学期列表...\");\n\n    // 获取学期列表\n    const semesters = await fetchSemesters();\n    if (!semesters || semesters.length === 0) {\n        window.shiguangBridge.showToast(\"获取学期列表失败，请检查登录状态或网络\");\n        return;\n    }\n\n    const labels = semesters.map(s => s.label);\n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(labels),\n        -1\n    );\n\n    if (selectedIndex === null || selectedIndex < 0) {\n        window.shiguangBridge.showToast(\"操作已取消\");\n        return;\n    }\n\n    const selectedSemester = semesters[selectedIndex];\n\n    // 并行获取元数据与课程表\n    window.shiguangBridge.showToast(\"正在拉取课表数据...\");\n    const [startDate, courses] = await Promise.all([\n        fetchSemesterMetadata(selectedSemester.value),\n        fetchAndParseCourses(selectedSemester.value)\n    ]);\n\n    if (!courses || courses.length === 0) {\n        window.shiguangBridge.showToast(\"未查询到有效课程数据\");\n        return;\n    }\n\n    // 保存学期配置\n    const configData = {\n        semesterStartDate: startDate,\n        semesterTotalWeeks: 20\n    };\n\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(configData));\n    } catch (e) {\n        window.shiguangBridge.showToast(\"配置保存异常: \" + e.message);\n        return;\n    }\n\n    // 保存课程列表\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n    } catch (e) {\n        window.shiguangBridge.showToast(\"课程保存异常: \" + e.message);\n        return;\n    }\n\n    // 保存预设作息时间\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(presetTimeSlots));\n    } catch (e) {\n        window.shiguangBridge.showToast(\"作息时间保存异常: \" + e.message);\n    }\n\n    window.shiguangBridge.showToast(`成功导入 ${courses.length} 门课程及作息时间！`);\n\n    // 任务完成通知\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();","JSEI_01":"// 江苏电子信息职业学院(jsei.edu.cn) 拾光课程表适配脚本\n// 基于正方教务系统接口适配\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提issues或者提交pr更改,这更加快速\n\n/**\n * 基础域名配置\n * 根据当前页面域名自动选择校园网直连或 WebVPN\n */\nconst BASE_URLS = {\n    // 校园网直连\n    campus: \"https://jwpd.jsei.edu.cn/jwglxt\",\n    // WebVPN 代理\n    webvpn: \"https://jwpd-443.webvpn.jsei.edu.cn/jwglxt\"\n};\n\n/**\n * 根据当前页面域名自动判断使用哪个基础地址\n * - 当前在 webvpn 域名下 -> 用 webvpn\n * - 否则 -> 用校园网直连\n */\nfunction getBaseUrl() {\n    if (window.location.hostname.includes(\"webvpn\")) {\n        return BASE_URLS.webvpn;\n    }\n    return BASE_URLS.campus;\n}\n\n/**\n * 节次与周次合并去重函数\n * @param {Array<Object>} courses 原始解析课程数组\n * @returns {Array<Object>} 合并去重后的课程数组\n */\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    // 1. 深拷贝并规范周次数据，过滤无效项\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n\n    // 阶段 1：合并连续节次与完全重复记录（前提：名称、教师、地点、星期、周次一致）\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n               (a.startSection || 0) - (b.startSection || 0);\n    });\n\n    const step1Merged = [];\n    let current = list[0];\n\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n\n        const isSameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n\n        if (isSameCourseAndWeeks && isContinuous) {\n            // 节次连续：延长结束节次 (如 1-2 节 + 3-4 节 -> 1-4 节)\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            // 完全重复：跳过\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    // 阶段 2：合并同节次的周次（前提：名称、教师、地点、星期、开始/结束节次一致）\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               (a.startSection || 0) - (b.startSection || 0) ||\n               (a.endSection || 0) - (b.endSection || 0);\n    });\n\n    const step2Merged = [];\n    let cur = step1Merged[0];\n\n    for (let i = 1; i < step1Merged.length; i++) {\n        const nxt = step1Merged[i];\n\n        const isSameCourseAndSection =\n            cur.name === nxt.name &&\n            cur.teacher === nxt.teacher &&\n            cur.position === nxt.position &&\n            cur.day === nxt.day &&\n            cur.startSection === nxt.startSection &&\n            cur.endSection === nxt.endSection;\n\n        if (isSameCourseAndSection) {\n            // 周次合并去重 (如 1-8 周 + 9-16 周 -> 1-16 周)\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(cur);\n            cur = nxt;\n        }\n    }\n    step2Merged.push(cur);\n\n    return step2Merged;\n}\n\n/**\n * 解析周次字符串，处理单双周和周次范围\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    const cleaned = weekStr\n        .replace(/周数[:：]/g, '')\n        .replace(/第/g, '')\n        .replace(/周/g, '')\n        .replace(/共\\s*\\d+\\s*.*$/g, '');\n\n    const segments = cleaned.split(/[,，、;；]/);\n\n    const weeks = [];\n    const segRegex = /(\\d+)(?:\\s*[-~]\\s*(\\d+))?\\s*(?:[（(]?\\s*([单双])\\s*周?\\s*[)）]?)?/g;\n\n    for (const seg of segments) {\n        const s = seg.trim();\n        if (!s) continue;\n\n        segRegex.lastIndex = 0;\n        let m;\n        while ((m = segRegex.exec(s)) !== null) {\n            if (m[0] === '') {\n                segRegex.lastIndex++;\n                continue;\n            }\n\n            const start = parseInt(m[1], 10);\n            const end = m[2] ? parseInt(m[2], 10) : start;\n            const flagStr = m[3] || '';\n\n            let flag = 0;\n            if (flagStr.includes('单')) flag = 1;\n            else if (flagStr.includes('双')) flag = 2;\n\n            for (let w = start; w <= end; w++) {\n                if (flag === 1 && w % 2 === 0) continue;\n                if (flag === 2 && w % 2 !== 0) continue;\n                weeks.push(w);\n            }\n        }\n    }\n\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 解析 API 返回的 JSON 数据\n */\nfunction parseJsonData(jsonData) {\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        return [];\n    }\n\n    const rawCourseList = jsonData.kbList;\n    const initialCourseList = [];\n\n    for (const rawCourse of rawCourseList) {\n        if (!rawCourse.kcmc || !rawCourse.xm || !rawCourse.cdmc || \n            !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) {\n            continue;\n        }\n\n        const weeksArray = parseWeeks(rawCourse.zcd);\n        if (weeksArray.length === 0) {\n            continue;\n        }\n        \n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]);\n        const day = Number(rawCourse.xqj);\n        \n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) || \n            day < 1 || day > 7 || startSection > endSection) {\n            continue;\n        }\n\n        initialCourseList.push({\n            name: rawCourse.kcmc.trim(),\n            teacher: rawCourse.xm.trim(),\n            position: rawCourse.cdmc.trim(),\n            day: day,\n            startSection: startSection,\n            endSection: endSection,\n            weeks: weeksArray\n        });\n    }\n\n    return mergeAndDistinctCourses(initialCourseList);\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\n/**\n * 从教务系统获取学年学期选项\n * 学年：以选中项为中心，取前2年+后2年，共5个选项\n */\nasync function fetchAcademicOptions() {\n    const url = `${getBaseUrl()}/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151&layout=default`;\n    \n    try {\n        const response = await fetch(url, {\n            method: \"GET\",\n            credentials: \"include\"\n        });\n\n        if (!response.ok) return null;\n\n        const htmlText = await response.text();\n        const parser = new DOMParser();\n        const doc = parser.parseFromString(htmlText, \"text/html\");\n\n        const allYearOptions = Array.from(doc.querySelectorAll(\"#xnm option\"))\n            .filter(opt => opt.value !== \"\")\n            .map(opt => ({\n                value: opt.value,\n                text: opt.textContent.trim(),\n                selected: opt.selected\n            }));\n\n        const semesterOptions = Array.from(doc.querySelectorAll(\"#xqm option\"))\n            .filter(opt => opt.value !== \"\")\n            .map(opt => ({\n                value: opt.value,\n                text: opt.textContent.trim(),\n                selected: opt.selected\n            }));\n\n        if (allYearOptions.length === 0 || semesterOptions.length === 0) {\n            return null;\n        }\n\n        const selectedIndex = allYearOptions.findIndex(opt => opt.selected);\n        \n        if (selectedIndex === -1) {\n            return {\n                yearOptions: allYearOptions.slice(0, 5),\n                semesterOptions,\n                defaultYearIndex: 0,\n                defaultSemesterIndex: semesterOptions.findIndex(opt => opt.selected) !== -1 \n                    ? semesterOptions.findIndex(opt => opt.selected) \n                    : 0\n            };\n        }\n\n        const start = Math.max(0, selectedIndex - 2);\n        const end = Math.min(allYearOptions.length, selectedIndex + 3);\n        const yearOptions = allYearOptions.slice(start, end);\n        const newDefaultIndex = selectedIndex - start;\n        const defaultSemesterIndex = semesterOptions.findIndex(opt => opt.selected);\n\n        return {\n            yearOptions,\n            semesterOptions,\n            defaultYearIndex: newDefaultIndex,\n            defaultSemesterIndex: defaultSemesterIndex !== -1 ? defaultSemesterIndex : 0\n        };\n\n    } catch (e) {\n        return null;\n    }\n}\n\n/**\n * 提示用户选择学年和学期\n */\nasync function selectAcademicYearAndSemester() {\n    const optionsData = await fetchAcademicOptions();\n\n    if (!optionsData) {\n        window.shiguangBridge.showToast(\"从教务系统读取学年学期失败，请确保登录状态。\");\n        return null;\n    }\n\n    const { yearOptions, semesterOptions, defaultYearIndex, defaultSemesterIndex } = optionsData;\n\n    const yearTexts = yearOptions.map(item => item.text);\n    const yearIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学年\",\n        JSON.stringify(yearTexts),\n        defaultYearIndex\n    );\n\n    if (yearIndex === null || yearIndex === -1) return null;\n    const selectedYearCode = yearOptions[yearIndex].value;\n\n    const semesterTexts = semesterOptions.map(item => item.text);\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesterTexts),\n        defaultSemesterIndex\n    );\n\n    if (semesterIndex === null || semesterIndex === -1) return null;\n    const selectedSemesterCode = semesterOptions[semesterIndex].value;\n\n    return {\n        academicYear: selectedYearCode,\n        semesterCode: selectedSemesterCode\n    };\n}\n\n/**\n * 获取学期开学日期\n */\nasync function fetchSemesterStartDate(academicYear, semesterCode) {\n    const url = `${getBaseUrl()}/kbcx/xskbcxZccx_cxZcByXnxq.html?gnmkdm=N2154`;\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}`;\n\n    try {\n        const response = await fetch(url, {\n            method: \"POST\",\n            headers: {\n                \"accept\": \"application/json, text/javascript, */*; q=0.01\",\n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: requestBody,\n            credentials: \"include\"\n        });\n\n        if (response.ok) {\n            const json = await response.json();\n            if (Array.isArray(json) && json.length > 0) {\n                // 优先找第1周，否则取第一项\n                const firstWeekObj = json.find(item => String(item.zs) === \"1\" || String(item.zsmc) === \"1\") || json[0];\n                \n                if (firstWeekObj.rq) {\n                    const startDateStr = firstWeekObj.rq.split('/')[0];\n                    if (/^\\d{4}-\\d{2}-\\d{2}$/.test(startDateStr)) {\n                        return startDateStr;\n                    }\n                }\n                if (firstWeekObj.zcrq) {\n                    const match = firstWeekObj.zcrq.match(/(\\d{4}-\\d{2}-\\d{2})/);\n                    if (match) return match[1];\n                }\n                // 某些系统用 ksrq 字段\n                if (firstWeekObj.ksrq) {\n                    const match = firstWeekObj.ksrq.match(/(\\d{4}-\\d{2}-\\d{2})/);\n                    if (match) return match[1];\n                }\n            }\n        }\n    } catch (e) {\n        // 获取失败不影响主流程\n    }\n    return null;\n}\n\n/**\n * 从教务系统获取作息时间表（节次时间）\n * @param {string} academicYear 学年\n * @param {string} semesterCode 学期代码\n * @returns {Promise<Array<{number: number, startTime: string, endTime: string}>>}\n */\nasync function fetchTimeSlots(academicYear, semesterCode) {\n    const url = `${getBaseUrl()}/jzgl/skxxMobile_cxRsdjc.html?gnmkdm=N2154`;\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}&xqh_id=1`;\n\n    try {\n        const response = await fetch(url, {\n            method: \"POST\",\n            headers: {\n                \"accept\": \"*/*\",\n                \"content-type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: requestBody,\n            credentials: \"include\"\n        });\n\n        if (!response.ok) return null;\n\n        const json = await response.json();\n        if (!Array.isArray(json)) return null;\n\n        // 过滤有效节次并转换格式\n        const timeSlots = json\n            .filter(item => item.jcmc && item.qssj && item.jssj)\n            .map(item => ({\n                number: Number(item.jcmc),\n                startTime: item.qssj.substring(0, 5), // \"08:30:00\" -> \"08:30\"\n                endTime: item.jssj.substring(0, 5)\n            }))\n            .sort((a, b) => a.number - b.number);\n\n        return timeSlots.length > 0 ? timeSlots : null;\n    } catch (e) {\n        return null;\n    }\n}\n\n/**\n * 请求和解析课程数据\n */\nasync function fetchAndParseCourses(academicYear, semesterCode) {\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`;\n    const targetUrl = `${getBaseUrl()}/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151`;\n\n    // 并行获取课程数据、开学日期、作息时间\n    const [courseResponse, semesterStartDate, fetchedTimeSlots] = await Promise.all([\n        fetch(targetUrl, {\n            method: \"POST\",\n            headers: {\n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\"\n            },\n            body: requestBody,\n            credentials: \"include\"\n        }),\n        fetchSemesterStartDate(academicYear, semesterCode),\n        fetchTimeSlots(academicYear, semesterCode)\n    ]);\n\n    try {\n        if (courseResponse.ok) {\n            const jsonText = await courseResponse.text();\n            const jsonData = JSON.parse(jsonText);\n            if (jsonData && jsonData.kbList) {\n                const parsedCourses = parseJsonData(jsonData);\n                if (parsedCourses.length > 0) {\n                    return {\n                        courses: parsedCourses,\n                        config: {\n                            semesterStartDate: semesterStartDate,\n                            semesterTotalWeeks: 20\n                        },\n                        timeSlots: fetchedTimeSlots\n                    };\n                }\n            }\n        }\n    } catch (e) {\n        // 请求失败\n    }\n\n    window.shiguangBridge.showToast(\"未能获取课表数据，请检查网络环境或登录状态。\");\n    return null;\n}\n\nasync function saveCourses(parsedCourses) {\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        return false;\n    }\n}\n\n// 优先使用从教务系统接口动态获取的作息时间，获取失败时回退到此表\nconst FALLBACK_TIME_SLOTS = [\n    { number: 1, startTime: \"08:30\", endTime: \"09:15\" },\n    { number: 2, startTime: \"09:20\", endTime: \"10:05\" },\n    { number: 3, startTime: \"10:20\", endTime: \"11:05\" },\n    { number: 4, startTime: \"11:10\", endTime: \"11:55\" },\n    { number: 5, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 6, startTime: \"14:50\", endTime: \"15:35\" },\n    { number: 7, startTime: \"15:50\", endTime: \"16:35\" },\n    { number: 8, startTime: \"16:40\", endTime: \"17:25\" },\n    { number: 9, startTime: \"17:30\", endTime: \"18:15\" },\n    { number: 10, startTime: \"19:00\", endTime: \"19:45\" },\n    { number: 11, startTime: \"19:55\", endTime: \"20:40\" }\n];\n\nasync function importPresetTimeSlots(timeSlots) {\n    let finalTimeSlots = timeSlots;\n    let usedFallback = false;\n\n    if (!finalTimeSlots || finalTimeSlots.length === 0) {\n        // 动态获取失败，回退到硬编码保底方案\n        finalTimeSlots = FALLBACK_TIME_SLOTS;\n        usedFallback = true;\n    }\n\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(finalTimeSlots));\n        if (usedFallback) {\n            window.shiguangBridge.showToast(\"未获取到教务系统作息，已使用内置保底作息时间导入。\");\n        } else {\n            window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n        }\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n    }\n}\n\nasync function runImportFlow() {\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    const selection = await selectAcademicYearAndSemester();\n    if (!selection) {\n        window.shiguangBridge.showToast(\"未选择学年学期，导入流程终止。\");\n        return;\n    }\n\n    const { academicYear, semesterCode } = selection;\n\n    const result = await fetchAndParseCourses(academicYear, semesterCode);\n    if (result === null) {\n        return;\n    }\n\n    const { courses, config, timeSlots } = result;\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        return;\n    }\n    \n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        let configMsg = \"课表配置更新成功！\";\n        if (config.semesterStartDate) {\n            configMsg += ` 开学日期：${config.semesterStartDate}`;\n        }\n        window.shiguangBridge.showToast(configMsg);\n    } catch (error) {\n        window.shiguangBridge.showToast(`课表配置保存失败: ${error.message}`);\n    }\n\n    await importPresetTimeSlots(timeSlots);\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();","JSEI_02":"// 江苏电子信息职业学院(jsei.edu.cn) 拾光课程表适配脚本\n// 基于正方教务系统接口适配\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提issues或者提交pr更改,这更加快速\n\n/**\n * 基础域名配置\n * 根据当前页面域名自动选择校园网直连或 WebVPN\n */\nconst BASE_URLS = {\n    // 校园网直连\n    campus: \"https://jwpd.jsei.edu.cn/jwglxt\",\n    // WebVPN 代理\n    webvpn: \"https://jwpd-443.webvpn.jsei.edu.cn/jwglxt\"\n};\n\n/**\n * 根据当前页面域名自动判断使用哪个基础地址\n * - 当前在 webvpn 域名下 -> 用 webvpn\n * - 否则 -> 用校园网直连\n */\nfunction getBaseUrl() {\n    if (window.location.hostname.includes(\"webvpn\")) {\n        return BASE_URLS.webvpn;\n    }\n    return BASE_URLS.campus;\n}\n\n/**\n * 节次与周次合并去重函数\n * @param {Array<Object>} courses 原始解析课程数组\n * @returns {Array<Object>} 合并去重后的课程数组\n */\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    // 1. 深拷贝并规范周次数据，过滤无效项\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n\n    // 阶段 1：合并连续节次与完全重复记录（前提：名称、教师、地点、星期、周次一致）\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n               (a.startSection || 0) - (b.startSection || 0);\n    });\n\n    const step1Merged = [];\n    let current = list[0];\n\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n\n        const isSameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n\n        if (isSameCourseAndWeeks && isContinuous) {\n            // 节次连续：延长结束节次 (如 1-2 节 + 3-4 节 -> 1-4 节)\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            // 完全重复：跳过\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    // 阶段 2：合并同节次的周次（前提：名称、教师、地点、星期、开始/结束节次一致）\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               (a.startSection || 0) - (b.startSection || 0) ||\n               (a.endSection || 0) - (b.endSection || 0);\n    });\n\n    const step2Merged = [];\n    let cur = step1Merged[0];\n\n    for (let i = 1; i < step1Merged.length; i++) {\n        const nxt = step1Merged[i];\n\n        const isSameCourseAndSection =\n            cur.name === nxt.name &&\n            cur.teacher === nxt.teacher &&\n            cur.position === nxt.position &&\n            cur.day === nxt.day &&\n            cur.startSection === nxt.startSection &&\n            cur.endSection === nxt.endSection;\n\n        if (isSameCourseAndSection) {\n            // 周次合并去重 (如 1-8 周 + 9-16 周 -> 1-16 周)\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(cur);\n            cur = nxt;\n        }\n    }\n    step2Merged.push(cur);\n\n    return step2Merged;\n}\n\n/**\n * 解析周次字符串，处理单双周和周次范围\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    const cleaned = weekStr\n        .replace(/周数[:：]/g, '')\n        .replace(/第/g, '')\n        .replace(/周/g, '')\n        .replace(/共\\s*\\d+\\s*.*$/g, '');\n\n    const segments = cleaned.split(/[,，、;；]/);\n\n    const weeks = [];\n    const segRegex = /(\\d+)(?:\\s*[-~]\\s*(\\d+))?\\s*(?:[（(]?\\s*([单双])\\s*周?\\s*[)）]?)?/g;\n\n    for (const seg of segments) {\n        const s = seg.trim();\n        if (!s) continue;\n\n        segRegex.lastIndex = 0;\n        let m;\n        while ((m = segRegex.exec(s)) !== null) {\n            if (m[0] === '') {\n                segRegex.lastIndex++;\n                continue;\n            }\n\n            const start = parseInt(m[1], 10);\n            const end = m[2] ? parseInt(m[2], 10) : start;\n            const flagStr = m[3] || '';\n\n            let flag = 0;\n            if (flagStr.includes('单')) flag = 1;\n            else if (flagStr.includes('双')) flag = 2;\n\n            for (let w = start; w <= end; w++) {\n                if (flag === 1 && w % 2 === 0) continue;\n                if (flag === 2 && w % 2 !== 0) continue;\n                weeks.push(w);\n            }\n        }\n    }\n\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 解析 API 返回的 JSON 数据\n */\nfunction parseJsonData(jsonData) {\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        return [];\n    }\n\n    const rawCourseList = jsonData.kbList;\n    const initialCourseList = [];\n\n    for (const rawCourse of rawCourseList) {\n        if (!rawCourse.kcmc || !rawCourse.xm || !rawCourse.cdmc || \n            !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) {\n            continue;\n        }\n\n        const weeksArray = parseWeeks(rawCourse.zcd);\n        if (weeksArray.length === 0) {\n            continue;\n        }\n        \n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]);\n        const day = Number(rawCourse.xqj);\n        \n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) || \n            day < 1 || day > 7 || startSection > endSection) {\n            continue;\n        }\n\n        initialCourseList.push({\n            name: rawCourse.kcmc.trim(),\n            teacher: rawCourse.xm.trim(),\n            position: rawCourse.cdmc.trim(),\n            day: day,\n            startSection: startSection,\n            endSection: endSection,\n            weeks: weeksArray\n        });\n    }\n\n    return mergeAndDistinctCourses(initialCourseList);\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\n/**\n * 从教务系统获取学年学期选项\n * 学年：以选中项为中心，取前2年+后2年，共5个选项\n */\nasync function fetchAcademicOptions() {\n    const url = `${getBaseUrl()}/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151&layout=default`;\n    \n    try {\n        const response = await fetch(url, {\n            method: \"GET\",\n            credentials: \"include\"\n        });\n\n        if (!response.ok) return null;\n\n        const htmlText = await response.text();\n        const parser = new DOMParser();\n        const doc = parser.parseFromString(htmlText, \"text/html\");\n\n        const allYearOptions = Array.from(doc.querySelectorAll(\"#xnm option\"))\n            .filter(opt => opt.value !== \"\")\n            .map(opt => ({\n                value: opt.value,\n                text: opt.textContent.trim(),\n                selected: opt.selected\n            }));\n\n        const semesterOptions = Array.from(doc.querySelectorAll(\"#xqm option\"))\n            .filter(opt => opt.value !== \"\")\n            .map(opt => ({\n                value: opt.value,\n                text: opt.textContent.trim(),\n                selected: opt.selected\n            }));\n\n        if (allYearOptions.length === 0 || semesterOptions.length === 0) {\n            return null;\n        }\n\n        const selectedIndex = allYearOptions.findIndex(opt => opt.selected);\n        \n        if (selectedIndex === -1) {\n            return {\n                yearOptions: allYearOptions.slice(0, 5),\n                semesterOptions,\n                defaultYearIndex: 0,\n                defaultSemesterIndex: semesterOptions.findIndex(opt => opt.selected) !== -1 \n                    ? semesterOptions.findIndex(opt => opt.selected) \n                    : 0\n            };\n        }\n\n        const start = Math.max(0, selectedIndex - 2);\n        const end = Math.min(allYearOptions.length, selectedIndex + 3);\n        const yearOptions = allYearOptions.slice(start, end);\n        const newDefaultIndex = selectedIndex - start;\n        const defaultSemesterIndex = semesterOptions.findIndex(opt => opt.selected);\n\n        return {\n            yearOptions,\n            semesterOptions,\n            defaultYearIndex: newDefaultIndex,\n            defaultSemesterIndex: defaultSemesterIndex !== -1 ? defaultSemesterIndex : 0\n        };\n\n    } catch (e) {\n        return null;\n    }\n}\n\n/**\n * 提示用户选择学年和学期\n */\nasync function selectAcademicYearAndSemester() {\n    const optionsData = await fetchAcademicOptions();\n\n    if (!optionsData) {\n        window.shiguangBridge.showToast(\"从教务系统读取学年学期失败，请确保登录状态。\");\n        return null;\n    }\n\n    const { yearOptions, semesterOptions, defaultYearIndex, defaultSemesterIndex } = optionsData;\n\n    const yearTexts = yearOptions.map(item => item.text);\n    const yearIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学年\",\n        JSON.stringify(yearTexts),\n        defaultYearIndex\n    );\n\n    if (yearIndex === null || yearIndex === -1) return null;\n    const selectedYearCode = yearOptions[yearIndex].value;\n\n    const semesterTexts = semesterOptions.map(item => item.text);\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesterTexts),\n        defaultSemesterIndex\n    );\n\n    if (semesterIndex === null || semesterIndex === -1) return null;\n    const selectedSemesterCode = semesterOptions[semesterIndex].value;\n\n    return {\n        academicYear: selectedYearCode,\n        semesterCode: selectedSemesterCode\n    };\n}\n\n/**\n * 获取学期开学日期\n */\nasync function fetchSemesterStartDate(academicYear, semesterCode) {\n    const url = `${getBaseUrl()}/kbcx/xskbcxZccx_cxZcByXnxq.html?gnmkdm=N2154`;\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}`;\n\n    try {\n        const response = await fetch(url, {\n            method: \"POST\",\n            headers: {\n                \"accept\": \"application/json, text/javascript, */*; q=0.01\",\n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: requestBody,\n            credentials: \"include\"\n        });\n\n        if (response.ok) {\n            const json = await response.json();\n            if (Array.isArray(json) && json.length > 0) {\n                // 优先找第1周，否则取第一项\n                const firstWeekObj = json.find(item => String(item.zs) === \"1\" || String(item.zsmc) === \"1\") || json[0];\n                \n                if (firstWeekObj.rq) {\n                    const startDateStr = firstWeekObj.rq.split('/')[0];\n                    if (/^\\d{4}-\\d{2}-\\d{2}$/.test(startDateStr)) {\n                        return startDateStr;\n                    }\n                }\n                if (firstWeekObj.zcrq) {\n                    const match = firstWeekObj.zcrq.match(/(\\d{4}-\\d{2}-\\d{2})/);\n                    if (match) return match[1];\n                }\n                // 某些系统用 ksrq 字段\n                if (firstWeekObj.ksrq) {\n                    const match = firstWeekObj.ksrq.match(/(\\d{4}-\\d{2}-\\d{2})/);\n                    if (match) return match[1];\n                }\n            }\n        }\n    } catch (e) {\n        // 获取失败不影响主流程\n    }\n    return null;\n}\n\n/**\n * 从教务系统获取作息时间表（节次时间）\n * @param {string} academicYear 学年\n * @param {string} semesterCode 学期代码\n * @returns {Promise<Array<{number: number, startTime: string, endTime: string}>>}\n */\nasync function fetchTimeSlots(academicYear, semesterCode) {\n    const url = `${getBaseUrl()}/jzgl/skxxMobile_cxRsdjc.html?gnmkdm=N2154`;\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}&xqh_id=1`;\n\n    try {\n        const response = await fetch(url, {\n            method: \"POST\",\n            headers: {\n                \"accept\": \"*/*\",\n                \"content-type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: requestBody,\n            credentials: \"include\"\n        });\n\n        if (!response.ok) return null;\n\n        const json = await response.json();\n        if (!Array.isArray(json)) return null;\n\n        // 过滤有效节次并转换格式\n        const timeSlots = json\n            .filter(item => item.jcmc && item.qssj && item.jssj)\n            .map(item => ({\n                number: Number(item.jcmc),\n                startTime: item.qssj.substring(0, 5), // \"08:30:00\" -> \"08:30\"\n                endTime: item.jssj.substring(0, 5)\n            }))\n            .sort((a, b) => a.number - b.number);\n\n        return timeSlots.length > 0 ? timeSlots : null;\n    } catch (e) {\n        return null;\n    }\n}\n\n/**\n * 请求和解析课程数据\n */\nasync function fetchAndParseCourses(academicYear, semesterCode) {\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`;\n    const targetUrl = `${getBaseUrl()}/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151`;\n\n    // 并行获取课程数据、开学日期、作息时间\n    const [courseResponse, semesterStartDate, fetchedTimeSlots] = await Promise.all([\n        fetch(targetUrl, {\n            method: \"POST\",\n            headers: {\n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\"\n            },\n            body: requestBody,\n            credentials: \"include\"\n        }),\n        fetchSemesterStartDate(academicYear, semesterCode),\n        fetchTimeSlots(academicYear, semesterCode)\n    ]);\n\n    try {\n        if (courseResponse.ok) {\n            const jsonText = await courseResponse.text();\n            const jsonData = JSON.parse(jsonText);\n            if (jsonData && jsonData.kbList) {\n                const parsedCourses = parseJsonData(jsonData);\n                if (parsedCourses.length > 0) {\n                    return {\n                        courses: parsedCourses,\n                        config: {\n                            semesterStartDate: semesterStartDate,\n                            semesterTotalWeeks: 20\n                        },\n                        timeSlots: fetchedTimeSlots\n                    };\n                }\n            }\n        }\n    } catch (e) {\n        // 请求失败\n    }\n\n    window.shiguangBridge.showToast(\"未能获取课表数据，请检查网络环境或登录状态。\");\n    return null;\n}\n\nasync function saveCourses(parsedCourses) {\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        return false;\n    }\n}\n\n// 优先使用从教务系统接口动态获取的作息时间，获取失败时回退到此表\nconst FALLBACK_TIME_SLOTS = [\n    { number: 1, startTime: \"08:30\", endTime: \"09:15\" },\n    { number: 2, startTime: \"09:20\", endTime: \"10:05\" },\n    { number: 3, startTime: \"10:20\", endTime: \"11:05\" },\n    { number: 4, startTime: \"11:10\", endTime: \"11:55\" },\n    { number: 5, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 6, startTime: \"14:50\", endTime: \"15:35\" },\n    { number: 7, startTime: \"15:50\", endTime: \"16:35\" },\n    { number: 8, startTime: \"16:40\", endTime: \"17:25\" },\n    { number: 9, startTime: \"17:30\", endTime: \"18:15\" },\n    { number: 10, startTime: \"19:00\", endTime: \"19:45\" },\n    { number: 11, startTime: \"19:55\", endTime: \"20:40\" }\n];\n\nasync function importPresetTimeSlots(timeSlots) {\n    let finalTimeSlots = timeSlots;\n    let usedFallback = false;\n\n    if (!finalTimeSlots || finalTimeSlots.length === 0) {\n        // 动态获取失败，回退到硬编码保底方案\n        finalTimeSlots = FALLBACK_TIME_SLOTS;\n        usedFallback = true;\n    }\n\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(finalTimeSlots));\n        if (usedFallback) {\n            window.shiguangBridge.showToast(\"未获取到教务系统作息，已使用内置保底作息时间导入。\");\n        } else {\n            window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n        }\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n    }\n}\n\nasync function runImportFlow() {\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    const selection = await selectAcademicYearAndSemester();\n    if (!selection) {\n        window.shiguangBridge.showToast(\"未选择学年学期，导入流程终止。\");\n        return;\n    }\n\n    const { academicYear, semesterCode } = selection;\n\n    const result = await fetchAndParseCourses(academicYear, semesterCode);\n    if (result === null) {\n        return;\n    }\n\n    const { courses, config, timeSlots } = result;\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        return;\n    }\n    \n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        let configMsg = \"课表配置更新成功！\";\n        if (config.semesterStartDate) {\n            configMsg += ` 开学日期：${config.semesterStartDate}`;\n        }\n        window.shiguangBridge.showToast(configMsg);\n    } catch (error) {\n        window.shiguangBridge.showToast(`课表配置保存失败: ${error.message}`);\n    }\n\n    await importPresetTimeSlots(timeSlots);\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();","JUST":"// 江苏科技大学(just.edu.cn) 拾光课程表适配脚本\n// 教务系统：正方新一代教务（/jwglxt）\n// 校外访问：深信服 enlink WebVPN，统一身份认证 https://client.v.just.edu.cn/\n//   WebVPN 代理路径形如 /http/webvpn<hex>/jwglxt/...，<hex> 与登录会话相关不能写死，\n//   脚本从当前页面 URL 动态取前缀。\n// 课表页的学年/学期是 <select id=\"xnm\">（学年）/ <select id=\"xqm\">（学期），\n// 被 chosen 组件包装成 div#xnm_chosen / div#xqm_chosen（原 select 是容器的前一个兄弟节点）。\n// 脚本读出选项让用户确认，再请求课表、校历与校区作息。\n// 维护者：abyss-stars\n\n(async function () {\n    const bridge = window.shiguangBridgePromise;\n    const native = window.shiguangBridge;\n    if (!bridge || !native) return;\n    if (window.__justImportRunning) {\n        native.showToast('课表正在导入，请勿重复点击。');\n        return;\n    }\n    window.__justImportRunning = true;\n\n    const GNMKDM = 'N2151';\n    const API = {\n        course: '/kbcx/xskbcx_cxXsgrkb.html',\n        calendar: '/kbcx/xskbcxZccx_cxZcByXnxq.html',\n        timeSlots: '/kbcx/xskbcx_cxRjc.html'\n    };\n\n    // ---------- 1. 接口 ----------\n    // 校内直连是 https://<host>/jwglxt/...，WebVPN 下前面还有 /http/webvpn<hex>（<hex> 与会话相关）\n    const matched = (window.location.pathname || '').match(/^(.*?)\\/jwglxt(?:\\/|$)/i);\n    const BASE = (matched ? matched[1] : '') + '/jwglxt';\n\n    // enlink 网关下通常需要 enlink-vpn 标记，两种写法依次尝试\n    async function request(modulePath, params) {\n        const body = Object.keys(params)\n            .map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(params[key] == null ? '' : params[key])}`)\n            .join('&');\n\n        for (const suffix of [`?gnmkdm=${GNMKDM}&enlink-vpn`, `?gnmkdm=${GNMKDM}`]) {\n            try {\n                const response = await fetch(BASE + modulePath + suffix, {\n                    method: 'POST',\n                    credentials: 'include',\n                    headers: {\n                        'X-Requested-With': 'XMLHttpRequest',\n                        'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8'\n                    },\n                    body: body\n                });\n                if (!response.ok) continue;\n                const raw = await response.text();\n                const head = raw.replace(/^\\s+/, '').charAt(0);\n                // 非 JSON（例如被跳到登录页）就换下一种写法\n                if (head === '{' || head === '[') return JSON.parse(raw);\n            } catch (error) {\n                // 换下一种写法\n            }\n        }\n        return null;\n    }\n\n    // ---------- 2. 解析 ----------\n    const text = (value) => String(value == null ? '' : value).replace(/^\\s+|\\s+$/g, '');\n\n    // 周次：\"1-16周\"、\"1-16周(单)\"、\"1,3,5-9周\" 等\n    function parseWeeks(value) {\n        const weeks = new Set();\n        const normalized = text(value).replace(/\\s/g, '').replace(/[，、；;]/g, ',')\n            .replace(/（/g, '(').replace(/）/g, ')');\n\n        for (const part of normalized.split(',')) {\n            const odds = /单/.test(part);\n            const evens = /双/.test(part);\n            const digits = part.replace(/[^\\d-]/g, '');\n            const matched = digits.match(/^(\\d+)-(\\d+)$/) || digits.match(/^(\\d+)$/);\n            if (!matched) continue;\n\n            const start = Number(matched[1]);\n            const end = Number(matched[2] || matched[1]);\n            if (!(start > 0) || end < start) continue;\n            for (let week = start; week <= end; week++) {\n                if (odds && week % 2 === 0) continue;\n                if (evens && week % 2 !== 0) continue;\n                weeks.add(week);\n            }\n        }\n        return [...weeks].sort((a, b) => a - b);\n    }\n\n    // 节次：\"1-2\"、\"1\"、\"0102\"（部分部署补零）\n    function parseSections(value) {\n        const raw = text(value);\n        const hyphen = raw.match(/(\\d+)\\s*[-~—－]\\s*(\\d+)/);\n        if (hyphen) return [Number(hyphen[1]), Number(hyphen[2])];\n\n        const digits = raw.replace(/\\D/g, '');\n        if (!digits) return null;\n        if (digits.length === 4) return [Number(digits.slice(0, 2)), Number(digits.slice(2))];\n        return [Number(digits), Number(digits)];\n    }\n\n    function toMinutes(value) {\n        const matched = String(value == null ? '' : value).match(/^(\\d{1,2}):(\\d{2})$/);\n        return matched ? Number(matched[1]) * 60 + Number(matched[2]) : -1;\n    }\n\n    // 统一成 app 要求的 HH:mm\n    function padTime(value) {\n        const matched = String(value == null ? '' : value).match(/(\\d{1,2}):(\\d{2})/);\n        if (!matched) return '';\n        const hour = Number(matched[1]);\n        return hour > 23 ? '' : `${hour < 10 ? '0' : ''}${hour}:${matched[2]}`;\n    }\n\n    // 一条接口记录 -> 排课条目；没有固定星期/节次的（实践、网络课程等）返回 null\n    function toCourseEntry(raw) {\n        const name = text(raw.kcmc);\n        const day = Number(text(raw.xqj));\n        const weeks = parseWeeks(raw.zcd);\n        const sections = parseSections(text(raw.jcs) !== '' ? raw.jcs : raw.jc);\n        if (!name || !(day >= 1 && day <= 7) || !weeks.length || !sections) return null;\n        if (!(sections[0] > 0) || sections[1] < sections[0]) return null;\n\n        return {\n            campusId: text(raw.xqh_id) || '0',\n            campusName: text(raw.xqmc),\n            course: {\n                name: name,\n                teacher: text(raw.xm) || '未知教师',\n                position: text(raw.cdmc) || text(raw.cdbh) || '未排地点',\n                day: day,\n                startSection: sections[0],\n                endSection: sections[1],\n                weeks: weeks\n            }\n        };\n    }\n\n    // kbList 与 sjkList 通用：只取有固定星期与节次的记录，其余（实践课程、网络课程等）忽略\n    function collectCourses(list) {\n        const entries = [];\n        for (const raw of (Array.isArray(list) ? list : [])) {\n            const entry = toCourseEntry(raw);\n            if (entry) entries.push(entry);\n        }\n        return entries;\n    }\n\n    // 校区作息：jcmc=节次，qssj/jssj=起止时间\n    function parseTimeSlots(rows) {\n        const slots = [];\n        for (const row of (Array.isArray(rows) ? rows : [])) {\n            const number = Number(text(row.jcmc != null ? row.jcmc : row.jcdm));\n            const startTime = padTime(row.qssj);\n            const endTime = padTime(row.jssj);\n            if (!(number > 0) || !startTime || !endTime) continue;\n            if (toMinutes(startTime) >= toMinutes(endTime)) continue;\n            slots.push({ number: number, startTime: startTime, endTime: endTime });\n        }\n\n        slots.sort((a, b) => a.number - b.number);\n        // app 要求节次从 1 连续，否则整段丢弃\n        const continuous = slots.length > 0 && (() => {\n            for (let i = 0; i < slots.length; i++) {\n                if (slots[i].number !== i + 1) return false;\n            }\n            return true;\n        })();\n        return continuous ? slots : [];\n    }\n\n    // 学期校历：zs=周次，rq=\"起始日/结束日\"\n    function parseCalendar(rows) {\n        const weeks = [];\n        for (const row of (Array.isArray(rows) ? rows : [])) {\n            const number = Number(text(row.zs != null ? row.zs : row.zsmc));\n            const start = text(row.rq || row.zcrq || row.ksrq).split('/')[0];\n            if (number > 0 && /^\\d{4}-\\d{2}-\\d{2}$/.test(start)) weeks.push({ number: number, start: start });\n        }\n        if (!weeks.length) return null;\n\n        weeks.sort((a, b) => a.number - b.number);\n        const first = weeks[0];\n        return {\n            startDate: first.start,\n            // app 的 firstDayOfWeek 是 1=周一 … 7=周日\n            firstDayOfWeek: (new Date(`${first.start}T00:00:00Z`).getUTCDay() + 6) % 7 + 1,\n            totalWeeks: weeks[weeks.length - 1].number\n        };\n    }\n\n    // 教务处公布的作息时间表（接口取不到时兜底）\n    const FALLBACK_TIME_SLOTS = {\n        '长山': [[1, '08:30', '09:15'], [2, '09:20', '10:05'], [3, '10:25', '11:10'], [4, '11:15', '12:00'],\n            [5, '14:00', '14:45'], [6, '14:50', '15:35'], [7, '15:55', '16:40'], [8, '16:45', '17:30'],\n            [9, '18:30', '19:15'], [10, '19:20', '20:05']],\n        '梦溪': [[1, '08:00', '08:45'], [2, '08:55', '09:40'], [3, '10:00', '10:45'], [4, '10:55', '11:40'],\n            [5, '14:00', '14:45'], [6, '14:55', '15:40'], [7, '15:50', '16:35'], [8, '16:45', '17:30'],\n            [9, '19:00', '19:45'], [10, '19:55', '20:40'], [11, '20:50', '21:35']],\n        // 张家港取自 2026-2027-1 学期 xskbcx_cxRjc 接口实测（与梦溪不同）\n        '张家港': [[1, '08:00', '08:45'], [2, '08:55', '09:40'], [3, '10:00', '10:45'], [4, '10:55', '11:40'],\n            [5, '14:00', '14:45'], [6, '14:55', '15:40'], [7, '16:00', '16:45'], [8, '16:55', '17:40'],\n            [9, '19:00', '19:45'], [10, '19:55', '20:40'], [11, '20:50', '21:35']]\n    };\n\n    function fallbackSlots(campusName) {\n        for (const key of Object.keys(FALLBACK_TIME_SLOTS)) {\n            if (new RegExp(key).test(campusName)) {\n                return FALLBACK_TIME_SLOTS[key].map((item) => ({ number: item[0], startTime: item[1], endTime: item[2] }));\n            }\n        }\n        return null;\n    }\n\n    // 节次与周次合并去重（参考 wiki《课程合并与去重函数》）\n    function mergeCourses(courses) {\n        if (courses.length <= 1) return courses;\n\n        const sameCourse = (a, b) =>\n            a.name === b.name && a.teacher === b.teacher && a.position === b.position && a.day === b.day &&\n            !!a.isCustomTime === !!b.isCustomTime &&\n            (!a.isCustomTime || (a.customStartTime === b.customStartTime && a.customEndTime === b.customEndTime));\n\n        const list = courses.map((course) => Object.assign({}, course, {\n            weeks: [...course.weeks].sort((a, b) => a - b)\n        }));\n\n        list.sort((a, b) =>\n            a.name.localeCompare(b.name) || a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) || a.day - b.day ||\n            a.weeks.join(',').localeCompare(b.weeks.join(',')) || a.startSection - b.startSection);\n\n        const merged = [];\n        let current = list[0];\n        for (let i = 1; i < list.length; i++) {\n            const next = list[i];\n            const mergeable = sameCourse(current, next) && !current.isCustomTime &&\n                current.weeks.join(',') === next.weeks.join(',');\n\n            if (mergeable && current.endSection + 1 === next.startSection) {\n                current.endSection = next.endSection;                       // 连续节次：1-2 + 3-4 -> 1-4\n            } else if (mergeable && current.startSection === next.startSection &&\n                current.endSection === next.endSection) {\n                continue;                                                   // 完全重复\n            } else {\n                merged.push(current);\n                current = next;\n            }\n        }\n        merged.push(current);\n\n        // 同节次的周次合并（单周 + 双周 -> 全周）\n        merged.sort((a, b) =>\n            a.name.localeCompare(b.name) || a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) || a.day - b.day ||\n            a.startSection - b.startSection || a.endSection - b.endSection);\n\n        const result = [];\n        let head = merged[0];\n        for (let i = 1; i < merged.length; i++) {\n            const next = merged[i];\n            if (sameCourse(head, next) && head.startSection === next.startSection &&\n                head.endSection === next.endSection) {\n                head.weeks = [...new Set([...head.weeks, ...next.weeks])].sort((a, b) => a - b);\n            } else {\n                result.push(head);\n                head = next;\n            }\n        }\n        result.push(head);\n        return result;\n    }\n\n    // ---------- 3. 学年学期 ----------\n    // 学年/学期是 <select id=\"xnm\"> / <select id=\"xqm\">，chosen 组件会在其后插入 div#xnm_chosen 容器\n    function findTermSelect(name) {\n        const select = document.getElementById(name);\n        if (select) return select;\n        const chosen = document.getElementById(name + '_chosen');\n        const sibling = chosen ? chosen.previousElementSibling : null;\n        return sibling && sibling.tagName === 'SELECT' ? sibling : null;\n    }\n\n    function readSelectOptions(name) {\n        const select = findTermSelect(name);\n        const options = [];\n        if (!select) return options;\n        // 注意：教务页面改写了 Array.prototype.filter/some/every（回调实参变成下标），\n        // 所以这里全部用普通循环，不调用这些方法。\n        for (const option of Array.from(select.options)) {\n            const value = text(option.value);\n            if (value === '') continue;\n            options.push({\n                value: value,\n                text: text(option.textContent) || value,\n                selected: option.selected === true\n            });\n        }\n        return options;\n    }\n\n    // 默认选中教务当前学年学期，没有标记则取第一项\n    function defaultIndex(options) {\n        for (let i = 0; i < options.length; i++) {\n            if (options[i].selected) return i;\n        }\n        return 0;\n    }\n\n    async function selectTerm() {\n        const yearOptions = readSelectOptions('xnm');\n        const semesterOptions = readSelectOptions('xqm');\n        if (!yearOptions.length || !semesterOptions.length) {\n            await bridge.showAlert('读取学年学期失败',\n                '未在页面中找到学年(.xnm)/学期(.xqm)下拉。\\n请确认：\\n' +\n                '1. 已登录教务系统（校外需先登录 WebVPN）；\\n' +\n                '2. 当前停留在「信息查询-学生课表查询」页面。', '知道了');\n            return null;\n        }\n\n        const yearIndex = await bridge.showSingleSelection('选择学年',\n            JSON.stringify(yearOptions.map((item) => item.text)), defaultIndex(yearOptions));\n        if (yearIndex === null || yearIndex === -1) return null;\n\n        const semesterIndex = await bridge.showSingleSelection('选择学期',\n            JSON.stringify(semesterOptions.map((item) => item.text)), defaultIndex(semesterOptions));\n        if (semesterIndex === null || semesterIndex === -1) return null;\n\n        return {\n            xnm: yearOptions[yearIndex].value,\n            xnmText: yearOptions[yearIndex].text,\n            xqm: semesterOptions[semesterIndex].value,\n            xqmText: semesterOptions[semesterIndex].text\n        };\n    }\n\n    // 返回该校区节次作息数组；接口取不到时用教务处公布的作息，未知校区返回 null（跳过作息导入）\n    async function fetchTimeSlots(campus, term) {\n        if (campus.id !== '0') {\n            const slots = parseTimeSlots(await request(API.timeSlots,\n                Object.assign({ xqh_id: campus.id }, term)));\n            if (slots.length) return slots;\n        }\n        return fallbackSlots(campus.name);\n    }\n\n    // ---------- 4. 主流程 ----------\n    try {\n        if (!await bridge.showAlert('江苏科技大学课表导入',\n            '导入前请确保已登录教务系统。\\n校外需先登录 WebVPN（client.v.just.edu.cn），' +\n            '并进入教务系统页面（如「信息查询-学生课表查询」）。', '好的，开始导入')) {\n            native.showToast('用户取消了导入。');\n            return;\n        }\n\n        const term = await selectTerm();\n        if (!term) {\n            native.showToast('导入已取消。');\n            return;\n        }\n\n        native.showToast('正在获取课表数据…');\n        const params = { xnm: term.xnm, xqm: term.xqm };\n        const [courseData, calendarRows] = await Promise.all([\n            request(API.course, Object.assign({ kzlx: 'ck', xsdm: '', kclbdm: '', kclxdm: '' }, params)),\n            request(API.calendar, params)\n        ]);\n        const calendar = parseCalendar(calendarRows);\n        if (!courseData || !Array.isArray(courseData.kbList)) {\n            await bridge.showAlert('获取课表失败',\n                '教务系统未返回课表数据，请确认已登录、且当前在教务系统页面内。', '知道了');\n            return;\n        }\n\n        // sjkList 是实践/集中教学安排，其中带星期与节次的同样可以排进课表\n        const entries = collectCourses(courseData.kbList).concat(collectCourses(courseData.sjkList));\n        if (!entries.length) {\n            await bridge.showAlert('没有可导入的课程', '所选学期没有解析出已排课程。', '知道了');\n            return;\n        }\n\n        const campusMap = new Map();\n        for (const entry of entries) {\n            const campus = campusMap.get(entry.campusId) ||\n                { id: entry.campusId, name: entry.campusName, count: 0 };\n            campus.count++;\n            campusMap.set(entry.campusId, campus);\n        }\n        const campuses = [...campusMap.values()].sort((a, b) => b.count - a.count);\n\n        native.showToast('正在获取校区作息…');\n        const slotsMap = new Map();\n        await Promise.all(campuses.map(async (campus) => {\n            slotsMap.set(campus.id, await fetchTimeSlots(campus, params));\n        }));\n\n        let campusIndex = 0;\n        if (campuses.length > 1) {\n            const index = await bridge.showSingleSelection('选择默认作息校区',\n                JSON.stringify(campuses.map((campus) => `${campus.name || campus.id}（${campus.count} 条）`)), 0);\n            if (index === null || index === -1) {\n                native.showToast('导入已取消。');\n                return;\n            }\n            campusIndex = index;\n        }\n        const presetCampus = campuses[campusIndex];\n        const presetSlots = slotsMap.get(presetCampus.id) || null;\n\n        // 与默认作息不同的校区，课程改用自定义时间\n        const courses = entries.map((entry) => {\n            const course = Object.assign({}, entry.course);\n            const slots = slotsMap.get(entry.campusId) || presetSlots;\n            if (presetSlots && slots && JSON.stringify(slots) !== JSON.stringify(presetSlots)) {\n                const first = slots[course.startSection - 1];\n                const last = slots[course.endSection - 1];\n                if (first && last) {\n                    course.isCustomTime = true;\n                    course.customStartTime = first.startTime;\n                    course.customEndTime = last.endTime;\n                }\n            }\n            return course;\n        });\n        const merged = mergeCourses(courses);\n\n        // 课表配置\n        const maxWeek = Math.max(0, ...merged.map((course) => Math.max(...course.weeks)));\n        const config = { semesterTotalWeeks: Math.max(calendar ? calendar.totalWeeks : 0, maxWeek, 1) };\n        if (calendar) {\n            config.semesterStartDate = calendar.startDate;\n            config.firstDayOfWeek = calendar.firstDayOfWeek;\n        }\n        const firstWeekday = Number(text(courseData.qsxqj));\n        if (firstWeekday >= 1 && firstWeekday <= 7) config.firstDayOfWeek = firstWeekday;\n        if (presetSlots) {\n            const classDuration = toMinutes(presetSlots[0].endTime) - toMinutes(presetSlots[0].startTime);\n            if (classDuration > 0) config.defaultClassDuration = classDuration;\n            if (presetSlots.length > 1) {\n                const breakDuration = toMinutes(presetSlots[1].startTime) - toMinutes(presetSlots[0].endTime);\n                if (breakDuration > 0) config.defaultBreakDuration = breakDuration;\n            }\n        }\n\n        await bridge.saveImportedCourses(JSON.stringify(merged));\n        if (presetSlots) await bridge.savePresetTimeSlots(JSON.stringify(presetSlots));\n        await bridge.saveCourseConfig(JSON.stringify(config));\n\n        // 课表下方\"未确认上课节次\"的安排（实践课程、网络课程等）无法排进课表，直接忽略；\n        // 只有本校区作息没取到时才提示一次\n        if (!presetSlots) {\n            await bridge.showAlert('导入完成',\n                `${term.xnmText} 学年第 ${term.xqmText} 学期：已导入 ${merged.length} 条排课记录。\\n\\n` +\n                '未能读取本校区节次作息，已跳过作息导入，请在应用内手动设置节次时间。', '知道了');\n        }\n\n        native.showToast(`课程导入成功，共导入 ${merged.length} 条排课记录！`);\n        native.notifyTaskCompletion();\n    } catch (error) {\n        await bridge.showAlert('江苏科技大学课表导入失败', (error && error.message) || String(error), '知道了');\n    } finally {\n        delete window.__justImportRunning;\n    }\n})();\n","JXNU":"// 文件: JXNU.js\n// 功能：从江西师范大学系统获取课程表， 解析后导入到拾光课程表\n// 适配：江西师大教务系统\n// 维护者：glxgo\n\n// ---------- 常量配置 ----------\n\nconst UNIT_COUNT = 13; // 每天最大节次数\n\n// ---------- 全局验证函数 ----------\n\nfunction validateYearInput(input) {\n    if (/^\\d{4}$/.test(input)) return false;\n    return \"请输入四位数字的年份（例如 2024）\";\n}\n\nfunction validateWeeksInput(input) {\n    const num = parseInt(input, 10);\n    if (isNaN(num) || num < 1 || num > 55) return \"请输入 1-55 之间的有效周数\";\n    return false;\n}\n\n// ---------- 单元格文本解析 ----------\n\n/**\n * 从课程格子文本中提取课程名、教师、教室\n * 输入例如：\"军事理论(W7103)合班吕俊.4班\"\n */\nfunction parseCellText(line) {\n    line = line.trim();\n    if (line.length < 3) return null;\n\n    let room = '', name = '', teacher = '';\n\n    const rmMatch = line.match(/\\(([^)]+)\\)/);\n    if (rmMatch) {\n        room = rmMatch[1].trim();\n        name = line.substring(0, line.indexOf('(' + rmMatch[1] + ')')).trim();\n        const after = line.substring(\n            line.indexOf('(' + rmMatch[1] + ')') + rmMatch[1].length + 2\n        ).trim();\n\n        const hbMatch = after.match(/合班(.+?)(?:$|\\.\\d+班|\\s)/);\n        if (hbMatch) teacher = hbMatch[1].trim();\n\n        if (!teacher) {\n            const jgMatch = after.match(/教工(.+?)(?:#|$|\\s)/);\n            if (jgMatch) teacher = jgMatch[1].trim();\n        }\n\n        if (!teacher && after.length > 0 && !after.match(/^\\d+班$/)) {\n            teacher = after.replace(/\\.\\d+班$/, '').trim();\n        }\n    } else {\n        name = line;\n    }\n\n    name = name.replace(/\\s+/g, '');\n    if (!/[\\u4e00-\\u9fa5a-zA-Z]/.test(name)) return null;\n    if (name.length > 50) name = name.substring(0, 50);\n\n    return { name, teacher, room };\n}\n\n/**\n * 判断单元格文本是否是\"节次标签\"\n */\nfunction isPeriodLabel(text) {\n    const t = text.trim();\n    if (!t) return false;\n\n    const cleaned = t.replace(/\\s+/g, '');\n    const normalized = cleaned.replace(/^第/, '').replace(/节$/, '');\n\n    if (/^[1-9]$/.test(normalized)) return true;\n    if (/^(1[0-3]?)$/.test(normalized) && parseInt(normalized) <= UNIT_COUNT) return true;\n\n    const rangeMatch = normalized.match(/^(\\d{1,2})(?:[-–—~～,]|至)(\\d{1,2})$/);\n    if (rangeMatch) {\n        const s = parseInt(rangeMatch[1]);\n        const e = parseInt(rangeMatch[2]);\n        if (s >= 1 && e <= UNIT_COUNT && s <= e) return true;\n    }\n\n    const rawTokens = (t.match(/\\d{1,2}/g) || []).map(n => parseInt(n, 10));\n    if (rawTokens.length >= 2 && rawTokens.every(n => n >= 1 && n <= UNIT_COUNT)) {\n        const stripped = t.replace(/\\d{1,2}/g, '').replace(/[第节\\s]/g, '');\n        if (!stripped) return true;\n    }\n\n    if (t.includes('晚') && (t.includes('上') || t.includes('自'))) return true;\n    return false;\n}\n\n/**\n * 从节次标签文本解析出节次数字数组\n * \"1\" → [1], \"3-4\" → [3,4], \"第6-7节\" → [6,7], \"6 7\" → [6,7], \"晚上\" → [10,11,12]\n */\nfunction parsePeriodText(text) {\n    const t = text.trim();\n    if (!t) return [];\n    if (t.includes('晚') && (t.includes('上') || t.includes('自'))) return [10, 11, 12];\n\n    const rawTokens = (t.match(/\\d{1,2}/g) || [])\n        .map(n => parseInt(n, 10))\n        .filter(n => n >= 1 && n <= UNIT_COUNT);\n    if (rawTokens.length >= 2) {\n        const stripped = t.replace(/\\d{1,2}/g, '').replace(/[第节\\s]/g, '');\n        if (!stripped) {\n            const nums = [...new Set(rawTokens)].sort((a, b) => a - b);\n            if (nums[nums.length - 1] - nums[0] + 1 === nums.length) return nums;\n        }\n    }\n\n    // 优先检查原始文本中是否有换行或空白分隔符（如 \"1\\n2\"）\n    // 按 \\n 或空白分割，每个部分独立解析为单个节次\n    if (t.includes('\\n') || t.includes('\\r') || /\\s{2,}/.test(t)) {\n        const parts = t.split(/[\\n\\r]+/).map(s => s.trim()).filter(s => s.length > 0);\n        if (parts.length >= 2) {\n            const nums = [];\n            for (const p of parts) {\n                const n = parseInt(p, 10);\n                if (n >= 1 && n <= UNIT_COUNT && !nums.includes(n)) nums.push(n);\n            }\n            if (nums.length >= 2) { nums.sort((a, b) => a - b); return nums; }\n        }\n    }\n\n    const cleaned = t.replace(/\\s+/g, '');\n    const normalized = cleaned.replace(/^第/, '').replace(/节$/, '');\n\n    const rangeMatch = normalized.match(/^(\\d{1,2})(?:[-–—~～,]|至)(\\d{1,2})$/);\n    if (rangeMatch) {\n        const start = parseInt(rangeMatch[1], 10);\n        const end = parseInt(rangeMatch[2], 10);\n        if (start >= 1 && end <= UNIT_COUNT && start <= end) {\n            const result = [];\n            for (let i = start; i <= end; i++) result.push(i);\n            return result;\n        }\n    }\n\n    const singleMatch = normalized.match(/^(\\d{1,2})$/);\n    if (singleMatch) {\n        const num = parseInt(singleMatch[1], 10);\n        if (num >= 1 && num <= UNIT_COUNT) return [num];\n    }\n\n    const nums = (normalized.match(/\\d{1,2}/g) || [])\n        .map(n => parseInt(n, 10))\n        .filter(n => n >= 1 && n <= UNIT_COUNT);\n    if (nums.length > 0) {\n        return [...new Set(nums)].sort((a, b) => a - b);\n    }\n    return [];\n}\n\n// ---------- DOM 解析（当前页面） ----------\n\n/**\n * 在指定 window 对象中递归查找课表表格。\n * 匹配条件：表格第一行（表头）必须包含\"星期一\"且至少有 7 列（周一到周日）。\n * 支持表格位于 iframe 内的情况。\n */\nfunction findCourseTable(win) {\n    try {\n        for (const t of win.document.querySelectorAll('table')) {\n            // 初级筛选：表格内容要包含\"星期一\"\n            if (!t.textContent.includes('星期一')) continue;\n            // 中级筛选：表格第一行必须有至少 7 列\n            if (t.rows.length === 0) continue;\n            const firstRow = t.rows[0];\n            if (firstRow.cells.length < 7) continue;\n            // 高级筛选：第一行某列确实包含\"星期一\"文本\n            let hasMondayHeader = false;\n            for (let c = 0; c < firstRow.cells.length; c++) {\n                if (firstRow.cells[c].textContent.includes('星期一')) {\n                    hasMondayHeader = true;\n                    break;\n                }\n            }\n            if (hasMondayHeader) return t;\n        }\n    } catch (e) {\n        // 跨域 iframe 无法访问，跳过\n    }\n    // 递归查找 iframe\n    try {\n        for (let i = 0; i < win.frames.length; i++) {\n            const found = findCourseTable(win.frames[i]);\n            if (found) return found;\n        }\n    } catch (e) {\n        // 跨域 iframe 无法访问，跳过\n    }\n    return null;\n}\n\n/**\n * 从当前页面的 DOM 中，用 table.rows API 提取课程数据。\n *\n * 核心差异（对比旧脚本的 querySelectorAll 平铺方案）：\n *   旧脚本用 gridTable.querySelectorAll('td, th') 获取所有格子的扁平列表，\n *   在有 rowspan 时索引会错位，导致课程落到错误的星期列。\n *\n *   本方案用 table.rows[r].cells[c]——浏览器原生处理 rowspan，\n *   rowspan 覆盖的格在下一行的 cells 中自动消失，不需要手动追踪。\n */\nfunction parseCourseTableFromCurrentPage() {\n    const courses = [];\n    const dayNames = ['星期一', '星期二', '星期三', '星期四', '星期五', '星期六', '星期日'];\n\n    const table = findCourseTable(window);\n    if (!table) {\n        console.warn(\"[JXNU] 未找到课表表格\");\n        return { courses, html: '' };\n    }\n\n    const pageHtml = document.documentElement.outerHTML;\n    const rows = table.rows;\n    if (rows.length < 3) {\n        console.warn(\"[JXNU] 课表格行数不足:\", rows.length);\n        return { courses, html: pageHtml };\n    }\n\n    let headerRowIdx = -1;\n    for (let i = 0; i < Math.min(rows.length, 3); i++) {\n        const rowText = rows[i].textContent.trim();\n        if (dayNames.some(d => rowText.includes(d))) {\n            headerRowIdx = i;\n            break;\n        }\n    }\n    if (headerRowIdx < 0) {\n        console.warn(\"[JXNU] 未找到课表表头行\");\n        return { courses, html: pageHtml };\n    }\n\n    const headerRow = rows[headerRowIdx];\n    const totalCols = headerRow.cells.length;\n    console.log(`[JXNU] 表头共 ${totalCols} 列`);\n\n    // 定位\"星期一\"所在列\n    let firstDayCol = -1;\n    for (let c = 0; c < totalCols; c++) {\n        const t = headerRow.cells[c].textContent.trim().replace(/\\s+/g, '');\n        console.log(`[JXNU]   列 ${c}: \"${t}\"`);\n        if (t.includes('星期一')) firstDayCol = c;\n    }\n    if (firstDayCol < 0) {\n        console.warn(\"[JXNU] 未找到星期一的表头列\");\n        return { courses, html: pageHtml };\n    }\n\n    // dayColMap: 表头列索引 → 星期几\n    const dayColMap = {};\n    for (let c = firstDayCol; c < totalCols && c - firstDayCol < 7; c++) {\n        dayColMap[c] = c - firstDayCol + 1;\n    }\n    console.log(`[JXNU] 星期一在列 ${firstDayCol}，dayColMap:`, JSON.stringify(dayColMap));\n\n    // periodLabelCol = 星期一的前一列\n    const periodLabelCol = firstDayCol - 1;\n    console.log(`[JXNU] periodLabelCol=${periodLabelCol}`);\n\n    // rowspan 追踪\n    const rowspanActive = new Array(totalCols).fill(0);\n    let totalPeriodRows = 0;\n\n    for (let r = headerRowIdx + 1; r < rows.length; r++) {\n        const row = rows[r];\n        const cells = row.cells;\n        if (cells.length < 2) {\n            console.log(`[JXNU]   行 ${r}: 只有 ${cells.length} 格（分隔行）`);\n        }\n\n        // ---- 用 Column-pass 算法遍历 ----\n        // 必须完整扫过每一列表头位，哪怕当前行可见单元格已经用完，\n        // 否则末尾列的 rowspan 不会在这一行递减，后续行会整体错位。\n        let periodText = '', foundPeriod = false;\n        let periods = [], courseData = [];\n        let cellIdx = 0;\n\n        for (let col = 0; col < totalCols; col++) {\n            if (rowspanActive[col] > 0) {\n                rowspanActive[col]--;\n                continue;\n            }\n\n            if (cellIdx >= cells.length) continue;\n\n            const cell = cells[cellIdx++];\n            if (cell.rowSpan > 1) rowspanActive[col] = cell.rowSpan - 1;\n\n            const text = cell.textContent.trim();\n\n            // 方案A：如果 col == periodLabelCol，用列位置判断\n            // 方案B：同时检查 col > periodLabelCol 的短表格情况\n            if (col === periodLabelCol) {\n                if (text && isPeriodLabel(text)) {\n                    periodText = text; periods = parsePeriodText(text);\n                    foundPeriod = periods.length > 0;\n                }\n                if (foundPeriod) console.log(`[JXNU]   行${r} period: \"${text.replace(/\\s+/g,' ')}\" → [${periods}]`);\n            }\n\n            // 如果是课程列，尝试从中提取课程名（用 isPeriodLabel 排除误判）\n            if (dayColMap[col] && text && text.length >= 2 && text !== '\\u00a0') {\n                const cleanText = text.replace(/\\s+/g, '');\n                const skipWords = ['上午', '下午', '晚上', '中午', '中 午', '午休', '节次'];\n                if (!skipWords.includes(cleanText) && text.length > 2) {\n                    courseData.push({ cell, text, day: dayColMap[col] });\n                    console.log(`[JXNU]   行${r} col${col}(周${dayColMap[col]}): \"${text.replace(/\\s+/g,' ').substring(0,60)}\"`);\n                }\n            }\n        }\n\n        // 如果没找到 period → 尝试方案C：扫描当前行所有格找 period\n        if (!foundPeriod) {\n            for (let ci = 0; ci < cells.length; ci++) {\n                const t = cells[ci].textContent.trim();\n                if (t && isPeriodLabel(t)) {\n                    periodText = t; periods = parsePeriodText(t);\n                    foundPeriod = periods.length > 0;\n                    console.log(`[JXNU]   行${r} [方案C] 扫描找到 period: \"${t.replace(/\\s+/g,' ')}\" 在 cell[${ci}]`);\n                    break;\n                }\n            }\n        }\n\n        if (!foundPeriod) {\n            console.log(`[JXNU]   行${r}: 未找到节次标签`);\n            continue;\n        }\n\n        totalPeriodRows++;\n        let rowCount = 0;\n\n        for (const { cell, text, day } of courseData) {\n            let name = '', teacher = '', room = '';\n            const titleEl = cell.querySelector('.title font, .title');\n\n            if (titleEl) {\n                name = titleEl.textContent.trim();\n                if (/[\\u4e00-\\u9fa5a-zA-Z]/.test(name)) {\n                    const pEls = cell.querySelectorAll('p font');\n                    if (pEls.length >= 2) room = pEls[1].textContent.trim();\n                    if (pEls.length >= 3) teacher = pEls[2].textContent.trim();\n                    if (!room && pEls.length >= 1) {\n                        const t = pEls[0].textContent.trim();\n                        if (/[楼馆教栋区斋轩堂室]/.test(t)) room = t;\n                    }\n                } else { name = ''; }\n            }\n\n            if (!name) {\n                const parsed = parseCellText(text);\n                if (!parsed || !parsed.name) {\n                    console.log(`[JXNU]     parseCellText失败: \"${text.replace(/\\s+/g,' ').substring(0,60)}\"`);\n                    continue;\n                }\n                name = parsed.name; teacher = parsed.teacher || teacher; room = parsed.room || room;\n            }\n\n            name = name.replace(/\\s+/g, '');\n            if (!/[\\u4e00-\\u9fa5a-zA-Z]/.test(name)) continue;\n\n            courses.push({ name, teacher: teacher || '', position: room || '',\n                day, startSection: periods[0], endSection: periods[periods.length - 1], weeks: [] });\n            rowCount++;\n        }\n        console.log(`[JXNU]   行${r}: 解析到 ${rowCount} 门课`);\n    }\n\n    console.log(`[JXNU] 共 ${totalPeriodRows} 行数据`);\n\n    const seen = new Set();\n    const deduped = [];\n    for (const c of courses) {\n        const key = `${c.name}|${c.day}|${c.startSection}|${c.endSection}|${c.teacher}|${c.position}`;\n        if (!seen.has(key)) { seen.add(key); deduped.push(c); }\n    }\n\n    console.log(`[JXNU] 完成: ${courses.length} → ${deduped.length} 条`);\n    return { courses: deduped, html: pageHtml };\n}\n\n// ---------- 时间段配置 ----------\n\nfunction getTimeSlots() {\n    return [\n        { number: 1, startTime: \"08:00\", endTime: \"08:40\" },\n        { number: 2, startTime: \"08:50\", endTime: \"09:30\" },\n        { number: 3, startTime: \"09:40\", endTime: \"10:20\" },\n        { number: 4, startTime: \"10:30\", endTime: \"11:10\" },\n        { number: 5, startTime: \"11:20\", endTime: \"12:00\" },\n        { number: 6, startTime: \"14:00\", endTime: \"14:40\" },\n        { number: 7, startTime: \"14:50\", endTime: \"15:30\" },\n        { number: 8, startTime: \"15:40\", endTime: \"16:20\" },\n        { number: 9, startTime: \"16:30\", endTime: \"17:10\" },\n        { number: 10, startTime: \"19:00\", endTime: \"19:40\" },\n        { number: 11, startTime: \"19:50\", endTime: \"20:30\" },\n        { number: 12, startTime: \"20:40\", endTime: \"21:20\" },\n    ];\n}\n\n// ---------- 用户交互 ----------\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"江西师范大学 课表导入\",\n        \"请确认：\\n1. 已在浏览器中登录教务系统\\n2. 已进入学生课表查询页面并选择了正确的学年学期\\n3. 已点击【查询】按钮，课表已正常显示\\n\\n点击确定开始导入。\",\n        \"确定，开始导入\"\n    );\n}\n\nasync function getTotalWeeks() {\n    return await window.shiguangBridgePromise.showPrompt(\n        \"设置本学期总周数\",\n        \"请输入本学期总周数（默认 20，范围 1-55）:\",\n        \"20\",\n        \"validateWeeksInput\"\n    );\n}\n\n// ---------- 主流程 ----------\n\nasync function run() {\n    try {\n        const confirmed = await promptUserToStart();\n        if (!confirmed) { window.shiguangBridge.showToast(\"用户取消了导入。\"); return; }\n\n        const weeksInput = await getTotalWeeks();\n        if (weeksInput === null) { window.shiguangBridge.showToast(\"导入已取消。\"); return; }\n        const totalWeeks = parseInt(weeksInput, 10);\n        if (isNaN(totalWeeks) || totalWeeks < 1) { window.shiguangBridge.showToast(\"周数设置无效。\"); return; }\n        const defaultWeeks = Array.from({ length: totalWeeks }, (_, i) => i + 1);\n\n        window.shiguangBridge.showToast(\"正在解析课表数据...\");\n        const { courses: parsedCourses, html: pageHtml } = parseCourseTableFromCurrentPage();\n\n        if (parsedCourses.length === 0) {\n            // 解析失败时给出更具体的提示\n            let detail = \"\";\n            if (!pageHtml.includes('星期一')) {\n                detail = '当前页面不包含课表表格。请确认：\\n' +\n                    '1. 已进入学生课表查询页面\\n' +\n                    '2. 已选择学年学期并点击【查询】\\n' +\n                    '3. 课表已正常显示（页面中能看到\"星期一\"表头）';\n            } else if (pageHtml.includes('星期一') && document.querySelectorAll('table').length > 0) {\n                detail = '已找到包含\"星期一\"的课表表格，但未能从中解析出有效的课程数据。\\n' +\n                    '请确认已从下拉菜单中选择了正确的学年学期，并点击了【查询/确定】按钮。\\n\\n' +\n                    '常见问题：\\n' +\n                    '1. 页面加载后未点击【查询】按钮\\n' +\n                    '2. 当前学期没有课程安排（课表空白）\\n' +\n                    '3. 选错了学年或学期';\n            } else {\n                detail = '未能在当前页面中找到课表数据。\\n' +\n                    '请确认已在学生课表查询页面正确选择了学期并点击了【查询】。';\n            }\n            await window.shiguangBridgePromise.showAlert(\"未解析到课程\", detail, \"确定\");\n            return;\n        }\n\n        const coursesWithWeeks = parsedCourses.map(c => ({\n            name: c.name, teacher: c.teacher, position: c.position,\n            day: c.day, startSection: c.startSection, endSection: c.endSection,\n            weeks: c.weeks.length > 0 ? c.weeks : defaultWeeks,\n        }));\n\n        try {\n            await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(coursesWithWeeks));\n            window.shiguangBridge.showToast(`课程数据已导入（共 ${coursesWithWeeks.length} 条）`);\n        } catch (saveErr) {\n            console.error(\"[JXNU] 保存课程失败:\", saveErr);\n            await window.shiguangBridgePromise.showAlert(\"保存课程失败\", saveErr.message || String(saveErr), \"确定\");\n            return;\n        }\n\n        const timeSlots = getTimeSlots();\n        try {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n            window.shiguangBridge.showToast(\"时间段数据已导入\");\n        } catch (slotErr) {\n            console.error(\"[JXNU] 保存时间段失败:\", slotErr);\n            window.shiguangBridge.showToast(`时间段保存失败：${slotErr.message}`);\n        }\n\n        window.shiguangBridge.showToast(\"导入完成！\");\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (err) {\n        console.error(\"[JXNU] 导入流程出错:\", err);\n        try {\n            await window.shiguangBridgePromise.showAlert(\"导入失败\", `未知错误：${err.message || err}\\n\\n请联系开发者。`, \"确定\");\n        } catch (_) {}\n        window.shiguangBridge.notifyTaskCompletion();\n    }\n}\n\nrun();\n","JXUST":"// 江西理工大学(jxust.edu.cn)拾光课程表适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提联系开发者或者提交pr更改,这更加快速\n\n// 预设节次时间\nconst TimeSlots = [\n    { \"number\": 1, \"startTime\": \"08:30\", \"endTime\": \"09:15\" },\n    { \"number\": 2, \"startTime\": \"09:20\", \"endTime\": \"10:05\" }, \n    { \"number\": 3, \"startTime\": \"10:25\", \"endTime\": \"11:10\" }, \n    { \"number\": 4, \"startTime\": \"11:15\", \"endTime\": \"12:00\" },\n    { \"number\": 5, \"startTime\": \"14:00\", \"endTime\": \"14:45\" }, \n    { \"number\": 6, \"startTime\": \"14:50\", \"endTime\": \"15:35\" },\n    { \"number\": 7, \"startTime\": \"15:55\", \"endTime\": \"16:40\" }, \n    { \"number\": 8, \"startTime\": \"16:45\", \"endTime\": \"17:30\" },\n    { \"number\": 9, \"startTime\": \"19:00\", \"endTime\": \"19:45\" }, \n    { \"number\": 10, \"startTime\": \"19:50\", \"endTime\": \"20:35\" }\n];\n\n// 课表配置\nconst CourseConfig = {\n    \"semesterTotalWeeks\": 20 \n};\n\n// 解析周次 (parseWeeks)\nfunction parseWeeks(weeksStr) {\n    const weeks = [];\n    if (!weeksStr) return weeks;\n    const cleanedStr = weeksStr.replace(/\\(周\\)|\\[.*?节\\]|<\\/?[a-z]+[^>]*>/ig, '').trim(); \n    if (cleanedStr === '') return weeks;\n\n    cleanedStr.split(',').forEach(part => {\n        const rangeMatch = part.match(/^(\\d+)-(\\d+)$/);\n        if (rangeMatch) {\n            const start = parseInt(rangeMatch[1]);\n            const end = parseInt(rangeMatch[2]);\n            for (let i = start; i <= end; i++) {\n                weeks.push(i);\n            }\n        } else {\n            const singleWeek = parseInt(part);\n            if (!isNaN(singleWeek)) {\n                weeks.push(singleWeek);\n            }\n        }\n    });\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n// 核心解析函数 (parseCourseTable)\nfunction parseCourseTable(htmlContent) {\n    const parser = new DOMParser();\n    const doc = parser.parseFromString(htmlContent, \"text/html\");\n    const courseList = [];\n\n    const table = doc.getElementById('kbtable');\n    if (!table) {\n        window.shiguangBridge.showToast(\"错误：未找到课表表格 (id=kbtable)。\");\n        return [];\n    }\n    \n    // 节次映射\n    const sectionMap = [\n        { start: 1, end: 2 },  \n        { start: 3, end: 4 },  \n        { start: 5, end: 6 },  \n        { start: 7, end: 8 },  \n        { start: 9, end: 10 }  \n    ];\n\n    const rows = table.querySelectorAll('tr');\n    \n    for (let i = 1; i < rows.length; i++) {\n        const row = rows[i];\n        const mapIndex = i - 1; \n        if (mapIndex >= sectionMap.length) continue; \n        const sections = sectionMap[mapIndex];\n        \n        const cells = row.querySelectorAll('td');\n\n        for (let j = 0; j < cells.length; j++) {\n            const cell = cells[j];\n            const dayOfWeek = j + 1; \n            const detailDiv = cell.querySelectorAll('div')[1]; \n            \n            if (!detailDiv) continue; \n\n            const rawContent = detailDiv.innerHTML.trim();\n            if (rawContent === '' || rawContent.replace(/&nbsp;|<[^>]*>/ig, '').trim() === '') continue; \n\n            // 多个课程块以分隔符处理\n            const courseBlocks = rawContent.split('---------------------<br>');\n            \n            courseBlocks.forEach(blockHtml => {\n                if (blockHtml.trim() === '') return;\n                \n                const cleanedBlock = blockHtml.replace(/<br\\/?>/gi, '\\n').trim();\n                \n                const nameMatch = cleanedBlock.match(/^(.*?)\\n/);\n                let name = (nameMatch && nameMatch[1].trim()) || \"未知课程\";\n                name = name.replace(/<span[^>]*>.*?<\\/span>|<\\/?[a-z]+[^>]*>/ig, '').trim(); \n                \n                const teacherMatch = cleanedBlock.match(/<font title=\"老师\">([^<]+?)<\\/font>/i);\n                const teacher = (teacherMatch && teacherMatch[1].trim()) || \"暂无教师\";\n\n                const positionMatch = cleanedBlock.match(/<font title=\"教室\">([^<]+?)<\\/font>/i);\n                const position = (positionMatch && positionMatch[1].trim()) || \"暂无教室\";\n\n                const weeksSectionMatch = cleanedBlock.match(/<font title=\"周次\\(节次\\)\">([^<]+?)<\\/font>/i);\n                const weeksSectionStr = (weeksSectionMatch && weeksSectionMatch[1].trim()) || \"\";\n\n                const weeksArray = parseWeeks(weeksSectionStr);\n                \n                if (weeksArray.length === 0) {\n                    return; \n                }\n\n                const course = {\n                    name: name,\n                    teacher: teacher,\n                    position: position,\n                    day: dayOfWeek,             \n                    startSection: sections.start,\n                    endSection: sections.end,\n                    weeks: weeksArray\n                };\n                \n                courseList.push(course);\n            });\n        }\n    }\n    \n    return courseList;\n}\n\n// 网络请求函数\nasync function fetchCourseHtml() {\n    window.shiguangBridge.showToast(\"正在获取课表数据...\");\n    const URL = \"https://jw.jxust.edu.cn/jsxsd/xskb/xskb_list.do\";\n    try {\n        const response = await fetch(URL, {\n            \"method\": \"GET\",\n            \"credentials\": \"include\"\n        });\n        \n        if (!response.ok) {\n            throw new Error(`网络请求失败，状态码: ${response.status}`);\n        }\n        \n        const text = await response.text();\n        \n        window.shiguangBridge.showToast(\"课表数据获取成功，开始解析...\");\n        return text;\n    } catch (error) {\n        window.shiguangBridge.showToast(`网络请求异常: ${error.message}`);\n        return null;\n    }\n}\n\n\nasync function importPresetTimeSlots() {\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(TimeSlots));\n        window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n        return false; \n    }\n}\n\nasync function saveConfig() {\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(CourseConfig));\n        window.shiguangBridge.showToast(\"课表配置更新成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"保存配置失败: \" + error.message);\n        return false;\n    }\n}\n\nasync function saveCourses(parsedCourses) {\n    if (parsedCourses.length === 0) {\n        window.shiguangBridge.showToast(\"未解析到任何课程数据，跳过保存。\");\n        return true;\n    }\n    \n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses));\n        window.shiguangBridge.showToast(`成功导入 ${parsedCourses.length} 门课程！`);\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`保存失败: ${error.message}`);\n        return false;\n    }\n}\n\nasync function runImportFlow() {\n    \n    const LOGIN_URL_START = \"https://authserver.jxust.edu.cn/authserver/login\";\n    if (window.location.href.startsWith(LOGIN_URL_START)) {\n        window.shiguangBridge.showToast(\"错误：当前页面为登录页，请先完成登录后再尝试导入！\");\n        return;\n    }\n\n    const alertConfirmed = await window.shiguangBridgePromise.showAlert(\n        \"开始导入\",\n        \"请确保您已登录教务系统\",\n        \"确定\"\n    );\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    // 获取 HTML\n    const htmlContent = await fetchCourseHtml();\n    if (htmlContent === null) {\n        window.shiguangBridge.showToast(\"导入终止。\");\n        return; \n    }\n    \n    // 解析课程数据\n    const parsedCourses = parseCourseTable(htmlContent);\n    \n    if (parsedCourses.length === 0) {\n        window.shiguangBridge.showToast(\"解析失败或未发现有效课程。导入终止。\");\n        return;\n    }\n    \n    // 导入时间段数据\n    await importPresetTimeSlots(); \n\n    // 导入课表配置\n    if (!await saveConfig()) return;\n\n    // 课程数据保存\n    if (!await saveCourses(parsedCourses)) return;\n\n    // 流程成功\n    window.shiguangBridge.showToast(\"所有任务已完成！课表已导入成功！\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\n// 启动导入流程\nrunImportFlow();","JHZYEDU_01":"// 江西航空职业技术学院(jhzyedu.cn) 拾光课程表适配脚本\n// 正方教务系统V9.0 API适配方案\n// 参考：GDUST广东科技学院适配案例\n\n/**\n * 解析周次字符串，处理单双周和周次范围。\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    const weekSets = weekStr.split(',');\n    let weeks = [];\n\n    for (const set of weekSets) {\n        const trimmedSet = set.trim();\n\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周/);\n\n        let start = 0;\n        let end = 0;\n        let processed = false;\n\n        if (rangeMatch) {\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) {\n            start = end = Number(singleMatch[1]);\n            processed = true;\n        }\n        \n        if (processed) {\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue;\n                if (isDouble && w % 2 !== 0) continue;\n                weeks.push(w);\n            }\n        }\n    }\n\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 解析 API 返回的 JSON 数据。\n */\nfunction parseJsonData(jsonData) {\n    console.log(\"JS: parseJsonData 正在解析 JSON 数据...\");\n    \n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        console.warn(\"JS: JSON 数据结构错误或缺少 kbList 字段。\");\n        return []; \n    }\n\n    const rawCourseList = jsonData.kbList;\n    const finalCourseList = [];\n\n    for (const rawCourse of rawCourseList) {\n        if (!rawCourse.kcmc || !rawCourse.xm || !rawCourse.cdmc || \n            !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) {\n            continue;\n        }\n\n        const weeksArray = parseWeeks(rawCourse.zcd);\n        \n        if (weeksArray.length === 0) {\n            continue;\n        }\n        \n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]); \n\n        const day = Number(rawCourse.xqj);\n        \n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) || day < 1 || day > 7 || startSection > endSection) {\n            continue;\n        }\n\n        finalCourseList.push({\n            name: rawCourse.kcmc.trim(),\n            teacher: rawCourse.xm.trim(),\n            position: rawCourse.cdmc.trim(),\n            day: day, \n            startSection: startSection,\n            endSection: endSection, \n            weeks: weeksArray\n        });\n    }\n\n    finalCourseList.sort((a, b) =>\n        a.day - b.day ||\n        a.startSection - b.startSection ||\n        a.name.localeCompare(b.name)\n    );\n    \n    console.log(`JS: JSON 数据解析完成，共找到 ${finalCourseList.length} 门课程。`);\n    return finalCourseList;\n}\n\nfunction validateYearInput(input) {\n    if (/^[0-9]{4}$/.test(input)) {\n        return false;\n    } else {\n        return \"请输入四位数字的学年！\";\n    }\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统。\\n将自动通过API获取课表数据，无需手动打开课表页面。\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function getAcademicYear() {\n    const currentYear = new Date().getFullYear().toString();\n    return await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\",\n        \"请输入要导入课程的起始学年（例如 2025-2026 学年应输入 2025）:\",\n        currentYear,\n        \"validateYearInput\"\n    );\n}\n\nasync function selectSemester() {\n    const semesters = [\"第一学期\", \"第二学期\"];\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesters),\n        0\n    );\n    return semesterIndex;\n}\n\nfunction getSemesterCode(semesterIndex) {\n    // 正方教务V9.0: 3=第一学期, 12=第二学期\n    return semesterIndex === 0 ? \"3\" : \"12\";\n}\n\n/**\n * 通过 API 请求课表数据\n */\nasync function fetchAndParseCourses(academicYear, semesterIndex) {\n    const semesterCode = getSemesterCode(semesterIndex);\n    const requestBody = \"xnm=\" + academicYear + \"&xqm=\" + semesterCode + \"&kzlx=ck&xsdm=&kclbdm=\";\n    \n    const apiUrl = \"https://jw.jhzyedu.cn/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151\";\n\n    window.shiguangBridge.showToast(\"正在通过API获取课表数据...\");\n    \n    try {\n        const response = await fetch(apiUrl, {\n            method: \"POST\",\n            headers: { \n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\" \n            },\n            body: requestBody,\n            credentials: \"include\"\n        });\n\n        if (response.ok) {\n            const jsonText = await response.text();\n            const jsonData = JSON.parse(jsonText);\n            if (jsonData && jsonData.kbList) {\n                const parsedCourses = parseJsonData(jsonData);\n                if (parsedCourses.length > 0) {\n                    return {\n                        courses: parsedCourses,\n                        config: {\n                            semesterStartDate: null,\n                            semesterTotalWeeks: 20\n                        }\n                    };\n                }\n            }\n        }\n        window.shiguangBridge.showToast(\"API 返回数据异常，请检查登录状态或学年学期选择。\");\n        return null;\n    } catch (e) {\n        console.error(\"API fetch error: \" + e.message);\n        window.shiguangBridge.showToast(\"请求课表数据失败，请确认已登录教务系统。\");\n        return null;\n    }\n}\n\nasync function saveCourses(parsedCourses) {\n    window.shiguangBridge.showToast(\"正在保存 \" + parsedCourses.length + \" 门课程...\");\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses, null, 2));\n        console.log(\"JS: 课程保存成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"课程保存失败: \" + error.message);\n        console.error('JS: Save Courses Error:', error);\n        return false;\n    }\n}\n\n// 江西航空职业技术学院作息时间（每节40分钟）\nconst TimeSlots = [\n    { number: 1, startTime: \"09:00\", endTime: \"09:40\" },\n    { number: 2, startTime: \"09:45\", endTime: \"10:25\" },\n    { number: 3, startTime: \"10:35\", endTime: \"11:15\" },\n    { number: 4, startTime: \"11:20\", endTime: \"12:00\" },\n    { number: 5, startTime: \"13:30\", endTime: \"14:10\" },\n    { number: 6, startTime: \"14:15\", endTime: \"14:55\" },\n    { number: 7, startTime: \"15:05\", endTime: \"15:45\" },\n    { number: 8, startTime: \"15:50\", endTime: \"16:30\" }\n];\n\nasync function importPresetTimeSlots(timeSlots) {\n    if (timeSlots.length > 0) {\n        window.shiguangBridge.showToast(\"正在导入 \" + timeSlots.length + \" 个预设时间段...\");\n        try {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n            window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n            console.log(\"JS: 预设时间段导入成功。\");\n        } catch (error) {\n            window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n            console.error('JS: Save Time Slots Error:', error);\n        }\n    }\n}\n\n\nasync function runImportFlow() {\n\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    const academicYear = await getAcademicYear();\n    if (academicYear === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n\n\n    const semesterIndex = await selectSemester();\n    if (semesterIndex === null || semesterIndex === -1) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n\n    const result = await fetchAndParseCourses(academicYear, semesterIndex);\n    if (result === null) {\n        return;\n    }\n    const { courses, config } = result;\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        return;\n    }\n    \n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        window.shiguangBridge.showToast(\"课表配置更新成功！总周数：\" + config.semesterTotalWeeks + \"周。\");\n    } catch (error) {\n        window.shiguangBridge.showToast(\"课表配置保存失败: \" + error.message);\n    }\n\n    await importPresetTimeSlots(TimeSlots);\n\n    window.shiguangBridge.showToast(\"课程导入成功，共导入 \" + courses.length + \" 门课程！\");\n    console.log(\"JS: 整个导入流程执行完毕并成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();\n","JXFU_01":"/**\n * 解析周次字符串 (例如 \"17,2,3,4,6\")\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n    let weeks = [];\n    let parts = String(weekStr).split(',');\n    for (let part of parts) {\n        if (part.includes('-')) {\n            let [start, end] = part.split('-');\n            for (let i = parseInt(start); i <= parseInt(end); i++) {\n                if (!weeks.includes(i)) weeks.push(i);\n            }\n        } else {\n            let w = parseInt(part.trim());\n            if (!isNaN(w) && !weeks.includes(w)) weeks.push(w);\n        }\n    }\n    return weeks.sort((a, b) => a - b);\n}\n\n/**\n * 直接从 JS 变量中提取 JSON 数据\n */\nfunction extractCoursesFromHtml(htmlText) {\n    let parsedCourses = [];\n    \n    // 使用正则表达式精准捕获 var kbxx = [...] 中的 JSON 数组\n    let match = htmlText.match(/var\\s+kbxx\\s*=\\s*(\\[[\\s\\S]*?\\])\\s*;/);\n    if (!match || !match[1]) {\n        if (htmlText.includes('<table class=\"kb\"')) {\n            console.warn(\"页面结构正确但未找到课表数据，推测该学期暂未排课。\");\n            return []; // 这是一个合法的空课表\n        }\n        console.error(\"【调试HTML片段】\", htmlText.substring(0, 800));\n        throw new Error(\"未能从目标页面抓取到 kbxx 数据，请确认当前处于教务系统登录状态。\");\n    }\n\n    let rawData = [];\n    try {\n        rawData = JSON.parse(match[1]);\n    } catch (e) {\n        throw new Error(\"解析课表JSON数据失败！\");\n    }\n\n    rawData.forEach(item => {\n        let courseObj = {\n            name: item.kcmc || \"未知课程\",\n            teacher: item.teaxms || \"未知\",\n            position: item.jxcdmcs || \"待定\",\n            day: parseInt(item.xq),\n            isCustomTime: false\n        };\n\n        // 处理周次 (item.zcs 格式为 \"18,2,3,4,7,8\")\n        if (item.zcs) {\n            courseObj.weeks = parseWeeks(item.zcs);\n        } else {\n            return; // 无周次则抛弃\n        }\n\n        // 处理节次 (item.jcdm2 格式为 \"05,06\" 或 \"10\")\n        if (item.jcdm2) {\n            let sections = item.jcdm2.split(',').map(s => parseInt(s, 10));\n            courseObj.startSection = sections[0];\n            courseObj.endSection = sections[sections.length - 1];\n        } else {\n            return; // 无节次则抛弃\n        }\n\n        // 只有包含完整有效信息才加入\n        if (courseObj.name && courseObj.weeks && courseObj.weeks.length > 0) {\n            parsedCourses.push(courseObj);\n        }\n    });\n\n    // 去重逻辑\n    let uniqueCourses = [];\n    let courseSet = new Set();\n    parsedCourses.forEach(course => {\n        let uniqueKey = `${course.day}-${course.startSection}-${course.endSection}-${course.name}-${course.weeks.join(',')}`;\n        if (!courseSet.has(uniqueKey)) {\n            courseSet.add(uniqueKey);\n            uniqueCourses.push(course);\n        }\n    });\n\n    return uniqueCourses;\n}\n\n/**\n * 生成学校专属的作息时间段\n */\nfunction getPresetTimeSlots() {\n    return [\n        { \"number\": 1, \"startTime\": \"08:00\", \"endTime\": \"08:45\" },\n        // 课间 10分\n        { \"number\": 2, \"startTime\": \"08:55\", \"endTime\": \"09:40\" },\n        // 课间 20分 (特殊)\n        { \"number\": 3, \"startTime\": \"10:00\", \"endTime\": \"10:45\" },\n        // 课间 10分\n        { \"number\": 4, \"startTime\": \"10:55\", \"endTime\": \"11:40\" },\n        \n        { \"number\": 5, \"startTime\": \"14:00\", \"endTime\": \"14:45\" },\n        // 课间 10分\n        { \"number\": 6, \"startTime\": \"14:55\", \"endTime\": \"15:40\" },\n        // 课间 15分 (特殊)\n        { \"number\": 7, \"startTime\": \"15:55\", \"endTime\": \"16:40\" },\n        // 课间 10分\n        { \"number\": 8, \"startTime\": \"16:50\", \"endTime\": \"17:35\" },\n        \n        { \"number\": 9, \"startTime\": \"19:00\", \"endTime\": \"19:45\" },\n        // 课间 10分\n        { \"number\": 10, \"startTime\": \"19:55\", \"endTime\": \"20:40\" },\n        // 课间 10分\n        { \"number\": 11, \"startTime\": \"20:50\", \"endTime\": \"21:35\" } \n    ];\n}\n\n/**\n * 生成全局课表配置\n */\nfunction getCourseConfig() {\n    return {\n        \"defaultClassDuration\": 45, // 单节课 45 分钟\n        \"defaultBreakDuration\": 10  // 默认课间 10 分钟\n    };\n}\n\n/**\n * 异步编排流程\n */\nasync function runImportFlow() {\n    try {\n        if (typeof window.shiguangBridge !== 'undefined') {\n            window.shiguangBridge.showToast(\"正在获取课表配置，请稍候...\");\n        } else {\n            console.log(\"正在请求获取学期列表...\");\n        }\n\n        // 第 1 步：请求外层页面，获取学期列表\n        const listResponse = await fetch('/xsgrkbcx!getXsgrbkList.action', { method: 'GET' });\n        const listHtml = await listResponse.text();\n        const parser = new DOMParser();\n        const listDoc = parser.parseFromString(listHtml, 'text/html');\n\n        const selectElem = listDoc.getElementById('xnxqdm');\n        let semesters = [];\n        let semesterValues = [];\n        let defaultIndex = 0;\n\n        if (selectElem) {\n            const options = selectElem.querySelectorAll('option');\n            options.forEach((opt, index) => {\n                semesters.push(opt.innerText.trim());\n                semesterValues.push(opt.value);\n                if (opt.hasAttribute('selected') || opt.selected) {\n                    defaultIndex = index;\n                }\n            });\n        }\n\n        if (semesters.length === 0) {\n            throw new Error(\"无法在页面中找到学期选项(xnxqdm)，请确认教务系统是否正常。\");\n        }\n\n        // 第 2 步：选择学期\n        let selectedIdx = defaultIndex;\n        if (typeof window.shiguangBridgePromise !== 'undefined') {\n            // APP 内原生弹窗\n            let userChoice = await window.shiguangBridgePromise.showSingleSelection(\n                \"请选择要导入的学期\", \n                JSON.stringify(semesters), \n                defaultIndex\n            );\n\n            if (userChoice === null) {\n                window.shiguangBridge.showToast(\"已取消导入\");\n                return;\n            }\n            selectedIdx = userChoice;\n        } else {\n            // 电脑浏览器端原生 prompt 弹窗测试\n            let msg = \"【浏览器测试】请选择学期对应的序号：\\n\\n\";\n            semesters.forEach((s, idx) => {\n                msg += `[ ${idx} ] : ${s}\\n`;\n            });\n            let userInput = prompt(msg, defaultIndex);\n            if (userInput === null) {\n                console.log(\"已取消测试。\");\n                return;\n            }\n            selectedIdx = parseInt(userInput);\n            if (isNaN(selectedIdx) || selectedIdx < 0 || selectedIdx >= semesters.length) {\n                alert(\"输入的序号不合法，将使用默认学期！\");\n                selectedIdx = defaultIndex;\n            }\n        }\n        \n        let targetXnxqdm = semesterValues[selectedIdx];\n\n        if (typeof window.shiguangBridge !== 'undefined') {\n            window.shiguangBridge.showToast(`正在获取 [${semesters[selectedIdx]}] 课表数据...`);\n        } else {\n            console.log(`准备拉取学期 [${semesters[selectedIdx]} / 代码: ${targetXnxqdm}] 的课表数据...`);\n        }\n\n        // 第 3 步：带上学期参数，请求真正的课表数据接口\n        const kbResponse = await fetch(`/xsgrkbcx!xsAllKbList.action?xnxqdm=${targetXnxqdm}`, { method: 'GET' });\n        const kbHtmlText = await kbResponse.text();\n\n        // 第 4 步：提取数据\n        const courses = extractCoursesFromHtml(kbHtmlText);\n        \n        if (courses.length === 0) {\n            const errMsg = \"该学期暂无排课数据。\";\n            if (typeof window.shiguangBridgePromise !== 'undefined') {\n                await window.shiguangBridgePromise.showAlert(\"提示\", errMsg, \"好的\");\n            } else {\n                alert(errMsg);\n            }\n            return;\n        }\n\n        const config = getCourseConfig();\n        const timeSlots = getPresetTimeSlots();\n\n        // 浏览器测试环境，直接打印输出\n        if (typeof window.shiguangBridgePromise === 'undefined') {\n            console.log(\"【测试成功】课表配置：\", config);\n            console.log(\"【测试成功】作息时间：\", timeSlots);\n            console.log(\"【测试成功】课程数据：\\n\", JSON.stringify(courses, null, 2));\n            alert(`解析成功！获取到 ${courses.length} 门课程以及专属作息。\\n（请打开 F12 Console 控制台查看具体数据）`);\n            return;\n        }\n\n        // APP 环境保存数据\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        \n        const saveResult = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        if (!saveResult) {\n            window.shiguangBridge.showToast(\"保存课程失败，请重试！\");\n            return;\n        }\n\n        window.shiguangBridge.showToast(`成功导入 ${courses.length} 节课程及作息时间！`);\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (error) {\n        if (typeof window.shiguangBridge !== 'undefined') {\n            window.shiguangBridge.showToast(\"导入发生异常: \" + error.message);\n        } else {\n            console.error(\"【导入发生异常】\", error);\n            alert(\"导入发生异常: \" + error.message);\n        }\n    }\n}\n\n// 启动导入流程\nrunImportFlow();","UJN_01":"/**\n * 济南大学教务适配\n * @since 2026-3-13\n * @description 支持班级课表和个人课表的导入\n * @author Moyu\n * @version 1.0\n */\nclass CourseModel {\n  name = \"\"; // 课程名称 (String)\n  teacher = \"\"; // 教师姓名 (String)\n  position = \"\"; // 上课地点 (String)\n  day = 0; //星期几 (Int, 1=周一, 7=周日)\n  startSection = 0; // 开始节次 (Int, 如果 isCustomTime 为 false 或未提供，则必填)\n  endSection = 0; // 结束节次 (Int, 如果 isCustomTime 为 false 或未提供，则必填)\n  weeks = [0]; // 上课周数 (Int Array, 必须是数字数组，例如 [1, 3, 5, 7])\n  isCustomTime = false; // 是否使用自定义时间 (Boolean, 可选，默认为 false。如果为 true，则 customStartTime 和 customEndTime 必填；如果为 false 或未提供，则 startSection 和 endSection 必填)\n  customStartTime = \"\"; // 自定义开始时间 (String, 格式 HH:mm, 如果 isCustomTime 为 true 则必填)\n  customEndTime = \"\"; // 自定义结束时间 (String, 格式 HH:mm, 如果 isCustomTime 为 true 则必填)\n  constructor(\n    name, // 课程名称 (String)\n    teacher, // 教师姓名 (String)\n    position, // 上课地点 (String)\n    day, // 星期几 (Int, 1=周一,7=周日)\n    startSection, // 开始节次 (Int)\n    endSection, // 结束节次 (Int)\n    weeks = [], // 上课周数 (Int Array)\n    isCustomTime = false, // 是否自定义时间 (Boolean，默认false)\n    customStartTime = \"\", // 自定义开始时间 (可选)\n    customEndTime = \"\", // 自定义结束时间 (可选)\n  ) {\n    // 1. 基础字段赋值（必选参数）\n    this.name = name;\n    this.teacher = teacher;\n    this.position = position;\n    this.day = day;\n    this.startSection = startSection;\n    this.endSection = endSection;\n    this.weeks = weeks;\n    this.isCustomTime = isCustomTime;\n    this.customStartTime = customStartTime;\n    this.customEndTime = customEndTime;\n  }\n}\nclass CustomTimeModel {\n  number = 0;\n  startTime = \"\"; // 开始时间 (String, 格式 HH:mm)\n  endTime = \"\"; // 结束时间 (String, 格式 HH:mm)\n  constructor(num, start, end) {\n    this.number = num;\n    this.startTime = start;\n    this.endTime = end;\n  }\n}\n\nconst urlPersonnalClassTable =\n  \"jwgl.ujn.edu.cn/jwglxt/kbcx/xskbcx_cxXskbcxIndex.html\";\nconst urlClassTable = \"jwgl.ujn.edu.cn/jwglxt/kbdy/bjkbdy_cxBjkbdyIndex.html\";\n\n//解析周数据\nfunction parseWeekText(text) {\n  if (!text) return [];\n  text = text.replace(/^[\\s\\uFEFF\\xA0]+|[\\s\\uFEFF\\xA0]+$/g, \"\").trim();\n\n  const allWeeks = new Set();\n  const noJie = text.replace(/\\(\\d+-\\d+节\\)/g, \" \");\n\n  const rangePattern = /(\\d+)-(\\d+)周(?:\\((单|双)\\))?/g;\n  const singlePattern = /(\\d+)周(?:\\((单|双)\\))?/g;\n\n  let match;\n  while ((match = rangePattern.exec(noJie)) !== null) {\n    const [, start, end, type] = match;\n    for (let w = parseInt(start, 10); w <= parseInt(end, 10); w++) {\n      if (\n        !type ||\n        (type === \"单\" && w % 2 === 1) ||\n        (type === \"双\" && w % 2 === 0)\n      ) {\n        allWeeks.add(w);\n      }\n    }\n  }\n\n  const processedRanges = [];\n  rangePattern.lastIndex = 0;\n  while ((match = rangePattern.exec(noJie)) !== null) {\n    processedRanges.push({\n      start: match.index,\n      end: match.index + match[0].length,\n    });\n  }\n\n  singlePattern.lastIndex = 0;\n  while ((match = singlePattern.exec(noJie)) !== null) {\n    const weekNum = parseInt(match[1], 10);\n    const type = match[2];\n\n    // 检查这个匹配是否已经被范围正则匹配过了（简单判断：如果包含\"-\"就跳过）\n    const matchStr = match[0];\n    if (matchStr.includes(\"-\")) continue;\n\n    if (\n      !type ||\n      (type === \"单\" && weekNum % 2 === 1) ||\n      (type === \"双\" && weekNum % 2 === 0)\n    ) {\n      allWeeks.add(weekNum);\n    }\n  }\n\n  return [...allWeeks].sort((a, b) => a - b);\n}\nfunction offsetColByRow(row) {\n  row = row - 2;\n  if (row % 4 == 0) {\n    return 0;\n  }\n  if (row % 4 == 2) {\n    return 1;\n  }\n}\nfunction analyzeCourseModel(item, flag) {\n  let td = item.closest(\"td\");\n  let elements = item.querySelectorAll(\"p\");\n  if (!td) {\n    console.error(\"找不到单元格\");\n    return null;\n  }\n  let tr = td.parentElement;\n  let site = {\n    row: tr.rowIndex, //第几行\n    rowSpan: td.rowSpan || 1, //跨几行\n    col: td.cellIndex, //第几列\n    colSpan: td.colSpan || 1, //跨几列\n    cell: td, //本身\n  };\n  let currentItem = item.querySelector(\".title\");\n  let name = currentItem.textContent;\n  let teacher;\n  let position;\n  let weeks;\n  if (flag == 1) {\n    teacher = elements[2].lastElementChild.innerText;\n    position = elements[1].lastElementChild.innerText;\n    weeks = parseWeekText(elements[0].lastElementChild.innerText);\n  } else {\n    if (elements.length != 1) {\n      teacher =\n        elements[4].firstElementChild.nextSibling.textContent.split(\"(\")[0];\n      position = elements[3].firstElementChild.nextSibling.textContent;\n      weeks = parseWeekText(\n        elements[2].firstElementChild.nextSibling.textContent,\n      );\n    } else {\n      teacher = \"\";\n      position = \"\";\n      weeks = parseWeekText(\"1-20周\");\n    }\n  }\n  return new CourseModel(\n    name.replace(/[■☆★◆]/g, \"\"),\n    teacher.trim(),\n    position.trim(),\n    site.col - 1 + offsetColByRow(site.row),\n    site.row - 1,\n    site.row + site.rowSpan - 2,\n    [...weeks],\n  );\n}\n\nasync function saveCourses() {\n  let flag = null;\n  let elements = [];\n  if (window.location.href.includes(urlPersonnalClassTable)) {\n    elements = document.querySelectorAll(\n      \"#innerContainer #table1 div.timetable_con\",\n    );\n    flag = 1;\n  } else {\n    if (window.location.href.includes(urlClassTable)) {\n      elements = document.querySelectorAll(\n        \"#table1.tab-pane>.timetable1 div.timetable_con\",\n      );\n      flag = 0;\n    }\n  }\n  let courseModels = [];\n  elements.forEach((item) => {\n    let course = analyzeCourseModel(item, flag);\n    if (course) {\n      courseModels.push({ ...course });\n    }\n  });\n\n  try {\n    await window.shiguangBridgePromise.saveImportedCourses(\n      JSON.stringify(courseModels),\n    );\n    return courseModels.length;\n  } catch (error) {\n    console.error(\"保存课程失败:\", error);\n    window.shiguangBridge.showToast(\"保存课程失败，请重试\");\n    return 0;\n  }\n}\nasync function checkEnvirenment() {\n  const nowSite = window.location.href;\n\n  const tableType = [\"班级课表\", \"个人课表\"];\n  if (\n    !nowSite.includes(urlPersonnalClassTable) &&\n    !nowSite.includes(urlClassTable)\n  ) {\n    window.shiguangBridge.showToast(\"当前页面不在支持的导入范围内\");\n    const selectedOption =\n      await window.shiguangBridgePromise.showSingleSelection(\n        \"现在不在可导入的页面中，请选择导入班级课表还是个人课表，之后并确保打开具体课程页面\",\n        JSON.stringify(tableType), // 必须是 JSON 字符串\n        -1, // 默认不选中\n      );\n    if (selectedOption === 0) {\n      clickMenu(\n        \"N214505\",\n        \"/kbdy/bjkbdy_cxBjkbdyIndex.html\",\n        \"班级课表查询\",\n        \"null\",\n      );\n      return false;\n    } else if (selectedOption === 1) {\n      clickMenu(\n        \"N253508\",\n        \"/kbcx/xskbcx_cxXskbcxIndex.html\",\n        \"个人课表\",\n        \"null\",\n      );\n      return false;\n    } else {\n      return false;\n    }\n  }\n\n  return true;\n}\n\nasync function runImportFlow() {\n  window.shiguangBridge.showToast(\"课程导入流程即将开始...\");\n\n  if (!(await checkEnvirenment())) return;\n\n  const savedCourseCount = await saveCourses();\n  if (!savedCourseCount) {\n    return;\n  }\n  const slots = [\n    new CustomTimeModel(1, \"08:00\", \"08:50\"),\n    new CustomTimeModel(2, \"08:55\", \"09:45\"),\n    new CustomTimeModel(3, \"10:15\", \"11:05\"),\n    new CustomTimeModel(4, \"11:10\", \"12:00\"),\n    new CustomTimeModel(5, \"14:00\", \"14:50\"),\n    new CustomTimeModel(6, \"14:55\", \"15:45\"),\n    new CustomTimeModel(7, \"16:15\", \"17:05\"),\n    new CustomTimeModel(8, \"17:10\", \"18:00\"),\n    new CustomTimeModel(9, \"19:00\", \"19:50\"),\n    new CustomTimeModel(10, \"19:55\", \"20:45\"),\n    new CustomTimeModel(11, \"20:50\", \"21:45\"),\n  ];\n  try {\n    await window.shiguangBridgePromise.savePresetTimeSlots(\n      JSON.stringify(slots),\n    );\n  } catch (error) {\n    console.error(\"保存时间段失败:\", error);\n    window.shiguangBridge.showToast(\"保存时间段失败，请重试\");\n    return;\n  }\n  // 8. 流程**完全成功**，发送结束信号。\n  window.shiguangBridge.showToast(`导入成功：共 ${savedCourseCount} 门课程`);\n  window.shiguangBridge.notifyTaskCompletion();\n}\n\n// 启动导入流程\nrunImportFlow();\n","JNMC_01":"// 济宁医学院教务（乘方教务 · 旧版 .action 接口）适配器\n\nconst PRESET_TIME_SLOTS = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:40\" },\n    { number: 2, startTime: \"08:50\", endTime: \"09:30\" },\n    { number: 3, startTime: \"09:50\", endTime: \"10:30\" },\n    { number: 4, startTime: \"10:40\", endTime: \"11:20\" },\n    { number: 5, startTime: \"11:30\", endTime: \"12:10\" },\n    { number: 6, startTime: \"14:00\", endTime: \"14:40\" },\n    { number: 7, startTime: \"14:50\", endTime: \"15:30\" },\n    { number: 8, startTime: \"15:50\", endTime: \"16:30\" },\n    { number: 9, startTime: \"16:40\", endTime: \"17:20\" },\n    { number: 10, startTime: \"17:30\", endTime: \"18:10\" },\n    { number: 11, startTime: \"19:00\", endTime: \"19:40\" },\n    { number: 12, startTime: \"19:50\", endTime: \"20:30\" },\n    { number: 13, startTime: \"20:50\", endTime: \"21:30\" },\n    { number: 14, startTime: \"21:40\", endTime: \"22:20\" }\n];\n\nfunction uniqueSortedNumbers(numbers) {\n    return [...new Set(numbers)].sort((a, b) => a - b);\n}\n\n// 支持 \"10,7,8,9\"、\"1-4\"、\"1-4,7\" 等周次写法。\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n    const weeks = [];\n    String(weekStr).replace(/[，、]/g, \",\").split(\",\").forEach(part => {\n        const text = part.trim().replace(/周/g, \"\");\n        const range = text.match(/^(\\d+)\\s*[-~]\\s*(\\d+)$/);\n        if (range) {\n            const start = parseInt(range[1], 10);\n            const end = parseInt(range[2], 10);\n            if (start > 0 && end >= start) {\n                for (let week = start; week <= end; week += 1) weeks.push(week);\n            }\n            return;\n        }\n        const week = parseInt(text, 10);\n        if (!isNaN(week) && week > 0) weeks.push(week);\n    });\n    return uniqueSortedNumbers(weeks);\n}\n\nfunction parseSections(sectionStr) {\n    return uniqueSortedNumbers(\n        String(sectionStr || \"\")\n            .replace(/[，、]/g, \",\")\n            .split(\",\")\n            .map(section => parseInt(section.trim(), 10))\n            .filter(section => !isNaN(section) && section > 0)\n    );\n}\n\n// 反斜杠表示合并教室（如 \"B205\\206教室\"），逗号才是不同地点的分隔符。\nfunction resolvePosition(raw) {\n    const position = String(raw || \"\").replace(/\\\\/g, \"/\").replace(/\\s+/g, \" \").trim();\n    return position || \"待定\";\n}\n\nfunction cleanTeacher(raw) {\n    const teacher = String(raw || \"\")\n        .split(/[,，、]/)\n        .map(name => name.trim())\n        .filter(Boolean)\n        .join(\"、\");\n    return teacher || \"未知\";\n}\n\nfunction courseKey(course) {\n    return [\n        course.name,\n        course.teacher,\n        course.position,\n        course.day,\n        course.startSection,\n        course.endSection\n    ].join(\"__\");\n}\n\nfunction addCourse(courseMap, item, weeks) {\n    const day = parseInt(item.xq, 10);\n    const sections = parseSections(item.jcdm2);\n    const allWeeks = uniqueSortedNumbers(weeks);\n    if (!item.kcmc || sections.length === 0 || allWeeks.length === 0 ||\n        isNaN(day) || day < 1 || day > 7) return;\n\n    const course = {\n        name: String(item.kcmc).trim(),\n        teacher: cleanTeacher(item.teaxms),\n        position: resolvePosition(item.jxcdmc || item.jxcdmcs),\n        day,\n        startSection: Math.min(...sections),\n        endSection: Math.max(...sections),\n        weeks: allWeeks\n    };\n\n    const key = courseKey(course);\n    const existing = courseMap.get(key);\n    if (existing) {\n        existing.weeks = uniqueSortedNumbers([...existing.weeks, ...course.weeks]);\n    } else {\n        courseMap.set(key, course);\n    }\n}\n\nfunction sortCourses(courses) {\n    return courses.sort((a, b) =>\n        a.day - b.day ||\n        a.startSection - b.startSection ||\n        a.endSection - b.endSection ||\n        a.name.localeCompare(b.name)\n    );\n}\n\n// 从整学期课表解析课程，作为周课表接口不可用时的回退。\nfunction parseCourseList(kbxx) {\n    if (!Array.isArray(kbxx)) throw new Error(\"课表接口返回格式不正确\");\n    const courseMap = new Map();\n    kbxx.forEach(item => {\n        addCourse(courseMap, item, parseWeeks(item.zcs));\n    });\n    return sortCourses(Array.from(courseMap.values()));\n}\n\n// 日历接口按周返回精确教室；同一课程换教室时，按周次拆成多个课程项。\nfunction parseWeeklyCourseList(rows) {\n    if (!Array.isArray(rows)) return [];\n    const courseMap = new Map();\n    rows.forEach(({ item, week }) => {\n        const actualWeek = parseInt(week, 10);\n        if (isNaN(actualWeek) || actualWeek < 1) return;\n        addCourse(courseMap, item, [actualWeek]);\n    });\n    return sortCourses(Array.from(courseMap.values()));\n}\n\nfunction maxWeekOf(kbxx) {\n    return kbxx.reduce((maxWeek, item) => {\n        const weeks = parseWeeks(item.zcs);\n        return Math.max(maxWeek, ...(weeks.length ? weeks : [0]));\n    }, 0);\n}\n\n// 读取课表页中的学期下拉框\nfunction extractSemesterOptions(doc) {\n    const selectElem = doc.getElementById(\"xnxqdm\");\n    if (!selectElem) return null;\n    const semesters = [];\n    const semesterValues = [];\n    let defaultIndex = 0;\n    Array.from(selectElem.querySelectorAll(\"option\")).forEach(option => {\n        if (!option.value) return;\n        semesters.push(option.innerText.trim());\n        semesterValues.push(option.value);\n        if (option.selected || option.hasAttribute(\"selected\")) defaultIndex = semesters.length - 1;\n    });\n    if (semesters.length === 0) return null;\n\n    const start = Math.max(0, defaultIndex - 1);\n    const end = Math.min(semesters.length, defaultIndex + 10);\n    return {\n        semesters: semesters.slice(start, end),\n        semesterValues: semesterValues.slice(start, end),\n        defaultIndex: defaultIndex - start\n    };\n}\n\n// 导入前提示先登录教务系统\nasync function promptUserToStart() {\n    const confirmed = await window.shiguangBridgePromise.showAlert(\n        \"济宁医学院教务导入\",\n        \"请先确保已登录教务系统，再继续导入。\",\n        \"我已登录\"\n    );\n    if (!confirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return null;\n    }\n    return true;\n}\n\n// 选择学期\nasync function selectSemester(semesterOptions) {\n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesterOptions.semesters),\n        semesterOptions.defaultIndex\n    );\n    if (selectedIndex === null || selectedIndex === undefined) return null;\n    const index = Number(selectedIndex);\n    if (!Number.isInteger(index) || index < 0 || index >= semesterOptions.semesters.length) return null;\n    return {\n        label: semesterOptions.semesters[index],\n        value: semesterOptions.semesterValues[index]\n    };\n}\n\n// 拉取课表页 HTML（含学期列表）\nasync function fetchSchedulePage() {\n    const response = await fetch(\"/xsgrkbcx!getXsgrbkList.action\", { method: \"GET\", credentials: \"include\" });\n    if (!response.ok) throw new Error(`无法打开课表页面（HTTP ${response.status}）`);\n    return response.text();\n}\n\n// 拉取指定学期课表（HTML 内嵌 var kbxx=[...]）\nasync function fetchCourseData(xnxqdm) {\n    const response = await fetch(\n        `/xsgrkbcx!xsAllKbList.action?xnxqdm=${encodeURIComponent(xnxqdm)}`,\n        { method: \"GET\", credentials: \"include\" }\n    );\n    if (!response.ok) throw new Error(`课表请求失败（HTTP ${response.status}）`);\n    const htmlText = await response.text();\n    const match = htmlText.match(/var\\s+kbxx\\s*=\\s*(\\[[\\s\\S]*?\\]);/);\n    if (!match) throw new Error(\"课表数据解析失败，请检查登录状态\");\n    let kbxx;\n    try {\n        kbxx = JSON.parse(match[1]);\n    } catch (error) {\n        throw new Error(`课表数据解析失败：${error.message}`);\n    }\n    return kbxx;\n}\n\nfunction normalizeDate(raw) {\n    const match = String(raw || \"\").match(/^(\\d{4}-\\d{2}-\\d{2})/);\n    return match ? match[1] : null;\n}\n\nfunction shiftDate(dateText, dayOffset) {\n    const match = String(dateText || \"\").match(/^(\\d{4})-(\\d{2})-(\\d{2})$/);\n    if (!match) return null;\n    const date = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));\n    date.setDate(date.getDate() + dayOffset);\n    return [\n        date.getFullYear(),\n        String(date.getMonth() + 1).padStart(2, \"0\"),\n        String(date.getDate()).padStart(2, \"0\")\n    ].join(\"-\");\n}\n\nfunction extractWeekStartDate(payload) {\n    const dateRows = Array.isArray(payload) && Array.isArray(payload[1]) ? payload[1] : [];\n    const monday = dateRows.find(item => parseInt(item.xqmc, 10) === 1) || dateRows[0];\n    return normalizeDate(monday && monday.rq);\n}\n\n// 获取某一周的日历数据，jxcdmc 是该周实际使用的教室。\nasync function fetchWeeklyCourseData(xnxqdm, week) {\n    const response = await fetch(\n        `/xsgrkbcx!getKbRq.action?xnxqdm=${encodeURIComponent(xnxqdm)}&zc=${encodeURIComponent(week)}`,\n        { method: \"GET\", credentials: \"include\" }\n    );\n    if (!response.ok) throw new Error(`第${week}周课表请求失败（HTTP ${response.status}）`);\n    const payload = await response.json();\n    const rows = Array.isArray(payload) && Array.isArray(payload[0]) ? payload[0] : [];\n    return {\n        rows: rows.map(item => ({ item, week })),\n        weekStartDate: extractWeekStartDate(payload)\n    };\n}\n\nasync function fetchWeeklyCourses(xnxqdm, kbxx) {\n    const weeks = Array.from({ length: maxWeekOf(kbxx) }, (_, index) => index + 1);\n    if (weeks.length === 0) return { rows: [], successfulWeeks: [], semesterStartDate: null };\n\n    const results = await Promise.all(weeks.map(async week => {\n        try {\n            const data = await fetchWeeklyCourseData(xnxqdm, week);\n            return { week, ...data };\n        } catch (error) {\n            console.warn(`读取第${week}周课表失败`, error);\n            return { week, rows: null, weekStartDate: null };\n        }\n    }));\n\n    const datedWeek = results.find(result => result.weekStartDate);\n    const semesterStartDate = datedWeek\n        ? shiftDate(datedWeek.weekStartDate, -7 * (datedWeek.week - 1))\n        : null;\n    return {\n        rows: results.flatMap(result => result.rows || []),\n        successfulWeeks: results.filter(result => result.rows !== null).map(result => result.week),\n        semesterStartDate\n    };\n}\n\nfunction mergeWeeklyAndFallbackCourses(kbxx, weeklyData) {\n    if (weeklyData.rows.length === 0) return parseCourseList(kbxx);\n\n    const courseMap = new Map();\n    parseWeeklyCourseList(weeklyData.rows).forEach(course => {\n        courseMap.set(courseKey(course), course);\n    });\n    const successfulWeeks = new Set(weeklyData.successfulWeeks);\n    if (successfulWeeks.size === weeklyData.successfulWeeks.length &&\n        successfulWeeks.size >= maxWeekOf(kbxx)) return sortCourses(Array.from(courseMap.values()));\n\n    // 仅为请求失败的周次使用整学期数据，避免覆盖周课表中的精确教室。\n    kbxx.forEach(item => {\n        const weeks = parseWeeks(item.zcs).filter(week => !successfulWeeks.has(week));\n        if (weeks.length > 0) addCourse(courseMap, item, weeks);\n    });\n    return sortCourses(Array.from(courseMap.values()));\n}\n\nasync function saveCourseConfig(config) {\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n}\n\nasync function saveCourses(courses) {\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n}\n\nasync function savePresetTimeSlots() {\n    await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(PRESET_TIME_SLOTS));\n}\n\n// 主流程：提示 → 选学期 → 拉课表 → 保存课程与作息\nasync function runImportFlow() {\n    try {\n        const alertConfirmed = await promptUserToStart();\n        if (!alertConfirmed) return;\n\n        const pageHtml = await fetchSchedulePage();\n        const semesterOptions = extractSemesterOptions(new DOMParser().parseFromString(pageHtml, \"text/html\"));\n        if (!semesterOptions) throw new Error(\"未找到学期列表，请先登录教务系统\");\n\n        const semester = await selectSemester(semesterOptions);\n        if (!semester) { window.shiguangBridge.showToast(\"导入已取消\"); return; }\n\n        window.shiguangBridge.showToast(`正在获取 ${semester.label} 的课表...`);\n        const allCourseData = await fetchCourseData(semester.value);\n        const weeklyData = await fetchWeeklyCourses(semester.value, allCourseData);\n        const courses = mergeWeeklyAndFallbackCourses(allCourseData, weeklyData);\n\n        if (courses.length === 0) {\n            await window.shiguangBridgePromise.showAlert(\n                \"提示\",\n                \"该学期没有获取到课程数据，请检查登录状态和所选学期。\",\n                \"确定\"\n            );\n            return;\n        }\n\n        const courseConfig = {\n            semesterTotalWeeks: Math.max(maxWeekOf(allCourseData), 20),\n            firstDayOfWeek: 1\n        };\n        if (weeklyData.semesterStartDate) {\n            courseConfig.semesterStartDate = weeklyData.semesterStartDate;\n        }\n\n        await saveCourseConfig(courseConfig);\n        await saveCourses(courses);\n        try {\n            await savePresetTimeSlots();\n        } catch (error) {\n            window.shiguangBridge.showToast(`课程已导入，作息时间导入失败：${error.message}`);\n        }\n\n        window.shiguangBridge.showToast(`成功导入 ${courses.length} 门课程！`);\n        if (!weeklyData.semesterStartDate) {\n            window.shiguangBridge.showToast(\"未获取到开学日期，请在应用内手动设置。\");\n        }\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        await window.shiguangBridgePromise.showAlert(\n            \"导入失败\",\n            error.message || String(error),\n            \"确定\"\n        );\n    }\n}\n\nrunImportFlow();\n","JYVTC_01":"// 济源职业技术学院_拾光课程表适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提联系开发者或者提交pr更改,这更加快速\n\nfunction parseWeeks(weekStr) {\n    const weeks = [];\n    const isDoubleWeek = weekStr.includes('双周');\n    const isSingleWeek = weekStr.includes('单周');\n    let cleanWeekStr = weekStr.replace('双周', '').replace('单周', '').trim();\n\n    const parts = cleanWeekStr.split(',');\n\n    for (const part of parts) {\n        let currentPart = part.trim();\n\n        if (currentPart.includes('-')) {\n            const [start, end] = currentPart.split('-').map(Number);\n            for (let i = start; i <= end; i++) {\n                if (isDoubleWeek) {\n                    if (i % 2 === 0) weeks.push(i);\n                } else if (isSingleWeek) {\n                    if (i % 2 !== 0) weeks.push(i);\n                } else {\n                    weeks.push(i);\n                }\n            }\n        } else if (!isNaN(Number(currentPart)) && currentPart !== '') {\n            weeks.push(Number(currentPart));\n        }\n    }\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\nfunction parseCourseString(cellContent) {\n    const courses = [];\n    const content = cellContent.replace(/<\\/?ul>/g, '').trim();\n    const courseLines = content.split(/<br\\s*\\/?>/i);\n\n    for (const line of courseLines) {\n        const text = line.trim();\n        if (!text) continue;\n\n        const match = text.match(/(.+?)\\s+([^\\s(]+)\\s*\\(([^()]+)\\)/);\n\n        if (match) {\n            const name = match[1].trim();\n            const teacher = match[2].trim();\n            const fullContent = match[3].trim();\n\n            const lastSpaceIndex = fullContent.lastIndexOf(' ');\n\n            if (lastSpaceIndex !== -1) {\n                const weeksStr = fullContent.substring(0, lastSpaceIndex).trim();\n                const position = fullContent.substring(lastSpaceIndex + 1).trim();\n\n                if (name && teacher && position && weeksStr) {\n                    courses.push({\n                        name: name,\n                        teacher: teacher,\n                        position: position,\n                        weeks: parseWeeks(weeksStr)\n                    });\n                }\n            }\n        }\n    }\n    return courses;\n}\n\nfunction transformSchedule(htmlString) {\n    console.log(\"JS: transformSchedule 正在解析 HTML...\");\n    const rowsMatch = htmlString.match(/<tr class=\"mykb\"[\\s\\S]*?<\\/tr>/g);\n    if (!rowsMatch) {\n        console.warn(\"JS: transformSchedule 未找到任何课程行 (tr class='mykb')\");\n        return [];\n    }\n\n    const tempCourseList = [];\n    const sectionMap = {};\n\n    for (let i = 0; i < rowsMatch.length; i++) {\n        const row = rowsMatch[i];\n        const sectionMatch = row.match(/<td[^>]*?>[^<]*?(\\d+)(?:\\([^)]*\\))?/i);\n        if (sectionMatch && sectionMatch[1]) {\n            sectionMap[i] = Number(sectionMatch[1]);\n        }\n    }\n\n    for (let rowIndex = 0; rowIndex < rowsMatch.length; rowIndex++) {\n        const row = rowsMatch[rowIndex];\n        const currentSection = sectionMap[rowIndex];\n        if (!currentSection) continue;\n\n        const allCells = row.match(/<td\\s+[^>]*?>[\\s\\S]*?<\\/td>/g);\n        if (!allCells) continue;\n\n        let courseCells;\n\n        if (allCells.length === 9) {\n            courseCells = allCells.slice(2, 9);\n        } else if (allCells.length === 8) {\n            courseCells = allCells.slice(1, 8);\n        } else {\n            continue;\n        }\n\n        if (courseCells.length !== 7) {\n            continue;\n        }\n\n        let dayOfWeek = 1;\n\n        for (const cellHtml of courseCells) {\n            const cellContentMatch = cellHtml.match(/<ul>([\\s\\S]*?)<\\/ul>/);\n\n            if (cellContentMatch) {\n                const courseLinesContent = cellContentMatch[1];\n                const coursesInCell = parseCourseString(courseLinesContent);\n\n                for (const course of coursesInCell) {\n                    if (dayOfWeek >= 1 && dayOfWeek <= 7) {\n                         tempCourseList.push({\n                            name: course.name,\n                            teacher: course.teacher,\n                            position: course.position,\n                            day: dayOfWeek,\n                            startSection: currentSection,\n                            endSection: currentSection,\n                            weeks: course.weeks\n                        });\n                    }\n                }\n            }\n            dayOfWeek++;\n        }\n    }\n\n    const finalCourseList = [];\n\n    tempCourseList.sort((a, b) =>\n        a.day - b.day ||\n        a.name.localeCompare(b.name) ||\n        a.teacher.localeCompare(b.teacher) ||\n        a.position.localeCompare(b.position) ||\n        a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n        a.startSection - b.startSection\n    );\n\n    let currentMergedCourse = null;\n\n    for (const course of tempCourseList) {\n        if (currentMergedCourse === null) {\n            currentMergedCourse = { ...course };\n        } else {\n            const isSameCourseContext = currentMergedCourse.name === course.name &&\n                                        currentMergedCourse.teacher === course.teacher &&\n                                        currentMergedCourse.position === course.position &&\n                                        currentMergedCourse.weeks.join(',') === course.weeks.join(',');\n\n            const isConsecutive = course.day === currentMergedCourse.day &&\n                                  course.startSection === currentMergedCourse.endSection + 1;\n\n            if (isSameCourseContext && isConsecutive) {\n                currentMergedCourse.endSection = course.endSection;\n            } else {\n                finalCourseList.push(currentMergedCourse);\n                currentMergedCourse = { ...course };\n            }\n        }\n    }\n\n    if (currentMergedCourse !== null) {\n        finalCourseList.push(currentMergedCourse);\n    }\n\n    console.log(`JS: transformSchedule 解析并合并完成，共 ${finalCourseList.length} 门课程。`);\n    return finalCourseList;\n}\n\nfunction isLoginPage() {\n    const url = window.location.href;\n    return url.includes('jwgl.jyvtc.edu.cn/jyvtcjw/cas/login.action');\n}\n\nfunction validateYearInput(input) {\n    console.log(\"JS: validateYearInput 被调用，输入: \" + input);\n    if (/^[0-9]{4}$/.test(input)) {\n        console.log(\"JS: validateYearInput 验证通过。\");\n        return false;\n    } else {\n        console.log(\"JS: validateYearInput 验证失败。\");\n        return \"请输入四位数字的学年！\";\n    }\n}\nasync function promptUserToStart() {\n    console.log(\"JS: 流程开始：显示公告。\");\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function getAcademicYear() {\n    const currentYear = new Date().getFullYear().toString();\n    console.log(\"JS: 提示用户输入学年。\");\n    return await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\",\n        \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\",\n        currentYear,\n        \"validateYearInput\"\n    );\n}\n\nasync function selectSemester() {\n    const semesters = [\"第一学期 (0)\", \"第二学期 (1)\"];\n    console.log(\"JS: 提示用户选择学期。\");\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesters),\n        0\n    );\n    return semesterIndex;\n}\n\nasync function fetchAndParseCourses(academicYear, semesterIndex) {\n    window.shiguangBridge.showToast(\"正在请求课表数据...\");\n\n    // 0是第一学期，1是第二学期\n    const semesterCode = semesterIndex === 0 ? \"0\" : \"1\";\n    const xnxqBody = `weeks=&xnxq=${academicYear}-${semesterCode}`;\n    const url = \"https://jwgl.jyvtc.edu.cn/jyvtcjw/frame/desk/showLessonScheduleDetail.action\";\n\n    console.log(`JS: 发送请求到 ${url}, body: ${xnxqBody}`);\n\n    const requestOptions = {\n        \"headers\": {\n          \"content-type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n        },\n        \"body\": xnxqBody,\n        \"method\": \"POST\",\n        \"credentials\": \"include\"\n    };\n\n    try {\n        const response = await fetch(url, requestOptions);\n\n        if (!response.ok) {\n            throw new Error(`网络请求失败。状态码: ${response.status} (${response.statusText})`);\n        }\n\n        const htmlText = await response.text();\n\n        const courses = transformSchedule(htmlText);\n\n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"未找到任何课程数据，请检查所选学年学期是否正确。\");\n            return null;\n        }\n\n        console.log(`JS: 课程数据解析成功，共找到 ${courses.length} 门课程。`);\n\n        return { courses: courses };\n\n    } catch (error) {\n        window.shiguangBridge.showToast(`请求或解析失败: ${error.message}`);\n        console.error('JS: Fetch/Parse Error:', error);\n        return null;\n    }\n}\n\nasync function saveCourses(parsedCourses) {\n    window.shiguangBridge.showToast(`正在保存 ${parsedCourses.length} 门课程...`);\n    console.log(`JS: 尝试保存 ${parsedCourses.length} 门课程...`);\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses, null, 2));\n        console.log(\"JS: 课程保存成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        console.error('JS: Save Courses Error:', error);\n        return false;\n    }\n}\n\nconst Non_summerTimeSlots = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:55\", endTime: \"09:40\" },\n    { number: 3, startTime: \"10:10\", endTime: \"10:55\" },\n    { number: 4, startTime: \"11:05\", endTime: \"11:50\" },\n    { number: 5, startTime: \"14:30\", endTime: \"15:15\" },\n    { number: 6, startTime: \"15:25\", endTime: \"16:10\" },\n    { number: 7, startTime: \"16:30\", endTime: \"17:14\" },\n    { number: 8, startTime: \"17:15\", \"endTime\": \"18:00\" },\n    { number: 9, startTime: \"19:30\", \"endTime\": \"20:14\" },\n    { number: 10, startTime: \"20:15\", \"endTime\": \"21:00\" }\n];\nconst SummerTimeSlots = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:55\", endTime: \"09:40\" },\n    { number: 3, startTime: \"10:10\", endTime: \"10:55\" },\n    { number: 4, startTime: \"11:05\", endTime: \"11:50\" },\n    { number: 5, startTime: \"15:00\", endTime: \"15:45\" },\n    { number: 6, startTime: \"15:55\", endTime: \"16:40\" },\n    { number: 7, startTime: \"17:00\", endTime: \"17:44\" },\n    { number: 8, startTime: \"17:45\", \"endTime\": \"18:30\" },\n    { number: 9, startTime: \"19:30\", \"endTime\": \"20:14\" },\n    { number: 10, startTime: \"20:15\", \"endTime\": \"21:00\" }\n];\n\nasync function selectTimeSlotsType() {\n    const timeSlotsOptions = [\"非夏季作息\", \"夏季作息\"];\n    console.log(\"JS: 提示用户选择作息时间类型。\");\n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择作息时间\",\n        JSON.stringify(timeSlotsOptions),\n        0\n    );\n    return selectedIndex;\n}\n\nasync function importPresetTimeSlots(timeSlots) {\n    console.log(`JS: 准备导入 ${timeSlots.length} 个预设时间段。`);\n\n    if (timeSlots.length > 0) {\n        window.shiguangBridge.showToast(`正在导入 ${timeSlots.length} 个预设时间段...`);\n        try {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n            window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n            console.log(\"JS: 预设时间段导入成功。\");\n        } catch (error) {\n            window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n            console.error('JS: Save Time Slots Error:', error);\n        }\n    } else {\n        window.shiguangBridge.showToast(\"警告：时间段为空，未导入时间段信息。\");\n        console.warn(\"JS: 警告：传入时间段为空，未导入时间段信息。\");\n    }\n}\n\nasync function runImportFlow() {\n    if (isLoginPage()) {\n        window.shiguangBridge.showToast(\"导入失败：请先登录教务系统！\");\n        console.log(\"JS: 检测到当前在登录页面，终止导入。\");\n        return;\n    }\n\n    // 1. 公告和前置检查。\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        console.log(\"JS: 用户取消了导入流程。\");\n        return;\n    }\n\n    const academicYear = await getAcademicYear();\n    if (academicYear === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        console.log(\"JS: 获取学年失败/取消，流程终止。\");\n        return;\n    }\n    console.log(`JS: 已选择学年: ${academicYear}`);\n\n\n    const semesterIndex = await selectSemester();\n    if (semesterIndex === null || semesterIndex === -1) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        console.log(\"JS: 选择学期失败/取消，流程终止。\");\n        return;\n    }\n    console.log(`JS: 已选择学期索引: ${semesterIndex}`);\n\n    const result = await fetchAndParseCourses(academicYear, semesterIndex);\n    if (result === null) {\n        console.log(\"JS: 课程获取或解析失败，流程终止。\");\n        return;\n    }\n    const { courses } = result;\n\n    // 5. 课程数据保存。\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        console.log(\"JS: 课程保存失败，流程终止。\");\n        return;\n    }\n\n    const timeSlotsIndex = await selectTimeSlotsType();\n    let selectedTimeSlots = [];\n\n    if (timeSlotsIndex === 0) {\n        // 0: 非夏季作息\n        selectedTimeSlots = Non_summerTimeSlots;\n        console.log(\"JS: 已选择非夏季作息。\");\n    } else if (timeSlotsIndex === 1) {\n        // 1: 夏季作息\n        selectedTimeSlots = SummerTimeSlots;\n        console.log(\"JS: 已选择夏季作息。\");\n    } else {\n        selectedTimeSlots = Non_summerTimeSlots;\n        console.warn(\"JS: 作息时间选择失败/取消，使用非夏季作息作为默认值。\");\n    }\n    await importPresetTimeSlots(selectedTimeSlots);\n\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    console.log(\"JS: 整个导入流程执行完毕并成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();","KSU_01":"// 喀什大学(ksu.edu.cn) 拾光课程表适配脚本\n// 基于正方教务系统接口适配\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提issues或者提交pr更改,这更加快速\n\n/**\n * 解析周次字符串，处理单双周和周次范围。\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    const weekSets = weekStr.split(',');\n    let weeks = [];\n\n    for (const set of weekSets) {\n        const trimmedSet = set.trim();\n\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周/); // 匹配以数字周结束的\n\n        let start = 0;\n        let end = 0;\n        let processed = false;\n\n        if (rangeMatch) { // 范围, 如 \"1-5周\"\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) { // 单个周, 如 \"6周\"\n            start = end = Number(singleMatch[1]);\n            processed = true;\n        }\n        \n        if (processed) {\n            // 确定单双周\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue; // 单周跳过偶数\n                if (isDouble && w % 2 !== 0) continue; // 双周跳过奇数\n                weeks.push(w);\n            }\n        }\n    }\n\n    // 去重并排序\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 解析 API 返回的 JSON 数据。\n */\nfunction parseJsonData(jsonData) {\n    console.log(\"JS: parseJsonData 正在解析 JSON 数据...\");\n    \n    // 检查JSON结构：新的数据在 kbList 字段中\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        console.warn(\"JS: JSON 数据结构错误或缺少 kbList 字段。\");\n        return []; \n    }\n\n    const rawCourseList = jsonData.kbList;\n    const finalCourseList = [];\n\n    for (const rawCourse of rawCourseList) {\n        // 关键字段检查： kcmc(课名), xm(教师), cdmc(教室), xqj(星期), jcs(节次范围), zcd(周次描述)\n        if (!rawCourse.kcmc || !rawCourse.xm || !rawCourse.cdmc || \n            !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) {\n            continue;\n        }\n\n        const weeksArray = parseWeeks(rawCourse.zcd);\n        \n        // 周次有效性检查\n        if (weeksArray.length === 0) {\n            continue;\n        }\n        \n        // 解析节次范围，例如 \"1-2\"\n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]); \n\n        const day = Number(rawCourse.xqj); // xqj: 星期几 (周一为1, 周日为7)\n        \n        // 数字有效性检查\n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) || day < 1 || day > 7 || startSection > endSection) {\n            // console.warn(`JS: 课程 ${rawCourse.kcmc} 星期或节次数据无效，跳过。`);\n            continue;\n        }\n\n        finalCourseList.push({\n            name: rawCourse.kcmc.trim(),\n            teacher: rawCourse.xm.trim(),\n            position: rawCourse.cdmc.trim(),\n            day: day, \n            startSection: startSection,\n            endSection: endSection, \n            weeks: weeksArray\n        });\n    }\n\n    finalCourseList.sort((a, b) =>\n        a.day - b.day ||\n        a.startSection - b.startSection ||\n        a.name.localeCompare(b.name)\n    );\n    \n    console.log(`JS: JSON 数据解析完成，共找到 ${finalCourseList.length} 门课程。`);\n    return finalCourseList;\n}\n\n/**\n * 检查是否在登录页面。\n * 只有当 URL 精确匹配时，才返回 true。\n */\nfunction isLoginPage() {\n    const url = window.location.href;\n    const loginUrl = \"https://cas.ksu.edu.cn/cas/login?service=https://jwnet.ksu.edu.cn/sso/ddlogin\";\n    \n    // 如果当前 URL 与指定的登录 URL 完全一致，则返回 true (是登录页)\n    return url === loginUrl; \n}\n\n\nfunction validateYearInput(input) {\n    console.log(\"JS: validateYearInput 被调用，输入: \" + input);\n    if (/^[0-9]{4}$/.test(input)) {\n        console.log(\"JS: validateYearInput 验证通过。\");\n        return false;\n    } else {\n        console.log(\"JS: validateYearInput 验证失败。\");\n        return \"请输入四位数字的学年！\";\n    }\n}\n\nasync function promptUserToStart() {\n    console.log(\"JS: 流程开始：显示公告。\");\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function getAcademicYear() {\n    const currentYear = new Date().getFullYear().toString();\n    console.log(\"JS: 提示用户输入学年。\");\n    return await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\",\n        \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\",\n        currentYear,\n        \"validateYearInput\"\n    );\n}\n\nasync function selectSemester() {\n    const semesters = [\"第一学期\", \"第二学期\"];\n    console.log(\"JS: 提示用户选择学期。\");\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesters),\n        0\n    );\n    return semesterIndex;\n}\n\n/**\n * 将选择索引转换为 API 所需的学期码。\n */\nfunction getSemesterCode(semesterIndex) {\n    // semesterIndex 3 (第一学期), 12 (第二学期)\n    return semesterIndex === 0 ? \"3\" : \"12\";\n}\n\n\n/**\n * 请求和解析课程数据\n */\nasync function fetchAndParseCourses(academicYear, semesterIndex) {\n    window.shiguangBridge.showToast(\"正在请求课表数据...\");\n\n    const semesterCode = getSemesterCode(semesterIndex);\n    \n    // API URL 和请求体\n    const xnmXqmBody = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`; \n    const url = \"https://jwnet.ksu.edu.cn/jwglxt/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151\";\n\n    console.log(`JS: 发送请求到 ${url}, body: ${xnmXqmBody}`);\n\n    const requestOptions = {\n        \"headers\": {\n            \"content-type\": \"application/x-www-form-urlencoded;charset=UTF-8\", \n        },\n        \"body\": xnmXqmBody,\n        \"method\": \"POST\",\n        \"credentials\": \"include\"\n    };\n\n    try {\n        const response = await fetch(url, requestOptions);\n\n        if (!response.ok) {\n            throw new Error(`网络请求失败。状态码: ${response.status} (${response.statusText})`);\n        }\n        \n        const jsonText = await response.text();\n        let jsonData;\n        try {\n            jsonData = JSON.parse(jsonText);\n        } catch (e) {\n            console.error('JS: JSON 解析失败，可能是会话过期:', e);\n            window.shiguangBridge.showToast(\"数据返回格式错误，可能是您未成功登录或会话已过期。\");\n            return null;\n        }\n\n        const courses = parseJsonData(jsonData); \n\n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"未找到任何课程数据，请检查所选学年学期是否正确或本学期无课，或教务系统需要二次登录。\");\n            return null;\n        }\n\n        console.log(`JS: 课程数据解析成功，共找到 ${courses.length} 门课程。`);\n        \n        // 默认总周数为 20，周一为一周第一天。\n        const config = {\n            semesterTotalWeeks: 20,\n            firstDayOfWeek: 1 \n        };\n\n        // 返回课程列表和配置信息\n        return { courses: courses, config: config }; \n\n    } catch (error) {\n        window.shiguangBridge.showToast(`请求或解析失败: ${error.message}`);\n        console.error('JS: Fetch/Parse Error:', error);\n        return null;\n    }\n}\n\nasync function saveCourses(parsedCourses) {\n    window.shiguangBridge.showToast(`正在保存 ${parsedCourses.length} 门课程...`);\n    console.log(`JS: 尝试保存 ${parsedCourses.length} 门课程...`);\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses, null, 2));\n        console.log(\"JS: 课程保存成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        console.error('JS: Save Courses Error:', error);\n        return false;\n    }\n}\n\n// 统一作息时间\nconst TimeSlots = [\n    { number: 1, startTime: \"10:00\", endTime: \"10:45\" },\n    { number: 2, startTime: \"10:55\", endTime: \"11:40\" },\n    { number: 3, startTime: \"12:00\", endTime: \"12:45\" },\n    { number: 4, startTime: \"12:55\", endTime: \"13:40\" },\n    { number: 5, startTime: \"13:45\", endTime: \"14:30\" },\n    { number: 6, startTime: \"16:00\", endTime: \"16:45\" },\n    { number: 7, startTime: \"16:55\", endTime: \"17:40\" },\n    { number: 8, startTime: \"18:00\", endTime: \"18:45\" },\n    { number: 9, startTime: \"18:55\", \"endTime\": \"19:40\" },\n    { number: 10, startTime: \"21:00\", \"endTime\": \"21:45\" },\n    { number: 11, startTime: \"21:55\", \"endTime\": \"22:40\" }\n];\n\nasync function importPresetTimeSlots(timeSlots) {\n    console.log(`JS: 准备导入 ${timeSlots.length} 个预设时间段。`);\n\n    if (timeSlots.length > 0) {\n        window.shiguangBridge.showToast(`正在导入 ${timeSlots.length} 个预设时间段...`);\n        try {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n            window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n            console.log(\"JS: 预设时间段导入成功。\");\n        } catch (error) {\n            window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n            console.error('JS: Save Time Slots Error:', error);\n        }\n    } else {\n        window.shiguangBridge.showToast(\"警告：时间段为空，未导入时间段信息。\");\n        console.warn(\"JS: 警告：传入时间段为空，未导入时间段信息。\");\n    }\n}\n\n\nasync function runImportFlow() {\n    if (isLoginPage()) {\n        window.shiguangBridge.showToast(\"导入失败：请先登录教务系统！\");\n        console.log(\"JS: 检测到当前在登录页面，终止导入。\");\n        return;\n    }\n\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        console.log(\"JS: 用户取消了导入流程。\");\n        return;\n    }\n\n    const academicYear = await getAcademicYear();\n    if (academicYear === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        console.log(\"JS: 获取学年失败/取消，流程终止。\");\n        return;\n    }\n    console.log(`JS: 已选择学年: ${academicYear}`);\n\n\n    const semesterIndex = await selectSemester();\n    if (semesterIndex === null || semesterIndex === -1) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        console.log(\"JS: 选择学期失败/取消，流程终止。\");\n        return;\n    }\n    console.log(`JS: 已选择学期索引: ${semesterIndex}`);\n\n    const result = await fetchAndParseCourses(academicYear, semesterIndex);\n    if (result === null) {\n        console.log(\"JS: 课程获取或解析失败，流程终止。\");\n        return;\n    }\n    const { courses, config } = result;\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        console.log(\"JS: 课程保存失败，流程终止。\");\n        return;\n    }\n    \n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        window.shiguangBridge.showToast(`课表配置更新成功！总周数：${config.semesterTotalWeeks}周。`);\n    } catch (error) {\n        window.shiguangBridge.showToast(`课表配置保存失败: ${error.message}`);\n        console.error('JS: Save Config Error:', error);\n    }\n\n\n    await importPresetTimeSlots(TimeSlots);\n\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    console.log(\"JS: 整个导入流程执行完毕并成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();","LYU":"// 临沂大学(lyu.edu.cn) 拾光课程表适配脚本\n// 基于正方教务系统接口适配（webvpn版）\n\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) || a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) || (a.day || 0) - (b.day || 0) ||\n               a.weeks.join(',').localeCompare(b.weeks.join(',')) || (a.startSection || 0) - (b.startSection || 0);\n    });\n    const step1Merged = [];\n    let current = list[0];\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n        const isSame = current.name === next.name && current.teacher === next.teacher &&\n            current.position === next.position && current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n        if (isSame && current.endSection + 1 === next.startSection) {\n            current.endSection = next.endSection;\n        } else if (isSame && current.startSection === next.startSection && current.endSection === next.endSection) {\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) || a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) || (a.day || 0) - (b.day || 0) ||\n               (a.startSection || 0) - (b.startSection || 0) || (a.endSection || 0) - (b.endSection || 0);\n    });\n    const step2Merged = [];\n    let cur = step1Merged[0];\n    for (let i = 1; i < step1Merged.length; i++) {\n        const nxt = step1Merged[i];\n        if (cur.name === nxt.name && cur.teacher === nxt.teacher && cur.position === nxt.position &&\n            cur.day === nxt.day && cur.startSection === nxt.startSection && cur.endSection === nxt.endSection) {\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(cur);\n            cur = nxt;\n        }\n    }\n    step2Merged.push(cur);\n    return step2Merged;\n}\n\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n    const weekSets = weekStr.split(',');\n    let weeks = [];\n    for (const set of weekSets) {\n        const trimmedSet = set.trim();\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周/);\n        let start = 0, end = 0, processed = false;\n        if (rangeMatch) { start = Number(rangeMatch[1]); end = Number(rangeMatch[2]); processed = true; }\n        else if (singleMatch) { start = end = Number(singleMatch[1]); processed = true; }\n        if (processed) {\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue;\n                if (isDouble && w % 2 !== 0) continue;\n                weeks.push(w);\n            }\n        }\n    }\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\nfunction parseJsonData(jsonData) {\n    if (!jsonData || !Array.isArray(jsonData.kbList)) return [];\n    const initialCourseList = [];\n    for (const rawCourse of jsonData.kbList) {\n        if (!rawCourse.kcmc || !rawCourse.xm || !rawCourse.cdmc ||\n            !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) continue;\n        const weeksArray = parseWeeks(rawCourse.zcd);\n        if (weeksArray.length === 0) continue;\n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]);\n        const day = Number(rawCourse.xqj);\n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) ||\n            day < 1 || day > 7 || startSection > endSection) continue;\n        initialCourseList.push({\n            name: rawCourse.kcmc.trim(),\n            teacher: rawCourse.xm.trim(),\n            position: rawCourse.cdmc.trim(),\n            day: day,\n            startSection: startSection,\n            endSection: endSection,\n            weeks: weeksArray\n        });\n    }\n    return mergeAndDistinctCourses(initialCourseList);\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function fetchAcademicOptions() {\n    const url = \"/jwglxt/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151&enlink-vpn\";\n    try {\n        const response = await fetch(url, { method: \"GET\", credentials: \"include\" });\n        if (!response.ok) return null;\n        const htmlText = await response.text();\n        const parser = new DOMParser();\n        const doc = parser.parseFromString(htmlText, \"text/html\");\n        const allYearOptions = Array.from(doc.querySelectorAll(\"#xnm option\"))\n            .filter(opt => opt.value !== \"\")\n            .map(opt => ({ value: opt.value, text: opt.textContent.trim(), selected: opt.hasAttribute(\"selected\") }));\n        const semesterOptions = Array.from(doc.querySelectorAll(\"#xqm option\"))\n            .filter(opt => opt.value !== \"\")\n            .map(opt => ({ value: opt.value, text: opt.textContent.trim(), selected: opt.hasAttribute(\"selected\") }));\n        if (allYearOptions.length === 0 || semesterOptions.length === 0) return null;\n        const selectedIndex = allYearOptions.findIndex(opt => opt.selected);\n        if (selectedIndex === -1) {\n            return {\n                yearOptions: allYearOptions.slice(0, 5), semesterOptions,\n                defaultYearIndex: 0,\n                defaultSemesterIndex: semesterOptions.findIndex(opt => opt.selected) !== -1 ? semesterOptions.findIndex(opt => opt.selected) : 0\n            };\n        }\n        const start = Math.max(0, selectedIndex - 2);\n        const end = Math.min(allYearOptions.length, selectedIndex + 3);\n        return {\n            yearOptions: allYearOptions.slice(start, end), semesterOptions,\n            defaultYearIndex: selectedIndex - start,\n            defaultSemesterIndex: semesterOptions.findIndex(opt => opt.selected) !== -1 ? semesterOptions.findIndex(opt => opt.selected) : 0\n        };\n    } catch (e) { return null; }\n}\n\nasync function selectAcademicYearAndSemester() {\n    const optionsData = await fetchAcademicOptions();\n    if (!optionsData) {\n        window.shiguangBridge.showToast(\"从教务系统读取学年学期失败，请确保登录状态。\");\n        return null;\n    }\n    const { yearOptions, semesterOptions, defaultYearIndex, defaultSemesterIndex } = optionsData;\n    const yearIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学年\", JSON.stringify(yearOptions.map(item => item.text)), defaultYearIndex\n    );\n    if (yearIndex === null || yearIndex === -1) return null;\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\", JSON.stringify(semesterOptions.map(item => item.text)), defaultSemesterIndex\n    );\n    if (semesterIndex === null || semesterIndex === -1) return null;\n    return { academicYear: yearOptions[yearIndex].value, semesterCode: semesterOptions[semesterIndex].value };\n}\n\nasync function fetchSemesterStartDate(academicYear, semesterCode) {\n    const url = \"/jwglxt/kbcx/xskbcxZccx_cxZcByXnxq.html?gnmkdm=N2154&enlink-vpn\";\n    try {\n        const response = await fetch(url, {\n            method: \"POST\",\n            headers: {\n                \"accept\": \"application/json, text/javascript, */*; q=0.01\",\n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: `xnm=${academicYear}&xqm=${semesterCode}`,\n            credentials: \"include\"\n        });\n        if (response.ok) {\n            const json = await response.json();\n            if (Array.isArray(json) && json.length > 0) {\n                const firstWeekObj = json.find(item => String(item.zs) === \"1\" || String(item.zsmc) === \"1\") || json[0];\n                if (firstWeekObj.rq) {\n                    const startDateStr = firstWeekObj.rq.split('/')[0];\n                    if (/^\\d{4}-\\d{2}-\\d{2}$/.test(startDateStr)) return startDateStr;\n                }\n                if (firstWeekObj.zcrq) {\n                    const match = firstWeekObj.zcrq.match(/(\\d{4}-\\d{2}-\\d{2})/);\n                    if (match) return match[1];\n                }\n            }\n        }\n    } catch (e) {}\n    return null;\n}\n\nasync function fetchAndParseCourses(academicYear, semesterCode) {\n    const targetUrl = \"/jwglxt/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151&enlink-vpn\";\n    const [courseResponse, semesterStartDate] = await Promise.all([\n        fetch(targetUrl, {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\" },\n            body: `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`,\n            credentials: \"include\"\n        }),\n        fetchSemesterStartDate(academicYear, semesterCode)\n    ]);\n    try {\n        if (courseResponse.ok) {\n            const jsonData = await courseResponse.json();\n            if (jsonData && jsonData.kbList) {\n                const parsedCourses = parseJsonData(jsonData);\n                if (parsedCourses.length > 0) {\n                    return { courses: parsedCourses, config: { semesterStartDate: semesterStartDate, semesterTotalWeeks: 20 } };\n                }\n            }\n        }\n    } catch (e) {}\n    window.shiguangBridge.showToast(\"未能获取课表数据，请检查网络环境或登录状态。\");\n    return null;\n}\n\nasync function saveCourses(parsedCourses) {\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"课程保存失败: \" + error.message);\n        return false;\n    }\n}\n\nasync function runImportFlow() {\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) { window.shiguangBridge.showToast(\"用户取消了导入。\"); return; }\n    const selection = await selectAcademicYearAndSemester();\n    if (!selection) { window.shiguangBridge.showToast(\"未选择学年学期，导入流程终止。\"); return; }\n    const { academicYear, semesterCode } = selection;\n    const result = await fetchAndParseCourses(academicYear, semesterCode);\n    if (result === null) return;\n    const { courses, config } = result;\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) return;\n    try { await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config)); } catch (e) {}\n    window.shiguangBridge.showToast(\"课程导入成功，共导入 \" + courses.length + \" 门课程！\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();\n","LZU_01":"// 兰州大学本科生教务系统 拾光课程表适配\n// 适配对象: 兰州大学本科生教务管理系统 (jwk.lzu.edu.cn/academic)\n// 使用方式: 登录教务后, 在【学生课表】网格视图 或【课程列表】视图 点击\"执行导入\"\n//\n// 说明(依次尝试, 取第一个成功的):\n//  - 策略C: 行列网格课表解析 (兰大 showTimetable 学生课表页)\n//  - 策略B: 课程列表表格解析 (含多时段、跨框架递归, 支持课程列表/选课结果视图)\n//  - 策略A: URP 标准网格课表解析 (td[id*=\"_\"] + .class_div, 兼容其他 URP 视图)\n//  - 策略B2: 纯文本兜底解析 (innerText 行)\n//  - 作息时间: 页面网格表头动态读取, 否则回退到兰大预设作息(秋季)\n//  - 递归穿透 <iframe>/<frame> 框架, 课程列表页(index_frame.jsp)也可导入\n\n// ========== 兰大预设作息时间 (秋季学期, 校教〔2014〕4号) ==========\n// 1-2节 8:30-10:10 / 3-4节 10:30-12:10 / 5-6节 14:30-16:10 /\n// 7-8节 16:30-18:10 / 9-10节 19:00-20:40 / 第11节 20:50-21:35\nconst LZU_TIME_SLOTS = [\n    { number: 1, startTime: \"08:30\", endTime: \"09:15\" },\n    { number: 2, startTime: \"09:25\", endTime: \"10:10\" },\n    { number: 3, startTime: \"10:30\", endTime: \"11:15\" },\n    { number: 4, startTime: \"11:25\", endTime: \"12:10\" },\n    { number: 5, startTime: \"14:30\", endTime: \"15:15\" },\n    { number: 6, startTime: \"15:25\", endTime: \"16:10\" },\n    { number: 7, startTime: \"16:30\", endTime: \"17:15\" },\n    { number: 8, startTime: \"17:25\", endTime: \"18:10\" },\n    { number: 9, startTime: \"19:00\", endTime: \"19:45\" },\n    { number: 10, startTime: \"19:55\", endTime: \"20:40\" },\n    { number: 11, startTime: \"20:50\", endTime: \"21:35\" }\n];\n\n// ========== 周次解析 ==========\n// 支持: \"1-18周\" / \"1-18周全周\" / \"1-17周单周\" / \"2-18周双周\" /\n//       \"第10,11周\" / \"1-8,10-17周\" / \"1-5,7-8,10-12周双周,13-17周\"\nfunction parseWeeks(weekStr) {\n    const weeks = new Set();\n    if (!weekStr) return [];\n    const text = String(weekStr).replace(/[第周]/g, \"\").replace(/[，;；]/g, \",\");\n    const segments = text.split(\",\");\n    segments.forEach(seg => {\n        const isOdd = seg.includes(\"单\");\n        const isEven = seg.includes(\"双\");\n        const clean = seg.replace(/[单双全]/g, \"\").trim();\n        if (clean.includes(\"-\")) {\n            const [s, e] = clean.split(\"-\").map(Number);\n            if (!isNaN(s) && !isNaN(e)) {\n                for (let w = s; w <= e; w++) {\n                    if (isOdd && w % 2 === 0) continue;\n                    if (isEven && w % 2 !== 0) continue;\n                    weeks.add(w);\n                }\n            }\n        } else if (clean) {\n            const n = Number(clean);\n            if (!isNaN(n) && n > 0) weeks.add(n);\n        }\n    });\n    return Array.from(weeks).sort((a, b) => a - b);\n}\n\n// ========== 节次解析 ==========\n// 支持: \"上午12节\"(1-2) \"上午34节\"(3-4) \"下午56节\"(5-6) \"下午78节\"(7-8)\n//       \"晚9-10节\"(9-10) \"晚9-11节\"(9-11) \"第3节\"(3-3)\nfunction parseSections(sectionStr) {\n    if (!sectionStr) return null;\n    const text = String(sectionStr).replace(/[节第上午下午晚上]/g, \"\");\n    const dashed = text.match(/(\\d+)-(\\d+)/);\n    if (dashed) {\n        return { startSection: parseInt(dashed[1]), endSection: parseInt(dashed[2]) };\n    }\n    const numMatch = text.match(/(\\d+)/);\n    if (!numMatch) return null;\n    const numStr = numMatch[1];\n    // 形如 \"12\"/\"34\"/\"56\"/\"78\" 的连续两位 → 拆成两个节次; 单个数字 → 单节\n    if (numStr.length === 2 && Number(numStr[1]) === Number(numStr[0]) + 1) {\n        return { startSection: Number(numStr[0]), endSection: Number(numStr[1]) };\n    }\n    const n = parseInt(numStr);\n    return { startSection: n, endSection: n };\n}\n\n// ========== 框架穿透辅助 ==========\n// URP 老教务可能把课表放在 <iframe> 或 <frameset><frame> 里, 需要递归遍历所有同源子文档\nfunction allDocuments() {\n    const docs = [];\n    const seen = new Set();\n    const walk = (doc) => {\n        if (!doc || seen.has(doc)) return;\n        seen.add(doc);\n        docs.push(doc);\n        try {\n            doc.querySelectorAll(\"iframe, frame\").forEach(f => {\n                try {\n                    if (f.contentDocument) walk(f.contentDocument);\n                } catch (e) { /* 跨域框架无法访问, 跳过 */ }\n            });\n        } catch (e) { /* ignore */ }\n    };\n    walk(document);\n    return docs;\n}\n\nfunction queryAllInFrames(selector) {\n    let nodes = [];\n    allDocuments().forEach(doc => {\n        try { nodes = nodes.concat(Array.from(doc.querySelectorAll(selector))); } catch (e) { /* ignore */ }\n    });\n    return nodes;\n}\n\n// ========== 策略A: URP 网格课表解析 ==========\nfunction parseGridSchedule() {\n    const courses = [];\n    let timeSlots = null;\n    const allTds = queryAllInFrames('td[id*=\"_\"]');\n    allTds.forEach(td => {\n        const idParts = td.id.split(\"_\");\n        if (idParts.length !== 2) return;\n        const day = parseInt(idParts[0]);\n        if (isNaN(day) || day < 1 || day > 7) return;\n        const classDivs = td.querySelectorAll(\".class_div\");\n        classDivs.forEach(div => {\n            const pTags = div.querySelectorAll(\"p\");\n            if (pTags.length < 5) return;\n            // 兼容两种 DOM 结构: 教师/周次/节次/地点 在 p[1..4] 或 p[2..5]\n            let teacherIdx = 2, weekIdx = 3, sectionIdx = 4, posIdx = 5;\n            const p1Text = pTags[1] ? pTags[1].textContent.trim() : \"\";\n            if (p1Text && !/\\d/.test(p1Text) && !p1Text.includes(\"周\") && p1Text.length < 10) {\n                teacherIdx = 1; weekIdx = 2; sectionIdx = 3; posIdx = 4;\n            }\n            const name = pTags[0].textContent.trim();\n            const teacher = (pTags[teacherIdx] ? pTags[teacherIdx].textContent : \"\").trim().replace(/\\*+/g, \" \").replace(/\\s+/g, \" \");\n            const weeks = parseWeeks(pTags[weekIdx] ? pTags[weekIdx].textContent : \"\");\n            const sec = parseSections(pTags[sectionIdx] ? pTags[sectionIdx].textContent : \"\");\n            const position = pTags[posIdx] ? pTags[posIdx].textContent.trim() : \"未知地点\";\n            if (name && weeks.length && sec) {\n                courses.push({\n                    name, teacher, position, day,\n                    startSection: sec.startSection, endSection: sec.endSection, weeks\n                });\n            }\n        });\n    });\n    // 尝试从网格表头动态读取作息时间: <th id=\"0_1\">... (08:30-09:15)\n    const ths = queryAllInFrames('th[id^=\"0_\"]');\n    const slots = [];\n    ths.forEach(th => {\n        const n = parseInt(th.id.split(\"_\")[1]);\n        const m = (th.textContent || \"\").match(/\\((\\d{2}:\\d{2})-(\\d{2}:\\d{2})\\)/);\n        if (!isNaN(n) && m) slots.push({ number: n, startTime: m[1], endTime: m[2] });\n    });\n    if (slots.length) timeSlots = slots.sort((a, b) => a.number - b.number);\n    return { courses, timeSlots };\n}\n\n// ========== 策略B: 列表/选课结果课表解析 ==========\n// 适配\"个人课表/选课结果\"列表视图:\n//  - 表格行结构: 课程信息行(课程号/课序号/课程名/教师...) 之后可跟 1 行或多行\"排课行\"\n//  - 或 div 布局: innerText 中课程信息行与排课行相邻\n// 排课字符串形如: \"1-18周全周 星期一 下午56节 天山堂A504\"\nconst WEEK_DAY_PATTERN = /([第]?[0-9,\\-，]+周(?:全周|单周|双周)?)\\s*(星期[一二三四五六日天]|周[一二三四五六日天])\\s*((?:上午|下午|晚上|晚)?\\s*\\d+(?:-\\d+)?节)\\s*(\\S+)/;\nconst WEEK_DAY_PATTERN_NO_POS = /([第]?[0-9,\\-，]+周(?:全周|单周|双周)?)\\s*(星期[一二三四五六日天]|周[一二三四五六日天])\\s*((?:上午|下午|晚上|晚)?\\s*\\d+(?:-\\d+)?节)/;\nconst DAY_MAP = { \"一\": 1, \"二\": 2, \"三\": 3, \"四\": 4, \"五\": 5, \"六\": 6, \"日\": 7, \"天\": 7 };\n\nfunction dayNum(dayText) {\n    // 兼容 \"星期一\" / \"周一\" / \"礼拜一\" / \"星期天\"\n    return dayFromText(dayText);\n}\n\n// 从文本片段数组中提取课程信息 (课程号 + 课程名 + 教师)\nfunction findCourseInfo(tokens) {\n    // 课程号特征: 形如 2402003 / 1402401b / 101402001(3)\n    const codeIdx = tokens.findIndex(c => /^\\d{3,}[a-zA-Z]*(\\(\\d+\\))?$/.test(c) && c.length <= 12);\n    if (codeIdx === -1) return null;\n    // 课程名 = 课程号之后第一个非纯数字且不含\"周\"的片段; 教师 = 再下一个片段\n    for (let i = codeIdx + 1; i < tokens.length; i++) {\n        if (!/^[\\d.\\-]+$/.test(tokens[i]) && !tokens[i].includes(\"周\")) {\n            return {\n                name: tokens[i],\n                teacher: (tokens[i + 1] || \"\").replace(/\\*+/g, \" \").replace(/\\s+/g, \" \")\n            };\n        }\n    }\n    return null;\n}\n\n// 从文本中提取排课信息 (周次/星期/节次/地点); nextText 用于\"地点在下一段\"的兜底\nfunction extractSchedule(text, nextText) {\n    let m = text.match(WEEK_DAY_PATTERN);\n    if (m) {\n        return { weeks: parseWeeks(m[1]), day: dayNum(m[2]), sec: parseSections(m[3]), position: m[4] };\n    }\n    m = text.match(WEEK_DAY_PATTERN_NO_POS);\n    if (m) {\n        const rest = text.slice(text.indexOf(m[3]) + m[3].length).trim();\n        const position = rest.split(/\\s+/)[0] || (nextText || \"\").split(/\\s+/)[0] || \"\";\n        return { weeks: parseWeeks(m[1]), day: dayNum(m[2]), sec: parseSections(m[3]), position };\n    }\n    return null;\n}\n\nfunction pushCourse(courses, info, sched) {\n    if (!info || !sched || !info.name || !sched.weeks.length || !sched.sec || !sched.day) return;\n    courses.push({\n        name: info.name,\n        teacher: info.teacher,\n        position: sched.position,\n        day: sched.day,\n        startSection: sched.sec.startSection,\n        endSection: sched.sec.endSection,\n        weeks: sched.weeks\n    });\n}\n\n// 从文本中提取全部排课信息 (一个单元格内可能有多个时段)\nfunction extractAllSchedules(text) {\n    const out = [];\n    const re = new RegExp(WEEK_DAY_PATTERN.source, \"g\");\n    let m;\n    while ((m = re.exec(text)) !== null) {\n        const weeks = parseWeeks(m[1]);\n        const day = dayNum(m[2]);\n        const sec = parseSections(m[3]);\n        const position = m[4] || \"\";\n        if (weeks.length && day && sec) {\n            out.push({ weeks, day, sec: { startSection: sec.startSection, endSection: sec.endSection }, position });\n        }\n    }\n    return out;\n}\n\n// 解析表格行结构 (兰大列表视图: 每门课一行, 上课时间地点在同一格内可含多个时段;\n// 也兼容\"课程信息行 + 后续排课行\"的两行结构)\nfunction parseListSchedule() {\n    const courses = [];\n    const rows = queryAllInFrames(\"tr\");\n    let pendingInfo = null;\n    rows.forEach(row => {\n        // 单元格内 <br> 转成空格再拼接, 避免多时段粘连(如 \"...B604 1-17周单周 ...\")\n        const cells = Array.from(row.querySelectorAll(\"td, th\")).map(c => {\n            const parts = brTextLines(c).join(\" \") || (c.textContent || \"\").trim();\n            return parts;\n        }).filter(Boolean);\n        const rowText = cells.join(\" \");\n        const info = findCourseInfo(cells);\n        if (info) pendingInfo = info;\n        if (pendingInfo) {\n            const scheds = extractAllSchedules(rowText);\n            scheds.forEach(s => pushCourse(courses, pendingInfo, s));\n        }\n    });\n    return { courses: dedupeAndMergeBlocks(courses), timeSlots: null };\n}\n\n// 解析整页文本行 (innerText), 适配 div 布局 / 复制的文本结构\nfunction parseTextSchedule() {\n    const courses = [];\n    const allLines = [];\n    allDocuments().forEach(doc => {\n        const bodyText = (doc.body && doc.body.innerText) || \"\";\n        const ls = bodyText.replace(/ /g, \" \").split(/\\r?\\n/).map(l => l.trim()).filter(Boolean);\n        ls.forEach(l => allLines.push(l));\n    });\n    let pendingInfo = null;\n    allLines.forEach((line, idx) => {\n        const tokens = line.split(/\\s+/).filter(Boolean);\n        const info = findCourseInfo(tokens);\n        const nextLine = allLines[idx + 1] || \"\";\n        if (info) {\n            pendingInfo = info;\n            const sched = extractSchedule(line, nextLine);\n            if (sched) pushCourse(courses, info, sched);\n        } else if (pendingInfo) {\n            const sched = extractSchedule(line, nextLine);\n            if (sched) pushCourse(courses, pendingInfo, sched);\n        }\n    });\n    return { courses, timeSlots: null };\n}\n\n// ========== 策略C: 行列网格解析 (兰大 showTimetable.do 学生课表) ==========\n// 结构: 表头行含\"周一..周日\"; 每门课是一个 td(id 形如 \"1-2268\", 首位数字=真实星期几),\n//       内容按 <br> 分隔多行: 课程名<< >>;序号/地点/教师/周次/自身节次(如\"晚9-11节\")/备注\nfunction cleanCourseName(s) {\n    // \"&lt;&lt;数学物理方法Ⅰ&gt;&gt;;2\" → \"数学物理方法Ⅰ\"; 兼容无 <</>> 情况\n    let n = String(s || \"\").replace(/&lt;|&gt;/g, \"\").replace(/<</g, \"\").split(\">>\")[0];\n    n = n.replace(/;[0-9]+$/, \"\").replace(/[;0-9]+$/, \"\").trim();\n    return n;\n}\n\nfunction isBuildingLike(t) {\n    return /(堂|楼|馆|室|区|操场)/.test(t) || /[A-Za-z]+\\s*\\d+/.test(t);\n}\n\n// 按 <br> 分行提取单元格纯文本 (兼容 textContent 不产生换行的问题)\nfunction brTextLines(cell) {\n    const raw = cell.innerHTML || \"\";\n    const segs = raw.split(/<br\\s*\\/?\\s*>/i);\n    const out = [];\n    segs.forEach(seg => {\n        const clean = seg.replace(/<[^>]+>/g, \"\")\n            .replace(/&lt;/g, \"<\").replace(/&gt;/g, \">\")\n            .replace(/&nbsp;/g, \" \").replace(/&amp;/g, \"&\").trim();\n        if (clean) out.push(clean);\n    });\n    return out;\n}\n\n// 从文本中识别节次区间 (如 \"晚9-11节\" \"上午34节\" \"第1-2节\")\nfunction parseSectionFromText(text) {\n    if (!text) return null;\n    const m = String(text).match(/((?:上午|下午|晚上|晚|第)?\\s*\\d{1,2}\\s*[-—~至]\\s*\\d{1,2}\\s*节|(?:上午|下午|晚上|晚|第)?\\s*\\d{1,2}\\s*节)/);\n    if (m) return parseSections(m[1]);\n    return null;\n}\n\n// 从课程格子 id (如 \"5-2268\") 首位取真实星期\nfunction cellDay(cell, fallback) {\n    const m = (cell.id || \"\").match(/^([1-7])-/);\n    return m ? parseInt(m[1]) : fallback;\n}\n\n// 解析单个课程格子 → 返回课程块数组\nfunction parseCourseCell(cell, day, fallbackSection) {\n    const results = [];\n    const lines = brTextLines(cell);\n    if (!lines.length) return results;\n    let cur = null;\n    const flush = () => {\n        if (cur) results.push(cur);\n        cur = null;\n    };\n    lines.forEach(line => {\n        const secL = /周/.test(line) ? null : parseSectionFromText(line);\n        const isNameLine = line.includes(\">>\") || line.includes(\"<<\")\n            || (!cur && !/周|学时|讲课|堂|楼|馆|节/.test(line) && line.length <= 40 && !/^\\d/.test(line));\n        if (isNameLine) {\n            flush();\n            cur = { name: cleanCourseName(line), teacher: \"\", position: \"\", weeks: [], day: day, startSection: null, endSection: null };\n        } else if (cur) {\n            if (secL) {\n                cur.startSection = secL.startSection;\n                cur.endSection = secL.endSection;\n            } else if (/[0-9]+周/.test(line) || /全周|单周|双周/.test(line)) {\n                cur.weeks = parseWeeks(line);\n            } else if (/学时|讲课|备注|实践/.test(line) || /^\\d{1,2}:\\d{2}/.test(line)) {\n                // 备注/时间行忽略\n            } else if (isBuildingLike(line)) {\n                cur.position = line;\n            } else {\n                cur.teacher = (cur.teacher ? cur.teacher + \" \" : \"\") + line;\n            }\n        }\n    });\n    flush();\n    // 自身文本未给出节次时, 用行标签节次\n    results.forEach(b => {\n        if (!b.startSection && fallbackSection) {\n            b.startSection = fallbackSection.startSection;\n            b.endSection = fallbackSection.endSection;\n        }\n    });\n    return results;\n}\n\nfunction parsePeriodGrid() {\n    const blocks = [];\n    const tables = queryAllInFrames(\"table\");\n    for (const table of tables) {\n        const dayInfo = tableDayColumns(table);\n        if (!dayInfo) continue;\n        const trs = Array.from(table.querySelectorAll(\"tr\")).filter(r => r.querySelectorAll(\"td,th\").length);\n        let carriedSection = null;\n        for (let r = dayInfo.headerRow + 1; r < trs.length; r++) {\n            const cells = Array.from(trs[r].querySelectorAll(\"td,th\"));\n            // 行节次: 找不含\"周\"、内容短、含 节/时间 的标签单元格 (课程格都含周次, 不会误判)\n            let rowSection = null;\n            for (const c of cells) {\n                const t = (c.textContent || \"\").trim();\n                if (!t || t.length > 60 || /周/.test(t)) continue;\n                if (!/节|^\\d{1,2}:\\d{2}/.test(t)) continue;\n                rowSection = parseSectionFromText(t);\n                if (rowSection) break;\n            }\n            if (!rowSection) rowSection = carriedSection;\n            else carriedSection = rowSection;\n            if (!rowSection) continue;\n            // 逐格取课程\n            for (let ci = 0; ci < cells.length; ci++) {\n                const cell = cells[ci];\n                const txt = (cell.textContent || \"\").trim();\n                if (!txt || txt.length < 4 || /^(&nbsp;|\\s|-|—|・|\\.)*$/.test(txt)) continue;\n                const looksCourse = /<<|>>/.test(txt) || (/周/.test(txt) && !dayFromText(txt));\n                if (!looksCourse) continue;\n                const day = cellDay(cell, dayInfo.colDay[ci] || 0);\n                parseCourseCell(cell, day, rowSection).forEach(b => blocks.push(b));\n            }\n        }\n    }\n    return { courses: dedupeAndMergeBlocks(blocks), timeSlots: null };\n}\n\n// 归一化 + 同课相邻节次合并 + 去重\nfunction dedupeAndMergeBlocks(blocks) {\n    const slotCount = LZU_TIME_SLOTS.length; // 兰大最多11节\n    const norm = [];\n    blocks.forEach(b => {\n        let s = b.startSection, e = b.endSection;\n        if (!s || !e || e < s || !b.name || !b.weeks.length || !b.day) return;\n        if (s > slotCount) return;\n        if (e > slotCount) e = slotCount;\n        norm.push({ name: b.name, teacher: (b.teacher || \"\").trim(), position: b.position || \"\", day: b.day, startSection: s, endSection: e, weeks: b.weeks });\n    });\n    const groups = {};\n    const wkKey = w => w.join(\",\");\n    norm.forEach(b => {\n        const g = b.name + \"|\" + b.teacher + \"|\" + b.position + \"|\" + b.day + \"|\" + wkKey(b.weeks);\n        (groups[g] = groups[g] || []).push(b);\n    });\n    const out = [];\n    Object.keys(groups).forEach(g => {\n        const grp = groups[g];\n        const first = grp[0];\n        if (grp.every(b => b.startSection === first.startSection && b.endSection === first.endSection)) {\n            out.push(first); // 完全重复 → 保留一条\n            return;\n        }\n        grp.sort((a, b) => a.startSection - b.startSection);\n        let cur = { ...grp[0] };\n        for (let i = 1; i < grp.length; i++) {\n            const b = grp[i];\n            if (b.startSection <= cur.endSection + 1) {\n                cur.endSection = Math.max(cur.endSection, b.endSection);\n                const ws = new Set(cur.weeks.concat(b.weeks));\n                cur.weeks = Array.from(ws).sort((x, y) => x - y);\n            } else {\n                out.push(cur);\n                cur = { ...b };\n            }\n        }\n        out.push(cur);\n    });\n    return out;\n}\n\n// ========== 诊断收集 (全部策略失败时输出表格 DOM 骨架, 便于定位结构) ==========\n// 短探针: 纯数字概览, 放在第一行, 抗复制乱码\nfunction collectProbe() {\n    const docs = allDocuments();\n    let frTotal = 0, frOk = 0;\n    try {\n        document.querySelectorAll(\"iframe, frame\").forEach(f => {\n            frTotal++;\n            try { if (f.contentDocument) frOk++; } catch (e) {}\n        });\n    } catch (e) {}\n    let tables = 0, trs = 0, tds = 0, hdrTbl = 0, codeCells = 0, schedCells = 0;\n    docs.forEach(doc => {\n        try {\n            tables += doc.querySelectorAll(\"table\").length;\n            trs += doc.querySelectorAll(\"tr\").length;\n            tds += doc.querySelectorAll(\"td, th\").length;\n            doc.querySelectorAll(\"table\").forEach(t => {\n                if ((t.innerText || t.textContent || \"\").indexOf(\"课程号\") > -1) hdrTbl++;\n            });\n        } catch (e) {}\n        try {\n            doc.querySelectorAll(\"td\").forEach(cd => {\n                const t = (cd.textContent || \"\").trim();\n                if (/^\\d{3,}[a-zA-Z]*(\\(\\d+\\))?$/.test(t) && t.length <= 12) codeCells++;\n                if (/[0-9]+周/.test(t) && /(?:星期|周)[一二三四五六日天]/.test(t)) schedCells++;\n            });\n        } catch (e) {}\n    });\n    return \"PROBE: 文档=\" + docs.length\n        + \" 框架=\" + frTotal + \"/\" + frOk\n        + \" 表=\" + tables + \" 行=\" + trs + \" 格=\" + tds\n        + \" 含课程号表=\" + hdrTbl\n        + \" 课程代码格=\" + codeCells\n        + \" 排课格=\" + schedCells;\n}\n\nfunction dayFromText(t) {\n    // 支持 \"星期一\" / \"周一\" / \"礼拜一\" 等表头\n    const s = String(t || \"\").replace(/星期|礼拜|周/g, \"\");\n    return DAY_MAP[s] || 0;\n}\n\n// 找出\"周一..周日\"表头所在行及列→星期映射\nfunction tableDayColumns(table) {\n    const trs = Array.from(table.querySelectorAll(\"tr\")).filter(r => r.querySelectorAll(\"td,th\").length);\n    for (let i = 0; i < trs.length; i++) {\n        const cells = Array.from(trs[i].querySelectorAll(\"td,th\"));\n        const map = {};\n        cells.forEach((c, ci) => {\n            const d = dayFromText(c.textContent);\n            if (d) map[ci] = d;\n        });\n        if (Object.keys(map).length >= 5) return { headerRow: i, colDay: map };\n    }\n    return null;\n}\n\n// 单元格摘要: 标签/id/class + innerHTML 开头(暴露嵌套结构)\nfunction cellBrief(cell) {\n    const id = cell.id || \"\";\n    const cls = (typeof cell.className === \"string\" ? cell.className : (cell.className && cell.className.baseVal) || \"\").toString();\n    const tag = cell.tagName || \"\";\n    let s = \"<\" + tag + (id ? \"#\" + id : \"\") + (cls ? \".\" + String(cls).slice(0, 14) : \"\") + \">\";\n    s += (cell.innerHTML || \"\").replace(/\\s+/g, \" \").trim().slice(0, 36);\n    return s;\n}\n\nfunction collectDiagnostics() {\n    const L = [collectProbe()];\n    try { L.push(\"URL尾: \" + (window.location.href || \"\").slice(-90)); } catch (e) {}\n    const tables = queryAllInFrames(\"table\");\n    L.push(\"tables=\" + tables.length);\n    tables.forEach((tb, ti) => {\n        const dayInfo = tableDayColumns(tb);\n        const trs = Array.from(tb.querySelectorAll(\"tr\")).filter(r => r.querySelectorAll(\"td,th\").length);\n        if (!dayInfo) return; // 只展示含\"周一..周日\"的课表表格\n        L.push(\"== 表T\" + ti + \" tr=\" + trs.length + \" 表头行=\" + dayInfo.headerRow + \" 列→星期: \" + JSON.stringify(dayInfo.colDay));\n        const start = Math.max(0, dayInfo.headerRow);\n        let dumped = false;\n        for (let r = start; r < Math.min(trs.length, start + 12); r++) {\n            const cells = Array.from(trs[r].querySelectorAll(\"td,th\"));\n            const bs = cells.map(cellBrief);\n            L.push(\"R\" + r + \"(\" + cells.length + \"): \" + bs.join(\" ⏐ \"));\n            // 找第一个疑似\"课程格子\"(文本含\"周\"且长度适中), 输出其完整 innerHTML\n            if (!dumped) {\n                const courseCell = cells.find((c) => {\n                    const t = (c.textContent || \"\").trim();\n                    return t.length > 6 && t.length < 500 && /周/.test(t);\n                });\n                if (courseCell) {\n                    L.push(\"  [首个课程格子innerHTML] \" + (courseCell.innerHTML || \"\").replace(/\\s+/g, \" \").slice(0, 500));\n                    dumped = true;\n                }\n            }\n        }\n    });\n    return L.join(\"\\n\");\n}\n\n// ========== 流程控制 ==========\nasync function runImportFlow() {\n    try {\n        const confirmed = await window.shiguangBridgePromise.showAlert(\n            \"兰州大学教务导入\",\n            \"请先登录教务系统并进入【学生课表】页面（网格视图），再点击确定开始导入。\",\n            \"开始导入\"\n        );\n        if (!confirmed) return;\n\n        // 依次尝试各解析策略, 取第一个成功的\n        let result = null;\n        let usedStrategy = \"\";\n        const strategies = [\n            { name: \"行列网格课表\", fn: parsePeriodGrid },\n            { name: \"网格课表\", fn: parseGridSchedule },\n            { name: \"列表课表(表格)\", fn: parseListSchedule },\n            { name: \"列表课表(文本)\", fn: parseTextSchedule }\n        ];\n        for (const s of strategies) {\n            const r = s.fn();\n            if (r.courses.length) {\n                result = r;\n                usedStrategy = s.name;\n                break;\n            }\n        }\n\n        if (!result || !result.courses.length) {\n            try {\n                const diag = collectDiagnostics();\n                await window.shiguangBridgePromise.showAlert(\n                    \"未检测到课表数据\",\n                    diag + \"\\n\\n----\\n请确认处于【学生课表】网格视图。若仍有问题, 可将以上信息截图反馈给维护者, 便于改进适配\",\n                    \"知道了\"\n                );\n            } catch (e) {\n                window.shiguangBridge.showToast(\"未检测到课表数据，请确认当前页面是个人课表后重试\");\n            }\n            return;\n        }\n\n        const timeSlots = result.timeSlots && result.timeSlots.length ? result.timeSlots : LZU_TIME_SLOTS;\n\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(result.courses));\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\n            semesterStartDate: null,\n            semesterTotalWeeks: 20,\n            defaultClassDuration: 45,\n            defaultBreakDuration: 10,\n            firstDayOfWeek: 1\n        }));\n\n        window.shiguangBridge.showToast(`兰州大学课表导入成功(${usedStrategy}): 共 ${result.courses.length} 条安排`);\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        console.error(\"兰州大学课表导入失败:\", error);\n        window.shiguangBridge.showToast(\"课表导入失败: \" + (error.message || error));\n    }\n}\n\nrunImportFlow();\n","LUT":"// 兰州理工大学教务系统课程表适配\r\n\r\nconst API_ROOT = \"/jwapp/sys\";\r\nconst TERM_URL = `${API_ROOT}/wdkb/modules/jshkcb/dqxnxq.do`;\r\nconst COURSE_URL = `${API_ROOT}/wdkb/modules/xskcb/cxxszhxqkb.do`;\r\nconst LUT_TIME_SLOTS = [\r\n    { number: 1, startTime: \"08:00\", endTime: \"08:50\" },\r\n    { number: 2, startTime: \"09:00\", endTime: \"09:50\" },\r\n    { number: 3, startTime: \"10:10\", endTime: \"11:00\" },\r\n    { number: 4, startTime: \"11:10\", endTime: \"12:00\" },\r\n    { number: 5, startTime: \"14:30\", endTime: \"15:20\" },\r\n    { number: 6, startTime: \"15:30\", endTime: \"16:20\" },\r\n    { number: 7, startTime: \"16:40\", endTime: \"17:30\" },\r\n    { number: 8, startTime: \"17:40\", endTime: \"18:30\" },\r\n    { number: 9, startTime: \"19:30\", endTime: \"20:20\" },\r\n    { number: 10, startTime: \"20:30\", endTime: \"21:20\" }\r\n];\r\n\r\nfunction rowsOf(data, name) {\r\n    return data && data.datas && data.datas[name] && Array.isArray(data.datas[name].rows)\r\n        ? data.datas[name].rows : [];\r\n}\r\n\r\nasync function requestJson(url, params) {\r\n    const options = { credentials: \"include\" };\r\n    if (params) {\r\n        options.method = \"POST\";\r\n        options.headers = { \"Content-Type\": \"application/x-www-form-urlencoded; charset=UTF-8\" };\r\n        options.body = new URLSearchParams(params);\r\n    }\r\n    const response = await fetch(url, options);\r\n    if (!response.ok) throw new Error(`请求失败: ${response.status} ${url}`);\r\n    const data = await response.json();\r\n    if (data.code && data.code !== \"0\") throw new Error(`教务系统拒绝请求: ${url}`);\r\n    return data;\r\n}\r\n\r\nfunction parseWeeks(value, maxWeek) {\r\n    const text = String(value || \"\").replace(/[第周]/g, \"\").replace(/，/g, \",\");\r\n    const numbers = text.match(/\\d+/g) || [];\r\n    const odd = /单/.test(text);\r\n    const even = /双/.test(text);\r\n    const weeks = new Set();\r\n    const add = week => {\r\n        if (week > 0 && week <= maxWeek && (!odd && !even || odd && week % 2 === 1 || even && week % 2 === 0)) {\r\n            weeks.add(week);\r\n        }\r\n    };\r\n    if (!numbers.length || /全周|全部/.test(text)) {\r\n        for (let week = 1; week <= maxWeek; week++) add(week);\r\n    } else {\r\n        numbers.forEach(number => add(Number(number)));\r\n        const rangePattern = /(\\d+)\\s*[至到-]\\s*(\\d+)/g;\r\n        let match;\r\n        while ((match = rangePattern.exec(text))) {\r\n            for (let week = Number(match[1]); week <= Number(match[2]); week++) add(week);\r\n        }\r\n    }\r\n    return Array.from(weeks).sort((a, b) => a - b);\r\n}\r\n\r\nfunction parseTime(value) {\r\n    const match = String(value || \"\").match(/(\\d{1,2}):(\\d{2})/);\r\n    return match ? `${match[1].padStart(2, \"0\")}:${match[2]}` : null;\r\n}\r\n\r\nfunction getTimeSlots(rows) {\r\n    return rows.map((row, index) => ({\r\n        number: Number(row.DM || index + 1),\r\n        startTime: parseTime(row.KSSJ || row.START_TIME),\r\n        endTime: parseTime(row.JSSJ || row.END_TIME)\r\n    })).filter(slot => slot.startTime && slot.endTime).sort((a, b) => a.number - b.number);\r\n}\r\n\r\nasync function loadLutSchedule() {\r\n    const termData = await requestJson(TERM_URL);\r\n    const term = rowsOf(termData, \"dqxnxq\")[0];\r\n    if (!term || !term.DM) throw new Error(\"未找到当前学期，请先登录教务系统\");\r\n\r\n    const courseData = await requestJson(COURSE_URL, { XNXQDM: term.DM });\r\n    const courseRows = rowsOf(courseData, \"cxxszhxqkb\");\r\n    const timeSlots = LUT_TIME_SLOTS;\r\n    const courses = courseRows.flatMap(row => {\r\n        const day = Number(row.SKXQ);\r\n        const startSection = Number(row.KSJC);\r\n        const endSection = Number(row.JSJC);\r\n        const weeks = parseWeeks(row.ZCMC, 30);\r\n        if (!row.KCM || !day || !startSection || !endSection || !weeks.length) return [];\r\n        return [{\r\n            name: String(row.KCM).trim(),\r\n            teacher: String(row.SKJS || \"\").trim(),\r\n            position: String(row.JASMC || \"\").trim(),\r\n            day,\r\n            startSection,\r\n            endSection,\r\n            weeks\r\n        }];\r\n    });\r\n    return { term, courses, timeSlots };\r\n}\r\n\r\nasync function importLutCourses() {\r\n    const result = await loadLutSchedule();\r\n    if (!result.courses.length) throw new Error(\"课表接口未返回可导入课程，请检查当前学期\");\r\n\r\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(result.courses));\r\n    if (result.timeSlots.length) {\r\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(result.timeSlots));\r\n    }\r\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\r\n        semesterStartDate: null,\r\n        semesterTotalWeeks: Math.max(...result.courses.flatMap(course => course.weeks), 20),\r\n        defaultClassDuration: 45,\r\n        defaultBreakDuration: 10,\r\n        firstDayOfWeek: 1\r\n    }));\r\n    window.shiguangBridge.showToast(`兰州理工大学课表导入成功，共 ${result.courses.length} 条安排`);\r\n    window.shiguangBridge.notifyTaskCompletion();\r\n}\r\n\r\n(async function run() {\r\n    try {\r\n        await importLutCourses();\r\n    } catch (error) {\r\n        console.error(\"兰州理工大学课表导入失败:\", error);\r\n        window.shiguangBridge.showToast(`课表导入失败: ${error.message}`);\r\n    }\r\n})();\r\n","LIT_01":"// 洛阳理工学院教务（乘方教务）适配器\n// 流程：获取学期列表 → 选择学期 → 导入课表与教务作息\n// 接口：\n//   GET  /new/student/xsgrkb/week.page            课表页数据（学期下拉 + 作息表，直接请求获取，无需进入课表页面）\n//   POST /new/student/xsgrkb/getCalendarWeekDatas  整学期课程数据\n\n// 周次字符串\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n    const weeks = weekStr.split(\",\").map(w => parseInt(w.trim(), 10)).filter(w => !isNaN(w) && w > 0);\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n// 解析按周场地字符串\nfunction parseVenueWeeks(jxcdmc2) {\n    const venueMap = new Map();\n    let lastRoom = null;\n    String(jxcdmc2 || \"\").split(\",\").forEach(part => {\n        const match = part.trim().match(/^(.*?)-(\\d+)$/);\n        if (!match) return;\n        const room = match[1].trim();\n        const week = parseInt(match[2], 10);\n        if (room) lastRoom = room;\n        if (!lastRoom || isNaN(week)) return;\n        if (!venueMap.has(lastRoom)) venueMap.set(lastRoom, []);\n        venueMap.get(lastRoom).push(week);\n    });\n    return venueMap;\n}\n\n// 课程地点\nfunction resolvePosition(item) {\n    const primary = String(item.jxcdmc || \"\").trim();\n    if (primary) return primary;\n    if (String(item.bapjxcd || \"\") === \"1\") return \"不用场地\";\n    return \"待定\";\n}\n\nfunction cleanTeacherName(raw) {\n    return String(raw || \"\").replace(/\\[[^\\]]*\\]/g, \"\").trim();\n}\n\n// 课表接口数据\nfunction parseCourseList(apiJson, slotMap) {\n    if (!apiJson) throw new Error(\"课表接口无响应\");\n    if (apiJson.code !== 0) {\n        const message = String(apiJson.message || \"\").trim();\n        throw new Error(message || `课表接口返回错误（code=${apiJson.code}）`);\n    }\n    if (!Array.isArray(apiJson.data)) throw new Error(\"课表接口返回格式不正确\");\n\n    const courseMap = new Map();\n    apiJson.data.forEach(item => {\n        const day = parseInt(item.xq, 10);\n        const startSection = parseInt(item.ps, 10);\n        const endSection = parseInt(item.pe, 10);\n        const allWeeks = parseWeeks(item.zc);\n        if (!item.kcmc || !allWeeks.length || isNaN(day) || isNaN(startSection) || isNaN(endSection) ||\n            day < 1 || day > 7 || startSection > endSection) return;\n\n        const teacher = cleanTeacherName(item.teaxms || item.pkr) || \"未知\";\n        const venues = parseVenueWeeks(item.jxcdmc2);\n        const venueEntries = venues.size > 0\n            ? Array.from(venues.entries(), ([position, weeks]) => ({ position, weeks: [...new Set(weeks)].sort((a, b) => a - b) }))\n            : [{ position: resolvePosition(item), weeks: allWeeks }];\n\n        venueEntries.forEach(({ position, weeks }) => {\n            const course = { name: item.kcmc.trim(), teacher, position, day, startSection, endSection, weeks };\n\n            const actualStart = String(item.qssj || \"\").slice(0, 5);\n            const actualEnd = String(item.jssj || \"\").slice(0, 5);\n            const expectedStart = slotMap[startSection] && slotMap[startSection].start;\n            const expectedEnd = slotMap[endSection] && slotMap[endSection].end;\n            if (actualStart && actualEnd && (actualStart !== expectedStart || actualEnd !== expectedEnd)) {\n                course.isCustomTime = true;\n                course.customStartTime = actualStart;\n                course.customEndTime = actualEnd;\n            }\n\n            const key = [course.name, teacher, position, day,\n                course.isCustomTime ? actualStart + actualEnd : `${startSection}-${endSection}`].join(\"__\");\n            const existing = courseMap.get(key);\n            if (existing) {\n                existing.weeks = [...new Set(existing.weeks.concat(weeks))].sort((a, b) => a - b);\n            } else {\n                courseMap.set(key, course);\n            }\n        });\n    });\n\n    return Array.from(courseMap.values()).sort((a, b) =>\n        a.day - b.day || a.startSection - b.startSection || a.endSection - b.endSection || a.name.localeCompare(b.name)\n    );\n}\n\n// 从 week.page 源码提取作息表\nfunction parseBusinessHoursFromHtml(htmlText) {\n    const match = htmlText.match(/var\\s+businessHours\\s*=\\s*\\$\\.parseJSON\\('(\\[.*?\\])'\\);/);\n    const slots = [];\n    const map = {};\n    if (match) {\n        JSON.parse(match[1]).forEach(item => {\n            const number = parseInt(item.jcdm, 10);\n            const startTime = String(item.qssj || \"\").slice(0, 5);\n            const endTime = String(item.jssj || \"\").slice(0, 5);\n            if (isNaN(number) || !startTime || !endTime) return;\n            slots.push({ number, startTime, endTime });\n            map[number] = { start: startTime, end: endTime };\n        });\n        slots.sort((a, b) => a.number - b.number);\n    }\n    return { slots, map };\n}\n\n// 读取页面中的学期下拉框\nfunction extractSemesterOptions(doc) {\n    const selectElem = doc.getElementById(\"xnxqdm\");\n    if (!selectElem) return null;\n    const semesters = [];\n    const semesterValues = [];\n    let defaultIndex = 0;\n    Array.from(selectElem.querySelectorAll(\"option\")).forEach(option => {\n        if (!option.value) return;\n        semesters.push(option.innerText.trim());\n        semesterValues.push(option.value);\n        if (option.selected || option.hasAttribute(\"selected\")) defaultIndex = semesters.length - 1;\n    });\n    if (semesters.length === 0) return null;\n\n    const start = Math.max(0, defaultIndex - 1);\n    const end = Math.min(semesters.length, defaultIndex + 10);\n    return {\n        semesters: semesters.slice(start, end),\n        semesterValues: semesterValues.slice(start, end),\n        defaultIndex: defaultIndex - start\n    };\n}\n\n// 导入前提示用户先登录教务系统\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"洛阳理工学院教务导入\",\n        \"请先确保已登录教务系统，再继续导入。\",\n        \"我已登录\"\n    );\n}\n\n// 从页面已有学期中选择目标学期\nasync function selectSemester(semesterOptions) {\n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesterOptions.semesters),\n        semesterOptions.defaultIndex\n    );\n    if (selectedIndex === null || selectedIndex < 0) return null;\n    return {\n        label: semesterOptions.semesters[selectedIndex],\n        value: semesterOptions.semesterValues[selectedIndex]\n    };\n}\n\n// 直接获取课表页数据（学期下拉与作息表）。乘方教务系统的学期列表由服务端渲染，\n// 不提供返回学期列表的 JSON 接口，因此直接请求 week.page 即可，无需用户进入课表页面。\nasync function fetchSchedulePage() {\n    const response = await fetch(\"/new/student/xsgrkb/week.page\", { method: \"GET\", credentials: \"include\" });\n    if (!response.ok) throw new Error(`无法获取课表数据（HTTP ${response.status}）`);\n    return response.text();\n}\n\n// 乘方统一表单 POST，附带 JSON 请求头与会话\nasync function postForm(url, formData) {\n    const response = await fetch(url, {\n        method: \"POST\",\n        headers: {\n            \"Content-Type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        credentials: \"include\",\n        body: formData.toString()\n    });\n    if (!response.ok) throw new Error(`请求失败（HTTP ${response.status}）`);\n    return response;\n}\n\n// 请求指定学期的课程数据\nasync function fetchCourseData(xnxqdm) {\n    const year = parseInt(xnxqdm.slice(0, 4), 10);\n    const formData = new URLSearchParams();\n    formData.append(\"xnxqdm\", xnxqdm);\n    formData.append(\"zc\", \"\");\n    formData.append(\"d1\", `${year}-08-01 00:00:00`);\n    formData.append(\"d2\", `${year + 1}-08-31 23:59:59`);\n    return (await postForm(\"/new/student/xsgrkb/getCalendarWeekDatas\", formData)).json();\n}\n\nasync function saveCourses(courses) {\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n}\n\nasync function saveTimeSlots(timeSlots) {\n    if (timeSlots.length === 0) return;\n    await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n}\n\n// 编排导入流程：提示 → 选学期 → 请求课表 → 保存课程与作息时间\nasync function runImportFlow() {\n    try {\n        const confirmed = await promptUserToStart();\n        if (!confirmed) { window.shiguangBridge.showToast(\"导入已取消\"); return; }\n\n        const pageHtml = await fetchSchedulePage();\n        const semesterOptions = extractSemesterOptions(new DOMParser().parseFromString(pageHtml, \"text/html\"));\n        if (!semesterOptions) throw new Error(\"未找到学期列表，请先登录教务系统\");\n\n        const semester = await selectSemester(semesterOptions);\n        if (!semester) { window.shiguangBridge.showToast(\"导入已取消\"); return; }\n\n        const { slots, map: slotMap } = parseBusinessHoursFromHtml(pageHtml);\n        window.shiguangBridge.showToast(`正在获取 ${semester.label} 的课表...`);\n        const courses = parseCourseList(await fetchCourseData(semester.value), slotMap);\n\n        if (courses.length === 0) {\n            await window.shiguangBridgePromise.showAlert(\n                \"提示\",\n                \"该学期没有获取到课程数据，请检查登录状态和所选学期。\",\n                \"确定\"\n            );\n            return;\n        }\n\n        await saveCourses(courses);\n        try {\n            await saveTimeSlots(slots);\n        } catch (error) {\n            window.shiguangBridge.showToast(`课程已导入，作息时间导入失败：${error.message}`);\n        }\n\n        window.shiguangBridge.showToast(\"导入完成\");\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        await window.shiguangBridgePromise.showAlert(\n            \"导入失败\",\n            error.message || String(error),\n            \"确定\"\n        );\n    }\n}\n\nrunImportFlow();\n","LCUDCC":"// 聊城大学东昌学院(lcudcc.edu.cn) 拾光课程表适配脚本\n// 基于正方教务系统接口适配\n// 出现问题请提issues或者提交pr更改\n\n/**\n * 节次与周次合并去重函数\n * @param {Array<Object>} courses 原始解析课程数组\n * @returns {Array<Object>} 合并去重后的课程数组\n */\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    // 1. 深拷贝并规范周次数据，过滤无效项\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n\n    // 阶段 1：合并连续节次与完全重复记录（前提：名称、教师、地点、星期、周次一致）\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n               (a.startSection || 0) - (b.startSection || 0);\n    });\n\n    const step1Merged = [];\n    let current = list[0];\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n        const isSameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n\n        if (isSameCourseAndWeeks && isContinuous) {\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    // 阶段 2：合并同节次的周次（前提：名称、教师、地点、星期、开始/结束节次一致）\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               (a.startSection || 0) - (b.startSection || 0) ||\n               (a.endSection || 0) - (b.endSection || 0);\n    });\n\n    const step2Merged = [];\n    let cur = step1Merged[0];\n    for (let i = 1; i < step1Merged.length; i++) {\n        const nxt = step1Merged[i];\n        const isSameCourseAndSection =\n            cur.name === nxt.name &&\n            cur.teacher === nxt.teacher &&\n            cur.position === nxt.position &&\n            cur.day === nxt.day &&\n            cur.startSection === nxt.startSection &&\n            cur.endSection === nxt.endSection;\n\n        if (isSameCourseAndSection) {\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(cur);\n            cur = nxt;\n        }\n    }\n    step2Merged.push(cur);\n\n    return step2Merged;\n}\n\n/**\n * 解析周次字符串，处理单双周和周次范围\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    const weekSets = weekStr.split(',');\n    let weeks = [];\n    for (const set of weekSets) {\n        const trimmedSet = set.trim();\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周/);\n\n        let start = 0;\n        let end = 0;\n        let processed = false;\n\n        if (rangeMatch) {\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) {\n            start = end = Number(singleMatch[1]);\n            processed = true;\n        }\n\n        if (processed) {\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue;\n                if (isDouble && w % 2 !== 0) continue;\n                weeks.push(w);\n            }\n        }\n    }\n\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 解析 API 返回的 JSON 数据\n */\nfunction parseJsonData(jsonData) {\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        return [];\n    }\n\n    const rawCourseList = jsonData.kbList;\n    const initialCourseList = [];\n\n    for (const rawCourse of rawCourseList) {\n        if (!rawCourse.kcmc || !rawCourse.xm || !rawCourse.cdmc ||\n            !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) {\n            continue;\n        }\n\n        const weeksArray = parseWeeks(rawCourse.zcd);\n        if (weeksArray.length === 0) {\n            continue;\n        }\n\n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]);\n        const day = Number(rawCourse.xqj);\n\n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) ||\n            day < 1 || day > 7 || startSection > endSection) {\n            continue;\n        }\n\n        initialCourseList.push({\n            name: rawCourse.kcmc.trim(),\n            teacher: rawCourse.xm.trim(),\n            position: rawCourse.cdmc.trim(),\n            day: day,\n            startSection: startSection,\n            endSection: endSection,\n            weeks: weeksArray\n        });\n    }\n\n    return mergeAndDistinctCourses(initialCourseList);\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\n/**\n * 从教务系统获取学年学期选项\n * 学年：以选中项为中心，取前2年+后2年，共5个选项\n */\nasync function fetchAcademicOptions() {\n    const url = \"https://jw.lcudcc.edu.cn/jwglxt/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151\";\n\n    try {\n        const response = await fetch(url, {\n            method: \"GET\",\n            credentials: \"include\"\n        });\n\n        if (!response.ok) return null;\n\n        const htmlText = await response.text();\n        const parser = new DOMParser();\n        const doc = parser.parseFromString(htmlText, \"text/html\");\n\n        const allYearOptions = Array.from(doc.querySelectorAll(\"#xnm option\"))\n            .filter(opt => opt.value !== \"\")\n            .map(opt => ({\n                value: opt.value,\n                text: opt.textContent.trim(),\n                selected: opt.selected\n            }));\n\n        const semesterOptions = Array.from(doc.querySelectorAll(\"#xqm option\"))\n            .filter(opt => opt.value !== \"\")\n            .map(opt => ({\n                value: opt.value,\n                text: opt.textContent.trim(),\n                selected: opt.selected\n            }));\n\n        if (allYearOptions.length === 0 || semesterOptions.length === 0) {\n            return null;\n        }\n\n        const selectedIndex = allYearOptions.findIndex(opt => opt.selected);\n\n        if (selectedIndex === -1) {\n            return {\n                yearOptions: allYearOptions.slice(0, 5),\n                semesterOptions,\n                defaultYearIndex: 0,\n                defaultSemesterIndex: semesterOptions.findIndex(opt => opt.selected) !== -1\n                    ? semesterOptions.findIndex(opt => opt.selected)\n                    : 0\n            };\n        }\n\n        const start = Math.max(0, selectedIndex - 2);\n        const end = Math.min(allYearOptions.length, selectedIndex + 3);\n        const yearOptions = allYearOptions.slice(start, end);\n        const newDefaultIndex = selectedIndex - start;\n        const defaultSemesterIndex = semesterOptions.findIndex(opt => opt.selected);\n\n        return {\n            yearOptions,\n            semesterOptions,\n            defaultYearIndex: newDefaultIndex,\n            defaultSemesterIndex: defaultSemesterIndex !== -1 ? defaultSemesterIndex : 0\n        };\n    } catch (e) {\n        return null;\n    }\n}\n\n/**\n * 提示用户选择学年和学期\n */\nasync function selectAcademicYearAndSemester() {\n    const optionsData = await fetchAcademicOptions();\n\n    if (!optionsData) {\n        window.shiguangBridge.showToast(\"从教务系统读取学年学期失败，请确保登录状态。\");\n        return null;\n    }\n\n    const { yearOptions, semesterOptions, defaultYearIndex, defaultSemesterIndex } = optionsData;\n\n    const yearTexts = yearOptions.map(item => item.text);\n    const yearIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学年\",\n        JSON.stringify(yearTexts),\n        defaultYearIndex\n    );\n\n    if (yearIndex === null || yearIndex === -1) return null;\n    const selectedYearCode = yearOptions[yearIndex].value;\n\n    const semesterTexts = semesterOptions.map(item => item.text);\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesterTexts),\n        defaultSemesterIndex\n    );\n\n    if (semesterIndex === null || semesterIndex === -1) return null;\n    const selectedSemesterCode = semesterOptions[semesterIndex].value;\n\n    return {\n        academicYear: selectedYearCode,\n        semesterCode: selectedSemesterCode\n    };\n}\n\n/**\n * 获取学期开学日期\n */\nasync function fetchSemesterStartDate(academicYear, semesterCode) {\n    const url = \"https://jw.lcudcc.edu.cn/jwglxt/kbcx/xskbcxZccx_cxZcByXnxq.html?gnmkdm=N2154\";\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}`;\n\n    try {\n        const response = await fetch(url, {\n            method: \"POST\",\n            headers: {\n                \"accept\": \"application/json, text/javascript, */*; q=0.01\",\n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: requestBody,\n            credentials: \"include\"\n        });\n\n        if (response.ok) {\n            const json = await response.json();\n            if (Array.isArray(json) && json.length > 0) {\n                const firstWeekObj = json.find(item => String(item.zs) === \"1\" || String(item.zsmc) === \"1\") || json[0];\n\n                if (firstWeekObj.rq) {\n                    const startDateStr = firstWeekObj.rq.split('/')[0];\n                    if (/^\\d{4}-\\d{2}-\\d{2}$/.test(startDateStr)) {\n                        return startDateStr;\n                    }\n                }\n\n                if (firstWeekObj.zcrq) {\n                    const match = firstWeekObj.zcrq.match(/(\\d{4}-\\d{2}-\\d{2})/);\n                    if (match) return match[1];\n                }\n\n                if (firstWeekObj.ksrq) {\n                    const match = firstWeekObj.ksrq.match(/(\\d{4}-\\d{2}-\\d{2})/);\n                    if (match) return match[1];\n                }\n            }\n        }\n    } catch (e) {\n        // 获取失败不影响主流程\n    }\n    return null;\n}\n\n/**\n * 请求和解析课程数据\n */\nasync function fetchAndParseCourses(academicYear, semesterCode) {\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`;\n    const targetUrl = \"https://jw.lcudcc.edu.cn/jwglxt/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151\";\n\n    const [courseResponse, semesterStartDate] = await Promise.all([\n        fetch(targetUrl, {\n            method: \"POST\",\n            headers: {\n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\"\n            },\n            body: requestBody,\n            credentials: \"include\"\n        }),\n        fetchSemesterStartDate(academicYear, semesterCode)\n    ]);\n\n    try {\n        if (courseResponse.ok) {\n            const jsonText = await courseResponse.text();\n            const jsonData = JSON.parse(jsonText);\n            if (jsonData && jsonData.kbList) {\n                const parsedCourses = parseJsonData(jsonData);\n                if (parsedCourses.length > 0) {\n                    return {\n                        courses: parsedCourses,\n                        config: {\n                            semesterStartDate: semesterStartDate,\n                            semesterTotalWeeks: 20\n                        }\n                    };\n                }\n            }\n        }\n    } catch (e) {\n        // 请求失败\n    }\n\n    window.shiguangBridge.showToast(\"未能获取课表数据，请检查网络环境或登录状态。\");\n    return null;\n}\n\nasync function saveCourses(parsedCourses) {\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        return false;\n    }\n}\n\nasync function runImportFlow() {\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    const selection = await selectAcademicYearAndSemester();\n    if (!selection) {\n        window.shiguangBridge.showToast(\"未选择学年学期，导入流程终止。\");\n        return;\n    }\n\n    const { academicYear, semesterCode } = selection;\n\n    const result = await fetchAndParseCourses(academicYear, semesterCode);\n    if (result === null) {\n        return;\n    }\n\n    const { courses, config } = result;\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        return;\n    }\n\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        let configMsg = \"课表配置更新成功！\";\n        if (config.semesterStartDate) {\n            configMsg += ` 开学日期：${config.semesterStartDate}`;\n        }\n        window.shiguangBridge.showToast(configMsg);\n    } catch (error) {\n        window.shiguangBridge.showToast(`课表配置保存失败: ${error.message}`);\n    }\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();\n","LNU_01":"// 辽宁大学课表适配脚本\n// 基于 URP 教务系统 JSON 接口适配\n\n// 解析 classWeek 二进制串，如 \"111111111111111100000000\" -> [1..16]\nfunction parseWeeks(binaryStr) {\n    const weeks = [];\n    if (!binaryStr) return weeks;\n    for (let i = 0; i < binaryStr.length; i++) {\n        if (binaryStr[i] === '1') weeks.push(i + 1);\n    }\n    return weeks;\n}\n\nfunction cleanTeacher(teacher) {\n    return (teacher || \"\").replace(/\\*/g, \" \").replace(/\\s+/g, \" \").trim();\n}\n\nfunction formatTime(timeStr) {\n    if (timeStr && timeStr.length === 4) {\n        return timeStr.substring(0, 2) + \":\" + timeStr.substring(2);\n    }\n    return timeStr || \"\";\n}\n\nfunction buildPosition(campus, building, room) {\n    const campusPart = (campus || \"\").trim();\n    let buildingPart = (building || \"\").trim();\n    let roomPart = (room || \"\").trim();\n    if (campusPart && buildingPart.startsWith(campusPart)) {\n        buildingPart = buildingPart.slice(campusPart.length);\n    }\n    if (campusPart && roomPart.startsWith(campusPart)) {\n        roomPart = roomPart.slice(campusPart.length);\n    }\n    const result = (campusPart + buildingPart + roomPart).trim();\n    return result || \"待定\";\n}\n\nfunction parseCourses(data) {\n    const courses = [];\n    const seen = new Set();\n    const list = (data && data.xkxx) || [];\n    for (let i = 0; i < list.length; i++) {\n        const map = list[i];\n        if (!map) continue;\n        for (const key in map) {\n            const course = map[key];\n            if (!course || !course.courseName || !course.timeAndPlaceList) continue;\n            const teacher = cleanTeacher(course.attendClassTeacher);\n            for (const timePlace of course.timeAndPlaceList) {\n                const day = parseInt(timePlace.classDay);\n                const start = parseInt(timePlace.classSessions);\n                const continuing = parseInt(timePlace.continuingSession) || 2;\n                const end = start + continuing - 1;\n                const weeks = parseWeeks(timePlace.classWeek);\n                if (!day || !start || weeks.length === 0) continue;\n                const position = buildPosition(timePlace.campusName, timePlace.teachingBuildingName, timePlace.classroomName);\n                const dedupKey = course.courseName + '|' + teacher + '|' + day + '|' + start + '|' + end + '|' + weeks.join(',') + '|' + position;\n                if (seen.has(dedupKey)) continue;\n                seen.add(dedupKey);\n                courses.push({\n                    name: course.courseName,\n                    teacher: teacher,\n                    position: position,\n                    day: day,\n                    startSection: start,\n                    endSection: end,\n                    weeks: weeks,\n                    isCustomTime: false\n                });\n            }\n        }\n    }\n    return courses;\n}\n\nfunction parseTimeSlots(data) {\n    const slots = [];\n    const list = (data && data.jcsjbs) || [];\n    for (const slot of list) {\n        const num = parseInt(slot.jc, 10);\n        if (isNaN(num)) continue;\n        slots.push({\n            number: num,\n            startTime: formatTime(slot.kssj),\n            endTime: formatTime(slot.jssj)\n        });\n    }\n    return slots.sort((a, b) => a.number - b.number);\n}\n\n// 教务系统提供的时间可能把校区搞混，所以提供各校区的作息时间表，供用户选择\nconst CHONGSHAN_TIME_SLOTS = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:50\" },\n    { number: 2, startTime: \"09:00\", endTime: \"09:50\" },\n    { number: 3, startTime: \"10:10\", endTime: \"11:00\" },\n    { number: 4, startTime: \"11:10\", endTime: \"12:00\" },\n    { number: 5, startTime: \"13:30\", endTime: \"14:20\" },\n    { number: 6, startTime: \"14:30\", endTime: \"15:20\" },\n    { number: 7, startTime: \"15:40\", endTime: \"16:30\" },\n    { number: 8, startTime: \"16:40\", endTime: \"17:30\" },\n    { number: 9, startTime: \"18:00\", endTime: \"18:50\" },\n    { number: 10, startTime: \"19:00\", endTime: \"19:50\" },\n    { number: 11, startTime: \"20:10\", endTime: \"21:00\" },\n    { number: 12, startTime: \"21:10\", endTime: \"22:00\" }\n];\n\nconst PUHE_TIME_SLOTS = [\n    { number: 1, startTime: \"08:30\", endTime: \"09:15\" },\n    { number: 2, startTime: \"09:20\", endTime: \"10:05\" },\n    { number: 3, startTime: \"10:25\", endTime: \"11:10\" },\n    { number: 4, startTime: \"11:15\", endTime: \"12:00\" },\n    { number: 5, startTime: \"13:30\", endTime: \"14:15\" },\n    { number: 6, startTime: \"14:20\", endTime: \"15:05\" },\n    { number: 7, startTime: \"15:25\", endTime: \"16:10\" },\n    { number: 8, startTime: \"16:15\", endTime: \"17:00\" },\n    { number: 9, startTime: \"17:30\", endTime: \"18:15\" },\n    { number: 10, startTime: \"18:20\", endTime: \"19:05\" },\n    { number: 11, startTime: \"19:25\", endTime: \"20:10\" },\n    { number: 12, startTime: \"20:15\", endTime: \"21:00\" }\n];\n\nconst WUSHENG_TIME_SLOTS = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:50\" },\n    { number: 2, startTime: \"09:00\", endTime: \"09:50\" },\n    { number: 3, startTime: \"10:10\", endTime: \"11:00\" },\n    { number: 4, startTime: \"11:10\", endTime: \"12:00\" },\n    { number: 5, startTime: \"13:30\", endTime: \"14:20\" },\n    { number: 6, startTime: \"14:30\", endTime: \"15:20\" },\n    { number: 7, startTime: \"15:30\", endTime: \"16:20\" },\n    { number: 8, startTime: \"16:30\", endTime: \"17:20\" },\n    { number: 9, startTime: \"18:00\", endTime: \"18:50\" },\n    { number: 10, startTime: \"19:00\", endTime: \"19:50\" },\n    { number: 11, startTime: \"20:10\", endTime: \"21:00\" },\n    { number: 12, startTime: \"21:10\", endTime: \"22:00\" }\n];\n\nconst CAMPUS_CHONGSHAN = \"崇山\";\nconst CAMPUS_PUHE = \"蒲河\";\nconst CAMPUS_WUSHENG = \"武圣\";\n\nconst TIME_SLOT_OPTIONS = [\n    \"从教务提取\",\n    \"内置\" + CAMPUS_CHONGSHAN + \"校区作息\",\n    \"内置\" + CAMPUS_PUHE + \"校区作息\",\n    \"内置\" + CAMPUS_WUSHENG + \"校区作息\"\n];\n\nconst TIME_SLOT_OPTION_EXTRACT = 0;\nconst TIME_SLOT_OPTION_CHONGSHAN = 1;\nconst TIME_SLOT_OPTION_PUHE = 2;\nconst TIME_SLOT_OPTION_WUSHENG = 3;\n\n// 根据课程数据的 campusName 字段猜测所在校区\nfunction guessCampus(data) {\n    const counts = {};\n    const list = (data && data.xkxx) || [];\n    for (const map of list) {\n        if (!map) continue;\n        for (const key in map) {\n            const course = map[key];\n            if (!course || !course.timeAndPlaceList) continue;\n            for (const timePlace of course.timeAndPlaceList) {\n                const campus = (timePlace.campusName || \"\").trim();\n                if (campus) {\n                    counts[campus] = (counts[campus] || 0) + 1;\n                }\n            }\n        }\n    }\n    let best = null;\n    let bestCount = 0;\n    for (const name in counts) {\n        if (counts[name] > bestCount) {\n            best = name;\n            bestCount = counts[name];\n        }\n    }\n    if (best && best.includes(CAMPUS_CHONGSHAN)) {\n        return CAMPUS_CHONGSHAN; \n    }\n    if (best && best.includes(CAMPUS_PUHE)) { \n        return CAMPUS_PUHE; \n    }\n    if (best && best.includes(CAMPUS_WUSHENG)) {\n        return CAMPUS_WUSHENG;\n    }\n    return null;\n}\n\nfunction readSemesterOptions() {\n    const select = document.getElementById('planCode');\n    if (!select || !select.options || select.options.length === 0) {\n        return null;\n    }\n    const texts = [];\n    const values = [];\n    for (let i = 0; i < select.options.length; i++) {\n        texts.push(select.options[i].text.replace(/\\s+/g, ' ').trim());\n        values.push(select.options[i].value);\n    }\n    return {\n        texts: texts,\n        values: values,\n        defaultIndex: select.selectedIndex >= 0 ? select.selectedIndex : 0\n    };\n}\n\nasync function fetchCourseConfig() {\n    try {\n        const res = await fetch(\"/indexCalendar\");\n        if (!res.ok) return null;\n        const html = await res.text();\n        \n        const config = {};\n        const rqMatch = html.match(/var\\s+rq\\s*=\\s*[\"'](\\d{8})[\"']/);\n        if (rqMatch && rqMatch[1]) {\n            const dateStr = rqMatch[1];\n            // 转换为 YYYY-MM-DD\n            config.semesterStartDate = `${dateStr.substring(0, 4)}-${dateStr.substring(4, 6)}-${dateStr.substring(6, 8)}`;\n        }\n        \n        const skzcMatch = html.match(/var\\s+skzc\\s*=\\s*[\"'](\\d+)[\"']/);\n        if (skzcMatch && skzcMatch[1]) {\n            config.semesterTotalWeeks = parseInt(skzcMatch[1], 10);\n        }\n        \n        return Object.keys(config).length > 0 ? config : null;\n    } catch (e) {\n        window.shiguangBridge.showToast(\"获取课程配置失败: \" + e.message);\n        return null;\n    }\n}\n\nasync function runImportFlow() {\n    try {\n        let method = \"GET\";\n        let body = undefined;\n        let idx = -1;\n        let options = null;\n\n        const apiPath = \"/student/courseSelect/thisSemesterCurriculum/ajaxStudentSchedule/callback\";\n        const headers = {\n            \"Accept\": \"*/*\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        };\n\n        const confirmed = await window.shiguangBridgePromise.showAlert(\n            \"辽宁大学课表导入\",\n            \"请确认已登录教务系统，并处于课表页面。\",\n            \"确定\"\n        );\n        if (!confirmed) return;\n\n        options = readSemesterOptions();\n        if (options) {\n            idx = await window.shiguangBridgePromise.showSingleSelection(\n                \"选择学期\",\n                JSON.stringify(options.texts),\n                options.defaultIndex\n            );\n            if (idx === null || idx < 0) {\n                window.shiguangBridge.showToast(\"导入已取消\");\n                return;\n            }\n        }\n\n        if (options && idx >= 0) {\n            method = \"POST\";\n            headers[\"Content-Type\"] = \"application/x-www-form-urlencoded; charset=UTF-8\";\n            headers[\"Accept\"] = \"application/json, text/javascript, */*; q=0.01\";\n            body = \"planCode=\" + encodeURIComponent(options.values[idx]);\n        }\n\n        window.shiguangBridge.showToast(\"正在获取教务数据...\");\n        const res = await fetch(apiPath, {\n            method: method,\n            headers: headers,\n            body: body,\n            credentials: \"include\"\n        });\n        if (!res.ok) {\n            window.shiguangBridge.showToast(\"网络请求失败，状态码: \" + res.status);\n            return;\n        }\n\n        const data = await res.json();\n\n        const courses = parseCourses(data);\n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"导入失败: 未解析到课程数据，请确认所选学期有课\");\n            return;\n        }\n\n        const campus = guessCampus(data);\n        let defaultIndex = TIME_SLOT_OPTION_EXTRACT;\n        if (campus === CAMPUS_CHONGSHAN) {\n            defaultIndex = TIME_SLOT_OPTION_CHONGSHAN;\n        } else if (campus === CAMPUS_PUHE) {\n            defaultIndex = TIME_SLOT_OPTION_PUHE;\n        } else if (campus === CAMPUS_WUSHENG) {\n            defaultIndex = TIME_SLOT_OPTION_WUSHENG;\n        }\n        const choice = await window.shiguangBridgePromise.showSingleSelection(\n            \"作息时间来源\",\n            JSON.stringify(TIME_SLOT_OPTIONS),\n            defaultIndex\n        );\n        if (choice === null || choice < 0) {\n            window.shiguangBridge.showToast(\"导入已取消\");\n            return;\n        }\n        let timeSlots;\n        if (choice === TIME_SLOT_OPTION_CHONGSHAN) {\n            timeSlots = CHONGSHAN_TIME_SLOTS;\n        } else if (choice === TIME_SLOT_OPTION_PUHE) {\n            timeSlots = PUHE_TIME_SLOTS;\n        } else if (choice === TIME_SLOT_OPTION_WUSHENG) {\n            timeSlots = WUSHENG_TIME_SLOTS;\n        } else {\n            timeSlots = parseTimeSlots(data);\n        }\n        \n        const configData = await fetchCourseConfig();\n\n        const saved = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        if (!saved) {\n            window.shiguangBridge.showToast(\"课程保存失败\");\n            return;\n        }\n        try {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n            if (configData) {\n                await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(configData));\n            }\n        } catch (error) {\n            window.shiguangBridge.showToast(\"作息时间或配置保存失败: \" + error.message);\n        }\n\n        window.shiguangBridge.showToast(\"成功导入 \" + courses.length + \" 个课程时段\");\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (e) {\n        window.shiguangBridge.showToast(\"导入失败: \" + e.message);\n    }\n}\n\nrunImportFlow();\n","USTL":"// 辽宁科技大学(ustl.edu.cn)拾光课程表适配脚本\n// 基于超星教务系统接口适配\n// 本校毕业生适配, 开发者无法及时发现问题\n// 出现问题请提issues或者提交pr更改, 这更加快速\n\n/**\n * 从 HTML 字符串中提取纯文本内容。\n * 超星系统返回的部分字段包含 HTML 标签（如 <a> 标签）\n */\nfunction extractAnchorText(htmlStr) {\n    if (!htmlStr) return '';\n    // 移除 HTML 标签，返回剩余的文本内容\n    const match = htmlStr.match(/>([^<]+)</);\n    return match ? match[1].trim() : htmlStr.trim();\n}\n\n/**\n * 清理教师名称，去除括号及其内容。\n */\nfunction cleanTeacherName(name) {\n    if (!name) return '';\n    // 移除全角或半角的括号及其中的内容\n    return name.replace(/（[^）]*）/g, '').replace(/\\([^)]*\\)/g, '').trim();\n}\n\n/**\n * 解析周次字符串，超星系统直接提供逗号分隔的周次数字。\n * @param {string} weekStr - 周次字符串，如 \"1,2,3,4,5\"\n * @returns {number[]} - 排序后的周次数组\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n    return weekStr.split(',')\n        .map(w => Number(w.trim()))\n        .filter(w => !isNaN(w) && w > 0)\n        .sort((a, b) => a - b);\n}\n\n/**\n * 从周次列表中获取开学日期（第1周的开始日期）。\n * @param {Array} zclist - 周次列表，来自 getZclistByXnxq 接口\n * @returns {string|null} - 开学日期，格式 YYYY-MM-DD\n */\nfunction getSemesterStartDate(zclist) {\n    if (!zclist || !Array.isArray(zclist) || zclist.length === 0) {\n        console.warn(\"JS: 周次列表为空或格式错误。\");\n        return null;\n    }\n\n    // 查找第1周的数据\n    const firstWeek = zclist.find(zc => Number(zc.zc) === 1);\n    if (!firstWeek || !firstWeek.minrq) {\n        console.warn(\"JS: 未找到第1周的开始日期。\");\n        return null;\n    }\n\n    // 将 \"2025-08-25 00:00:00\" 格式转换为 \"2025-08-25\"\n    const dateStr = firstWeek.minrq.split(' ')[0];\n    console.log(`JS: 获取到开学日期: ${dateStr}`);\n    return dateStr;\n}\n\n/**\n * 解析课程数据，并合并连续节次的同一课程。\n * @param {Object} jsonData - sdpkkbList 接口返回的 JSON 数据\n * @returns {Array<Object>} - 解析并合并后的课程列表\n */\nfunction parseCourseData(jsonData) {\n    console.log(\"JS: 开始解析超星课程数据...\");\n\n    if (!jsonData || !Array.isArray(jsonData.data)) {\n        console.warn(\"JS: 课程数据结构错误或缺少 data 字段。\");\n        return [];\n    }\n\n    const rawCourseList = jsonData.data;\n\n    // 1. 预处理课程数据，提取必要字段并标准化\n    const processedList = rawCourseList\n        .map(rawCourse => {\n            const name = extractAnchorText(rawCourse.kcmc);\n            const teacher = cleanTeacherName(extractAnchorText(rawCourse.tmc));\n            const position = extractAnchorText(rawCourse.croommc) || '待定';\n            const day = Number(rawCourse.xingqi);\n            const section = Number(rawCourse.djc);\n            \n            // 解析周次字符串并转换为标准 JSON 字符串（用于比较）\n            const weeksArray = parseWeeks(rawCourse.zcstr);\n            const standardizedWeeks = JSON.stringify(weeksArray);\n\n            // 验证必填字段\n            if (!name || isNaN(day) || isNaN(section) || day < 1 || day > 7 || section < 1 || weeksArray.length === 0) {\n                return null;\n            }\n\n            return { name, teacher, position, day, section, standardizedWeeks, weeksArray };\n        })\n        .filter(c => c !== null)\n        // 排序：按星期 > 周次 > 课程名 > 教师 > 教室 > 节次\n        .sort((a, b) =>\n            a.day - b.day ||\n            a.standardizedWeeks.localeCompare(b.standardizedWeeks) ||\n            a.name.localeCompare(b.name) ||\n            a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) ||\n            a.section - b.section \n        );\n\n    // 2. 合并连续节次的相同课程\n    const finalCourseList = [];\n    let i = 0;\n\n    while (i < processedList.length) {\n        let current = processedList[i];\n        let startSection = current.section;\n        let endSection = current.section;\n        let j = i + 1;\n\n        // 查找连续的节次\n        while (j < processedList.length) {\n            let next = processedList[j];\n\n            // 检查是否可以合并：周次、星期、课程名、教师、教室必须相同，且节次连续\n            if (\n                next.day === current.day &&\n                next.name === current.name &&\n                next.teacher === current.teacher &&\n                next.position === current.position &&\n                next.standardizedWeeks === current.standardizedWeeks && \n                next.section === endSection + 1\n            ) {\n                endSection = next.section;\n                j++;\n            } else {\n                break;\n            }\n        }\n\n        // 添加合并后的课程\n        finalCourseList.push({\n            name: current.name,\n            teacher: current.teacher,\n            position: current.position,\n            day: current.day,\n            startSection: startSection,\n            endSection: endSection,\n            weeks: current.weeksArray\n        });\n\n        i = j;\n    }\n\n    console.log(`JS: 课程数据解析完成，共 ${finalCourseList.length} 门课程（已合并连续节次）。`);\n    return finalCourseList;\n}\n\n/**\n * 生成学年学期选项列表。\n * @returns {Object} - 包含 labels（显示文本）、values（参数值）、defaultIndex（默认选项）\n */\nfunction getSemesterOptions() {\n    const currentYear = new Date().getFullYear();\n    const currentMonth = new Date().getMonth() + 1;\n    \n    // 根据当前月份判断默认学期（9月前为第二学期，9月后为第一学期）\n    const defaultSemester = currentMonth < 9 ? 2 : 1;\n    const defaultYear = currentMonth < 9 ? currentYear - 1 : currentYear;\n    \n    // 生成前后三年的学年学期选项\n    const years = [currentYear - 2, currentYear - 1, currentYear, currentYear + 1]; \n    const semesterCodes = [\"1\", \"2\"];\n\n    let labels = [];\n    let values = [];\n    let defaultIndex = -1;\n    \n    let index = 0;\n    for (let i = 0; i < years.length; i++) {\n        const startYear = years[i];\n        const endYear = startYear + 1;\n        const yearStr = `${startYear}-${endYear}`;\n\n        for (let j = 0; j < semesterCodes.length; j++) {\n            const code = semesterCodes[j];\n            const apiValue = `${yearStr}-${code}`;\n            const semesterName = code === \"1\" ? \"第一学期\" : \"第二学期\";\n            \n            labels.push(`${yearStr}学年 ${semesterName}`);\n            values.push(apiValue);\n            \n            // 设置默认选项\n            if (startYear === defaultYear && Number(code) === defaultSemester) {\n                defaultIndex = index;\n            }\n            \n            index++;\n        }\n    }\n    \n    return { labels, values, defaultIndex };\n}\n\n/**\n * 从学年学期下拉框 HTML 中解析选项。\n * @param {string} selectHtml - id=xnxq1 的 select 元素 HTML\n * @returns {Object|null} - 包含 labels、values、defaultIndex，失败返回 null\n */\nfunction parseSemesterOptionsFromHtml(selectHtml) {\n    if (!selectHtml || typeof selectHtml !== 'string') {\n        return null;\n    }\n\n    try {\n        const doc = new DOMParser().parseFromString(selectHtml, \"text/html\");\n        const selectElement = doc.querySelector('#xnxq1') || doc.querySelector('select[name=\"xnxq\"]');\n        if (!selectElement) {\n            return null;\n        }\n\n        const optionElements = Array.from(selectElement.querySelectorAll('option'));\n        const validOptions = optionElements.filter(option => (option.value || '').trim() !== '');\n        if (validOptions.length === 0) {\n            return null;\n        }\n\n        const labels = validOptions.map(option => (option.textContent || option.value || '').trim());\n        const values = validOptions.map(option => (option.value || '').trim());\n\n        let defaultIndex = validOptions.findIndex(option => option.selected);\n        if (defaultIndex < 0) {\n            defaultIndex = 0;\n        }\n\n        return { labels, values, defaultIndex };\n    } catch (error) {\n        console.warn(\"JS: 解析学年学期下拉 HTML 失败\", error);\n        return null;\n    }\n}\n\n/**\n * 提示用户选择学年学期。\n * @param {string|null|undefined} xnxqSelectHtml - 页面中 id=xnxq1 的 select 元素 HTML\n * @returns {Promise<string|null>} - 选中的学年学期参数（如 \"2025-2026-1\"），或 null（取消）\n */\nasync function selectAcademicYearAndSemester(xnxqSelectHtml) {\n    console.log(\"JS: 提示用户选择学年学期。\");\n    let options = parseSemesterOptionsFromHtml(xnxqSelectHtml);\n    if (!options) {\n        console.warn(\"JS: 页面学年学期选项解析失败，回退为前后三年选项。\");\n        options = getSemesterOptions();\n    }\n    const { labels, values, defaultIndex } = options;\n    \n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学年学期\",\n        JSON.stringify(labels),\n        defaultIndex\n    );\n    \n    if (selectedIndex === null || selectedIndex === -1) {\n        return null;\n    }\n    \n    console.log(`JS: 用户选择了学年学期: ${values[selectedIndex]}`);\n    return values[selectedIndex];\n}\n\n/**\n * 获取校区列表。\n * @returns {Promise<Array<{xqdm: string, xqmc: string}>|null>} - 校区列表，或 null（失败）\n */\nasync function fetchCampusList() {\n    console.log(\"JS: 正在请求校区列表...\");\n\n    const url = \"/admin/api/jcsj/xqsj/getXqList\";\n    const requestOptions = {\n        \"headers\": {\n            \"Accept\": \"application/json, text/plain, */*\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        \"method\": \"GET\",\n        \"credentials\": \"include\"\n    };\n\n    try {\n        const response = await fetch(url, requestOptions);\n\n        if (!response.ok) {\n            throw new Error(`网络请求失败。状态码: ${response.status}`);\n        }\n\n        const jsonData = await response.json();\n\n        if (jsonData.ret !== 0) {\n            throw new Error(`API 返回错误: ${jsonData.msg || '未知错误'}`);\n        }\n\n        if (!Array.isArray(jsonData.data)) {\n            throw new Error(\"校区列表数据格式错误。\");\n        }\n\n        const campusList = jsonData.data\n            .map(item => ({\n                xqdm: String(item.id || '').trim(),\n                xqmc: String(item.xqmc || item.id || '').trim()\n            }))\n            .filter(item => item.xqdm && item.xqmc);\n\n        if (campusList.length === 0) {\n            throw new Error(\"未获取到有效校区信息。\");\n        }\n\n        console.log(`JS: 校区列表获取成功，共 ${campusList.length} 个校区。`);\n        return campusList;\n    } catch (error) {\n        window.shiguangBridge.showToast(`获取校区列表失败: ${error.message}`);\n        console.error('JS: fetchCampusList Error:', error);\n        return null;\n    }\n}\n\n/**\n * 提示用户选择校区。\n * @param {string} defaultXqdm - 默认选中的校区代码\n * @returns {Promise<{xqdm: string, xqmc: string}|null>} - 选中的校区信息，或 null（取消/失败）\n */\nasync function selectCampus(defaultXqdm) {\n    const campusList = await fetchCampusList();\n    if (!campusList) {\n        console.warn(`JS: 获取校区列表失败，使用页面参数 xqdm=${defaultXqdm} 继续导入。`);\n        window.shiguangBridge.showToast(\"获取校区列表失败，使用默认校区继续导入。\");\n        return {\n            xqdm: defaultXqdm,\n            xqmc: \"\"\n        };\n    }\n\n    const labels = campusList.map(item => item.xqmc);\n    const defaultIndex = Math.max(\n        campusList.findIndex(item => item.xqdm === defaultXqdm),\n        0\n    );\n\n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择校区\",\n        JSON.stringify(labels),\n        defaultIndex\n    );\n\n    if (selectedIndex === null || selectedIndex === -1) {\n        return null;\n    }\n\n    const selectedCampus = campusList[selectedIndex];\n    console.log(`JS: 用户选择了校区: ${selectedCampus.xqmc} (${selectedCampus.xqdm})`);\n    return selectedCampus;\n}\n\n/** \n * 时间格式化\n * @returns {string|null} - 格式化后的时间字符串 \"HH:MM\"，或 null（格式不合法）\n */\nfunction formatTime(timeStr) {\n    if (typeof timeStr !== 'string') return null;\n    const match = timeStr.match(/^(\\d{1,2}):(\\d{1,2})(?::\\d{1,2})?$/);\n    if (!match) return null;\n    let [ , hour, minute ] = match.map(Number);\n    return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;\n}\n\n/**\n * 从节次时间数据生成时间段列表。\n * @param {Array} jcsjszList - 节次时间数组，来自 getZclistByXnxq 接口\n * @returns {Array<Object>|null} - 时间段列表，格式不合法时返回 null\n */\nfunction generateTimeSlots(jcsjszList) {\n    if (!jcsjszList || !Array.isArray(jcsjszList)) {\n        console.warn(\"JS: 节次时间数据为空或格式错误。\");\n        return [];\n    }\n\n    const timeSlots = [];\n\n    for (const item of jcsjszList) {\n        const startTime = formatTime(item.kssj);\n        const endTime = formatTime(item.jssj);\n\n        if (!startTime || !endTime) {\n            console.warn(\"JS: 节次时间格式不合法，跳过生成时间段列表。\", item);\n            return null;\n        }\n\n        timeSlots.push({\n            number: Number(item.jc),\n            startTime,\n            endTime\n        });\n    }\n\n    timeSlots.sort((a, b) => a.number - b.number);\n\n    console.log(`JS: 生成了 ${timeSlots.length} 个时间段。`);\n    return timeSlots;\n}\n\n/**\n * 从页面中提取必要的参数。\n * @returns {Object|null} - 包含 xhid、xqdm 和 xnxqSelectHtml 的对象，或 null（提取失败）\n */\nasync function extractPageParams() {\n    console.log(\"JS: 尝试从页面中提取参数...\");\n    \n    // 方法1：从隐藏的 input 元素中获取\n    let xhid = document.querySelector('#xhid')?.value;\n    let xqdm = document.querySelector('#xqdm')?.value;\n    let xnxqSelectHtml = document.querySelector('#xnxq1')?.outerHTML;\n    \n    // 方法2：如果页面上找不到，尝试抓取课表页并解析\n    if (!xhid || !xqdm || !xnxqSelectHtml) {\n        console.log(\"JS: 尝试抓取课表页并解析...\");\n        const path = \"/admin/pkgl/xskb/queryKbForXsd\";\n\n        try {\n            // 获取课表页的 HTML 文档\n            const htmlText = await fetch(path).then(res => res.text());\n            const contentDom = new DOMParser().parseFromString(htmlText, \"text/html\");\n\n            // 从转换后的 HTML 文档中获取 xhid 和 xqdm 的值\n            xhid = contentDom.querySelector(\"#xhid\")?.value ||  xhid;\n            xqdm = contentDom.querySelector(\"#xqdm\")?.value || xqdm;\n            xnxqSelectHtml = contentDom.querySelector(\"#xnxq1\")?.outerHTML || xnxqSelectHtml;\n        } catch (error) {\n            console.warn(\"JS: 通过抓取课表页提取参数失败\", error);\n        }\n    }\n    \n    console.log(`JS: 提取到参数 - xhid: ${xhid}, xqdm: ${xqdm}, xnxqSelectHtml: ${xnxqSelectHtml ? 'yes' : 'no'}`);\n    \n    if (!xhid || !xqdm) {\n        console.warn(\"JS: 无法从页面中提取必要参数。\");\n        return null;\n    }\n    \n    return { xhid, xqdm, xnxqSelectHtml };\n}\n\n/**\n * 获取节次时间和开学日期信息。\n * @param {string} xnxq - 学年学期参数\n * @param {string} xqdm - 校区代码\n * @returns {Promise<Object>} - 包含 timeSlots 和 semesterStartDate，请求失败时返回空配置继续流程\n */\nasync function fetchTimeAndWeekData(xnxq, xqdm) {\n    console.log(`JS: 正在请求节次时间和周次数据...`);\n    window.shiguangBridge.showToast(\"正在获取课表配置信息...\");\n    \n    const url = `/admin/api/getZclistByXnxq?xnxq=${xnxq}&xqid=${xqdm}`;\n    \n    const requestOptions = {\n        \"headers\": {\n            \"Accept\": \"application/json, text/plain, */*\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        \"method\": \"GET\",\n        \"credentials\": \"include\"\n    };\n\n    try {\n        const response = await fetch(url, requestOptions);\n\n        if (!response.ok) {\n            throw new Error(`网络请求失败。状态码: ${response.status}`);\n        }\n        \n        const jsonData = await response.json();\n        \n        if (jsonData.ret !== 0) {\n            throw new Error(`API 返回错误: ${jsonData.msg || '未知错误'}`);\n        }\n\n        // 提取节次时间和开学日期\n        const timeSlots = generateTimeSlots(jsonData.data?.jcsjszList);\n        const semesterStartDate = getSemesterStartDate(jsonData.data?.zclist);\n\n        if (!timeSlots) {\n            console.warn(\"JS: 未获取到节次时间\");\n        }\n\n        if (!semesterStartDate) {\n            console.warn(\"JS: 未获取到开学日期\");\n        }\n\n        console.log(`JS: 成功获取节次时间（${Array.isArray(timeSlots) ? timeSlots.length : 0}个）和开学日期（${semesterStartDate}）。`);\n        return { timeSlots, semesterStartDate };\n\n    } catch (error) {\n        window.shiguangBridge.showToast(`获取配置信息失败，将继续导入课程: ${error.message}`);\n        console.error('JS: fetchTimeAndWeekData Error:', error);\n        return {\n            timeSlots: null,\n            semesterStartDate: null\n        };\n    }\n}\n\n/**\n * 获取课程数据。\n * @param {string} xnxq - 学年学期参数\n * @param {string} xhid - 学号ID\n * @param {string} xqdm - 校区代码\n * @returns {Promise<Array|null>} - 课程列表，或 null（失败）\n */\nasync function fetchCourseData(xnxq, xhid, xqdm) {\n    console.log(`JS: 正在请求课程数据...`);\n    window.shiguangBridge.showToast(`正在获取 ${xnxq} 的课程数据...`);\n    \n    const url = `/admin/xsd/pkgl/xskb/sdpkkbList?xnxq=${xnxq}&xhid=${xhid}&xqdm=${xqdm}&xskbxslx=0`;\n    \n    const requestOptions = {\n        \"headers\": {\n            \"Accept\": \"application/json, text/plain, */*\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        \"method\": \"GET\",\n        \"credentials\": \"include\"\n    };\n\n    try {\n        const response = await fetch(url, requestOptions);\n\n        if (!response.ok) {\n            throw new Error(`网络请求失败。状态码: ${response.status}`);\n        }\n        \n        const jsonData = await response.json();\n        \n        if (jsonData.ret !== 0) {\n            throw new Error(`API 返回错误: ${jsonData.msg || '未知错误'}`);\n        }\n\n        const courses = parseCourseData(jsonData);\n\n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"未找到任何课程数据，本学期可能无课。\");\n            return null;\n        }\n\n        console.log(`JS: 课程数据获取成功，共 ${courses.length} 门课程。`);\n        return courses;\n\n    } catch (error) {\n        window.shiguangBridge.showToast(`获取课程数据失败: ${error.message}`);\n        console.error('JS: fetchCourseData Error:', error);\n        return null;\n    }\n}\n\n/**\n * 保存课程数据到应用。\n * @param {Array} courses - 课程列表\n * @returns {Promise<boolean>} - 是否保存成功\n */\nasync function saveCourses(courses) {\n    console.log(`JS: 正在保存 ${courses.length} 门课程...`);\n    window.shiguangBridge.showToast(`正在保存 ${courses.length} 门课程...`);\n    \n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses, null, 2));\n        console.log(\"JS: 课程保存成功。\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        console.error('JS: saveCourses Error:', error);\n        return false;\n    }\n}\n\n/**\n * 导入预设时间段到应用。\n * @param {Array} timeSlots - 时间段列表\n * @returns {Promise<boolean>} - 是否导入成功\n */\nasync function importPresetTimeSlots(timeSlots) {\n    console.log(`JS: 正在导入 ${timeSlots.length} 个预设时间段...`);\n    window.shiguangBridge.showToast(`正在导入作息时间...`);\n    \n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        console.log(\"JS: 预设时间段导入成功。\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n        console.error('JS: importPresetTimeSlots Error:', error);\n        return false;\n    }\n}\n\n/**\n * 保存课表配置（开学日期等）。\n * @param {string|null} semesterStartDate - 开学日期\n * @returns {Promise<boolean>} - 是否保存成功\n */\nasync function saveCourseConfig(semesterStartDate) {\n    if (!semesterStartDate) {\n        console.log(\"JS: 开学日期为空，跳过课表配置保存。\");\n        return true;\n    }\n    \n    console.log(`JS: 正在保存课表配置（开学日期: ${semesterStartDate}）...`);\n    \n    const config = {\n        semesterStartDate: semesterStartDate\n    };\n    \n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        console.log(\"JS: 课表配置保存成功。\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"保存课表配置失败: \" + error.message);\n        console.error('JS: saveCourseConfig Error:', error);\n        return false;\n    }\n}\n\n/**\n * 检查是否在登录页面。\n * @returns {boolean}\n */\nfunction isLoginPage() {\n    const url = window.location.href;\n    return url.includes('admin/login');\n}\n\n/**\n * 提示用户开始导入。\n * @returns {Promise<boolean>} - 用户是否确认\n */\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"超星教务系统课表导入\",\n        \"导入前请确保您已在成功登录教务系统，并打开课表页面。\\n\\n本脚本将自动获取作息时间、开学日期和课程数据。\",\n        \"开始导入\"\n    );\n}\n\n/**\n * 主导入流程。\n */\nasync function runImportFlow() {\n    console.log(\"JS: 开始执行超星教务系统课表导入流程...\");\n    \n    // 1. 检查是否在登录页面\n    if (isLoginPage()) {\n        window.shiguangBridge.showToast(\"导入失败：请先登录教务系统！\");\n        return;\n    }\n\n    // 2. 提示用户确认开始导入\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n    \n    // 3. 提取页面参数\n    const params = await extractPageParams();\n    if (!params) {\n        window.shiguangBridge.showToast(\"无法从页面获取必要参数，请确保在正确的页面执行脚本。\");\n        return;\n    }\n    \n    const { xhid, xqdm: pageXqdm, xnxqSelectHtml } = params;\n    \n    // 4. 让用户选择学年学期\n    const xnxq = await selectAcademicYearAndSemester(xnxqSelectHtml);\n    if (xnxq === null) {\n        window.shiguangBridge.showToast(\"导入已取消，未选择学年学期。\");\n        return;\n    }\n\n    // 5. 让用户选择校区（默认使用页面参数中的 xqdm，若校区接口失败则自动回退使用页面 xqdm）\n    const selectedCampus = await selectCampus(pageXqdm);\n    if (!selectedCampus) {\n        window.shiguangBridge.showToast(\"导入已取消，未选择校区。\");\n        return;\n    }\n    const { xqdm } = selectedCampus;\n\n    // 6. 获取节次时间和开学日期\n    const timeData = await fetchTimeAndWeekData(xnxq, xqdm);\n    const { timeSlots, semesterStartDate } = timeData;\n\n    // 7. 获取课程数据\n    const courses = await fetchCourseData(xnxq, xhid, xqdm);\n    if (!courses) {\n        return;\n    }\n\n    // 8. 保存课程数据\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        return;\n    }\n\n    // 9. 导入预设时间段\n    if (Array.isArray(timeSlots) && timeSlots.length > 0) {\n        await importPresetTimeSlots(timeSlots);\n    } else {\n        console.log(\"JS: 未生成有效时间段，跳过预设时间段导入。\");\n    }\n\n    // 10. 保存课表配置（开学日期）\n    if (semesterStartDate) {\n        await saveCourseConfig(semesterStartDate);\n    } else {\n        console.log(\"JS: 未获取到开学日期，跳过课表配置保存。\");\n    }\n\n    // 11. 完成\n    window.shiguangBridge.showToast(`导入成功！共导入 ${courses.length} 门课程。`);\n    window.shiguangBridge.notifyTaskCompletion();\n    console.log(\"JS: 超星教务系统课表导入流程完成。\");\n}\n\n// 执行主流程\nrunImportFlow();","MYSY":"// 绵阳师范学院正方教务系统课表适配脚本\n// 页面为 frameset 结构，课表主体在 iframe[name=\"Frame1\"] 的 #kbtable 中。\n\nfunction showToast(message) {\n  try {\n    const bridge = window.shiguangBridge;\n    if (bridge && typeof bridge.showToast === 'function') {\n      bridge.showToast(message);\n    }\n  } catch (error) {\n    console.error('[MYSY] showToast failed:', error);\n  }\n}\n\nfunction getScheduleDocument() {\n  if (document.querySelector && document.querySelector('#kbtable')) {\n    return document;\n  }\n\n  const frames = [\n    document.querySelector('iframe[name=\"Frame1\"]'),\n    document.querySelector('frame[name=\"Frame1\"]')\n  ];\n\n  for (const frame of frames) {\n    if (!frame) continue;\n    try {\n      const doc = frame.contentDocument || frame.contentWindow.document;\n      if (doc && doc.querySelector('#kbtable')) return doc;\n    } catch (error) {\n      console.warn('[MYSY] Unable to access Frame1 document:', error);\n    }\n  }\n\n  try {\n    const namedFrame = window.frames && window.frames['Frame1'];\n    if (namedFrame && namedFrame.document && namedFrame.document.querySelector('#kbtable')) {\n      return namedFrame.document;\n    }\n  } catch (error) {\n    console.warn('[MYSY] Unable to access named Frame1:', error);\n  }\n\n  return null;\n}\n\nfunction waitForScheduleTable(timeoutMs) {\n  const timeout = timeoutMs || 15000;\n  const start = Date.now();\n\n  return new Promise((resolve) => {\n    const check = () => {\n      const doc = getScheduleDocument();\n      if (doc && doc.querySelector('#kbtable')) {\n        resolve(doc);\n        return;\n      }\n      if (Date.now() - start >= timeout) {\n        resolve(getScheduleDocument());\n        return;\n      }\n      setTimeout(check, 250);\n    };\n    check();\n  });\n}\n\nfunction parseWeeks(weekStr) {\n  if (!weekStr) return [];\n\n  const cleaned = String(weekStr)\n    .replace(/\\[[^\\]]*节[^\\]]*\\]/g, '')\n    .replace(/\\s+/g, '');\n\n  const weeks = [];\n  const parts = cleaned.split(/[,，]/).filter(Boolean);\n\n  for (const part of parts) {\n    const parityMatch = part.match(/[（(](单|双)[）)]/);\n    const parity = parityMatch ? parityMatch[1] : null;\n    const numeric = part\n      .replace(/[（(](单|双)[）)]/g, '')\n      .replace(/[（(]周[）)]/g, '')\n      .replace(/周/g, '');\n    const match = numeric.match(/^(\\d+)(?:[-~到](\\d+))?$/);\n\n    if (!match) continue;\n\n    const start = Number(match[1]);\n    const end = match[2] ? Number(match[2]) : start;\n\n    for (let week = start; week <= end; week++) {\n      if (parity === '单' && week % 2 === 0) continue;\n      if (parity === '双' && week % 2 === 1) continue;\n      weeks.push(week);\n    }\n  }\n\n  return Array.from(new Set(weeks)).sort((a, b) => a - b);\n}\n\nfunction parseSectionRange(text) {\n  const match = String(text || '').match(/\\[(\\d{1,2})(?:\\s*[-~]\\s*(\\d{1,2}))?节\\]/);\n  if (!match) return null;\n\n  return {\n    start: Number(match[1]),\n    end: Number(match[2] || match[1])\n  };\n}\n\nfunction getDirectText(element) {\n  const parts = [];\n\n  for (const node of element.childNodes) {\n    if (node.nodeType !== 3) continue;\n    const text = (node.textContent || '').replace(/\\s+/g, ' ').trim();\n    if (text) parts.push(text);\n  }\n\n  return parts.join(' ').trim();\n}\n\nfunction getTitledText(element, title) {\n  const target = element.querySelector(`font[title=\"${title}\"]`);\n  if (!target) return '';\n  return (target.textContent || '').replace(/\\s+/g, ' ').trim();\n}\n\nfunction parseCourseDiv(div) {\n  const text = (div.textContent || '').replace(/\\s+/g, ' ').trim();\n  if (!text) return null;\n\n  const idParts = (div.getAttribute('id') || '').split('_');\n  const day = Number(idParts[1]) || 0;\n  const name = getDirectText(div);\n  const teacher = getTitledText(div, '老师') || '待定';\n  const position = getTitledText(div, '教室') || '待定';\n  const timeText = getTitledText(div, '周次(节次)');\n  const weeks = parseWeeks(timeText);\n\n  if (!name || weeks.length === 0 || day < 1 || day > 7) return null;\n\n  const section = parseSectionRange(timeText);\n  const course = {\n    name: name,\n    teacher: teacher,\n    position: position,\n    day: day,\n    startSection: section ? section.start : 0,\n    endSection: section ? section.end : 0,\n    weeks: weeks\n  };\n\n  return course;\n}\n\nfunction extractCourses(doc) {\n  const table = doc.querySelector('#kbtable');\n  if (!table) return [];\n\n  const courses = [];\n  const seen = new Set();\n\n  table.querySelectorAll('div.kbcontent').forEach((div) => {\n    const course = parseCourseDiv(div);\n    if (!course) return;\n\n    const key = JSON.stringify(course);\n    if (seen.has(key)) return;\n    seen.add(key);\n    courses.push(course);\n  });\n\n  courses.sort((a, b) => {\n    if (a.day !== b.day) return a.day - b.day;\n    if (a.startSection !== b.startSection) return a.startSection - b.startSection;\n    return a.name.localeCompare(b.name);\n  });\n\n  return courses;\n}\n\nfunction toMinutes(hhmm) {\n  const parts = String(hhmm).split(':').map(Number);\n  return parts[0] * 60 + parts[1];\n}\n\nfunction toHHMM(totalMinutes) {\n  const hours = Math.floor(totalMinutes / 60);\n  const minutes = totalMinutes % 60;\n  return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;\n}\n\nfunction generateTimeSlots(doc) {\n  const fallback = [\n    { number: 1, startTime: '08:00', endTime: '08:45' },\n    { number: 2, startTime: '08:50', endTime: '09:35' },\n    { number: 3, startTime: '09:55', endTime: '10:40' },\n    { number: 4, startTime: '10:45', endTime: '11:30' },\n    { number: 5, startTime: '11:35', endTime: '12:20' },\n    { number: 6, startTime: '14:00', endTime: '14:45' },\n    { number: 7, startTime: '14:50', endTime: '15:35' },\n    { number: 8, startTime: '15:55', endTime: '16:40' },\n    { number: 9, startTime: '16:45', endTime: '17:30' },\n    { number: 10, startTime: '17:35', endTime: '18:20' },\n    { number: 11, startTime: '19:00', endTime: '19:45' },\n    { number: 12, startTime: '19:50', endTime: '20:35' },\n    { number: 13, startTime: '20:40', endTime: '21:25' }\n  ];\n\n  const table = doc.querySelector('#kbtable');\n  if (!table) return fallback;\n\n  const blocks = [];\n  table.querySelectorAll('tr th[rowspan]').forEach((th) => {\n    const text = (th.textContent || '').replace(/\\s+/g, ' ').trim();\n    const match = text.match(/(\\d{1,2}):(\\d{2})\\s*[-~]\\s*(\\d{1,2}):(\\d{2})/);\n    if (!match) return;\n\n    const rowspan = Number(th.getAttribute('rowspan')) || 1;\n    blocks.push({\n      rowspan: rowspan,\n      start: `${match[1]}:${match[2]}`,\n      end: `${match[3]}:${match[4]}`\n    });\n  });\n\n  if (blocks.length === 0) return fallback;\n\n  const slots = [];\n  let number = 1;\n  const classDuration = 45;\n  const breakDuration = 5;\n\n  for (const block of blocks) {\n    const count = Math.max(1, block.rowspan);\n    let cursor = toMinutes(block.start);\n\n    for (let i = 0; i < count; i++) {\n      const start = cursor;\n      const end = start + classDuration;\n      slots.push({\n        number: number,\n        startTime: toHHMM(start),\n        endTime: toHHMM(end)\n      });\n      number++;\n      cursor = end + (i < count - 1 ? breakDuration : 0);\n    }\n  }\n\n  return slots.length > 0 ? slots : fallback;\n}\n\nasync function saveCourses(courses) {\n  try {\n    if (!window.shiguangBridgePromise || typeof window.shiguangBridgePromise.saveImportedCourses !== 'function') {\n      throw new Error('saveImportedCourses bridge not found');\n    }\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n    return true;\n  } catch (error) {\n    console.error('[MYSY] save courses failed:', error);\n    showToast(`课表保存失败: ${error.message}`);\n    return false;\n  }\n}\n\nasync function saveTimeSlots(slots) {\n  try {\n    if (!window.shiguangBridgePromise || typeof window.shiguangBridgePromise.savePresetTimeSlots !== 'function') {\n      throw new Error('savePresetTimeSlots bridge not found');\n    }\n    await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(slots));\n    return true;\n  } catch (error) {\n    console.error('[MYSY] save time slots failed:', error);\n    showToast(`时间模板保存失败: ${error.message}`);\n    return false;\n  }\n}\n\nasync function saveCourseConfig() {\n  try {\n    if (!window.shiguangBridgePromise || typeof window.shiguangBridgePromise.saveCourseConfig !== 'function') {\n      return;\n    }\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\n      semesterTotalWeeks: 20,\n      defaultClassDuration: 45,\n      defaultBreakDuration: 5,\n      firstDayOfWeek: 1\n    }));\n  } catch (error) {\n    console.warn('[MYSY] save course config failed:', error);\n  }\n}\n\nasync function runImportFlow() {\n  console.log('[MYSY] 开始导入绵阳师范学院课表...');\n  showToast('正在检查课表页面...');\n\n  const doc = await waitForScheduleTable(15000);\n  if (!doc || !doc.querySelector('#kbtable')) {\n    showToast('未找到课表，请先打开“学期理论课表”并确认已加载');\n    return;\n  }\n\n  const courses = extractCourses(doc);\n  if (courses.length === 0) {\n    showToast('未找到已安排上课时间的课程');\n    return;\n  }\n\n  try {\n    const confirmed = await window.shiguangBridgePromise.showAlert(\n      '教务系统课表导入',\n      `检测到 ${courses.length} 门课程，是否导入？`,\n      '确认导入'\n    );\n    if (!confirmed) {\n      showToast('已取消导入');\n      return;\n    }\n  } catch (error) {\n    console.warn('[MYSY] confirmation dialog unavailable:', error);\n  }\n\n  if (!(await saveCourses(courses))) return;\n\n  const timeSlots = generateTimeSlots(doc);\n  if (!(await saveTimeSlots(timeSlots))) return;\n\n  await saveCourseConfig();\n\n  showToast(`课表导入成功，共导入 ${courses.length} 门课程`);\n  console.log(`[MYSY] 成功导入 ${courses.length} 门课程`);\n\n  try {\n    if (window.shiguangBridge && typeof window.shiguangBridge.notifyTaskCompletion === 'function') {\n      window.shiguangBridge.notifyTaskCompletion();\n    }\n  } catch (error) {\n    console.warn('[MYSY] notifyTaskCompletion failed:', error);\n  }\n}\n\nif (/mtc\\.edu\\.cn$/i.test(window.location.hostname)) {\n  setTimeout(runImportFlow, 800);\n} else {\n  showToast('请先在绵阳师范学院教务系统打开课表页面');\n}\n","MMPT":"// ====================== 工具函数 ======================\n\n/**\n * 检查用户是否已登录。\n * 如果当前URL包含登录关键字，说明用户未登录，返回false。\n * 如果不包含登录关键字，说明用户已登录，返回true。\n */\nfunction isUserLoggedIn() {\n    const url = window.location.href;\n    const loginKeywords = [\n        \"https://jwc.mmpt.edu.cn/xtgl/login_slogin.html\"\n    ];\n    \n    // 检查URL是否包含登录关键字\n    for (const keyword of loginKeywords) {\n        if (url.includes(keyword)) {\n            return false; // 包含登录关键字，说明用户未登录\n        }\n    }\n    \n    // 不包含登录关键字，说明用户已登录\n    return true;\n}\n\n// 解析节次字符串 -> 开始节次和结束节次\nfunction parseSections(sectionStr) {\n    if (!sectionStr) return { start: 1, end: 1 };\n    \n    // 处理 \"1-2节\" 或 \"3-4节\" 等格式\n    const match = sectionStr.match(/(\\d+)-(\\d+)节?/);\n    if (match) {\n        return {\n            start: parseInt(match[1]),\n            end: parseInt(match[2])\n        };\n    }\n    \n    // 处理单个节次 \"1节\" 等\n    const singleMatch = sectionStr.match(/(\\d+)节?/);\n    if (singleMatch) {\n        const num = parseInt(singleMatch[1]);\n        return { start: num, end: num };\n    }\n    \n    return { start: 1, end: 1 };\n}\n\n/**\n * 解析周次字符串，处理单双周和周次范围。\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    const weekSets = weekStr.split(',');\n    let weeks = [];\n\n    for (const set of weekSets) {\n        const trimmedSet = set.trim();\n\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周/); // 匹配以数字周结束的\n\n        let start = 0;\n        let end = 0;\n        let processed = false;\n\n        if (rangeMatch) { // 范围, 如 \"1-5周\"\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) { // 单个周, 如 \"6周\"\n             start = end = Number(singleMatch[1]);\n             processed = true;\n        }\n        \n        if (processed) {\n            // 确定单双周\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue; // 单周跳过偶数\n                if (isDouble && w % 2 !== 0) continue; // 双周跳过奇数\n                weeks.push(w);\n            }\n        }\n    }\n\n    // 去重并排序\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n// 合并重复课程\nfunction mergeDuplicateCourses(courses) {\n    const merged = [];\n    const keyMap = {}; // key = name+day+startSection+endSection+position\n\n    for (const c of courses) {\n        const key = `${c.name}|${c.day}|${c.startSection}|${c.endSection}|${c.position}`;\n        if (!keyMap[key]) {\n            keyMap[key] = { ...c, weeks: [...c.weeks] };\n        } else {\n            keyMap[key].weeks = Array.from(new Set([...keyMap[key].weeks, ...c.weeks]));\n        }\n    }\n\n    for (const k in keyMap) merged.push(keyMap[k]);\n    return merged;\n}\n\nconst MMPT_CONFIG = {\n    name: '茂名职业技术学院',\n    domains: ['mmpt.edu.cn', 'mmvtc.edu.cn'],\n    jwcUrl: 'https://jwc.mmpt.edu.cn',\n    apiPath: '/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151'\n};\n\n// 茂名职业技术学院作息时间表配置\nconst MMVT_SCHEDULE_CONFIG = {\n    '南校区': {\n        timeSlots: [\n            { number: 1, startTime: \"08:30\", endTime: \"09:10\" },\n            { number: 2, startTime: \"09:20\", endTime: \"10:00\" },\n            { number: 3, startTime: \"10:15\", endTime: \"10:55\" },\n            { number: 4, startTime: \"11:05\", endTime: \"11:45\" },\n            { number: 5, startTime: \"14:30\", endTime: \"15:10\" },\n            { number: 6, startTime: \"15:20\", endTime: \"16:00\" },\n            { number: 7, startTime: \"16:15\", endTime: \"16:55\" },\n            { number: 8, startTime: \"17:05\", endTime: \"17:45\" },\n            { number: 9, startTime: \"19:00\", endTime: \"19:40\" },\n            { number: 10, startTime: \"19:50\", endTime: \"20:30\" },\n            { number: 11, startTime: \"20:40\", endTime: \"21:20\" }\n        ]\n    },\n    '北校区': {\n        timeSlots: [\n            { number: 1, startTime: \"08:00\", endTime: \"08:40\" },\n            { number: 2, startTime: \"08:50\", endTime: \"09:30\" },\n            { number: 3, startTime: \"09:40\", endTime: \"10:20\" },\n            { number: 4, startTime: \"10:30\", endTime: \"11:10\" },\n            { number: 5, startTime: \"11:20\", endTime: \"12:00\" },\n            { number: 6, startTime: \"14:30\", endTime: \"15:10\" },\n            { number: 7, startTime: \"15:20\", endTime: \"16:00\" },\n            { number: 8, startTime: \"16:15\", endTime: \"16:55\" },\n            { number: 9, startTime: \"17:05\", endTime: \"17:45\" },\n            { number: 10, startTime: \"19:00\", endTime: \"19:40\" },\n            { number: 11, startTime: \"19:50\", endTime: \"20:30\" },\n            { number: 12, startTime: \"20:40\", endTime: \"21:20\" }\n        ]\n    }\n};\n\n\n// 获取MMPT配置（无需选择，直接使用）\nfunction getMMPTConfig() {\n    return MMPT_CONFIG;\n}\n\n// 选择校区时间表\nasync function selectCampusSchedule() {\n    const campuses = Object.keys(MMVT_SCHEDULE_CONFIG);\n    const campusIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择校区时间表\", \n        JSON.stringify(campuses),\n        -1\n    );\n    \n    if (campusIndex === null) {\n        window.shiguangBridge.showToast(\"未选择校区，使用南校区时间表\");\n        return MMVT_SCHEDULE_CONFIG['南校区'];\n    }\n    \n    return MMVT_SCHEDULE_CONFIG[campuses[campusIndex]];\n}\n\n\n// 选择学年\nasync function selectAcademicYear() {\n    const currentYear = new Date().getFullYear();\n    const years = [];\n    \n    // 生成最近3年的学年选项，格式为 xxxx-xxxx\n    for (let i = 0; i < 3; i++) {\n        const year = currentYear - i;\n        years.push(`${year}-${year + 1}`);\n    }\n    \n    const yearIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学年\", \n        JSON.stringify(years),\n        0 // 默认选择当前学年\n    );\n    \n    if (yearIndex === null) {\n        return currentYear; // 默认当前学年\n    }\n    \n    return currentYear - yearIndex;\n}\n\n// 选择学期\nasync function selectSemester() {\n    const semesters = [\"第一学期\", \"第二学期\"];\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\", \n        JSON.stringify(semesters),\n        -1\n    );\n    \n    if (semesterIndex === null) {\n        return \"3\"; // 默认第一学期\n    }\n    \n    return semesterIndex === 0 ? \"3\" : \"12\";\n}\n\n// ====================== 获取课程数据 ======================\nasync function fetchCourseData() {\n    try {\n        // 使用MMPT配置，让用户选择学年和学期\n        const schoolConfig = getMMPTConfig();\n        const academicYear = await selectAcademicYear();\n        const semester = await selectSemester();\n        \n        console.log(`使用学校配置: ${schoolConfig.name}`);\n        console.log(`选择学年: ${academicYear}, 选择学期: ${semester}`);\n        \n        // 构建完整的API URL\n        const apiUrl = schoolConfig.jwcUrl + schoolConfig.apiPath;\n        \n        // 从新系统获取课程数据\n        // 使用POST请求获取完整的课程数据\n        const response = await fetch(apiUrl, {\n            method: 'POST',\n            headers: {\n                'Content-Type': 'application/x-www-form-urlencoded',\n                'Accept': 'application/json'\n            },\n            body: new URLSearchParams({\n                'xnm': academicYear,   // 用户选择的学年\n                'xqm': semester,      // 用户选择的学期（3或12）\n                'kzlx': 'ck',         // 课程类型\n                'xsdm': '',           // 学生代码\n                'kclbdm': ''          // 课程类别代码\n            })\n        });\n        \n        if (!response.ok) {\n            throw new Error(`HTTP error! status: ${response.status}`);\n        }\n        \n        const data = await response.json();\n        return data;\n    } catch (err) {\n        console.error(\"获取课程数据失败:\", err);\n        window.shiguangBridge.showToast(\"获取课程数据失败：\" + err.message);\n        return null;\n    }\n}\n\n// ====================== 解析课程数据 ======================\nfunction parseCourseData(responseData) {\n    const courses = [];\n    \n    if (!responseData || !responseData.kbList) {\n        console.error(\"响应数据格式不正确\");\n        return [];\n    }\n    \n    responseData.kbList.forEach(course => {\n        try {\n            // 解析节次\n            const sections = parseSections(course.jc);\n            \n            // 解析周次\n            const weeks = parseWeeks(course.zcd);\n            \n            if (weeks.length === 0) {\n                console.warn(`课程 ${course.kcmc} 没有有效的周次信息`);\n                return;\n            }\n            \n            courses.push({\n                name: course.kcmc || \"未知课程\",\n                teacher: course.xm || \"未知教师\",\n                position: course.cdmc || \"未知教室\",\n                day: parseInt(course.xqj) || 1,\n                startSection: sections.start,\n                endSection: sections.end,\n                weeks: weeks\n            });\n        } catch (err) {\n            console.error(`解析课程数据失败:`, err, course);\n        }\n    });\n    \n    return courses;\n}\n\n// ====================== 保存课程 ======================\nasync function saveCourses(courses) {\n    try {\n        const result = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        if (result === true) {\n            window.shiguangBridge.showToast(\"课程导入成功！\");\n            return true;\n        } else {\n            window.shiguangBridge.showToast(\"课程导入失败，请查看日志！\");\n            return false;\n        }\n    } catch (err) {\n        console.error(\"保存课程失败:\", err);\n        window.shiguangBridge.showToast(\"保存课程失败：\" + err.message);\n        return false;\n    }\n}\n\n// ====================== 导入预设时间段（根据选择的校区） ======================\nasync function importPresetTimeSlots() {\n    try {\n        // 让用户选择校区时间表\n        const campusConfig = await selectCampusSchedule();\n        const timeSlots = campusConfig.timeSlots;\n        \n        console.log(`使用校区时间表: ${campusConfig.name || '未知校区'}`);\n        console.log(`时间段数量: ${timeSlots.length}`);\n        \n        const result = await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        if (result === true) {\n            window.shiguangBridge.showToast(`时间段导入成功！共导入${timeSlots.length}个时间段`);\n        } else {\n            window.shiguangBridge.showToast(\"时间段导入失败，请查看日志！\");\n        }\n    } catch (err) {\n        console.error(\"时间段导入失败:\", err);\n        window.shiguangBridge.showToast(\"时间段导入失败：\" + err.message);\n    }\n}\n\n// ====================== 主流程 ======================\nasync function runImportFlow() {\n    // 检查用户是否已登录\n    if (!isUserLoggedIn()) {\n        window.shiguangBridge.showToast(\"检测到未登录状态，请先登录后再使用课程导入功能！\");\n        return;\n    }\n    \n    window.shiguangBridge.showToast(\"课程导入流程即将开始...\");\n\n    try {\n        // 1️⃣ 获取课程数据（选择学年学期）\n        window.shiguangBridge.showToast(\"请选择学年和学期...\");\n        \n        // 从新系统获取课程数据\n        const responseData = await fetchCourseData();\n        if (!responseData) {\n            window.shiguangBridge.showToast(\"获取课程数据失败！\");\n            return;\n        }\n        \n        // 2️⃣ 解析课程数据\n        window.shiguangBridge.showToast(\"正在解析课程数据...\");\n        const courses = parseCourseData(responseData);\n        if (!courses || courses.length === 0) {\n            window.shiguangBridge.showToast(\"未找到课程数据！\");\n            return;\n        }\n        \n        // 3️⃣ 合并重复课程\n        window.shiguangBridge.showToast(\"正在合并重复课程...\");\n        const mergedCourses = mergeDuplicateCourses(courses);\n        \n        // 4️⃣ 保存课程\n        window.shiguangBridge.showToast(\"正在保存课程数据...\");\n        const saveResult = await saveCourses(mergedCourses);\n        if (!saveResult) {\n            return;\n        }\n\n        // 5️⃣ 导入预设时间段（用户选择校区）\n        window.shiguangBridge.showToast(\"请选择校区时间表...\");\n        await importPresetTimeSlots();\n\n        // ✅ 只有所有步骤都成功完成，才通知任务完成\n        window.shiguangBridge.showToast(`课程导入成功，共导入 ${mergedCourses.length} 门课程！`);\n        console.log(\"JS：整个导入流程执行完毕并成功。\");\n        window.shiguangBridge.notifyTaskCompletion();\n        \n    } catch (err) {\n        console.error(\"导入流程失败:\", err);\n        window.shiguangBridge.showToast(\"导入失败：\" + err.message);\n        // ❌ 失败时不调用 notifyTaskCompletion()\n    }\n}\n\n// 启动流程\nrunImportFlow();\n","MKU_01":"// 闽南科技学院(mku.edu.cn) 轻屿课表适配脚本\n// 教务平台：强智教务系统（新版 layui UI）\n// 数据来源：个人课表 /jsxsd/xskb/xskb_list.do（默认渲染当前学期，可用 xnxq01id 切换学期）\n// 解析逻辑参考本仓库 HYNU / ZHKU 两个强智适配的实现，按 MKU 新版 DOM 重写\n// 非该校在校开发者适配，出现问题请提交 issue 或 PR\n\n// ===== 基础常量 =====\n\nconst MKU_BASE_URL = \"https://jwgl.mku.edu.cn\";\nconst MKU_TIMETABLE_URL = MKU_BASE_URL + \"/jsxsd/xskb/xskb_list.do\";\nconst MKU_WEEK_AJAX_URL = MKU_BASE_URL + \"/jsxsd/xskb/jxzlzc_xnxq_ajax\";\nconst MKU_HOME_URL = MKU_BASE_URL + \"/jsxsd/framework/xsMainV.htmlx\";\n\n// 默认总周数；实际值优先取自教务周次接口 jxzlzc_xnxq_ajax\nconst MKU_DEFAULT_TOTAL_WEEKS = 20;\n\n// 每小节课 45 分钟、课间 10 分钟（与课表页大节时间 08:00~09:40 等标注一致）\nconst MKU_SECTION_MINUTES = 45;\nconst MKU_BREAK_MINUTES = 10;\n\n// 兜底作息（按 2026-2027-1 学期课表页标注的大节时间推导）\nconst MKU_FALLBACK_TIME_SLOTS = [\n  { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n  { number: 2, startTime: \"08:55\", endTime: \"09:40\" },\n  { number: 3, startTime: \"10:00\", endTime: \"10:45\" },\n  { number: 4, startTime: \"10:55\", endTime: \"11:40\" },\n  { number: 5, startTime: \"14:00\", endTime: \"14:45\" },\n  { number: 6, startTime: \"14:55\", endTime: \"15:40\" },\n  { number: 7, startTime: \"15:50\", endTime: \"16:35\" },\n  { number: 8, startTime: \"16:45\", endTime: \"17:30\" },\n  { number: 9, startTime: \"18:30\", endTime: \"19:15\" },\n  { number: 10, startTime: \"19:25\", endTime: \"20:10\" },\n  { number: 11, startTime: \"20:20\", endTime: \"21:05\" },\n  { number: 12, startTime: \"21:15\", endTime: \"22:00\" }\n];\n\n// ===== 通用工具 =====\n\n// HH:mm 转当天分钟数\nfunction mkuTimeToMinutes(hhmm) {\n  const parts = hhmm.split(\":\");\n  return Number(parts[0]) * 60 + Number(parts[1]);\n}\n\n// 当天分钟数转 HH:mm\nfunction mkuMinutesToTime(total) {\n  const h = Math.floor(total / 60);\n  const m = total % 60;\n  return String(h).padStart(2, \"0\") + \":\" + String(m).padStart(2, \"0\");\n}\n\n// Date 转 YYYY-MM-DD\nfunction mkuFormatDate(date) {\n  const y = date.getFullYear();\n  const m = String(date.getMonth() + 1).padStart(2, \"0\");\n  const d = String(date.getDate()).padStart(2, \"0\");\n  return y + \"-\" + m + \"-\" + d;\n}\n\n// ===== 周次与节次解析 =====\n\n// 将周次片段（\"1,3,5\" / \"1-16\" / \"1-8,10-16\"）展开为去重排序的数字数组\nfunction mkuExpandWeeks(weekPart) {\n  const weeks = [];\n  (weekPart.match(/\\d+(?:\\s*[-~]\\s*\\d+)?/g) || []).forEach((seg) => {\n    const m = seg.match(/(\\d+)\\s*(?:[-~]\\s*(\\d+))?/);\n    const start = Number(m[1]);\n    const end = m[2] ? Number(m[2]) : start;\n    for (let w = start; w <= end; w++) weeks.push(w);\n  });\n  return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n// 解析\"时间\"字段，如 \"1,3,5,7,9,11,13,15周[1-2节]\"\nfunction mkuParseTimeText(timeText) {\n  if (!timeText) return null;\n  const weekMatch = timeText.match(/^([^周]+)周/);\n  const secMatch = timeText.match(/\\[\\s*(\\d+)\\s*(?:[-~]\\s*(\\d+))?\\s*节\\s*\\]/);\n  if (!weekMatch && !secMatch) return null;\n\n  let weeks = weekMatch ? mkuExpandWeeks(weekMatch[1]) : null;\n  if (weeks) {\n    // 兼容\"单周/双周\"标注\n    if (/单\\s*周/.test(timeText)) weeks = weeks.filter((w) => w % 2 === 1);\n    if (/双\\s*周/.test(timeText)) weeks = weeks.filter((w) => w % 2 === 0);\n  }\n\n  return {\n    weeks,\n    startSection: secMatch ? Number(secMatch[1]) : null,\n    endSection: secMatch ? (secMatch[2] ? Number(secMatch[2]) : Number(secMatch[1])) : null\n  };\n}\n\n// ===== 课表解析 =====\n\n// 将表格展开为 grid[row][col]，正确处理 rowspan / colspan\nfunction mkuBuildGrid(table) {\n  const grid = [];\n  Array.from(table.rows).forEach((tr, r) => {\n    if (!grid[r]) grid[r] = [];\n    let col = 0;\n    Array.from(tr.cells).forEach((td) => {\n      while (grid[r][col]) col++;\n      const rowSpan = td.rowSpan || 1;\n      const colSpan = td.colSpan || 1;\n      for (let dr = 0; dr < rowSpan; dr++) {\n        for (let dc = 0; dc < colSpan; dc++) {\n          if (!grid[r + dr]) grid[r + dr] = [];\n          grid[r + dr][col + dc] = td;\n        }\n      }\n      col += colSpan;\n    });\n  });\n  return grid;\n}\n\n// 解析行标签（第 0 列）：大节范围与时间，如 \"1-2\" + \"08:00~09:40\"\nfunction mkuParseRowInfos(table) {\n  const rowInfos = new Map();\n  Array.from(table.rows).forEach((tr, r) => {\n    const labelCell = tr.cells[0];\n    if (!labelCell) return;\n    const titleText = labelCell.querySelector(\".index-title\")\n      ? labelCell.querySelector(\".index-title\").textContent.trim()\n      : \"\";\n    const range = titleText.match(/^(\\d+)(?:\\s*[-~]\\s*(\\d+))?$/);\n    if (!range) return;\n    const timeMatch = labelCell.textContent.match(/(\\d{1,2}:\\d{2})\\s*~\\s*(\\d{1,2}:\\d{2})/);\n    rowInfos.set(r, {\n      startSection: Number(range[1]),\n      endSection: range[2] ? Number(range[2]) : Number(range[1]),\n      blockStart: timeMatch ? mkuTimeToMinutes(timeMatch[1]) : null,\n      blockEnd: timeMatch ? mkuTimeToMinutes(timeMatch[2]) : null\n    });\n  });\n  return rowInfos;\n}\n\n// 从\"老师:xx;时间:..周[..节];地点:yy\"详情串中按标签取字段\nfunction mkuParseInfoField(text, label) {\n  const m = text.match(new RegExp(label + \"[:：]\\\\s*([^;；]*)\"));\n  return m ? m[1].trim() : \"\";\n}\n\n// 解析课表文档中的全部课程（同一单元格可能含多条课程，逐 li 解析）\nfunction mkuParseCourses(doc) {\n  const sampleTd = doc.querySelector('td[name=\"kbDataTd\"]');\n  if (!sampleTd) return { courses: [], rowInfos: new Map() };\n  const table = sampleTd.closest(\"table\");\n  const grid = mkuBuildGrid(table);\n  const rowInfos = mkuParseRowInfos(table);\n\n  const courses = [];\n  const seenTds = new Set();\n\n  for (const [row, rowInfo] of rowInfos) {\n    for (let day = 1; day <= 7; day++) {\n      const td = grid[row] && grid[row][day];\n      // rowspan 跨行的大格只在首行解析一次\n      if (!td || seenTds.has(td)) continue;\n      seenTds.add(td);\n\n      Array.from(td.querySelectorAll(\"li\")).forEach((li) => {\n        const nameEl = li.querySelector(\".qz-hasCourse-title\");\n        const infoEl = li.querySelector(\".qz-hasCourse-abbrinfo\");\n        if (!nameEl || !infoEl) return;\n        const name = nameEl.textContent.trim();\n        const infoText = infoEl.textContent.trim();\n        if (!name || !infoText) return;\n\n        const teacher = mkuParseInfoField(infoText, \"老师\") || \"未知教师\";\n        const position = mkuParseInfoField(infoText, \"地点\") || \"未知地点\";\n        const timeInfo = mkuParseTimeText(mkuParseInfoField(infoText, \"时间\"));\n\n        // 节次以\"时间\"字段为准，缺失时回退到大节行标签\n        const startSection = timeInfo && timeInfo.startSection\n          ? timeInfo.startSection\n          : rowInfo.startSection;\n        const endSection = timeInfo && timeInfo.endSection\n          ? timeInfo.endSection\n          : rowInfo.endSection;\n        const weeks = timeInfo && timeInfo.weeks && timeInfo.weeks.length\n          ? timeInfo.weeks\n          : null;\n        // 无周次信息则跳过，避免导入错误数据\n        if (!weeks) return;\n\n        courses.push({\n          name,\n          teacher,\n          position,\n          day,\n          startSection,\n          endSection,\n          weeks\n        });\n      });\n    }\n  }\n\n  // 完全重复的条目去重（同名/同师/同地/同天/同节次/同周次）\n  const deduped = [];\n  const seenKeys = new Set();\n  for (const course of courses) {\n    const key = [\n      course.name, course.teacher, course.position, course.day,\n      course.startSection, course.endSection, course.weeks.join(\",\")\n    ].join(\"|\");\n    if (seenKeys.has(key)) continue;\n    seenKeys.add(key);\n    deduped.push(course);\n  }\n\n  return { courses: deduped, rowInfos };\n}\n\n// 由课表页大节时间推导小节作息；推导失败时回退兜底配置\nfunction mkuBuildTimeSlots(rowInfos) {\n  const slots = [];\n  const rows = [...rowInfos.values()].sort((a, b) => a.startSection - b.startSection);\n  for (const info of rows) {\n    if (info.blockStart == null || info.blockEnd == null) return MKU_FALLBACK_TIME_SLOTS;\n    const count = info.endSection - info.startSection + 1;\n    const span = info.blockEnd - info.blockStart;\n    if (span !== MKU_SECTION_MINUTES * count + MKU_BREAK_MINUTES * (count - 1)) {\n      return MKU_FALLBACK_TIME_SLOTS;\n    }\n    for (let i = 0; i < count; i++) {\n      const start = info.blockStart + i * (MKU_SECTION_MINUTES + MKU_BREAK_MINUTES);\n      slots.push({\n        number: info.startSection + i,\n        startTime: mkuMinutesToTime(start),\n        endTime: mkuMinutesToTime(start + MKU_SECTION_MINUTES)\n      });\n    }\n  }\n  return slots.length ? slots : MKU_FALLBACK_TIME_SLOTS;\n}\n\n// ===== 教务数据获取 =====\n\n// 拉取个人课表页面（不传学期则渲染教务当前学期）\nasync function mkuFetchTimetableDoc(semesterId) {\n  let url = MKU_TIMETABLE_URL + \"?viweType=0&zc=&cj0701id=\";\n  if (semesterId) url += \"&xnxq01id=\" + encodeURIComponent(semesterId);\n  const resp = await fetch(url, { credentials: \"include\" });\n  if (!resp.ok) throw new Error(\"获取课表页面失败：HTTP \" + resp.status);\n  const html = await resp.text();\n  const doc = new DOMParser().parseFromString(html, \"text/html\");\n  if (!doc.querySelector(\"#xnxq01id\") && !doc.querySelector('td[name=\"kbDataTd\"]')) {\n    throw new Error(\"未获取到课表数据，请先在浏览器登录教务系统\");\n  }\n  return doc;\n}\n\n// 学期下拉选项（value 与显示文本一致，如 2026-2027-1）\nfunction mkuGetSemesterOptions(doc) {\n  const select = doc.querySelector(\"#xnxq01id\");\n  if (!select) return [];\n  return Array.from(select.options)\n    .filter((o) => o.value)\n    .map((o) => ({ value: o.value, text: o.text.trim(), selected: o.selected }));\n}\n\n// 学期总周数（接口返回如 [{\"qszc\":1,\"jszc\":20}]）\nasync function mkuFetchTotalWeeks(semesterId) {\n  try {\n    const resp = await fetch(MKU_WEEK_AJAX_URL + \"?xnxq01id=\" + encodeURIComponent(semesterId), {\n      credentials: \"include\"\n    });\n    const data = await resp.json();\n    if (Array.isArray(data) && data.length > 0 && Number(data[0].jszc) > 0) {\n      return Number(data[0].jszc);\n    }\n  } catch (error) {\n    console.warn(\"获取学期总周数失败，使用默认值：\", error);\n  }\n  return MKU_DEFAULT_TOTAL_WEEKS;\n}\n\n// 学期第一周周一日期：仅当所选学期是教务\"当前学期\"时可信\n// 首页 #headerShowTime 形如 \"2026-2027-1 第1周\"，结合本地今天日期反推开学日\nasync function mkuFetchSemesterStartDate(semesterId) {\n  try {\n    const resp = await fetch(MKU_HOME_URL, { credentials: \"include\" });\n    if (!resp.ok) return null;\n    const html = await resp.text();\n    const m = html.match(/id=\"headerShowTime\"[^>]*>\\s*([^<]+?)\\s*</);\n    if (!m) return null;\n    const currentSemester = m[1].split(/\\s+/)[0];\n    const weekMatch = m[1].match(/第\\s*(\\d+)\\s*周/);\n    if (currentSemester !== semesterId || !weekMatch) return null;\n    const currentWeek = Number(weekMatch[1]);\n    if (!(currentWeek >= 1)) return null;\n\n    const now = new Date();\n    const mondayOffset = (now.getDay() + 6) % 7; // 周一记 0\n    const start = new Date(\n      now.getFullYear(),\n      now.getMonth(),\n      now.getDate() - mondayOffset - (currentWeek - 1) * 7\n    );\n    return mkuFormatDate(start);\n  } catch (error) {\n    console.warn(\"获取学期开始日期失败：\", error);\n    return null;\n  }\n}\n\n// ===== 主流程 =====\n\nasync function mkuRunImportFlow() {\n  const bridge = window.shiguangBridge;\n  const bridgePromise = window.shiguangBridgePromise;\n\n  const confirmed = await bridgePromise.showAlert(\n    \"导入说明\",\n    \"将读取闽南科技学院教务系统\\\"个人课表\\\"数据并导入轻屿课表。\\n请确保已在当前浏览器登录教务系统（jwgl.mku.edu.cn）。\\n是否继续？\",\n    \"确认已登录\"\n  );\n  if (!confirmed) {\n    bridge.showToast(\"导入已取消\");\n    return;\n  }\n\n  bridge.showToast(\"正在读取课表页面...\");\n  const firstDoc = await mkuFetchTimetableDoc();\n\n  // 让用户选择学期（默认为教务当前学期）\n  const options = mkuGetSemesterOptions(firstDoc);\n  const defaultOption = options.find((o) => o.selected) || null;\n  let semesterId = defaultOption ? defaultOption.value : null;\n  if (options.length > 0) {\n    const defaultIndex = Math.max(0, options.findIndex((o) => o.selected));\n    const labels = options.map((o) => o.text + (o.selected ? \"（当前学期）\" : \"\"));\n    const index = await bridgePromise.showSingleSelection(\n      \"选择要导入的学期\",\n      JSON.stringify(labels),\n      defaultIndex\n    );\n    if (index == null || index < 0 || index >= options.length) {\n      bridge.showToast(\"导入已取消\");\n      return;\n    }\n    semesterId = options[index].value;\n  }\n\n  // 所选学期与默认渲染学期一致时直接复用首次页面\n  const doc = defaultOption && semesterId === defaultOption.value\n    ? firstDoc\n    : await mkuFetchTimetableDoc(semesterId);\n\n  const { courses, rowInfos } = mkuParseCourses(doc);\n  if (courses.length === 0) {\n    bridge.showToast(\"未解析到课程，请确认所选学期有课且已登录\");\n    return;\n  }\n\n  bridge.showToast(\"正在获取学期配置...\");\n  const totalWeeks = await mkuFetchTotalWeeks(semesterId);\n  const startDate = await mkuFetchSemesterStartDate(semesterId);\n\n  const timeSlots = mkuBuildTimeSlots(rowInfos);\n  const config = {\n    defaultClassDuration: MKU_SECTION_MINUTES,\n    defaultBreakDuration: MKU_BREAK_MINUTES,\n    semesterTotalWeeks: totalWeeks,\n    firstDayOfWeek: 1\n  };\n  // 仅当前学期能可靠推算开学日期，历史学期留给 App 端处理\n  if (startDate) config.semesterStartDate = startDate;\n\n  await bridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n  await bridgePromise.saveCourseConfig(JSON.stringify(config));\n  await bridgePromise.saveImportedCourses(JSON.stringify(courses));\n\n  bridge.showToast(\"导入成功：共 \" + courses.length + \" 条课程\");\n  bridge.notifyTaskCompletion();\n}\n\n// 启动导入流程\n(async () => {\n  try {\n    await mkuRunImportFlow();\n  } catch (error) {\n    console.error(\"课表导入失败：\", error);\n    try {\n      window.shiguangBridge.showToast(\n        \"导入失败：\" + (error && error.message ? error.message : error)\n      );\n    } catch (e) {\n      /* 桥接不可用时仅保留控制台日志 */\n    }\n  }\n})();\n","MASU_01":"// 马鞍山学院教务系统（jwxt.masu.edu.cn）拾光课表导入适配脚本\n// 青果/URP 金刚教务：课表渲染后直接解析 #manualArrangeCourseTable 表格，\n// 课程文本格式：课程名(序号) (教师) (周次,教室)，一个单元格可能含多门课\n\n// 预设作息时间（该校实际 11 节）\nconst MASU_TIME_SLOTS = [\n    { number: 1, startTime: \"08:20\", endTime: \"09:05\" },\n    { number: 2, startTime: \"09:10\", endTime: \"09:55\" },\n    { number: 3, startTime: \"10:15\", endTime: \"11:00\" },\n    { number: 4, startTime: \"11:05\", endTime: \"11:50\" },\n    { number: 5, startTime: \"13:50\", endTime: \"14:35\" },\n    { number: 6, startTime: \"14:40\", endTime: \"15:25\" },\n    { number: 7, startTime: \"15:45\", endTime: \"16:30\" },\n    { number: 8, startTime: \"16:35\", endTime: \"17:20\" },\n    { number: 9, startTime: \"18:20\", endTime: \"19:05\" },\n    { number: 10, startTime: \"19:10\", endTime: \"19:55\" },\n    { number: 11, startTime: \"20:00\", endTime: \"20:45\" }\n];\n\nfunction getErrorMessage(error) {\n    if (error && typeof error.message === \"string\" && error.message.trim()) return error.message;\n    if (typeof error === \"string\" && error.trim()) return error;\n    try {\n        const serialized = JSON.stringify(error);\n        if (serialized && serialized !== \"{}\") return serialized;\n    } catch (_) {\n        // Ignore serialization failures and use the generic fallback below.\n    }\n    return \"未知错误\";\n}\n\n// 从课表页 HTML 提取当前学期 id（semesterCalendar 配置中的 value:\"403\"），仅用于日志\nfunction extractCurrentSemesterId() {\n    const html = document.documentElement.outerHTML;\n    const m = html.match(/value:\"(\\d+)\"/);\n    return m ? m[1] : null;\n}\n\n// 去掉课程名末尾的序号括号：\"形势与政策1(202620271.11202001.002)\" → \"形势与政策1\"\nfunction cleanCourseName(name) {\n    return String(name || \"\").replace(/[（(][^（()）]*[)）]\\s*$/, \"\").trim();\n}\n\n// 解析周次文本：支持 \"2-5\"、\"双周2-6、10\"、\"2-3、6-7、9-14\"、\"6-7、9-11、13、16\" 等\nfunction parseWeeksText(weekStr) {\n    let isOdd = false;\n    let isEven = false;\n    let s = String(weekStr || \"\").trim();\n    if (s.includes(\"双周\") || s.startsWith(\"双\")) isEven = true;\n    if (s.includes(\"单周\") || s.startsWith(\"单\")) isOdd = true;\n    s = s.replace(/单周|双周|[单双]|第/g, \"\").replace(/周/g, \"\");\n\n    const weeks = new Set();\n    s.split(/[、,，;；]/).forEach(part => {\n        part = part.trim();\n        if (!part) return;\n        const range = part.match(/^(\\d+)-(\\d+)$/);\n        if (range) {\n            const start = Number(range[1]);\n            const end = Number(range[2]);\n            for (let i = start; i <= end; i++) {\n                if (isEven && i % 2 !== 0) continue;\n                if (isOdd && i % 2 === 0) continue;\n                weeks.add(i);\n            }\n        } else if (/^\\d+$/.test(part)) {\n            const n = Number(part);\n            if (isEven && n % 2 !== 0) return;\n            if (isOdd && n % 2 === 0) return;\n            weeks.add(n);\n        }\n    });\n    return Array.from(weeks).sort((a, b) => a - b);\n}\n\n// 解析单元格文本中的单门课\n// 文本格式：课程名(序号) (教师) (周次,教室)，教室可能含括号如 数智楼(3号实验楼)309\nconst COURSE_RE = /([^\\s()]+)\\([^()]*\\)\\s*\\(([^()]*)\\)\\s*\\(([^()]*(?:\\([^()]*\\)[^()]*)*)\\)/g;\n\nfunction parseCourseText(text, day, startSection, endSection, courses) {\n    let m;\n    COURSE_RE.lastIndex = 0;\n    while ((m = COURSE_RE.exec(text)) !== null) {\n        const name = cleanCourseName(m[1]);\n        const teacher = String(m[2] || \"\").trim();\n        const weeksRoom = m[3];\n        if (!name || !weeksRoom) continue;\n\n        // 周次段 \"周次,教室\"：按第一个逗号切分（教室可能含括号但无逗号）\n        const commaIdx = weeksRoom.indexOf(\",\");\n        if (commaIdx === -1) continue;\n        const weeksStr = weeksRoom.slice(0, commaIdx).trim();\n        const room = weeksRoom.slice(commaIdx + 1).trim();\n        const weeks = parseWeeksText(weeksStr);\n        if (weeks.length === 0) continue;\n\n        courses.push({\n            name,\n            teacher: teacher || \"未知\",\n            position: room || \"待定\",\n            day,\n            startSection,\n            endSection,\n            weeks\n        });\n    }\n}\n\n// 从渲染后的课表表格解析全部课程\nfunction parseCourseTableFromDom() {\n    const table = document.querySelector(\"#manualArrangeCourseTable\");\n    if (!table) return null;\n\n    const unitCount = 11; // 该校 11 节课\n    const courses = [];\n    const seen = new Set();\n\n    table.querySelectorAll(\"td[id^='TD']\").forEach(td => {\n        const idMatch = td.id.match(/^TD(\\d+)_/);\n        if (!idMatch) return;\n        const n = Number(idMatch[1]);\n        const day = Math.floor(n / unitCount) + 1;\n        const startSection = (n % unitCount) + 1;\n        const rowspan = Number(td.getAttribute(\"rowspan\")) || 1;\n        const endSection = startSection + rowspan - 1;\n\n        const text = (td.textContent || \"\").replace(/\\s+/g, \" \").trim();\n        if (!text) return;\n\n        parseCourseText(text, day, startSection, endSection, courses);\n    });\n\n    // 去重（同一课名/星期/节次/教师/教室可能重复出现）\n    const deduped = courses.filter(c => {\n        const key = `${c.name}|${c.day}|${c.startSection}|${c.endSection}|${c.teacher}|${c.position}|${c.weeks.join(',')}`;\n        if (seen.has(key)) return false;\n        seen.add(key);\n        return true;\n    });\n    return deduped.sort((a, b) => a.day - b.day || a.startSection - b.startSection || a.name.localeCompare(b.name));\n}\n\n// 保存预设作息时间（失败仅告警，不阻断课程导入）\nasync function saveTimeSlots(timeSlots) {\n    if (!timeSlots || timeSlots.length === 0) return;\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        console.log(\"JS: 作息时间保存成功\");\n    } catch (error) {\n        console.error(\"JS: 作息时间保存失败:\", error);\n    }\n}\n\nasync function runImportFlow() {\n    const alertConfirmed = await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已登录教务系统，建议在课表页面进行导入\",\n        \"好的，开始导入\"\n    );\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    window.shiguangBridge.showToast(\"正在解析课表...\");\n    try {\n        const semesterId = extractCurrentSemesterId();\n        const courses = parseCourseTableFromDom();\n        if (!courses || courses.length === 0) throw new Error(\"未在课表页面检测到有效课程，请确认课表已加载。\");\n\n        console.log(`JS: 当前学期 ${semesterId || \"未知\"}，解析到 ${courses.length} 条课程`);\n        window.shiguangBridge.showToast(`正在保存 ${courses.length} 门课程...`);\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses, null, 2));\n\n        await saveTimeSlots(MASU_TIME_SLOTS);\n\n        window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        window.shiguangBridge.showToast(`导入失败：${getErrorMessage(error)}`);\n        console.error(\"JS: Import Error:\", error);\n    }\n}\n\nrunImportFlow();\n","IMU_01":"// 内蒙古大学(imu.edu.cn)拾光课程表适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提联系开发者或者提交pr更改,这更加快速\n\n// 验证学年输入（4位数字）\nfunction validateYear(year) {\n    if (!year || year.trim().length === 0) return \"学年不能为空！\";\n    const yearRegex = /^\\d{4}$/;\n    if (!yearRegex.test(year)) return \"请输入正确的4位数字学年（例如：2025）\";\n    return false;\n}\n\n// 解析 classWeek 字符串 (支持不定长度)\nfunction parseWeekString(weekStr) {\n    let weeks = [];\n    if (!weekStr) return weeks;\n    for (let i = 0; i < weekStr.length; i++) {\n        if (weekStr[i] === '1') weeks.push(i + 1);\n    }\n    return weeks;\n}\n\n// 格式化时间 (0800 -> 08:00)\nfunction formatTime(timeStr) {\n    if (timeStr && timeStr.length === 4) {\n        return timeStr.substring(0, 2) + \":\" + timeStr.substring(2);\n    }\n    return timeStr;\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\n/**\n * 获取学年\n */\nasync function getAcademicYear() {\n    return await window.shiguangBridgePromise.showPrompt(\n        \"学年设置\",\n        \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\",\n        \"\", \n        \"validateYear\"\n    );\n}\n\n/**\n * 获取学期\n */\nasync function selectSemester() {\n    const semesters = [\"1（第一学期）\", \"2（第二学期）\"];\n    return await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\", \n        JSON.stringify(semesters),\n        -1 \n    );\n}\n\n/**\n * 网络请求和数据解析\n */\nasync function fetchAndParseJwData(academicYear, semesterIndex) {\n    try {\n        const semesterValue = parseInt(semesterIndex) + 1; \n        const endYear = parseInt(academicYear) + 1;\n        const planCode = `${academicYear}-${endYear}-${semesterValue}-2`;\n\n        window.shiguangBridge.showToast(\"正在获取教务数据...\");\n        const response = await fetch(\"https://jwxt.imu.edu.cn/student/courseSelect/thisSemesterCurriculum/ajaxStudentSchedule/callback\", {\n            \"headers\": { \"content-type\": \"application/x-www-form-urlencoded; charset=UTF-8\" },\n            \"body\": `&planCode=${planCode}`,\n            \"method\": \"POST\",\n            \"credentials\": \"include\"\n        });\n\n        const data = await response.json();\n        \n        if (!data) throw new Error(\"服务器未返回任何数据\");\n        if (!data.dateList || !Array.isArray(data.dateList)) {\n            console.error(\"教务返回数据异常:\", data);\n            throw new Error(\"未能获取到课程列表，请检查是否已登录或该学期是否有课\");\n        }\n\n        // 解析时间段\n        const timeSlots = (data.jcsjbs || []).map(item => ({\n            number: parseInt(item.jc),\n            startTime: formatTime(item.kssj),\n            endTime: formatTime(item.jssj)\n        }));\n\n        // 解析课程\n        let courses = [];\n        data.dateList.forEach(plan => {\n            // 修正：确保 selectCourseList 存在且是数组\n            if (plan && plan.selectCourseList && Array.isArray(plan.selectCourseList)) {\n                plan.selectCourseList.forEach(c => {\n                    const teacher = (c.attendClassTeacher || \"\").replace(/\\* /g, \"\").trim();\n                    if (c.timeAndPlaceList && Array.isArray(c.timeAndPlaceList)) {\n                        c.timeAndPlaceList.forEach(tp => {\n                            courses.push({\n                                name: c.courseName,\n                                teacher: teacher,\n                                position: (tp.teachingBuildingName || \"\") + (tp.classroomName || \"\"),\n                                day: tp.classDay,\n                                startSection: tp.classSessions,\n                                endSection: tp.classSessions + tp.continuingSession - 1,\n                                weeks: parseWeekString(tp.classWeek),\n                                isCustomTime: false\n                            });\n                        });\n                    }\n                });\n            }\n        });\n\n        if (courses.length === 0) {\n            throw new Error(\"该学期暂无排课数据\");\n        }\n\n        return { courses, timeSlots };\n    } catch (e) {\n        window.shiguangBridge.showToast(\"同步失败: \" + e.message);\n        return null;\n    }\n}\n\n/**\n * 保存数据到应用\n */\nasync function saveToApp(result) {\n    const courseSuccess = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(result.courses));\n    if (!courseSuccess) return false;\n\n    await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(result.timeSlots));\n    \n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\n        semesterTotalWeeks: 20 \n    }));\n    \n    return true;\n}\n\n/**\n * 流程控制\n */\nasync function runImportFlow() {\n    // 公告\n    const alertResult = await promptUserToStart();\n    if (!alertResult) return;\n\n    // 获取学年\n    const academicYear = await getAcademicYear();\n    if (academicYear === null) {\n        window.shiguangBridge.showToast(\"导入已取消\");\n        return;\n    }\n\n    // 获取学期\n    const semesterIndex = await selectSemester();\n    if (semesterIndex === null) {\n        window.shiguangBridge.showToast(\"导入已取消\");\n        return;\n    }\n\n    // 请求与解析\n    const result = await fetchAndParseJwData(academicYear, semesterIndex);\n    if (!result || result.courses.length === 0) return;\n\n    // 保存并结束\n    if (await saveToApp(result)) {\n        window.shiguangBridge.showToast(`成功导入 ${result.courses.length} 个课程时段`);\n        window.shiguangBridge.notifyTaskCompletion(); \n    }\n}\n\n// 启动\nrunImportFlow();","IMUT_01":"// 内蒙古工业大学教务系统课程导入脚本\n// 根据教务处网站内容解析课程表数据\n// 2025.11.25\n\n// ============生成时间段配置==============\n\n/**\n * 默认时段配置，来源于学校官网(2025.11.23)\n */\nconst defaultTimeSlots = [\n    { \"number\": 1, \"startTime\": \"08:00\", \"endTime\": \"08:45\" },\n    { \"number\": 2, \"startTime\": \"08:55\", \"endTime\": \"09:35\" },\n    { \"number\": 3, \"startTime\": \"10:05\", \"endTime\": \"10:50\" },\n    { \"number\": 4, \"startTime\": \"11:00\", \"endTime\": \"11:40\" },\n    { \"number\": 5, \"startTime\": \"13:30\", \"endTime\": \"14:15\" },\n    { \"number\": 6, \"startTime\": \"14:25\", \"endTime\": \"15:05\" },\n    { \"number\": 7, \"startTime\": \"15:35\", \"endTime\": \"16:20\" },\n    { \"number\": 8, \"startTime\": \"16:30\", \"endTime\": \"17:10\" },\n    { \"number\": 9, \"startTime\": \"18:00\", \"endTime\": \"18:45\" },\n    { \"number\": 10, \"startTime\": \"18:45\", \"endTime\": \"19:35\" },\n    { \"number\": 11, \"startTime\": \"19:45\", \"endTime\": \"20:30\" },\n    { \"number\": 12, \"startTime\": \"20:30\", \"endTime\": \"21:20\" }\n];\n\n/**\n * 从HTML文本中解析时段信息\n * @param {string} doc -  DOM 文档对象\n * @returns {Object} 时段信息对象\n */\nfunction parseTimeSlotsFromHTML(doc) {\n    const timeSlots = {};\n    \n    const timetable = doc.querySelector('table#timetable');\n    if (timetable) {\n        const rows = timetable.querySelectorAll('tr');\n        \n        for (let i = 1; i < rows.length; i++) { // 跳过表头行\n            const th = rows[i].querySelector('th');\n            if (th) {\n                const sectionText = th.textContent.trim();\n                \n                // 解析格式如：\"第1节\\n08:20\\n┆\\n09:05\"\n                const sectionMatch = sectionText.match(/第(\\d+)节/);\n                const timeMatch = sectionText.match(/(\\d{2}:\\d{2})/g);\n                \n                if (sectionMatch && timeMatch && timeMatch.length >= 2) {\n                    const section = parseInt(sectionMatch[1]);\n                    timeSlots[section] = {\n                        section: section,\n                        startTime: timeMatch[0],\n                        endTime: timeMatch[1]\n                    };\n                }\n            }\n        }\n    }\n    \n    if (Object.keys(timeSlots).length === 0) {\n        throw new Error('未找到时段信息表格');\n    }\n    \n    return timeSlots;\n}\n\n/**\n * 从指定网页地址异步获取HTML并解析时段信息，如果解析失败则返回默认时段\n * @param {string} url - 网页地址\n * @returns {Promise<Array<Object>>} 时段信息数组，按节次排序\n * @returns {number} .number 节次编号\n * @returns {string} .startTime 开始时间\n * @returns {string} .endTime 结束时间\n */\nasync function getTimeSlotsArray(url) {\n    try {\n        const doc = await fetchAndParseHTML(url, 'gbk');\n        \n        // 解析时段信息\n        const timeSlots = parseTimeSlotsFromHTML(doc);\n        \n        const hasValidData = Object.keys(timeSlots).length > 0 && \n                            timeSlots[1] && timeSlots[1].startTime;\n        \n        if (hasValidData) {\n            // 转换为目标格式\n            return Object.values(timeSlots).map(slot => ({\n                number: slot.section,\n                startTime: slot.startTime,\n                endTime: slot.endTime\n            })).sort((a, b) => a.number - b.number);\n        } else {\n            throw new Error('解析到的时段数据不完整');\n        }\n    } catch (error) {\n        console.error('从HTML解析时段信息失败，使用默认时段:', error.message);\n        // 使用默认时段\n        return defaultTimeSlots;\n    }\n}\n\n// ============解析课程表数据==============\n\n/**\n * 解析周数字符串\n * @param {string} weeksText - 周数字符串，支持格式：\"11周\"、\"1-13周\"、\"1-10周,11-18周\"\n * @returns {number[]} 解析后的周数数组，按升序排列\n */\nfunction parseWeeks(weeksText) {\n    if (!weeksText) return [];\n    \n    const weeks = [];\n    const text = weeksText.replace('周', '').trim();\n    \n    // 处理单个周数 \"11周\" -> [11]\n    if (/^\\d+$/.test(text)) {\n        return [parseInt(text)];\n    }\n    \n    // 处理范围 \"1-13周\" -> [1,2,3,...,13]\n    const rangeMatch = text.match(/^(\\d+)-(\\d+)$/);\n    if (rangeMatch) {\n        const start = parseInt(rangeMatch[1]);\n        const end = parseInt(rangeMatch[2]);\n        for (let i = start; i <= end; i++) {\n            weeks.push(i);\n        }\n        return weeks;\n    }\n    \n    // 处理多个范围 \"1-10周,11-18周\"\n    const ranges = text.split(',');\n    ranges.forEach(range => {\n        const singleMatch = range.match(/^(\\d+)$/);\n        if (singleMatch) {\n            weeks.push(parseInt(singleMatch[1]));\n        } else {\n            const rangeMatch = range.match(/(\\d+)-(\\d+)/);\n            if (rangeMatch) {\n                const start = parseInt(rangeMatch[1]);\n                const end = parseInt(rangeMatch[2]);\n                for (let i = start; i <= end; i++) {\n                    weeks.push(i);\n                }\n            }\n        }\n    });\n    \n    return weeks;\n}\n\n/**\n * 解析课程名称（去除<<>>）\n * @param {*} courseText - 原始课程名称文本\n * @returns {string} 解析后的课程名称\n */\nfunction parseCourseName(courseText) {\n    let name = courseText\n        .replace(/<</g, '')  // 直接移除 <<\n        .replace(/>>/g, '')  // 直接移除 >>\n        .split(';')[0];\n    \n    return name.trim();\n}\n\nfunction parseSingleCourse(lines, day, timeSlot) {\n    \n    const courseNameMatch = lines[0].match(/<<(.*?)>>/);\n\n    if (!courseNameMatch) {\n        return null;\n    }\n\n    let courseData = {\n        name: parseCourseName(courseNameMatch[1]),\n        position: lines[1] || '',\n        day: day,\n        startSection: timeSlot,\n        endSection: timeSlot,\n        weeks: []\n    };\n\n    // 单门课程示例\n    // ['<<离散数学导论>>;1', '教C', '贾老师', '1-15周', '讲课']\n    // 无教师名课程示例：\n    // ['<<体育选项课(一)>>;11', '操   场', '2-18周', '讲课']\n\n    if (lines.length > 4) {\n        // 有教师名课程\n        courseData.teacher = lines[2].replace(/,$/, '');\n        courseData.weeks = parseWeeks(lines[3]);\n    } else {\n        // 无教师名课程\n        courseData.teacher = '';\n        courseData.weeks = parseWeeks(lines[2]);\n    }\n\n    return courseData;\n}\n\n/**\n * 解析包含多个课程的课程信息块。\n *\n * @param {Array<string>} lines - 包含课程信息的字符串数组，每个元素表示一行数据。\n * @param {string} day - 表示课程所在的星期几。\n * @param {string} timeSlot - 表示课程所在的时间段。\n * @returns {Array<Object>} 返回一个包含课程信息的数组，每个课程信息是一个对象。\n */\nfunction parseMultipleCourses(lines, day, timeSlot) {\n    const courses = [];\n    let currentCourseLines = [];\n\n    // 示例：\n    // ['<<工程训练C>>;11', '格物楼D', '刘老师', '1-10周', '讲课', '<<数据结构与算法>>;1', '教C', '秦老师', '11-18周', '讲课']\n\n    for (let i = 0; i < lines.length; i++) {\n        if (lines[i].includes('<<') && currentCourseLines.length > 0) {\n            const courseData = parseSingleCourse(currentCourseLines, day, timeSlot);\n            if (courseData) {\n                courses.push(courseData);\n            }\n            currentCourseLines = [];\n        }\n        currentCourseLines.push(lines[i]);\n    }\n\n    if (currentCourseLines.length > 0) {\n\n        const courseData = parseSingleCourse(currentCourseLines, day, timeSlot);\n        if (courseData) {\n            courses.push(courseData);\n        }\n    }\n\n    return courses;\n}\n\n/**\n * 处理课程区块信息，解析出课程的详细信息。\n *\n * @param {string} block - 包含课程信息的HTML字符串，使用`<br>`分隔每行。\n * @param {string} day - 表示课程所在的星期几。\n * @param {string} timeSlot - 表示课程所在的时间段。\n * @returns {Array<Object>} 返回一个包含课程信息的数组，每个课程信息是一个对象。\n */\nfunction processCourseBlock(block, day, timeSlot) {\n    const lines = block.split('<br>').map(line => \n        line.replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim()\n    ).filter(line => line);\n\n    const courses = [];\n\n    const courseCount = lines.filter(line => line.includes('<<')).length;\n\n    if (courseCount > 1) {\n        courses.push(...parseMultipleCourses(lines, day, timeSlot));\n    } else if (lines.length >= 4) {\n        const courseData = parseSingleCourse(lines, day, timeSlot);\n        if (courseData) {\n            courses.push(courseData);\n        }\n    }\n\n    return courses;\n}\n\n/**\n * 将HTML课程表转换为标准格式的课程数据\n * @param {string} url - 网页地址\n * @returns {Promise<Array<Object>>} 课程表数据数组\n * @returns {string} .name 课程名称\n * @returns {string} .teacher 授课教师\n * @returns {string} .position 上课地点\n * @returns {number} .day 星期几 (1=周一, 7=周日)\n * @returns {number} .startSection 开始节次\n * @returns {number} .endSection 结束节次\n * @returns {number[]} .weeks 上课周次数组\n */\nasync function convertToTargetFormat(url) {\n    try {\n        const doc = await fetchAndParseHTML(url, 'gbk');\n        \n        const timetable = [];\n        const rows = doc.querySelectorAll('#timetable tr');\n        \n        // 跳过表头行\n        for (let rowIndex = 1; rowIndex < rows.length; rowIndex++) {\n            const row = rows[rowIndex];\n            const timeSlot = rowIndex; // 第1-13节对应rowIndex 1-13\n            const cells = row.querySelectorAll('td');\n            \n            for (let day = 1; day <= cells.length; day++) {\n                const cell = cells[day - 1];\n                const content = cell.innerHTML.trim();\n                \n                if (content && content !== '&nbsp;') {\n\n                    // 分割每个课程块（一个单元格可能有多个课程）\n                    const courseBlocks = content.split(/<br>\\s*<br>/);\n                    \n                    courseBlocks.forEach(block => {\n                        if (block.trim()) {\n\n                            const courses = processCourseBlock(block, day, timeSlot);\n\n                            for (const course of courses) {\n                                timetable.push(course);\n\n                            }\n                        }\n                    });\n                }\n            }\n        }\n\n        return timetable;\n        \n    } catch (error) {\n\n        return []; // 返回空数组作为错误回退\n    }\n}\n\n/**\n * 合并连续的课程信息。\n * 合并条件：同一天、同一课程名称、同一位置、同一教师、同一周次且时间连续\n *\n * @param {Array<Object>} courses - 课程信息数组\n * @returns {Array<Object>} 返回合并后的课程信息数组\n */\nfunction mergeContinuousCourses(courses) {\n    // 按所有关键属性进行分组\n    const grouped = {};\n    \n    courses.forEach(course => {\n        // 使用周次数组的字符串表示作为分组键的一部分\n        const weeksKey = JSON.stringify(course.weeks.sort((a, b) => a - b));\n        const key = `${course.day}-${course.name}-${course.position}-${course.teacher || '未知'}-${weeksKey}`;\n        if (!grouped[key]) {\n            grouped[key] = [];\n        }\n        grouped[key].push(course);\n    });\n    \n    const result = [];\n    \n    // 处理每个分组\n    Object.values(grouped).forEach(group => {\n        // 按开始节次排序\n        group.sort((a, b) => a.startSection - b.startSection);\n        \n        let currentCourse = null;\n        \n        group.forEach(course => {\n            if (!currentCourse) {\n                // 第一个课程\n                currentCourse = { ...course };\n            } else if (currentCourse.endSection + 1 === course.startSection) {\n                // 时间连续，合并\n                currentCourse.endSection = course.endSection;\n            } else {\n                // 时间不连续，将当前课程加入结果，开始新的课程\n                result.push(currentCourse);\n                currentCourse = { ...course };\n            }\n        });\n        \n        // 将最后一个课程加入结果\n        if (currentCourse) {\n            result.push(currentCourse);\n        }\n    });\n    \n    return result;\n}\n\n// ============配置获取==============\n\n/*\n    * 异步获取学年学期信息\n    * @returns {Promise<Object>} 包含 studentid, year, term的对象\n    * studentid: 标识ID\n    * year: 学年，例如 45 (2025-1980)\n    * term: 学期，1=春季，2=夏季，3=秋季\n    */\nasync function getSemesterInfo(url) {\n    try {\n        const doc = await fetchAndParseHTML(url, 'gbk');\n        \n        // 查找 CTRT 元素\n        const ctrtElement = doc.querySelector('eduaffair\\\\:CTRT');\n        \n        if (!ctrtElement) {\n            throw new Error('未找到 CTRT 元素');\n        }\n        \n        // 提取参数\n        const params = {\n            studentid: ctrtElement.getAttribute('studentid'),\n            year: ctrtElement.getAttribute('year'),\n            term: ctrtElement.getAttribute('term'),\n        };\n        \n        return params;\n        \n    } catch (error) {\n        console.error('提取参数时出错:', error);\n        return null;\n    }\n}\n\n/**\n * 获取指定学年和学期的最大周数值。\n *\n * @param {string} yearid - 学年的ID，例如 \"2023\"。\n * @param {string} termid - 学期的ID，例如 \"1\" 或 \"2\"。\n * @returns {Promise<number>} 返回一个Promise，解析为最大周数值。\n */\nasync function getMaxWeekValue(yearid, termid) {\n    const url = `http://jw.imut.edu.cn/academic/manager/coursearrange/studentWeeklyTimetable.do?yearid=${yearid}&termid=${termid}`;\n    try {\n        const doc = await fetchAndParseHTML(url, 'gbk');\n        \n        // 查找whichWeek选择框\n        const weekSelect = doc.querySelector('select[name=\"whichWeek\"]');\n        \n        if (!weekSelect) {\n            throw new Error('未找到周次选择框');\n        }\n\n        // 获取所有option的value并转换为数字\n        const weekOptions = Array.from(weekSelect.querySelectorAll('option'));\n        const weekValues = weekOptions\n            .map(option => parseInt(option.value))\n            .filter(value => !isNaN(value) && value !== 0); // 过滤掉非数字和空值\n\n        if (weekValues.length === 0) {\n            throw new Error('未找到有效的周数值');\n        }\n        const maxWeek = Math.max(...weekValues);\n\n        return maxWeek;\n        \n    } catch (error) {\n        console.error('获取最大周数时出错:', error);\n        throw error;\n    }\n}\n\n/*    * 异步获取第一个课程日期\n    * 调用此函数需要先设定学年和学期，否则可能获取不到正确的数据\n    *\n    * @param {string} yearid - 学年ID\n    * @param {string} termid - 学期ID\n    * @returns {Promise<string>} 第一个课程日期字符串，格式如 \"2025-09-01\"\n**/\nasync function getFirstCourseDate(yearid, termid) {\n    const url = 'http://jw.imut.edu.cn/academic/manager/coursearrange/studentWeeklyTimetable.do';\n    \n    try {\n        // 构建POST请求的表单数据\n        const formData = new URLSearchParams();\n        formData.append('yearid', yearid);\n        formData.append('termid', termid);\n        formData.append('whichWeek', '1');  // 固定请求第一周\n        \n        const doc = await fetch(url, {\n            method: 'POST',\n            headers: {\n                'Content-Type': 'application/x-www-form-urlencoded',\n                'Referer': `http://jw.imut.edu.cn/academic/manager/coursearrange/studentWeeklyTimetable.do?yearid=${yearid}&termid=${termid}`\n            },\n            body: formData.toString(),\n            credentials: 'include'  // 包含cookie\n        })\n        .then(response => {\n            if (!response.ok) {\n                throw new Error(`HTTP error! status: ${response.status}`);\n            }\n            return response.text();\n        })\n        .then(text => {\n            // 将文本解析为DOM文档\n            const parser = new DOMParser();\n            return parser.parseFromString(text, 'text/html');\n        });\n        \n        // 查找第一个课程日期\n        const firstDateTd = doc.querySelector('td[name=\"td0\"]');\n        \n        if (firstDateTd) {\n            const firstCourseDate = firstDateTd.textContent.trim();\n            return firstCourseDate;\n        } else {\n            return null;\n        }\n        \n    } catch (error) {\n        console.error('获取数据失败:', error);\n        return null;\n    }\n}\n\n// 设置当前学年和学期\nasync function setCurrentYearAndTerm(yearid, termid) {\n    const url = `http://jw.imut.edu.cn/academic/student/currcourse/currcourse.jsdo?year=${yearid}&term=${termid}`\n    try {\n        const doc = await fetchAndParseHTML(url, 'gbk');\n        const text = doc.querySelector('#title td div').textContent.trim();\n        const match = text.match(/(\\d{4})(春|夏|秋)/);\n        if (match) {\n            const year = match[1];\n            const season = match[2];\n\n            let curtermid = (season === '春') ? 1 : (season === '夏') ? 2 : 3;\n            let curyearid = String(parseInt(year) - 1980);\n\n            if (curtermid == termid && curyearid == yearid) {\n                return true;\n            }\n        }\n        return false;\n    } catch (error) {\n        console.error('设置当前学年学期失败:', error);\n        return false;\n    }\n}\n\n// ====================== 辅助函数 ======================\n\n// 请求与解析HTML的通用函数\nasync function fetchAndParseHTML(url, encoding = 'gbk') {\n    const response = await fetch(url);\n    if (!response.ok) {\n        throw new Error(`HTTP错误! 状态码: ${response.status}`);\n    }\n    const buffer = await response.arrayBuffer();\n    const decoder = new TextDecoder(encoding);\n    const htmlText = decoder.decode(buffer);\n    const parser = new DOMParser();\n    return parser.parseFromString(htmlText, 'text/html');\n}\n\n// 日期格式验证函数\nfunction validateDateFormat(dateString) {\n    const regex = /^\\d{4}-\\d{2}-\\d{2}$/;\n    if (regex.test(dateString)) {\n        return false;\n    } else {\n        return \"请输入正确的日期格式，示例：2025-09-01\";\n    }\n}\n\n// 弹出日期确认对话框\nasync function setStartDate(suggestedDate) {\n    const dateSelection = await window.shiguangBridgePromise.showPrompt(\n        \"请确认学期起始日期\",\n        `此日期来自您此学期第一节课日期，如有误，请修改（格式：YYYY-MM-DD）：`,\n        suggestedDate || \"\",\n        \"validateDateFormat\"\n    );\n    return dateSelection;\n}\n\n// 验证学年输入函数\nfunction validateYearInput(input) {\n    if (/^[0-9]{4}$/.test(input)) {\n        return false; // 验证通过\n    } else {\n        return \"请输入四位数字的学年！\"; // 验证失败\n    }\n}\n\n\n// 选择学年\nasync function getAcademicYear(currentYear) {\n    const yearSelection = await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\", \n        \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\",\n        parseInt(currentYear) + 1980, \n        \"validateYearInput\" // 传入全局函数名\n    );\n    const academicYear = String(parseInt(yearSelection) - 1980);\n    return academicYear;\n}\n\n// 选择学期\nasync function selectTerms() {\n    const terms = [\"春（第二学期）\", \"夏\", \"秋（第一学期）\"];\n    const termIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"请选择学期\",\n        JSON.stringify(terms),\n        -1\n    );\n    const term = termIndex + 1; // 转换为1,2,3\n\n    return term;\n}\n\n// 弹出修改学年和学期对话框\nasync function setYearAndTerm(currentYear, currentTerm) {\n    const confirmed = await window.shiguangBridgePromise.showAlert(\n        \"请确认学年和学期\",\n        `当前学年为 ${parseInt(currentYear) + 1980} 年，学期为 ${currentTerm === '3' ? '秋（第一学期）' : currentTerm === '1' ? '春（第二学期）' : '夏'}。是否需要修改？`,\n        \"我要修改\"\n    );\n    if (!confirmed) {\n        window.shiguangBridge.showToast(\"使用默认学年和学期进行导入。\");\n        return false;\n    }\n    return true;\n}\n\n// ====================== 导入课程主流程 ======================\n\nasync function runImportFlow() {\n\n    window.shiguangBridge.showToast(\"即将开始导入课表，请稍候...\");\n\n    // 获取学年学期信息\n    const semesterInfo = await getSemesterInfo(\"http://jw.imut.edu.cn/academic/student/currcourse/currcourse.jsdo\");\n    if (!semesterInfo) {\n        window.shiguangBridge.showToast(\"获取学生信息失败，请重试！\");\n        return;\n    }\n    currentYear = semesterInfo.year; // 当前年份 - 1980\n    currentTerm = semesterInfo.term; // 当前学期\n\n    // 自定义年份学期\n    const needModify = await setYearAndTerm(currentYear, currentTerm);\n    if (needModify) {\n        currentYear = await getAcademicYear(currentYear);\n        currentTerm = await selectTerms();\n        window.shiguangBridge.showToast(`当前年份与学期已修改为：${parseInt(currentYear) + 1980} 年，学期 ${currentTerm === 2 ? '夏' : currentTerm === 1 ? '春（第二学期）' : '秋（第一学期）'}`);\n    }\n\n    // 设置当前学年和学期\n    const setResult = await setCurrentYearAndTerm(currentYear, currentTerm);\n    if (!setResult) {\n        window.shiguangBridge.showToast(\"设置学年和学期失败！\");\n        return;\n    }\n\n    // 构造课程表URL\n    const timetableUrl = `http://jw.imut.edu.cn/academic/manager/coursearrange/showTimetable.do?id=${semesterInfo.studentid}&yearid=${currentYear}&termid=${currentTerm}&timetableType=STUDENT&sectionType=BASE`;\n\n    // 获取时段数据\n    const timeSlots = await getTimeSlotsArray(timetableUrl);\n    if (!timeSlots || timeSlots.length === 0) {\n        window.shiguangBridge.showToast(\"获取时间段信息失败，使用默认时间段！\");\n    }\n\n    // 获取并转换课程表数据\n    let courses = await convertToTargetFormat(timetableUrl);\n    if (courses.length === 0) {\n        window.shiguangBridge.showToast(\"获取课程表数据失败，请重试！\");\n        return;\n    }\n\n    // 合并连续课程\n    courses = mergeContinuousCourses(courses)\n\n    // 获取第一个课程日期\n    let firstCourseDate = null;\n    try {\n        firstCourseDate = await getFirstCourseDate(currentYear, currentTerm);\n    } catch (err) {\n        console.warn(\"获取第一个课程日期失败:\", err);\n    }\n\n    // 用户确认起始日期\n    try {\n        firstCourseDate = await setStartDate(firstCourseDate);\n    } catch (err) {\n        console.error(\"用户取消了日期输入:\", err);\n        window.shiguangBridge.showToast(\"未输入起始日期。\");\n    }\n\n    // 获取最大周数\n    let maxWeeks = 20; // 默认最大周数\n    try {\n        maxWeeks = await getMaxWeekValue(currentYear, currentTerm);\n    } catch (err) {\n        console.warn(\"获取最大周数失败，使用默认值 20\");\n    }\n\n    // 配置课表配置\n    const coursesConfig = {\n        semesterStartDate: firstCourseDate,\n        semesterTotalWeeks: maxWeeks,\n    };\n\n    // 将数据传递给Android端\n\n    // 提交课程数据\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        const coursesCount = courses.length;\n        window.shiguangBridge.showToast(`课程导入成功，共导入 ${coursesCount} 门课程！`);\n    } catch (err) {\n        console.error(\"课程导入失败:\", err);\n        window.shiguangBridge.showToast(\"课程导入失败：\" + err.message);\n        return;\n    }\n\n    // 提交时间段数据\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        window.shiguangBridge.showToast(\"时间段导入成功！\");\n    } catch (err) {\n        console.error(\"时间段导入失败:\", err);\n        window.shiguangBridge.showToast(\"时间段导入失败：\" + err.message);\n        return;\n    }\n\n    // 提交课表配置\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(coursesConfig));\n        window.shiguangBridge.showToast(\"课表配置保存成功！\");\n    } catch (err) {\n        console.error(\"课表配置保存失败:\", err);\n        window.shiguangBridge.showToast(\"课表配置保存失败：\" + err.message);\n        return;\n    }\n\n    // 通知任务完成\n    console.log(\"JS：整个导入流程执行完毕并成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n\n}\n\nrunImportFlow();","NUIST_01":"// 南京信息工程大学教务系统（jwxt.nuist.edu.cn）拾光课程表适配脚本\n\nfunction parseWeeks(skzc) {\n    const value = String(skzc || \"\");\n    const weeks = [];\n    for (let i = 0; i < value.length; i++) {\n        if (value[i] === \"1\") weeks.push(i + 1);\n    }\n    return weeks;\n}\n\n// jc.do 不可用时的 NUIST 默认作息（已由接口确认）。\nconst DEFAULT_TIME_SLOTS = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:55\", endTime: \"09:40\" },\n    { number: 3, startTime: \"10:10\", endTime: \"10:55\" },\n    { number: 4, startTime: \"11:05\", endTime: \"11:50\" },\n    { number: 5, startTime: \"13:45\", endTime: \"14:30\" },\n    { number: 6, startTime: \"14:40\", endTime: \"15:25\" },\n    { number: 7, startTime: \"15:55\", endTime: \"16:40\" },\n    { number: 8, startTime: \"16:50\", endTime: \"17:35\" },\n    { number: 9, startTime: \"18:45\", endTime: \"19:30\" },\n    { number: 10, startTime: \"19:40\", endTime: \"20:25\" },\n    { number: 11, startTime: \"20:35\", endTime: \"21:20\" },\n    { number: 12, startTime: \"21:25\", endTime: \"22:00\" }\n];\n\nfunction getErrorMessage(error) {\n    if (error && typeof error.message === \"string\" && error.message.trim()) return error.message;\n    if (typeof error === \"string\" && error.trim()) return error;\n    try {\n        const serialized = JSON.stringify(error);\n        if (serialized && serialized !== \"{}\") return serialized;\n    } catch (_) {\n        // Ignore serialization failures and use the generic fallback below.\n    }\n    return \"未知错误\";\n}\n\nfunction parsePosition(row) {\n    const campus = String(row.XXXQDM_DISPLAY || \"\").trim();\n    const room = String(row.JASMC || \"\").trim();\n    if (campus && room) return `${room}（${campus}）`;\n    return room || campus || \"待定\";\n}\n\nfunction parseCourse(row) {\n    const day = Number(row.SKXQ);\n    const startSection = Number(row.KSJC);\n    const endSection = Number(row.JSJC);\n    const weeks = parseWeeks(row.SKZC);\n    if (!row.KCM || !day || day < 1 || day > 7 || !startSection || !endSection ||\n        startSection > endSection || weeks.length === 0) return null;\n\n    return {\n        name: String(row.KCM).trim(),\n        teacher: String(row.SKJS || \"\").split(/[\\\\/、,，]/)[0].trim() || \"未知\",\n        position: parsePosition(row),\n        day,\n        startSection,\n        endSection,\n        weeks\n    };\n}\n\nasync function fetchCourses(xnxqdm) {\n    const response = await fetch(\"/jwapp/sys/wdkb/modules/xskcb/cxxszhxqkb.do\", {\n        method: \"POST\",\n        headers: {\n            \"Content-Type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        body: `XNXQDM=${encodeURIComponent(xnxqdm)}`,\n        credentials: \"include\"\n    });\n    if (!response.ok) throw new Error(`课表接口请求失败（HTTP ${response.status}）`);\n\n    const payload = await response.json();\n    const table = payload && payload.datas && payload.datas.cxxszhxqkb;\n    if (!table) throw new Error(\"教务系统返回数据格式异常。\");\n    if (table.extParams && Number(table.extParams.code) !== 1) {\n        throw new Error(table.extParams.msg || \"教务系统未发布该学期课表。\");\n    }\n\n    const rows = Array.isArray(table.rows) ? table.rows : [];\n    const courses = rows.map(parseCourse).filter(Boolean);\n    if (courses.length === 0) throw new Error(\"未找到包含有效时间的课程。\");\n    courses.sort((a, b) => a.day - b.day || a.startSection - b.startSection || a.name.localeCompare(b.name));\n    return { courses, xnxqdm };\n}\n\nasync function fetchCurrentSemester() {\n    const response = await fetch(\"/jwapp/sys/wdkb/modules/jshkcb/dqxnxq.do\", {\n        method: \"POST\",\n        headers: {\n            \"Content-Type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        body: \"\",\n        credentials: \"include\"\n    });\n    if (!response.ok) throw new Error(`当前学期接口请求失败（HTTP ${response.status}）`);\n    const payload = await response.json();\n    const rows = payload && payload.datas && payload.datas.dqxnxq && payload.datas.dqxnxq.rows;\n    const term = Array.isArray(rows) && rows.length > 0 ? rows[0] : null;\n    if (!term || !term.DM) throw new Error(\"未获取到当前学期信息。\");\n    return {\n        code: String(term.DM),\n        name: String(term.MC || term.DM)\n    };\n}\n\nasync function fetchSemesterList() {\n    const response = await fetch(\"/jwapp/sys/wdkb/modules/jshkcb/xnxqcx.do\", {\n        method: \"POST\",\n        headers: {\n            \"Content-Type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        body: \"*order=-DM\",\n        credentials: \"include\"\n    });\n    if (!response.ok) throw new Error(`学期列表接口请求失败（HTTP ${response.status}）`);\n    const payload = await response.json();\n    const rows = payload && payload.datas && payload.datas.xnxqcx && payload.datas.xnxqcx.rows;\n    if (!Array.isArray(rows)) throw new Error(\"学期列表返回数据格式异常。\");\n    return rows.filter(item => item && item.DM).map(item => ({\n        code: String(item.DM),\n        name: String(item.MC || item.DM),\n        year: item.XNDM,\n        term: item.XQDM\n    }));\n}\n\nasync function selectSemester() {\n    let semesters;\n    try {\n        semesters = await fetchSemesterList();\n    } catch (error) {\n        window.shiguangBridge.showToast(`获取学期列表失败：${getErrorMessage(error)}`);\n        return null;\n    }\n    if (semesters.length === 0) {\n        window.shiguangBridge.showToast(\"未查询到可用学期。\");\n        return null;\n    }\n\n    let currentCode = null;\n    try {\n        currentCode = (await fetchCurrentSemester()).code;\n    } catch (error) {\n        console.warn(\"获取当前学期失败，将不设置默认选项\", error);\n    }\n\n    const visibleSemesters = semesters.slice(0, 10);\n    const defaultIndex = currentCode\n        ? visibleSemesters.findIndex(item => item.code === currentCode)\n        : -1;\n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"请选择学期\",\n        JSON.stringify(visibleSemesters.map(item => item.name)),\n        defaultIndex\n    );\n    if (selectedIndex === null || selectedIndex < 0 || !visibleSemesters[selectedIndex]) return null;\n    return visibleSemesters[selectedIndex];\n}\n\nasync function fetchTimeSlots() {\n    const response = await fetch(\"/jwapp/sys/wdkb/modules/jshkcb/jc.do\", {\n        method: \"POST\",\n        headers: {\n            \"Content-Type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        body: \"\",\n        credentials: \"include\"\n    });\n    if (!response.ok) throw new Error(`节次时间接口请求失败（HTTP ${response.status}）`);\n    const payload = await response.json();\n    const rows = payload && payload.datas && payload.datas.jc && payload.datas.jc.rows;\n    if (!Array.isArray(rows) || rows.length === 0) return [];\n    return rows.map(row => ({\n        number: Number(row.DM),\n        startTime: String(row.KSSJ || \"\"),\n        endTime: String(row.JSSJ || \"\")\n    })).filter(slot => slot.number > 0 && slot.startTime && slot.endTime)\n      .sort((a, b) => a.number - b.number);\n}\n\nasync function fetchSemesterConfig(xnxqdm) {\n    const parts = String(xnxqdm || \"\").split(\"-\");\n    if (parts.length < 3) return { semesterStartDate: null, semesterTotalWeeks: 20 };\n    const response = await fetch(\"/jwapp/sys/wdkb/modules/jshkcb/cxjcs.do\", {\n        method: \"POST\",\n        headers: {\n            \"Content-Type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        body: `XN=${encodeURIComponent(`${parts[0]}-${parts[1]}`)}&XQ=${encodeURIComponent(parts[2])}`,\n        credentials: \"include\"\n    });\n    if (!response.ok) throw new Error(`学期配置接口请求失败（HTTP ${response.status}）`);\n    const payload = await response.json();\n    const rows = payload && payload.datas && payload.datas.cxjcs && payload.datas.cxjcs.rows;\n    const row = Array.isArray(rows) ? rows[0] : null;\n    if (!row) return { semesterStartDate: null, semesterTotalWeeks: 20 };\n    const rawDate = row.XQKSRQ || row.XQKSRQ_DISPLAY || row.KSRQ;\n    const startDate = rawDate ? String(rawDate).split(/[ T]/)[0] : null;\n    const totalWeeks = Number.parseInt(row.ZZC || row.ZCZ || row.ZC, 10);\n    return {\n        semesterStartDate: /^\\d{4}-\\d{2}-\\d{2}$/.test(startDate || \"\") ? startDate : null,\n        semesterTotalWeeks: Number.isFinite(totalWeeks) && totalWeeks > 0 ? totalWeeks : 20\n    };\n}\n\nasync function runImportFlow() {\n    try {\n        const confirmed = await window.shiguangBridgePromise.showAlert(\n            \"南京信息工程大学课表导入\",\n            \"请先在当前教务页面完成登录，再开始导入。\",\n            \"开始导入\"\n        );\n        if (!confirmed) return;\n\n        const semester = await selectSemester();\n        if (!semester) {\n            window.shiguangBridge.showToast(\"导入已取消。\");\n            return;\n        }\n        window.shiguangBridge.showToast(`已选择学期：${semester.name}`);\n        const result = await fetchCourses(semester.code);\n        let semesterConfig = { semesterStartDate: null, semesterTotalWeeks: 20 };\n        try {\n            semesterConfig = await fetchSemesterConfig(semester.code);\n        } catch (error) {\n            console.warn(\"获取学期配置失败，将使用默认配置\", error);\n            window.shiguangBridge.showToast(\"开学日期获取失败，已使用默认配置继续导入。\");\n        }\n        let timeSlots = DEFAULT_TIME_SLOTS;\n        try {\n            const fetchedTimeSlots = await fetchTimeSlots();\n            if (fetchedTimeSlots.length > 0) timeSlots = fetchedTimeSlots;\n        } catch (error) {\n            console.warn(\"NUIST time slot request failed, using defaults\", error);\n            window.shiguangBridge.showToast(\"作息时间获取失败，已使用默认时间继续导入。\");\n        }\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\n            ...semesterConfig,\n            defaultClassDuration: 45,\n            defaultBreakDuration: 10,\n            firstDayOfWeek: 1\n        }));\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(result.courses));\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        window.shiguangBridge.showToast(`成功导入 ${result.courses.length} 条课程记录（${result.xnxqdm}）。`);\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        window.shiguangBridge.showToast(`导入失败：${getErrorMessage(error)}`);\n        console.error(\"NUIST adapter error\", error);\n    }\n}\n\nrunImportFlow();\n","NJCIT":"// 南京信息职业技术学院教务适配\n// 注意：本校教务页面加载的 zftal-ui 的 jquery.extends.contact-min.js\n// 会污染以下原型方法，本文件一律不使用：\n//   Array.prototype.filter / some —— 回调实参变成 (下标, 元素, 数组)\n//   Array.prototype.every        —— 恒为 true\n//   String.prototype.trim        —— 删除所有空白而非仅首尾\n// 参考 resources/SCNU/scnu.js、resources/UJS/ujs_zhengfang_v9.0.js 的同类处理。\n\nconst text = value => String(value == null ? '': value).replace(/^\\s+|\\s+$/g, '');\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统（无需打开课表页面），点击开始后将弹窗选择学期。\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function fetchAcademicOptions() {\n    const url = \"/jwglxt/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151&layout=default\"\n\n    try {\n        const response = await fetch(url, {\n            method : \"GET\",\n            credentials: \"include\"\n        }) \n\n        if (!response.ok) {\n            return null;\n        }\n\n        const htmlText = await response.text();\n        const doc = new DOMParser().parseFromString(htmlText, \"text/html\");\n\n        const parseOptions = (selector) => {\n            const list = [];\n            let defaultIdx = 0;\n\n            for (const opt of doc.querySelectorAll(`${selector} option`)) {\n                const value = opt.getAttribute(\"value\") || opt.value;\n                if (!value) continue;\n\n                const selected = opt.hasAttribute(\"selected\") || opt.selected;\n                if (selected) defaultIdx = list.length;\n                \n                list.push({value, text: text(opt.textContent), selected});\n            }\n\n            return {list, defaultIdx};\n        }\n        const {list: allYears, defaultIdx: yearIdx} = parseOptions(\"#xnm\");\n        const {list: semesterOptions, defaultIdx: defaultSemesterIndex } = parseOptions(\"#xqm\");\n\n        if (allYears.length == 0 || semesterOptions.length == 0) return null;\n\n        const start = Math.max(0, yearIdx - 2);\n        const end = Math.min(allYears.length, yearIdx + 3);\n\n        const yearOptions = allYears.slice(start, end);\n\n        return {\n            yearOptions,\n            semesterOptions,\n            defaultYearIndex: yearIdx - start,\n            defaultSemesterIndex\n        }\n    } catch(error) {\n        console.error(error.message);\n        return null;\n    }\n}\n\n\nasync function selectAcademicYearAndSemester()  {\n    const optionsData = await fetchAcademicOptions();\n        \n    if (!optionsData) {\n        window.shiguangBridge.showToast(\"从教务系统读取学年学期失败，请确保登录状态。\");\n        return null;\n    }\n\n    const { yearOptions, semesterOptions, defaultYearIndex, defaultSemesterIndex } = optionsData;\n    \n    const yearTexts = yearOptions.map(item => item.text);\n    const yearIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学年\",\n        JSON.stringify(yearTexts),\n        defaultYearIndex\n    );\n\n    if (yearIndex === null || yearIndex === -1) {\n        return null;\n    }\n    const selectedYearCode = yearOptions[yearIndex].value;\n\n    const semesterTexts = semesterOptions.map(item => item.text); \n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesterTexts),\n        defaultSemesterIndex\n    );\n\n    if (semesterIndex === null || semesterIndex === -1) return null;\n    const selectedSemesterCode = semesterOptions[semesterIndex].value;\n\n    return {\n        academicYear: selectedYearCode,\n        semesterCode: selectedSemesterCode\n    };\n}\n\nasync function fetchSemesterStartDate(academicYear, semesterCode) {\n    const url = \"/jwglxt/kbcx/xskbcxZccx_cxZcByXnxq.html?gnmkdm=N2154\";\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}`;\n    try {\n        const response = await fetch(url, {\n            method : \"POST\",\n            headers : {\n                \"Content-Type\" :\"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: requestBody,\n            credentials: \"include\"\n        });\n\n        if (!response.ok) {\n            return null;\n        }\n\n        const json = await response.json();\n        if (Array.isArray(json) &&  json.length > 0) {\n            const firstWeekObj = json.find(item => String(item.zs) == \"1\" || String(item.zsmc) == \"1\") || json[0];\n            const totalWeeksInt = json.length;\n\n            if (firstWeekObj.rq) {\n                const startDateStr = firstWeekObj.rq.split('/')[0];\n                if (/^\\d{4}-\\d{2}-\\d{2}$/.test(startDateStr)) {\n                    return {\n                        semesterStartDate : startDateStr,\n                        semesterTotalWeeks: totalWeeksInt\n                    }\n                }\n            }\n        }\n\n    } catch(e) {\n        console.error(e);\n    }\n    return null;\n}\n\nasync function fetchTimesSlots(academicYear, semesterCode) {\n    const url = \"/jwglxt/kbcx/xskbcx_cxRjc.html?gnmkdm=N2151\";\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}&xqh_id=01`;\n    try {\n        const response = await fetch(url, {\n            method : \"POST\",\n            headers : {\n                \"Content-Type\" :\"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: requestBody,\n            credentials: \"include\"\n        });\n\n        if (!response.ok) {\n            return null;\n        }\n\n        const json = await response.json();\n        if (!Array.isArray(json)) {\n            return null;\n        }\n        \n        const timeSlots = [];\n        for (const item of json) {\n            if (!item.jcmc || !item.qssj || !item.jssj) {\n                continue;\n            }\n\n            timeSlots.push({\n                number: Number(item.jcmc),\n                startTime: item.qssj.substring(0, 5),\n                endTime: item.jssj.substring(0, 5)\n            })\n        }\n        timeSlots.sort((a, b) => a.number - b.number);\n            \n        return timeSlots.length > 0 ? timeSlots : null;\n    } catch (e) {\n        console.error(e);\n        return null;\n    }\n}\n\n/**\n * 节次与周次合并去重函数\n * @param {Array<Object>} courses 原始解析课程数组\n * @returns {Array<Object>} 合并去重后的课程数组\n */\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    // 1. 深拷贝并规范周次数据，过滤无效项\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n\n    // 阶段 1：合并连续节次与完全重复记录（前提：名称、教师、地点、星期、周次一致）\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n               (a.startSection || 0) - (b.startSection || 0);\n    });\n\n    const step1Merged = [];\n    let current = list[0];\n\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n\n        const isSameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n\n        if (isSameCourseAndWeeks && isContinuous) {\n            // 节次连续：延长结束节次 (如 1-2 节 + 3-4 节 -> 1-4 节)\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            // 完全重复：跳过\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    // 阶段 2：合并同节次的周次（前提：名称、教师、地点、星期、开始/结束节次一致）\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               (a.startSection || 0) - (b.startSection || 0) ||\n               (a.endSection || 0) - (b.endSection || 0);\n    });\n\n    const step2Merged = [];\n    let cur = step1Merged[0];\n\n    for (let i = 1; i < step1Merged.length; i++) {\n        const nxt = step1Merged[i];\n\n        const isSameCourseAndSection =\n            cur.name === nxt.name &&\n            cur.teacher === nxt.teacher &&\n            cur.position === nxt.position &&\n            cur.day === nxt.day &&\n            cur.startSection === nxt.startSection &&\n            cur.endSection === nxt.endSection;\n\n        if (isSameCourseAndSection) {\n            // 周次合并去重 (如 1-8 周 + 9-16 周 -> 1-16 周)\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(cur);\n            cur = nxt;\n        }\n    }\n    step2Merged.push(cur);\n\n    return step2Merged;\n}\n\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    const weekSets = weekStr.split(',');\n    let weeks = [];\n\n    for (const set of weekSets) {\n        const trimmedSet = text(set);\n\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周/);\n\n        let start = 0;\n        let end = 0;\n        let processed = false;\n\n        if (rangeMatch) {\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) {\n            start = end = Number(singleMatch[1]);\n            processed = true;\n        }\n        \n        if (processed) {\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue;\n                if (isDouble && w % 2 !== 0) continue;\n                weeks.push(w);\n            }\n        }\n    }\n\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\nfunction parseCourseJsonData(jsonData) {\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        return [];\n    }\n\n    const rawCourseList = jsonData.kbList;\n    let initalCourseList = [];\n\n    for (const rawCourse of rawCourseList) {\n        if (!rawCourse.kcmc || !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) {\n            continue;\n        }\n\n        \n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]);\n        const day = Number(rawCourse.xqj);\n        const weeks = parseWeeks(rawCourse.zcd);\n\n        initalCourseList.push({\n            name: text(rawCourse.kcmc),\n            teacher: text(rawCourse.xm),\n            position: text(rawCourse.cdmc || \"未排地点\"),\n            day: day,\n            startSection: startSection,\n            endSection: endSection,\n            weeks: weeks\n        })\n    }\n\n    return mergeAndDistinctCourses(initalCourseList);\n}\n\n\nasync function fetchAndParseCourses(academicYear, semesterCode) {\n    const url = \"/jwglxt/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151\";\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck`;\n    \n    try {\n        const [courseResponse, semesterStartDate, fetchedTimeSlots] = await Promise.all(\n            [\n                fetch(url, {\n                method : \"POST\",\n                headers : {\n                    \"Content-Type\" :\"application/x-www-form-urlencoded;charset=UTF-8\",\n                    \"x-requested-with\": \"XMLHttpRequest\"\n                },\n                body: requestBody,\n                credentials: \"include\"\n                }),\n                fetchSemesterStartDate(academicYear, semesterCode),\n                fetchTimesSlots(academicYear, semesterCode)\n            ]\n        );\n\n        if (courseResponse.ok) {\n            const json = await courseResponse.json();\n            const courseData = parseCourseJsonData(json);\n\n            return {\n                courses: courseData,\n                config: semesterStartDate,\n                timeSlots: fetchedTimeSlots\n            }\n        }\n    } catch(e) {\n        console.error(e);\n    }\n\n    return null;\n}\n\n\n\n// 课程是必须的，保存失败就没有导入的意义，抛异常交给导入流程中断\nasync function saveCourses(courses) {\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n    } catch (error) {\n        throw new Error(\"课程保存失败：\" + error.message);\n    }\n}\n\n// 作息和学期配置不是必须的，失败只返回 false，由导入流程汇总提示\nasync function saveTimeSlots(timeSlots) {\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        return true;\n    } catch (error) {\n        console.error(error);\n        return false;\n    }\n}\n\nasync function saveConfig(config) {\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        return true;\n    } catch (error) {\n        console.error(error);\n        return false;\n    }\n}\n\n(async function runImportFlow() {\n\n    const confirmed = await promptUserToStart();\n    if (!confirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    const selection = await selectAcademicYearAndSemester();\n    if (!selection) {\n        window.shiguangBridge.showToast(\"未选择学年学期，导入流程终止。\");\n        return;\n    }\n\n    const { academicYear, semesterCode } = selection;\n\n    const result = await fetchAndParseCourses(academicYear, semesterCode);\n    if (!result || !result.courses || result.courses.length === 0) {\n        window.shiguangBridge.showToast(\"未获取到有效课程，导入终止！\");\n        return;\n    }\n    const { courses, config, timeSlots } = result;\n\n    try {\n        await saveCourses(courses);\n    } catch(error) {\n        window.shiguangBridge.showToast(error.message);\n        return;\n    }\n\n    // 记下没保存成功的部分，最后一起提示，避免提示互相覆盖\n    const failed = [];\n\n    if (config) {\n        const saved = await saveConfig(config);\n        if (!saved) failed.push(\"学期配置\");\n    }\n\n    if (timeSlots) {\n        const saved = await saveTimeSlots(timeSlots);\n        if (!saved) failed.push(\"作息\");\n    }\n\n    window.shiguangBridge.showToast(\n        failed.length\n            ? `成功导入 ${courses.length} 条排课记录，但${failed.join(\"、\")}未保存成功`\n            : `成功导入 ${courses.length} 条排课记录！`\n    );\n\n    window.shiguangBridge.notifyTaskCompletion();\n})();","NJTECH":"// 南京工业大学(njtech.edu.cn)拾光课程表适配脚本\n// 基于正方教务系统接口适配\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提issues或者提交pr更改,这更加快速\n\n/**\n * 解析周次字符串，处理单双周和周次范围。\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    const weekSets = weekStr.split(',');\n    let weeks = [];\n\n    for (const set of weekSets) {\n        const trimmedSet = set.trim();\n\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周/); // 匹配以数字周结束的\n\n        let start = 0;\n        let end = 0;\n        let processed = false;\n\n        if (rangeMatch) { // 范围, 如 \"1-5周\"\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) { // 单个周, 如 \"6周\"\n            start = end = Number(singleMatch[1]);\n            processed = true;\n        }\n        \n        if (processed) {\n            // 确定单双周\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue; // 单周跳过偶数\n                if (isDouble && w % 2 !== 0) continue; // 双周跳过奇数\n                weeks.push(w);\n            }\n        }\n    }\n\n    // 去重并排序\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 解析 API 返回的 JSON 数据。\n */\nfunction parseJsonData(jsonData) {\n    console.log(\"JS: parseJsonData 正在解析 JSON 数据...\");\n    \n    // 检查JSON结构：新的数据在 kbList 字段中\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        console.warn(\"JS: JSON 数据结构错误或缺少 kbList 字段。\");\n        return []; \n    }\n\n    const rawCourseList = jsonData.kbList;\n    const finalCourseList = [];\n\n    for (const rawCourse of rawCourseList) {\n        // 关键字段检查： kcmc(课名), xm(教师), cdmc(教室), xqj(星期), jcs(节次范围), zcd(周次描述)\n        if (!rawCourse.kcmc || !rawCourse.xm || !rawCourse.cdmc || \n            !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) {\n            continue;\n        }\n\n        const weeksArray = parseWeeks(rawCourse.zcd);\n        \n        // 周次有效性检查\n        if (weeksArray.length === 0) {\n            continue;\n        }\n        \n        // 解析节次范围，例如 \"1-2\"\n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]); \n\n        const day = Number(rawCourse.xqj); // xqj: 星期几 (周一为1, 周日为7)\n        \n        // 数字有效性检查\n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) || day < 1 || day > 7 || startSection > endSection) {\n            // console.warn(`JS: 课程 ${rawCourse.kcmc} 星期或节次数据无效，跳过。`);\n            continue;\n        }\n\n        finalCourseList.push({\n            name: rawCourse.kcmc.trim(),\n            teacher: rawCourse.xm.trim(),\n            position: rawCourse.cdmc.trim(),\n            day: day, \n            startSection: startSection,\n            endSection: endSection, \n            weeks: weeksArray\n        });\n    }\n\n    finalCourseList.sort((a, b) =>\n        a.day - b.day ||\n        a.startSection - b.startSection ||\n        a.name.localeCompare(b.name)\n    );\n    \n    console.log(`JS: JSON 数据解析完成，共找到 ${finalCourseList.length} 门课程。`);\n    return finalCourseList;\n}\n\n\n\nfunction validateYearInput(input) {\n    console.log(\"JS: validateYearInput 被调用，输入: \" + input);\n    if (/^[0-9]{4}$/.test(input)) {\n        console.log(\"JS: validateYearInput 验证通过。\");\n        return false;\n    } else {\n        console.log(\"JS: validateYearInput 验证失败。\");\n        return \"请输入四位数字的学年！\";\n    }\n}\n\nasync function promptUserToStart() {\n    console.log(\"JS: 流程开始：显示公告。\");\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function getAcademicYear() {\n    const currentYear = new Date().getFullYear().toString();\n    console.log(\"JS: 提示用户输入学年。\");\n    return await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\",\n        \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\",\n        currentYear,\n        \"validateYearInput\"\n    );\n}\n\nasync function selectSemester() {\n    const semesters = [\"第一学期\", \"第二学期\"];\n    console.log(\"JS: 提示用户选择学期。\");\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesters),\n        -1\n    );\n    return semesterIndex;\n}\n\n/**\n * 将选择索引转换为 API 所需的学期码。\n */\nfunction getSemesterCode(semesterIndex) {\n    // semesterIndex 3 (第一学期), 12 (第二学期)\n    return semesterIndex === 0 ? \"3\" : \"12\";\n}\n\n\n/**\n * 请求和解析课程数据\n */\nasync function fetchAndParseCourses(academicYear, semesterIndex) {\n    const semesterCode = getSemesterCode(semesterIndex);\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`;\n    const targetUrl = \"https://jwgl.njtech.edu.cn/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151\";\n\n    try {\n        const response = await fetch(targetUrl, {\n            method: \"POST\",\n            headers: { \n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\" \n            },\n            body: requestBody,\n            credentials: \"include\"\n        });\n\n        if (response.ok) {\n            const jsonText = await response.text();\n            const jsonData = JSON.parse(jsonText);\n            if (jsonData && jsonData.kbList) {\n                const parsedCourses = parseJsonData(jsonData);\n                if (parsedCourses.length > 0) {\n                    return {\n                        courses: parsedCourses,\n                        config: {\n                            semesterStartDate: null,\n                            semesterTotalWeeks: 20\n                        }\n                    };\n                }\n            }\n        }\n    } catch (e) {\n        console.error(`Request failed: ${targetUrl}`, e);\n    }\n\n    window.shiguangBridge.showToast(\"未能获取课表数据，请检查网络环境或登录状态。\");\n    return null;\n}\n\nasync function saveCourses(parsedCourses) {\n    window.shiguangBridge.showToast(`正在保存 ${parsedCourses.length} 门课程...`);\n    console.log(`JS: 尝试保存 ${parsedCourses.length} 门课程...`);\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses, null, 2));\n        console.log(\"JS: 课程保存成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        console.error('JS: Save Courses Error:', error);\n        return false;\n    }\n}\n\n// 统一作息时间\nconst TimeSlots = [\n    { number: 1, startTime: \"08:10\", endTime: \"08:55\" },\n    { number: 2, startTime: \"09:05\", endTime: \"09:50\" },\n    { number: 3, startTime: \"10:20\", endTime: \"11:05\" },\n    { number: 4, startTime: \"11:15\", endTime: \"12:00\" },\n    { number: 5, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 6, startTime: \"14:55\", endTime: \"15:40\" },\n    { number: 7, startTime: \"16:10\", endTime: \"16:55\" },\n    { number: 8, startTime: \"17:05\", endTime: \"17:50\" },\n    { number: 9, startTime: \"19:00\", \"endTime\": \"19:45\" },\n    { number: 10, startTime: \"19:55\", \"endTime\": \"20:40\" },\n];\n\nasync function importPresetTimeSlots(timeSlots) {\n    console.log(`JS: 准备导入 ${timeSlots.length} 个预设时间段。`);\n\n    if (timeSlots.length > 0) {\n        window.shiguangBridge.showToast(`正在导入 ${timeSlots.length} 个预设时间段...`);\n        try {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n            window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n            console.log(\"JS: 预设时间段导入成功。\");\n        } catch (error) {\n            window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n            console.error('JS: Save Time Slots Error:', error);\n        }\n    } else {\n        window.shiguangBridge.showToast(\"警告：时间段为空，未导入时间段信息。\");\n        console.warn(\"JS: 警告：传入时间段为空，未导入时间段信息。\");\n    }\n}\n\n\nasync function runImportFlow() {\n\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        console.log(\"JS: 用户取消了导入流程。\");\n        return;\n    }\n\n    const academicYear = await getAcademicYear();\n    if (academicYear === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        console.log(\"JS: 获取学年失败/取消，流程终止。\");\n        return;\n    }\n    console.log(`JS: 已选择学年: ${academicYear}`);\n\n\n    const semesterIndex = await selectSemester();\n    if (semesterIndex === null || semesterIndex === -1) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        console.log(\"JS: 选择学期失败/取消，流程终止。\");\n        return;\n    }\n    console.log(`JS: 已选择学期索引: ${semesterIndex}`);\n\n    const result = await fetchAndParseCourses(academicYear, semesterIndex);\n    if (result === null) {\n        console.log(\"JS: 课程获取或解析失败，流程终止。\");\n        return;\n    }\n    const { courses, config } = result;\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        console.log(\"JS: 课程保存失败，流程终止。\");\n        return;\n    }\n    \n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        window.shiguangBridge.showToast(`课表配置更新成功！总周数：${config.semesterTotalWeeks}周。`);\n    } catch (error) {\n        window.shiguangBridge.showToast(`课表配置保存失败: ${error.message}`);\n        console.error('JS: Save Config Error:', error);\n    }\n\n\n    await importPresetTimeSlots(TimeSlots);\n\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    console.log(\"JS: 整个导入流程执行完毕并成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();","NIIT":"// 文件: courseImportApi.js\n// 南京工业职业技术大学(jwxt.niit.edu.cn)「我的课表」API 方案适配脚本（金智教育 WIS 平台）\n// 全自动：自动确定当前学期，直接调用教务后端接口获取课表并导入，无任何人工输入。\n\nconst SCHOOL = {\n    api: \"https://jwxt.niit.edu.cn/jwapp/sys/wdkb/modules/xskcb/cxxszhxqkb.do\"\n};\n\n// 本校作息时间表（11 节）\nconst PRESET_TIME_SLOTS = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:55\", endTime: \"09:40\" },\n    { number: 3, startTime: \"10:00\", endTime: \"10:45\" },\n    { number: 4, startTime: \"10:55\", endTime: \"11:40\" },\n    { number: 5, startTime: \"13:30\", endTime: \"14:15\" },\n    { number: 6, startTime: \"14:25\", endTime: \"15:10\" },\n    { number: 7, startTime: \"15:30\", endTime: \"16:15\" },\n    { number: 8, startTime: \"16:25\", endTime: \"17:10\" },\n    { number: 9, startTime: \"18:15\", endTime: \"19:00\" },\n    { number: 10, startTime: \"19:10\", endTime: \"19:55\" },\n    { number: 11, startTime: \"20:05\", endTime: \"20:50\" }\n];\n\n// 自动确定当前学期，优先取页面学期标签，其次取当前日期\nfunction currentTerm() {\n    try {\n        var t = document.querySelector(\"#dqxnxq2\");\n        if (t && t.getAttribute(\"value\")) return t.getAttribute(\"value\");\n    } catch (e) { }\n    var y = new Date().getFullYear();\n    return (new Date().getMonth() >= 1 && new Date().getMonth() <= 6)\n        ? (y - 1) + \"-\" + y + \"-2\"\n        : y + \"-\" + (y + 1) + \"-1\";\n}\n\n// POST 请求教务接口（复用登录 Cookie）\nasync function fetchCourseRows() {\n    var resp = await fetch(SCHOOL.api, {\n        method: \"POST\",\n        headers: {\n            \"content-type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n            \"x-requested-with\": \"XMLHttpRequest\"\n        },\n        body: \"XNXQDM=\" + currentTerm(),\n        credentials: \"include\"\n    });\n    return (await resp.json()).datas;\n}\n\n// 从 datas 中定位课程 rows（键名可能不同，做兜底）\nfunction pluckRows(datas) {\n    for (var k in datas) {\n        var v = datas[k];\n        if (v && Array.isArray(v.rows)) return v.rows;\n        if (Array.isArray(v)) return v;\n    }\n    return [];\n}\n\n// 解析一条排课；周次串\"111...000...\"逐位为1即在第i+1周上课\nfunction parseCourse(r) {\n    var day = parseInt(r.SKXQ, 10);\n    var startSection = parseInt(r.KSJC, 10);\n    var endSection = parseInt(r.JSJC, 10);\n    if (!r.KCM || isNaN(day) || isNaN(startSection) || isNaN(endSection)) return null;\n    var weeks = [];\n    (r.SKZC || \"\").split(\"\").forEach(function (c, i) { if (c === \"1\") weeks.push(i + 1); });\n    if (!weeks.length) return null;\n    var name = r.KCM;\n    var teacher = (r.SKJS || \"待定\").split(\"/\")[0];\n    var position = r.JASMC || \"待定\";\n    // 去重 key：星期+节次+课程+教师+教室；并合并同 key 的周次\n    var key = day + \"|\" + startSection + \"|\" + endSection + \"|\" + name + \"|\" + teacher + \"|\" + position;\n    return { key: key, course: { name: name, teacher: teacher, position: position, day: day, startSection: startSection, endSection: endSection, weeks: weeks } };\n}\n\n// 主流程\n(async function () {\n    if (!(window.shiguangBridgePromise && window.shiguangBridgePromise.saveImportedCourses)) return;\n\n    var datas = await fetchCourseRows();\n    var rows = pluckRows(datas);\n    console.log(\"[课程API导入] 接口返回行数:\", rows.length, rows);\n    var index = {}, courses = [];\n\n    for (var i = 0; i < rows.length; i++) {\n        var p = parseCourse(rows[i]);\n        if (!p) continue; // 只识别完整学期课表，不做调课/补课/停课过滤\n        if (index[p.key] === undefined) {\n            index[p.key] = courses.length;\n            courses.push(p.course);\n        } else {\n            var ex = courses[index[p.key]];\n            p.course.weeks.forEach(function (w) { if (ex.weeks.indexOf(w) === -1) ex.weeks.push(w); });\n        }\n    }\n    courses.forEach(function (c) { c.weeks.sort(function (a, b) { return a - b; }); });\n\n    if (!courses.length) return;\n    var totalWeeks = 0;\n    for (var j = 0; j < rows.length; j++) totalWeeks = Math.max(totalWeeks, String(rows[j].SKZC || \"\").length);\n\n    await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(PRESET_TIME_SLOTS));\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({ semesterStartDate: null, semesterTotalWeeks: totalWeeks || 20, firstDayOfWeek: 1 }));\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n    try { window.shiguangBridge.notifyTaskCompletion(); } catch (e) { }\n})();","NJNU":"// 南京师范大学(njnu.edu.cn)拾光课程表适配脚本\n// 由本校开发者适配，可联系开发者修改\n// 出现问题请提联系开发者或者提交pr更改,这更加快速\n\n// 核心工具函数：数据验证 \nfunction validateYearInput(input) {\n    if (/^[0-9]{4}$/.test(input) && parseInt(input) > 2000) {\n        return false;\n    } else {\n        return \"请输入有效的四位数字学年（例如：2025）！\";\n    }\n}\n\n/**\n * 辅助函数：解析周次字符串 \"111000...\" 为数字数组 [1, 2, 3]\n */\nfunction parseWeeksFromSkzc(skzc) {\n    const weeks = [];\n    const rawSkzc = skzc || '';\n    for (let i = 0; i < rawSkzc.length; i++) {\n        if (rawSkzc[i] === '1') {\n            weeks.push(Number(i + 1)); \n        }\n    }\n    return weeks;\n}\n\n\n/**\n * 将教务系统的课程数据转换成 CourseJsonModel 结构\n */\nfunction parseSingleCourse(rawCourse) {\n    const courseName = rawCourse.KCM;\n    const teacherName = rawCourse.SKJS ? rawCourse.SKJS.split('/')[0] : '';\n    const position = rawCourse.JASMC;\n    const day = rawCourse.SKXQ; \n    const startSection = rawCourse.KSJC; \n    const endSection = rawCourse.JSJC; \n    const weeks = parseWeeksFromSkzc(rawCourse.SKZC);\n\n    if (!courseName || !day || !startSection || !endSection || weeks.length === 0) {\n        return null;\n    }\n\n    const course = {\n        \"name\": courseName,\n        \"teacher\": teacherName,\n        \"position\": position || '待定',\n        \"day\": parseInt(day),\n        \"startSection\": parseInt(startSection),\n        \"endSection\": parseInt(endSection),\n        \"weeks\": weeks\n    };\n    \n    course._kbId = rawCourse.KBID; \n    course._day = course.day;\n    course._startSection = course.startSection;\n    course._endSection = course.endSection;\n    \n    return course;\n}\n/**\n * 获取学期开始日期函数\n */\nasync function fetchSemesterStartDate(academicYear, semesterCode) {\n    try {\n        const response = await fetch(\"http://ehallapp.nnu.edu.cn/jwapp/sys/wdkb/modules/jshkcb/cxjcs.do\", {\n            method: \"POST\",\n            headers: {\n                \"accept\": \"application/json, text/javascript, */*; q=0.01\",\n                \"content-type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: `XN=${academicYear}-${parseInt(academicYear) + 1}&XQ=${semesterCode}`,\n            credentials: \"include\"\n        });\n\n        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);\n\n        const data = await response.json();\n        \n        // 安全检查：确保 rows 存在\n        if (!data?.datas?.cxjcs?.rows || data.datas.cxjcs.rows.length === 0) {\n            return null;\n        }\n\n        const xqksrq = data.datas.cxjcs.rows[0].XQKSRQ; \n        // 本校获取日期格式通常为 \"2025-09-01 00:00:00\"的形式\n        \n        // 直接切割字符串，不使用 new Date() 避免时区导致的日期减一\n        const formattedDate = xqksrq.split(' ')[0]; \n        console.log('确认学期开始日期:', formattedDate);\n        \n        return formattedDate;\n        \n    } catch (error) {\n        console.error('获取日期失败:', error);\n        window.shiguangBridge.showToast(\"获取错误，需要手动设置开学日期\");\n        return null;\n    }\n}\n/**\n * 将调课数据应用到已解析的课程列表上\n */\nfunction applyCourseChanges(parsedCourses, rawChanges) {\n    let successCount = 0;\n    \n    for (const change of rawChanges) {\n        const kbID = change.KBID; \n        const originalTeacher = change.YSKJS ? change.YSKJS.split('/')[0] : '';\n        \n        const weeksToRemove = parseWeeksFromSkzc(change.SKZC); \n        \n        let changeApplied = false; \n\n        const affectedOriginalCourses = parsedCourses.filter(c => \n            c._kbId === kbID && \n            c._day === parseInt(change.SKXQ) && \n            c._startSection === parseInt(change.KSJC) &&\n            c._endSection === parseInt(change.JSJC)\n        );\n        \n        if (affectedOriginalCourses.length === 0) {\n            continue;\n        }\n\n        if (weeksToRemove.length > 0) {\n            affectedOriginalCourses.forEach(originalCourse => {\n                const beforeLength = originalCourse.weeks.length;\n                originalCourse.weeks = originalCourse.weeks.filter(w => !weeksToRemove.includes(w));\n                if (originalCourse.weeks.length < beforeLength) {\n                    changeApplied = true;\n                }\n            });\n        }\n        \n        const isTimeLocationChange = (change.TKLXDM === '01' || change.TKLXDM === '03'); \n\n        if (isTimeLocationChange && change.XSKZC && change.XSKXQ && change.XKSJC && change.XJSJC) {\n            const newWeeks = parseWeeksFromSkzc(change.XSKZC);\n            \n            if (newWeeks.length > 0) {\n                const newCourse = {\n                    \"name\": change.KCM,\n                    \"teacher\": change.XSKJS ? change.XSKJS.split('/')[0] : originalTeacher, \n                    \"position\": change.XJASMC || change.JASMC || '待定',\n                    \"day\": parseInt(change.XSKXQ),\n                    \"startSection\": parseInt(change.XKSJC),\n                    \"endSection\": parseInt(change.XJSJC),\n                    \"weeks\": newWeeks,\n                    \"_kbId\": kbID, \n                    \"_day\": parseInt(change.XSKXQ),\n                    \"_startSection\": parseInt(change.XKSJC),\n                    \"_endSection\": parseInt(change.XJSJC)\n                };\n                parsedCourses.push(newCourse);\n                changeApplied = true; \n            }\n        } \n        \n        if (changeApplied) {\n            successCount++; \n        }\n    }\n    \n    if (successCount > 0) {\n        window.shiguangBridge.showToast(`已应用 ${successCount} 条调课/停课变更，获得实际课表。`);\n    }\n    \n    return parsedCourses.map(c => {\n        delete c._kbId;\n        delete c._day;\n        delete c._startSection;\n        delete c._endSection;\n        return c;\n    }).filter(c => c.weeks.length > 0); \n}\n\n\nasync function promptUserToStart() {\n    const confirmed = await window.shiguangBridgePromise.showAlert(\n        \"重要通知：南京师范大学课表导入\",\n        \"本流程将通过教务系统接口获取您的个人课表。\\n重要提示:\\n导入前请确保您已在浏览器中成功登录教务系统，且未关闭登录窗口，确认当前页面有显示你想要获取的学期的课表，不然获取不了数据\",\n        \"好的，开始导入\"\n    );\n    if (!confirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return null;\n    }\n    return true;\n}\n\nasync function getAcademicYear() {\n    const currentYear = new Date().getFullYear();\n    const yearSelection = await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\",\n        \"请输入要导入课程的学年（例如 2025-2026学年，无论你是上学期还是下学期，都请输入2025哦）:\",\n        String(currentYear), \n        \"validateYearInput\"\n    );\n    return yearSelection;\n}\n\nasync function selectSemester() {\n    const semesters = [\"1 (秋季学期/上学期)\", \"2 (春季学期/下学期)\"];\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesters),\n        0\n    );\n    \n    if (semesterIndex === null) return null;\n    return String(semesterIndex + 1);\n}\n// 数据获取和解析部分\n\nasync function fetchAndParseCourses(academicYear, semesterCode) {\n    const XNXQDM = `${academicYear}-${parseInt(academicYear) + 1}-${semesterCode}`;\n    const headers = {\n        \"content-type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n        \"x-requested-with\": \"XMLHttpRequest\",\n    };\n    \n    // 获取个人课表数据\n    const courseUrl = \"http://ehallapp.nnu.edu.cn/jwapp/sys/wdkb/modules/xskcb/cxxszhxqkb.do\";\n    const courseBody = `XNXQDM=${XNXQDM}&`;\n    let rawCourseData;\n    try {\n        const response = await fetch(courseUrl, { \"headers\": headers, \"body\": courseBody, \"method\": \"POST\", \"credentials\": \"include\" });\n        rawCourseData = JSON.parse(await response.text());\n    } catch (e) {\n        window.shiguangBridge.showToast(\"请求课表 API 失败，请检查网络和登录状态,以及是否跳转到课表页面\");\n        console.error(\"Fetch Course Error:\", e);\n        return null;\n    }\n\n    const rawCourses = rawCourseData?.datas?.cxxszhxqkb?.rows || [];\n    if (rawCourses.length === 0) {\n        window.shiguangBridge.showToast(\"该学期未查询到您的课程数据。\");\n        return null;\n    }\n    let parsedCourses = rawCourses.map(c => parseSingleCourse(c)).filter(c => c !== null);\n    \n    const changeUrl = \"http://ehallapp.nnu.edu.cn/jwapp/sys/wdkb/modules/xskcb/xsdkkc.do\";\n    const changeBody = `XNXQDM=${XNXQDM}&*order=-SQSJ`; \n    let rawChangeData;\n    try {\n        const response = await fetch(changeUrl, { \"headers\": headers, \"body\": changeBody, \"method\": \"POST\", \"credentials\": \"include\" });\n        rawChangeData = JSON.parse(await response.text());\n    } catch (e) {\n        window.shiguangBridge.showToast(\"请求调课 API 失败，将使用未调整的课表数据。\");\n        console.error(\"Fetch Change Error:\", e);\n    }\n    \n    const rawChanges = rawChangeData?.datas?.xsdkkc?.rows || [];\n    \n    // 应用调课变更\n    if (rawChanges.length > 0) {\n        parsedCourses = applyCourseChanges(parsedCourses, rawChanges);\n    }\n    \n    // 课表配置数据\n    const semesterStartDate = await fetchSemesterStartDate(academicYear, semesterCode);\n    const courseConfig = {\n        semesterTotalWeeks: 20,\n        semesterStartDate: semesterStartDate\n    };\n\n    return {\n        courses: parsedCourses,\n        config: courseConfig\n    };\n}\n\n\nasync function saveCourses(parsedCourses) {\n    if (parsedCourses.length === 0) {\n        window.shiguangBridge.showToast(\"没有有效的课程数据可供保存。\");\n        return true;\n    }\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses));\n        window.shiguangBridge.showToast(`成功导入 ${parsedCourses.length} 门课程！`);\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`保存课程数据失败: ${error.message}`);\n        return false;\n    }\n}\n\n/**\n * 导入预设时间段数据\n */\nasync function importPresetTimeSlots() {\n    window.shiguangBridge.showToast(\"正在导入预设节次时间...\");\n    \n    const presetTimeSlots = [\n        { \"number\": 1, \"startTime\": \"08:00\", \"endTime\": \"08:40\" },\n        { \"number\": 2, \"startTime\": \"08:45\", \"endTime\": \"09:25\" },\n        { \"number\": 3, \"startTime\": \"09:40\", \"endTime\": \"10:20\" },\n        { \"number\": 4, \"startTime\": \"10:35\", \"endTime\": \"11:15\" },\n        { \"number\": 5, \"startTime\": \"11:20\", \"endTime\": \"12:00\" },\n        { \"number\": 6, \"startTime\": \"13:30\", \"endTime\": \"14:10\" },\n        { \"number\": 7, \"startTime\": \"14:15\", \"endTime\": \"14:55\" },\n        { \"number\": 8, \"startTime\": \"15:10\", \"endTime\": \"15:50\" },\n        { \"number\": 9, \"startTime\": \"15:55\", \"endTime\": \"16:35\" },\n        { \"number\": 10, \"startTime\": \"18:30\", \"endTime\": \"19:10\" },\n        { \"number\": 11, \"startTime\": \"19:20\", \"endTime\": \"20:00\" },\n        { \"number\": 12, \"startTime\": \"20:10\", \"endTime\": \"20:50\" }\n    ];\n\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(presetTimeSlots));\n        window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n        return true; \n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n        return false; \n    }\n}\n\nasync function saveConfig(configData) {\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(configData));\n        window.shiguangBridge.showToast(\"课表配置更新成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"保存配置失败: \" + error.message);\n        return false;\n    }\n}\n\n// 主流程入口\n\nasync function runImportFlow() {\n    window.shiguangBridge.showToast(\"南京师范大学课程导入流程启动...\");\n\n    // 1. 公告和前置检查。\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) return;\n    \n    // 2. 获取用户输入参数 (学年和学期)。\n    const academicYear = await getAcademicYear();\n    if (academicYear === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n    \n    const semesterCode = await selectSemester();\n    if (semesterCode === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n\n    // 3. 导入预设时间段\n    await importPresetTimeSlots();\n\n    // 4. 网络请求和数据解析。\n    const courseData = await fetchAndParseCourses(academicYear, semesterCode);\n    if (courseData === null) return;\n\n    // 5. 保存配置数据\n    const configSaveResult = await saveConfig(courseData.config);\n    if (!configSaveResult) return;\n\n    // 6. 课程数据保存。\n    const saveResult = await saveCourses(courseData.courses);\n    if (!saveResult) return;\n\n    // 7. 流程完全成功，发送结束信号。\n    window.shiguangBridge.showToast(\"所有任务已完成！课表导入成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\n// 启动导入流程\nrunImportFlow();","NJFU_01":"const STANDARD_TIME_SLOTS = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:55\", endTime: \"09:40\" },\n    { number: 3, startTime: \"10:00\", endTime: \"10:45\" },\n    { number: 4, startTime: \"10:55\", endTime: \"11:40\" },\n    { number: 5, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 6, startTime: \"14:50\", endTime: \"15:35\" },\n    { number: 7, startTime: \"15:55\", endTime: \"16:40\" },\n    { number: 8, startTime: \"16:45\", endTime: \"17:30\" },\n    { number: 9, startTime: \"18:30\", endTime: \"19:15\" },\n    { number: 10, startTime: \"19:20\", endTime: \"20:05\" },\n    { number: 11, startTime: \"20:10\", endTime: \"20:55\" }\n];\n\nconst CAMPUS_TIME_SLOTS = {\n    \"新庄校区\": STANDARD_TIME_SLOTS,\n    \"淮安校区\": STANDARD_TIME_SLOTS,\n    \"白马校区\": [\n        { number: 1, startTime: \"08:30\", endTime: \"09:15\" },\n        { number: 2, startTime: \"09:20\", endTime: \"10:05\" },\n        { number: 3, startTime: \"10:25\", endTime: \"11:10\" },\n        { number: 4, startTime: \"11:15\", endTime: \"12:00\" },\n        { number: 5, startTime: \"14:00\", endTime: \"14:45\" },\n        { number: 6, startTime: \"14:50\", endTime: \"15:35\" },\n        { number: 7, startTime: \"15:55\", endTime: \"16:40\" },\n        { number: 8, startTime: \"16:45\", endTime: \"17:30\" },\n        { number: 9, startTime: \"18:30\", endTime: \"19:15\" },\n        { number: 10, startTime: \"19:20\", endTime: \"20:05\" },\n        { number: 11, startTime: \"20:10\", endTime: \"20:55\" }\n    ]\n};\n\nconst CAMPUS_KEYWORDS = [\n    { campus: \"淮安校区\", keywords: [\"淮安校区\"] },\n    { campus: \"白马校区\", keywords: [\"白马校区\"] },\n    { campus: \"新庄校区\", keywords: [\"新庄校区\"] }\n];\n\nfunction cleanPosition(position) {\n    return String(position || \"\")\n        .replace(/^(新庄校区|淮安校区|白马校区)/, \"\")\n        .replace(/[（(]\\d+人[)）]\\s*$/g, \"\")\n        .trim() || \"待定\";\n}\n\nfunction showToast(message) {\n    if (typeof window.shiguangBridge !== \"undefined\") {\n        window.shiguangBridge.showToast(message);\n    } else {\n        console.log(message);\n    }\n}\n\nfunction parseWeeks(rawText) {\n    if (!rawText) return [];\n\n    const weekPart = String(rawText)\n        .replace(/\\s+/g, \"\")\n        .replace(/\\(周\\).*/, \"\")\n        .replace(/周次[:：]?/g, \"\");\n\n    const weeks = new Set();\n    weekPart.split(/[,，]/).forEach((segment) => {\n        if (!segment) return;\n\n        const isOdd = segment.includes(\"单\");\n        const isEven = segment.includes(\"双\");\n        const cleaned = segment.replace(/[单双周]/g, \"\");\n        const match = cleaned.match(/^(\\d+)(?:-(\\d+))?$/);\n        if (!match) return;\n\n        const start = Number(match[1]);\n        const end = Number(match[2] || match[1]);\n        for (let week = start; week <= end; week++) {\n            if (isOdd && week % 2 === 0) continue;\n            if (isEven && week % 2 !== 0) continue;\n            weeks.add(week);\n        }\n    });\n\n    return Array.from(weeks).sort((a, b) => a - b);\n}\n\nfunction detectCampusOrNull(...texts) {\n    const text = texts\n        .filter(Boolean)\n        .map((item) => String(item))\n        .join(\" \");\n\n    for (const item of CAMPUS_KEYWORDS) {\n        if (item.keywords.some((keyword) => text.includes(keyword))) {\n            return item.campus;\n        }\n    }\n    return null;\n}\n\nfunction readLineTexts(div) {\n    const cloned = div.cloneNode(true);\n    cloned.querySelectorAll(\".item-box\").forEach((node) => node.remove());\n    return cloned.innerHTML\n        .split(/<br\\s*\\/?>/i)\n        .map((line) => line.replace(/<[^>]+>/g, \"\").trim())\n        .filter(Boolean);\n}\n\nfunction extractCourseName(lines) {\n    const metadataPrefixes = [\"通知单编号\", \"班级\", \"备注\"];\n    const metadataKeywords = [\"周\", \"节\", \"教师\", \"教室\", \"校区\"];\n    const nameLines = [];\n\n    for (const line of lines) {\n        if (!line) continue;\n        if (metadataPrefixes.some((prefix) => line.startsWith(prefix))) break;\n        if (metadataKeywords.some((keyword) => line.includes(keyword))) break;\n        nameLines.push(line);\n    }\n\n    return nameLines.join(\"\").trim();\n}\n\nfunction parseCourseBlock(blockHtml, fallbackDay) {\n    const tempDiv = document.createElement(\"div\");\n    tempDiv.innerHTML = blockHtml;\n\n    const lines = readLineTexts(tempDiv);\n    if (!lines.length) return null;\n\n    let name = extractCourseName(lines);\n    const teacher = tempDiv.querySelector('font[title=\"教师\"]')?.innerText.trim() || \"未知\";\n    if (teacher && name && name !== teacher && name.endsWith(teacher)) {\n        name = name.slice(0, -teacher.length).trim();\n    }\n    const positionRaw = tempDiv.querySelector('font[title=\"教室\"]')?.innerText.trim() || \"待定\";\n    const building = tempDiv.querySelector('font[title=\"教学楼\"]')?.innerText.trim()\n        || tempDiv.querySelector('font[name=\"jxlmc\"]')?.innerText.trim()\n        || \"\";\n    const position = cleanPosition(positionRaw);\n    const timeText = tempDiv.querySelector('font[title=\"周次(节次)\"]')?.innerText.trim() || \"\";\n    if (!timeText) return null;\n\n    const weekMatch = timeText.match(/^(.*?)\\(周\\)/);\n    const sectionMatch = timeText.match(/\\[(\\d+)(?:-(\\d+))?(?:-(\\d+))?(?:-(\\d+))?节\\]/);\n    const weeks = parseWeeks(weekMatch ? weekMatch[1] : timeText);\n\n    let startSection = 0;\n    let endSection = 0;\n    if (sectionMatch) {\n        const values = sectionMatch.slice(1).filter(Boolean).map(Number);\n        startSection = values[0];\n        endSection = values[values.length - 1];\n    }\n\n    if (!name || !weeks.length || !startSection || !endSection) return null;\n\n    return {\n        name,\n        teacher,\n        position,\n        day: fallbackDay,\n        startSection,\n        endSection,\n        weeks,\n        campus: detectCampusOrNull(positionRaw, building, lines.join(\" \"))\n    };\n}\n\nfunction extractCoursesFromDoc(doc) {\n    const table = doc.getElementById(\"timetable\");\n    if (!table) {\n        throw new Error(\"未获取到课表表格，请确认当前账号已登录教务系统。\");\n    }\n\n    const rows = Array.from(table.querySelectorAll(\"tr\")).slice(1, -1);\n    const courses = [];\n\n    rows.forEach((row) => {\n        const cells = Array.from(row.querySelectorAll(\"td\"));\n        cells.forEach((cell, index) => {\n            const day = index + 1;\n            const detailDivs = cell.querySelectorAll(\"div.kbcontent\");\n            detailDivs.forEach((div) => {\n                const html = div.innerHTML.trim();\n                if (!html || html === \"&nbsp;\") return;\n\n                const blocks = html.split(/-{10,}\\s*<br\\s*\\/?>/i).filter((item) => item.trim());\n                if (!blocks.length) blocks.push(html);\n\n                blocks.forEach((block) => {\n                    const course = parseCourseBlock(block, day);\n                    if (course) {\n                        courses.push(course);\n                    }\n                });\n            });\n        });\n    });\n\n    const uniqueMap = new Map();\n    courses.forEach((course) => {\n        const key = [\n            course.name,\n            course.teacher,\n            course.position,\n            course.day,\n            course.startSection,\n            course.endSection,\n            course.weeks.join(\",\")\n        ].join(\"|\");\n        if (!uniqueMap.has(key)) {\n            uniqueMap.set(key, course);\n        }\n    });\n\n    return Array.from(uniqueMap.values());\n}\n\nfunction choosePrimaryCampus(courses) {\n    for (const course of courses) {\n        if (course.campus) {\n            return course.campus;\n        }\n    }\n    return \"新庄校区\";\n}\n\nfunction normalizeCourses(courses, primaryCampus) {\n    return courses.map((course) => {\n        return {\n            name: course.name,\n            teacher: course.teacher,\n            position: course.position,\n            day: course.day,\n            startSection: course.startSection,\n            endSection: course.endSection,\n            weeks: course.weeks,\n            campus: course.campus || primaryCampus\n        };\n    });\n}\n\nfunction parseSemesterOptions(doc) {\n    const select = doc.getElementById(\"xnxq01id\");\n    if (!select) return { labels: [], values: [], defaultIndex: 0 };\n\n    const labels = [];\n    const values = [];\n    let defaultIndex = 0;\n\n    Array.from(select.querySelectorAll(\"option\")).forEach((option) => {\n        labels.push(option.innerText.trim());\n        values.push(option.value);\n        if (option.selected || option.hasAttribute(\"selected\")) {\n            defaultIndex = labels.length - 1;\n        }\n    });\n\n    return { labels, values, defaultIndex };\n}\n\nasync function fetchTermDoc(termValue) {\n    const body = new URLSearchParams();\n    if (termValue) body.append(\"xnxq01id\", termValue);\n\n    const response = await fetch(\"/jsxsd/xskb/xskb_list.do\", {\n        method: termValue ? \"POST\" : \"GET\",\n        headers: termValue ? { \"Content-Type\": \"application/x-www-form-urlencoded\" } : undefined,\n        body: termValue ? body.toString() : undefined,\n        credentials: \"include\"\n    });\n\n    const html = await response.text();\n    return new DOMParser().parseFromString(html, \"text/html\");\n}\n\nasync function pickTerm(doc) {\n    const { labels, values, defaultIndex } = parseSemesterOptions(doc);\n    if (!labels.length || typeof window.shiguangBridgePromise === \"undefined\") {\n        return { doc, termLabel: labels[defaultIndex] || \"\" };\n    }\n\n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"请选择要导入的学期\",\n        JSON.stringify(labels),\n        defaultIndex\n    );\n    if (selectedIndex === null || selectedIndex === -1) {\n        throw new Error(\"已取消导入\");\n    }\n\n    if (selectedIndex === defaultIndex) {\n        return { doc, termLabel: labels[selectedIndex] };\n    }\n\n    const selectedDoc = await fetchTermDoc(values[selectedIndex]);\n    return { doc: selectedDoc, termLabel: labels[selectedIndex] };\n}\n\nasync function saveToApp(courses, primaryCampus) {\n    const timeSlots = CAMPUS_TIME_SLOTS[primaryCampus];\n    const allWeeks = courses.flatMap((course) => course.weeks || []);\n    const semesterTotalWeeks = allWeeks.length ? Math.max(...allWeeks) : 20;\n\n    if (typeof window.shiguangBridgePromise === \"undefined\") {\n        console.log(\"Primary campus:\", primaryCampus);\n        console.log(\"Time slots:\", timeSlots);\n        console.log(\"Courses:\", courses);\n        alert(`解析完成：${primaryCampus}，共 ${courses.length} 门课程。请查看控制台输出。`);\n        return;\n    }\n\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\n        semesterTotalWeeks,\n        firstDayOfWeek: 1\n    }));\n    await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n    const appCourses = courses.map(({ campus, ...course }) => course);\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(appCourses));\n}\n\nasync function runImportFlow() {\n    try {\n        showToast(\"正在获取 NJFU 课表数据...\");\n        const initialDoc = await fetchTermDoc(\"\");\n        const { doc, termLabel } = await pickTerm(initialDoc);\n        const parsedCourses = extractCoursesFromDoc(doc);\n\n        if (!parsedCourses.length) {\n            throw new Error(\"未解析到课程，请确认当前账号已登录教务系统。\");\n        }\n\n        const primaryCampus = choosePrimaryCampus(parsedCourses);\n        const courses = normalizeCourses(parsedCourses, primaryCampus);\n\n        await saveToApp(courses, primaryCampus);\n\n        const message = `导入完成：${primaryCampus}${termLabel ? ` ${termLabel}` : \"\"}`;\n\n        showToast(message);\n        if (typeof window.shiguangBridge !== \"undefined\") {\n            window.shiguangBridge.notifyTaskCompletion();\n        }\n    } catch (error) {\n        console.error(error);\n        showToast(`导入失败: ${error.message}`);\n    }\n}\n\nrunImportFlow();\n","NUAA_01":"// 南京航空航天大学(aao-eas.nuaa.edu.cn) 拾光课程表适配脚本\n// 基于旧树维(TJAU)方案，调整 TaskActivity 参数位次与 13 节作息\n\nconst BASE = \"https://aao-eas.nuaa.edu.cn/eams\";\n\nfunction powerSplit(paramsRaw) {\n    const args = [];\n    let current = \"\";\n    let depth = 0;\n    let inQuote = false;\n    let quoteChar = \"\";\n\n    for (let i = 0; i < paramsRaw.length; i++) {\n        let char = paramsRaw[i];\n        if ((char === '\"' || char === \"'\") && (i === 0 || paramsRaw[i - 1] !== '\\\\')) {\n            if (!inQuote) { inQuote = true; quoteChar = char; }\n            else if (char === quoteChar) { inQuote = false; }\n        }\n        if (!inQuote) {\n            if (char === '(' || char === '[' || char === '{') depth++;\n            if (char === ')' || char === ']' || char === '}') depth--;\n        }\n        if (char === ',' && depth === 0 && !inQuote) {\n            args.push(cleanArg(current));\n            current = \"\";\n        } else {\n            current += char;\n        }\n    }\n    args.push(cleanArg(current));\n    return args;\n}\n\nfunction cleanArg(s) {\n    s = s.trim();\n    if (s === \"null\") return null;\n    return s.replace(/^[\"']|[\"']$/g, \"\");\n}\n\nfunction mergeContinuousLessons(lessons) {\n    if (!lessons || lessons.length === 0) return [];\n\n    const groups = {};\n    lessons.forEach(l => {\n        const key = `${l.name}|${l.teacher}|${l.position}|${l.day}`;\n        if (!groups[key]) {\n            groups[key] = {\n                name: l.name,\n                teacher: l.teacher,\n                position: l.position,\n                campus: l.campus || \"\",\n                day: l.day,\n                weeksMatrix: Array.from({ length: 50 }, () => new Set())\n            };\n        } else if (!groups[key].campus && l.campus) {\n            groups[key].campus = l.campus;\n        }\n        if (l.weeks && Array.isArray(l.weeks)) {\n            l.weeks.forEach(w => {\n                if (w >= 0 && w < 50) {\n                    for (let s = l.startSection; s <= l.endSection; s++) {\n                        groups[key].weeksMatrix[w].add(s);\n                    }\n                }\n            });\n        }\n    });\n\n    const merged = [];\n    for (const key in groups) {\n        const group = groups[key];\n        const matrix = group.weeksMatrix;\n        const blockMap = {};\n\n        for (let w = 0; w < matrix.length; w++) {\n            const sections = Array.from(matrix[w]).sort((a, b) => a - b);\n            if (sections.length === 0) continue;\n\n            let start = sections[0];\n            let prev = sections[0];\n            for (let i = 1; i < sections.length; i++) {\n                const curr = sections[i];\n                if (curr === prev + 1) {\n                    prev = curr;\n                } else {\n                    const blockKey = `${start}-${prev}`;\n                    if (!blockMap[blockKey]) blockMap[blockKey] = [];\n                    blockMap[blockKey].push(w);\n                    start = curr;\n                    prev = curr;\n                }\n            }\n            const blockKey = `${start}-${prev}`;\n            if (!blockMap[blockKey]) blockMap[blockKey] = [];\n            blockMap[blockKey].push(w);\n        }\n\n        for (const blockKey in blockMap) {\n            const [startSec, endSec] = blockKey.split('-').map(Number);\n            merged.push({\n                name: group.name,\n                teacher: group.teacher,\n                position: group.position,\n                campus: group.campus || \"\",\n                day: group.day,\n                startSection: startSec,\n                endSection: endSec,\n                weeks: blockMap[blockKey]\n            });\n        }\n    }\n\n    merged.sort((a, b) => {\n        if (a.day !== b.day) return a.day - b.day;\n        if (a.startSection !== b.startSection) return a.startSection - b.startSection;\n        return a.name.localeCompare(b.name);\n    });\n\n    return merged;\n}\n\n// 系统节次 5/6 为午一/午二，不导入课表\n// 1-4 保持；7-13 映射为官方第五节至第十一节（应用内 5-11）\nfunction mapSection(nuaaSection) {\n    if (nuaaSection >= 1 && nuaaSection <= 4) return nuaaSection;\n    if (nuaaSection >= 7 && nuaaSection <= 13) return nuaaSection - 2;\n    return null;\n}\n\n// 南航 TaskActivity 相对天津农学院整体右移 1 位：\n// args[3]=课程名, args[6]=地点, args[7]=周次位图\nfunction parseTaskActivities(html) {\n    const rawResults = [];\n    const blocks = html.split(/var\\s+teachers\\s*=/);\n\n    for (let i = 1; i < blocks.length; i++) {\n        const block = blocks[i];\n        let teacherName = \"未知教师\";\n        const tMatch = block.match(/actTeachers\\s*=\\s*\\[\\s*\\{[\\s\\S]*?name:\\s*\"(.*?)\"/);\n        if (tMatch) teacherName = tMatch[1];\n\n        const activityMatch = block.match(/new\\s+TaskActivity\\(([\\s\\S]*?)\\);/);\n        if (!activityMatch) continue;\n\n        const args = powerSplit(activityMatch[1]);\n        const courseName = (args[3] || \"未知课程\").trim();\n        const positionRaw = (args[6] || \"\").trim();\n        const position = positionRaw.replace(/\\(.*?\\)/g, \"\").trim() || \"未知地点\";\n        const campus = /天目湖/.test(positionRaw) ? \"天目湖\" : \"\";\n        const weeksBitmap = args[7] || \"\";\n\n        const weeks = [];\n        for (let j = 0; j < weeksBitmap.length; j++) {\n            if (weeksBitmap[j] === '1') weeks.push(j);\n        }\n\n        const unitCountMatch = html.match(/unitCount\\s*=\\s*(\\d+)/);\n        const unitCount = unitCountMatch ? parseInt(unitCountMatch[1]) : 13;\n\n        const idxRegex = /index\\s*=\\s*(\\d+)\\s*\\*\\s*unitCount\\s*\\+\\s*(\\d+);/g;\n        let m;\n        while ((m = idxRegex.exec(block)) !== null) {\n            const day = parseInt(m[1]) + 1;\n            const section = mapSection(parseInt(m[2]) + 1);\n            if (section === null) continue;\n            rawResults.push({\n                name: courseName,\n                teacher: teacherName,\n                position: position,\n                campus: campus,\n                day: day,\n                startSection: section,\n                endSection: section,\n                weeks: weeks\n            });\n        }\n    }\n\n    return mergeContinuousLessons(rawResults);\n}\n\nasync function request(url, options = {}) {\n    const res = await fetch(url, { credentials: \"include\", ...options });\n    if (!res.ok) throw new Error(`网络请求失败: ${res.status}`);\n    return await res.text();\n}\n\nfunction extractDefaultSemesterId(html) {\n    // 教务页当前加载的学期：hidden input 或 semesterCalendar 初始化 value\n    const target = html.match(/id=\"semesterCalendar_target\"[\\s\\S]*?value=\"(\\d+)\"/);\n    if (target) return target[1];\n    const cal = html.match(/semesterCalendar\\(\\{[^}]*value:\"(\\d+)\"/);\n    if (cal) return cal[1];\n    return \"\";\n}\n\nasync function detectParameters() {\n    const html = await request(`${BASE}/courseTableForStd.action?sf_request_type=ajax`);\n    const idsMatch = html.match(/bg\\.form\\.addInput\\(form,\\s*\"ids\",\\s*\"(\\d+)\"\\)/);\n    const tagIdMatch = html.match(/id=\"(semesterBar\\d+Semester)\"/);\n    if (!idsMatch || !tagIdMatch) return null;\n    return {\n        ids: idsMatch[1],\n        tagId: tagIdMatch[1],\n        defaultSemesterId: extractDefaultSemesterId(html)\n    };\n}\n\nasync function getSelectedSemester(tagId, defaultSemesterId) {\n    const raw = await request(`${BASE}/dataQuery.action?sf_request_type=ajax`, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n        body: `tagId=${encodeURIComponent(tagId)}&dataType=semesterCalendar`\n    });\n    const data = Function(`return (${raw});`)();\n    const list = [];\n    for (let key in data.semesters) {\n        data.semesters[key].forEach(s => list.push({\n            id: String(s.id),\n            name: `${s.schoolYear} ${s.name}学期`\n        }));\n    }\n    if (list.length === 0) throw new Error(\"未解析到学期列表，请确认已登录教务系统\");\n\n    // 默认选中教务页当前加载的学期，而不是列表里的第一条\n    let defaultIndex = 0;\n    if (defaultSemesterId) {\n        const found = list.findIndex(s => s.id === String(defaultSemesterId));\n        if (found >= 0) defaultIndex = found;\n    }\n\n    const idx = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(list.map(s => s.name)),\n        defaultIndex\n    );\n    return idx !== null ? list[idx] : null;\n}\n\nasync function fetchAndParseCourses(semesterId, ids) {\n    const html = await request(`${BASE}/courseTableForStd!courseTable.action?sf_request_type=ajax`, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n        body: `ignoreHead=1&setting.kind=std&semester.id=${semesterId}&ids=${ids}`\n    });\n    return parseTaskActivities(html);\n}\n\n// 官方校历 11 节作息，不含午一/午二\nfunction getTimeSlots(campus) {\n    const tianmuhu = [\n        [\"08:30\", \"09:20\"], [\"09:25\", \"10:15\"], [\"10:30\", \"11:20\"], [\"11:25\", \"12:15\"],\n        [\"14:00\", \"14:50\"], [\"14:55\", \"15:45\"], [\"16:00\", \"16:50\"], [\"16:55\", \"17:45\"],\n        [\"18:45\", \"19:35\"], [\"19:40\", \"20:30\"], [\"20:35\", \"21:25\"]\n    ];\n    const other = [\n        [\"08:00\", \"08:50\"], [\"08:55\", \"09:45\"], [\"10:15\", \"11:05\"], [\"11:10\", \"12:00\"],\n        [\"14:00\", \"14:50\"], [\"14:55\", \"15:45\"], [\"16:15\", \"17:05\"], [\"17:10\", \"18:00\"],\n        [\"18:45\", \"19:35\"], [\"19:40\", \"20:30\"], [\"20:35\", \"21:25\"]\n    ];\n    const pairs = campus === \"天目湖\" ? tianmuhu : other;\n    return pairs.map((p, i) => ({\n        number: i + 1,\n        startTime: p[0],\n        endTime: p[1]\n    }));\n}\n\nfunction detectCampusFromCourses(courses) {\n    if (!courses || courses.length === 0) return \"\";\n    const first = courses.find(c => c.campus);\n    return first ? first.campus : \"\";\n}\n\nasync function applyTimeSlots(courses) {\n    const campus = detectCampusFromCourses(courses) || \"其他校区\";\n    const slots = getTimeSlots(campus === \"天目湖\" ? \"天目湖\" : \"other\");\n    window.shiguangBridge.showToast(`按${campus || \"默认\"}作息导入时间段`);\n    return await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(slots));\n}\n\nasync function runImportFlow() {\n    try {\n        window.shiguangBridge.showToast(\"开始探测教务参数...\");\n        const params = await detectParameters();\n        if (!params) {\n            window.shiguangBridge.showToast(\"无法识别当前页面，请先登录教务系统并进入课表页面\");\n            return;\n        }\n\n        const semester = await getSelectedSemester(params.tagId, params.defaultSemesterId);\n        if (!semester) {\n            window.shiguangBridge.showToast(\"导入已取消\");\n            return;\n        }\n\n        window.shiguangBridge.showToast(\"正在同步课表...\");\n        const courses = await fetchAndParseCourses(semester.id, params.ids);\n        if (!courses || courses.length === 0) {\n            window.shiguangBridge.showToast(\"未解析到课程数据，可能是学期选择错误或尚未登录\");\n            return;\n        }\n\n        await applyTimeSlots(courses);\n        const payload = courses.map(({ campus, ...rest }) => rest);\n        const saveResult = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(payload));\n\n        if (saveResult) {\n            window.shiguangBridge.showToast(`成功导入 ${courses.length} 个课程条目`);\n            window.shiguangBridge.notifyTaskCompletion();\n        }\n    } catch (e) {\n        console.error(`[异常] ${e.message}`);\n        window.shiguangBridge.showToast(e.message);\n    }\n}\n\nrunImportFlow();\n","NJUPT_01":"// 南京邮电大学正方教务（V9）拾光课程表适配脚本\n// 通过正方 API 获取课程与学期第一周日期\n\nconst NJUPT_TIME_SLOTS = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:50\", endTime: \"09:35\" },\n    { number: 3, startTime: \"09:50\", endTime: \"10:35\" },\n    { number: 4, startTime: \"10:40\", endTime: \"11:25\" },\n    { number: 5, startTime: \"11:30\", endTime: \"12:15\" },\n    { number: 6, startTime: \"13:45\", endTime: \"14:30\" },\n    { number: 7, startTime: \"14:35\", endTime: \"15:20\" },\n    { number: 8, startTime: \"15:35\", endTime: \"16:20\" },\n    { number: 9, startTime: \"16:25\", endTime: \"17:10\" },\n    { number: 10, startTime: \"18:30\", endTime: \"19:15\" },\n    { number: 11, startTime: \"19:25\", endTime: \"20:10\" },\n    { number: 12, startTime: \"20:20\", endTime: \"21:05\" }\n];\n\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    const list = courses.map(course => ({\n        ...course,\n        name: course.name || \"\",\n        teacher: course.teacher || \"\",\n        position: course.position || \"\",\n        weeks: Array.isArray(course.weeks)\n            ? [...course.weeks].sort((a, b) => a - b)\n            : []\n    }));\n\n    list.sort((a, b) =>\n        a.name.localeCompare(b.name) ||\n        a.teacher.localeCompare(b.teacher) ||\n        a.position.localeCompare(b.position) ||\n        a.day - b.day ||\n        a.weeks.join(\",\").localeCompare(b.weeks.join(\",\")) ||\n        a.startSection - b.startSection\n    );\n\n    const sectionMerged = [];\n    let current = list[0];\n    for (let index = 1; index < list.length; index++) {\n        const next = list[index];\n        const sameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(\",\") === next.weeks.join(\",\");\n        const continuous = current.endSection + 1 === next.startSection;\n        const duplicate =\n            current.startSection === next.startSection &&\n            current.endSection === next.endSection;\n\n        if (sameCourseAndWeeks && continuous) {\n            current.endSection = next.endSection;\n        } else if (!sameCourseAndWeeks || !duplicate) {\n            sectionMerged.push(current);\n            current = next;\n        }\n    }\n    sectionMerged.push(current);\n\n    sectionMerged.sort((a, b) =>\n        a.name.localeCompare(b.name) ||\n        a.teacher.localeCompare(b.teacher) ||\n        a.position.localeCompare(b.position) ||\n        a.day - b.day ||\n        a.startSection - b.startSection ||\n        a.endSection - b.endSection\n    );\n\n    const result = [];\n    let merged = sectionMerged[0];\n    for (let index = 1; index < sectionMerged.length; index++) {\n        const next = sectionMerged[index];\n        const sameCourseAndSections =\n            merged.name === next.name &&\n            merged.teacher === next.teacher &&\n            merged.position === next.position &&\n            merged.day === next.day &&\n            merged.startSection === next.startSection &&\n            merged.endSection === next.endSection;\n\n        if (sameCourseAndSections) {\n            merged.weeks = [...new Set([...merged.weeks, ...next.weeks])]\n                .sort((a, b) => a - b);\n        } else {\n            result.push(merged);\n            merged = next;\n        }\n    }\n    result.push(merged);\n    return result;\n}\n\nfunction parseWeeks(weekText) {\n    if (!weekText) return [];\n\n    const weeks = [];\n    for (const segment of String(weekText).split(/[，,]/)) {\n        const normalized = segment.trim().replace(/（/g, \"(\").replace(/）/g, \")\");\n        const match = normalized.match(/(\\d+)(?:-(\\d+))?\\s*周?/);\n        if (!match) continue;\n\n        const start = Number(match[1]);\n        const end = match[2] ? Number(match[2]) : start;\n        const oddOnly = normalized.includes(\"(单)\");\n        const evenOnly = normalized.includes(\"(双)\");\n\n        for (let week = start; week <= end; week++) {\n            if (oddOnly && week % 2 === 0) continue;\n            if (evenOnly && week % 2 !== 0) continue;\n            weeks.push(week);\n        }\n    }\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\nfunction parseJsonData(jsonData) {\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        console.warn(\"JS: API 数据中缺少 kbList。\");\n        return [];\n    }\n\n    const courses = [];\n    for (const rawCourse of jsonData.kbList) {\n        if (!rawCourse.kcmc || !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) {\n            continue;\n        }\n\n        const weeks = parseWeeks(rawCourse.zcd);\n        const sectionNumbers = String(rawCourse.jcs).match(/\\d+/g)?.map(Number) || [];\n        const day = Number(rawCourse.xqj);\n        const startSection = sectionNumbers[0];\n        const endSection = sectionNumbers[sectionNumbers.length - 1];\n\n        if (\n            weeks.length === 0 ||\n            !Number.isInteger(day) || day < 1 || day > 7 ||\n            !Number.isInteger(startSection) || !Number.isInteger(endSection) ||\n            startSection < 1 || startSection > endSection\n        ) {\n            continue;\n        }\n\n        courses.push({\n            name: String(rawCourse.kcmc).trim(),\n            teacher: String(rawCourse.xm || \"\").trim(),\n            position: String(rawCourse.cdmc || \"\").trim(),\n            day,\n            startSection,\n            endSection,\n            weeks\n        });\n    }\n\n    return mergeAndDistinctCourses(courses);\n}\n\nfunction getNjuptApiBasePath() {\n    // 直接匹配路径，避免依赖教务页面可能改写的数组和字符串方法。\n    const isTeachingSystemPage = /\\/(?:kbcx|xtgl)\\//.test(window.location.pathname);\n    if (!isTeachingSystemPage) return null;\n\n    // 南邮 WebVPN 会拦截并改写根相对请求。若传入已经带 WebVPN\n    // 哈希前缀的完整 URL，会被二次改写成“当前页面.htm/kbcx/...”。\n    return \"\";\n}\n\nasync function postForm(url, requestBody) {\n    const response = await fetch(url, {\n        method: \"POST\",\n        headers: {\n            \"Accept\": \"application/json, text/javascript, */*; q=0.01\",\n            \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        body: requestBody,\n        credentials: \"include\"\n    });\n    if (!response.ok) throw new Error(`HTTP ${response.status}`);\n    return response;\n}\n\nasync function fetchAcademicOptions(appBasePath) {\n    const url = `${appBasePath}/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151&layout=default`;\n    try {\n        const response = await fetch(url, {\n            method: \"GET\",\n            credentials: \"include\"\n        });\n        if (!response.ok) return null;\n\n        const html = await response.text();\n        const document = new DOMParser().parseFromString(html, \"text/html\");\n        const readOptions = selector => {\n            const nodes = document.querySelectorAll(selector);\n            const options = [];\n            for (let index = 0; index < nodes.length; index++) {\n                const option = nodes[index];\n                const value = String(option.value || \"\").trim();\n                const text = String(option.textContent || \"\").trim();\n                if (value === \"\" || text === \"\") continue;\n                options.push({ value, text, selected: option.selected });\n            }\n            return options;\n        };\n        const allYearOptions = readOptions(\"#xnm option\");\n        const semesterOptions = readOptions(\"#xqm option\");\n\n        if (allYearOptions.length === 0 || semesterOptions.length === 0) return null;\n\n        const selectedYearIndex = allYearOptions.findIndex(option => option.selected);\n        const start = selectedYearIndex === -1 ? 0 : Math.max(0, selectedYearIndex - 2);\n        const end = selectedYearIndex === -1\n            ? Math.min(allYearOptions.length, 5)\n            : Math.min(allYearOptions.length, selectedYearIndex + 3);\n        const yearOptions = allYearOptions.slice(start, end);\n        const selectedSemesterIndex = semesterOptions.findIndex(option => option.selected);\n\n        return {\n            yearOptions,\n            semesterOptions,\n            defaultYearIndex: selectedYearIndex === -1 ? 0 : selectedYearIndex - start,\n            defaultSemesterIndex: selectedSemesterIndex === -1 ? 0 : selectedSemesterIndex\n        };\n    } catch (error) {\n        console.error(\"JS: 获取学年学期列表失败：\", error);\n        return null;\n    }\n}\n\nasync function selectAcademicYearAndSemester(appBasePath) {\n    const options = await fetchAcademicOptions(appBasePath);\n    if (!options) {\n        await window.shiguangBridgePromise.showAlert(\n            \"无法读取学年学期\",\n            \"请确认已登录教务系统，并重新尝试导入。\",\n            \"确定\"\n        );\n        return null;\n    }\n\n    const yearIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学年\",\n        JSON.stringify(options.yearOptions.map(option => option.text)),\n        options.defaultYearIndex\n    );\n    if (yearIndex === null || yearIndex === -1 || !options.yearOptions[yearIndex]) return null;\n\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(options.semesterOptions.map(option => option.text)),\n        options.defaultSemesterIndex\n    );\n    if (\n        semesterIndex === null ||\n        semesterIndex === -1 ||\n        !options.semesterOptions[semesterIndex]\n    ) return null;\n\n    return {\n        academicYear: options.yearOptions[yearIndex].value,\n        semesterCode: options.semesterOptions[semesterIndex].value\n    };\n}\n\nasync function fetchSemesterStartDate(appBasePath, academicYear, semesterCode) {\n    const url = `${appBasePath}/kbcx/xskbcxZccx_cxZcByXnxq.html?gnmkdm=N2154`;\n    try {\n        const response = await postForm(url, `xnm=${academicYear}&xqm=${semesterCode}`);\n        const data = await response.json();\n        if (!Array.isArray(data) || data.length === 0) return null;\n\n        const firstWeek = data.find(item => String(item.zs) === \"1\" || String(item.zsmc) === \"1\") || data[0];\n        if (firstWeek.rq) {\n            const date = String(firstWeek.rq).split(\"/\")[0];\n            if (/^\\d{4}-\\d{2}-\\d{2}$/.test(date)) return date;\n        }\n        if (firstWeek.zcrq) {\n            const match = String(firstWeek.zcrq).match(/\\d{4}-\\d{2}-\\d{2}/);\n            if (match) return match[0];\n        }\n    } catch (error) {\n        console.error(\"JS: 获取开学日期失败：\", error);\n    }\n    return null;\n}\n\nasync function fetchCourses(appBasePath, academicYear, semesterCode) {\n    const url = `${appBasePath}/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151`;\n    const body = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`;\n    const response = await postForm(url, body);\n    const data = await response.json();\n    return parseJsonData(data);\n}\n\nasync function saveImportResult(courses, semesterStartDate) {\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses, null, 2));\n\n    const config = { semesterTotalWeeks: 20 };\n    if (semesterStartDate) config.semesterStartDate = semesterStartDate;\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n    await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(NJUPT_TIME_SLOTS));\n}\n\nasync function runImportFlow() {\n    const confirmed = await window.shiguangBridgePromise.showAlert(\n        \"南京邮电大学课表导入\",\n        \"请先登录智慧校园并进入教务系统，建议打开课表页面后再导入。\",\n        \"好的，开始导入\"\n    );\n    if (!confirmed) return;\n\n    const appBasePath = getNjuptApiBasePath();\n    if (appBasePath === null) {\n        await window.shiguangBridgePromise.showAlert(\n            \"无法识别当前页面\",\n            \"请先从智慧校园进入教务系统，并打开课表页面后重试。\",\n            \"确定\"\n        );\n        return;\n    }\n\n    try {\n        const selection = await selectAcademicYearAndSemester(appBasePath);\n        if (!selection) return;\n\n        const { academicYear, semesterCode } = selection;\n        window.shiguangBridge.showToast(\"正在从教务系统获取课表...\");\n\n        const [courses, semesterStartDate] = await Promise.all([\n            fetchCourses(appBasePath, academicYear, semesterCode),\n            fetchSemesterStartDate(appBasePath, academicYear, semesterCode)\n        ]);\n\n        if (courses.length === 0) {\n            await window.shiguangBridgePromise.showAlert(\n                \"未获取到课程\",\n                \"请确认已登录教务系统，并检查所选学年、学期是否正确。\",\n                \"确定\"\n            );\n            return;\n        }\n\n        await saveImportResult(courses, semesterStartDate);\n        const dateMessage = semesterStartDate ? `，开学日期 ${semesterStartDate}` : \"\";\n        window.shiguangBridge.showToast(`导入成功：${courses.length} 门课程${dateMessage}`);\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        console.error(\"JS: API 课表导入失败：\", error);\n        await window.shiguangBridgePromise.showAlert(\n            \"导入失败\",\n            `无法从教务系统 API 获取或保存数据：${error.message}`,\n            \"确定\"\n        );\n    }\n}\n\nrunImportFlow();\n","USC_01":"// 南华大学(http://jwzx.usc.edu.cn:8924)拾光课程表适配脚本\n\n\nconst BASE_URL = \"http://jwzx.usc.edu.cn:8924\";\nconst [URL_COURSE, URL_CALENDAR] = [`${BASE_URL}/jsxsd/xskb/xskb_list.do`, `${BASE_URL}/jsxsd/jxzl/jxzl_query`];\n\n// 工具函数\nconst parseSlots = arr => arr.map((s, i) => ({ number: i + 1, startTime: s.slice(0, 5), endTime: s.slice(6) }));\nconst TIME_SLOTS_SUMMER = parseSlots([\"08:00-08:45\",\"08:55-09:40\",\"10:00-10:45\",\"10:55-11:40\",\"15:00-15:45\",\"15:55-16:40\",\"17:00-17:45\",\"17:55-18:40\",\"20:00-20:45\",\"20:55-21:40\"]);\nconst TIME_SLOTS_WINTER = parseSlots([\"08:20-09:05\",\"09:15-10:00\",\"10:20-11:05\",\"11:15-12:00\",\"14:30-15:15\",\"15:25-16:10\",\"16:30-17:15\",\"17:25-18:10\",\"19:30-20:15\",\"20:25-21:10\"]);\n\nconst pad2 = n => String(n).padStart(2, \"0\");\nconst WEEK_MAP = { 一:1, 二:2, 三:3, 四:4, 五:5, 六:6, 日:7, 天:7 };\n\nconst parseWeeks = str => [...new Set((str || \"\").split(\"(\")[0].split(\",\").flatMap(s => {\n    const [st, ed] = s.split(\"-\").map(Number);\n    return (st && ed) ? Array.from({length: ed - st + 1}, (_, i) => st + i) : [st].filter(n => !isNaN(n));\n}))].sort((a, b) => a - b);\n\nconst parseSectionRange = text => {\n    const [_, s, e] = String(text || \"\").match(/(\\d+)\\s*(?:-\\s*(\\d+))?/) || [];\n    return s ? { start: +s, end: +(e || s) } : null;\n};\n\nfunction parseDayColumns(table) {\n    for (const row of table.rows) {\n        const days = [...row.children].filter(el => /^(TH|TD)$/.test(el.tagName))\n            .map(el => WEEK_MAP[el.textContent.trim().match(/^星期([一二三四五六日天])$/)?.[1]] || null);\n        if (days.filter(Boolean).length >= 5) return days.filter(d => d !== null);\n    }\n    return null;\n}\n\nfunction parseCellCourses(cell, selector, day, rowSec) {\n    const block = cell.querySelector(selector);\n    if (!block?.innerHTML.trim() || block.innerHTML.trim() === \"&nbsp;\") return [];\n\n    return block.innerHTML.split(/---------------------?/).flatMap(part => {\n        if (!part.trim()) return [];\n        const temp = document.createElement(\"div\");\n        temp.innerHTML = part;\n\n        let name = \"\";\n        for (const node of temp.childNodes) {\n            if (node.tagName === \"FONT\") break;\n            if (node.nodeType === 3) name += node.textContent.replace(/\\s+/g, \" \");\n        }\n        if (!(name = name.trim())) return [];\n\n        const textOf = sel => (temp.querySelector(sel)?.textContent || \"\").trim();\n        const teacher = textOf(\"font[title='老师'], font[title='教师']\").replace(\"任课教师:\", \"\") || \"未知教师\";\n        const position = textOf(\"font[title='教室']\") || \"未知地点\";\n        const weekStr = textOf(\"font[title='周次(节次)']\");\n\n        const nums = (weekStr.match(/\\[([\\d\\-,\\s]+?)节\\]/)?.[1] || \"\").split(/[^\\d]+/).map(Number).filter(n => n > 0);\n        const startSection = nums.length ? Math.min(...nums) : (rowSec?.start || 0);\n        const endSection = nums.length ? Math.max(...nums) : (rowSec?.end || 0);\n        const weeks = parseWeeks(weekStr);\n\n        return (weeks.length && startSection) ? [{ name, teacher, position, day, startSection, endSection: Math.max(startSection, endSection), weeks }] : [];\n    });\n}\n\n// 合并函数\nfunction mergeAndDistinctCourses(courses) {\n    if (!courses?.length) return [];\n    const key1 = c => [c.name, c.teacher, c.position, c.day, c.weeks.join()].join(\"|\");\n    const key2 = c => [c.name, c.teacher, c.position, c.day, c.startSection, c.endSection].join(\"|\");\n\n    return courses.map(c => ({...c, weeks: [...c.weeks].sort((a, b) => a - b)}))\n        .sort((a, b) => key1(a).localeCompare(key1(b)) || a.startSection - b.startSection)\n        .reduce((acc, n) => { // 阶段1：合并连续/重复节次\n            const cur = acc[acc.length - 1];\n            if (cur && key1(cur) === key1(n)) {\n                if (cur.endSection + 1 === n.startSection) cur.endSection = n.endSection;\n                else if (cur.startSection !== n.startSection || cur.endSection !== n.endSection) acc.push(n);\n            } else acc.push(n);\n            return acc;\n        }, [])\n        .sort((a, b) => key2(a).localeCompare(key2(b)))\n        .reduce((acc, n) => { // 阶段2：合并相同节次的周次\n            const cur = acc[acc.length - 1];\n            if (cur && key2(cur) === key2(n)) cur.weeks = [...new Set([...cur.weeks, ...n.weeks])].sort((a,b) => a - b);\n            else acc.push(n);\n            return acc;\n        }, []);\n}\n\nconst parseTimetableToModel = doc => {\n    const table = doc.getElementById(\"kbtable\");\n    if (!table) return [];\n    const dayMap = parseDayColumns(table) || [1, 2, 3, 4, 5, 6, 7];\n    const selector = table.querySelector(\"div.kbcontent\") ? \"div.kbcontent\" : \"div.kbcontent1\";\n\n    return mergeAndDistinctCourses([...table.rows].flatMap(row => {\n        const cells = [...row.querySelectorAll(\"td\")];\n        const dayCells = cells.length === dayMap.length + 1 ? cells.slice(1) : cells;\n        if (dayCells.length !== dayMap.length) return [];\n        const rowSec = parseSectionRange(row.querySelector(\"th\")?.textContent);\n        return dayCells.flatMap((cell, i) => dayMap[i] ? parseCellCourses(cell, selector, dayMap[i], rowSec) : []);\n    }));\n};\n\n// 网络请求与解析\nconst parseHtml = html => new DOMParser().parseFromString(html, \"text/html\");\nconst req = async (url, opts) => {\n    const res = await fetch(url, { credentials: \"include\", ...opts });\n    if (!res.ok) throw new Error(`HTTP ${res.status}`);\n    return res.text();\n};\nconst formOpts = body => ({ method: \"POST\", headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" }, body });\n\nconst requestCoursePage = semId => req(URL_COURSE, formOpts(`jx0404id=&cj0701id=&zc=&demo=&xnxq01id=${semId||\"\"}`));\nconst requestCoursePageByGet = semId => req(`${URL_COURSE}?xnxq01id=${encodeURIComponent(semId||\"\")}&zc=&cj0701id=&demo=`, { method: \"GET\" });\nconst requestCalendarPage = semId => req(URL_CALENDAR, formOpts(`xnxq01id=${semId}`));\n\nfunction parseSemesterOptions(html) {\n    const select = parseHtml(html).getElementById(\"xnxq01id\");\n    if (!select) return { list: [], defaultIndex: -1 };\n    const all = [...select.options].map(o => ({ value: o.value, label: o.textContent.trim(), selected: o.selected })).filter(o => o.value);\n    const idx = Math.max(0, all.findIndex(o => o.selected));\n    const start = Math.max(0, idx - 3);\n    return { list: all.slice(start, idx + 4), defaultIndex: idx - start };\n}\n\nasync function fetchCourses(semId) {\n    let html = await requestCoursePage(semId).catch(() => null);\n    let courses = html ? parseTimetableToModel(parseHtml(html)) : [];\n    if (!courses.length) {\n        html = await requestCoursePageByGet(semId).catch(() => null);\n        if (html) courses = parseTimetableToModel(parseHtml(html));\n    }\n    return courses;\n}\n\nasync function fetchSemesterInfo(semId) {\n    try {\n        const doc = parseHtml(await requestCalendarPage(semId));\n        const dates = [...doc.querySelectorAll(\"td[title]\")].map(td => {\n            const m = td.getAttribute(\"title\")?.match(/(\\d{4})年(\\d{1,2})月(\\d{1,2})日?/);\n            return m ? `${m[1]}-${pad2(m[2])}-${pad2(m[3])}` : null;\n        }).filter(Boolean).sort();\n        const totalWeeks = Math.max(0, ...[...doc.querySelectorAll(\"#kbtable tr td:first-child\")].map(td => parseInt(td.textContent, 10)).filter(n => !isNaN(n)));\n        return { startDate: dates[0] || null, totalWeeks: totalWeeks || null };\n    } catch { return { startDate: null, totalWeeks: null }; }\n}\n\n// 全局校验\nwindow.validateStartDateInput = input => !input?.trim() || /^\\d{4}-\\d{1,2}-\\d{1,2}$/.test(input.trim()) ? false : \"请输入形如 2026-09-01 的日期，或留空跳过\";\n\nasync function promptSemesterStartDate() {\n    const input = await window.shiguangBridgePromise.showPrompt(\"设置开学日期\", \"未能自动获取开学日期...\\n请输入本学期第一周的星期一日期（如 2026-09-01），留空则跳过：\", \"\", \"validateStartDateInput\");\n    const m = input?.trim().match(/^(\\d{4})-(\\d{1,2})-(\\d{1,2})$/);\n    return m ? `${m[1]}-${pad2(m[2])}-${pad2(m[3])}` : null;\n}\n\nconst computeTotalWeeks = courses => {\n    const max = Math.max(0, ...courses.flatMap(c => c.weeks || []));\n    return (max > 0 && max <= 40) ? max : 20;\n};\n\nfunction buildComboSchedule(semId, label) {\n    const [_, y0, y1, term] = String(semId || \"\").match(/^(\\d{4})-(\\d{4})-(\\d)$/) || [];\n    if (!term) return null;\n    const Y = term === \"2\" ? +y1 : +y0;\n    const winter = { name: \"秋冬季作息\", startDate: `${term === \"2\" ? Y - 1 : Y}-10-01`, endDate: `${term === \"2\" ? Y : Y + 1}-04-30`, timeSlots: [] };\n    return {\n        name: `南华大学 ${label || semId} 作息方案`,\n        publicSchedules: [ { name: \"夏秋季作息\", startDate: `${Y}-05-01`, endDate: `${Y}-09-30`, timeSlots: TIME_SLOTS_SUMMER }, winter ].sort((a,b) => a.startDate.localeCompare(b.startDate))\n    };\n}\n\nconst saveAppConfig = (startDate, weeks) => window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({ semesterTotalWeeks: weeks || 20, firstDayOfWeek: 7, defaultClassDuration: 45, ...(startDate && { semesterStartDate: startDate }) }));\nconst saveAppTimeSlots = () => window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(TIME_SLOTS_WINTER));\n\n// 主流程\n(async function runImportFlow() {\n    const bridge = window.shiguangBridge, pBridge = window.shiguangBridgePromise;\n    try {\n        if (!await pBridge.showAlert(\"提示\", \"请确保已登录教务在线，并已打开「学期理论课表」页面。\\n是否开始导入？\", \"开始\")) return;\n\n        bridge.showToast(\"正在获取学期列表...\");\n        const { list, defaultIndex } = parseSemesterOptions(await requestCoursePage(\"\"));\n        if (!list.length) return bridge.showToast(\"未获取到学期列表，请检查登录状态。\");\n\n        const selIdx = await pBridge.showSingleSelection(\"选择学期\", JSON.stringify(list.map(s => s.label)), defaultIndex);\n        if (selIdx === null) return bridge.showToast(\"已取消导入。\");\n\n        bridge.showToast(\"正在请求课程数据...\");\n        const sem = list[selIdx], courses = await fetchCourses(sem.value);\n        if (!courses.length) return bridge.showToast(\"未发现课程，请检查学期选择或登录状态。\");\n\n        bridge.showToast(\"正在获取学期信息...\");\n        const { startDate, totalWeeks } = await fetchSemesterInfo(sem.value);\n        const finalStart = startDate || await promptSemesterStartDate();\n\n        await saveAppConfig(finalStart, totalWeeks || computeTotalWeeks(courses));\n        await pBridge.saveImportedCourses(JSON.stringify(courses));\n\n        try {\n            if (await saveAppTimeSlots()) {\n                const combo = buildComboSchedule(sem.value, sem.label);\n                if (combo) await pBridge.saveComboSchedule(JSON.stringify(combo));\n            }\n        } catch { bridge.showToast(\"时间段或组合作息导入异常，已跳过。\"); }\n\n        bridge.showToast(`成功导入 ${courses.length} 条课程`);\n        bridge.notifyTaskCompletion();\n    } catch (e) { bridge.showToast(\"异常: \" + e.message); }\n})();","NANKAI":"// 南开大学（研究生）教育综合管理系统 拾光课程表适配脚本\n// 适用系统: https://yjs.nankai.edu.cn/   入口: 培养 → 个人课表 (py/page/student/grkcb.htm)\n//\n// 要点:\n//   1. 服务端渲染(JSP)输出表格, 无 JSON 接口, 只能解析 DOM;\n//   2. 表格按「周次」分周渲染, 同一门课只在它真正上课的那一周出现 —— 逐周抓取第 1 ~ N 周, 每周抓\n//      到什么就记一条 weeks=[N] 的原子记录; 跨周合并 / 连续节次合并 / 去重交给官方函数处理;\n//   3. 只抓一次不带参数的课表页: 学年 / 学期 / 周次三个 <select>（选中项即学校默认学期）与作息\n//      说明都在这一份响应里; 学年学期不给用户挑, 确认框列出学年 / 学期 / 开学日期后直接导入。\n//\n// 维护者: Cure   |   出现问题请提 issues 或提交 PR\n\n/* 包在 IIFE 里: 不污染教务页面全局, 重复注入时顶层 const 也不会重复声明（函数体不再缩进一级）。 */\n(function () {\n'use strict';\n\n/* ============================ 常量 ============================ */\n\n// 课表页路径（系统内所有页面均为 /<模块>/page/<角色>/<页面>.htm 结构）\nconst NKU_KB_PAGE = '/py/page/student/grkcb.htm';\n\n// 逐周抓取的并发数（同一 JSP 会话并发过高会被串行化, 3 比较稳）\nconst NKU_FETCH_CONCURRENCY = 3;\n\n// 兜底作息: 正常从课表页正文解析, 这里只作解析失败（页面改版）时的保底; 下标 + 1 即节次\nconst NKU_FALLBACK_TIME_SLOTS = [\n    '08:00-08:45', '08:55-09:40', '10:00-10:45', '10:55-11:40', '12:00-12:45',\n    '12:55-13:40', '14:00-14:45', '14:55-15:40', '16:00-16:45', '16:55-17:40',\n    '18:30-19:15', '19:25-20:10', '20:20-21:05', '21:15-22:00'\n].map((range, index) => {\n    const [startTime, endTime] = range.split('-');\n    return { number: index + 1, startTime, endTime };\n});\n\n// 开学日期（第 1 周周一）推算基准 = [月, 日, 年偏移]: 取基准日当天或之后的第一个周一（系统无校历）\nconst NKU_TERM_BASE = {\n    '11': [9, 1, 0],  // 第一学期: 当年 9 月 1 日\n    '12': [2, 20, 1], // 第二学期: 次年 2 月 20 日\n    '13': [7, 1, 0]   // 短学期:   当年 7 月 1 日\n};\n\n/* ============================ 通用工具 ============================ */\n\nconst CN_DIGITS = { 零: 0, 一: 1, 二: 2, 两: 2, 三: 3, 四: 4, 五: 5, 六: 6, 七: 7, 八: 8, 九: 9 };\n\n/** 中文数字 -> 整数（支持 一 ~ 九十九）; 无法解析返回 NaN */\nfunction cnToInt(text) {\n    const s = String(text || '').replace(/\\s/g, '');\n    if (!s) return NaN;\n    if (s === '十') return 10;\n    if (s.length === 1) return Object.prototype.hasOwnProperty.call(CN_DIGITS, s) ? CN_DIGITS[s] : NaN;\n    const idx = s.indexOf('十');\n    if (idx === -1) return NaN;\n    const high = idx === 0 ? 1 : CN_DIGITS[s[idx - 1]];\n    const low = idx === s.length - 1 ? 0 : CN_DIGITS[s[idx + 1]];\n    return (high === undefined || low === undefined) ? NaN : high * 10 + low;\n}\n\n/** 规整空白与全角空格 */\nfunction normalizeText(text) {\n    return String(text == null ? '' : text).replace(/\\u00a0/g, ' ').replace(/\\s+/g, ' ').trim();\n}\n\n/** \"8:00\" / \"08:00:00\" -> \"08:00\"; 非法返回 null */\nfunction formatTime(value) {\n    const match = typeof value === 'string' ? value.match(/^(\\d{1,2}):(\\d{1,2})(?::\\d{1,2})?$/) : null;\n    if (!match) return null;\n    const hour = Number(match[1]);\n    const minute = Number(match[2]);\n    if (hour > 23 || minute > 59) return null;\n    return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;\n}\n\n/** \"08:45\" -> 525; 非法返回 -1 */\nfunction timeToMinutes(value) {\n    const t = formatTime(value);\n    return t ? Number(t.slice(0, 2)) * 60 + Number(t.slice(3)) : -1;\n}\n\n/** 日期 -> \"YYYY-MM-DD\" */\nfunction formatDate(date) {\n    const pad = n => String(n).padStart(2, '0');\n    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;\n}\n\n/* ============================ 桥接层 ============================ */\n\nfunction showToast(message) {\n    try { window.shiguangBridge.showToast(message); } catch { /* 提示失败不打断导入 */ }\n}\n\nfunction notifyTaskCompletion() {\n    try { window.shiguangBridge.notifyTaskCompletion(); } catch { /* 结束信号交给宿主处理 */ }\n}\n\nconst bridgeSupports = method =>\n    !!(window.shiguangBridgePromise && typeof window.shiguangBridgePromise[method] === 'function');\n\n/* ============================ 页面解析 ============================ */\n\n/** 把表格展开成二维网格, 正确处理 rowspan / colspan（课表用 rowspan 跨节次） */\nfunction buildTableGrid(table) {\n    const grid = [];\n    const occupied = [];\n\n    Array.from(table.querySelectorAll('tr')).forEach((tr, rowIndex) => {\n        let col = 0;\n        Array.from(tr.children).forEach(cell => {\n            const tag = (cell.tagName || '').toLowerCase();\n            if (tag !== 'td' && tag !== 'th') return;\n\n            while (occupied[rowIndex] && occupied[rowIndex][col]) col++;\n            const colspan = Math.max(parseInt(cell.getAttribute('colspan') || '1', 10) || 1, 1);\n            const rowspan = Math.max(parseInt(cell.getAttribute('rowspan') || '1', 10) || 1, 1);\n\n            for (let i = 0; i < rowspan; i++) {\n                const r = rowIndex + i;\n                grid[r] = grid[r] || [];\n                occupied[r] = occupied[r] || [];\n                for (let j = 0; j < colspan; j++) {\n                    if (!i && !j) grid[r][col] = cell;\n                    occupied[r][col + j] = true;\n                }\n            }\n            col += colspan;\n        });\n    });\n\n    return grid;\n}\n\n/** 表头形如 <th colspan=\"2\">时间</th><th>星期一</th>… -> { 列下标: 星期(1~7) } */\nfunction findDayColumns(grid) {\n    const dayChars = '一二三四五六日';\n    const map = {};\n    (grid[0] || []).forEach((cell, col) => {\n        if (!cell) return;\n        const match = normalizeText(cell.textContent).replace(/\\s/g, '').match(/^星期([一二三四五六日天])$/);\n        if (!match) return;\n        const day = dayChars.indexOf(match[1] === '天' ? '日' : match[1]) + 1;\n        if (day >= 1 && day <= 7) map[col] = day;\n    });\n    return map;\n}\n\n/** 课表主表格 */\nfunction findTimetable(doc) {\n    const direct = doc.querySelector('table.table-course');\n    if (direct && /星期/.test(direct.textContent || '')) return direct;\n\n    return Array.from(doc.querySelectorAll('table')).find(table =>\n        /星期一/.test(table.textContent || '') && /第\\s*\\d+\\s*节/.test(table.textContent || '')) || null;\n}\n\n/** 单元格里的 <a> -> 按行切分的文本数组（<br> 视为换行）: 课程名 / 周次说明 / 第X节 -- 第Y节 / 教师 / 地点 */\nfunction anchorToLines(anchor) {\n    const clone = anchor.cloneNode(true);\n    Array.from(clone.querySelectorAll('br')).forEach(br => {\n        br.parentNode.replaceChild(document.createTextNode('\\n'), br);\n    });\n    return String(clone.textContent || '').replace(/\\u00a0/g, ' ').split('\\n')\n        .map(line => normalizeText(line)).filter(Boolean);\n}\n\n/** 解析一个课程链接 -> { name, teacher, position, day, startSection, endSection }\n *  周次不在这里判断: 抓取哪一周, 这条记录就属于哪一周（见 crawlAllWeeks 的原子化） */\nfunction parseCourseAnchor(anchor, day) {\n    const lines = anchorToLines(anchor);\n    const strong = anchor.querySelector('strong');\n    let name = normalizeText(strong ? strong.textContent : '') || normalizeText(lines[0] || '');\n    name = name.replace(/^[|\\s]+/, '');\n    if (!name) return null;\n\n    // 「第X节 -- 第Y节」所在行\n    const sectionIdx = lines.findIndex(line => /第\\s*\\d+\\s*节/.test(line));\n    if (sectionIdx < 0) return null;\n\n    const numbers = (lines[sectionIdx].match(/第\\s*(\\d+)\\s*节/g) || [])\n        .map(token => Number(token.replace(/\\D/g, ''))).filter(num => num > 0);\n    if (!numbers.length) return null;\n\n    // 教师 / 地点紧随节次行; 有些课程没有独立教师行, 此时第一行其实是地点\n    let teacher = normalizeText(lines[sectionIdx + 1] || '');\n    let position = normalizeText(lines[sectionIdx + 2] || '');\n    if (!position && /楼|室|馆|场地|校区|通知|待定/.test(teacher)) {\n        position = teacher;\n        teacher = '';\n    }\n\n    if (!(day >= 1 && day <= 7)) return null;\n    return {\n        name,\n        teacher,\n        position: position || '待定',\n        day,\n        startSection: Math.min.apply(null, numbers),\n        endSection: Math.max.apply(null, numbers)\n    };\n}\n\n/** 解析某一周课表页面里的所有课程; null 表示页面里找不到课表（可能登录已失效） */\nfunction parseTimetableDoc(doc) {\n    const table = findTimetable(doc);\n    if (!table) return null;\n\n    const grid = buildTableGrid(table);\n    const dayColumns = findDayColumns(grid);\n    const colKeys = Object.keys(dayColumns);\n    if (colKeys.length === 0) return null;\n\n    const courses = [];\n    for (let row = 1; row < grid.length; row++) {\n        colKeys.forEach(key => {\n            const cell = grid[row] ? grid[row][Number(key)] : null;\n            if (!cell) return;\n            // 同一格可能塞了多门课（冲突课程）, 逐个解析\n            Array.from(cell.querySelectorAll('a'))\n                .filter(anchor => /第\\s*\\d+\\s*节/.test(anchor.textContent || ''))\n                .forEach(anchor => {\n                    const course = parseCourseAnchor(anchor, dayColumns[key]);\n                    if (course) courses.push(course);\n                });\n        });\n    }\n    return courses;\n}\n\n/** 从页面底部说明文字解析作息时间, 形如 \"上午:第一节 8:00-8:45 第二节8:55-9:40 …\"\n *  时间段必须从 1 开始且编号连续, 否则返回 null 交给兜底表 */\nfunction parseTimeSlotsFromDoc(doc) {\n    const bodyText = doc && doc.body ? doc.body.textContent || '' : '';\n    if (!bodyText) return null;\n\n    const normalized = bodyText\n        .replace(/[：]/g, ':')\n        .replace(/[–—~～至]/g, '-')\n        .replace(/\\s+/g, ' ');\n    const pattern = /第([一二三四五六七八九十]+)节?:?\\s*(\\d{1,2}:\\d{2})\\s*-\\s*(\\d{1,2}:\\d{2})/g;\n    const collected = new Map();\n    let match;\n\n    while ((match = pattern.exec(normalized)) !== null) {\n        const number = cnToInt(match[1]);\n        const startTime = formatTime(match[2]);\n        const endTime = formatTime(match[3]);\n        if (!number || !startTime || !endTime) continue;\n        if (timeToMinutes(startTime) >= timeToMinutes(endTime)) continue;\n        collected.set(number, { number, startTime, endTime });\n    }\n\n    const slots = Array.from(collected.values()).sort((a, b) => a.number - b.number);\n    if (!slots.length) return null;\n    return slots.every((slot, index) => slot.number === index + 1) ? slots : null;\n}\n\n/* ============================ 合并与去重（官方参考实现）============================ */\n\n/** 拾光官方《课程合并与去重函数》的参考实现, 照搬（只精简了注释）:\n *  https://github.com/XingHeYuZhuan/shiguangschedule/wiki/课程合并与去重函数\n *  输入 / 输出都是原子课程 { name, teacher, position, day, startSection, endSection, weeks } */\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    const list = courses.map(course => Object.assign({}, course, {\n        name: course.name || '',\n        teacher: course.teacher || '',\n        position: course.position || '',\n        weeks: Array.isArray(course.weeks) ? [].concat(course.weeks).sort((a, b) => a - b) : []\n    }));\n\n    // 阶段 1: 合并连续节次与完全重复的记录（前提: 名称 / 教师 / 地点 / 星期 / 周次一致）\n    list.sort((a, b) =>\n        a.name.localeCompare(b.name) ||\n        a.teacher.localeCompare(b.teacher) ||\n        a.position.localeCompare(b.position) ||\n        (a.day || 0) - (b.day || 0) ||\n        a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n        (a.startSection || 0) - (b.startSection || 0));\n\n    const withSections = [];\n    let current = list[0];\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n        const sameWeeks = current.name === next.name\n            && current.teacher === next.teacher\n            && current.position === next.position\n            && current.day === next.day\n            && current.weeks.join(',') === next.weeks.join(',');\n        if (sameWeeks && current.endSection + 1 === next.startSection) {\n            current.endSection = next.endSection;\n        } else if (sameWeeks && current.startSection === next.startSection && current.endSection === next.endSection) {\n            continue;\n        } else {\n            withSections.push(current);\n            current = next;\n        }\n    }\n    withSections.push(current);\n\n    // 阶段 2: 合并同节次的周次（前提: 名称 / 教师 / 地点 / 星期 / 起止节次一致）\n    withSections.sort((a, b) =>\n        a.name.localeCompare(b.name) ||\n        a.teacher.localeCompare(b.teacher) ||\n        a.position.localeCompare(b.position) ||\n        (a.day || 0) - (b.day || 0) ||\n        (a.startSection || 0) - (b.startSection || 0) ||\n        (a.endSection || 0) - (b.endSection || 0));\n\n    const merged = [];\n    let head = withSections[0];\n    for (let i = 1; i < withSections.length; i++) {\n        const next = withSections[i];\n        const sameSection = head.name === next.name\n            && head.teacher === next.teacher\n            && head.position === next.position\n            && head.day === next.day\n            && head.startSection === next.startSection\n            && head.endSection === next.endSection;\n        if (sameSection) {\n            head.weeks = Array.from(new Set([].concat(head.weeks, next.weeks))).sort((a, b) => a - b);\n        } else {\n            merged.push(head);\n            head = next;\n        }\n    }\n    merged.push(head);\n\n    return merged;\n}\n\n/* ============================ 列表读取与抓取 ============================ */\n\n/** <select> 的选项 -> [{ value, label, selected }] */\nfunction readSelectOptions(selectEl) {\n    if (!selectEl) return [];\n    return Array.from(selectEl.querySelectorAll('option'))\n        .map(option => ({\n            value: normalizeText(option.value),\n            label: normalizeText(option.textContent || option.value),\n            selected: option.selected === true || option.hasAttribute('selected')\n        }))\n        .filter(option => option.value !== '');\n}\n\n/** 页面已选中的选项值; 没有选中项时返回空串 */\nfunction selectedValue(options) {\n    const selected = options.find(option => option.selected);\n    return selected ? selected.value : '';\n}\n\n/** 文档是否为本系统的课表页 —— 用来区分「这一周没课」和「登录失效 / 请求被拦」 */\nconst looksLikeCoursePage = doc =>\n    !!(doc && (doc.querySelector('#kcbForm') || doc.querySelector('#zc') || doc.querySelector('#xn')));\n\n/** 课表页地址; 不带任何参数即为系统默认的当前学期 */\nconst kbPageUrl = (xn, xj, zc) =>\n    `${NKU_KB_PAGE}?xn=${encodeURIComponent(xn)}&xj=${encodeURIComponent(xj)}&zc=${encodeURIComponent(zc)}`;\n\n/** 抓一个页面并解析成 DOM。请求失败 / 状态异常一律抛出, 由调用方统一按「没抓到」处理 */\nasync function fetchCourseDoc(url) {\n    const response = await fetch(url, { method: 'GET', credentials: 'include' });\n    if (!response.ok) throw new Error('页面请求失败');\n    return new DOMParser().parseFromString(await response.text(), 'text/html');\n}\n\n/** 简单的并发池 */\nasync function runWithConcurrency(tasks, limit) {\n    const results = new Array(tasks.length);\n    let cursor = 0;\n    const worker = async () => {\n        while (cursor < tasks.length) {\n            const index = cursor++;\n            results[index] = await tasks[index]();\n        }\n    };\n    await Promise.all(Array.from({ length: Math.min(limit, tasks.length) }, worker));\n    return results;\n}\n\n/** 逐周抓取: 第 N 周抓到的每门课都记成一条原子记录（weeks = [N]）, 不做任何归并。\n *  返回 { courses, okWeeks }; okWeeks = 成功取到课表页的周次数（0 表示整轮都没抓到）。 */\nasync function crawlAllWeeks(xn, xj, weeks) {\n    const tasks = weeks.map(week => async () => {\n        try {\n            const doc = await fetchCourseDoc(kbPageUrl(xn, xj, week));\n            const list = parseTimetableDoc(doc);\n            if (list) return { week, list };\n            // 是本系统的课表页却没有表格 —— 多为超出本学期周次范围, 按当周无课处理\n            return looksLikeCoursePage(doc) ? { week, list: [] } : null;\n        } catch {\n            return null;\n        }\n    });\n\n    const courses = [];\n    let okWeeks = 0;\n\n    (await runWithConcurrency(tasks, NKU_FETCH_CONCURRENCY)).forEach(result => {\n        if (!result) return;\n        okWeeks++;\n        result.list.forEach(course => courses.push(Object.assign({}, course, { weeks: [result.week] })));\n    });\n\n    return { courses, okWeeks };\n}\n\n/* ============================ 页面读取与确认 ============================ */\n\n/** 取某个值在选项里的显示文本（学年形如 2026-2027, 学期形如 第一学期）; 找不到就用原始值 */\nconst labelOf = (options, value) => (options.find(option => option.value === value) || {}).label || value;\n\n/** 第 1 周周一 = 基准日当天或之后的第一个周一; 学期代码认不出来时按第一学期 */\nfunction guessStartDate(xn, xj) {\n    const [month, day, offset] = NKU_TERM_BASE[String(xj)] || NKU_TERM_BASE['11'];\n    const date = new Date((Number(xn) || new Date().getFullYear()) + offset, month - 1, day);\n    date.setDate(date.getDate() + (8 - date.getDay()) % 7); // 当天就是周一则不动\n    return formatDate(date);\n}\n\n/** 抓一次不带参数的课表页, 一次读齐: 学年与学期的值及显示文本（页面选中项 = 学校当前学期）、\n *  周次列表、作息时间、按学期规则推算的开学日期。读不到下拉框（登录失效 / 页面改版）返回 null */\nasync function loadCoursePage() {\n    let doc;\n    try {\n        doc = await fetchCourseDoc(NKU_KB_PAGE);\n    } catch {\n        return null;\n    }\n\n    const xnOptions = readSelectOptions(doc.querySelector('#xn'));\n    const xjOptions = readSelectOptions(doc.querySelector('#xj'));\n    const weeks = readSelectOptions(doc.querySelector('#zc'))\n        .map(option => Number(option.value)).filter(value => value > 0);\n    const xn = selectedValue(xnOptions);\n    const xj = selectedValue(xjOptions);\n    if (!xn || !xj || !weeks.length) return null;\n\n    return {\n        xn,\n        xj,\n        xnLabel: labelOf(xnOptions, xn),\n        xjLabel: labelOf(xjOptions, xj),\n        startDate: guessStartDate(xn, xj),\n        weeks,\n        timeSlots: parseTimeSlotsFromDoc(doc)\n    };\n}\n\n/** 导入信息确认框: 列出学年 / 学期 / 开学日期, 只能确认或关掉（关掉 = 放弃导入） */\nasync function confirmTerm(page) {\n    if (!bridgeSupports('showAlert')) return true;\n\n    const content = '即将导入以下内容，请确认：\\n\\n'\n        + `　学年　　　${page.xnLabel}\\n`\n        + `　学期　　　${page.xjLabel}\\n`\n        + `　开学日期　${page.startDate}（周一）\\n\\n`\n        + '学年与学期取自教务系统的默认学期，开学日期按学期规则推算。';\n    try {\n        return await window.shiguangBridgePromise.showAlert('确认导入信息', content, '开始导入') === true;\n    } catch {\n        return true;\n    }\n}\n\n/* ============================ 保存 ============================ */\n\n/** 调用桥接层的保存接口; 失败时给一句笼统提示（不带原始异常）并返回 false */\nasync function saveVia(method, payload, failMessage) {\n    try {\n        await window.shiguangBridgePromise[method](JSON.stringify(payload));\n        return true;\n    } catch {\n        showToast(failMessage);\n        return false;\n    }\n}\n\n/** 从作息时间推算单节课与课间时长, 用于课表配置 */\nfunction deriveDurations(timeSlots) {\n    const fallback = { classDuration: 45, breakDuration: 10 };\n    if (!Array.isArray(timeSlots) || timeSlots.length < 2) return fallback;\n\n    const classDuration = timeToMinutes(timeSlots[0].endTime) - timeToMinutes(timeSlots[0].startTime);\n    const breakDuration = timeToMinutes(timeSlots[1].startTime) - timeToMinutes(timeSlots[0].endTime);\n    return (classDuration > 0 && breakDuration >= 0) ? { classDuration, breakDuration } : fallback;\n}\n\n/* ============================ 主流程 ============================ */\n\nasync function importFlow() {\n    // 1. 抓一次无参课表页: 学年学期默认值、周次列表、作息时间都出在这一份响应里; 抓不到即中止\n    const page = await loadCoursePage();\n    if (!page) {\n        showToast('导入失败：未获取到课表数据，请重新登录后重试。');\n        return;\n    }\n\n    // 2. 确认框: 列出学年 / 学期 / 开学日期, 只能确认或关掉\n    if (!await confirmTerm(page)) {\n        showToast('已取消导入。');\n        return;\n    }\n\n    // 3. 逐周抓取 -> 原子课程 -> 交给官方函数合并去重\n    const crawl = await crawlAllWeeks(page.xn, page.xj, page.weeks);\n    if (!crawl.okWeeks) {\n        showToast('导入失败：未获取到课表数据，请重新登录后重试。');\n        return;\n    }\n    if (!crawl.courses.length) {\n        showToast('未查询到课程，请确认所选学年学期是否正确。');\n        return;\n    }\n    const courses = mergeAndDistinctCourses(crawl.courses);\n\n    // 4. 保存: 课程 -> 作息时间 -> 课表配置\n    const timeSlots = page.timeSlots || NKU_FALLBACK_TIME_SLOTS;\n    if (!await saveVia('saveImportedCourses', courses, '课程保存失败')) return;\n    await saveVia('savePresetTimeSlots', timeSlots, '导入作息时间失败');\n\n    // 开学日期用推算出来的第 1 周周一\n    const durations = deriveDurations(timeSlots);\n    await saveVia('saveCourseConfig', {\n        semesterStartDate: page.startDate,\n        semesterTotalWeeks: courses.reduce((max, course) => Math.max(max, ...course.weeks), 1),\n        defaultClassDuration: durations.classDuration,\n        defaultBreakDuration: durations.breakDuration,\n        firstDayOfWeek: 1\n    }, '保存课表配置失败');\n\n    // 5. 完成\n    notifyTaskCompletion();\n}\n\n/* ============================ 入口 ============================ */\n\n// 宿主在用户点击「开始导入」后注入本脚本, 所以顶层直接启动: 抓一次课表页 -> 确认框 -> 逐周抓取\nimportFlow();\n\n})();\n","SUSTECH":"// 南方科技大学 TIS 教学管理与服务平台 课表导入适配器\n//\n// 依赖的 TIS 接口（均为登录后同域请求，凭证由 WebView 自动携带）：\n//   POST /component/querydangqianxnxq        当前学年学期 { XN, XQ, XNXQ }\n//   POST /cjgl/grcjcx/grcjcx                 历年课程记录（用于生成可选学期列表）\n//   POST /xszykb/queryxszykbzong             整学期课表（xn, xq）\n//   POST /component/queryKbjg                作息时间（xn, xq, zc）\n//   POST /component/querydangqianzc          当前教学周（纯数字文本）\n//\n// 课表条目关键字段（2026 秋实测）：\n//   KEY   \"xq1_jc5\"  -> 星期 1（周一），jc 为课表网格行号（非节次）\n//   KSJC / JSJC      起始 / 结束节次（真正的节次）\n//   ZC               0/1 位图，下标即周次（下标 0 未使用）\n//   SKSJ             多行文本：课程名 / [教师] / [班级] / [周次][地点][节次]\n//   KCWZSM / SKFS 等 实测为 null，仅作兜底\n\n// ========================================\n// 常量\n// ========================================\n\n// 教务系统未返回作息时间时的兜底节次时间（南科大常规作息）\nconst FALLBACK_TIME_SLOTS = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:50\" },\n    { number: 2, startTime: \"09:00\", endTime: \"09:50\" },\n    { number: 3, startTime: \"10:20\", endTime: \"11:10\" },\n    { number: 4, startTime: \"11:20\", endTime: \"12:10\" },\n    { number: 5, startTime: \"14:00\", endTime: \"14:50\" },\n    { number: 6, startTime: \"15:00\", endTime: \"15:50\" },\n    { number: 7, startTime: \"16:20\", endTime: \"17:10\" },\n    { number: 8, startTime: \"17:20\", endTime: \"18:10\" },\n    { number: 9, startTime: \"19:00\", endTime: \"19:50\" },\n    { number: 10, startTime: \"20:00\", endTime: \"20:50\" },\n    { number: 11, startTime: \"21:20\", endTime: \"22:10\" },\n    { number: 12, startTime: \"22:20\", endTime: \"23:10\" }\n];\n\nconst CONFIG_BASE = {\n    semesterTotalWeeks: 18,\n    defaultClassDuration: 50,\n    defaultBreakDuration: 10\n};\n\n// ========================================\n// 网络请求\n// ========================================\n\nasync function postFormRaw(path, params) {\n    const body = new URLSearchParams();\n\n    Object.keys(params || {}).forEach(function (key) {\n        const value = params[key];\n        body.append(key, value === null || value === undefined ? \"\" : String(value));\n    });\n\n    const response = await fetch(path, {\n        method: \"POST\",\n        credentials: \"include\",\n        headers: {\n            \"Content-Type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        body: body.toString()\n    });\n\n    if (!response.ok) {\n        throw new Error(`请求 ${path} 失败：HTTP ${response.status}`);\n    }\n\n    return await response.text();\n}\n\nasync function postForm(path, params) {\n    const text = await postFormRaw(path, params);\n    return parseJsonSafely(text, path);\n}\n\nasync function postJson(path, payload) {\n    const response = await fetch(path, {\n        method: \"POST\",\n        credentials: \"include\",\n        headers: {\n            \"Content-Type\": \"application/json\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        body: JSON.stringify(payload || {})\n    });\n\n    if (!response.ok) {\n        throw new Error(`请求 ${path} 失败：HTTP ${response.status}`);\n    }\n\n    return parseJsonSafely(await response.text(), path);\n}\n\nfunction parseJsonSafely(text, path) {\n    const trimmed = (text || \"\").trim();\n\n    if (!trimmed) {\n        return null;\n    }\n\n    if (trimmed.charAt(0) === \"<\") {\n        throw new Error(\"登录状态已失效，请重新登录本科教务系统后再导入。\");\n    }\n\n    // 会话失效时 TIS 会返回登录提示页（HTML 或带\"登录\"字样的 JSON）\n    if (/重新登录|请登录|用户认证|登录已过期/.test(trimmed)) {\n        throw new Error(\"登录状态已失效，请重新登录教务系统后再导入。\");\n    }\n\n    try {\n        return JSON.parse(trimmed);\n    } catch (error) {\n        throw new Error(\n            `教务系统返回了非 JSON 内容，请确认已登录本科教务系统（${path}）。`\n        );\n    }\n}\n\n// 取数组型数据：接口可能直接返回数组，也可能包在 content / data 里\nfunction toArray(data) {\n    if (Array.isArray(data)) {\n        return data;\n    }\n\n    if (data && Array.isArray(data.content)) {\n        return data.content;\n    }\n\n    if (data && Array.isArray(data.data)) {\n        return data.data;\n    }\n\n    return [];\n}\n\n// ========================================\n// 学期信息\n// ========================================\n\nasync function fetchCurrentSemester() {\n    const data = await postForm(\"/component/querydangqianxnxq\", {});\n\n    if (!data || !data.XN || !data.XQ) {\n        throw new Error(\"未能获取学年学期，请确认已登录本科教务系统。\");\n    }\n\n    return {\n        xn: String(data.XN),\n        xq: String(data.XQ),\n        label: data.XNXQ || `${data.XN}学年第${data.XQ}学期`\n    };\n}\n\n// 通过成绩/选课接口拿到该学生有记录的所有学期，作为可选列表\nasync function fetchSemesterOptions() {\n    const options = [];\n    const seen = {};\n\n    try {\n        const data = await postJson(\"/cjgl/grcjcx/grcjcx\", {\n            xn: null,\n            xq: null,\n            kcmc: null,\n            cxbj: \"-1\",\n            pylx: \"1\",\n            current: 1,\n            pageSize: 500\n        });\n\n        const rows = (data && data.content && data.content.list) || [];\n\n        rows.forEach(function (row) {\n            addSemesterOption(options, seen, row && row.xnxq, row && row.xnxqmc);\n        });\n    } catch (error) {\n        // 拿不到历史学期列表时不阻塞流程，调用方会退回\"仅当前学期\"\n        return options;\n    }\n\n    return options;\n}\n\nfunction addSemesterOption(options, seen, xnxq, label) {\n    const matched = String(xnxq || \"\").match(/^(\\d{4}-\\d{4})(\\d)$/);\n\n    if (!matched) {\n        return;\n    }\n\n    const xn = matched[1];\n    const xq = matched[2];\n    const key = `${xn}-${xq}`;\n\n    if (seen[key]) {\n        return;\n    }\n\n    seen[key] = true;\n    options.push({ xn: xn, xq: xq, key: key, label: label || key });\n}\n\nfunction mergeCurrentSemester(options, current) {\n    const key = `${current.xn}-${current.xq}`;\n    const exists = options.some(function (item) {\n        return item.key === key;\n    });\n\n    if (!exists) {\n        options.push({\n            xn: current.xn,\n            xq: current.xq,\n            key: key,\n            label: current.label\n        });\n    }\n\n    options.sort(function (a, b) {\n        return b.key < a.key ? -1 : 1;\n    });\n\n    return options;\n}\n\n// ========================================\n// 用户交互\n// ========================================\n\nfunction validateDateInput(input) {\n    const text = String(input || \"\").trim();\n\n    if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(text)) {\n        return \"请输入 YYYY-MM-DD 格式的日期！\";\n    }\n\n    const date = new Date(`${text}T00:00:00`);\n\n    if (isNaN(date.getTime())) {\n        return \"请输入有效的日期！\";\n    }\n\n    return false;\n}\n\nasync function confirmStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"导入说明\",\n        \"本适配用于导入南方科技大学 TIS 本科教务系统的课表。\\n请先完成 CAS 登录并停留在教务系统页面内，再点击确认开始导入。\",\n        \"开始导入\"\n    );\n}\n\nasync function selectSemester(options, current) {\n    if (!options.length) {\n        return { xn: current.xn, xq: current.xq, key: `${current.xn}-${current.xq}` };\n    }\n\n    const labels = options.map(function (item) {\n        return `${item.label}（${item.xn}学年第${item.xq}学期）`;\n    });\n\n    const defaultIndex = options.findIndex(function (item) {\n        return item.key === `${current.xn}-${current.xq}`;\n    });\n\n    const index = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(labels),\n        defaultIndex >= 0 ? defaultIndex : 0\n    );\n\n    if (index === null || index < 0 || index >= options.length) {\n        return null;\n    }\n\n    return options[index];\n}\n\nasync function askSemesterStartDate(defaultValue) {\n    const input = await window.shiguangBridgePromise.showPrompt(\n        \"学期开始日期\",\n        \"该学期不是当前学期，无法自动推算周次。\\n请输入该学期第 1 周星期一的日期：\",\n        defaultValue,\n        \"validateDateInput\"\n    );\n\n    if (input === null) {\n        return null;\n    }\n\n    return String(input).trim();\n}\n\n// ========================================\n// 课表数据与作息时间\n// ========================================\n\nasync function fetchTimeSlots(xn, xq) {\n    try {\n        const data = await postForm(\"/component/queryKbjg\", { xn: xn, xq: xq, zc: \"1\" });\n        const slots = toArray(data).map(function (item) {\n            const number = toNumber(item.xj);\n            const startTime = normalizeTime(item.kssj);\n            const endTime = normalizeTime(item.jssj);\n\n            if (!number || !startTime || !endTime) {\n                return null;\n            }\n\n            return { number: number, startTime: startTime, endTime: endTime };\n        }).filter(Boolean);\n\n        if (slots.length) {\n            slots.sort(function (a, b) {\n                return a.number - b.number;\n            });\n            return slots;\n        }\n    } catch (error) {\n        // 忽略，使用兜底作息\n    }\n\n    return FALLBACK_TIME_SLOTS.slice();\n}\n\nasync function fetchCourses(xn, xq) {\n    const data = await postForm(\"/xszykb/queryxszykbzong\", { xn: xn, xq: xq });\n    const rows = toArray(data);\n\n    if (!rows.length) {\n        throw new Error(\"教务系统未返回课表数据，请确认该学期已选课。\");\n    }\n\n    return parseCourses(rows);\n}\n\nfunction parseCourses(rows) {\n    const courses = [];\n    const seen = {};\n\n    rows.forEach(function (row) {\n        const course = parseCourse(row);\n\n        if (!course) {\n            return;\n        }\n\n        const identity = [\n            course.name,\n            course.day,\n            course.startSection,\n            course.endSection,\n            course.weeks.join(\",\"),\n            course.teacher,\n            course.position\n        ].join(\"|\");\n\n        // 同一节课会在课表网格中占多行（KEY 的 jc 不同），需要去重\n        if (seen[identity]) {\n            return;\n        }\n\n        seen[identity] = true;\n        courses.push(course);\n    });\n\n    return courses;\n}\n\nfunction parseCourse(row) {\n    if (!row || typeof row !== \"object\") {\n        return null;\n    }\n\n    const keyMatch = String(row.KEY || \"\").match(/xq(\\d+)_jc(\\d+)/i);\n    const day = keyMatch ? toNumber(keyMatch[1]) : null;\n\n    if (!day || day < 1 || day > 7) {\n        return null;\n    }\n\n    const detail = parseScheduleText(row.SKSJ || row.SKSJ_EN);\n\n    // 真实数据中 KCWZSM 为 null，课程信息以 SKSJ 为准\n    const name = firstText(detail.name, row.KCMC, row.KCWZSM);\n\n    if (!name) {\n        return null;\n    }\n\n    // jc 只是网格行号，真实节次用 KSJC / JSJC\n    const slotIndex = keyMatch ? toNumber(keyMatch[2]) : null;\n    const startSection = toNumber(row.KSJC) || slotIndex;\n    const endSection = toNumber(row.JSJC) || startSection;\n    const weeks = parseWeekBitmap(row.ZC, detail.declaredWeeks);\n\n    if (!startSection || !endSection || endSection < startSection || !weeks.length) {\n        return null;\n    }\n\n    return {\n        name: name,\n        teacher: firstText(detail.teacher, row.SKJS, row.JSXM, row.DGJSMC),\n        position: firstText(detail.position, row.SKDD, row.JXCDMC, row.SKDDMC),\n        day: day,\n        startSection: startSection,\n        endSection: endSection,\n        weeks: weeks\n    };\n}\n\n// ZC 是 0/1 位图，实测下标即周次（下标 0 未使用）。\n// 为兼容不同学期的差异，同时算出两种解释，用 SKSJ 里声明的周次（如 [1-16周]）校准。\nfunction parseWeekBitmap(value, declaredWeeks) {\n    const bitmap = String(value || \"\");\n\n    if (!/^[01]+$/.test(bitmap)) {\n        return declaredWeeks || [];\n    }\n\n    function build(shift) {\n        const weeks = [];\n\n        for (let index = 0; index < bitmap.length; index += 1) {\n            if (bitmap[index] === \"1\") {\n                const week = index + 1 - shift;\n\n                if (week > 0) {\n                    weeks.push(week);\n                }\n            }\n        }\n\n        return weeks;\n    }\n\n    // shift=1：周次 = 下标（教务实际使用的口径）；shift=0：周次 = 下标 + 1\n    const candidates = [build(1), build(0)];\n\n    if (!declaredWeeks || !declaredWeeks.length) {\n        return candidates[0];\n    }\n\n    let best = candidates[0];\n    let bestScore = -1;\n\n    candidates.forEach(function (weeks) {\n        const set = {};\n        weeks.forEach(function (week) {\n            set[week] = true;\n        });\n\n        const score = declaredWeeks.filter(function (week) {\n            return set[week];\n        }).length;\n\n        if (score > bestScore) {\n            bestScore = score;\n            best = weeks;\n        }\n    });\n\n    return best;\n}\n\nconst WEEK_PATTERN = /\\d[\\d,\\-]*(单|双)?周/;      // 1-16周 / 1-15单周 / 1-9,11周\nconst SECTION_PATTERN = /\\d+\\s*(-\\s*\\d+)?\\s*节/;  // 9-10节 / 3节\n\n// 详情行：含周次或节次的那些行，如 [1-16周][一教110][1-2节]、[3-16周]、[教室][1-4节]\nfunction isDetailLine(line) {\n    return WEEK_PATTERN.test(line) || SECTION_PATTERN.test(line);\n}\n\n// 解析 \"1-16周\" / \"1-9,11,13-15周\" / \"1-15单周\" 形式的周次声明\nfunction parseWeekExpression(text) {\n    const matched = String(text).match(WEEK_PATTERN);\n\n    if (!matched) {\n        return [];\n    }\n\n    // 去掉末尾的 \"单周\" / \"双周\" / \"周\"，剩下的就是周次表达式\n    const expression = matched[0].replace(/(单|双)?周$/, \"\");\n    const parity = /单周$/.test(matched[0]) ? \"单\" : (/双周$/.test(matched[0]) ? \"双\" : \"\");\n    const weeks = [];\n\n    expression.split(\",\").forEach(function (part) {\n        const range = part.match(/^(\\d+)(?:-(\\d+))?$/);\n\n        if (!range) {\n            return;\n        }\n\n        const start = Number(range[1]);\n        const end = range[2] ? Number(range[2]) : start;\n\n        for (let week = start; week <= end && week <= 36; week += 1) {\n            weeks.push(week);\n        }\n    });\n\n    const filtered = weeks.filter(function (week) {\n        if (parity === \"单\") {\n            return week % 2 === 1;\n        }\n\n        if (parity === \"双\") {\n            return week % 2 === 0;\n        }\n\n        return true;\n    });\n\n    return uniqueSorted(filtered);\n}\n\n// SKSJ 形如：\n//   思想道德与法治\n//   [兰美荣]\n//   [思想道德与法治-09班-中文]\n//   [1-16周][智华楼207][9-10节]\nfunction parseScheduleText(value) {\n    const lines = String(value || \"\")\n        .replace(/<br\\s*\\/?>/gi, \"\\n\")\n        .replace(/<[^>]+>/g, \"\\n\")\n        .split(\"\\n\")\n        .map(function (line) {\n            return line.trim();\n        })\n        .filter(Boolean);\n\n    const result = { name: \"\", teacher: \"\", position: \"\", declaredWeeks: [] };\n\n    if (!lines.length) {\n        return result;\n    }\n\n    result.name = unwrap(lines[0]);\n\n    lines.slice(1).forEach(function (line) {\n        const groups = bracketGroups(line);\n\n        // 详情行：[1-16周][智华楼207][9-10节]\n        // 注意：不能用 \"含周/含节\" 判断，课程名或教师名里可能有\"周\"字（如\"某单周课\"）\n        if (isDetailLine(line)) {\n            if (!result.declaredWeeks.length) {\n                result.declaredWeeks = parseWeekExpression(line);\n            }\n\n            if (!result.position) {\n                const place = firstMatch(groups, function (part) {\n                    return part && !WEEK_PATTERN.test(part) && !SECTION_PATTERN.test(part) &&\n                        !/班/.test(part) && part !== result.name &&\n                        part.indexOf(result.name) < 0 && result.name.indexOf(part) < 0;\n                });\n\n                if (place) {\n                    result.position = unwrap(place);\n                }\n            }\n\n            return;\n        }\n\n        const text = unwrap(line);\n\n        // 教师行：课程名的下一行，排除班级行（含\"班\"）与课程名本身\n        if (!result.teacher && text && text !== result.name && !/班/.test(text)) {\n            result.teacher = text;\n        }\n    });\n\n    return result;\n}\n\n// ========================================\n// 课表配置（学期开始日期 / 总周数）\n// ========================================\n\nasync function fetchCurrentWeek() {\n    try {\n        const text = (await postFormRaw(\"/component/querydangqianzc\", {})).trim();\n\n        if (/^\\d+$/.test(text)) {\n            return Number(text);\n        }\n    } catch (error) {\n        // 学期未开始时该接口返回空内容\n    }\n\n    return null;\n}\n\n// 本周周一往前推 (当前周 - 1) 周，即为第 1 周周一\nfunction computeSemesterStart(currentWeek) {\n    if (!currentWeek || currentWeek < 1) {\n        return \"\";\n    }\n\n    const now = new Date();\n    const monday = new Date(\n        now.getFullYear(),\n        now.getMonth(),\n        now.getDate() - ((now.getDay() + 6) % 7)\n    );\n\n    monday.setDate(monday.getDate() - (currentWeek - 1) * 7);\n\n    return formatDate(monday);\n}\n\nasync function buildCourseConfig(semester, current, courses) {\n    const maxWeek = courses.reduce(function (max, course) {\n        return Math.max(max, course.weeks[course.weeks.length - 1] || 0);\n    }, 0);\n\n    const config = Object.assign({}, CONFIG_BASE, {\n        semesterTotalWeeks: Math.max(CONFIG_BASE.semesterTotalWeeks, maxWeek)\n    });\n\n    const isCurrent = semester && current && semester.key === `${current.xn}-${current.xq}`;\n    let startDate = isCurrent ? computeSemesterStart(await fetchCurrentWeek()) : \"\";\n\n    if (!startDate) {\n        startDate = await askSemesterStartDate(computeSemesterStart(1));\n\n        if (!startDate) {\n            return null;\n        }\n    }\n\n    config.semesterStartDate = startDate;\n\n    return config;\n}\n\n// ========================================\n// 工具函数\n// ========================================\n\nfunction firstText() {\n    for (let index = 0; index < arguments.length; index += 1) {\n        const value = arguments[index];\n\n        if (value !== null && value !== undefined && String(value).trim() !== \"\") {\n            return String(value).trim();\n        }\n    }\n\n    return \"\";\n}\n\n// 去掉一对包裹的中括号：[兰美荣] -> 兰美荣\nfunction unwrap(value) {\n    return String(value || \"\").trim()\n        .replace(/^\\[/, \"\")\n        .replace(/\\]$/, \"\")\n        .trim();\n}\n\n// 提取一行里所有 [xxx] 的内容\nfunction bracketGroups(line) {\n    const groups = [];\n    const pattern = /\\[([^\\]]*)\\]/g;\n    let matched = pattern.exec(String(line));\n\n    while (matched !== null) {\n        groups.push(matched[1].trim());\n        matched = pattern.exec(String(line));\n    }\n\n    return groups;\n}\n\nfunction firstMatch(list, predicate) {\n    for (let index = 0; index < list.length; index += 1) {\n        if (predicate(list[index])) {\n            return list[index];\n        }\n    }\n\n    return null;\n}\n\nfunction uniqueSorted(numbers) {\n    const seen = {};\n    const result = [];\n\n    numbers.forEach(function (number) {\n        if (!seen[number]) {\n            seen[number] = true;\n            result.push(number);\n        }\n    });\n\n    return result.sort(function (a, b) {\n        return a - b;\n    });\n}\n\nfunction toNumber(value) {\n    if (value === null || value === undefined || value === \"\") {\n        return null;\n    }\n\n    const number = Number(value);\n\n    return Number.isFinite(number) && number > 0 ? number : null;\n}\n\nfunction normalizeTime(value) {\n    const text = String(value || \"\").trim();\n\n    return /^\\d{1,2}:\\d{2}$/.test(text) ? text : \"\";\n}\n\nfunction formatDate(date) {\n    const month = String(date.getMonth() + 1).padStart(2, \"0\");\n    const day = String(date.getDate()).padStart(2, \"0\");\n\n    return `${date.getFullYear()}-${month}-${day}`;\n}\n\nfunction toast(message) {\n    if (window.shiguangBridge && typeof window.shiguangBridge.showToast === \"function\") {\n        window.shiguangBridge.showToast(message);\n    }\n}\n\n// ========================================\n// 主流程\n// ========================================\n\nasync function runImportFlow() {\n    try {\n        if (!window.shiguangBridgePromise) {\n            throw new Error(\"当前环境不支持导入，请在时光课程表 App 内运行。\");\n        }\n\n        const confirmed = await confirmStart();\n\n        if (!confirmed) {\n            toast(\"已取消导入。\");\n            return;\n        }\n\n        toast(\"正在获取学期信息...\");\n\n        const current = await fetchCurrentSemester();\n        const options = mergeCurrentSemester(await fetchSemesterOptions(), current);\n        const semester = await selectSemester(options, current);\n\n        if (!semester) {\n            toast(\"已取消导入。\");\n            return;\n        }\n\n        toast(\"正在获取课表...\");\n\n        const courses = await fetchCourses(semester.xn, semester.xq);\n\n        if (!courses.length) {\n            throw new Error(\"未解析到任何课程，请确认该学期课表已发布。\");\n        }\n\n        const timeSlots = await fetchTimeSlots(semester.xn, semester.xq);\n        const config = await buildCourseConfig(semester, current, courses);\n\n        if (!config) {\n            toast(\"已取消导入。\");\n            return;\n        }\n\n        toast(`正在导入 ${courses.length} 门课程...`);\n\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n\n        toast(`成功导入 ${courses.length} 门课程！`);\n\n        if (window.shiguangBridge && typeof window.shiguangBridge.notifyTaskCompletion === \"function\") {\n            window.shiguangBridge.notifyTaskCompletion();\n        }\n    } catch (error) {\n        toast(`导入失败：${error.message}`);\n    }\n}\n\nrunImportFlow();\n","THDM_01":"// 南昌科技职业大学教务系统适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提联系开发者或者提交pr更改,这更加快速\n\nfunction parseWeeks(str) {\n  if (!str) return [];\n  return String(str).split(',').map(s => s.trim()).reduce((acc, part) => {\n    if (part.includes('-')) {\n      const [start, end] = part.split('-').map(Number);\n      for (let i = start; i <= end; i++) acc.push(i);\n    } else {\n      const n = Number(part);\n      if (!isNaN(n)) acc.push(n);\n    }\n    return acc;\n  }, []).sort((a, b) => a - b);\n}\n\n/**\n * 节次与周次合并去重函数\n */\nfunction mergeAndDistinctCourses(courses) {\n  if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n  // 1. 深拷贝并规范周次数据\n  const list = courses.map(c => ({\n    ...c,\n    name: c.name || '',\n    teacher: c.teacher || '',\n    position: c.position || '',\n    weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n  }));\n\n  // 阶段 1：合并连续节次与完全重复记录\n  list.sort((a, b) => {\n    return a.name.localeCompare(b.name) ||\n      a.teacher.localeCompare(b.teacher) ||\n      a.position.localeCompare(b.position) ||\n      (a.day || 0) - (b.day || 0) ||\n      a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n      (a.startSection || 0) - (b.startSection || 0);\n  });\n\n  const step1 = [];\n  let current = list[0];\n\n  for (let i = 1; i < list.length; i++) {\n    const next = list[i];\n\n    const isSameCourseAndWeeks =\n      current.name === next.name &&\n      current.teacher === next.teacher &&\n      current.position === next.position &&\n      current.day === next.day &&\n      current.weeks.join(',') === next.weeks.join(',');\n\n    const isContinuous = current.endSection + 1 === next.startSection;\n    const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n\n    if (isSameCourseAndWeeks && isContinuous) {\n      current.endSection = next.endSection;\n    } else if (isSameCourseAndWeeks && isDuplicate) {\n      continue;\n    } else {\n      step1.push(current);\n      current = next;\n    }\n  }\n  step1.push(current);\n\n  // 阶段 2：合并同节次的周次\n  step1.sort((a, b) => {\n    return a.name.localeCompare(b.name) ||\n      a.teacher.localeCompare(b.teacher) ||\n      a.position.localeCompare(b.position) ||\n      (a.day || 0) - (b.day || 0) ||\n      (a.startSection || 0) - (b.startSection || 0) ||\n      (a.endSection || 0) - (b.endSection || 0);\n  });\n\n  const step2 = [];\n  let cur = step1[0];\n\n  for (let i = 1; i < step1.length; i++) {\n    const nxt = step1[i];\n\n    const isSameCourseAndSection =\n      cur.name === nxt.name &&\n      cur.teacher === nxt.teacher &&\n      cur.position === nxt.position &&\n      cur.day === nxt.day &&\n      cur.startSection === nxt.startSection &&\n      cur.endSection === nxt.endSection;\n\n    if (isSameCourseAndSection) {\n      cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n    } else {\n      step2.push(cur);\n      cur = nxt;\n    }\n  }\n  step2.push(cur);\n\n  return step2;\n}\n\nasync function runImportFlow() {\n  window.shiguangBridge.showToast(\"课程导入流程即将开始...\");\n\n  const baseUrl = window.location.origin;\n  let semester = '2026-2027-1';\n  let semesterStartDate = '2026-09-01';\n\n  // 获取学期信息\n  try {\n    const semesterRes = await fetch(baseUrl + '/api/baseInfo/semester/selectCurrentXnXq?_t=' + Date.now(), {\n      headers: { 'X-Requested-With': 'XMLHttpRequest' }\n    });\n    const semesterJson = await semesterRes.json();\n    if (semesterJson.code === 200 && semesterJson.data) {\n      semester = semesterJson.data.semester || semester;\n      if (semesterJson.data.ksrq) {\n        semesterStartDate = semesterJson.data.ksrq.split(' ')[0];\n      }\n    }\n  } catch (e) {\n    console.error(\"获取学期信息失败:\", e);\n    window.shiguangBridge.showToast(\"获取学期信息失败，将使用默认值\");\n  }\n\n  // 获取所有周次\n  let weeks = [];\n  try {\n    const qwRes = await fetch(baseUrl + '/api/arrange/teacherServer/queryWeek?schoolYear=' + encodeURIComponent(semester) + '&_t=' + Date.now());\n    const qwJson = await qwRes.json();\n    weeks = qwJson.code === 200 && Array.isArray(qwJson.data) ? qwJson.data : [];\n  } catch (e) {\n    console.error(\"获取周次信息失败:\", e);\n    window.shiguangBridge.showToast(\"获取周次信息失败\");\n    return;\n  }\n\n  if (weeks.length === 0) {\n    window.shiguangBridge.showToast(\"未获取到周次信息\");\n    return;\n  }\n\n  // 逐周获取课程数据\n  const allData = [];\n  for (const w of weeks) {\n    try {\n      const res = await fetch(baseUrl + '/api/arrange/CourseScheduleAllQuery/studentCourseSchedule?_t=' + Date.now(), {\n        method: 'POST',\n        headers: {\n          'Content-Type': 'application/json;charset=UTF-8',\n          'X-Requested-With': 'XMLHttpRequest',\n          'Origin': baseUrl,\n          'Referer': baseUrl + '/'\n        },\n        body: JSON.stringify({ studentId: '', oddOrDouble: 1, source: 'xs', semester, weeks: [w], queryType: 'single' })\n      });\n      const json = await res.json();\n      if (json.code === 200 && Array.isArray(json.data)) {\n        allData.push(...json.data);\n      }\n    } catch (e) {\n      console.error(\"获取第\" + w + \"周课程数据失败:\", e);\n    }\n  }\n\n  // 解析课程和时间段\n  const courses = [];\n  const timeSlotsMap = new Map();\n\n  for (const slot of allData) {\n    if (!slot.time || !slot.time.timeCode || !slot.week || slot.week.weekCode == null) {\n      continue;\n    }\n\n    const timeCode = slot.time.timeCode;\n    const parts = timeCode.split('_');\n    const startSection = Number(parts[0]);\n    const endSection = Number(parts[1]);\n    const day = slot.week.weekCode == 1 ? 7 : slot.week.weekCode - 1;\n\n    if (!timeSlotsMap.has(timeCode)) {\n      timeSlotsMap.set(timeCode, { number: startSection, startTime: slot.time.startTime, endTime: slot.time.endTime });\n    }\n\n    if (Array.isArray(slot.courseList)) {\n      for (const c of slot.courseList) {\n        if (c.courseName) {\n          courses.push({\n            name: c.courseName,\n            teacher: c.teacherName || '',\n            position: c.classroomName || '',\n            day,\n            startSection,\n            endSection,\n            weeks: parseWeeks(c.weeks),\n            isCustomTime: false\n          });\n        }\n      }\n    }\n  }\n\n  const merged = mergeAndDistinctCourses(courses);\n  const timeSlots = Array.from(timeSlotsMap.values()).sort((a, b) => a.number - b.number);\n\n  if (merged.length === 0) {\n    window.shiguangBridge.showToast(\"未解析到有效课程数据\");\n    return;\n  }\n\n  // 保存课程数据\n  try {\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(merged));\n    window.shiguangBridge.showToast(\"成功导入 \" + merged.length + \" 门课程\");\n  } catch (e) {\n    console.error(\"保存课程失败:\", e);\n    window.shiguangBridge.showToast(\"保存课程失败: \" + e.message);\n    return;\n  }\n\n  // 保存预设时间段\n  if (timeSlots.length > 0) {\n    try {\n      await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n      window.shiguangBridge.showToast(\"预设时间段导入成功\");\n    } catch (e) {\n      console.error(\"保存时间段失败:\", e);\n      window.shiguangBridge.showToast(\"保存时间段失败: \" + e.message);\n    }\n  }\n\n  // 保存课表配置\n  try {\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\n      semesterStartDate,\n      semesterTotalWeeks: weeks.length || 20,\n      firstDayOfWeek: 1\n    }));\n  } catch (e) {\n    console.error(\"保存配置失败:\", e);\n  }\n\n  window.shiguangBridge.showToast(\"所有任务已完成！\");\n  window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();\n","NCHU_01":"// 文件: nchu.js\n// 南昌航空大学教务系统课程表导入脚本\n\nfunction isOnSchedulePage() {\n    const url = window.location.href;\n    return /jwc-publish2\\.jwc\\.nchu\\.edu\\.cn/i.test(url);\n}\n\n// 解析周数字符串，支持逗号/顿号分隔的多段与连续区间\n// 例：第4-6,8-19周 / 第5,7,9,11,13,15,17,19周 / 第9周 / 第13-16周\nfunction parseWeeks(timeStr) {\n    const weeks = new Set();\n    const segment = timeStr.match(/第\\s*([\\d、,\\-\\s]+)\\s*周/);\n    if (!segment) return [];\n    segment[1].split(/[,、\\s]+/).forEach(part => {\n        part = part.trim();\n        if (!part) return;\n        const range = part.match(/^(\\d+)\\s*-\\s*(\\d+)$/);\n        if (range) {\n            const start = parseInt(range[1], 10);\n            const end = parseInt(range[2], 10);\n            for (let i = start; i <= end; i++) weeks.add(i);\n        } else if (/^\\d+$/.test(part)) {\n            weeks.add(parseInt(part, 10));\n        }\n    });\n    return Array.from(weeks).sort((a, b) => a - b);\n}\n\n// 解析节次字符串，兼容 \"01~02小节\" 与 \"01~02节\" 两种写法\nfunction parseSections(sectionStr) {\n    const match = sectionStr.match(/(\\d{1,2})~(\\d{1,2})(?:小)?节/);\n    if (match) {\n        return { start: parseInt(match[1], 10), end: parseInt(match[2], 10) };\n    }\n    return null;\n}\n\n// 从文档中提取课程数据\nfunction extractCoursesFromDoc(doc) {\n    const courses = [];\n    \n    const table = doc.querySelector('.time-table table');\n    if (!table) {\n        console.log('未找到课表表格');\n        return courses;\n    }\n    \n    const rows = table.querySelectorAll('tbody tr');\n    \n    rows.forEach(row => {\n        const cells = row.querySelectorAll('td');\n        if (cells.length < 2) return;\n        \n        // cells[0] 是节次列，cells[1..] 对应周一~周日\n        for (let i = 1; i < cells.length; i++) {\n            const day = i;\n            const cell = cells[i];\n            \n            // 一个格子里可能有多门课（多个 .item-box）\n            const itemBoxes = cell.querySelectorAll('.item-box');\n            itemBoxes.forEach(itemBox => {\n                parseItemBox(itemBox, day, courses);\n            });\n        }\n    });\n    \n    return courses;\n}\n\n// 解析单个 .item-box（一门课），其内部可能含多个时间段块\nfunction parseItemBox(itemBox, day, courses) {\n    // 课程全名：.item-box 内第一个 <p>\n    const courseP = itemBox.querySelector('p');\n    const name = courseP ? courseP.textContent.trim() : '';\n    if (!name) return;\n    \n    // 每个时间段块的构成：<p>课程名</p><div class=\"tch-name\">…</div><div><span item1>教室</span><span item3>周次</span></div>\n    itemBox.querySelectorAll('.tch-name').forEach(tch => {\n        const segDiv = tch.nextElementSibling;\n        if (!segDiv) return;\n        \n        // 周次：该 div 中 item3.png 所在 span 的文本（如 \"第13-16周 星期四\"）\n        const weekImg = segDiv.querySelector('img[src*=\"item3.png\"]');\n        const timeInfo = weekImg && weekImg.parentElement ? weekImg.parentElement.textContent.trim() : '';\n        const weeks = parseWeeks(timeInfo);\n        if (weeks.length === 0) return;\n        \n        // 节次：从 tch-name 内 \"01~02节\" 的 span 获取\n        let sectionInfo = null;\n        tch.querySelectorAll('span').forEach(s => {\n            if (sectionInfo) return;\n            sectionInfo = parseSections(s.textContent);\n        });\n        if (!sectionInfo) return;\n        \n        // 教室：该 div 中 item1.png 所在 span 的文字（如 \"博学楼F栋-F302\"）\n        let room = '';\n        const roomImg = segDiv.querySelector('img[src*=\"item1.png\"]');\n        if (roomImg && roomImg.parentElement) {\n            room = roomImg.parentElement.textContent.trim();\n        }\n        \n        // 教师：在本块 tch-name 的 span 中找 \"教师：xxx\"（避免与学分/节次拼接）\n        let teacher = '';\n        tch.querySelectorAll('span').forEach(s => {\n            if (teacher) return;\n            const m = s.textContent.match(/教师[:：]\\s*(.+)/);\n            if (m) teacher = m[1].trim();\n        });\n        \n        courses.push({\n            name,\n            teacher,\n            position: room || '未指定',\n            day,\n            startSection: sectionInfo.start,\n            endSection: sectionInfo.end,\n            weeks\n        });\n    });\n}\n\n// 获取当前页面的课程（兼容课表页直接注入，或从首页 iframe 中取课表内容）\nfunction getCurrentWeekCourses() {\n    // 若当前文档自身就是课表页，直接解析\n    if (document.querySelector('.time-table table')) {\n        return extractCoursesFromDoc(document);\n    }\n    \n    // 否则遍历 iframe 查找课表页\n    const iframes = Array.from(document.querySelectorAll('iframe'));\n    for (const iframe of iframes) {\n        try {\n            if (iframe.contentDocument && iframe.contentDocument.querySelector('.time-table table')) {\n                return extractCoursesFromDoc(iframe.contentDocument);\n            }\n        } catch (e) {\n            // 跨域 iframe 跳过\n        }\n    }\n    \n    return [];\n}\n\n// 去重合并课程\nfunction mergeAndDeduplicateCourses(allCourses) {\n    const courseMap = new Map();\n    \n    allCourses.forEach(course => {\n        const key = `${course.day}-${course.startSection}-${course.endSection}-${course.name}-${course.teacher}-${course.position}`;\n        \n        if (!courseMap.has(key)) {\n            courseMap.set(key, {\n                ...course,\n                weeks: [...course.weeks]\n            });\n        } else {\n            const existing = courseMap.get(key);\n            const weekSet = new Set([...existing.weeks, ...course.weeks]);\n            existing.weeks = Array.from(weekSet).sort((a, b) => a - b);\n        }\n    });\n    \n    return Array.from(courseMap.values());\n}\n\n// 生成时间段配置（该校实际为 11 节课）\nfunction generateTimeSlots() {\n    return [\n        { \"number\": 1, \"startTime\": \"08:00\", \"endTime\": \"08:45\" },\n        { \"number\": 2, \"startTime\": \"08:55\", \"endTime\": \"09:40\" },\n        { \"number\": 3, \"startTime\": \"10:00\", \"endTime\": \"10:45\" },\n        { \"number\": 4, \"startTime\": \"10:55\", \"endTime\": \"11:40\" },\n        { \"number\": 5, \"startTime\": \"14:00\", \"endTime\": \"14:45\" },\n        { \"number\": 6, \"startTime\": \"14:55\", \"endTime\": \"15:40\" },\n        { \"number\": 7, \"startTime\": \"16:00\", \"endTime\": \"16:45\" },\n        { \"number\": 8, \"startTime\": \"16:55\", \"endTime\": \"17:40\" },\n        { \"number\": 9, \"startTime\": \"19:00\", \"endTime\": \"19:45\" },\n        { \"number\": 10, \"startTime\": \"19:55\", \"endTime\": \"20:40\" },\n        { \"number\": 11, \"startTime\": \"20:50\", \"endTime\": \"21:35\" }\n    ];\n}\n\n// 主函数：导入课程\nasync function importCourseSchedule() {\n    try {\n        console.log('开始导入课程表...');\n        window.shiguangBridge.showToast('正在获取课表数据...');\n        \n        // 获取当前周课程\n        const courses = getCurrentWeekCourses();\n        console.log(`找到 ${courses.length} 门课程`);\n        \n        if (courses.length === 0) {\n            window.shiguangBridge.showToast('未找到课程数据');\n            return false;\n        }\n        \n        console.log('课程数据:', courses);\n        \n        // 导入课程\n        const coursesResult = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        if (coursesResult === true) {\n            console.log('课程导入成功！');\n            window.shiguangBridge.showToast(`成功导入 ${courses.length} 门课程！`);\n        } else {\n            console.log('课程导入失败');\n            window.shiguangBridge.showToast('课程导入失败');\n            return false;\n        }\n        \n        // 生成并导入时间段\n        const finalTimeSlots = generateTimeSlots();\n        const timeSlotsResult = await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(finalTimeSlots));\n        if (timeSlotsResult === true) {\n            console.log('时间段导入成功！');\n        }\n        \n        return true;\n        \n    } catch (error) {\n        console.error('导入过程出错:', error);\n        window.shiguangBridge.showToast('导入失败: ' + error.message);\n        return false;\n    }\n}\n\n// ========== 主执行逻辑 ==========\n\nif (isOnSchedulePage()) {\n    console.log('检测到南昌航空大学教务系统');\n    window.shiguangBridge.showToast('正在准备导入课程表...');\n    \n    setTimeout(async () => {\n        const success = await importCourseSchedule();\n        if (success) {\n            window.shiguangBridge.notifyTaskCompletion();\n        }\n    }, 2000);\n    \n} else {\n    console.log('当前不在教务系统页面');\n    window.shiguangBridge.showToast('请先登录教务系统！');\n}\n","STCNCHU":"// 南昌航空大学科技学院(stcnchu.edu.cn) 拾光课程表适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提联系开发者或者提交pr更改,这更加快速\n\n// 工具函数\n\nwindow.validateYearInput = function(input) {\n    return /^[0-9]{4}$/.test(input) ? false : \"请输入四位数字的学年！\";\n};\n\nfunction parseWeeks(weekStr) {\n    const weeks = [];\n    if (!weekStr) return weeks;\n    const pureWeekData = weekStr.split('(')[0]; \n    pureWeekData.split(',').forEach(seg => {\n        if (seg.includes('-')) {\n            const [s, e] = seg.split('-').map(Number);\n            if (!isNaN(s) && !isNaN(e)) {\n                for (let i = s; i <= e; i++) weeks.push(i);\n            }\n        } else {\n            const w = parseInt(seg);\n            if (!isNaN(w)) weeks.push(w);\n        }\n    });\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 节次合并与去重\n */\nfunction mergeAndDistinctCourses(courses) {\n    if (courses.length <= 1) return courses;\n\n    courses.sort((a, b) => {\n        return a.name.localeCompare(b.name) || \n               a.day - b.day || \n               a.startSection - b.startSection || \n               a.weeks.join(',').localeCompare(b.weeks.join(','));\n    });\n\n    const merged = [];\n    let current = courses[0];\n\n    for (let i = 1; i < courses.length; i++) {\n        const next = courses[i];\n        const isSameCourse = \n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n\n        if (isSameCourse && isContinuous) {\n            current.endSection = next.endSection;\n        } else if (isSameCourse && current.startSection === next.startSection && current.endSection === next.endSection) {\n            continue;\n        } else {\n            merged.push(current);\n            current = next;\n        }\n    }\n    merged.push(current);\n    return merged;\n}\n\n// 核心解析逻辑\n\nfunction parseTimetableToModel(doc) {\n    const timetable = doc.getElementById('kbtable');\n    if (!timetable) return [];\n\n    let rawCourses = [];\n    const rows = Array.from(timetable.querySelectorAll('tr')).filter(r => r.querySelector('td'));\n\n    rows.forEach(row => {\n        const cells = row.querySelectorAll('td');\n        cells.forEach((cell, dayIndex) => {\n            const day = dayIndex + 1;\n            const detailDivs = cell.querySelectorAll('div.kbcontent');\n            \n            detailDivs.forEach(div => {\n                const rawHtml = div.innerHTML.trim();\n                if (!rawHtml || rawHtml === \"&nbsp;\" || div.innerText.trim().length < 2) return;\n\n                const blocks = rawHtml.split(/---------------------|----------------------/);\n\n                blocks.forEach(block => {\n                    if (!block.trim()) return;\n                    const tempDiv = document.createElement('div');\n                    tempDiv.innerHTML = block;\n\n                    let name = \"\";\n                    for (let node of tempDiv.childNodes) {\n                        if (node.nodeType === 3 && node.textContent.trim() !== \"\") {\n                            name = node.textContent.trim();\n                            break;\n                        }\n                    }\n\n                    const teacherRaw = tempDiv.querySelector('font[title=\"老师\"], font[title=\"教师\"]')?.innerText || \"\";\n                    const teacher = teacherRaw.replace(\"任课教师:\", \"\").trim();\n                    const position = tempDiv.querySelector('font[title=\"教室\"]')?.innerText || \"未知地点\";\n                    const weekStr = tempDiv.querySelector('font[title=\"周次(节次)\"]')?.innerText || \"\";\n                    \n                    let startSection = 0;\n                    let endSection = 0;\n                    if (weekStr) {\n                        // 匹配方括号内所有的数字\n                        const sectionPart = weekStr.match(/\\[(.*?)节\\]/);\n                        if (sectionPart && sectionPart[1]) {\n                            const sections = sectionPart[1].split('-').map(Number).filter(n => !isNaN(n));\n                            if (sections.length > 0) {\n                                startSection = sections[0];\n                                endSection = sections[sections.length - 1];\n                            }\n                        }\n                    }\n\n                    if (name && startSection > 0) {\n                        rawCourses.push({\n                            \"name\": name,\n                            \"teacher\": teacher || \"未知教师\",\n                            \"weeks\": parseWeeks(weekStr),\n                            \"position\": position,\n                            \"day\": day,\n                            \"startSection\": startSection,\n                            \"endSection\": endSection\n                        });\n                    }\n                });\n            });\n        });\n    });\n\n    return mergeAndDistinctCourses(rawCourses);\n}\n\n// 配置与流程\n\nasync function saveAppConfig() {\n    const config = { \"semesterTotalWeeks\": 20, \"firstDayOfWeek\": 1 };\n    return await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n}\n\n/**\n * 适配多校区双季作息\n * @param {number} campusIndex 0 代表共青城校区, 1 代表上海路校区\n * @param {number} semesterIndex 0 代表第一学期(冬令时), 1 代表第二学期(夏令时)\n */\nasync function saveAppTimeSlots(campusIndex, semesterIndex) {\n    // 共青城校区\n    const campus1_slots = {\n        winter: [\n            { \"number\": 1, \"startTime\": \"08:30\", \"endTime\": \"09:10\" },\n            { \"number\": 2, \"startTime\": \"09:15\", \"endTime\": \"09:55\" },\n            { \"number\": 3, \"startTime\": \"10:05\", \"endTime\": \"10:45\" },\n            { \"number\": 4, \"startTime\": \"10:50\", \"endTime\": \"11:30\" },\n            { \"number\": 5, \"startTime\": \"13:20\", \"endTime\": \"14:00\" },\n            { \"number\": 6, \"startTime\": \"14:05\", \"endTime\": \"14:45\" },\n            { \"number\": 7, \"startTime\": \"14:55\", \"endTime\": \"15:35\" },\n            { \"number\": 8, \"startTime\": \"15:40\", \"endTime\": \"16:20\" },\n            { \"number\": 9, \"startTime\": \"19:00\", \"endTime\": \"19:40\" },\n            { \"number\": 10, \"startTime\": \"19:45\", \"endTime\": \"20:25\" },\n            { \"number\": 11, \"startTime\": \"20:30\", \"endTime\": \"21:10\" },\n            { \"number\": 12, \"startTime\": \"21:15\", \"endTime\": \"21:55\" }\n        ],\n        summer: [\n            { \"number\": 1, \"startTime\": \"08:30\", \"endTime\": \"09:10\" },\n            { \"number\": 2, \"startTime\": \"09:15\", \"endTime\": \"09:55\" },\n            { \"number\": 3, \"startTime\": \"10:05\", \"endTime\": \"10:45\" },\n            { \"number\": 4, \"startTime\": \"10:50\", \"endTime\": \"11:30\" },\n            { \"number\": 5, \"startTime\": \"13:40\", \"endTime\": \"14:20\" },\n            { \"number\": 6, \"startTime\": \"14:25\", \"endTime\": \"15:05\" },\n            { \"number\": 7, \"startTime\": \"15:15\", \"endTime\": \"15:55\" },\n            { \"number\": 8, \"startTime\": \"16:00\", \"endTime\": \"16:40\" },\n            { \"number\": 9, \"startTime\": \"19:00\", \"endTime\": \"19:40\" },\n            { \"number\": 10, \"startTime\": \"19:45\", \"endTime\": \"20:25\" },\n            { \"number\": 11, \"startTime\": \"20:30\", \"endTime\": \"21:10\" },\n            { \"number\": 12, \"startTime\": \"21:15\", \"endTime\": \"21:55\" }\n        ]\n    };\n\n    // 上海路校区（无双季作息，共用同一个数组）\n    const shanghaiRoadTimeTable = [\n        { \"number\": 1, \"startTime\": \"08:00\", \"endTime\": \"08:45\" },\n        { \"number\": 2, \"startTime\": \"08:55\", \"endTime\": \"09:40\" },\n        { \"number\": 3, \"startTime\": \"10:00\", \"endTime\": \"10:45\" },\n        { \"number\": 4, \"startTime\": \"10:55\", \"endTime\": \"11:40\" },\n        { \"number\": 5, \"startTime\": \"14:00\", \"endTime\": \"14:45\" },\n        { \"number\": 6, \"startTime\": \"14:55\", \"endTime\": \"15:40\" },\n        { \"number\": 7, \"startTime\": \"16:00\", \"endTime\": \"16:45\" },\n        { \"number\": 8, \"startTime\": \"16:55\", \"endTime\": \"17:40\" },\n        { \"number\": 9, \"startTime\": \"19:00\", \"endTime\": \"19:45\" },\n        { \"number\": 10, \"startTime\": \"19:55\", \"endTime\": \"20:40\" },\n        { \"number\": 11, \"startTime\": \"20:50\", \"endTime\": \"21:35\" },\n        { \"number\": 12, \"startTime\": \"21:45\", \"endTime\": \"22:30\" }\n    ];\n\n    const campus2_slots = {\n        winter: shanghaiRoadTimeTable,\n        summer: shanghaiRoadTimeTable\n    };\n\n    const targetCampus = (campusIndex === 0) ? campus1_slots : campus2_slots;\n    const selectedSlots = (semesterIndex === 0) ? targetCampus.winter : targetCampus.summer;\n\n    return await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(selectedSlots));\n}\n\n// ================= 流程编排 =================\n\nasync function runImportFlow() {\n    try {\n        const confirmed = await window.shiguangBridgePromise.showAlert(\"提示\", \"请确保已成功登录教务系统。是否开始导入？\", \"开始\");\n        if (!confirmed) return;\n\n        // 1. 获取就读校区\n        const campusIndex = await window.shiguangBridgePromise.showSingleSelection(\"选择所在校区\", JSON.stringify([\"共青城校区\", \"上海路校区\"]), -1);\n        if (campusIndex === null) return;\n\n        // 2. 获取学年\n        const year = await window.shiguangBridgePromise.showPrompt(\"选择学年\", \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\", \"\", \"validateYearInput\");\n        if (!year) return;\n\n        // 3. 获取学期并记录索引\n        const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\"选择学期\", JSON.stringify([\"第一学期\", \"第二学期\"]), -1);\n        if (semesterIndex === null) return;\n\n        const semesterId = `${year}-${parseInt(year) + 1}-${semesterIndex + 1}`;\n\n        window.shiguangBridge.showToast(\"正在请求数据...\");\n        const response = await fetch(\"http://qzjwxt.stcnchu.edu.cn:800/jsxsd/xskb/xskb_list.do\", {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n            body: `jx0404id=&cj0701id=&zc=&demo=&xnxq01id=${semesterId}`,\n            credentials: \"include\"\n        });\n        \n        const html = await response.text();\n        const finalCourses = parseTimetableToModel(new DOMParser().parseFromString(html, \"text/html\"));\n\n        if (finalCourses.length === 0) {\n            window.shiguangBridge.showToast(\"未发现课程，请检查学期选择或登录状态。\");\n            return;\n        }\n\n        // 保存全局设置\n        await saveAppConfig();\n        // 传入校区索引和学期索引联合控制作息映射\n        await saveAppTimeSlots(campusIndex, semesterIndex);\n        // 保存课程\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(finalCourses));\n        \n        window.shiguangBridge.showToast(`成功导入 ${finalCourses.length} 门课程`);\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        window.shiguangBridge.showToast(\"异常: \" + error.message);\n    }\n}\n\n// 启动\nrunImportFlow();","NTU":"// 南通大学拾光课程表适配脚本\n// 通过正方教务V9个人/班级课表接口获取课程，并转换为导入格式\n\n(function () {\nconst WINTER_TIME_SLOTS = [\n    { number: 1, startTime: \"07:50\", endTime: \"08:30\" },\n    { number: 2, startTime: \"08:40\", endTime: \"09:20\" },\n    { number: 3, startTime: \"09:35\", endTime: \"10:15\" },\n    { number: 4, startTime: \"10:30\", endTime: \"11:10\" },\n    { number: 5, startTime: \"11:20\", endTime: \"12:00\" },\n    { number: 6, startTime: \"13:30\", endTime: \"14:10\" },\n    { number: 7, startTime: \"14:20\", endTime: \"15:00\" },\n    { number: 8, startTime: \"15:20\", endTime: \"16:00\" },\n    { number: 9, startTime: \"16:10\", endTime: \"16:50\" },\n    { number: 10, startTime: \"18:30\", endTime: \"19:10\" },\n    { number: 11, startTime: \"19:20\", endTime: \"20:00\" },\n    { number: 12, startTime: \"20:10\", endTime: \"20:50\" }\n];\n\nconst SUMMER_TIME_SLOTS = [\n    { number: 1, startTime: \"07:50\", endTime: \"08:30\" },\n    { number: 2, startTime: \"08:40\", endTime: \"09:20\" },\n    { number: 3, startTime: \"09:35\", endTime: \"10:15\" },\n    { number: 4, startTime: \"10:30\", endTime: \"11:10\" },\n    { number: 5, startTime: \"11:20\", endTime: \"12:00\" },\n    { number: 6, startTime: \"14:00\", endTime: \"14:40\" },\n    { number: 7, startTime: \"14:50\", endTime: \"15:30\" },\n    { number: 8, startTime: \"15:50\", endTime: \"16:30\" },\n    { number: 9, startTime: \"16:40\", endTime: \"17:20\" },\n    { number: 10, startTime: \"19:00\", endTime: \"19:40\" },\n    { number: 11, startTime: \"19:50\", endTime: \"20:30\" },\n    { number: 12, startTime: \"20:40\", endTime: \"21:20\" }\n];\n\nfunction parseSections(value) {\n    const numbers = String(value || \"\").match(/\\d+/g);\n    if (!numbers || numbers.length === 0) return null;\n    const startSection = Number(numbers[0]);\n    const endSection = Number(numbers[numbers.length - 1]);\n    if (!Number.isInteger(startSection) || !Number.isInteger(endSection) || startSection < 1 || endSection < startSection) return null;\n    return { startSection, endSection };\n}\n\n// 将周次文本转换为周数数组\nfunction parseWeeks(value) {\n    const weeks = new Set();\n    String(value || \"\").replace(/（/g, \"(\").replace(/）/g, \")\").split(/[，,、;]/).forEach((part) => {\n        const numbers = part.match(/\\d+/g);\n        if (!numbers) return;\n        const start = Number(numbers[0]);\n        const end = Number(numbers[numbers.length - 1]);\n        const odd = part.includes(\"单\");\n        const even = part.includes(\"双\");\n        for (let week = start; week <= end; week += 1) {\n            if (odd && week % 2 === 0) continue;\n            if (even && week % 2 !== 0) continue;\n            weeks.add(week);\n        }\n    });\n    return [...weeks].sort((left, right) => left - right);\n}\n\nfunction normalizeStartDate(value) {\n    const match = String(value || \"\").match(/(\\d{4})[-\\/.年](\\d{1,2})[-\\/.月](\\d{1,2})/);\n    if (!match) return null;\n    return `${match[1]}-${match[2].padStart(2, \"0\")}-${match[3].padStart(2, \"0\")}`;\n}\n\nfunction findStartDate(value) {\n    if (!value || typeof value !== \"object\") return normalizeStartDate(value);\n    if (Array.isArray(value)) {\n        const firstWeek = value.find((item) => String(item?.zs) === \"1\" || String(item?.zsmc) === \"1\") || value[0];\n        return normalizeStartDate(firstWeek?.zrq || firstWeek?.zcrq || firstWeek?.rq);\n    }\n    const firstWeekDate = normalizeStartDate(value.zrq || value.zcrq || value.rq);\n    if (firstWeekDate) return firstWeekDate;\n    for (const [key, item] of Object.entries(value)) {\n        const date = item && typeof item === \"object\" ? findStartDate(item) : null;\n        if (date) return date;\n    }\n    return null;\n}\n\nasync function fetchSemesterStartDate() {\n    const xnm = document.querySelector(\"#xnm\")?.value;\n    const xqm = document.querySelector(\"#xqm\")?.value;\n    if (!xnm || !xqm) {\n        console.warn(\"NTU semester start date: missing xnm or xqm\", { xnm, xqm });\n        return null;\n    }\n    const url = new URL(\"/jwglxt/kbcx/xskbcxZccx_cxZcByXnxq.html?gnmkdm=N2154\", window.location.origin);\n    try {\n        const response = await fetch(url.href, {\n            headers: {\n                accept: \"application/json, text/javascript, */*; q=0.01\",\n                \"content-type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: `xnm=${encodeURIComponent(xnm)}&xqm=${encodeURIComponent(xqm)}`,\n            method: \"POST\",\n            credentials: \"include\"\n        });\n        const rawText = await response.text();\n        let data;\n        try {\n            data = JSON.parse(rawText);\n        } catch {\n            console.warn(\"NTU semester start date: response is not JSON\", response.status, rawText);\n            return null;\n        }\n        console.log(\"NTU semester start date response:\", data);\n        const startDate = findStartDate(data);\n        console.log(\"NTU semester start date:\", startDate || \"not found\");\n        return startDate;\n    } catch (error) {\n        console.warn(\"NTU semester start date request failed:\", error);\n        return null;\n    }\n}\n\n// 将课程字段转换为导入协议字段\nfunction normalizeCourses(rawCourses) {\n    const uniqueCourses = new Map();\n    rawCourses.forEach((rawCourse) => {\n        const name = String(rawCourse.kcmc || \"\").replace(/[■◆▲]/g, \"\").trim();\n        const teacher = String(rawCourse.xm || \"未知\").trim() || \"未知\";\n        const position = String(rawCourse.cdmc || \"待定\").trim() || \"待定\";\n        const day = Number(rawCourse.xqj);\n        const sections = parseSections(rawCourse.jcs || rawCourse.jc);\n        const weeks = parseWeeks(rawCourse.zcd);\n        if (!name || !sections || !Number.isInteger(day) || day < 1 || day > 7 || weeks.length === 0) return;\n        const course = { name, teacher, position, day, startSection: sections.startSection, endSection: sections.endSection, weeks };\n        const key = [name, teacher, position, day, sections.startSection, sections.endSection, weeks.join(\",\")].join(\"|\");\n        if (!uniqueCourses.has(key)) uniqueCourses.set(key, course);\n    });\n    return [...uniqueCourses.values()].sort((left, right) => left.day - right.day || left.startSection - right.startSection || left.name.localeCompare(right.name));\n}\n\n// 合并同一课程的重复节次\nfunction mergeAndDistinctCourses(courses) {\n    if (courses.length <= 1) return courses;\n    const list = courses.map((course) => ({ ...course, weeks: [...new Set(course.weeks)].sort((left, right) => left - right) }));\n    const sameBase = (left, right) => left.name === right.name && left.teacher === right.teacher && left.position === right.position && left.day === right.day;\n    list.sort((left, right) => left.name.localeCompare(right.name) || left.teacher.localeCompare(right.teacher) || left.position.localeCompare(right.position) || left.day - right.day || left.startSection - right.startSection);\n    const merged = [];\n    for (const course of list) {\n        const previous = merged[merged.length - 1];\n        if (previous && sameBase(previous, course) && previous.startSection === course.startSection && previous.endSection === course.endSection) {\n            previous.weeks = [...new Set([...previous.weeks, ...course.weeks])].sort((left, right) => left - right);\n        } else if (previous && sameBase(previous, course) && previous.weeks.join(\",\") === course.weeks.join(\",\") && previous.endSection + 1 === course.startSection) {\n            previous.endSection = course.endSection;\n        } else {\n            merged.push(course);\n        }\n    }\n    return merged;\n}\n\n// 个人课表\nasync function fetchApiCourses() {\n    const xnm = document.querySelector(\"#xnm\")?.value;\n    const xqm = document.querySelector(\"#xqm\")?.value;\n    if (!xnm || !xqm) return null;\n    const url = new URL(\"/jwglxt/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151\", window.location.origin);\n    try {\n        const response = await fetch(url.href, {\n            method: \"POST\",\n            headers: { \"content-type\": \"application/x-www-form-urlencoded;charset=UTF-8\", \"x-requested-with\": \"XMLHttpRequest\" },\n            body: `xnm=${encodeURIComponent(xnm)}&xqm=${encodeURIComponent(xqm)}&kzlx=ck&xsdm=&kclbdm=`,\n            credentials: \"include\"\n        });\n        const data = await response.json();\n        console.log(\"NTU course API response:\", data);\n        const rawCourses = data?.kbList || data?.datas?.kbList || data?.rows;\n        if (!Array.isArray(rawCourses) || !rawCourses.length) return null;\n        return mergeAndDistinctCourses(normalizeCourses(rawCourses));\n    } catch (error) {\n        console.warn(\"NTU course API request failed:\", error);\n        return null;\n    }\n}\n\n// 班级课表\nasync function fetchClassApiCourses() {\n    const pageMap = window.api?.data?.map || {};\n    const readValue = (key) => pageMap[key] ?? document.querySelector(`#${key}`)?.value ?? \"\";\n    const requestFields = [\n        \"xnm\",\n        \"xqm\",\n        \"njdm_id\",\n        \"zyh_id\",\n        \"bh_id\",\n        \"tjkbzdm\",\n        \"tjkbzxsdm\",\n        \"zxszjjs\"\n    ];\n    const body = new URLSearchParams();\n    requestFields.forEach((key) => {\n        const value = readValue(key);\n        if (value !== \"\" && value !== null && typeof value !== \"undefined\") body.set(key, String(value));\n    });\n    if (!body.get(\"xnm\") || !body.get(\"xqm\") || !body.get(\"bh_id\")) {\n        console.warn(\"NTU class course API parameters are incomplete\", Object.fromEntries(body));\n        return null;\n    }\n    const url = new URL(\"/jwglxt/kbdy/bjkbdy_cxBjKb.html\", window.location.origin);\n    try {\n        const response = await fetch(url.href, {\n            method: \"POST\",\n            headers: { \"content-type\": \"application/x-www-form-urlencoded;charset=UTF-8\", \"x-requested-with\": \"XMLHttpRequest\" },\n            body,\n            credentials: \"include\"\n        });\n        const data = await response.json();\n        console.log(\"NTU class course API response:\", data);\n        const rawCourses = data?.kbList || data?.datas?.kbList || data?.rows;\n        if (!Array.isArray(rawCourses) || !rawCourses.length) return null;\n        return mergeAndDistinctCourses(normalizeCourses(rawCourses));\n    } catch (error) {\n        console.warn(\"NTU class course API request failed:\", error);\n        return null;\n    }\n}\n\nasync function runImport() {\n    try {\n        if (!await window.shiguangBridgePromise.showAlert(\"南通大学课表导入\", \"导入前请确保已登录南通大学教务系统。\", \"开始导入\")) return;\n        const formAction = document.querySelector(\"#ajaxForm\")?.getAttribute(\"action\") || \"\";\n        const isPersonalPage = /xskbcx_cxXskbcxIndex/i.test(formAction) || /\\/kbcx\\/xskbcx/i.test(window.location.pathname);\n        const pageCourses = isPersonalPage ? await fetchApiCourses() : await fetchClassApiCourses();\n        if (pageCourses?.length) {\n            const pageWeeks = pageCourses.flatMap((course) => course.weeks);\n            const semesterStartDate = await fetchSemesterStartDate();\n            if (!semesterStartDate) throw new Error(\"未获取到开学日期，无法判断令时\");\n            const startMonth = Number(semesterStartDate.slice(5, 7));\n            if (!Number.isInteger(startMonth) || startMonth < 1 || startMonth > 12) throw new Error(`开学日期格式无效：${semesterStartDate}`);\n            const timeSlots = startMonth <= 6 ? WINTER_TIME_SLOTS : SUMMER_TIME_SLOTS;\n            const courseConfig = { semesterTotalWeeks: Math.max(19, ...pageWeeks), defaultClassDuration: 40, firstDayOfWeek: 1 };\n            courseConfig.semesterStartDate = semesterStartDate;\n            await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(courseConfig));\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n            await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(pageCourses));\n            window.shiguangBridge.showToast(`导入成功：${pageCourses.length} 条课程安排`);\n            window.shiguangBridge.notifyTaskCompletion();\n            return;\n        }\n        window.shiguangBridge.showToast(\"当前页面未找到课表，请先打开个人或班级课表页面。\");\n    } catch (error) {\n        console.error(\"NTU adapter error\", error);\n        window.shiguangBridge.showToast(`导入失败：${error.message}`);\n    }\n}\n\nrunImport();\n})();\n","NYNU_01":"/**\n * 南阳师范学院教务系统课表导入适配脚本\n * 青果软件系统，通过 showLessonScheduleInfosV14.action 接口获取课表\n * 课程信息分布在 id 形如 weekly0X_Y 的 div 中（X 为星期，Y 为节次单元）\n */\n\nfunction parseWeeks(weekStr) {\n    // 兼容 \"1-2,5-18\" 逗号分段 + 区间\n    const weeks = [];\n    weekStr.split(',').forEach(part => {\n        part = part.trim();\n        if (part.includes('-')) {\n            const dashSegs = part.split('-').map(Number);\n            if (dashSegs.length === 2 && !isNaN(dashSegs[0]) && !isNaN(dashSegs[1])) {\n                for (let i = dashSegs[0]; i <= dashSegs[1]; i++) weeks.push(i);\n            }\n        } else if (!isNaN(Number(part))) {\n            weeks.push(Number(part));\n        }\n    });\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 解析单个 weekly 块里的 li 文本，返回课程信息\n */\nfunction parseWeeklyDiv(divId, liTexts) {\n    // id 形如 weekly03_1 -> 星期=3，节次单元=1\n    const m = divId.match(/^weekly0?(\\d+)_(\\d+)$/);\n    if (!m) return null;\n    const day = parseInt(m[1], 10);\n    if (day < 1 || day > 7) return null;\n\n    let name = \"\", teacher = \"\", timeText = \"\", position = \"\";\n    for (const t of liTexts) {\n        const str = t.trim();\n        if (str.startsWith(\"课程名称\")) name = str.replace(/^课程名称：/, \"\").replace(/^<b>/, \"\").replace(/<\\/b>$/, \"\");\n        else if (str.startsWith(\"任课教师\")) teacher = str.replace(/^任课教师：/, \"\").replace(/^<b>/, \"\").replace(/<\\/b>$/, \"\");\n        else if (str.startsWith(\"上课时间\")) timeText = str.replace(/^上课时间：/, \"\").replace(/^<b>/, \"\").replace(/<\\/b>$/, \"\");\n        else if (str.startsWith(\"上课地点\")) position = str.replace(/^上课地点：/, \"\").replace(/^<b>/, \"\").replace(/<\\/b>$/, \"\");\n    }\n\n    if (!name || !timeText) return null;\n\n    // 上课时间形如：[1-2,5-18周] 三[1-2节]\n    const weekMatch = timeText.match(/\\[([\\d,\\-]+)周\\]/);\n    const sectionMatch = timeText.match(/\\[(\\d+)(?:-(\\d+))?节\\]/);\n    if (!weekMatch || !sectionMatch) return null;\n\n    const weeks = parseWeeks(weekMatch[1]);\n    const startSection = parseInt(sectionMatch[1], 10);\n    const endSection = sectionMatch[2] ? parseInt(sectionMatch[2], 10) : startSection;\n\n    if (weeks.length === 0) return null;\n\n    return {\n        name: name,\n        teacher: teacher || \"未知教师\",\n        position: position || \"未知地点\",\n        day: day,\n        startSection: startSection,\n        endSection: endSection,\n        weeks: weeks\n    };\n}\n\n/**\n * 从接口返回的 HTML 中提取所有 weekly div 并解析课程\n */\nfunction transformSchedule(htmlString) {\n    console.log(\"JS: transformSchedule 正在解析 HTML...\");\n\n    const tempDoc = new DOMParser().parseFromString(htmlString, \"text/html\");\n\n    // 只取包裹课程详情的 weekly div（跳过表格等内容）\n    const weekDivs = Array.from(tempDoc.querySelectorAll('[id^=\"weekly\"]'))\n        .filter(d => d.classList.contains(\"weeklesson\"));\n\n    console.log(`JS: 找到 ${weekDivs.length} 个 weekly 课程块`);\n\n    const rawCourses = [];\n\n    weekDivs.forEach(div => {\n        const divId = div.id;\n        const lis = Array.from(div.querySelectorAll(\"ul li\"));\n        const liTexts = lis.map(li => li.innerHTML);\n        const course = parseWeeklyDiv(divId, liTexts);\n        if (course) rawCourses.push(course);\n    });\n\n    console.log(`JS: 解析出 ${rawCourses.length} 条课程记录`);\n\n    // 青果系统同一门课会因节次格/周次分段生成重复的 weekly 块，\n    // 按组合键去重（同一课程、同时段、同周次只保留一条）。\n    const seen = new Set();\n    const courses = [];\n    for (const c of rawCourses) {\n        const key = `${c.name}|${c.day}|${c.startSection}|${c.endSection}|${c.weeks.join(',')}|${c.teacher}|${c.position}`;\n        if (seen.has(key)) continue;\n        seen.add(key);\n        courses.push(c);\n    }\n\n    console.log(`JS: 去重后剩 ${courses.length} 门课程`);\n    return courses;\n}\n\nfunction isLoginPage() {\n    const url = window.location.href;\n    return url.includes('login') || url.includes('cas');\n}\n\nfunction validateYearInput(input) {\n    if (/^[0-9]{4}$/.test(input)) return false;\n    return \"请输入四位数字的学年！\";\n}\n\nasync function promptUserToStart() {\n    console.log(\"JS: 流程开始：显示公告。\");\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function getAcademicYear() {\n    const currentYear = new Date().getFullYear().toString();\n    return await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\",\n        \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\",\n        currentYear,\n        \"validateYearInput\"\n    );\n}\n\nasync function selectSemester() {\n    const semesters = [\"第一学期 (0)\", \"第二学期 (1)\"];\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesters),\n        0\n    );\n    return semesterIndex;\n}\n\nasync function fetchAndParseCourses(academicYear, semesterIndex) {\n    window.shiguangBridge.showToast(\"正在请求课表数据...\");\n\n    const semesterCode = semesterIndex === 0 ? \"0\" : \"1\";\n    // 从当前页面 URL 提取 vpn-12-o1-{源站} 形式的后缀（如 nysyjw.nynu.edu.cn），\n    // 不同登录会话源站域名可能不同；没匹配到时回退到教务源站固定值。\n    const originMatch = window.location.href.match(/vpn-12-o1-([a-zA-Z0-9.\\-]+(?:\\.edu\\.cn)?)/);\n    const originHost = originMatch ? originMatch[1] : \"nysyjw.nynu.edu.cn\";\n    const baseUrl = \"https://vpn.nynu.edu.cn/http/77726476706e69737468656265737421feee52852d27265e67069ce29d51367b58d2/nysfjw/frame/desk/showLessonScheduleInfosV14.action\";\n    const url = `${baseUrl}?vpn-12-o1-${originHost}&xn=${academicYear}&xq=${semesterCode}`;\n    console.log(`JS: 请求课表接口: ${url}`);\n\n    try {\n        const response = await fetch(url, {\n            method: \"GET\",\n            credentials: \"include\"\n        });\n\n        if (!response.ok) {\n            throw new Error(`网络请求失败。状态码: ${response.status}`);\n        }\n\n        const htmlText = await response.text();\n        const courses = transformSchedule(htmlText);\n\n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"未找到任何课程数据，请检查所选学年学期是否正确。\");\n            return null;\n        }\n\n        console.log(`JS: 课程数据解析成功，共找到 ${courses.length} 门课程。`);\n        return { courses };\n\n    } catch (error) {\n        window.shiguangBridge.showToast(`请求或解析失败: ${error.message}`);\n        console.error('JS: Fetch/Parse Error:', error);\n        return null;\n    }\n}\n\nasync function saveCourses(parsedCourses) {\n    window.shiguangBridge.showToast(`正在保存 ${parsedCourses.length} 门课程...`);\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses, null, 2));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        console.error('JS: Save Courses Error:', error);\n        return false;\n    }\n}\n\nasync function runImportFlow() {\n    if (isLoginPage()) {\n        window.shiguangBridge.showToast(\"导入失败：请先登录教务系统！\");\n        return;\n    }\n\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    const academicYear = await getAcademicYear();\n    if (academicYear === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n\n    const semesterIndex = await selectSemester();\n    if (semesterIndex === null || semesterIndex === -1) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n\n    const result = await fetchAndParseCourses(academicYear, semesterIndex);\n    if (result === null) {\n        return;\n    }\n    const { courses } = result;\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        return;\n    }\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();","NBUT_01":"/**\n * 基础工具函数：Base64 编码\n */\nfunction encodeParams(xn, xq) {\n    const rawStr = `xnm=${xn}&xqm=${xq}`;\n    return rawStr;\n}\n\n/**\n * 判断是否处于教务系统登录环境\n */\nasync function checkLoginEnvironment() {\n    const currentUrl = window.location.href;\n    const loginUrl = \"http://jwxt.nbut.edu.cn/jwglxt/xtgl/login_slogin.html\";\n    const targetUrl = \"http://jwxt.nbut.edu.cn/\"\n\n    if (!currentUrl.includes(targetUrl)) {\n        window.shiguangBridge.showToast(\"不处于教务系统网站，自动为你跳转\");\n        window.location.href = loginUrl;\n        return false;\n    } \n    if (currentUrl.includes(loginUrl)) {\n        window.shiguangBridge.showToast(\"请先登录教务系统再进行导入\");\n        return false;\n    }\n    return true; \n}\n\n/**\n * 星期解析函数\n */\nfunction parseDayOfWeek(dateString){\n    const weekdayMap = {\n    \"星期一\": 1,\n    \"星期二\": 2,\n    \"星期三\": 3,\n    \"星期四\": 4,\n    \"星期五\": 5,\n    \"星期六\": 6,\n    \"星期日\": 7\n    };\n    return weekdayMap[dateString] || null;\n}\n\n/**\n * 上课周次解析函数\n */\nfunction parseWeek(weekString){\n    let a = weekString;\n    a = a.replace(\"周\",\"\");\n    a = a.replace(\"(\",\"\").replace(\")\",\"\");\n    const isSingle = a.includes(\"单\");\n    const isDouble = a.includes(\"双\");\n    a = a.replace(\"单\",\"\").replace(\"双\",\"\");\n    const [start,end] = a.split(\"-\").map(Number);\n    const weeks = []\n    for(let i = start;i <= end;i++){\n        if(isSingle && i % 2 === 0){\n            continue;\n        }\n        if(isDouble && i % 2 === 1){\n            continue;\n        }\n        weeks.push(i);\n    }\n    return weeks;\n}\n\n\n/**\n * 处理单个课程信息\n */\nfunction parseSingleCourseData(jsonObject){\n    const singleCourse = new Object();\n    singleCourse.name = jsonObject.kcmc;\n    singleCourse.teacher = jsonObject.xm;\n    singleCourse.position = jsonObject.cdmc;\n    singleCourse.day = parseDayOfWeek(jsonObject.xqjmc);\n    singleCourse.startSection = jsonObject.jcs.split(\"-\").map(Number)[0];\n    singleCourse.endSection = jsonObject.jcs.split(\"-\").map(Number)[1];\n    singleCourse.weeks = parseWeek(jsonObject.zcd);\n    singleCourse.id = jsonObject.kch_id;\n    return singleCourse;\n}\n\n/**\n * 课表数据解析函数\n */\nfunction parseAllCourseData(jsonObject) {\n    const newCourseList = [];\n    const oldCourseList = jsonObject.kbList;\n    for(let i = 0;i < oldCourseList.length;i++){\n        newCourseList.push(parseSingleCourseData(oldCourseList[i]));\n    }\n    return newCourseList;\n}\n\n/**\n * 学期获取函数\n */\nasync function fetchYearAndSemester() {\n    try {\n        const response = await fetch(\"http://jwxt.nbut.edu.cn/jwglxt/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151&layout=default\", {\n        });\n        const html = await response.text();\n        const dom = new DOMParser().parseFromString(html, 'text/html');\n        xn = dom.getElementById(\"xnm\").value;\n        xq = dom.getElementById(\"xqm\").value;\n        return {xn,xq};\n    } catch (error) {\n        return null;\n    }\n}\n\n/**\n * 课表抓取函数\n */\nasync function fetchCourses(xn, xq) {\n    const paramsBase64 = encodeParams(xn, xq);\n    const response = await fetch(\"http://jwxt.nbut.edu.cn/jwglxt/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151\",{\n        method: 'POST',\n        body: paramsBase64,\n        headers:{\n            'X-Requested-With': 'XMLHttpRequest',\n            'Referer': 'http://jwxt.nbut.edu.cn/jwglxt/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151&layout=default',\n            'Origin': 'http://jwxt.nbut.edu.cn',\n            'Accept': '*/*',\n            'Accept-Language': 'zh-CN,zh;q=0.9',\n            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/145.0.0.0 Safari/537.36',\n            'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8'\n        },\n        credentials: 'include',\n        mode:'cors'\n    })\n    if(!response.ok){\n        throw new Error(`课表信息请求失败：${response.status}`);\n    }\n    const courseJson = await response.json();\n    return parseAllCourseData(courseJson);\n}\n\n/**\n * 单个时间段解析函数\n */\nfunction parseSinglePresetTimeSlot(jsonObject) {\n    const timeData = new Object();\n    timeData.number = jsonObject.jcmc;\n    timeData.startTime = jsonObject.qssj;\n    timeData.endTime = jsonObject.jssj;\n    return timeData;\n}\n\n\n/**\n * 时间段解析函数\n */\nfunction parseAllPresetTimeSlot(jsonObject) {\n    const newTimeSlotList = [];\n    const oldTimeSlotList = jsonObject;\n    for(let i = 0;i < oldTimeSlotList.length;i++){\n        newTimeSlotList.push(parseSinglePresetTimeSlot(oldTimeSlotList[i]));\n    }\n    return newTimeSlotList;\n}\n\n/**\n * 时间段导入函数\n */\nasync function fetchPresetTimeSlots(xn,xq) {\n    const requestBody = encodeParams(xn,xq);\n    const response = await fetch(\"http://jwxt.nbut.edu.cn/jwglxt/kbcx/xskbcx_cxRjc.html?gnmkdm=N2151\",{\n        method : 'POST',\n        body : requestBody,\n        headers : {\n            'X-Requested-With': 'XMLHttpRequest',\n            'Accept-Language': 'zh-CN,zh;q=0.9',\n            'Accept' : '*/*',\n            'Content-Type' : 'application/x-www-form-urlencoded;charset=UTF-8',\n            'User-Agent' : 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/145.0.0.0 Safari/537.36',\n            'Origin' : 'http://jwxt.nbut.edu.cn',\n            'Referer': 'http://jwxt.nbut.edu.cn/jwglxt/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151&layout=default'\n        },\n        credentials: 'include',\n        mode:'cors'\n    })\n    if(!response.ok){\n        throw new Error(`时间段信息请求失败：${response.status}`)\n    }\n    const timeJson = await response.json();\n    return parseAllPresetTimeSlot(timeJson);\n}\n\n/**\n * 全局配置解析函数\n */\nasync function fetchConfig(params) {\n    try{\n        const response = await fetch(\"http://jwxt.nbut.edu.cn/jwglxt/pkgl/xlglMobile_cxXlIndexForxs.html?gnmkdm=Y210501&layout=default\",{\n            method : 'GET',\n            headers : {\n                'Accept-Language': 'zh-CN,zh;q=0.9',\n                'Content-Type' : 'application/x-www-form-urlencoded;charset=UTF-8',\n                'User-Agent' : 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/145.0.0.0 Safari/537.36',\n                'Origin' : 'http://jwxt.nbut.edu.cn',\n                'Referer': 'http://jwxt.nbut.edu.cn/jwglxt/xtgl/index_initMenu.html?jsdm=xs&_t=1776496821521&echarts=1',\n                'Upgrade-Insecure-Requests' : '1',\n                'Accept':'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.7'\n            },\n            credentials: 'include',\n            mode:'cors'\n        })\n        const html = await response.text();\n        const dom = new DOMParser().parseFromString(html,'text/html');\n        const semesterStartDate = dom.getElementById(\"ksrq\").value;\n\n        const config = new Object();\n        config.semesterStartDate = semesterStartDate;\n        config.defaultClassDuration = 40;\n        return config;\n    }catch(error){\n        return null;\n    }\n   \n}\n\n/**\n * 最终流程控制\n */\nasync function runImportFlow() {\n    console.log(\"开始导入\")\n    // 环境检查\n    const isReady = await checkLoginEnvironment();\n    if (!isReady) {\n        console.log(\"不处于教务页面，或未登录\")\n        return\n    };\n    // 获取当前学期\n    const params = await fetchYearAndSemester();\n    if (!params){\n        console.log(\"未找到学期\")\n        return;\n    } ;\n    // 获取，解析，保存课程数据\n    const courses = await fetchCourses(params.xn, params.xq);\n    if (!courses || courses.length === 0) {\n        console.log(\"未找到有效课程\");\n        return;\n    }\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n\n    // 获取，解析，保存时间段\n    const time = await fetchPresetTimeSlots(params.xn, params.xq);\n    if (!time || time.length === 0) {\n        console.log(\"未找到有效时间段\");\n        return;\n    }\n    await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(time));\n\n    const config = await fetchConfig(params);\n    if(!config){\n        console.log(\"未找到学校全局配置\")\n        return;\n    }\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n    // 完成\n    console.log('导入成功')\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\n// 启动\nrunImportFlow();","QFNU_01":"// 曲阜师范大学(zhjw.qfnu.edu.cn) 拾光课程表适配脚本\n// 教务系统：强智 jsxsd\n// 使用流程：在软件内置浏览器登录教务系统，停留在任意教务功能页面后执行导入\n// 说明：学期列表与教学周历自动读取；教务系统不提供节次时间，导入后需在软件内设置上课时间\n// 维护者：Yumu-banxia\n\nconst QFNU_KB_URL = '/jsxsd/xskb/xskb_list.do';\nconst QFNU_CALENDAR_URL = '/jsxsd/jxzl/jxzl_query';\nconst QFNU_CLASS_DURATION = 45;\nconst QFNU_BREAK_DURATION = 10;\nconst QFNU_POST_OPTIONS = { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } };\n\n// ==================== 桥接封装 ====================\n\nfunction toast(message) {\n    if (window.shiguangBridge && typeof window.shiguangBridge.showToast === 'function') {\n        window.shiguangBridge.showToast(message);\n    } else {\n        console.log('[QFNU] ' + message);\n    }\n}\n\nasync function alertUser(title, message) {\n    if (window.shiguangBridgePromise && typeof window.shiguangBridgePromise.showAlert === 'function') {\n        const confirmed = await window.shiguangBridgePromise.showAlert(title, message, '知道了');\n        return confirmed === true || confirmed === 'true';\n    }\n    alert(title + '\\n' + message);\n    return true;\n}\n\n// 原生以字符串序号或 \"null\" 回传，统一为数字序号，-1 表示取消\nasync function selectFromList(title, items, defaultIndex) {\n    if (!(window.shiguangBridgePromise && typeof window.shiguangBridgePromise.showSingleSelection === 'function')) {\n        return defaultIndex;\n    }\n    const result = await window.shiguangBridgePromise.showSingleSelection(title, JSON.stringify(items), defaultIndex);\n    if (result === null || result === undefined || result === 'null') return -1;\n    const index = typeof result === 'number' ? result : parseInt(result, 10);\n    return isNaN(index) ? -1 : index;\n}\n\n// ==================== 请求 ====================\n\n// 兼容直连与 WebVPN 形态的地址，取 /jsxsd/ 之前的部分作为前缀\nfunction jsxsdUrl(path) {\n    const currentPath = window.location.pathname || '';\n    const index = currentPath.indexOf('/jsxsd/');\n    return window.location.origin + (index < 0 ? '' : currentPath.slice(0, index)) + path;\n}\n\nasync function requestText(url, options) {\n    const response = await fetch(url, Object.assign({ credentials: 'include' }, options || {}));\n    return await response.text();\n}\n\n// 课表页表单字段与页面 Form1 一致，POST 失败时退回带查询参数的 GET\nasync function fetchTimetableDoc(semesterValue, kbjcmsid) {\n    const url = jsxsdUrl(QFNU_KB_URL);\n    const body = 'jx0404id=&cj0701id=&zc=&demo=&xnxq01id=' + encodeURIComponent(semesterValue) +\n        '&sfFD=1&kbjcmsid=' + encodeURIComponent(kbjcmsid);\n\n    const posted = new DOMParser().parseFromString(\n        await requestText(url, Object.assign({ method: 'POST', body: body }, QFNU_POST_OPTIONS)), 'text/html');\n    if (findTimetableTable(posted)) return posted;\n\n    const got = new DOMParser().parseFromString(\n        await requestText(url + '?xnxq01id=' + encodeURIComponent(semesterValue)), 'text/html');\n    return findTimetableTable(got) ? got : null;\n}\n\n// ==================== 学期与教学周历 ====================\n\n// 学期列表：[{ value: \"2026-2027-1\", label: \"2026-2027 学年第 1 学期\", selected: true }]\nfunction parseSemesters(doc) {\n    const select = doc.querySelector('select[name=\"xnxq01id\"], select#xnxq01id');\n    if (!select) return [];\n    const list = [];\n    select.querySelectorAll('option').forEach(function (option) {\n        const value = String(option.getAttribute('value') || '').trim();\n        if (!value) return;\n        list.push({\n            value: value,\n            label: value.replace(/^(\\d{4})-(\\d{4})-(\\d)$/, '$1-$2 学年第 $3 学期'),\n            selected: option.hasAttribute('selected')\n        });\n    });\n    return list;\n}\n\nfunction parseKbjcmsid(doc) {\n    const select = doc.querySelector('select[name=\"kbjcmsid\"]');\n    const option = select ? (select.querySelector('option[selected]') || select.querySelector('option')) : null;\n    return option ? String(option.getAttribute('value') || '').trim() : '';\n}\n\n// 教学周历：首列为周次序号，第二列含该周星期一日期\nfunction parseCalendar(doc) {\n    const result = { semesterStartDate: null, totalWeeks: null };\n    const table = doc.querySelector('table');\n    if (!table) return result;\n\n    const toDate = function (text) {\n        const match = String(text || '').match(/(\\d{4})\\s*[-年]\\s*(\\d{1,2})\\s*[-月]\\s*(\\d{1,2})/);\n        return match ? match[1] + '-' + match[2].padStart(2, '0') + '-' + match[3].padStart(2, '0') : null;\n    };\n\n    Array.from(table.querySelectorAll('tr')).forEach(function (row) {\n        const cells = Array.from(row.children);\n        const first = cells.length > 0 ? String(cells[0].textContent).trim() : '';\n        if (!/^\\d+$/.test(first)) return;\n\n        const week = parseInt(first, 10);\n        result.totalWeeks = result.totalWeeks === null ? week : Math.max(result.totalWeeks, week);\n        if (week === 1 && !result.semesterStartDate && cells.length > 1) {\n            result.semesterStartDate = toDate(cells[1].getAttribute('title')) || toDate(cells[1].textContent);\n        }\n    });\n    return result;\n}\n\nasync function fetchCalendar(semesterValue) {\n    try {\n        const text = await requestText(jsxsdUrl(QFNU_CALENDAR_URL), Object.assign(\n            { method: 'POST', body: 'xnxq01id=' + encodeURIComponent(semesterValue) }, QFNU_POST_OPTIONS));\n        return parseCalendar(new DOMParser().parseFromString(text, 'text/html'));\n    } catch (error) {\n        console.warn('[QFNU] 教学周历读取失败：', error);\n        return { semesterStartDate: null, totalWeeks: null };\n    }\n}\n\n// ==================== 课表解析 ====================\n\n// 不同强智版本分别使用 #timetable 与 #kbtable\nfunction findTimetableTable(doc) {\n    return doc.getElementById('timetable') || doc.getElementById('kbtable');\n}\n\n// 周次与节次：兼容 1-16(周)[01-02节]、1-8,10-16(周)、1-15周(单)、2-16(双)、第3-4节 等写法\nfunction parseWeeksAndSections(text) {\n    const result = { weeks: [], sections: [] };\n    const content = String(text || '').trim();\n    if (!content) return result;\n\n    const parity = /双/.test(content) ? 2 : (/单/.test(content) ? 1 : 0);\n    const bracketIndex = content.indexOf('[');\n    const cleaned = (bracketIndex >= 0 ? content.slice(0, bracketIndex) : content)\n        .replace(/第/g, '')\n        .replace(/至|到|~/g, '-')\n        .replace(/[（(][^（）()]*[）)]/g, '')\n        .replace(/周/g, '');\n\n    cleaned.split(/[,，、;；\\s]+/).forEach(function (segment) {\n        const item = segment.trim();\n        const range = item.match(/^(\\d+)\\s*[-–—]\\s*(\\d+)$/);\n        if (range) {\n            for (let week = parseInt(range[1], 10); week <= parseInt(range[2], 10); week++) result.weeks.push(week);\n        } else if (/^\\d+$/.test(item)) {\n            result.weeks.push(parseInt(item, 10));\n        }\n    });\n\n    if (parity) {\n        result.weeks = result.weeks.filter(function (week) { return week % 2 === (parity === 1 ? 1 : 0); });\n    }\n    result.weeks = Array.from(new Set(result.weeks)).sort(function (a, b) { return a - b; });\n\n    const sectionMatch = content.match(/\\[([^\\]]*)\\]/);\n    if (sectionMatch) {\n        (sectionMatch[1].match(/\\d+/g) || []).forEach(function (number) {\n            const section = parseInt(number, 10);\n            if (result.sections.indexOf(section) < 0) result.sections.push(section);\n        });\n        result.sections.sort(function (a, b) { return a - b; });\n    }\n    return result;\n}\n\n// 收集单个课表单元格内的全部课程候选。强智在格内同时输出简表与详表，\n// 简表缺少教师与节次方括号，此处一并解析，交由归并阶段择优。\nfunction collectCellCandidates(cellDiv, day, output, rowSections) {\n    const html = String(cellDiv.innerHTML || '').trim();\n    if (!html || html.replace(/&nbsp;/gi, '').trim() === '') return;\n\n    html.split(/[-—–]{6,}\\s*(?:<br\\s*\\/?>)?/i).forEach(function (blockHtml) {\n        if (!blockHtml.trim()) return;\n\n        const holder = document.createElement('div');\n        holder.innerHTML = blockHtml;\n\n        let name = '';\n        for (let i = 0; i < holder.childNodes.length; i++) {\n            const node = holder.childNodes[i];\n            if (node.nodeType === 3 && /[\\u4e00-\\u9fa5]/.test(node.textContent)) {\n                name = node.textContent.trim();\n                break;\n            }\n        }\n        if (!name) name = String(holder.textContent || '').split('\\n')[0].trim();\n        if (!name) return;\n\n        const pickText = function (titles) {\n            for (let i = 0; i < titles.length; i++) {\n                const element = holder.querySelector('font[title*=\"' + titles[i] + '\"]');\n                if (element && element.textContent.trim()) return element.textContent.trim();\n            }\n            return '';\n        };\n\n        let timeText = pickText(['周次', '节次']);\n        if (!/\\[[^\\]]*\\]/.test(timeText)) {\n            const bracket = String(holder.textContent || '').match(/\\[[^\\]]*\\]/);\n            if (bracket) timeText += bracket[0];\n        }\n\n        const parsed = parseWeeksAndSections(timeText || holder.textContent);\n        if (parsed.weeks.length === 0) return;\n        if (parsed.sections.length === 0 && rowSections) {\n            for (let section = rowSections[0]; section <= rowSections[1]; section++) parsed.sections.push(section);\n        }\n\n        const teacher = pickText(['教师', '老师']);\n        const position = pickText(['教室', '地点']).replace(/\\[\\s*\\d+\\s*-\\s*\\d+\\s*\\]\\s*节?$/, '').trim();\n\n        output.push({\n            name: name,\n            teacher: teacher,\n            position: position,\n            day: day,\n            weeks: parsed.weeks,\n            sections: parsed.sections,\n            score: (teacher ? 4 : 0) + (/\\[[^\\]]*\\]/.test(timeText) ? 3 : 0) +\n                (position ? 1 : 0) + (parsed.sections.length > 1 ? 1 : 0)\n        });\n    });\n}\n\n// 按课程名、周次、教室归并候选，保留信息更完整的一条\nfunction mergeCellCandidates(candidates) {\n    const groups = {};\n    const order = [];\n    candidates.forEach(function (item) {\n        const key = item.name + '|' + item.weeks.join(',') + '|' + item.position;\n        if (groups[key] === undefined) {\n            groups[key] = item;\n            order.push(key);\n        } else if (item.score > groups[key].score) {\n            groups[key] = item;\n        }\n    });\n\n    const courses = [];\n    order.forEach(function (key) {\n        const item = groups[key];\n        if (item.sections.length === 0) return;\n        courses.push({\n            name: item.name,\n            teacher: item.teacher || '未知教师',\n            position: item.position || '未知地点',\n            day: item.day,\n            weeks: item.weeks,\n            startSection: item.sections[0],\n            endSection: item.sections[item.sections.length - 1]\n        });\n    });\n    return courses;\n}\n\nfunction parseTimetable(doc) {\n    const table = findTimetableTable(doc);\n    if (!table) return [];\n\n    const courses = [];\n    Array.from(table.querySelectorAll('tr')).forEach(function (row) {\n        const label = row.querySelector('th');\n        const labelMatch = label ? String(label.textContent).match(/(\\d+)\\s*[~～\\-—]\\s*(\\d+)\\s*节/) : null;\n        const rowSections = labelMatch ? [parseInt(labelMatch[1], 10), parseInt(labelMatch[2], 10)] : null;\n\n        Array.from(row.querySelectorAll('td')).forEach(function (cell, index) {\n            const blocks = cell.querySelectorAll('div.kbcontent, div.kbcontent1');\n            if (blocks.length === 0) return;\n\n            const candidates = [];\n            Array.from(blocks).forEach(function (block) {\n                collectCellCandidates(block, index + 1, candidates, rowSections);\n            });\n            mergeCellCandidates(candidates).forEach(function (course) {\n                courses.push(course);\n            });\n        });\n    });\n    return courses;\n}\n\n// 节次与周次合并去重函数\n// 来源：官方 Wiki《课程合并与去重函数》\n// https://github.com/XingHeYuZhuan/shiguangschedule/wiki/课程合并与去重函数\n// 阶段一按名称、教师、地点、星期、周次一致合并连续节次并去除完全重复，阶段二按相同节次合并周次\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n            a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) ||\n            (a.day || 0) - (b.day || 0) ||\n            a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n            (a.startSection || 0) - (b.startSection || 0);\n    });\n\n    const step1Merged = [];\n    let current = list[0];\n\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n\n        const isSameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n\n        if (isSameCourseAndWeeks && isContinuous) {\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n            a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) ||\n            (a.day || 0) - (b.day || 0) ||\n            (a.startSection || 0) - (b.startSection || 0) ||\n            (a.endSection || 0) - (b.endSection || 0);\n    });\n\n    const step2Merged = [];\n    let merged = step1Merged[0];\n\n    for (let i = 1; i < step1Merged.length; i++) {\n        const next = step1Merged[i];\n\n        const isSameCourseAndSection =\n            merged.name === next.name &&\n            merged.teacher === next.teacher &&\n            merged.position === next.position &&\n            merged.day === next.day &&\n            merged.startSection === next.startSection &&\n            merged.endSection === next.endSection;\n\n        if (isSameCourseAndSection) {\n            merged.weeks = Array.from(new Set([...merged.weeks, ...next.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(merged);\n            merged = next;\n        }\n    }\n    step2Merged.push(merged);\n\n    return step2Merged;\n}\n\n// ==================== 流程编排 ====================\n\nasync function runImportFlow() {\n    try {\n        if ((window.location.pathname || '').indexOf('/jsxsd/') < 0) {\n            await alertUser('请先进入教务系统', '请登录教务系统并停留在任意教务功能页面后重新执行导入。');\n            return;\n        }\n\n        toast('正在获取学期信息…');\n        const listDoc = new DOMParser().parseFromString(await requestText(jsxsdUrl(QFNU_KB_URL)), 'text/html');\n        const semesters = parseSemesters(listDoc);\n        if (semesters.length === 0) {\n            await alertUser('未获取到学期列表', '课表页返回异常，请确认登录状态有效后重试。');\n            return;\n        }\n\n        let defaultIndex = 0;\n        semesters.forEach(function (item, index) { if (item.selected) defaultIndex = index; });\n        const picked = semesters.length > 1\n            ? await selectFromList('选择学期', semesters.map(function (item) { return item.label; }), defaultIndex)\n            : defaultIndex;\n        if (picked < 0 || picked >= semesters.length) {\n            toast('导入已取消');\n            return;\n        }\n        const semester = semesters[picked];\n\n        toast('正在获取 ' + semester.label + ' 课表…');\n        const tableDoc = await fetchTimetableDoc(semester.value, parseKbjcmsid(listDoc));\n        if (!tableDoc) {\n            await alertUser('未获取到课表数据', '请确认已登录教务系统后重试。');\n            return;\n        }\n\n        const courses = mergeAndDistinctCourses(parseTimetable(tableDoc));\n        if (courses.length === 0) {\n            await alertUser('未解析到课程', semester.label + ' 页面中没有课程内容，该学期可能尚未发布课表。');\n            return;\n        }\n\n        const calendar = await fetchCalendar(semester.value);\n        const weeks = courses.reduce(function (all, course) { return all.concat(course.weeks); }, []);\n        const config = {\n            semesterTotalWeeks: calendar.totalWeeks || Math.max.apply(null, weeks),\n            defaultClassDuration: QFNU_CLASS_DURATION,\n            defaultBreakDuration: QFNU_BREAK_DURATION\n        };\n        if (calendar.semesterStartDate) {\n            config.semesterStartDate = calendar.semesterStartDate;\n        } else {\n            toast('未读取到教学周历，开学日期可在软件内手动校准');\n        }\n\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        if (!await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses))) {\n            toast('课程保存失败，请重试');\n            return;\n        }\n\n        toast('导入成功：' + semester.label + ' 共 ' + courses.length + ' 条课程时段');\n        if (window.shiguangBridge && typeof window.shiguangBridge.notifyTaskCompletion === 'function') {\n            window.shiguangBridge.notifyTaskCompletion();\n        }\n    } catch (error) {\n        console.error('[QFNU] 导入流程异常：', error);\n        await alertUser('导入失败', error && error.message ? error.message : String(error));\n    }\n}\n\n// 启动导入流程\nrunImportFlow();\n","QVTU":"// ============================================================\n// 泉州职业技术大学（jw.qvtu.edu.cn/jsxsd，强智教务）\n// 拾光课程表适配脚本\n//\n// 参照官方强智适配案例（YSSDUFE_01，见 shiguangschedule Wiki\n// \"常见教务系统适配案例参考\"）编写：\n//   1. 教学周历 jxzl_query 提供学期列表 / 开学日期 / 总周数；\n//   2. 学期理论课表 xskb_list.do 提供课程数据（#kbtable / div.kbcontent 官方结构）。\n// 若站点周历页结构与案例不同，自动降级：跳过选学期、不提交开学日期，\n// 任何情况都不会阻塞导入。\n// 流程遵循官方开发文档约定：学期配置 → 课程 → 作息时间（可选，失败不阻止完成）；\n// notifyTaskCompletion 只在流程成功后调用。\n// 出现问题请联系开发者或提交 PR 更改。\n// ============================================================\n\n// 整体包一层 IIFE：本脚本可能被反复注入同一页面（测试器每次点击都会\n// 重新注入且不刷新页面），顶层 const/function 会与上一次注入冲突\n// （Identifier has already been declared），也会覆盖教务页面自己的全局函数。\n(function () {\n\n// ================= 配置 =================\n\n// 作息时间：来自教务\"大节\"时段，小节按\"45 分钟上课 + 15 分钟休息\"拆分。\n// 注：站点里\"第七大节(13,14小节) 12:00-13:59\"与晚间节次时间重叠，\n//     会被拾光\"时间段不可重叠\"校验拒绝，故不提供 13、14 节时间（当前无课程使用）。\nconst QVTU_TIME_SLOTS = [\n  { number: 1, startTime: \"08:10\", endTime: \"08:55\" },\n  { number: 2, startTime: \"09:10\", endTime: \"09:55\" },\n  { number: 3, startTime: \"10:10\", endTime: \"10:55\" },\n  { number: 4, startTime: \"11:10\", endTime: \"11:55\" },\n  { number: 5, startTime: \"14:10\", endTime: \"14:55\" },\n  { number: 6, startTime: \"15:10\", endTime: \"15:55\" },\n  { number: 7, startTime: \"16:10\", endTime: \"16:55\" },\n  { number: 8, startTime: \"17:10\", endTime: \"17:55\" },\n  { number: 9, startTime: \"19:10\", endTime: \"19:55\" },\n  { number: 10, startTime: \"20:10\", endTime: \"20:55\" },\n  { number: 11, startTime: \"21:10\", endTime: \"21:55\" },\n  { number: 12, startTime: \"22:10\", endTime: \"22:55\" }\n];\n\n// 教务系统地址与接口\nconst QVTU_ORIGIN_CHECK = /jw\\.qvtu\\.edu\\.cn$/i; // 只在教务站点上运行\nconst QVTU_JXZL_URL = \"/jsxsd/jxzl/jxzl_query\"; // 教学周历（学期列表 + 开学日期 + 总周数）\nconst QVTU_XSKB_URL = \"/jsxsd/xskb/xskb_list.do\"; // 学期理论课表\n\nconst QVTU_REQUEST_TIMEOUT = 8000; // 单请求超时（毫秒）\n\n// ================= 工具函数 =================\n\nfunction toast(message) {\n  window.shiguangBridge.showToast(message);\n}\n\n// 生命周期结束信号：只在流程成功后调用（官方约定）\nfunction notifyDone() {\n  window.shiguangBridge.notifyTaskCompletion();\n}\n\n// 带超时保护的 fetch（门户切换页面时站点脚本会中断进行中的请求，失败重试一次）\nasync function fetchText(url, options, tag) {\n  const opts = options || { method: \"GET\", credentials: \"include\" };\n  let lastErr = null;\n  for (let attempt = 1; attempt <= 2; attempt++) {\n    try {\n      const p = fetch(url, opts).then(r => r.text());\n      if (typeof setTimeout !== \"function\") return await p;\n      return await Promise.race([p, new Promise((_, reject) => {\n        setTimeout(() => reject(new Error(\"请求超时：\" + tag)), QVTU_REQUEST_TIMEOUT);\n      })]);\n    } catch (e) {\n      lastErr = e;\n    }\n  }\n  throw new Error(\"请求失败（\" + tag + \"）：\" + (lastErr && lastErr.message ? lastErr.message : \"网络错误\"));\n}\n\n// 解析 HTML 文本为文档对象\nfunction parseHtml(html) {\n  return new DOMParser().parseFromString(String(html || \"\"), \"text/html\");\n}\n\n// 只认可解析得了的课表（登录页/错误页不含这些标记）。\n// 不同强智版本课表格子用 class=\"kbcontent\" 或 class=\"kb_table\"，本站另有 <p title=...> 格式。\nfunction hasCourse(text) {\n  return /课程名称：|kbcontent|kb_table/.test(String(text || \"\"));\n}\n\n// ================= 核心解析逻辑（一）：教学周历 =================\n\n// GET 周历页：解析学期下拉框，以当前选中学期为原点上下各取 3 个。\n// 站点若无 xnxq01id 下拉框则返回空列表（流程自动跳过选学期）。\nasync function fetchSemesterList() {\n  const doc = parseHtml(await fetchText(location.origin + QVTU_JXZL_URL, null, \"教学周历页\"));\n  const select = doc.getElementById(\"xnxq01id\");\n  if (!select) return { list: [], defaultIndex: -1 };\n\n  const all = Array.from(select.querySelectorAll(\"option\")).map(opt => ({\n    value: opt.value,\n    label: opt.textContent.trim(),\n    selected: opt.hasAttribute(\"selected\")\n  }));\n  let idx = all.findIndex(o => o.selected);\n  if (idx === -1) idx = 0;\n  const start = Math.max(0, idx - 3);\n  return {\n    list: all.slice(start, Math.min(all.length, idx + 4)),\n    defaultIndex: idx - start\n  };\n}\n\n// POST 周历页：解析指定学期的开学日期（首行 td[title]）与总周数（首列最大整数）。\n// 结构不符时返回 { startDate: null, totalWeeks: null }，不阻塞流程。\nasync function fetchSemesterInfo(semesterId) {\n  const html = await fetchText(location.origin + QVTU_JXZL_URL, {\n    method: \"POST\",\n    headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n    body: \"xnxq01id=\" + encodeURIComponent(semesterId),\n    credentials: \"include\"\n  }, \"教学周历详情\");\n  const doc = parseHtml(html);\n  const timetable = doc.getElementById(\"kbtable\");\n  if (!timetable) return { startDate: null, totalWeeks: null };\n\n  const rows = Array.from(timetable.querySelectorAll(\"tr\")).filter(r => r.querySelector(\"td\"));\n  if (!rows.length) return { startDate: null, totalWeeks: null };\n\n  // 开学日期：第一行首个带 title 的 td，如 \"2025年9月1日\"（兼容不补零）\n  const title = (rows[0].querySelector(\"td[title]\") || {}).getAttribute\n    ? rows[0].querySelector(\"td[title]\").getAttribute(\"title\") : \"\";\n  const m = String(title).match(/^(\\d{4})年(\\d{1,2})月(\\d{1,2})日$/);\n  const pad = n => (n < 10 ? \"0\" + n : \"\" + n);\n  const startDate = m ? m[1] + \"-\" + pad(+m[2]) + \"-\" + pad(+m[3]) : null;\n\n  // 总周数：所有行首列能解析为整数的最大值\n  let totalWeeks = null;\n  for (const row of rows) {\n    const td = row.querySelector(\"td\");\n    if (!td) continue;\n    const n = parseInt(td.textContent.trim(), 10);\n    if (!isNaN(n) && n > 0 && (totalWeeks === null || n > totalWeeks)) totalWeeks = n;\n  }\n  return { startDate, totalWeeks };\n}\n\n// ================= 核心解析逻辑（二）：课程 =================\n\n// \"第3周\"、\"第1-16周\"、\"第1,3,5-8周\"、\"第1-15周(单周)\" → [3] / [1..16] / 奇数周…\nfunction parseWeeks(text) {\n  let t = String(text || \"\").replace(/\\s/g, \"\");\n  const parity = t.indexOf(\"单周\") >= 0 ? 1 : t.indexOf(\"双周\") >= 0 ? 2 : 0;\n  t = t.replace(/[（(][^）)]*[）)]/g, \"\");\n  const set = {};\n  const rangeRe = /(\\d+)\\s*[-–—~]\\s*(\\d+)/g;\n  let m;\n  while ((m = rangeRe.exec(t)) !== null) {\n    for (let w = Math.min(+m[1], +m[2]); w <= Math.max(+m[1], +m[2]); w++) set[w] = 1;\n  }\n  for (const s of t.replace(rangeRe, \" \").match(/\\d+/g) || []) set[+s] = 1;\n  const weeks = [];\n  for (const k in set) {\n    const n = +k;\n    if (n >= 1 && n <= 30 && !(parity === 1 && n % 2 === 0) && !(parity === 2 && n % 2 === 1)) weeks.push(n);\n  }\n  return weeks.sort((a, b) => a - b);\n}\n\n// 把解析结果合并进总表（同名同天同节次区间同地点 → 合并周次）\nfunction mergeCourse(map, c) {\n  if (!c.name || !c.day || !c.weeks.length || !c.startSection) return;\n  const key = [c.name, c.day, c.startSection + \"-\" + c.endSection, c.position].join(\"|\");\n  if (!map[key]) {\n    map[key] = c;\n  } else {\n    for (const w of c.weeks) if (!map[key].weeks.includes(w)) map[key].weeks.push(w);\n    map[key].weeks.sort((a, b) => a - b);\n  }\n}\n\n// 解析路径 A：官方案例的 DOM 结构（#kbtable 内 div.kbcontent，多课程以长横线分隔）\nfunction parseKbcontent(doc) {\n  const timetable = doc.getElementById(\"kbtable\");\n  if (!timetable) return [];\n  const map = {};\n  const rows = Array.from(timetable.querySelectorAll(\"tr\")).filter(r => r.querySelector(\"td\"));\n  rows.forEach(row => {\n    const cells = row.querySelectorAll(\"td\");\n    cells.forEach((cell, dayIndex) => {\n      const day = dayIndex + 1;\n      cell.querySelectorAll(\"div.kbcontent\").forEach(div => {\n        const raw = div.innerHTML.trim();\n        if (!raw || raw === \"&nbsp;\" || div.innerText.trim().length < 2) return;\n        raw.split(/-{10,}/).forEach(block => {\n          if (!block.trim()) return;\n          const box = document.createElement(\"div\");\n          box.innerHTML = block;\n\n          let name = \"\";\n          for (const node of box.childNodes) {\n            if (node.nodeType === 3 && node.textContent.trim() !== \"\") { name = node.textContent.trim(); break; }\n          }\n          const teacher = (box.querySelector('font[title=\"老师\"], font[title=\"教师\"]') || {}).innerText || \"\";\n          const position = (box.querySelector('font[title=\"教室\"]') || {}).innerText || \"未知地点\";\n          const weekStr = ((box.querySelector('font[title=\"周次(节次)\"]') || {}).innerText) || \"\";\n\n          let startSection = 0, endSection = 0;\n          const sec = weekStr.match(/\\[(.*?)节\\]/);\n          if (sec && sec[1]) {\n            const nums = sec[1].split(\"-\").map(Number).filter(n => !isNaN(n));\n            if (nums.length) { startSection = nums[0]; endSection = nums[nums.length - 1]; }\n          }\n          if (name && startSection > 0) {\n            mergeCourse(map, {\n              name, teacher: teacher.replace(/任课教师[:：]/, \"\").trim() || \"未知教师\",\n              position, day, weeks: parseWeeks(weekStr),\n              startSection, endSection\n            });\n          }\n        });\n      });\n    });\n  });\n  return Object.values(map);\n}\n\n// ================= 数据抓取与编排 =================\n\nasync function fetchAndParseCourses() {\n  if (!QVTU_ORIGIN_CHECK.test(location.hostname)) {\n    throw new Error(\"请先在浏览器/WebView 打开教务网站（https://jw.qvtu.edu.cn/jsxsd）并登录，再运行。当前页面：\" + location.href);\n  }\n\n  // 1) 学期列表 + 用户选择（站点无学期下拉框时自动跳过，导入当前学期）\n  let semesterId = null;\n  const { list, defaultIndex } = await fetchSemesterList();\n  if (list.length) {\n    const picked = await window.shiguangBridgePromise.showSingleSelection(\n      \"选择学期\", JSON.stringify(list.map(s => s.label)), defaultIndex\n    );\n    if (picked === null) { toast(\"已取消导入。\"); return null; }\n    semesterId = list[picked].value;\n  }\n\n  // 2) 教学周历 → 开学日期 + 总周数（结构不符则降级为 null）\n  let startDate = null, totalWeeks = null;\n  if (semesterId) {\n    const info = await fetchSemesterInfo(semesterId);\n    startDate = info.startDate;\n    totalWeeks = info.totalWeeks;\n  }\n\n  // 3) 课表：选了学期用 POST 指定学期，否则 GET 当前学期\n  const html = await fetchText(location.origin + QVTU_XSKB_URL, semesterId ? {\n    method: \"POST\",\n    headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n    body: \"jx0404id=&cj0701id=&zc=&demo=&xnxq01id=\" + encodeURIComponent(semesterId),\n    credentials: \"include\"\n  } : null, \"学期课表页\");\n\n  if (!hasCourse(html)) {\n    if (/用户登录|请登录|loginForm|passwd/i.test(String(html))) {\n      throw new Error(\"教务会话已过期或尚未登录（接口返回登录页）。请重新登录教务系统后运行。\");\n    }\n    console.warn(\"[泉州职业技术大学适配器] 学期课表页返回了意外内容（前 300 字符）：\",\n      String(html || \"\").replace(/\\s+/g, \" \").slice(0, 300));\n    throw new Error(\"学期课表页返回了无法识别的内容，请按 F12 打开控制台，把警告信息发给开发者核对。\");\n  }\n\n  // 4) 解析（官方案例 DOM 结构）\n  const courses = parseKbcontent(parseHtml(html));\n  if (!courses.length) {\n    throw new Error(\"教务页面里没有解析到课程。请确认所选学期已有排课，或把错误信息发给我核对。\");\n  }\n\n  // 5) 周历未给出总周数时，取课程最大周次兜底\n  if (!totalWeeks) {\n    for (const c of courses) for (const w of c.weeks) if (w > totalWeeks) totalWeeks = w;\n  }\n  return { courses, startDate, totalWeeks };\n}\n\n// ================= 保存步骤（顺序参照官方开发文档） =================\n\n// 保存学期配置（开学日期/总周数来自教学周历，没拿到就不提交/用课程最大周兜底）\n// defaultClassDuration/defaultBreakDuration 与作息表一致（45 分钟一节、小节间休息 15 分钟）\nasync function saveCourseConfig(startDate, totalWeeks) {\n  try {\n    const config = {\n      firstDayOfWeek: 1,\n      defaultClassDuration: 45,\n      defaultBreakDuration: 15,\n      semesterTotalWeeks: totalWeeks > 0 ? totalWeeks : 20\n    };\n    if (startDate) config.semesterStartDate = startDate;\n    const ok = await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n    if (!ok) { toast(\"学期配置保存失败。\"); return false; }\n    return true;\n  } catch (e) {\n    toast(\"学期配置保存失败：\" + e.message);\n    return false;\n  }\n}\n\n// 保存课程数据\nasync function saveCourses(courses) {\n  try {\n    const ok = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n    if (!ok) { toast(\"课程数据保存失败。\"); return false; }\n    return true;\n  } catch (e) {\n    toast(\"课程数据保存失败：\" + e.message);\n    return false;\n  }\n}\n\n// 保存作息时间表（官方文档：可选步骤，失败不阻止导入完成）\nasync function savePresetTimeSlots() {\n  try {\n    const ok = await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(QVTU_TIME_SLOTS));\n    if (!ok) toast(\"作息时间保存失败。\");\n    return !!ok;\n  } catch (e) {\n    toast(\"作息时间保存失败：\" + e.message);\n    return false;\n  }\n}\n\n// ================= 流程编排 =================\n\n/**\n * 编排整个课程导入流程（顺序与约定参照官方开发文档）。\n * 用户取消或关键步骤保存失败时立即结束；作息时间为可选步骤，失败不阻止完成；\n * notifyTaskCompletion 只在流程成功后调用（官方约定）。\n */\nasync function runImportFlow() {\n  try {\n    // 1. 公告和前置检查\n    const confirmed = await window.shiguangBridgePromise.showAlert(\n      \"提示\",\n      \"请确保已成功登录泉州职业技术大学教务系统。是否开始导入？\",\n      \"开始\"\n    );\n    if (!confirmed) {\n      toast(\"已取消导入。\");\n      return;\n    }\n\n    // 2. 网络请求和数据解析（内部含选学期；取消时返回 null）\n    toast(\"正在获取学期课表…\");\n    const result = await fetchAndParseCourses();\n    if (!result) return;\n    const { courses, startDate, totalWeeks } = result;\n\n    // 3. 保存学期配置\n    if (!await saveCourseConfig(startDate, totalWeeks)) return;\n\n    // 4. 保存课程数据\n    toast(\"正在保存 \" + courses.length + \" 条课程安排…\");\n    if (!await saveCourses(courses)) return;\n\n    // 5. 导入作息时间表（可选步骤，失败不阻止导入完成）\n    if (!await savePresetTimeSlots()) {\n      toast(\"提示：作息时间未导入，课程已保存，可在 App 里手动设置或稍后重试。\");\n    }\n\n    // 6. 流程成功，发送结束信号\n    toast(`成功导入 ${courses.length} 条课程安排！` +\n      (startDate ? `学期 ${startDate} 起，共 ${totalWeeks} 周。` : \"开学日期未能自动获取，可在 App 里手动设置。\"));\n    notifyDone();\n  } catch (error) {\n    // 任何一步失败：记录并提示用户，与官方适配一致不向外抛出，也不发送完成信号\n    console.error(\"[泉州职业技术大学适配器]\", error);\n    toast(\"导入失败：\" + (error && error.message ? error.message : error));\n  }\n}\n\n// 启动导入流程\nrunImportFlow();\n\n})();\n","QAU_01":"/**\n * 青岛农业大学综合教务管理系统(强智科技)\n * by ReGoMark, 2026.07.04\n * \n */\n\n// ─────────────────────────────────────────────\n// 工具函数\n// ─────────────────────────────────────────────\n\n/**\n * 解析周次字符串\n * 例如 \"1-4,6,11-13\" → [1, 2, 3, 4, 6, 11, 12, 13]\n */\nfunction parseWeeks(weekStr) {\n    let weeks = [];\n    weekStr = weekStr.replace(/\\(.*?\\)/g, '').trim();\n    let parts = weekStr.split(',');\n    for (let part of parts) {\n        part = part.trim();\n        if (part.includes('-')) {\n            let [start, end] = part.split('-');\n            for (let i = parseInt(start); i <= parseInt(end); i++) {\n                if (!weeks.includes(i)) weeks.push(i);\n            }\n        } else {\n            let w = parseInt(part);\n            if (!isNaN(w) && !weeks.includes(w)) weeks.push(w);\n        }\n    }\n    return weeks.sort((a, b) => a - b);\n}\n\n/**\n * 解析行标题中的节次范围\n * 例如 \"第1,2节\" → { start: 1, end: 2 }\n *      \"第5节\"   → { start: 5, end: 5 }\n */\nfunction parseSectionFromThHeader(thText) {\n    let match = thText.match(/第([\\d,]+)节/);\n    if (!match) return null;\n    let nums = match[1].split(',').map(n => parseInt(n)).filter(n => !isNaN(n));\n    if (nums.length === 0) return null;\n    return { start: nums[0], end: nums[nums.length - 1] };\n}\n\n// ─────────────────────────────────────────────\n// 核心解析\n// ─────────────────────────────────────────────\n\n/**\n * 从课表页面的 Document 中提取并去重、合并课程数据\n */\nfunction extractCoursesFromDoc(doc) {\n    let parsedCourses = [];\n\n    const table = doc.getElementById('kbtable');\n    if (!table) throw new Error(\"未找到课表表格（#kbtable），请确认已登录教务系统且当前学期有排课。\");\n\n    const rows = table.getElementsByTagName('tr');\n\n    for (let i = 1; i < rows.length - 1; i++) {\n        const row = rows[i];\n\n        const th = row.querySelector('th');\n        if (!th) continue;\n        const sectionInfo = parseSectionFromThHeader(th.innerText || th.textContent);\n        if (!sectionInfo) continue;\n\n        const cells = row.getElementsByTagName('td');\n        for (let j = 0; j < cells.length; j++) {\n            const dayOfWeek = j + 1;\n            const cell = cells[j];\n\n            const detailDivs = cell.querySelectorAll('div.kbcontent');\n            if (detailDivs.length === 0) continue;\n\n            detailDivs.forEach(div => {\n                let htmlContent = div.innerHTML;\n                if (!htmlContent.trim() || htmlContent.trim() === '&nbsp;') return;\n\n                let courseBlocks = htmlContent.split(/-{5,}\\s*<br\\s*\\/?>/i);\n\n                courseBlocks.forEach(block => {\n                    if (!block.trim() || block.trim() === '&nbsp;') return;\n\n                    let tempDiv = doc.createElement('div');\n                    tempDiv.innerHTML = block;\n\n                    let courseObj = {\n                        day: dayOfWeek,\n                        isCustomTime: false,\n                        startSection: sectionInfo.start,\n                        endSection: sectionInfo.end\n                    };\n\n                    // 1. 课程名\n                    let lines = tempDiv.innerHTML.split(/<br\\s*\\/?>/i);\n                    for (let line of lines) {\n                        let cleanLine = line.replace(/<[^>]+>/g, '').trim();\n                        if (cleanLine && cleanLine !== '&nbsp;') {\n                            courseObj.name = cleanLine;\n                            break;\n                        }\n                    }\n\n                    // 2. 教师（QAU title=\"老师\"）\n                    let teacherFont = tempDiv.querySelector('font[title=\"老师\"]');\n                    courseObj.teacher = teacherFont\n                        ? (teacherFont.innerText || teacherFont.textContent).trim()\n                        : \"未知\";\n\n                    // 3. 教室\n                    let positionFont = tempDiv.querySelector('font[title=\"教室\"]');\n                    courseObj.position = positionFont\n                        ? (positionFont.innerText || positionFont.textContent).trim()\n                        : \"待定\";\n\n                    // 4. 周次\n                    let timeFont = tempDiv.querySelector('font[title=\"周次(节次)\"]');\n                    if (timeFont) {\n                        let timeText = (timeFont.innerText || timeFont.textContent).trim();\n                        let weekMatch = timeText.match(/^(.+?)\\(周\\)/);\n                        if (weekMatch) {\n                            courseObj.weeks = parseWeeks(weekMatch[1]);\n                        }\n                    }\n\n                    if (!courseObj.weeks || courseObj.weeks.length === 0) return;\n                    if (!courseObj.name) return;\n\n                    parsedCourses.push(courseObj);\n                });\n            });\n        }\n    }\n\n    // ── 去重 ──\n    let uniqueCourses = [];\n    let courseSet = new Set();\n    parsedCourses.forEach(course => {\n        let key = `${course.day}-${course.startSection}-${course.endSection}-${course.name}-${course.weeks.join(',')}`;\n        if (!courseSet.has(key)) {\n            courseSet.add(key);\n            uniqueCourses.push(course);\n        }\n    });\n\n    // ── 合并相邻节次（最多合并两个大节，即 1-4 节）──\n    // 条件：同天、同名、同教师、同教室、同周次，节次紧邻，且合并后跨度不超过 4 节\n    const sorted = uniqueCourses.sort((a, b) => {\n        if (a.day !== b.day) return a.day - b.day;\n        if (a.name !== b.name) return a.name.localeCompare(b.name);\n        const wa = a.weeks.join(','), wb = b.weeks.join(',');\n        if (wa !== wb) return wa.localeCompare(wb);\n        return a.startSection - b.startSection;\n    });\n\n    const merged = [];\n    for (const cur of sorted) {\n        const prev = merged[merged.length - 1];\n        const canMerge = prev\n            && prev.day === cur.day\n            && prev.name === cur.name\n            && prev.teacher === cur.teacher\n            && prev.position === cur.position\n            && prev.weeks.join(',') === cur.weeks.join(',')\n            && prev.endSection + 1 === cur.startSection\n            && (cur.endSection - prev.startSection) <= 3;\n        if (canMerge) {\n            prev.endSection = cur.endSection;\n        } else {\n            merged.push({ ...cur });\n        }\n    }\n\n    return merged;\n}\n\n// ─────────────────────────────────────────────\n// 学校定制数据\n// ─────────────────────────────────────────────\n\n/**\n * 三个校区的作息时间表\n */\nconst CAMPUS_TIME_SLOTS = {\n    \"青岛校区\": [\n        { \"number\": 1,  \"startTime\": \"08:00\", \"endTime\": \"08:45\" },\n        { \"number\": 2,  \"startTime\": \"08:55\", \"endTime\": \"09:40\" },\n        { \"number\": 3,  \"startTime\": \"09:55\", \"endTime\": \"10:40\" },\n        { \"number\": 4,  \"startTime\": \"10:50\", \"endTime\": \"11:35\" },\n        { \"number\": 5,  \"startTime\": \"11:35\", \"endTime\": \"12:00\" },\n        { \"number\": 6,  \"startTime\": \"14:00\", \"endTime\": \"14:45\" },\n        { \"number\": 7,  \"startTime\": \"14:55\", \"endTime\": \"15:40\" },\n        { \"number\": 8,  \"startTime\": \"15:55\", \"endTime\": \"16:40\" },\n        { \"number\": 9,  \"startTime\": \"16:50\", \"endTime\": \"17:35\" },\n        { \"number\": 10, \"startTime\": \"18:50\", \"endTime\": \"19:35\" },\n        { \"number\": 11, \"startTime\": \"19:45\", \"endTime\": \"20:30\" }\n    ],\n    \"平度校区\": [\n        { \"number\": 1,  \"startTime\": \"08:30\", \"endTime\": \"09:15\" },\n        { \"number\": 2,  \"startTime\": \"09:25\", \"endTime\": \"10:10\" },\n        { \"number\": 3,  \"startTime\": \"10:20\", \"endTime\": \"11:05\" },\n        { \"number\": 4,  \"startTime\": \"11:15\", \"endTime\": \"12:00\" },\n        { \"number\": 5,  \"startTime\": \"12:00\", \"endTime\": \"12:25\" },\n        { \"number\": 6,  \"startTime\": \"14:00\", \"endTime\": \"14:45\" },\n        { \"number\": 7,  \"startTime\": \"14:55\", \"endTime\": \"15:40\" },\n        { \"number\": 8,  \"startTime\": \"15:50\", \"endTime\": \"16:35\" },\n        { \"number\": 9,  \"startTime\": \"16:45\", \"endTime\": \"17:30\" },\n        { \"number\": 10, \"startTime\": \"18:50\", \"endTime\": \"19:35\" },\n        { \"number\": 11, \"startTime\": \"19:45\", \"endTime\": \"20:30\" }\n    ],\n    \"蓝谷校区\": [\n        { \"number\": 1,  \"startTime\": \"08:30\", \"endTime\": \"09:15\" },\n        { \"number\": 2,  \"startTime\": \"09:20\", \"endTime\": \"10:05\" },\n        { \"number\": 3,  \"startTime\": \"10:15\", \"endTime\": \"11:00\" },\n        { \"number\": 4,  \"startTime\": \"11:05\", \"endTime\": \"11:50\" },\n        { \"number\": 5,  \"startTime\": \"13:10\", \"endTime\": \"13:55\" },\n        { \"number\": 6,  \"startTime\": \"14:00\", \"endTime\": \"14:45\" },\n        { \"number\": 7,  \"startTime\": \"14:55\", \"endTime\": \"15:40\" },\n        { \"number\": 8,  \"startTime\": \"15:45\", \"endTime\": \"16:30\" },\n        { \"number\": 9,  \"startTime\": \"16:35\", \"endTime\": \"17:20\" },\n        { \"number\": 10, \"startTime\": \"18:30\", \"endTime\": \"19:15\" },\n        { \"number\": 11, \"startTime\": \"19:25\", \"endTime\": \"20:15\" }\n    ]\n};\n\nfunction getCourseConfig() {\n    return {\n        \"defaultClassDuration\": 45,\n        \"defaultBreakDuration\": 5\n    };\n}\n\n// ─────────────────────────────────────────────\n// 主流程\n// ─────────────────────────────────────────────\n\nasync function runImportFlow() {\n    try {\n        window.shiguangBridge.showToast(\"正在获取课表数据，请稍候...\");\n\n        const response = await fetch('/jsxsd/xskb/xskb_list.do', { method: 'GET' });\n        const htmlText = await response.text();\n        const parser = new DOMParser();\n        let doc = parser.parseFromString(htmlText, 'text/html');\n\n        // 解析学期列表\n        const selectElem = doc.getElementById('xnxq01id');\n        let semesters = [];\n        let semesterValues = [];\n        let defaultIndex = 0;\n\n        if (selectElem) {\n            const options = selectElem.querySelectorAll('option');\n            options.forEach((opt, index) => {\n                semesters.push((opt.innerText || opt.textContent).trim());\n                semesterValues.push(opt.value);\n                if (opt.hasAttribute('selected')) {\n                    defaultIndex = index;\n                }\n            });\n        }\n\n        // 选择学期\n        if (semesters.length > 0) {\n            let selectedIdx = await window.shiguangBridgePromise.showSingleSelection(\n                \"请选择要导入的学期\",\n                JSON.stringify(semesters),\n                defaultIndex\n            );\n\n            if (selectedIdx === null) {\n                window.shiguangBridge.showToast(\"已取消导入\");\n                return;\n            }\n\n            if (selectedIdx !== defaultIndex) {\n                window.shiguangBridge.showToast(`正在获取 [${semesters[selectedIdx]}] 课表...`);\n                let formData = new URLSearchParams();\n                formData.append('xnxq01id', semesterValues[selectedIdx]);\n\n                const postResponse = await fetch('/jsxsd/xskb/xskb_list.do', {\n                    method: 'POST',\n                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },\n                    body: formData.toString()\n                });\n                const postHtml = await postResponse.text();\n                doc = parser.parseFromString(postHtml, 'text/html');\n            }\n        }\n\n        // 选择校区\n        const campusNames = Object.keys(CAMPUS_TIME_SLOTS);\n        const campusIdx = await window.shiguangBridgePromise.showSingleSelection(\n            \"请选择您所在的校区\",\n            JSON.stringify(campusNames),\n            0\n        );\n\n        if (campusIdx === null) {\n            window.shiguangBridge.showToast(\"已取消导入\");\n            return;\n        }\n\n        const selectedCampus = campusNames[campusIdx];\n        const timeSlots = CAMPUS_TIME_SLOTS[selectedCampus];\n\n        // 解析课程\n        const courses = extractCoursesFromDoc(doc);\n\n        if (courses.length === 0) {\n            await window.shiguangBridgePromise.showAlert(\n                \"提示\",\n                \"未能解析到任何课程，请检查当前学期是否有排课，或尝试切换学期。\",\n                \"好的\"\n            );\n            return;\n        }\n\n        // 保存\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(getCourseConfig()));\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n\n        const saveResult = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        if (!saveResult) {\n            window.shiguangBridge.showToast(\"课程保存失败，请重试！\");\n            return;\n        }\n\n        window.shiguangBridge.showToast(`成功导入 ${courses.length} 节课程（${selectedCampus}作息）！`);\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入发生异常: \" + error.message);\n    }\n}\n\nrunImportFlow();","QDU_01":"// 青岛大学(xjw.qdu.edu.cn)拾光课程表适配脚本\n// 由本校开发者JellyfisHawthorn适配\n// 出现问题请提联系开发者或者提交pr更改,这更加快速\n\nconst BASE_URL = \"https://xjw.qdu.edu.cn\";\nconst URL_SEMESTER = `${BASE_URL}/jsxsd/jxzl/jxzl_query`;   // 教学周历（学期列表 + 开学日期 + 最大周次）\nconst URL_COURSE = `${BASE_URL}/jsxsd/xskb/xskb_list.do`; // 课表查询\nconst URL_PLAN = `${BASE_URL}/jsxsd/pyfa/pyfa_query`; // 执行计划查询（用于查课程学分）\nconst URL_FXPLAN = `${BASE_URL}/jsxsd/pyfa/fxpyfa_query`; // 辅修执行计划查询\nconst URL_WZYPLAN = `${BASE_URL}/jsxsd/pyfa/wzypyfa_query`; // 微专业执行计划查询\n\n// 工具函数\n\nfunction parseWeeks(weekStr) {\n    const weeks = [];\n    if (!weekStr) return weeks;\n    const pureWeekData = weekStr.split('(')[0];\n    pureWeekData.split(',').forEach(seg => {\n        if (seg.includes('-')) {\n            const [s, e] = seg.split('-').map(Number);\n            if (!isNaN(s) && !isNaN(e)) {\n                for (let i = s; i <= e; i++) weeks.push(i);\n            }\n        } else {\n            const w = parseInt(seg);\n            if (!isNaN(w)) weeks.push(w);\n        }\n    });\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 节次与周次合并去重函数（供开发者参考）\n * @param {Array<Object>} courses 原始解析课程数组\n * @returns {Array<Object>} 合并去重后的课程数组\n */\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    // 1. 深拷贝并规范周次数据，过滤无效项\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n\n    // 阶段 1：合并连续节次与完全重复记录\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n            a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) ||\n            (a.day || 0) - (b.day || 0) ||\n            a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n            (a.startSection || 0) - (b.startSection || 0);\n    });\n\n    const step1Merged = [];\n    let current = list[0];\n\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n\n        const isSameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n\n        if (isSameCourseAndWeeks && isContinuous) {\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    // 阶段 2：合并同节次的周次\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n            a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) ||\n            (a.day || 0) - (b.day || 0) ||\n            (a.startSection || 0) - (b.startSection || 0) ||\n            (a.endSection || 0) - (b.endSection || 0);\n    });\n\n    const step2Merged = [];\n    let cur = step1Merged[0];\n\n    for (let i = 1; i < step1Merged.length; i++) {\n        const nxt = step1Merged[i];\n\n        const isSameCourseAndSection =\n            cur.name === nxt.name &&\n            cur.teacher === nxt.teacher &&\n            cur.position === nxt.position &&\n            cur.day === nxt.day &&\n            cur.startSection === nxt.startSection &&\n            cur.endSection === nxt.endSection;\n\n        if (isSameCourseAndSection) {\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(cur);\n            cur = nxt;\n        }\n    }\n    step2Merged.push(cur);\n\n    return step2Merged;\n}\n\n// 核心解析逻辑\n\nfunction parseTimetableToModel(doc, courseCredits) {\n    // 获取课程学分对象\n\n    const timetable = doc.getElementById('timetable');\n    if (!timetable) return [];\n\n    let rawCourses = [];\n    const rows = Array.from(timetable.querySelectorAll('tr')).filter(r => r.querySelector('td'));\n\n    rows.forEach((row, SectionIndex) => {\n\n        const cells = row.querySelectorAll('td');\n        cells.forEach((cell, dayIndex) => {\n            const day = dayIndex + 1;\n            const detailDivs = cell.querySelectorAll('div.kbcontent');\n\n            detailDivs.forEach(div => {\n                const rawHtml = div.innerHTML.trim();\n                if (!rawHtml || rawHtml === \"&nbsp;\" || div.innerText.trim().length < 2) return;\n\n                const blocks = rawHtml.split(/---------------------|----------------------/);\n\n                blocks.forEach(block => {\n                    if (!block.trim()) return;\n                    const tempDiv = document.createElement('div');\n                    tempDiv.innerHTML = block;\n\n                    let name = \"\";\n                    for (let node of tempDiv.childNodes) {\n                        if (node.nodeType === 1 && node.textContent.trim() !== \"\") {\n                            name = node.textContent.trim();\n                            break;\n                        }\n                    }\n\n                    const teacherRaw = tempDiv.querySelector('font[title=\"老师\"], font[title=\"教师\"]')?.innerText || \"\";\n                    const teacher = teacherRaw.replace(\"任课教师:\", \"\").trim();\n                    const position = tempDiv.querySelector('font[title=\"教室\"]')?.innerText || \"未知地点\";\n                    const weekStr = tempDiv.querySelector('font[title=\"周次(节次)\"]')?.innerText || \"\";\n\n                    let startSection = SectionIndex * 2 + 1;\n                    if (SectionIndex >= 2) startSection += 1;\n                    if (SectionIndex >= 4) startSection += 1;\n\n                    let endSection = 0;\n                    if (SectionIndex === 5) endSection = startSection; else endSection = startSection + 1;\n\n                    if (name) {\n                        rawCourses.push({\n                            \"name\": name,\n                            \"teacher\": teacher || \"未知教师\",\n                            \"weeks\": parseWeeks(weekStr),\n                            \"position\": position,\n                            \"day\": day,\n                            \"startSection\": startSection,\n                            \"endSection\": endSection,\n                            \"credit\": courseCredits[name] || null\n                        });\n                    }\n                });\n            });\n        });\n    });\n\n    return mergeAndDistinctCourses(rawCourses);\n}\n\n// 网络请求封装\n\n/**\n * GET 教学周历页面（用于获取学期列表）\n */\nasync function requestSemesterPage() {\n    const response = await fetch(URL_SEMESTER, {\n        method: \"GET\",\n        credentials: \"include\"\n    });\n    return await response.text();\n}\n\n/**\n * POST 教学周历页面（用于获取指定学期的开学日期与最大周次）\n * @param {string} semesterId 形如 \"2025-2026-2\"\n */\nasync function requestSemesterDetailPage(semesterId) {\n    const response = await fetch(URL_SEMESTER, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n        body: `xnxq01id=${semesterId}`,\n        credentials: \"include\"\n    });\n    return await response.text();\n}\n\n/**\n * POST 课表页面（用于获取课程数据）\n * @param {string} semesterId 形如 \"2025-2026-2\"\n */\nasync function requestCoursePage(semesterId) {\n    const response = await fetch(URL_COURSE, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n        body: `jx0404id=&cj0701id=&zc=&demo=&xnxq01id=${semesterId}`,\n        credentials: \"include\"\n    });\n    return await response.text();\n}\n\n/**\n * GET 执行计划页面（用于获取课程对应的学分）\n */\nasync function requestPlanPage() {\n    const response = await fetch(URL_PLAN, {\n        method: \"GET\",\n        credentials: \"include\"\n    });\n    return await response.text();\n}\n\n/**\n* GET 辅修执行计划页面（用于获取课程对应的学分）\n*/\nasync function requestFxFPlanPage() {\n    const response = await fetch(URL_FXPLAN, {\n        method: \"GET\",\n        credentials: \"include\"\n    });\n    return await response.text();\n}\n\n/**\n* GET 微专业执行计划页面（用于获取课程对应的学分）\n*/\nasync function requestWZYPlanPage() {\n    const response = await fetch(URL_WZYPLAN, {\n        method: \"GET\",\n        credentials: \"include\"\n    });\n    return await response.text();\n}\n\n// 业务逻辑\n\n/**\n * 获取学期列表，以 selected 为原点上下各取 3 个\n * @returns {Promise<{list: Array<{value:string,label:string}>, defaultIndex:number}>}\n */\nasync function fetchSemesterList() {\n    const html = await requestSemesterPage();\n    const doc = new DOMParser().parseFromString(html, \"text/html\");\n    const select = doc.getElementById(\"xnxq01id\");\n    if (!select) return { list: [], defaultIndex: -1 };\n\n    const allOptions = Array.from(select.querySelectorAll(\"option\")).map(opt => ({\n        value: opt.value,\n        label: opt.textContent.trim(),\n        selected: opt.hasAttribute(\"selected\")\n    }));\n\n    let selectedIndex = allOptions.findIndex(o => o.selected);\n    if (selectedIndex === -1) selectedIndex = 0;\n\n    const start = Math.max(0, selectedIndex - 3);\n    const end = Math.min(allOptions.length, selectedIndex + 4);\n\n    const list = allOptions.slice(start, end);\n    const defaultIndex = selectedIndex - start;\n\n    return { list, defaultIndex };\n}\n\n/**\n * 获取指定学期的开学日期 + 最大周次\n * @param {string} semesterId 形如 \"2025-2026-2\"\n * @returns {Promise<{startDate: string|null, totalWeeks: number|null}>}\n */\nasync function fetchSemesterInfo(semesterId) {\n    const html = await requestSemesterDetailPage(semesterId);\n    const doc = new DOMParser().parseFromString(html, \"text/html\");\n    const timetable = doc.getElementById(\"kbtable\");\n    if (!timetable) return { startDate: null, totalWeeks: null };\n\n    const rows = Array.from(timetable.querySelectorAll(\"tr\")).filter(r => r.querySelector(\"td\"));\n    if (rows.length === 0) return { startDate: null, totalWeeks: null };\n\n    const firstDateCell = rows[0].querySelector(\"td[title]\");\n    const title = firstDateCell?.getAttribute(\"title\") || \"\";\n    const match = title.match(/^(\\d{4})年(\\d{2})月(\\d{2})$/);\n    const startDate = match ? `${match[1]}-${match[2]}-${match[3]}` : null;\n\n    // 最大周次：所有行第一个 td 中能解析为整数的最大值\n    let totalWeeks = null;\n    for (const row of rows) {\n        const firstTd = row.querySelector(\"td\");\n        if (!firstTd) continue;\n        const n = parseInt(firstTd.textContent.trim(), 10);\n        if (!isNaN(n) && n > 0) {\n            if (totalWeeks === null || n > totalWeeks) totalWeeks = n;\n        }\n    }\n\n    return { startDate, totalWeeks };\n}\n\n/**\n * 获取并解析指定学期的课程\n * @param {string} semesterId 形如 \"2025-2026-2\"\n * @returns {Promise<Array<Object>>}\n */\nasync function fetchCourses(semesterId) {\n    const courseCredits = await fetchAllCourseCredits();\n    const html = await requestCoursePage(semesterId);\n    return parseTimetableToModel(new DOMParser().parseFromString(html, \"text/html\"), courseCredits);\n}\n\n/**\n * 获取执行计划里所有课程对应的学分\n * 部分限选、任选课的学分信息暂时无法获取\n * @returns {Promise<Object>} 课程名称 -> 学分\n */\nasync function fetchAllCourseCredits() {\n\n    const courseCredits = {}; // 存储所有课程的学分信息\n\n    // 依次获取三个执行计划表的学分信息\n    const requestFns = [\n        requestPlanPage,\n        requestFxFPlanPage,\n        requestWZYPlanPage\n    ];\n\n    for (const requestFn of requestFns) {\n        const html = await requestFn();\n        const doc = new DOMParser().parseFromString(html, \"text/html\");\n        const dataTable = doc.getElementById(\"dataList\");\n\n        const rows = Array.from(dataTable.querySelectorAll('tr')).filter(r => r.querySelector('td'));\n\n        // 如果rows的第一项内容只有“未查询到数据”文本，说明没有数据，跳过后续处理\n        if (rows[0].querySelector('td').textContent.trim() === \"未查询到数据\") {\n            continue;\n        }\n\n        rows.forEach((row) => {\n\n            // 每一行的第四个单元格是课程名称，第六个单元格是学分\n            const courseName = row.querySelector('td:nth-child(4)').textContent.trim();\n            const credit = row.querySelector('td:nth-child(6)').textContent.trim();\n            if (courseName && !(courseName in courseCredits)) {\n                courseCredits[courseName] = parseFloat(credit);\n            }\n        });\n    }\n\n    return courseCredits;\n\n}\n\n/**\n * 获取某课程的学分\n * @param {string} courseName 课程名称 \n * @param {Object} courseCredits 学分信息对象\n * @returns {Promise<number|null>}\n */\nasync function fetchCourseCredit(courseName, courseCredits) {\n    if (courseName in courseCredits) {\n        return courseCredits[courseName];\n    } else {\n        window.shiguangBridge.showToast(`${courseName}的学分信息未找到！`);\n        return null;\n    }\n}\n\n\n\n// 配置保存\n\nasync function saveAppConfig(semesterStartDate, totalWeeks) {\n    const config = {\n        \"semesterTotalWeeks\": totalWeeks || 20,\n        \"firstDayOfWeek\": 1,\n        \"defaultClassDuration\": 50\n    };\n    if (semesterStartDate) {\n        config.semesterStartDate = semesterStartDate;\n    }\n    return await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n}\n\n/**\n * 统一作息\n */\nasync function saveAppTimeSlots(semesterId) {\n    // 基础时间段\n    const baseTimeSlots = [\n        { \"number\": 1, \"startTime\": \"08:00\", \"endTime\": \"08:50\" },\n        { \"number\": 2, \"startTime\": \"09:00\", \"endTime\": \"09:50\" },\n        { \"number\": 3, \"startTime\": \"10:10\", \"endTime\": \"11:00\" },\n        { \"number\": 4, \"startTime\": \"11:10\", \"endTime\": \"12:00\" },\n        { \"number\": 5, \"startTime\": \"13:10\", \"endTime\": \"14:00\" },\n        { \"number\": 6, \"startTime\": \"14:00\", \"endTime\": \"14:50\" },\n        { \"number\": 7, \"startTime\": \"15:00\", \"endTime\": \"15:50\" },\n        { \"number\": 8, \"startTime\": \"16:00\", \"endTime\": \"16:50\" },\n        { \"number\": 9, \"startTime\": \"17:00\", \"endTime\": \"17:50\" },\n        { \"number\": 10, \"startTime\": \"17:50\", \"endTime\": \"18:30\" },\n        { \"number\": 11, \"startTime\": \"19:00\", \"endTime\": \"19:50\" },\n        { \"number\": 12, \"startTime\": \"20:00\", \"endTime\": \"20:50\" },\n        { \"number\": 13, \"startTime\": \"21:00\", \"endTime\": \"21:50\" }\n    ];\n\n    // 创建当前学期的组合作息方案。注：T2时段（第10节）仅供参考（因为我没上过且没找到官方具体时间）\n    // 根据semesterId获取此学期的信息\n    const [startYear, endYear, semester] = semesterId.split(\"-\");\n    let comboSchedule = null;\n    if (semester === \"1\") {\n        // 秋冬学期\n        comboSchedule = {\n            name: `${startYear}秋组合作息方案`,\n            publicSchedules: [\n                {\n                    name: `${startYear}春夏作息`,\n                    startDate: `${startYear}-05-01`,\n                    endDate: `${startYear}-09-30`,\n                    timeSlots: [\n                        { \"number\": 5, \"startTime\": \"13:10\", \"endTime\": \"14:00\" },\n                        { \"number\": 6, \"startTime\": \"14:00\", \"endTime\": \"14:50\" },\n                        { \"number\": 7, \"startTime\": \"15:00\", \"endTime\": \"15:50\" },\n                        { \"number\": 8, \"startTime\": \"16:00\", \"endTime\": \"16:50\" },\n                        { \"number\": 9, \"startTime\": \"17:00\", \"endTime\": \"17:50\" },\n                        { \"number\": 10, \"startTime\": \"17:50\", \"endTime\": \"18:30\" },\n                        { \"number\": 11, \"startTime\": \"19:00\", \"endTime\": \"19:50\" },\n                        { \"number\": 12, \"startTime\": \"20:00\", \"endTime\": \"20:50\" },\n                        { \"number\": 13, \"startTime\": \"21:00\", \"endTime\": \"21:50\" }\n                    ]\n                },\n                {\n                    name: `${startYear}秋冬作息`,\n                    startDate: `${startYear}-10-01`,\n                    endDate: `${endYear}-04-30`,\n                    timeSlots: [\n                        { \"number\": 5, \"startTime\": \"12:40\", \"endTime\": \"13:30\" },\n                        { \"number\": 6, \"startTime\": \"13:30\", \"endTime\": \"14:20\" },\n                        { \"number\": 7, \"startTime\": \"14:30\", \"endTime\": \"15:20\" },\n                        { \"number\": 8, \"startTime\": \"15:30\", \"endTime\": \"16:20\" },\n                        { \"number\": 9, \"startTime\": \"16:30\", \"endTime\": \"17:20\" },\n                        { \"number\": 10, \"startTime\": \"17:20\", \"endTime\": \"18:00\" },\n                        { \"number\": 11, \"startTime\": \"18:30\", \"endTime\": \"19:20\" },\n                        { \"number\": 12, \"startTime\": \"19:30\", \"endTime\": \"20:20\" },\n                        { \"number\": 13, \"startTime\": \"20:30\", \"endTime\": \"21:20\" }\n                    ]\n                }\n            ]\n        };\n    } else if (semester === \"2\") {\n        // 春夏学期\n        comboSchedule = {\n            name: `${endYear}春组合作息方案`,\n            publicSchedules: [\n                {\n                    name: `${startYear}秋冬作息`,\n                    startDate: `${startYear}-10-01`,\n                    endDate: `${endYear}-04-30`,\n                    timeSlots: [\n                        { \"number\": 5, \"startTime\": \"12:40\", \"endTime\": \"13:30\" },\n                        { \"number\": 6, \"startTime\": \"13:30\", \"endTime\": \"14:20\" },\n                        { \"number\": 7, \"startTime\": \"14:30\", \"endTime\": \"15:20\" },\n                        { \"number\": 8, \"startTime\": \"15:30\", \"endTime\": \"16:20\" },\n                        { \"number\": 9, \"startTime\": \"16:30\", \"endTime\": \"17:20\" },\n                        { \"number\": 10, \"startTime\": \"17:20\", \"endTime\": \"18:00\" },\n                        { \"number\": 11, \"startTime\": \"18:30\", \"endTime\": \"19:20\" },\n                        { \"number\": 12, \"startTime\": \"19:30\", \"endTime\": \"20:20\" },\n                        { \"number\": 13, \"startTime\": \"20:30\", \"endTime\": \"21:20\" }\n                    ]\n                },\n                {\n                    name: `${endYear}春夏作息`,\n                    startDate: `${endYear}-05-01`,\n                    endDate: `${endYear}-09-30`,\n                    timeSlots: [\n                        { \"number\": 5, \"startTime\": \"13:10\", \"endTime\": \"14:00\" },\n                        { \"number\": 6, \"startTime\": \"14:00\", \"endTime\": \"14:50\" },\n                        { \"number\": 7, \"startTime\": \"15:00\", \"endTime\": \"15:50\" },\n                        { \"number\": 8, \"startTime\": \"16:00\", \"endTime\": \"16:50\" },\n                        { \"number\": 9, \"startTime\": \"17:00\", \"endTime\": \"17:50\" },\n                        { \"number\": 10, \"startTime\": \"17:50\", \"endTime\": \"18:30\" },\n                        { \"number\": 11, \"startTime\": \"19:00\", \"endTime\": \"19:50\" },\n                        { \"number\": 12, \"startTime\": \"20:00\", \"endTime\": \"20:50\" },\n                        { \"number\": 13, \"startTime\": \"21:00\", \"endTime\": \"21:50\" }\n                    ]\n                }\n            ]\n        };\n    }\n\n    // 保存作息方案\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(baseTimeSlots));\n        await window.shiguangBridgePromise.saveComboSchedule(JSON.stringify(comboSchedule));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"作息方案导入失败: \" + error.message);\n        return false;\n    }\n}\n\n// 流程编排\n\nasync function runImportFlow() {\n    try {\n        // 1. 用户确认\n        const confirmed = await window.shiguangBridgePromise.showAlert(\n            \"提示\", \"请确保已成功登录教务系统。是否开始导入？\", \"开始\"\n        );\n        if (!confirmed) return;\n\n        // 2. 获取学期列表\n        window.shiguangBridge.showToast(\"正在获取学期列表...\");\n        const { list: semesters, defaultIndex } = await fetchSemesterList();\n        if (!semesters || semesters.length === 0) {\n            window.shiguangBridge.showToast(\"未获取到学期列表，请检查登录状态。\");\n            return;\n        }\n\n        // 3. 用户选择学期\n        const labels = semesters.map(s => s.label);\n        const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n            \"选择学期\", JSON.stringify(labels), defaultIndex\n        );\n        if (selectedIndex === null) return;\n        const semesterId = semesters[selectedIndex].value;\n\n        // 4. 获取开学日期\n        window.shiguangBridge.showToast(\"正在获取学期信息...\");\n        const { startDate: semesterStartDate, totalWeeks } = await fetchSemesterInfo(semesterId);\n\n        // 5. 获取课程\n        window.shiguangBridge.showToast(\"正在请求课程数据...\");\n        const finalCourses = await fetchCourses(semesterId);\n        if (finalCourses.length === 0) {\n            window.shiguangBridge.showToast(\"未发现课程，请检查学期选择或登录状态。\");\n            return;\n        }\n\n        // 6. 保存配置（含开学日期 + 最大周次（最大限制为 20））/ 作息 / 课程\n        await saveAppConfig(semesterStartDate, Math.min(totalWeeks, 20));\n        await saveAppTimeSlots(semesterId);\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(finalCourses));\n\n        // 7. 完成\n        window.shiguangBridge.showToast(`成功导入 ${finalCourses.length} 门课程`);\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        window.shiguangBridge.showToast(\"异常: \" + error.message);\n    }\n}\n\n// 启动\nrunImportFlow();","QUT":"// 青岛理工大学 - 正方教务系统 课程表适配脚本\n\n// 教务系统基地址：跟随当前登录页协议（http/https 的会话 cookie 是分开的，必须与登录页一致）\nvar BASE_URL = window.location.origin;\n\n/**\n * 解析周次字符串，处理单双周和周次范围。\n */\nfunction parseWeeks(zcd) {\n    if (!zcd) return [];\n\n    var weekSets = String(zcd).replace(/，/g, ',').split(',');\n    var weeks = [];\n\n    for (var i = 0; i < weekSets.length; i++) {\n        var trimmedSet = weekSets[i].trim();\n\n        var rangeMatch = trimmedSet.match(/(\\d+)\\s*-\\s*(\\d+)\\s*周?/);\n        var singleMatch = trimmedSet.match(/^(\\d+)\\s*周?/);\n\n        var start = 0;\n        var end = 0;\n        var processed = false;\n\n        if (rangeMatch) {\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) {\n            start = end = Number(singleMatch[1]);\n            processed = true;\n        }\n\n        if (processed && start >= 1 && end >= start) {\n            var isSingle = trimmedSet.indexOf('(单)') !== -1;\n            var isDouble = trimmedSet.indexOf('(双)') !== -1;\n\n            for (var w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue;\n                if (isDouble && w % 2 !== 0) continue;\n                weeks.push(w);\n            }\n        }\n    }\n\n    var uniqueWeeks = [];\n    var seen = {};\n    for (var j = 0; j < weeks.length; j++) {\n        if (!seen[weeks[j]]) {\n            seen[weeks[j]] = true;\n            uniqueWeeks.push(weeks[j]);\n        }\n    }\n    uniqueWeeks.sort(function(a, b) { return a - b; });\n    return uniqueWeeks;\n}\n\n/**\n * 清洗课程名称中的特殊字符\n */\nfunction cleanCourseName(name) {\n    return name.replace(/[★○●◇◆]/g, '').trim();\n}\n\nfunction mergeAndDistinctCourses(courses) {\n    var sorted = courses.slice().sort(function(a, b) {\n        return a.name.localeCompare(b.name) ||\n            a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) ||\n            a.day - b.day ||\n            a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n            a.startSection - b.startSection;\n    });\n    var merged = [];\n\n    sorted.forEach(function(course) {\n        var previous = merged[merged.length - 1];\n        var sameCourse = previous && previous.name === course.name &&\n            previous.teacher === course.teacher && previous.position === course.position &&\n            previous.day === course.day && previous.weeks.join(',') === course.weeks.join(',');\n\n        if (sameCourse && previous.endSection + 1 >= course.startSection) {\n            previous.endSection = Math.max(previous.endSection, course.endSection);\n        } else if (sameCourse && previous.startSection === course.startSection && previous.endSection === course.endSection) {\n            return;\n        } else {\n            merged.push(course);\n        }\n    });\n\n    var sameSection = new Map();\n    merged.forEach(function(course) {\n        var key = [course.name, course.teacher, course.position, course.day,\n            course.startSection, course.endSection].join('|');\n        if (sameSection.has(key)) {\n            var existing = sameSection.get(key);\n            existing.weeks = Array.from(new Set(existing.weeks.concat(course.weeks))).sort(function(a, b) { return a - b; });\n        } else {\n            sameSection.set(key, course);\n        }\n    });\n    return Array.from(sameSection.values()).sort(function(a, b) {\n        return a.day - b.day || a.startSection - b.startSection || a.name.localeCompare(b.name);\n    });\n}\n\n/**\n * 解析 API 返回的 JSON 数据。\n */\nfunction parseJsonData(jsonData) {\n    console.log(\"JS: parseJsonData 正在解析 JSON 数据...\");\n\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        console.warn(\"JS: JSON 数据结构错误或缺少 kbList 字段。\");\n        return [];\n    }\n\n    var rawCourseList = jsonData.kbList;\n    var finalCourseList = [];\n\n    for (var dbg = 0; dbg < Math.min(rawCourseList.length, 2); dbg++) {\n        console.log(\"JS: 原始课程字段示例[\" + dbg + \"]: \" + JSON.stringify(rawCourseList[dbg]));\n    }\n\n    for (var i = 0; i < rawCourseList.length; i++) {\n        var rawCourse = rawCourseList[i];\n        if (!rawCourse || typeof rawCourse !== \"object\" || !rawCourse.kcmc ||\n            rawCourse.xqj == null || rawCourse.jcs == null || rawCourse.zcd == null) {\n            continue;\n        }\n\n        var weeksArray = parseWeeks(rawCourse.zcd);\n        if (weeksArray.length === 0) {\n            continue;\n        }\n\n        var sectionMatch = String(rawCourse.jcs).match(/^\\s*(?:第)?(\\d+)\\s*(?:-\\s*(\\d+))?\\s*节?\\s*$/);\n        if (!sectionMatch) {\n            console.warn(\"JS: 跳过无法解析节次的课程：\" + rawCourse.kcmc + \"，节次=\" + rawCourse.jcs);\n            continue;\n        }\n        var startSection = Number(sectionMatch[1]);\n        var endSection = Number(sectionMatch[2] || sectionMatch[1]);\n        var day = Number(rawCourse.xqj);\n\n        if (!Number.isInteger(day) || !Number.isInteger(startSection) || !Number.isInteger(endSection) ||\n            day < 1 || day > 7 || startSection < 1 || endSection < startSection) {\n            continue;\n        }\n\n        finalCourseList.push({\n            name: cleanCourseName(String(rawCourse.kcmc)),\n            teacher: rawCourse.xm == null ? \"\" : String(rawCourse.xm).trim(),\n            position: rawCourse.cdmc == null ? \"\" : String(rawCourse.cdmc).trim(),\n            day: day,\n            startSection: startSection,\n            endSection: endSection,\n            weeks: weeksArray\n        });\n    }\n\n    finalCourseList = mergeAndDistinctCourses(finalCourseList);\n\n    console.log(\"JS: JSON 数据解析完成，共找到 \" + finalCourseList.length + \" 门课程。\");\n    return finalCourseList;\n}\n\n/**\n * 构建课表配置，从课程数据中推断最大周次。\n */\nfunction buildCourseConfig(courses) {\n    var maxWeek = 0;\n    for (var i = 0; i < courses.length; i++) {\n        var course = courses[i];\n        for (var j = 0; j < course.weeks.length; j++) {\n            if (course.weeks[j] > maxWeek) {\n                maxWeek = course.weeks[j];\n            }\n        }\n    }\n    return {\n        semesterStartDate: null,\n        semesterTotalWeeks: maxWeek || 20,\n        firstDayOfWeek: 1\n    };\n}\n\n/**\n * 检查是否在登录页面。\n */\nfunction isLoginPage() {\n    var url = window.location.href;\n    return url.indexOf(\"/jwglxt/xtgl/login_slogin.html\") !== -1;\n}\n\nasync function promptUserToStart() {\n    console.log(\"JS: 流程开始：显示公告。\");\n    return await window.shiguangBridgePromise.showAlert(\n        \"青岛理工大学课表导入\",\n        \"导入前请确保您已在浏览器中成功登录青岛理工大学教务系统。\\n脚本将通过正方教务接口读取课表。\",\n        \"好的，开始导入\"\n    );\n}\n\nfunction parseSelectOptions(selectElement) {\n    if (!selectElement) return { options: [], defaultIndex: 0 };\n    var options = [];\n    var defaultIndex = 0;\n    Array.from(selectElement.querySelectorAll(\"option\")).forEach(function(option) {\n        var value = String(option.value || \"\").trim();\n        if (!value) return;\n        var text = String(option.textContent || \"\").trim() || value;\n        if (option.selected) defaultIndex = options.length;\n        options.push({ value: value, text: text });\n    });\n    return { options: options, defaultIndex: defaultIndex };\n}\n\nfunction parseTermOptions(doc) {\n    var yearData = parseSelectOptions(doc.querySelector(\"#xnm\"));\n    var semesterData = parseSelectOptions(doc.querySelector(\"#xqm\"));\n    if (!yearData.options.length || !semesterData.options.length) {\n        throw new Error(\"课表页面未找到有效的学年或学期选项\");\n    }\n    return { yearData: yearData, semesterData: semesterData };\n}\n\nfunction isOnTimetablePage() {\n    return window.location.pathname.indexOf(\"/jwglxt/kbcx/xskbcx_cxXskbcxIndex.html\") !== -1;\n}\n\nfunction readCurrentTerm() {\n    var yearElement = document.querySelector(\"#xnm\");\n    var semesterElement = document.querySelector(\"#xqm\");\n    var academicYear = yearElement ? String(yearElement.value || \"\").trim() : \"\";\n    var semesterCode = semesterElement ? String(semesterElement.value || \"\").trim() : \"\";\n    if (!academicYear || !semesterCode) {\n        throw new Error(\"当前课表页面未读取到学年学期，请先在教务系统页面选择学年和学期\");\n    }\n    return { academicYear: academicYear, semesterCode: semesterCode };\n}\n\nasync function fetchTermPage() {\n    var url = BASE_URL + \"/jwglxt/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N253508&layout=default\";\n    var response = await fetch(url, { method: \"GET\", credentials: \"include\" });\n    if (!response.ok) throw new Error(\"读取课表页面失败：HTTP \" + response.status);\n    return new DOMParser().parseFromString(await response.text(), \"text/html\");\n}\n\nasync function selectTermFromPage(doc) {\n    var termData = parseTermOptions(doc);\n    var yearIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学年\", JSON.stringify(termData.yearData.options.map(function(item) { return item.text; })), termData.yearData.defaultIndex\n    );\n    if (yearIndex === null || yearIndex === -1 || !termData.yearData.options[yearIndex]) throw new Error(\"已取消或无法识别学年选择\");\n\n    var semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\", JSON.stringify(termData.semesterData.options.map(function(item) { return item.text; })), termData.semesterData.defaultIndex\n    );\n    if (semesterIndex === null || semesterIndex === -1 || !termData.semesterData.options[semesterIndex]) throw new Error(\"已取消或无法识别学期选择\");\n\n    return {\n        academicYear: termData.yearData.options[yearIndex].value,\n        semesterCode: termData.semesterData.options[semesterIndex].value\n    };\n}\n\nasync function resolveTerm() {\n    if (isOnTimetablePage()) return readCurrentTerm();\n    return await selectTermFromPage(await fetchTermPage());\n}\n\nfunction normalizeStartDate(value) {\n    var match = String(value || \"\").match(/(\\d{4})[-\\/.年](\\d{1,2})[-\\/.月](\\d{1,2})/);\n    if (!match) return null;\n    return match[1] + \"-\" + match[2].padStart(2, \"0\") + \"-\" + match[3].padStart(2, \"0\");\n}\n\nfunction findSemesterStartDate(value) {\n    if (value == null) return null;\n    if (typeof value !== \"object\") return normalizeStartDate(value);\n\n    if (Array.isArray(value)) {\n        var firstWeek = value.find(function(item) {\n            return item && (String(item.zs) === \"1\" || String(item.zsmc) === \"1\");\n        }) || value[0];\n        var firstWeekDate = findSemesterStartDate(firstWeek);\n        if (firstWeekDate) return firstWeekDate;\n        for (var i = 0; i < value.length; i++) {\n            var date = findSemesterStartDate(value[i]);\n            if (date) return date;\n        }\n        return null;\n    }\n\n    var fields = [\"zrq\", \"zcrq\", \"rq\", \"ksrq\"];\n    for (var j = 0; j < fields.length; j++) {\n        var fieldDate = normalizeStartDate(value[fields[j]]);\n        if (fieldDate) return fieldDate;\n    }\n    var values = Object.values(value);\n    for (var k = 0; k < values.length; k++) {\n        var nestedDate = findSemesterStartDate(values[k]);\n        if (nestedDate) return nestedDate;\n    }\n    return null;\n}\n\nasync function fetchSemesterStartDate(academicYear, semesterCode) {\n    var url = BASE_URL + \"/jwglxt/kbcx/xskbcxZccx_cxZcByXnxq.html?gnmkdm=N2154\";\n    var requestBody = \"xnm=\" + encodeURIComponent(academicYear) + \"&xqm=\" + encodeURIComponent(semesterCode);\n\n    try {\n        var response = await fetch(url, {\n            method: \"POST\",\n            headers: {\n                \"accept\": \"application/json, text/javascript, */*; q=0.01\",\n                \"content-type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: requestBody,\n            credentials: \"include\"\n        });\n        if (!response.ok) {\n            console.warn(\"JS: 开学日期接口请求失败：HTTP \" + response.status);\n            return null;\n        }\n        var responseText = await response.text();\n        var data;\n        try {\n            data = JSON.parse(responseText);\n        } catch (error) {\n            console.warn(\"JS: 开学日期接口未返回 JSON，可能登录已过期。\", error);\n            return null;\n        }\n        var startDate = findSemesterStartDate(data);\n        if (!startDate) console.warn(\"JS: 校历响应中未找到第 1 周开学日期。\");\n        else console.log(\"JS: 获取到开学日期：\" + startDate);\n        return startDate;\n    } catch (error) {\n        console.warn(\"JS: 获取学期开学日期失败：\", error);\n        return null;\n    }\n}\n\n/**\n * 请求和解析课程数据。\n */\nasync function fetchAndParseCourses(academicYear, semesterCode) {\n    window.shiguangBridge.showToast(\"正在获取课表数据...\");\n\n    var requestBody = \"xnm=\" + encodeURIComponent(academicYear) +\n                      \"&xqm=\" + encodeURIComponent(semesterCode) +\n                      \"&kzlx=ck&xsdm=&kclbdm=&kclxdm=\";\n    var url = BASE_URL + \"/jwglxt/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N253508\";\n\n    console.log(\"JS: 发送请求到 \" + url + \", body: \" + requestBody);\n\n    var requestOptions = {\n        \"headers\": {\n            \"content-type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n            \"X-Requested-With\": \"XMLHttpRequest\",\n        },\n        \"body\": requestBody,\n        \"method\": \"POST\",\n        \"credentials\": \"include\"\n    };\n\n    try {\n        var requests = await Promise.all([fetch(url, requestOptions), fetchSemesterStartDate(academicYear, semesterCode)]);\n        var response = requests[0];\n        var semesterStartDate = requests[1];\n        var jsonText = await response.text();\n        var responseType = response.headers && response.headers.get\n            ? response.headers.get(\"content-type\") || \"未知\"\n            : \"未知\";\n        var responsePreview = jsonText.replace(/\\s+/g, \" \").trim().slice(0, 200) || \"<空响应>\";\n\n        if (!response.ok) {\n            var sessionHint = response.status === 901\n                ? \"；QUT 教务系统通常用 901 表示登录会话无效或已过期，请重新登录后停留在教务系统页面再测试\"\n                : \"\";\n            throw new Error(\n                \"QUT 课表接口请求失败：HTTP \" + response.status +\n                (response.statusText ? \" \" + response.statusText : \"\") +\n                sessionHint +\n                \"；响应类型=\" + responseType +\n                \"；最终地址=\" + (response.url || url) +\n                \"；响应摘要=\" + responsePreview\n            );\n        }\n\n        if (jsonText.indexOf(\"登录\") !== -1 && jsonText.indexOf(\"密码\") !== -1) {\n            throw new Error(\n                \"QUT 课表接口返回了登录页面，当前登录会话已失效。\" +\n                \"请重新登录教务系统后再导入；最终地址=\" + (response.url || url) +\n                \"；响应类型=\" + responseType\n            );\n        }\n\n        var jsonData;\n        try {\n            jsonData = JSON.parse(jsonText);\n        } catch (e) {\n            throw new Error(\n                \"QUT 课表接口未返回有效 JSON：\" + e.message +\n                \"；响应类型=\" + responseType +\n                \"；最终地址=\" + (response.url || url) +\n                \"；响应摘要=\" + responsePreview\n            );\n        }\n\n        var courses = parseJsonData(jsonData);\n\n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"未找到任何课程数据，请检查所选学年学期是否正确或本学期无课。\");\n            return null;\n        }\n\n        console.log(\"JS: 课程数据解析成功，共找到 \" + courses.length + \" 门课程。\");\n\n        var config = buildCourseConfig(courses);\n        config.semesterStartDate = semesterStartDate;\n\n        return { courses: courses, config: config };\n\n    } catch (error) {\n        window.shiguangBridge.showToast(\"请求或解析失败: \" + error.message);\n        console.error('JS: Fetch/Parse Error:', error);\n        return null;\n    }\n}\n\n/**\n * 从正方系统获取该学期真实的节次作息时间。\n */\nasync function fetchAndParseTimeSlots(academicYear, semesterCode) {\n    var baseUrl = BASE_URL + \"/jwglxt/kbcx/xskbcx_cxRjc.html\";\n    var requestBody = \"xnm=\" + encodeURIComponent(academicYear) +\n                      \"&xqm=\" + encodeURIComponent(semesterCode) +\n                      \"&kzlx=ck&xsdm=&kclbdm=&kclxdm=\";\n    var gnmkdms = [\"N2151\", \"N253508\"];\n    var lastError = null;\n\n    for (var i = 0; i < gnmkdms.length; i++) {\n        var url = baseUrl + \"?gnmkdm=\" + gnmkdms[i];\n        try {\n            var response = await fetch(url, {\n                \"headers\": {\n                    \"content-type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                    \"X-Requested-With\": \"XMLHttpRequest\",\n                },\n                \"body\": requestBody,\n                \"method\": \"POST\",\n                \"credentials\": \"include\"\n            });\n            if (!response.ok) {\n                lastError = \"HTTP \" + response.status;\n                console.warn(\"JS: 节次时间接口请求失败(gnmkdm=\" + gnmkdms[i] + \")：HTTP \" + response.status);\n                continue;\n            }\n\n            var responseText = await response.text();\n            var responsePreview = responseText.replace(/\\s+/g, \" \").trim().slice(0, 200) || \"<空响应>\";\n\n            var data;\n            try {\n                data = JSON.parse(responseText);\n            } catch (e) {\n                lastError = \"非 JSON：响应=\" + responsePreview;\n                console.warn(\"JS: 节次时间接口未返回 JSON(gnmkdm=\" + gnmkdms[i] + \")：\", e, \"响应摘要=\" + responsePreview);\n                continue;\n            }\n\n            if (data && !Array.isArray(data) && Array.isArray(data.data)) {\n                data = data.data;\n            }\n            if (!Array.isArray(data)) {\n                lastError = \"格式异常：响应=\" + responsePreview;\n                console.warn(\"JS: 节次时间接口返回格式异常(gnmkdm=\" + gnmkdms[i] + \")：响应摘要=\" + responsePreview);\n                continue;\n            }\n\n            var timeSlots = [];\n            for (var j = 0; j < data.length; j++) {\n                var item = data[j];\n                if (!item || typeof item !== \"object\") continue;\n\n                var number = Number(item.jcdm != null ? item.jcdm : item.jcmc);\n                var startTime = \"\";\n                var endTime = \"\";\n                if (item.qssj != null && item.jssj != null) {\n                    startTime = String(item.qssj).trim();\n                    endTime = String(item.jssj).trim();\n                } else if (item.sksj) {\n                    var sksjParts = String(item.sksj).split(/[~\\-—至到]/);\n                    if (sksjParts.length >= 2) {\n                        startTime = sksjParts[0].trim();\n                        endTime = sksjParts[1].trim();\n                    }\n                }\n                startTime = startTime.slice(0, 5);\n                endTime = endTime.slice(0, 5);\n                if (!(number > 0) || !startTime || !endTime) continue;\n\n                timeSlots.push({ number: number, startTime: startTime, endTime: endTime });\n            }\n\n            timeSlots.sort(function(a, b) { return a.number - b.number; });\n\n            if (timeSlots.length === 0) {\n                lastError = \"无有效数据：响应=\" + responsePreview;\n                console.warn(\"JS: 节次时间接口未返回有效作息时间(gnmkdm=\" + gnmkdms[i] + \")：响应摘要=\" + responsePreview);\n                continue;\n            }\n\n            console.log(\"JS: 获取到真实节次作息 \" + timeSlots.length + \" 条(gnmkdm=\" + gnmkdms[i] + \")，第1节 \" +\n                timeSlots[0].startTime + \"-\" + timeSlots[0].endTime);\n            return timeSlots;\n        } catch (error) {\n            lastError = error.message || String(error);\n            console.warn(\"JS: 获取节次作息时间失败(gnmkdm=\" + gnmkdms[i] + \")：\", error);\n        }\n    }\n\n    console.warn(\"JS: 所有节次时间接口尝试均失败，最后原因：\" + lastError);\n    return null;\n}\n\nasync function saveCourses(parsedCourses) {\n    window.shiguangBridge.showToast(\"正在保存 \" + parsedCourses.length + \" 门课程...\");\n    console.log(\"JS: 尝试保存 \" + parsedCourses.length + \" 门课程...\");\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses));\n        console.log(\"JS: 课程保存成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"课程保存失败: \" + error.message);\n        console.error('JS: Save Courses Error:', error);\n        return false;\n    }\n}\n\n// 青岛理工大学统一作息时间（兜底，接口获取失败时使用）\nvar TimeSlots = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:50\", endTime: \"09:35\" },\n    { number: 3, startTime: \"09:55\", endTime: \"10:40\" },\n    { number: 4, startTime: \"10:45\", endTime: \"11:30\" },\n    { number: 5, startTime: \"11:35\", endTime: \"12:20\" },\n    { number: 6, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 7, startTime: \"14:50\", endTime: \"15:35\" },\n    { number: 8, startTime: \"15:55\", endTime: \"16:40\" },\n    { number: 9, startTime: \"16:45\", endTime: \"17:30\" },\n    { number: 10, startTime: \"19:00\", endTime: \"19:45\" }\n];\n\nasync function importPresetTimeSlots(timeSlots) {\n    console.log(\"JS: 准备导入 \" + timeSlots.length + \" 个预设时间段。\");\n\n    if (timeSlots.length > 0) {\n        window.shiguangBridge.showToast(\"正在导入 \" + timeSlots.length + \" 个预设时间段...\");\n        try {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n            window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n            console.log(\"JS: 预设时间段导入成功。\");\n        } catch (error) {\n            window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n            console.error('JS: Save Time Slots Error:', error);\n        }\n    } else {\n        window.shiguangBridge.showToast(\"警告：时间段为空，未导入时间段信息。\");\n        console.warn(\"JS: 警告：传入时间段为空，未导入时间段信息。\");\n    }\n}\n\nasync function runImportFlow() {\n    try {\n        if (isLoginPage()) {\n            throw new Error(\"当前是登录页面，请先登录青岛理工大学教务系统\");\n        }\n\n        window.shiguangBridge.showToast(\"拾光课程表 - 青岛理工大学适配\");\n\n        var alertConfirmed = await promptUserToStart();\n        if (!alertConfirmed) {\n            window.shiguangBridge.showToast(\"用户取消了导入。\");\n            console.log(\"JS: 用户取消了导入流程。\");\n            return;\n        }\n\n        var term = await resolveTerm();\n        console.log(\"JS: 已选择学年学期: \" + term.academicYear + \", \" + term.semesterCode);\n\n        var result = await fetchAndParseCourses(term.academicYear, term.semesterCode);\n        if (result === null) {\n            console.log(\"JS: 课程获取或解析失败，流程终止。\");\n            return;\n        }\n        var courses = result.courses;\n        var config = result.config;\n\n        var saveResult = await saveCourses(courses);\n        if (!saveResult) {\n            console.log(\"JS: 课程保存失败，流程终止。\");\n            return;\n        }\n\n        var timeSlots = await fetchAndParseTimeSlots(term.academicYear, term.semesterCode);\n        if (timeSlots === null) {\n            timeSlots = TimeSlots;\n            window.shiguangBridge.showToast(\"未获取到学校作息时间，已使用内置统一作息作为兜底。\");\n        }\n\n        if (timeSlots.length > 0) {\n            var firstSlotDuration = Math.round(\n                (timeSlots[0].endTime.slice(0, 2) * 60 + Number(timeSlots[0].endTime.slice(3, 5))) -\n                (timeSlots[0].startTime.slice(0, 2) * 60 + Number(timeSlots[0].startTime.slice(3, 5)))\n            );\n            if (firstSlotDuration >= 20) {\n                config.defaultClassDuration = Math.round(firstSlotDuration / 5) * 5;\n                config.defaultBreakDuration = 10;\n            }\n        }\n\n        try {\n            await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n            window.shiguangBridge.showToast(\"课表配置更新成功！总周数：\" + config.semesterTotalWeeks + \"周。\");\n        } catch (error) {\n            window.shiguangBridge.showToast(\"课表配置保存失败: \" + error.message);\n            console.error('JS: Save Config Error:', error);\n        }\n\n        await importPresetTimeSlots(timeSlots);\n\n        window.shiguangBridge.showToast(\"成功导入 \" + courses.length + \" 门课程！\");\n        console.log(\"JS: 整个导入流程执行完毕并成功。\");\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入失败: \" + error.message);\n        console.error(\"JS: 导入流程失败:\", error);\n    }\n}\n\nrunImportFlow();\n","QDHHC":"// 青岛黄海学院(qdhhc.edu.cn) 拾光课程表适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提issues或者提交pr更改,这更加快速\n\n/**\n * 节次与周次合并去重函数\n * @param {Array<Object>} courses 原始解析课程数组\n * @returns {Array<Object>} 合并去重后的课程数组\n */\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    // 1. 深拷贝并规范周次数据，过滤无效项\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n\n    // 阶段 1：合并连续节次与完全重复记录（前提：名称、教师、地点、星期、周次一致）\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n               (a.startSection || 0) - (b.startSection || 0);\n    });\n\n    const step1Merged = [];\n    let current = list[0];\n\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n\n        const isSameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n\n        if (isSameCourseAndWeeks && isContinuous) {\n            // 节次连续：延长结束节次 (如 1-2 节 + 3-4 节 -> 1-4 节)\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            // 完全重复：跳过\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    // 阶段 2：合并同节次的周次（前提：名称、教师、地点、星期、开始/结束节次一致）\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               (a.startSection || 0) - (b.startSection || 0) ||\n               (a.endSection || 0) - (b.endSection || 0);\n    });\n\n    const step2Merged = [];\n    let cur = step1Merged[0];\n\n    for (let i = 1; i < step1Merged.length; i++) {\n        const nxt = step1Merged[i];\n\n        const isSameCourseAndSection =\n            cur.name === nxt.name &&\n            cur.teacher === nxt.teacher &&\n            cur.position === nxt.position &&\n            cur.day === nxt.day &&\n            cur.startSection === nxt.startSection &&\n            cur.endSection === nxt.endSection;\n\n        if (isSameCourseAndSection) {\n            // 周次合并去重 (如 1-8 周 + 9-16 周 -> 1-16 周)\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(cur);\n            cur = nxt;\n        }\n    }\n    step2Merged.push(cur);\n\n    return step2Merged;\n}\n\n/**\n * 解析周次字符串，处理单双周和周次范围。\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    const weekSets = weekStr.split(',');\n    let weeks = [];\n\n    for (const set of weekSets) {\n        const trimmedSet = set.trim();\n\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周/); // 匹配以数字周结束的\n\n        let start = 0;\n        let end = 0;\n        let processed = false;\n\n        if (rangeMatch) { // 范围, 如 \"1-5周\"\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) { // 单个周, 如 \"6周\"\n            start = end = Number(singleMatch[1]);\n            processed = true;\n        }\n        \n        if (processed) {\n            // 确定单双周\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue; // 单周跳过偶数\n                if (isDouble && w % 2 !== 0) continue; // 双周跳过奇数\n                weeks.push(w);\n            }\n        }\n    }\n\n    // 去重并排序\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 解析 API 返回的 JSON 数据。\n */\nfunction parseJsonData(jsonData) {\n    console.log(\"JS: parseJsonData 正在解析 JSON 数据...\");\n    \n    // 检查JSON结构：新的数据在 kbList 字段中\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        console.warn(\"JS: JSON 数据结构错误或缺少 kbList 字段。\");\n        return []; \n    }\n\n    const rawCourseList = jsonData.kbList;\n    const initialCourseList = [];\n\n    for (const rawCourse of rawCourseList) {\n        // 关键字段检查： kcmc(课名), xm(教师), cdmc(教室), xqj(星期), jcs(节次范围), zcd(周次描述)\n        if (!rawCourse.kcmc || !rawCourse.xm || !rawCourse.cdmc || \n            !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) {\n            continue;\n        }\n\n        const weeksArray = parseWeeks(rawCourse.zcd);\n        \n        // 周次有效性检查\n        if (weeksArray.length === 0) {\n            continue;\n        }\n        \n        // 解析节次范围，例如 \"1-2\"\n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]); \n\n        const day = Number(rawCourse.xqj); // xqj: 星期几 (周一为1, 周日为7)\n        \n        // 数字有效性检查\n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) || day < 1 || day > 7 || startSection > endSection) {\n            // console.warn(`JS: 课程 ${rawCourse.kcmc} 星期或节次数据无效，跳过。`);\n            continue;\n        }\n\n        initialCourseList.push({\n            name: rawCourse.kcmc.trim(),\n            teacher: rawCourse.xm.trim(),\n            position: rawCourse.cdmc.trim(),\n            day: day, \n            startSection: startSection,\n            endSection: endSection, \n            weeks: weeksArray\n        });\n    }\n\n    // 调用合并与去重函数，整理连续节次与单双周周次\n    const finalCourseList = mergeAndDistinctCourses(initialCourseList);\n    \n    console.log(`JS: JSON 数据解析与合并完成，整理后共 ${finalCourseList.length} 门课程。`);\n    return finalCourseList;\n}\n\nfunction validateYearInput(input) {\n    console.log(\"JS: validateYearInput 被调用，输入: \" + input);\n    if (/^[0-9]{4}$/.test(input)) {\n        console.log(\"JS: validateYearInput 验证通过。\");\n        return false;\n    } else {\n        console.log(\"JS: validateYearInput 验证失败。\");\n        return \"请输入四位数字的学年！\";\n    }\n}\n\nasync function promptUserToStart() {\n    console.log(\"JS: 流程开始：显示公告。\");\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function getAcademicYear() {\n    const currentYear = new Date().getFullYear().toString();\n    console.log(\"JS: 提示用户输入学年。\");\n    return await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\",\n        \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\",\n        currentYear,\n        \"validateYearInput\"\n    );\n}\n\nasync function selectSemester() {\n    const semesters = [\"第一学期\", \"第二学期\"];\n    console.log(\"JS: 提示用户选择学期。\");\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesters),\n        0\n    );\n    return semesterIndex;\n}\n\n/**\n * 将选择索引转换为 API 所需的学期码。\n */\nfunction getSemesterCode(semesterIndex) {\n    // semesterIndex 3 (第一学期), 12 (第二学期)\n    return semesterIndex === 0 ? \"3\" : \"12\";\n}\n\nasync function fetchSemesterStartDate(academicYear, semesterCode) {\n    const url = \"http://jwxt.qdhhc.edu.cn/jwglxt/kbcx/xskbcxZccx_cxZcByXnxq.html?gnmkdm=N2154\";\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}`;\n\n    try {\n        const response = await fetch(url, {\n            method: \"POST\",\n            headers: { \n                \"accept\": \"application/json, text/javascript, */*; q=0.01\",\n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: requestBody,\n            credentials: \"include\"\n        });\n\n        if (response.ok) {\n            const json = await response.json();\n            if (Array.isArray(json) && json.length > 0) {\n                const firstWeekObj = json.find(item => String(item.zs) === \"1\" || String(item.zsmc) === \"1\") || json[0];\n                \n                if (firstWeekObj.rq) {\n                    const startDateStr = firstWeekObj.rq.split('/')[0];\n                    if (/^\\d{4}-\\d{2}-\\d{2}$/.test(startDateStr)) {\n                        return startDateStr;\n                    }\n                }\n                if (firstWeekObj.zcrq) {\n                    const match = firstWeekObj.zcrq.match(/(\\d{4}-\\d{2}-\\d{2})/);\n                    if (match) return match[1];\n                }\n            }\n        }\n    } catch (e) {\n        console.error(\"JS: 获取学期开学时间失败:\", e);\n    }\n    return null;\n}\n\nasync function fetchAndParseCourses(academicYear, semesterIndex) {\n    const semesterCode = getSemesterCode(semesterIndex);\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`;\n    \n    const semesterStartDate = await fetchSemesterStartDate(academicYear, semesterCode);\n    console.log(\"JS: 获取到的开学日期为:\", semesterStartDate);\n\n    const targetUrls = [\n        \"http://jwxt.qdhhc.edu.cn/jwglxt/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151\"\n    ];\n\n    for (const url of targetUrls) {\n        try {\n            const response = await fetch(url, {\n                method: \"POST\",\n                headers: { \n                    \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\" \n                },\n                body: requestBody,\n                credentials: \"include\"\n            });\n\n            if (response.ok) {\n                const jsonText = await response.text();\n                const jsonData = JSON.parse(jsonText);\n                if (jsonData && jsonData.kbList) {\n                    const parsedCourses = parseJsonData(jsonData);\n                    if (parsedCourses.length > 0) {\n                        return {\n                            courses: parsedCourses,\n                            config: {\n                                semesterStartDate: semesterStartDate,\n                                semesterTotalWeeks: 20\n                            }\n                        };\n                    }\n                }\n            }\n        } catch (e) {\n            console.error(`JS: 接口请求失败: ${url}`, e);\n        }\n    }\n    window.shiguangBridge.showToast(\"未能获取课表数据，请检查网络环境或登录状态。\");\n    return null;\n}\n\nasync function saveCourses(parsedCourses) {\n    window.shiguangBridge.showToast(`正在保存 ${parsedCourses.length} 门课程...`);\n    console.log(`JS: 尝试保存 ${parsedCourses.length} 门课程...`);\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses, null, 2));\n        console.log(\"JS: 课程保存成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        console.error('JS: Save Courses Error:', error);\n        return false;\n    }\n}\n\nconst TimeSlots = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:50\", endTime: \"09:35\" },\n    { number: 3, startTime: \"10:05\", endTime: \"10:50\" },\n    { number: 4, startTime: \"10:55\", endTime: \"11:40\" },\n    { number: 5, startTime: \"11:45\", endTime: \"12:30\" },\n    { number: 6, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 7, startTime: \"14:50\", endTime: \"15:35\" },\n    { number: 8, startTime: \"16:05\", endTime: \"16:50\" },\n    { number: 9, startTime: \"16:55\", endTime: \"17:40\" },\n    { number: 10, startTime: \"19:10\", endTime: \"19:55\" },\n    { number: 11, startTime: \"20:00\", endTime: \"20:45\" }\n];\n\nasync function importPresetTimeSlots(timeSlots) {\n    console.log(`JS: 准备导入 ${timeSlots.length} 个预设时间段。`);\n\n    if (timeSlots.length > 0) {\n        window.shiguangBridge.showToast(`正在导入 ${timeSlots.length} 个预设时间段...`);\n        try {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n            window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n            console.log(\"JS: 预设时间段导入成功。\");\n        } catch (error) {\n            window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n            console.error('JS: Save Time Slots Error:', error);\n        }\n    } else {\n        window.shiguangBridge.showToast(\"警告：时间段为空，未导入时间段信息。\");\n        console.warn(\"JS: 警告：传入时间段为空，未导入时间段信息。\");\n    }\n}\n\n\nasync function runImportFlow() {\n\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        console.log(\"JS: 用户取消了导入流程。\");\n        return;\n    }\n\n    const academicYear = await getAcademicYear();\n    if (academicYear === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        console.log(\"JS: 获取学年失败/取消，流程终止。\");\n        return;\n    }\n    console.log(`JS: 已选择学年: ${academicYear}`);\n\n\n    const semesterIndex = await selectSemester();\n    if (semesterIndex === null || semesterIndex === -1) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        console.log(\"JS: 选择学期失败/取消，流程终止。\");\n        return;\n    }\n    console.log(`JS: 已选择学期索引: ${semesterIndex}`);\n\n    const result = await fetchAndParseCourses(academicYear, semesterIndex);\n    if (result === null) {\n        console.log(\"JS: 课程获取或解析失败，流程终止。\");\n        return;\n    }\n    const { courses, config } = result;\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        console.log(\"JS: 课程保存失败，流程终止。\");\n        return;\n    }\n    \n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        let configMsg = `课表配置更新成功！`;\n        if (config.semesterStartDate) {\n            configMsg += `开学日期：${config.semesterStartDate}`;\n        }\n        window.shiguangBridge.showToast(configMsg);\n    } catch (error) {\n        window.shiguangBridge.showToast(`课表配置保存失败: ${error.message}`);\n        console.error('JS: Save Config Error:', error);\n    }\n\n\n    await importPresetTimeSlots(TimeSlots);\n\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    console.log(\"JS: 整个导入流程执行完毕并成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();","qingguo_01":"/**\n * 青果教务系统通用适配脚本\n * 采用“倒数 7 列”逻辑，解决星期偏移\n */\n\nfunction parseWeeks(weekStr) {\n    const weeks = [];\n    weekStr.split(',').forEach(part => {\n        if (part.includes('-')) {\n            const [start, end] = part.split('-').map(Number);\n            for (let i = start; i <= end; i++) weeks.push(i);\n        } else {\n            const w = parseInt(part);\n            if (!isNaN(w)) weeks.push(w);\n        }\n    });\n    return weeks;\n}\n\nasync function fetchAndParseCourses() {\n    const rawItems = [];\n    \n    function findTable(win) {\n        const t = Array.from(win.document.querySelectorAll('table')).find(x => x.innerText.includes(\"星期一\") && x.innerText.includes(\"[\"));\n        if (t) return t;\n        for (let i = 0; i < win.frames.length; i++) {\n            try { const st = findTable(win.frames[i]); if (st) return st; } catch (e) {}\n        }\n        return null;\n    }\n\n    const table = findTable(window);\n    if (!table) return null;\n\n    // 原始数据清洗抓取\n    Array.from(table.rows).forEach(row => {\n        const cells = Array.from(row.cells);\n        if (cells.length < 7) return;\n\n        cells.forEach((cell, colIndex) => {\n            const distanceToLast = cells.length - 1 - colIndex;\n            if (distanceToLast > 6) return; \n            const day = 7 - distanceToLast;\n\n            const rawText = cell.innerText.trim();\n            if (!rawText.includes('[')) return;\n\n            // 过滤掉空白行，并清洗每一行的首尾空格\n            const lines = rawText.split('\\n').map(l => l.trim()).filter(l => l);\n            \n            lines.forEach((line, i) => {\n                const match = line.match(/([\\d\\-,]+)\\[(\\d+)-(\\d+)\\]/);\n                if (match) {\n                    let name = \"未知课程\";\n                    if (i >= 2) name = lines[i-2];\n                    else if (i >= 1) name = lines[i-1];\n\n                    let teacher = (i >= 1 && !lines[i-1].includes('[')) ? lines[i-1] : \"未知教师\";\n                    let position = (i < lines.length - 1) ? lines[i+1] : \"未知地点\";\n\n                    rawItems.push({\n                        name: name.replace(/\\s/g, \"\"), // 去除所有空格\n                        teacher: teacher.replace(/\\s/g, \"\"),\n                        position: position.replace(/\\s/g, \"\"),\n                        day: day,\n                        startSection: parseInt(match[2]),\n                        endSection: parseInt(match[3]),\n                        weeks: parseWeeks(match[1])\n                    });\n                }\n            });\n        });\n    });\n\n    // 矩阵合并\n    const groupMap = new Map();\n    rawItems.forEach(item => {\n        const key = `${item.name}|${item.teacher}|${item.position}|${item.day}`;\n        if (!groupMap.has(key)) groupMap.set(key, {});\n        \n        const weekMap = groupMap.get(key);\n        item.weeks.forEach(w => {\n            if (!weekMap[w]) weekMap[w] = new Set();\n            for (let s = item.startSection; s <= item.endSection; s++) {\n                weekMap[w].add(s);\n            }\n        });\n    });\n\n    const finalCourses = [];\n    groupMap.forEach((weekMap, key) => {\n        const [name, teacher, position, day] = key.split('|');\n        \n        // 模式聚合：寻找具有相同“节次跨度”的周次\n        const patternMap = new Map(); \n\n        Object.keys(weekMap).forEach(w => {\n            const week = parseInt(w);\n            const sections = Array.from(weekMap[week]).sort((a, b) => a - b);\n            if (sections.length === 0) return;\n\n            // 重新切分连续节次\n            let start = sections[0];\n            for (let i = 0; i < sections.length; i++) {\n                if (i === sections.length - 1 || sections[i+1] !== sections[i] + 1) {\n                    const pKey = `${start}-${sections[i]}`;\n                    if (!patternMap.has(pKey)) patternMap.set(pKey, []);\n                    patternMap.get(pKey).push(week);\n                    if (i < sections.length - 1) start = sections[i+1];\n                }\n            }\n        });\n\n        patternMap.forEach((weeks, pKey) => {\n            const [sStart, sEnd] = pKey.split('-').map(Number);\n            finalCourses.push({\n                name, teacher, position,\n                day: parseInt(day),\n                startSection: sStart,\n                endSection: sEnd,\n                weeks: weeks.sort((a, b) => a - b)\n            });\n        });\n    });\n\n    return finalCourses;\n}\n\nasync function runImportFlow() {\n    try {\n        window.shiguangBridge.showToast(\"正在合并课表数据...\");\n        const courses = await fetchAndParseCourses();\n        if (!courses || courses.length === 0) {\n            window.shiguangBridge.showToast(\"未找到可导入课程\");\n            return;\n        }\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        window.shiguangBridge.showToast(`成功：已优化合并为 ${courses.length} 个课块`);\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        window.shiguangBridge.showToast(\"解析失败: \" + error.message);\n    }\n}\n\nrunImportFlow();"};
